        $attachedTemplates = $this->readAttachedTemplates(
            $parts,
            $settingsPart['xml'],
            $settingsPart['partName'],
            $settingsRelationshipsPart,
            $settingsRelationships,
            $contentTypes,
        );
        $printerSettings = $this->readPrinterSettings(
            $parts,
            $settingsPart['partName'],
            $settingsPart['exists'],
