    /**
     * @param array<string, string> $parts
     * @return array<string, string>
     */
    private function normalizeParts(array $parts): array
    {
        $normalized = [];
        foreach ($parts as $name => $contents) {
            $partName = $this->normalizePartName((string) $name);
            if ($partName !== '') {
                $normalized[$partName] = $contents;
            }
        }

        return $normalized;
    }

    /**
     * @param array<string, string> $parts
     * @return array{defaults:array<string, string>, overrides:array<string, string>}
     */
    private function readContentTypes(array $parts): array
    {
        if (!isset($parts['[Content_Types].xml'])) {
            return ['defaults' => [], 'overrides' => []];
        }

        try {
            $dom = $this->loadXml($parts['[Content_Types].xml'], '[Content_Types].xml');
        } catch (\RuntimeException) {
            return ['defaults' => [], 'overrides' => []];
        }

        $xpath = $this->xpath($dom);
        $defaults = [];
        $overrides = [];

        foreach ($this->elements($xpath, '/ct:Types/ct:Default') as $node) {
            $extension = strtolower($node->getAttribute('Extension'));
            if ($extension !== '') {
                $defaults[$extension] = $node->getAttribute('ContentType');
            }
        }

        foreach ($this->elements($xpath, '/ct:Types/ct:Override') as $node) {
            $partName = $this->contentTypeOverridePartName($node->getAttribute('PartName'));
            if ($partName !== '') {
                $overrides[$partName] = $node->getAttribute('ContentType');
            }
        }

        return ['defaults' => $defaults, 'overrides' => $overrides];
    }

    private function contentTypeOverridePartName(string $partName): string
    {
        try {
            return $this->normalizePartName(OpcPackagePath::canonicalPartNameFromUri($partName));
        } catch (\InvalidArgumentException) {
            return $this->normalizePartName($partName);
        }
    }

    /**
     * @param array<string, string> $parts
     * @return array<string, array{id:string, type:string, target:string, targetMode:string, resolvedTarget:string}>
     */
    private function readRelationshipsPart(array $parts, string $partName): array
    {
        if (!isset($parts[$partName])) {
            return [];
        }

        $relationships = [];
        foreach ($this->readRelationshipRecordsPart($parts, $partName) as $record) {
            if ($record['id'] === '' || $record['target'] === '') {
                continue;
            }

            $relationships[$record['id']] = [
                'id' => $record['id'],
                'type' => $record['type'],
                'target' => $record['target'],
                'targetMode' => $record['targetMode'],
                'resolvedTarget' => $record['resolvedTarget'],
            ];
        }

        return $relationships;
    }

    /**
     * @param array<string, string> $parts
     * @return list<array{ordinal:int, id:string, type:string, target:string, targetMode:string, resolvedTarget:string}>
     */
    private function readRelationshipRecordsPart(array $parts, string $partName): array
    {
        return $this->readRelationshipRecordsPartDiagnostics($parts, $partName)['records'];
    }

    /**
     * @param array<string, string> $parts
     * @return array{records:list<array{ordinal:int, id:string, type:string, target:string, targetMode:string, resolvedTarget:string}>, exists:bool, validXml:?bool, validRoot:?bool, rootNamespace:?string, rootLocalName:?string, xmlParseError:?string, issues:list<string>}
     */
    private function readRelationshipRecordsPartDiagnostics(array $parts, string $partName): array
    {
        if (!isset($parts[$partName])) {
            return [
                'records' => [],
                'exists' => false,
                'validXml' => null,
                'validRoot' => null,
                'rootNamespace' => null,
                'rootLocalName' => null,
                'xmlParseError' => null,
                'issues' => [],
            ];
        }

        try {
            $dom = $this->loadXml($parts[$partName], $partName);
        } catch (\RuntimeException $error) {
            return [
                'records' => [],
                'exists' => true,
                'validXml' => false,
                'validRoot' => false,
                'rootNamespace' => null,
                'rootLocalName' => null,
                'xmlParseError' => $error->getMessage(),
                'issues' => ['invalid-xml'],
            ];
        }

        $root = $dom->documentElement;
        $rootNamespace = $root instanceof \DOMElement ? $root->namespaceURI : null;
        $rootLocalName = $root instanceof \DOMElement ? $root->localName : null;
        $validRoot = $rootNamespace === self::NS_REL && $rootLocalName === 'Relationships';
        $issues = $validRoot ? [] : ['unexpected-root'];

        $xpath = $this->xpath($dom);
        $records = [];
        $ordinal = 0;
        foreach ($this->elements($xpath, '/rel:Relationships/rel:Relationship') as $node) {
            $recordOrdinal = $ordinal++;
            $id = $node->getAttribute('Id');
            $targetMode = $node->getAttribute('TargetMode');
            $target = $node->getAttribute('Target');
            $records[] = [
                'ordinal' => $recordOrdinal,
                'id' => $id,
                'type' => $node->getAttribute('Type'),
                'target' => $target,
                'targetMode' => $targetMode,
                'resolvedTarget' => $target === '' ? '' : $this->resolveRelationshipTarget($partName, $target, $targetMode),
            ];
        }

        return [
            'records' => $records,
            'exists' => true,
            'validXml' => true,
            'validRoot' => $validRoot,
            'rootNamespace' => $rootNamespace,
            'rootLocalName' => $rootLocalName,
            'xmlParseError' => null,
            'issues' => $issues,
        ];
    }

    /**
     * @param array<string, array{id:string, type:string, target:string, targetMode:string, resolvedTarget:string}> $relationships
     */
    private function officeDocumentPart(array $relationships): string
    {
        foreach ($relationships as $relationship) {
            if ($relationship['type'] === self::OFFICE_DOCUMENT_REL && !$this->isExternalRelationshipTarget($relationship)) {
                return $this->stripQueryAndFragment($relationship['resolvedTarget']);
            }
        }

        return 'word/document.xml';
    }

    /**
     * @param array<string, array{id:string, type:string, target:string, targetMode:string, resolvedTarget:string}> $relationships
     * @return array{id:string, type:string, target:string, targetMode:string, resolvedTarget:string}|null
     */
    private function firstRelationshipByType(array $relationships, string $relationshipType): ?array
    {
        foreach ($relationships as $relationship) {
            if ($relationship['type'] === $relationshipType && $relationship['targetMode'] !== 'External') {
                return $relationship;
            }
        }

        return null;
    }

    /**
     * @return array<string, array{id:string, type:string, name:string, headingLevel:int|null, basedOn:?string, next:?string, link:?string, numStyleLink:?string, styleLink:?string, referenceCount:int, missingReferenceCount:int, references:list<array{kind:string, targetStyleId:string, exists:bool}>, missingReferences:list<array{kind:string, targetStyleId:string}>}>
     */
    private function readStyles(string $xml, string $partName): array
    {
        if ($xml === '') {
            return [];
        }

        $dom = $this->loadXml($xml, $partName);
        $xpath = $this->xpath($dom);
        $declaredStyleIds = [];
        foreach ($this->elements($xpath, '/w:styles/w:style[@w:styleId]') as $style) {
            $styleId = trim($style->getAttributeNS(self::NS_W, 'styleId'));
            if ($styleId !== '') {
                $declaredStyleIds[$styleId] = true;
            }
        }

        $referenceKinds = ['basedOn', 'next', 'link', 'numStyleLink', 'styleLink'];
        $styles = [];
        foreach ($this->elements($xpath, '/w:styles/w:style[@w:type="paragraph"]') as $style) {
            $styleId = trim($style->getAttributeNS(self::NS_W, 'styleId'));
            if ($styleId === '') {
                continue;
            }

            $name = $this->childAttr($style, 'name', 'val');
            $outline = $this->childElement($this->childElement($style, 'pPr'), 'outlineLvl');
            $headingLevel = null;
            if ($outline instanceof \DOMElement && is_numeric($outline->getAttributeNS(self::NS_W, 'val'))) {
                $headingLevel = min(6, max(1, ((int) $outline->getAttributeNS(self::NS_W, 'val')) + 1));
            } elseif (preg_match('/(?:^|[^a-z])heading\s*([1-6])(?:$|[^0-9])/i', $name, $match) === 1) {
                $headingLevel = (int) $match[1];
            } elseif (preg_match('/^Heading([1-6])$/', $styleId, $match) === 1) {
                $headingLevel = (int) $match[1];
            }

            $referenceValues = [];
            $references = [];
            $missingReferences = [];
            foreach ($referenceKinds as $kind) {
                $targetStyleId = trim($this->childAttr($style, $kind, 'val'));
                $referenceValues[$kind] = $targetStyleId === '' ? null : $targetStyleId;
                if ($targetStyleId === '') {
                    continue;
                }

                $exists = isset($declaredStyleIds[$targetStyleId]);
                $references[] = [
                    'kind' => $kind,
                    'targetStyleId' => $targetStyleId,
                    'exists' => $exists,
                ];
                if (!$exists) {
                    $missingReferences[] = [
                        'kind' => $kind,
                        'targetStyleId' => $targetStyleId,
                    ];
                }
            }

            $styles[$styleId] = [
                'id' => $styleId,
                'type' => 'paragraph',
                'name' => $name,
                'headingLevel' => $headingLevel,
                'basedOn' => $referenceValues['basedOn'],
                'next' => $referenceValues['next'],
                'link' => $referenceValues['link'],
                'numStyleLink' => $referenceValues['numStyleLink'],
                'styleLink' => $referenceValues['styleLink'],
                'referenceCount' => count($references),
                'missingReferenceCount' => count($missingReferences),
                'references' => $references,
                'missingReferences' => $missingReferences,
            ];
        }

        return $styles;
    }

    /**
     * @param array<string, array<string, mixed>> $styles
     * @return array<string, mixed>
     */
    private function styleReferenceSummary(array $styles, string $partName): array
    {
        $kindCounts = [
            'basedOn' => 0,
            'next' => 0,
            'link' => 0,
            'numStyleLink' => 0,
            'styleLink' => 0,
        ];
        $missingByKind = [
            'basedOn' => 0,
            'next' => 0,
            'link' => 0,
            'numStyleLink' => 0,
            'styleLink' => 0,
        ];
        $referencedStyleIds = [];
        $targetStyleIds = [];
        $missingTargetStyleIds = [];
        $stylesWithMissingReferences = [];
        $referenceCount = 0;
        $missingReferenceCount = 0;

        foreach ($styles as $styleId => $style) {
            $references = $style['references'] ?? [];
            if (!is_array($references) || $references === []) {
                continue;
            }

            $referencedStyleIds[] = (string) $styleId;
            foreach ($references as $reference) {
                if (!is_array($reference)) {
                    continue;
                }

                $kind = (string) ($reference['kind'] ?? '');
                $targetStyleId = (string) ($reference['targetStyleId'] ?? '');
                if ($kind === '' || $targetStyleId === '') {
                    continue;
                }

                if (!array_key_exists($kind, $kindCounts)) {
                    $kindCounts[$kind] = 0;
                    $missingByKind[$kind] = 0;
                }
                ++$referenceCount;
                ++$kindCounts[$kind];
                $targetStyleIds[$targetStyleId] = true;
                if (($reference['exists'] ?? false) === true) {
                    continue;
                }

                ++$missingReferenceCount;
                ++$missingByKind[$kind];
                $missingTargetStyleIds[$targetStyleId] = true;
                $stylesWithMissingReferences[(string) $styleId] = true;
            }
        }

        return [
            'partName' => $partName,
            'styleCount' => count($styles),
            'referencedStyleCount' => count($referencedStyleIds),
            'referencedStyleIds' => $referencedStyleIds,
            'targetStyleCount' => count($targetStyleIds),
            'targetStyleIds' => array_keys($targetStyleIds),
            'referenceCount' => $referenceCount,
            'kindCounts' => $kindCounts,
            'missingReferenceCount' => $missingReferenceCount,
            'missingByKind' => $missingByKind,
            'missingTargetStyleCount' => count($missingTargetStyleIds),
            'missingTargetStyleIds' => array_keys($missingTargetStyleIds),
            'stylesWithMissingReferences' => array_keys($stylesWithMissingReferences),
        ];
    }

    /**
     * @return array<string, mixed>
     */
    private function readLatentStyles(string $xml, string $partName): array
    {
        if ($xml === '') {
            return [];
        }

        $dom = $this->loadXml($xml, $partName);
        $xpath = $this->xpath($dom);
        $latentStyles = $this->firstElement($xpath, '/w:styles/w:latentStyles', $dom);
        if (!$latentStyles instanceof \DOMElement) {
            return [];
        }

        $items = [];
        $byName = [];
        $quickFormatNames = [];
        $semiHiddenNames = [];
        $unhideWhenUsedNames = [];
        $lockedNames = [];

        foreach ($this->elements($xpath, 'w:lsdException', $latentStyles) as $exception) {
            $name = trim($exception->getAttributeNS(self::NS_W, 'name'));
            if ($name === '') {
                continue;
            }

            $item = [
                'name' => $name,
                'quickFormat' => $this->wordOptionalBooleanAttr($exception, 'qFormat'),
                'uiPriority' => $this->wordOptionalIntAttr($exception, 'uiPriority'),
                'semiHidden' => $this->wordOptionalBooleanAttr($exception, 'semiHidden'),
                'unhideWhenUsed' => $this->wordOptionalBooleanAttr($exception, 'unhideWhenUsed'),
                'locked' => $this->wordOptionalBooleanAttr($exception, 'locked'),
            ];

            if ($item['quickFormat'] === true) {
                $quickFormatNames[] = $name;
            }
            if ($item['semiHidden'] === true) {
                $semiHiddenNames[] = $name;
            }
            if ($item['unhideWhenUsed'] === true) {
                $unhideWhenUsedNames[] = $name;
            }
            if ($item['locked'] === true) {
                $lockedNames[] = $name;
            }

            $items[] = $item;
            $byName[$name] = $item;
        }

        return [
            'present' => true,
            'partName' => $partName,
            'declaredCount' => $this->wordOptionalIntAttr($latentStyles, 'count'),
            'defaultLocked' => $this->wordOptionalBooleanAttr($latentStyles, 'defLockedState'),
            'defaultUiPriority' => $this->wordOptionalIntAttr($latentStyles, 'defUIPriority'),
            'defaultSemiHidden' => $this->wordOptionalBooleanAttr($latentStyles, 'defSemiHidden'),
            'defaultUnhideWhenUsed' => $this->wordOptionalBooleanAttr($latentStyles, 'defUnhideWhenUsed'),
            'defaultQuickFormat' => $this->wordOptionalBooleanAttr($latentStyles, 'defQFormat'),
            'exceptionCount' => count($items),
            'quickFormatCount' => count($quickFormatNames),
            'semiHiddenCount' => count($semiHiddenNames),
            'unhideWhenUsedCount' => count($unhideWhenUsedNames),
            'lockedCount' => count($lockedNames),
            'quickFormatNames' => $quickFormatNames,
            'semiHiddenNames' => $semiHiddenNames,
            'unhideWhenUsedNames' => $unhideWhenUsedNames,
            'lockedNames' => $lockedNames,
            'exceptions' => $items,
            'byName' => $byName,
        ];
    }

    /**
     * @param array<string, string> $parts
     * @param array<string, array{id:string, type:string, target:string, targetMode:string, resolvedTarget:string}> $relationships
     * @return array{partName:string, xml:string, relationship:array{id:string, type:string, target:string, targetMode:string, resolvedTarget:string}|null, exists:bool}
     */
    private function corePropertiesPart(array $parts, array $relationships): array
    {
        foreach ($relationships as $relationship) {
            if ($relationship['type'] !== self::CORE_PROPERTIES_REL || $relationship['targetMode'] === 'External') {
                continue;
            }

            $partName = $this->stripQueryAndFragment($relationship['resolvedTarget']);

            return [
                'partName' => $partName,
                'xml' => $parts[$partName] ?? '',
                'relationship' => $relationship,
                'exists' => isset($parts[$partName]),
            ];
        }

        $partName = 'docProps/core.xml';

        return [
            'partName' => $partName,
            'xml' => $parts[$partName] ?? '',
            'relationship' => null,
            'exists' => isset($parts[$partName]),
        ];
    }

    /**
     * @param array<string, string> $parts
     * @param array<string, array{id:string, type:string, target:string, targetMode:string, resolvedTarget:string}> $relationships
     * @return array{partName:string, xml:string, relationship:array{id:string, type:string, target:string, targetMode:string, resolvedTarget:string}|null, exists:bool}
     */
    private function rootRelatedPart(array $parts, array $relationships, string $relationshipType, string $fallbackPart): array
    {
        foreach ($relationships as $relationship) {
            if ($relationship['type'] !== $relationshipType || $relationship['targetMode'] === 'External') {
                continue;
            }

            $partName = $this->stripQueryAndFragment($relationship['resolvedTarget']);

            return [
                'partName' => $partName,
                'xml' => $parts[$partName] ?? '',
                'relationship' => $relationship,
                'exists' => isset($parts[$partName]),
            ];
        }

        $partName = $this->normalizePartName($fallbackPart);

        return [
            'partName' => $partName,
            'xml' => $parts[$partName] ?? '',
            'relationship' => null,
            'exists' => isset($parts[$partName]),
        ];
    }

    /**
     * @param array<string, string> $parts
     * @param array<string, array{id:string, type:string, target:string, targetMode:string, resolvedTarget:string}> $relationships
     * @return array{partName:string, xml:string, relationship:array{id:string, type:string, target:string, targetMode:string, resolvedTarget:string}|null, exists:bool}
     */
    private function stylesPart(array $parts, array $relationships, string $documentPart): array
    {
