    /**
     * @param array<string, string> $parts
     * @param array{partName:string, xml:string, relationship:array{id:string, type:string, target:string, targetMode:string, resolvedTarget:string}|null, exists:bool} $numberingPart
     * @param string $documentPart
     * @param string $documentRelationshipsPart
     * @param array<string, array{id:string, type:string, target:string, targetMode:string, resolvedTarget:string}> $documentRelationships
     * @param array{defaults:array<string, string>, overrides:array<string, string>} $contentTypes
     * @return array<string, mixed>
     */
    private function numberingRelationshipReview(
        array $parts,
        array $numberingPart,
        string $documentPart,
        string $documentRelationshipsPart,
        array $documentRelationships,
        array $contentTypes
    ): array {
        $selectedRelationship = $numberingPart['relationship'];
        $selectedRelationshipId = is_array($selectedRelationship) ? (string) $selectedRelationship['id'] : null;
        $partName = $numberingPart['partName'];
        $partContentType = $this->contentTypeResolutionForPart($partName, $contentTypes);

        $relationships = [];
        $byRelationshipId = [];
        $byRelationshipKey = [];
        $relationshipIds = [];
        $targetParts = [];
        $externalTargets = [];
        $contentTypesSeen = [];
        $issueCodes = [];
        $relationshipCount = 0;
        $internalRelationshipCount = 0;
        $externalRelationshipCount = 0;
        $selectedRelationshipCount = 0;
        $existingTargetCount = 0;
        $missingTargetCount = 0;
        $missingContentTypeCount = 0;
        $unexpectedContentTypeCount = 0;
        $issueCount = 0;

        foreach ($documentRelationships as $relationship) {
            if ($relationship['type'] !== self::NUMBERING_REL) {
                continue;
            }

            $index = $relationshipCount++;
            $relationshipKey = $documentRelationshipsPart . '#' . $relationship['id'];
            $summary = $this->relationshipInventorySummary(
                $parts,
                $relationship,
                $documentPart,
                $documentRelationshipsPart,
                $contentTypes,
            );
            $external = (bool) $summary['external'];
            if ($external) {
                ++$externalRelationshipCount;
                $this->appendUniqueString($externalTargets, $relationship['target']);
            } else {
                ++$internalRelationshipCount;
            }

            $targetPart = is_string($summary['targetPart'] ?? null) ? $summary['targetPart'] : null;
            if ($targetPart !== null) {
                $this->appendUniqueString($targetParts, $targetPart);
            }
            $this->appendUniqueString($contentTypesSeen, is_string($summary['contentType'] ?? null) ? $summary['contentType'] : null);
            $relationshipIds[] = $relationship['id'];
            $selected = $selectedRelationshipId !== null && $relationship['id'] === $selectedRelationshipId;
            if ($selected) {
                ++$selectedRelationshipCount;
            }

            $exists = (bool) $summary['exists'];
            if (!$external && $exists) {
                ++$existingTargetCount;
            }

            $issues = [];
            if ($external) {
                $issues[] = 'external-numbering-relationship';
            } elseif (!$exists) {
                ++$missingTargetCount;
                $issues[] = 'missing-numbering-part';
            }

            $contentTypeBase = is_string($summary['contentTypeBase'] ?? null) ? $summary['contentTypeBase'] : '';
            if (!$external && $contentTypeBase === '') {
                ++$missingContentTypeCount;
                $issues[] = 'missing-numbering-content-type';
            } elseif (!$external && $contentTypeBase !== self::CT_WORD_NUMBERING) {
                ++$unexpectedContentTypeCount;
                $issues[] = 'unexpected-numbering-content-type';
            }

            $byteLength = null;
            $crc32 = null;
            $sha256 = null;
            if (!$external && $targetPart !== null && isset($parts[$targetPart])) {
                $targetBytes = $parts[$targetPart];
                $byteLength = strlen($targetBytes);
                $crc32 = sprintf('%08x', crc32($targetBytes));
                $sha256 = hash('sha256', $targetBytes);
            }

            foreach ($issues as $issue) {
                $issueCodes[$issue] = true;
            }
            if ($issues !== []) {
                ++$issueCount;
            }

            $item = [
                'index' => $index,
                'relationshipKey' => $relationshipKey,
                'id' => $relationship['id'],
                'type' => $relationship['type'],
                'sourcePart' => $summary['sourcePart'],
                'relationshipsPart' => $summary['relationshipsPart'],
                'target' => $summary['target'],
                'targetMode' => $summary['targetMode'],
                'external' => $external,
                'resolvedTarget' => $summary['resolvedTarget'],
                'targetPart' => $targetPart,
                'targetQuery' => $summary['targetQuery'],
                'targetFragment' => $summary['targetFragment'],
                'targetReferenceSuffix' => $summary['targetReferenceSuffix'],
                'targetParentTraversalCount' => $summary['targetParentTraversalCount'],
                'targetHasParentTraversal' => $summary['targetHasParentTraversal'],
                'targetStartsAtPackageRoot' => $summary['targetStartsAtPackageRoot'],
                'sameSourcePart' => $summary['sameSourcePart'],
                'externalTargetKind' => $summary['externalTargetKind'],
                'externalTargetScheme' => $summary['externalTargetScheme'],
                'externalTargetAllowed' => $summary['externalTargetAllowed'],
                'externalTargetIssues' => $summary['externalTargetIssues'],
                'exists' => $exists,
                'byteLength' => $byteLength,
                'crc32' => $crc32,
                'sha256' => $sha256,
                'contentType' => $summary['contentType'],
                'contentTypeBase' => $contentTypeBase,
                'contentTypeHasParameters' => $summary['contentTypeHasParameters'],
                'contentTypeParameterCount' => $summary['contentTypeParameterCount'],
                'contentTypeParameters' => $summary['contentTypeParameters'],
                'contentTypeParameterMap' => $summary['contentTypeParameterMap'],
                'contentTypeSource' => $summary['contentTypeSource'],
                'defaultExtension' => $summary['defaultExtension'],
                'overridePartName' => $summary['overridePartName'],
                'expectedContentType' => self::CT_WORD_NUMBERING,
                'selected' => $selected,
                'valid' => $issues === [],
                'issues' => $issues,
                'byteExposurePolicy' => 'numbering-relationship-bytes-blocked',
                'reviewPolicy' => 'numbering-relationship-metadata-only',
            ];
            $relationships[] = $item;
            $byRelationshipId[$relationship['id']] = $item;
            $byRelationshipKey[$relationshipKey] = $item;
        }

        ksort($issueCodes, SORT_STRING);
        sort($targetParts, SORT_STRING);
        sort($externalTargets, SORT_STRING);
        sort($contentTypesSeen, SORT_STRING);

        return [
            'partName' => $partName,
            'exists' => (bool) $numberingPart['exists'],
            'bytes' => isset($parts[$partName]) ? strlen($parts[$partName]) : 0,
            'crc32' => isset($parts[$partName]) ? sprintf('%08x', crc32($parts[$partName])) : null,
            'sha256' => isset($parts[$partName]) ? hash('sha256', $parts[$partName]) : null,
            'contentType' => $partContentType['contentType'],
            'contentTypeBase' => $partContentType['contentTypeBase'],
            'contentTypeHasParameters' => $partContentType['contentTypeHasParameters'],
            'contentTypeParameterCount' => $partContentType['contentTypeParameterCount'],
            'contentTypeParameters' => $partContentType['contentTypeParameters'],
            'contentTypeParameterMap' => $partContentType['contentTypeParameterMap'],
            'contentTypeSource' => $partContentType['contentTypeSource'],
            'defaultExtension' => $partContentType['defaultExtension'],
            'overridePartName' => $partContentType['overridePartName'],
            'expectedContentType' => self::CT_WORD_NUMBERING,
            'relationshipPresent' => $selectedRelationshipId !== null,
            'fallbackUsed' => $selectedRelationshipId === null,
            'selectedRelationshipId' => $selectedRelationshipId,
            'selectedRelationshipKey' => $selectedRelationshipId === null ? null : $documentRelationshipsPart . '#' . $selectedRelationshipId,
            'relationshipCount' => $relationshipCount,
            'internalRelationshipCount' => $internalRelationshipCount,
            'externalRelationshipCount' => $externalRelationshipCount,
            'selectedRelationshipCount' => $selectedRelationshipCount,
            'existingTargetCount' => $existingTargetCount,
            'missingTargetCount' => $missingTargetCount,
            'missingContentTypeCount' => $missingContentTypeCount,
            'unexpectedContentTypeCount' => $unexpectedContentTypeCount,
            'issueCount' => $issueCount,
            'relationshipIds' => $relationshipIds,
            'targetParts' => $targetParts,
            'externalTargets' => $externalTargets,
            'contentTypes' => $contentTypesSeen,
            'issueCodes' => array_keys($issueCodes),
            'relationships' => $relationships,
            'byRelationshipId' => $byRelationshipId,
            'byRelationshipKey' => $byRelationshipKey,
            'byteExposurePolicy' => 'numbering-relationship-bytes-blocked',
            'reviewPolicy' => 'numbering-relationship-metadata-only',
        ];
    }

    /**
     * @param array<string, string> $parts
     * @param array<string, array{id:string, type:string, target:string, targetMode:string, resolvedTarget:string}> $relationships
     * @return array{partName:string, xml:string, relationship:array{id:string, type:string, target:string, targetMode:string, resolvedTarget:string}|null, exists:bool}
     */
    private function relatedDocumentPart(
        array $parts,
        array $relationships,
        string $documentPart,
        string $relationshipType,
        string $fallbackFileName
    ): array {
        foreach ($relationships as $relationship) {
            if ($relationship['type'] !== $relationshipType || $relationship['targetMode'] === 'External') {
                continue;
            }

            $partName = $this->stripQueryAndFragment($relationship['resolvedTarget']);

            return [
                'partName' => $partName,
                'xml' => $parts[$partName] ?? '',
                'relationship' => $relationship,
                'exists' => isset($parts[$partName]),
            ];
        }

        $partName = $this->documentSiblingPart($documentPart, $fallbackFileName);

        return [
            'partName' => $partName,
            'xml' => $parts[$partName] ?? '',
            'relationship' => null,
            'exists' => isset($parts[$partName]),
        ];
    }

    /**
     * @return array<string, mixed>
     */
    private function readSectionProperties(string $xml, string $partName): array
    {
        if ($xml === '') {
            return [
                'count' => 0,
                'types' => [],
                'orientations' => [],
                'headerReferenceCount' => 0,
                'footerReferenceCount' => 0,
                'landscapeCount' => 0,
                'titlePageCount' => 0,
                'columnLayoutCount' => 0,
                'pageSizeCount' => 0,
                'pageMarginCount' => 0,
                'issueCount' => 0,
                'issueCodes' => [],
                'items' => [],
            ];
        }

        $dom = $this->loadXml($xml, $partName);
        $xpath = $this->xpath($dom);
        $items = [];
        $types = [];
        $orientations = [];
        $issueCodes = [];
        $headerReferenceCount = 0;
        $footerReferenceCount = 0;
        $landscapeCount = 0;
        $titlePageCount = 0;
        $columnLayoutCount = 0;
        $pageSizeCount = 0;
        $pageMarginCount = 0;
        $issueCount = 0;

        foreach ($this->elements($xpath, '//w:sectPr') as $section) {
            $item = $this->sectionPropertyItem($section, $xpath, $partName, count($items));
            $items[] = $item;

            $this->appendUniqueString($types, is_string($item['type'] ?? null) ? $item['type'] : null);
            $orientation = is_array($item['pageSize'] ?? null) ? ($item['pageSize']['orientation'] ?? null) : null;
            $this->appendUniqueString($orientations, is_string($orientation) ? $orientation : null);
            $headerReferenceCount += (int) ($item['headerReferenceCount'] ?? 0);
            $footerReferenceCount += (int) ($item['footerReferenceCount'] ?? 0);
            if (($item['landscape'] ?? false) === true) {
                ++$landscapeCount;
            }
            if (($item['titlePage'] ?? false) === true) {
                ++$titlePageCount;
            }
            if (($item['columns']['present'] ?? false) === true) {
                ++$columnLayoutCount;
            }
            if (($item['pageSize']['present'] ?? false) === true) {
                ++$pageSizeCount;
            }
            if (($item['pageMargins']['present'] ?? false) === true) {
                ++$pageMarginCount;
            }
            foreach (($item['issues'] ?? []) as $issue) {
                if (is_string($issue) && $issue !== '') {
                    $issueCodes[$issue] = true;
                    ++$issueCount;
                }
            }
        }

        sort($types, SORT_STRING);
        sort($orientations, SORT_STRING);
        ksort($issueCodes, SORT_STRING);

        return [
            'count' => count($items),
            'types' => $types,
            'orientations' => $orientations,
            'headerReferenceCount' => $headerReferenceCount,
            'footerReferenceCount' => $footerReferenceCount,
            'landscapeCount' => $landscapeCount,
            'titlePageCount' => $titlePageCount,
            'columnLayoutCount' => $columnLayoutCount,
            'pageSizeCount' => $pageSizeCount,
            'pageMarginCount' => $pageMarginCount,
            'issueCount' => $issueCount,
            'issueCodes' => array_keys($issueCodes),
            'items' => $items,
        ];
    }

    /**
     * @return array<string, mixed>
     */
    private function sectionPropertyItem(\DOMElement $section, \DOMXPath $xpath, string $partName, int $index): array
    {
        $headerReferences = $this->sectionReferenceItems($section, $xpath, 'header');
        $footerReferences = $this->sectionReferenceItems($section, $xpath, 'footer');
        $pageSize = $this->sectionPageSize($this->firstElement($xpath, 'w:pgSz', $section));
        $pageMargins = $this->sectionPageMargins($this->firstElement($xpath, 'w:pgMar', $section));
        $columns = $this->sectionColumns($this->firstElement($xpath, 'w:cols', $section));
        $pageNumbering = $this->sectionPageNumbering($this->firstElement($xpath, 'w:pgNumType', $section));
        $documentGrid = $this->sectionDocumentGrid($this->firstElement($xpath, 'w:docGrid', $section));
        $titlePage = $this->firstElement($xpath, 'w:titlePg', $section);
        $issues = [];

        foreach (array_merge($headerReferences, $footerReferences) as $reference) {
            foreach ($reference['issues'] as $issue) {
                $issues[] = $issue;
            }
        }

        $issues = array_values(array_unique($issues));
        sort($issues, SORT_STRING);

        return [
            'index' => $index,
            'documentPart' => $partName,
            'type' => $this->emptyStringToNull($this->childAttr($section, 'type', 'val')),
            'headerReferenceCount' => count($headerReferences),
            'footerReferenceCount' => count($footerReferences),
            'headerReferences' => $headerReferences,
            'footerReferences' => $footerReferences,
            'pageSize' => $pageSize,
            'pageMargins' => $pageMargins,
            'columns' => $columns,
            'pageNumbering' => $pageNumbering,
            'documentGrid' => $documentGrid,
            'titlePage' => $titlePage instanceof \DOMElement ? $this->wordBoolean($titlePage) : false,
            'landscape' => ($pageSize['orientation'] ?? null) === 'landscape',
            'textDirection' => $this->emptyStringToNull($this->childAttr($section, 'textDirection', 'val')),
            'issues' => $issues,
        ];
    }

    /**
     * @return list<array<string, mixed>>
     */
    private function sectionReferenceItems(\DOMElement $section, \DOMXPath $xpath, string $kind): array
    {
        $items = [];
        $elementName = $kind === 'footer' ? 'footerReference' : 'headerReference';
        foreach ($this->elements($xpath, 'w:' . $elementName, $section) as $reference) {
            $relationshipId = $reference->getAttributeNS(self::NS_R, 'id');
            $type = $reference->getAttributeNS(self::NS_W, 'type');
            $type = $type === '' ? 'default' : $type;
            $issues = [];
            if ($relationshipId === '') {
                $issues[] = 'missing-' . $kind . '-reference-id';
            }
            if (!in_array($type, ['default', 'even', 'first'], true)) {
                $issues[] = 'invalid-' . $kind . '-reference-type';
            }

            $items[] = [
                'index' => count($items),
                'kind' => $kind,
                'relationshipId' => $relationshipId,
                'type' => $type,
                'validType' => $issues === [] || !in_array('invalid-' . $kind . '-reference-type', $issues, true),
                'issues' => $issues,
            ];
        }

        return $items;
    }

    /**
     * @return array<string, mixed>
     */
    private function sectionPageSize(?\DOMElement $pageSize): array
    {
        if (!$pageSize instanceof \DOMElement) {
            return [
                'present' => false,
                'widthTwips' => null,
                'heightTwips' => null,
                'orientation' => null,
                'code' => null,
            ];
        }

        return [
            'present' => true,
            'widthTwips' => $this->wordOptionalIntAttr($pageSize, 'w'),
            'heightTwips' => $this->wordOptionalIntAttr($pageSize, 'h'),
            'orientation' => $this->emptyStringToNull($pageSize->getAttributeNS(self::NS_W, 'orient')),
            'code' => $this->wordOptionalIntAttr($pageSize, 'code'),
        ];
    }

    /**
     * @return array<string, mixed>
     */
    private function sectionPageMargins(?\DOMElement $pageMargins): array
    {
        $margins = ['top', 'right', 'bottom', 'left', 'header', 'footer', 'gutter'];
        $values = ['present' => $pageMargins instanceof \DOMElement];
        foreach ($margins as $margin) {
            $values[$margin . 'Twips'] = $pageMargins instanceof \DOMElement
                ? $this->wordOptionalIntAttr($pageMargins, $margin)
                : null;
        }

        return $values;
    }

    /**
     * @return array<string, mixed>
     */
    private function sectionColumns(?\DOMElement $columns): array
    {
        if (!$columns instanceof \DOMElement) {
            return [
                'present' => false,
                'count' => null,
                'spaceTwips' => null,
                'equalWidth' => null,
                'separator' => null,
            ];
        }

        return [
            'present' => true,
            'count' => $this->wordOptionalIntAttr($columns, 'num'),
            'spaceTwips' => $this->wordOptionalIntAttr($columns, 'space'),
            'equalWidth' => $this->wordOptionalBooleanAttr($columns, 'equalWidth'),
            'separator' => $this->wordOptionalBooleanAttr($columns, 'sep'),
        ];
    }

    /**
     * @return array<string, mixed>
     */
    private function sectionPageNumbering(?\DOMElement $pageNumbering): array
    {
        if (!$pageNumbering instanceof \DOMElement) {
            return [
                'present' => false,
                'start' => null,
                'format' => null,
                'chapterStyle' => null,
                'chapterSeparator' => null,
            ];
        }

        return [
            'present' => true,
            'start' => $this->wordOptionalIntAttr($pageNumbering, 'start'),
            'format' => $this->emptyStringToNull($pageNumbering->getAttributeNS(self::NS_W, 'fmt')),
            'chapterStyle' => $this->wordOptionalIntAttr($pageNumbering, 'chapStyle'),
            'chapterSeparator' => $this->emptyStringToNull($pageNumbering->getAttributeNS(self::NS_W, 'chapSep')),
        ];
    }

    /**
     * @return array<string, mixed>
     */
    private function sectionDocumentGrid(?\DOMElement $documentGrid): array
    {
        if (!$documentGrid instanceof \DOMElement) {
            return [
                'present' => false,
                'type' => null,
                'linePitch' => null,
                'charSpace' => null,
            ];
        }

        return [
            'present' => true,
            'type' => $this->emptyStringToNull($documentGrid->getAttributeNS(self::NS_W, 'type')),
            'linePitch' => $this->wordOptionalIntAttr($documentGrid, 'linePitch'),
            'charSpace' => $this->wordOptionalIntAttr($documentGrid, 'charSpace'),
        ];
    }

    /**
     * @return array{header:array<string, list<string>>, footer:array<string, list<string>>}
     */
    private function readHeaderFooterReferences(string $xml, string $partName): array
    {
        if ($xml === '') {
            return ['header' => [], 'footer' => []];
        }

        $dom = $this->loadXml($xml, $partName);
        $xpath = $this->xpath($dom);
        $references = ['header' => [], 'footer' => []];
        foreach (['headerReference' => 'header', 'footerReference' => 'footer'] as $elementName => $sourceType) {
            foreach ($this->elements($xpath, '//w:' . $elementName) as $reference) {
                $relationshipId = $reference->getAttributeNS(self::NS_R, 'id');
                if ($relationshipId === '') {
                    continue;
                }

                $type = $reference->getAttributeNS(self::NS_W, 'type');
                $type = $type === '' ? 'default' : $type;
                if (!isset($references[$sourceType][$relationshipId])) {
                    $references[$sourceType][$relationshipId] = [];
                }
                if (!in_array($type, $references[$sourceType][$relationshipId], true)) {
                    $references[$sourceType][$relationshipId][] = $type;
                }
            }
        }

        return $references;
    }

    /**
     * @param array<string, string> $parts
     * @param array<string, array{id:string, type:string, target:string, targetMode:string, resolvedTarget:string}> $relationships
     * @param array<string, list<string>> $referencesByRelationshipId
     * @param array{defaults:array<string, string>, overrides:array<string, string>} $contentTypes
     * @param array<string, array{id:string, name:string, headingLevel:int|null}> $styles
     * @param array<string, array{abstractNumId:string, levels:array<int, array{format:string, text:string, start:int}>}> $numbering
     * @param array<string, array<string, AstNode>> $referencedNotes
     * @return array<string, mixed>
     */
    private function readHeaderFooterParts(
        array $parts,
        array $relationships,
        string $documentPart,
        string $relationshipType,
        string $sourceType,
        string $rootName,
        array $referencesByRelationshipId,
        array $contentTypes,
        array $styles,
        array $numbering,
        array $referencedNotes
    ): array {
        $items = [];
        $byRelationshipId = [];
        $relationshipsPart = $this->relationshipsPartFor($documentPart);
        $handledRelationshipIds = [];

        foreach ($relationships as $relationship) {
            if ($relationship['type'] !== $relationshipType) {
                continue;
            }

            $relationshipId = $relationship['id'];
            $item = $this->headerFooterPartItem(
                $parts,
                $relationship,
                $documentPart,
                $relationshipsPart,
                $relationshipType,
                $sourceType,
                $rootName,
                $contentTypes,
                $styles,
                $numbering,
                $referencedNotes,
                $relationshipId,
                count($items),
                $referencesByRelationshipId[$relationshipId] ?? [],
            );
            $items[] = $item;
            $byRelationshipId[$relationshipId] = $item;
            $handledRelationshipIds[$relationshipId] = true;
        }

        foreach ($referencesByRelationshipId as $relationshipId => $referenceTypes) {
            if (isset($handledRelationshipIds[$relationshipId])) {
                continue;
            }

            $item = $this->headerFooterPartItem(
                $parts,
                $relationships[$relationshipId] ?? null,
                $documentPart,
                $relationshipsPart,
                $relationshipType,
                $sourceType,
                $rootName,
                $contentTypes,
                $styles,
                $numbering,
                $referencedNotes,
                $relationshipId,
                count($items),
                $referenceTypes,
            );
            $items[] = $item;
            $byRelationshipId[$relationshipId] = $item;
        }

        $relationshipIds = [];
        $referencedRelationshipIds = [];
        $partNames = [];
        $externalTargets = [];
        $issueCodes = [];
        foreach ($items as $item) {
            $this->appendUniqueString($relationshipIds, is_string($item['relationshipId'] ?? null) ? $item['relationshipId'] : null);
            if (($item['referenced'] ?? false) === true) {
                $this->appendUniqueString($referencedRelationshipIds, is_string($item['relationshipId'] ?? null) ? $item['relationshipId'] : null);
            }
            $this->appendUniqueString($partNames, is_string($item['partName'] ?? null) ? $item['partName'] : null);
            if (($item['external'] ?? false) === true) {
                $this->appendUniqueString($externalTargets, is_string($item['target'] ?? null) ? $item['target'] : null);
            }
            foreach (($item['issues'] ?? []) as $issue) {
                if (is_string($issue) && $issue !== '') {
                    $issueCodes[$issue] = true;
                }
            }
        }
        ksort($issueCodes, SORT_STRING);

        return [
            'count' => count($items),
            'existingCount' => count(array_filter($items, static fn (array $item): bool => $item['external'] === false && $item['exists'] === true && $item['relationshipType'] === $relationshipType)),
            'missingCount' => count(array_filter($items, static fn (array $item): bool => in_array('missing-in-package', $item['issues'], true))),
            'externalCount' => count(array_filter($items, static fn (array $item): bool => $item['external'] === true)),
            'referencedCount' => count(array_filter($items, static fn (array $item): bool => $item['referenced'] === true)),
            'unresolvedCount' => count(array_filter(
                $items,
                static fn (array $item): bool => in_array('missing-relationship-id', $item['issues'], true) || in_array('unknown-relationship', $item['issues'], true),
            )),
            'unexpectedRelationshipTypeCount' => count(array_filter($items, static fn (array $item): bool => in_array('unexpected-relationship-type', $item['issues'], true))),
            'missingContentTypeCount' => count(array_filter($items, static fn (array $item): bool => in_array('missing-content-type', $item['issues'], true))),
            'issueCount' => count(array_filter($items, static fn (array $item): bool => $item['issues'] !== [])),
            'relationshipIds' => $relationshipIds,
            'referencedRelationshipIds' => $referencedRelationshipIds,
            'partNames' => $partNames,
            'externalTargets' => $externalTargets,
            'issueCodes' => array_keys($issueCodes),
            'byRelationshipId' => $byRelationshipId,
            'items' => $items,
        ];
    }

    /**
     * @param array<string, string> $parts
     * @param array{id:string, type:string, target:string, targetMode:string, resolvedTarget:string}|null $relationship
     * @param array{defaults:array<string, string>, overrides:array<string, string>} $contentTypes
     * @param array<string, array{id:string, name:string, headingLevel:int|null}> $styles
     * @param array<string, array{abstractNumId:string, levels:array<int, array{format:string, text:string, start:int}>}> $numbering
     * @param array<string, array<string, AstNode>> $referencedNotes
     * @param list<string> $referenceTypes
     * @return array<string, mixed>
     */
    private function headerFooterPartItem(
        array $parts,
        ?array $relationship,
        string $documentPart,
        string $relationshipsPart,
        string $expectedRelationshipType,
        string $sourceType,
        string $rootName,
        array $contentTypes,
        array $styles,
        array $numbering,
        array $referencedNotes,
        string $relationshipId,
        int $index,
        array $referenceTypes,
    ): array {
        $item = [
            'index' => $index,
            'relationshipId' => $relationshipId,
            'sourceType' => $sourceType,
            'referenced' => $referenceTypes !== [],
            'referenceTypes' => $referenceTypes,
            'relationshipType' => null,
            'target' => null,
            'targetMode' => null,
            'resolvedTarget' => null,
            'external' => false,
            'partName' => null,
            'targetPart' => null,
            'targetQuery' => null,
            'targetFragment' => null,
            'targetReferenceSuffix' => '',
            'exists' => false,
            'validRoot' => false,
            'rootName' => null,
            'relationshipsPart' => null,
            'relationshipCount' => 0,
            'blockCount' => 0,
            'text' => '',
            'relationship' => null,
            'reviewPolicy' => 'header-footer-metadata-only',
            'issues' => [],
        ];

        if ($relationshipId === '') {
            $item['issues'][] = 'missing-relationship-id';

            return $item;
        }

        if (!is_array($relationship)) {
            $item['issues'][] = 'unknown-relationship';

            return $item;
        }

        $summary = $this->relationshipInventorySummary($parts, $relationship, $documentPart, $relationshipsPart, $contentTypes);
        $targetPart = is_string($summary['targetPart'] ?? null) ? $summary['targetPart'] : null;
        $exists = (bool) $summary['exists'];
        $partRelationshipsPart = $targetPart === null ? null : $this->relationshipsPartFor($targetPart);
        $partRelationships = $partRelationshipsPart === null || (bool) $summary['external']
            ? []
            : $this->readRelationshipsPart($parts, $partRelationshipsPart);

        $item['relationshipType'] = $summary['type'];
        $item['target'] = $summary['target'];
        $item['targetMode'] = $summary['targetMode'];
        $item['resolvedTarget'] = $summary['resolvedTarget'];
        $item['external'] = (bool) $summary['external'];
        $item['partName'] = $targetPart;
        $item['targetPart'] = $targetPart;
        $item['targetQuery'] = $summary['targetQuery'];
        $item['targetFragment'] = $summary['targetFragment'];
        $item['targetReferenceSuffix'] = $summary['targetReferenceSuffix'];
        $item['exists'] = $exists;
        $item['relationshipsPart'] = $partRelationshipsPart;
        $item['relationshipCount'] = count($partRelationships);
        $item['relationship'] = $summary;

        if ($relationship['type'] !== $expectedRelationshipType) {
            $item['issues'][] = 'unexpected-relationship-type';

            return $item;
        }

        if ($item['external'] === true) {
            $item['issues'][] = 'external-' . $sourceType;

            return $item;
        }

        if (!$exists || $targetPart === null) {
            $item['issues'][] = 'missing-in-package';

            return $item;
        }

        if (($summary['contentTypeSource'] ?? '') === 'missing') {
            $item['issues'][] = 'missing-content-type';
        }

        $part = $this->readHeaderFooterPart($parts[$targetPart], $targetPart, $rootName, $partRelationships, $contentTypes, $styles, $numbering, $referencedNotes);
        $item['validRoot'] = $part['validRoot'];
        $item['rootName'] = $part['rootName'];
        $item['blockCount'] = count($part['blocks']);
        $item['text'] = $this->plainBlockText($part['blocks']);

        return $item;
    }

    /**
     * @param array<string, string> $parts
     * @param array<string, array{id:string, type:string, target:string, targetMode:string, resolvedTarget:string}> $relationships
     * @param array{defaults:array<string, string>, overrides:array<string, string>} $contentTypes
     * @return array<string, mixed>
     */
    private function readAlternativeFormatImports(
        array $parts,
        string $xml,
        string $documentPart,
        array $relationships,
        array $contentTypes
    ): array {
        $items = [];
        $byRelationshipId = [];
        $relationshipIds = [];
        $referencedRelationshipIds = [];
        $referencedAltChunkRelationshipIds = [];
        $relationshipsPart = $this->relationshipsPartFor($documentPart);

        if ($xml !== '') {
            $dom = $this->loadXml($xml, $documentPart);
            $xpath = $this->xpath($dom);
            foreach ($this->elements($xpath, '//w:altChunk') as $chunk) {
                $relationshipId = $chunk->getAttributeNS(self::NS_R, 'id');
                $item = $this->alternativeFormatImportItem(
                    $parts,
                    $relationships[$relationshipId] ?? null,
                    $documentPart,
                    $relationshipsPart,
                    $contentTypes,
                    $relationshipId,
                    count($items),
                    true,
                );
                $items[] = $item;

                $this->appendUniqueString($relationshipIds, $relationshipId);
                $this->appendUniqueString($referencedRelationshipIds, $relationshipId);
                if ($item['relationshipType'] === self::ALT_CHUNK_REL) {
                    $this->appendUniqueString($referencedAltChunkRelationshipIds, $relationshipId);
                }
                if ($relationshipId !== '' && !isset($byRelationshipId[$relationshipId])) {
                    $byRelationshipId[$relationshipId] = $item;
                }
            }
        }

        $unreferencedRelationshipIds = [];
        foreach ($relationships as $relationship) {
            if ($relationship['type'] !== self::ALT_CHUNK_REL) {
                continue;
            }

            $relationshipId = $relationship['id'];
            if (in_array($relationshipId, $referencedAltChunkRelationshipIds, true)) {
                continue;
            }

            $item = $this->alternativeFormatImportItem(
                $parts,
                $relationship,
                $documentPart,
                $relationshipsPart,
                $contentTypes,
                $relationshipId,
                count($items),
                false,
            );
            $items[] = $item;

            $this->appendUniqueString($relationshipIds, $relationshipId);
            $this->appendUniqueString($unreferencedRelationshipIds, $relationshipId);
            if (!isset($byRelationshipId[$relationshipId])) {
                $byRelationshipId[$relationshipId] = $item;
            }
        }

        $partNames = [];
        $externalTargets = [];
        $unsafeExternalTargets = [];
        $externalTargetKindCounts = [];
        $externalTargetSchemeCounts = [];
        $externalTargetIssueCodes = [];
        $contentTypesSeen = [];
        $issueCodes = [];
        foreach ($items as $item) {
            $partName = is_string($item['partName'] ?? null) ? $item['partName'] : null;
            $this->appendUniqueString($partNames, $partName);
            $this->appendUniqueString($contentTypesSeen, is_string($item['contentType'] ?? null) ? $item['contentType'] : null);
            if (($item['external'] ?? false) === true) {
                $this->appendUniqueString($externalTargets, is_string($item['target'] ?? null) ? $item['target'] : null);
                if (($item['externalTargetAllowed'] ?? null) !== true) {
                    $this->appendUniqueString($unsafeExternalTargets, is_string($item['target'] ?? null) ? $item['target'] : null);
                }

                $kind = is_string($item['externalTargetKind'] ?? null) ? $item['externalTargetKind'] : '(unknown)';
                $externalTargetKindCounts[$kind] = ($externalTargetKindCounts[$kind] ?? 0) + 1;
                $scheme = is_string($item['externalTargetScheme'] ?? null) ? $item['externalTargetScheme'] : '(none)';
                $externalTargetSchemeCounts[$scheme] = ($externalTargetSchemeCounts[$scheme] ?? 0) + 1;

                foreach (($item['externalTargetIssues'] ?? []) as $issue) {
                    if (is_string($issue) && $issue !== '') {
                        $externalTargetIssueCodes[$issue] = true;
                    }
                }
            }
            foreach (($item['issues'] ?? []) as $issue) {
                if (is_string($issue) && $issue !== '') {
                    $issueCodes[$issue] = true;
                }
            }
        }
        ksort($issueCodes, SORT_STRING);
        ksort($externalTargetKindCounts, SORT_STRING);
        ksort($externalTargetSchemeCounts, SORT_STRING);
        ksort($externalTargetIssueCodes, SORT_STRING);

        return [
            'count' => count($items),
            'relationshipCount' => count(array_filter($relationships, static fn (array $relationship): bool => $relationship['type'] === self::ALT_CHUNK_REL)),
            'referencedCount' => count(array_filter($items, static fn (array $item): bool => $item['referenced'] === true)),
            'unreferencedRelationshipCount' => count($unreferencedRelationshipIds),
            'existingCount' => count(array_filter($items, static fn (array $item): bool => $item['exists'] === true)),
            'missingCount' => count(array_filter($items, static fn (array $item): bool => in_array('missing-in-package', $item['issues'], true))),
            'externalCount' => count(array_filter($items, static fn (array $item): bool => $item['external'] === true)),
            'allowedExternalTargetCount' => count(array_filter($items, static fn (array $item): bool => $item['external'] === true && ($item['externalTargetAllowed'] ?? null) === true)),
            'unsafeExternalTargetCount' => count(array_filter($items, static fn (array $item): bool => $item['external'] === true && ($item['externalTargetAllowed'] ?? null) !== true)),
            'unresolvedCount' => count(array_filter(
                $items,
                static fn (array $item): bool => in_array('missing-relationship-id', $item['issues'], true) || in_array('unknown-relationship', $item['issues'], true),
            )),
            'unexpectedRelationshipTypeCount' => count(array_filter($items, static fn (array $item): bool => in_array('unexpected-relationship-type', $item['issues'], true))),
            'missingContentTypeCount' => count(array_filter($items, static fn (array $item): bool => in_array('missing-content-type', $item['issues'], true))),
            'relationshipIds' => $relationshipIds,
            'referencedRelationshipIds' => $referencedRelationshipIds,
            'unreferencedRelationshipIds' => $unreferencedRelationshipIds,
            'partNames' => $partNames,
            'externalTargets' => $externalTargets,
            'unsafeExternalTargets' => $unsafeExternalTargets,
            'externalTargetKindCounts' => $externalTargetKindCounts,
            'externalTargetSchemeCounts' => $externalTargetSchemeCounts,
            'externalTargetIssueCodes' => array_keys($externalTargetIssueCodes),
            'contentTypes' => $contentTypesSeen,
            'issueCount' => count(array_filter($items, static fn (array $item): bool => $item['issues'] !== [])),
            'issueCodes' => array_keys($issueCodes),
            'byRelationshipId' => $byRelationshipId,
            'items' => $items,
            'byteExposurePolicy' => 'alternative-format-import-bytes-blocked',
            'reviewPolicy' => 'alternative-format-import-metadata-only',
        ];
    }

    /**
     * @param array<string, string> $parts
     * @param array{id:string, type:string, target:string, targetMode:string, resolvedTarget:string}|null $relationship
     * @param array{defaults:array<string, string>, overrides:array<string, string>} $contentTypes
     * @return array<string, mixed>
     */
    private function alternativeFormatImportItem(
        array $parts,
        ?array $relationship,
        string $documentPart,
        string $relationshipsPart,
        array $contentTypes,
        string $relationshipId,
        int $index,
        bool $referenced
    ): array {
        $item = [
            'index' => $index,
            'relationshipId' => $relationshipId,
            'referenced' => $referenced,
            'relationshipType' => null,
            'target' => null,
            'targetMode' => null,
            'resolvedTarget' => null,
            'external' => false,
            'partName' => null,
            'targetPart' => null,
            'targetQuery' => null,
            'targetFragment' => null,
            'targetReferenceSuffix' => '',
            'externalTargetKind' => null,
            'externalTargetScheme' => null,
            'externalTargetAllowed' => null,
            'externalTargetIssues' => [],
            'exists' => false,
            'bytes' => 0,
            'crc32' => null,
            'sha256' => null,
            'contentType' => '',
            'contentTypeBase' => '',
            'contentTypeHasParameters' => false,
            'contentTypeParameterCount' => 0,
            'contentTypeParameters' => [],
            'contentTypeParameterMap' => [],
            'contentTypeSource' => 'missing',
            'defaultExtension' => null,
            'overridePartName' => null,
            'relationshipsPart' => null,
            'relationshipCount' => 0,
            'relationship' => null,
            'byteExposurePolicy' => 'alternative-format-import-bytes-blocked',
            'reviewPolicy' => 'alternative-format-import-metadata-only',
            'issues' => [],
        ];

        if ($relationshipId === '') {
            $item['issues'][] = 'missing-relationship-id';
            return $item;
        }

        if (!is_array($relationship)) {
            $item['issues'][] = 'unknown-relationship';
            return $item;
        }

        $summary = $this->relationshipInventorySummary($parts, $relationship, $documentPart, $relationshipsPart, $contentTypes);
        $targetPart = is_string($summary['targetPart'] ?? null) ? $summary['targetPart'] : null;
        $exists = (bool) $summary['exists'];
        $partRelationshipsPart = $targetPart === null ? null : $this->relationshipsPartFor($targetPart);
        $partRelationships = $partRelationshipsPart === null ? [] : $this->readRelationshipsPart($parts, $partRelationshipsPart);

        $item['relationshipType'] = $summary['type'];
        $item['target'] = $summary['target'];
        $item['targetMode'] = $summary['targetMode'];
        $item['resolvedTarget'] = $summary['resolvedTarget'];
        $item['external'] = (bool) $summary['external'];
        $item['partName'] = $targetPart;
        $item['targetPart'] = $targetPart;
        $item['targetQuery'] = $summary['targetQuery'];
        $item['targetFragment'] = $summary['targetFragment'];
        $item['targetReferenceSuffix'] = $summary['targetReferenceSuffix'];
        $item['externalTargetKind'] = $summary['externalTargetKind'];
        $item['externalTargetScheme'] = $summary['externalTargetScheme'];
        $item['externalTargetAllowed'] = $summary['externalTargetAllowed'];
        $item['externalTargetIssues'] = $summary['externalTargetIssues'];
        $item['exists'] = $exists;
        $item['bytes'] = $exists && $targetPart !== null ? strlen($parts[$targetPart]) : 0;
        $item['crc32'] = $exists && $targetPart !== null ? sprintf('%08x', crc32($parts[$targetPart])) : null;
        $item['sha256'] = $exists && $targetPart !== null ? hash('sha256', $parts[$targetPart]) : null;
        $item['contentType'] = $summary['contentType'];
        $item['contentTypeBase'] = $summary['contentTypeBase'];
        $item['contentTypeHasParameters'] = $summary['contentTypeHasParameters'];
        $item['contentTypeParameterCount'] = $summary['contentTypeParameterCount'];
        $item['contentTypeParameters'] = $summary['contentTypeParameters'];
        $item['contentTypeParameterMap'] = $summary['contentTypeParameterMap'];
        $item['contentTypeSource'] = $summary['contentTypeSource'];
        $item['defaultExtension'] = $summary['defaultExtension'];
        $item['overridePartName'] = $summary['overridePartName'];
        $item['relationshipsPart'] = $partRelationshipsPart;
        $item['relationshipCount'] = count($partRelationships);
        $item['relationship'] = $summary;

        if ($relationship['type'] !== self::ALT_CHUNK_REL) {
            $item['issues'][] = 'unexpected-relationship-type';
            return $item;
        }

        if ($item['external'] === true) {
            $item['issues'][] = 'external-altchunk';
            foreach ($item['externalTargetIssues'] as $issue) {
                if (is_string($issue) && $issue !== '') {
                    $item['issues'][] = $issue;
                }
            }
            return $item;
        }

        if (!$exists) {
            $item['issues'][] = 'missing-in-package';
            return $item;
        }

        if ($item['contentTypeSource'] === 'missing') {
            $item['issues'][] = 'missing-content-type';
        }

        return $item;
    }

    /**
     * @param array<string, string> $parts
     * @param array<string, array{id:string, type:string, target:string, targetMode:string, resolvedTarget:string}> $relationships
     * @param array{defaults:array<string, string>, overrides:array<string, string>} $contentTypes
     * @return array<string, mixed>
     */
    private function readSubdocuments(
        array $parts,
        string $xml,
        string $documentPart,
        array $relationships,
        array $contentTypes
    ): array {
        $items = [];
        $byRelationshipId = [];
        $relationshipIds = [];
        $referencedRelationshipIds = [];
        $referencedSubdocumentRelationshipIds = [];
        $relationshipsPart = $this->relationshipsPartFor($documentPart);

        if ($xml !== '') {
            $dom = $this->loadXml($xml, $documentPart);
            $xpath = $this->xpath($dom);
            foreach ($this->elements($xpath, '//w:subDoc') as $subdocument) {
                $relationshipId = $subdocument->getAttributeNS(self::NS_R, 'id');
                $item = $this->subdocumentItem(
                    $parts,
                    $relationships[$relationshipId] ?? null,
                    $documentPart,
                    $relationshipsPart,
                    $contentTypes,
                    $relationshipId,
                    count($items),
                    true,
                );
                $items[] = $item;

                $this->appendUniqueString($relationshipIds, $relationshipId);
                $this->appendUniqueString($referencedRelationshipIds, $relationshipId);
                if ($item['relationshipType'] === self::SUBDOCUMENT_REL) {
                    $this->appendUniqueString($referencedSubdocumentRelationshipIds, $relationshipId);
                }
                if ($relationshipId !== '' && !isset($byRelationshipId[$relationshipId])) {
                    $byRelationshipId[$relationshipId] = $item;
                }
            }
        }

        $unreferencedRelationshipIds = [];
        foreach ($relationships as $relationship) {
            if ($relationship['type'] !== self::SUBDOCUMENT_REL) {
                continue;
            }

            $relationshipId = $relationship['id'];
            if (in_array($relationshipId, $referencedSubdocumentRelationshipIds, true)) {
                continue;
            }

            $item = $this->subdocumentItem(
                $parts,
                $relationship,
                $documentPart,
                $relationshipsPart,
                $contentTypes,
                $relationshipId,
                count($items),
                false,
            );
            $items[] = $item;

            $this->appendUniqueString($relationshipIds, $relationshipId);
            $this->appendUniqueString($unreferencedRelationshipIds, $relationshipId);
            if (!isset($byRelationshipId[$relationshipId])) {
                $byRelationshipId[$relationshipId] = $item;
            }
        }

        $partNames = [];
        $externalTargets = [];
        $unsafeExternalTargets = [];
        $externalTargetKindCounts = [];
        $externalTargetSchemeCounts = [];
        $externalTargetIssueCodes = [];
        $contentTypesSeen = [];
        $issueCodes = [];
        foreach ($items as $item) {
            $this->appendUniqueString($partNames, is_string($item['partName'] ?? null) ? $item['partName'] : null);
            $this->appendUniqueString($contentTypesSeen, is_string($item['contentType'] ?? null) ? $item['contentType'] : null);
            if (($item['external'] ?? false) === true) {
                $this->appendUniqueString($externalTargets, is_string($item['target'] ?? null) ? $item['target'] : null);
                if (($item['externalTargetAllowed'] ?? null) !== true) {
                    $this->appendUniqueString($unsafeExternalTargets, is_string($item['target'] ?? null) ? $item['target'] : null);
                }

                $kind = is_string($item['externalTargetKind'] ?? null) ? $item['externalTargetKind'] : '(unknown)';
                $externalTargetKindCounts[$kind] = ($externalTargetKindCounts[$kind] ?? 0) + 1;
                $scheme = is_string($item['externalTargetScheme'] ?? null) ? $item['externalTargetScheme'] : '(none)';
                $externalTargetSchemeCounts[$scheme] = ($externalTargetSchemeCounts[$scheme] ?? 0) + 1;

                foreach (($item['externalTargetIssues'] ?? []) as $issue) {
                    if (is_string($issue) && $issue !== '') {
                        $externalTargetIssueCodes[$issue] = true;
                    }
                }
            }
            foreach (($item['issues'] ?? []) as $issue) {
                if (is_string($issue) && $issue !== '') {
                    $issueCodes[$issue] = true;
                }
            }
        }
        ksort($issueCodes, SORT_STRING);
        ksort($externalTargetKindCounts, SORT_STRING);
        ksort($externalTargetSchemeCounts, SORT_STRING);
        ksort($externalTargetIssueCodes, SORT_STRING);

        return [
            'count' => count($items),
            'relationshipCount' => count(array_filter($relationships, static fn (array $relationship): bool => $relationship['type'] === self::SUBDOCUMENT_REL)),
            'referencedCount' => count(array_filter($items, static fn (array $item): bool => $item['referenced'] === true)),
            'unreferencedRelationshipCount' => count($unreferencedRelationshipIds),
            'existingCount' => count(array_filter($items, static fn (array $item): bool => $item['exists'] === true)),
            'missingCount' => count(array_filter($items, static fn (array $item): bool => in_array('missing-in-package', $item['issues'], true))),
            'externalCount' => count(array_filter($items, static fn (array $item): bool => $item['external'] === true)),
            'internalCount' => count(array_filter(
                $items,
                static fn (array $item): bool => is_array($item['relationship']) && $item['external'] !== true,
            )),
            'unresolvedCount' => count(array_filter(
                $items,
                static fn (array $item): bool => in_array('missing-relationship-id', $item['issues'], true) || in_array('unknown-relationship', $item['issues'], true),
            )),
            'unexpectedRelationshipTypeCount' => count(array_filter($items, static fn (array $item): bool => in_array('unexpected-relationship-type', $item['issues'], true))),
            'missingContentTypeCount' => count(array_filter($items, static fn (array $item): bool => in_array('missing-content-type', $item['issues'], true))),
            'allowedExternalTargetCount' => count(array_filter($items, static fn (array $item): bool => $item['external'] === true && ($item['externalTargetAllowed'] ?? null) === true)),
            'unsafeExternalTargetCount' => count(array_filter($items, static fn (array $item): bool => $item['external'] === true && ($item['externalTargetAllowed'] ?? null) !== true)),
            'unsupportedCount' => count(array_filter($items, static fn (array $item): bool => $item['directReaderParity'] === false)),
            'relationshipIds' => $relationshipIds,
            'referencedRelationshipIds' => $referencedRelationshipIds,
            'unreferencedRelationshipIds' => $unreferencedRelationshipIds,
            'partNames' => $partNames,
            'externalTargets' => $externalTargets,
            'unsafeExternalTargets' => $unsafeExternalTargets,
            'externalTargetKindCounts' => $externalTargetKindCounts,
            'externalTargetSchemeCounts' => $externalTargetSchemeCounts,
            'externalTargetIssueCodes' => array_keys($externalTargetIssueCodes),
            'contentTypes' => $contentTypesSeen,
            'issueCount' => count(array_filter($items, static fn (array $item): bool => $item['issues'] !== [])),
            'issueCodes' => array_keys($issueCodes),
            'byRelationshipId' => $byRelationshipId,
            'items' => $items,
            'directReaderParity' => false,
            'unsupportedReason' => 'subdocument-master-document-expansion-not-implemented',
            'byteExposurePolicy' => 'subdocument-package-bytes-blocked',
            'reviewPolicy' => 'subdocument-metadata-only',
        ];
    }

    /**
     * @param array<string, string> $parts
     * @param array{id:string, type:string, target:string, targetMode:string, resolvedTarget:string}|null $relationship
     * @param array{defaults:array<string, string>, overrides:array<string, string>} $contentTypes
     * @return array<string, mixed>
     */
    private function subdocumentItem(
        array $parts,
        ?array $relationship,
        string $documentPart,
        string $relationshipsPart,
        array $contentTypes,
        string $relationshipId,
        int $index,
        bool $referenced
    ): array {
        $item = [
            'index' => $index,
            'relationshipId' => $relationshipId,
            'referenced' => $referenced,
            'relationshipType' => null,
            'target' => null,
            'targetMode' => null,
            'resolvedTarget' => null,
            'external' => false,
            'partName' => null,
            'targetPart' => null,
            'targetQuery' => null,
            'targetFragment' => null,
            'targetReferenceSuffix' => '',
            'externalTargetKind' => null,
            'externalTargetScheme' => null,
            'externalTargetAllowed' => null,
            'externalTargetIssues' => [],
            'exists' => false,
            'bytes' => 0,
            'crc32' => null,
            'sha256' => null,
            'contentType' => '',
            'contentTypeBase' => '',
            'contentTypeHasParameters' => false,
            'contentTypeParameterCount' => 0,
            'contentTypeParameters' => [],
            'contentTypeParameterMap' => [],
            'contentTypeSource' => 'missing',
            'defaultExtension' => null,
            'overridePartName' => null,
            'relationship' => null,
            'directReaderParity' => false,
            'unsupportedReason' => 'subdocument-master-document-expansion-not-implemented',
            'byteExposurePolicy' => 'subdocument-package-bytes-blocked',
            'reviewPolicy' => 'subdocument-metadata-only',
            'issues' => [],
        ];

        if ($relationshipId === '') {
            $item['issues'][] = 'missing-relationship-id';
            return $item;
        }

        if (!is_array($relationship)) {
            $item['issues'][] = 'unknown-relationship';
            return $item;
        }

        $summary = $this->relationshipInventorySummary($parts, $relationship, $documentPart, $relationshipsPart, $contentTypes);
        $targetPart = is_string($summary['targetPart'] ?? null) ? $summary['targetPart'] : null;
        $exists = (bool) $summary['exists'];

        $item['relationshipType'] = $summary['type'];
        $item['target'] = $summary['target'];
        $item['targetMode'] = $summary['targetMode'];
        $item['resolvedTarget'] = $summary['resolvedTarget'];
        $item['external'] = (bool) $summary['external'];
        $item['partName'] = $targetPart;
        $item['targetPart'] = $targetPart;
        $item['targetQuery'] = $summary['targetQuery'];
        $item['targetFragment'] = $summary['targetFragment'];
        $item['targetReferenceSuffix'] = $summary['targetReferenceSuffix'];
        $item['externalTargetKind'] = $summary['externalTargetKind'];
        $item['externalTargetScheme'] = $summary['externalTargetScheme'];
        $item['externalTargetAllowed'] = $summary['externalTargetAllowed'];
        $item['externalTargetIssues'] = $summary['externalTargetIssues'];
        $item['exists'] = $exists;
        $item['bytes'] = $exists && $targetPart !== null ? strlen($parts[$targetPart]) : 0;
        $item['crc32'] = $exists && $targetPart !== null ? sprintf('%08x', crc32($parts[$targetPart])) : null;
        $item['sha256'] = $exists && $targetPart !== null ? hash('sha256', $parts[$targetPart]) : null;
        $item['contentType'] = $summary['contentType'];
        $item['contentTypeBase'] = $summary['contentTypeBase'];
        $item['contentTypeHasParameters'] = $summary['contentTypeHasParameters'];
        $item['contentTypeParameterCount'] = $summary['contentTypeParameterCount'];
        $item['contentTypeParameters'] = $summary['contentTypeParameters'];
        $item['contentTypeParameterMap'] = $summary['contentTypeParameterMap'];
        $item['contentTypeSource'] = $summary['contentTypeSource'];
        $item['defaultExtension'] = $summary['defaultExtension'];
        $item['overridePartName'] = $summary['overridePartName'];
        $item['relationship'] = $summary;

        if ($relationship['type'] !== self::SUBDOCUMENT_REL) {
            $item['issues'][] = 'unexpected-relationship-type';
            return $item;
        }

        if ($item['external'] === true) {
            foreach ($item['externalTargetIssues'] as $issue) {
                if (is_string($issue) && $issue !== '') {
                    $this->appendUniqueString($item['issues'], $issue);
                }
            }

            return $item;
        }

        $item['issues'][] = 'internal-subdocument-target';

        if (!$exists) {
            $item['issues'][] = 'missing-in-package';
        }

        if ($item['contentTypeSource'] === 'missing') {
            $item['issues'][] = 'missing-content-type';
        }

        return $item;
    }

    /**
     * @param array<string, string> $parts
     * @param array<string, array{id:string, type:string, target:string, targetMode:string, resolvedTarget:string}> $relationships
     * @param array{defaults:array<string, string>, overrides:array<string, string>} $contentTypes
     * @return array<string, mixed>
     */
    private function readEmbeddedObjects(
        array $parts,
        string $xml,
        string $documentPart,
        array $relationships,
        array $contentTypes
    ): array {
        $items = [];
        $byRelationshipId = [];
        $relationshipIds = [];
        $referencedRelationshipIds = [];
        $referencedEmbeddedRelationshipIds = [];
        $relationshipsPart = $this->relationshipsPartFor($documentPart);

        if ($xml !== '') {
            $dom = $this->loadXml($xml, $documentPart);
            $xpath = $this->xpath($dom);
            foreach ($this->elements($xpath, '//o:OLEObject') as $object) {
                $relationshipId = $object->getAttributeNS(self::NS_R, 'id');
                $item = $this->embeddedObjectItem(
                    $parts,
                    $relationships[$relationshipId] ?? null,
                    $documentPart,
                    $relationshipsPart,
                    $contentTypes,
                    $relationshipId,
                    count($items),
                    true,
                    $this->embeddedObjectDescriptor($object),
                );
                $items[] = $item;

                $this->appendUniqueString($relationshipIds, $relationshipId);
                $this->appendUniqueString($referencedRelationshipIds, $relationshipId);
                if ($this->isEmbeddedObjectRelationshipType((string) ($item['relationshipType'] ?? ''))) {
                    $this->appendUniqueString($referencedEmbeddedRelationshipIds, $relationshipId);
                }
                if ($relationshipId !== '' && !isset($byRelationshipId[$relationshipId])) {
                    $byRelationshipId[$relationshipId] = $item;
                }
            }
        }

        $unreferencedRelationshipIds = [];
        foreach ($relationships as $relationship) {
            if (!$this->isEmbeddedObjectRelationshipType($relationship['type'])) {
                continue;
            }

            $relationshipId = $relationship['id'];
            if (in_array($relationshipId, $referencedEmbeddedRelationshipIds, true)) {
                continue;
            }

            $item = $this->embeddedObjectItem(
                $parts,
                $relationship,
                $documentPart,
                $relationshipsPart,
                $contentTypes,
                $relationshipId,
                count($items),
                false,
                null,
            );
            $items[] = $item;

            $this->appendUniqueString($relationshipIds, $relationshipId);
            $this->appendUniqueString($unreferencedRelationshipIds, $relationshipId);
            if (!isset($byRelationshipId[$relationshipId])) {
                $byRelationshipId[$relationshipId] = $item;
            }
        }

        $partNames = [];
        $externalTargets = [];
        $unsafeExternalTargets = [];
        $externalTargetKindCounts = [];
        $externalTargetSchemeCounts = [];
        $externalTargetIssueCodes = [];
        $contentTypesSeen = [];
        $issueCodes = [];
        foreach ($items as $item) {
            $partName = is_string($item['partName'] ?? null) ? $item['partName'] : null;
            $this->appendUniqueString($partNames, $partName);
            $this->appendUniqueString($contentTypesSeen, is_string($item['contentType'] ?? null) ? $item['contentType'] : null);
            if (($item['external'] ?? false) === true) {
                $this->appendUniqueString($externalTargets, is_string($item['target'] ?? null) ? $item['target'] : null);
                if (($item['externalTargetAllowed'] ?? null) !== true) {
                    $this->appendUniqueString($unsafeExternalTargets, is_string($item['target'] ?? null) ? $item['target'] : null);
                }

                $kind = is_string($item['externalTargetKind'] ?? null) ? $item['externalTargetKind'] : '(unknown)';
                $externalTargetKindCounts[$kind] = ($externalTargetKindCounts[$kind] ?? 0) + 1;
                $scheme = is_string($item['externalTargetScheme'] ?? null) ? $item['externalTargetScheme'] : '(none)';
                $externalTargetSchemeCounts[$scheme] = ($externalTargetSchemeCounts[$scheme] ?? 0) + 1;

                foreach (($item['externalTargetIssues'] ?? []) as $issue) {
                    if (is_string($issue) && $issue !== '') {
                        $externalTargetIssueCodes[$issue] = true;
                    }
                }
            }
            foreach (($item['issues'] ?? []) as $issue) {
                if (is_string($issue) && $issue !== '') {
                    $issueCodes[$issue] = true;
                }
            }
        }
        ksort($issueCodes, SORT_STRING);
        ksort($externalTargetKindCounts, SORT_STRING);
        ksort($externalTargetSchemeCounts, SORT_STRING);
        ksort($externalTargetIssueCodes, SORT_STRING);

        return [
            'count' => count($items),
            'relationshipCount' => count(array_filter($relationships, fn (array $relationship): bool => $this->isEmbeddedObjectRelationshipType($relationship['type']))),
            'referencedCount' => count(array_filter($items, static fn (array $item): bool => $item['referenced'] === true)),
            'unreferencedRelationshipCount' => count($unreferencedRelationshipIds),
            'existingCount' => count(array_filter($items, static fn (array $item): bool => $item['exists'] === true)),
            'missingCount' => count(array_filter($items, static fn (array $item): bool => in_array('missing-in-package', $item['issues'], true))),
            'externalCount' => count(array_filter($items, static fn (array $item): bool => $item['external'] === true)),
            'allowedExternalTargetCount' => count(array_filter($items, static fn (array $item): bool => $item['external'] === true && ($item['externalTargetAllowed'] ?? null) === true)),
            'unsafeExternalTargetCount' => count(array_filter($items, static fn (array $item): bool => $item['external'] === true && ($item['externalTargetAllowed'] ?? null) !== true)),
            'unresolvedCount' => count(array_filter(
                $items,
                static fn (array $item): bool => in_array('missing-relationship-id', $item['issues'], true) || in_array('unknown-relationship', $item['issues'], true),
            )),
            'unexpectedRelationshipTypeCount' => count(array_filter($items, static fn (array $item): bool => in_array('unexpected-relationship-type', $item['issues'], true))),
            'missingContentTypeCount' => count(array_filter($items, static fn (array $item): bool => in_array('missing-content-type', $item['issues'], true))),
            'relationshipIds' => $relationshipIds,
            'referencedRelationshipIds' => $referencedRelationshipIds,
            'unreferencedRelationshipIds' => $unreferencedRelationshipIds,
            'partNames' => $partNames,
            'externalTargets' => $externalTargets,
            'unsafeExternalTargets' => $unsafeExternalTargets,
            'externalTargetKindCounts' => $externalTargetKindCounts,
            'externalTargetSchemeCounts' => $externalTargetSchemeCounts,
            'externalTargetIssueCodes' => array_keys($externalTargetIssueCodes),
            'contentTypes' => $contentTypesSeen,
            'issueCount' => count(array_filter($items, static fn (array $item): bool => $item['issues'] !== [])),
            'issueCodes' => array_keys($issueCodes),
            'byRelationshipId' => $byRelationshipId,
            'items' => $items,
            'byteExposurePolicy' => 'embedded-object-bytes-blocked',
            'reviewPolicy' => 'embedded-object-metadata-only',
        ];
    }

    /**
     * @return array{progId:?string, shapeId:?string, drawAspect:?string, objectId:?string, updateMode:?string}
     */
    private function embeddedObjectDescriptor(\DOMElement $object): array
    {
        return [
            'progId' => $this->emptyStringToNull($object->getAttribute('ProgID')),
            'shapeId' => $this->emptyStringToNull($object->getAttribute('ShapeID')),
            'drawAspect' => $this->emptyStringToNull($object->getAttribute('DrawAspect')),
            'objectId' => $this->emptyStringToNull($object->getAttribute('ObjectID')),
            'updateMode' => $this->emptyStringToNull($object->getAttribute('UpdateMode')),
        ];
    }

    /**
     * @param array<string, string> $parts
     * @param array{id:string, type:string, target:string, targetMode:string, resolvedTarget:string}|null $relationship
     * @param array{defaults:array<string, string>, overrides:array<string, string>} $contentTypes
     * @param array{progId:?string, shapeId:?string, drawAspect:?string, objectId:?string, updateMode:?string}|null $descriptor
     * @return array<string, mixed>
     */
    private function embeddedObjectItem(
        array $parts,
        ?array $relationship,
        string $documentPart,
        string $relationshipsPart,
        array $contentTypes,
        string $relationshipId,
        int $index,
        bool $referenced,
        ?array $descriptor
    ): array {
        $item = [
            'index' => $index,
            'relationshipId' => $relationshipId,
            'referenced' => $referenced,
            'progId' => $descriptor['progId'] ?? null,
            'shapeId' => $descriptor['shapeId'] ?? null,
            'drawAspect' => $descriptor['drawAspect'] ?? null,
            'objectId' => $descriptor['objectId'] ?? null,
            'updateMode' => $descriptor['updateMode'] ?? null,
            'relationshipType' => null,
            'target' => null,
            'targetMode' => null,
            'resolvedTarget' => null,
            'external' => false,
            'partName' => null,
            'targetPart' => null,
            'targetQuery' => null,
            'targetFragment' => null,
            'targetReferenceSuffix' => '',
            'externalTargetKind' => null,
            'externalTargetScheme' => null,
            'externalTargetAllowed' => null,
            'externalTargetIssues' => [],
            'exists' => false,
            'bytes' => 0,
            'crc32' => null,
            'sha256' => null,
            'contentType' => '',
            'contentTypeBase' => '',
            'contentTypeHasParameters' => false,
            'contentTypeParameterCount' => 0,
            'contentTypeParameters' => [],
            'contentTypeParameterMap' => [],
            'contentTypeSource' => 'missing',
            'defaultExtension' => null,
            'overridePartName' => null,
            'relationshipsPart' => null,
            'relationshipsPartExists' => false,
            'relationshipsPartBytes' => 0,
            'relationshipCount' => 0,
            'relationshipRecordCount' => 0,
            'duplicateRelationshipIdCount' => 0,
            'duplicateRelationshipRecordCount' => 0,
            'duplicateRelationshipIds' => [],
            'duplicateRelationshipIdItems' => [],
            'invalidRelationshipRecordCount' => 0,
            'relationshipRecordIssueCount' => 0,
            'relationshipRecordIssueCodes' => [],
            'invalidRelationshipRecords' => [],
            'relationships' => [],
            'relationshipRecords' => [],
            'relationship' => null,
            'byteExposurePolicy' => 'embedded-object-bytes-blocked',
            'reviewPolicy' => 'embedded-object-metadata-only',
            'issues' => [],
        ];

        if ($relationshipId === '') {
            $item['issues'][] = 'missing-relationship-id';
            return $item;
        }

        if (!is_array($relationship)) {
            $item['issues'][] = 'unknown-relationship';
            return $item;
        }

        $summary = $this->relationshipInventorySummary($parts, $relationship, $documentPart, $relationshipsPart, $contentTypes);
        $targetPart = is_string($summary['targetPart'] ?? null) ? $summary['targetPart'] : null;
        $exists = (bool) $summary['exists'];
        $partRelationshipsPart = $targetPart === null ? null : $this->relationshipsPartFor($targetPart);
        $partRelationships = $partRelationshipsPart === null ? [] : $this->readRelationshipsPart($parts, $partRelationshipsPart);
        $partRelationshipProvenance = $partRelationshipsPart === null
            ? null
            : $this->relationshipPartProvenance($parts, $partRelationshipsPart, $targetPart ?? '', $partRelationships, $contentTypes);

        $item['relationshipType'] = $summary['type'];
        $item['target'] = $summary['target'];
        $item['targetMode'] = $summary['targetMode'];
        $item['resolvedTarget'] = $summary['resolvedTarget'];
        $item['external'] = (bool) $summary['external'];
        $item['partName'] = $targetPart;
        $item['targetPart'] = $targetPart;
        $item['targetQuery'] = $summary['targetQuery'];
        $item['targetFragment'] = $summary['targetFragment'];
        $item['targetReferenceSuffix'] = $summary['targetReferenceSuffix'];
        $item['externalTargetKind'] = $summary['externalTargetKind'];
        $item['externalTargetScheme'] = $summary['externalTargetScheme'];
        $item['externalTargetAllowed'] = $summary['externalTargetAllowed'];
        $item['externalTargetIssues'] = $summary['externalTargetIssues'];
        $item['exists'] = $exists;
        $item['bytes'] = $exists && $targetPart !== null ? strlen($parts[$targetPart]) : 0;
        $item['crc32'] = $exists && $targetPart !== null ? sprintf('%08x', crc32($parts[$targetPart])) : null;
        $item['sha256'] = $exists && $targetPart !== null ? hash('sha256', $parts[$targetPart]) : null;
        $item['contentType'] = $summary['contentType'];
        $item['contentTypeBase'] = $summary['contentTypeBase'];
        $item['contentTypeHasParameters'] = $summary['contentTypeHasParameters'];
        $item['contentTypeParameterCount'] = $summary['contentTypeParameterCount'];
        $item['contentTypeParameters'] = $summary['contentTypeParameters'];
        $item['contentTypeParameterMap'] = $summary['contentTypeParameterMap'];
        $item['contentTypeSource'] = $summary['contentTypeSource'];
        $item['defaultExtension'] = $summary['defaultExtension'];
        $item['overridePartName'] = $summary['overridePartName'];
        $item['relationshipsPart'] = $partRelationshipsPart;
        $item['relationshipCount'] = count($partRelationships);
        if ($partRelationshipProvenance !== null) {
            $item['relationshipsPartExists'] = (bool) $partRelationshipProvenance['exists'];
            $item['relationshipsPartBytes'] = (int) $partRelationshipProvenance['bytes'];
            $item['relationshipRecordCount'] = (int) $partRelationshipProvenance['relationshipRecordCount'];
            $item['duplicateRelationshipIdCount'] = (int) $partRelationshipProvenance['duplicateRelationshipIdCount'];
            $item['duplicateRelationshipRecordCount'] = (int) $partRelationshipProvenance['duplicateRelationshipRecordCount'];
            $item['duplicateRelationshipIds'] = $partRelationshipProvenance['duplicateRelationshipIds'];
            $item['duplicateRelationshipIdItems'] = $partRelationshipProvenance['duplicateRelationshipIdItems'];
            $item['invalidRelationshipRecordCount'] = (int) $partRelationshipProvenance['invalidRelationshipRecordCount'];
            $item['relationshipRecordIssueCount'] = (int) $partRelationshipProvenance['relationshipRecordIssueCount'];
            $item['relationshipRecordIssueCodes'] = $partRelationshipProvenance['relationshipRecordIssueCodes'];
            $item['invalidRelationshipRecords'] = $partRelationshipProvenance['invalidRelationshipRecords'];
            $item['relationships'] = $partRelationshipProvenance['relationships'];
            $item['relationshipRecords'] = $partRelationshipProvenance['relationshipRecords'];
        }
        $item['relationship'] = $summary;

        if (!$this->isEmbeddedObjectRelationshipType($relationship['type'])) {
            $item['issues'][] = 'unexpected-relationship-type';
            return $item;
        }

        if ($item['external'] === true) {
            $item['issues'][] = 'external-embedded-object';
            foreach ($item['externalTargetIssues'] as $issue) {
                if (is_string($issue) && $issue !== '') {
                    $this->appendUniqueString($item['issues'], $issue);
                }
            }
            return $item;
        }

        if (!$exists) {
            $item['issues'][] = 'missing-in-package';
        }

        if ($item['contentTypeSource'] === 'missing') {
            $item['issues'][] = 'missing-content-type';
        }

        return $item;
    }

    private function isEmbeddedObjectRelationshipType(string $relationshipType): bool
    {
        return $relationshipType === self::OLE_OBJECT_REL
            || $relationshipType === self::EMBEDDED_PACKAGE_REL;
    }

    /**
     * @param array<string, string> $parts
     * @param array<string, array{id:string, type:string, target:string, targetMode:string, resolvedTarget:string}> $relationships
     * @param array{defaults:array<string, string>, overrides:array<string, string>} $contentTypes
     * @return array<string, mixed>
     */
    private function readDocumentHyperlinks(
        array $parts,
        string $xml,
        string $documentPart,
        array $relationships,
        array $contentTypes
    ): array {
        $items = [];
        $byRelationshipId = [];
        $relationshipIds = [];
        $referencedRelationshipIds = [];
        $referencedHyperlinkRelationshipIds = [];
        $anchors = [];
        $relationshipsPart = $this->relationshipsPartFor($documentPart);

        if ($xml !== '') {
            $dom = $this->loadXml($xml, $documentPart);
            $xpath = $this->xpath($dom);
            foreach ($this->elements($xpath, '//w:hyperlink') as $hyperlink) {
                $relationshipId = $hyperlink->getAttributeNS(self::NS_R, 'id');
                $anchor = $hyperlink->getAttributeNS(self::NS_W, 'anchor');
                $referenceKind = $relationshipId !== ''
                    ? ($anchor === '' ? 'relationship' : 'relationship-anchor')
                    : ($anchor === '' ? 'empty' : 'anchor');

                $item = $this->documentHyperlinkItem(
                    $parts,
                    $relationships[$relationshipId] ?? null,
                    $documentPart,
                    $relationshipsPart,
                    $contentTypes,
                    $relationshipId,
                    count($items),
                    true,
                    $referenceKind,
                    $anchor,
                    $hyperlink->getAttributeNS(self::NS_W, 'docLocation'),
                    $hyperlink->getAttributeNS(self::NS_W, 'tooltip'),
                    $hyperlink->getAttributeNS(self::NS_W, 'tgtFrame'),
                    $hyperlink->getAttributeNS(self::NS_W, 'history'),
                );
                $items[] = $item;

                $this->appendUniqueString($relationshipIds, $relationshipId);
                $this->appendUniqueString($referencedRelationshipIds, $relationshipId);
                $this->appendUniqueString($anchors, $anchor);
                if (($item['relationshipType'] ?? null) === self::HYPERLINK_REL) {
                    $this->appendUniqueString($referencedHyperlinkRelationshipIds, $relationshipId);
                }
                if ($relationshipId !== '' && !isset($byRelationshipId[$relationshipId])) {
                    $byRelationshipId[$relationshipId] = $item;
                }
            }
        }

        $unreferencedRelationshipIds = [];
        foreach ($relationships as $relationship) {
            if ($relationship['type'] !== self::HYPERLINK_REL) {
                continue;
            }

            $relationshipId = $relationship['id'];
            if (in_array($relationshipId, $referencedHyperlinkRelationshipIds, true)) {
                continue;
            }

            $item = $this->documentHyperlinkItem(
                $parts,
                $relationship,
                $documentPart,
                $relationshipsPart,
                $contentTypes,
                $relationshipId,
                count($items),
                false,
                'relationship',
                '',
                '',
                '',
                '',
                '',
            );
            $items[] = $item;

            $this->appendUniqueString($relationshipIds, $relationshipId);
            $this->appendUniqueString($unreferencedRelationshipIds, $relationshipId);
            if (!isset($byRelationshipId[$relationshipId])) {
                $byRelationshipId[$relationshipId] = $item;
            }
        }

        $targetParts = [];
        $externalTargets = [];
        $issueCodes = [];
        foreach ($items as $item) {
            if (($item['relationshipType'] ?? null) === self::HYPERLINK_REL) {
                $this->appendUniqueString($targetParts, is_string($item['targetPart'] ?? null) ? $item['targetPart'] : null);
            }
            if (($item['external'] ?? false) === true) {
                $this->appendUniqueString($externalTargets, is_string($item['target'] ?? null) ? $item['target'] : null);
            }
            foreach (($item['issues'] ?? []) as $issue) {
                if (is_string($issue) && $issue !== '') {
                    $issueCodes[$issue] = true;
                }
            }
        }
        ksort($issueCodes, SORT_STRING);

        return [
            'count' => count($items),
            'relationshipCount' => count(array_filter($relationships, static fn (array $relationship): bool => $relationship['type'] === self::HYPERLINK_REL)),
            'referenceCount' => count(array_filter($items, static fn (array $item): bool => $item['referenced'] === true)),
            'referencedRelationshipCount' => count($referencedHyperlinkRelationshipIds),
            'unreferencedRelationshipCount' => count($unreferencedRelationshipIds),
            'anchorOnlyCount' => count(array_filter($items, static fn (array $item): bool => $item['referenceKind'] === 'anchor')),
            'anchorRelationshipCount' => count(array_filter($items, static fn (array $item): bool => $item['referenceKind'] === 'relationship-anchor')),
            'externalCount' => count(array_filter($items, static fn (array $item): bool => $item['relationshipType'] === self::HYPERLINK_REL && $item['external'] === true)),
            'unsafeExternalTargetCount' => count(array_filter($items, static fn (array $item): bool => in_array('external-target-unsafe-scheme', $item['issues'], true))),
            'internalTargetExistingCount' => count(array_filter($items, static fn (array $item): bool => $item['relationshipType'] === self::HYPERLINK_REL && $item['external'] === false && $item['exists'] === true)),
            'internalTargetMissingCount' => count(array_filter($items, static fn (array $item): bool => $item['relationshipType'] === self::HYPERLINK_REL && in_array('missing-hyperlink-target', $item['issues'], true))),
            'unknownRelationshipCount' => count(array_filter($items, static fn (array $item): bool => in_array('unknown-relationship', $item['issues'], true))),
            'missingContentTypeCount' => count(array_filter($items, static fn (array $item): bool => in_array('missing-hyperlink-content-type', $item['issues'], true))),
            'unexpectedRelationshipTypeCount' => count(array_filter($items, static fn (array $item): bool => in_array('unexpected-relationship-type', $item['issues'], true))),
            'issueCount' => count(array_filter($items, static fn (array $item): bool => $item['issues'] !== [])),
            'relationshipIds' => $relationshipIds,
            'referencedRelationshipIds' => $referencedRelationshipIds,
            'referencedHyperlinkRelationshipIds' => $referencedHyperlinkRelationshipIds,
            'unreferencedRelationshipIds' => $unreferencedRelationshipIds,
            'anchors' => $anchors,
            'targetParts' => $targetParts,
            'externalTargets' => $externalTargets,
            'issueCodes' => array_keys($issueCodes),
            'byRelationshipId' => $byRelationshipId,
            'items' => $items,
            'byteExposurePolicy' => 'document-hyperlink-target-bytes-blocked',
            'reviewPolicy' => 'document-hyperlink-metadata-only',
        ];
    }

    /**
     * @param array<string, string> $parts
     * @param array{id:string, type:string, target:string, targetMode:string, resolvedTarget:string}|null $relationship
     * @param array{defaults:array<string, string>, overrides:array<string, string>} $contentTypes
     * @return array<string, mixed>
     */
    private function documentHyperlinkItem(
        array $parts,
        ?array $relationship,
        string $documentPart,
        string $relationshipsPart,
        array $contentTypes,
        string $relationshipId,
        int $index,
        bool $referenced,
        string $referenceKind,
        string $anchor,
        string $docLocation,
        string $tooltip,
        string $targetFrame,
        string $history
    ): array {
        $item = [
            'index' => $index,
            'relationshipId' => $relationshipId,
            'referenced' => $referenced,
            'referenceKind' => $referenceKind,
            'anchor' => $anchor === '' ? null : $anchor,
            'docLocation' => $docLocation === '' ? null : $docLocation,
            'tooltip' => $tooltip === '' ? null : $tooltip,
            'targetFrame' => $targetFrame === '' ? null : $targetFrame,
            'history' => $history === '' ? null : $history,
            'url' => '',
            'relationshipType' => null,
            'target' => null,
            'targetMode' => null,
            'resolvedTarget' => null,
            'external' => false,
            'targetPart' => null,
            'targetQuery' => null,
            'targetFragment' => null,
            'targetReferenceSuffix' => '',
            'exists' => false,
            'byteLength' => null,
            'crc32' => null,
            'sha256' => null,
            'contentType' => '',
            'contentTypeBase' => '',
            'contentTypeHasParameters' => false,
            'contentTypeParameterCount' => 0,
            'contentTypeParameters' => [],
            'contentTypeParameterMap' => [],
            'contentTypeSource' => 'missing',
            'defaultExtension' => null,
            'overridePartName' => null,
            'externalTargetKind' => null,
            'externalTargetScheme' => null,
            'externalTargetAllowed' => null,
            'byteExposurePolicy' => 'document-hyperlink-target-bytes-blocked',
            'reviewPolicy' => 'document-hyperlink-metadata-only',
            'valid' => false,
            'issues' => [],
            'relationship' => null,
        ];

        if ($relationshipId === '') {
            if ($anchor === '') {
                $item['issues'][] = 'missing-hyperlink-target';
            } else {
                $item['url'] = '#' . $anchor;
            }

            $item['valid'] = $item['issues'] === [];
            return $item;
        }

        if (!is_array($relationship)) {
            $item['issues'][] = 'unknown-relationship';
            if ($anchor !== '') {
                $item['url'] = '#' . $anchor;
            }

            return $item;
        }

        $summary = $this->relationshipInventorySummary($parts, $relationship, $documentPart, $relationshipsPart, $contentTypes);
        $targetPart = is_string($summary['targetPart'] ?? null) ? $summary['targetPart'] : null;
        $exists = (bool) $summary['exists'];

        $item['relationshipType'] = $summary['type'];
        $item['target'] = $summary['target'];
        $item['targetMode'] = $summary['targetMode'];
        $item['resolvedTarget'] = $summary['resolvedTarget'];
        $item['external'] = (bool) $summary['external'];
        $item['targetPart'] = $targetPart;
        $item['targetQuery'] = $summary['targetQuery'];
        $item['targetFragment'] = $summary['targetFragment'];
        $item['targetReferenceSuffix'] = $summary['targetReferenceSuffix'];
        $item['exists'] = $exists;
        $item['contentType'] = $summary['contentType'];
        $item['contentTypeBase'] = $summary['contentTypeBase'];
        $item['contentTypeHasParameters'] = $summary['contentTypeHasParameters'];
        $item['contentTypeParameterCount'] = $summary['contentTypeParameterCount'];
        $item['contentTypeParameters'] = $summary['contentTypeParameters'];
        $item['contentTypeParameterMap'] = $summary['contentTypeParameterMap'];
        $item['contentTypeSource'] = $summary['contentTypeSource'];
        $item['defaultExtension'] = $summary['defaultExtension'];
        $item['overridePartName'] = $summary['overridePartName'];
        $item['relationship'] = $summary;
        $item['url'] = $item['external'] ? (string) $summary['target'] : (string) $summary['resolvedTarget'];
        if ($anchor !== '') {
            $item['url'] .= '#' . $anchor;
        }

        if ($relationship['type'] !== self::HYPERLINK_REL) {
            $item['issues'][] = 'unexpected-relationship-type';
        }

        if ($item['external']) {
            $externalPolicy = $this->externalRelationshipTargetPolicy($relationship['target']);
            $item['externalTargetKind'] = $externalPolicy['kind'];
            $item['externalTargetScheme'] = $externalPolicy['scheme'];
            $item['externalTargetAllowed'] = $externalPolicy['allowed'];
            $item['issues'] = array_values(array_unique(array_merge($item['issues'], $externalPolicy['issues'])));
        } elseif ($targetPart !== null) {
            if ($exists) {
                $item['byteLength'] = strlen($parts[$targetPart]);
                $item['crc32'] = sprintf('%08x', crc32($parts[$targetPart]));
                $item['sha256'] = hash('sha256', $parts[$targetPart]);
            } else {
                $item['issues'][] = 'missing-hyperlink-target';
            }
            if (($summary['contentTypeSource'] ?? '') === 'missing') {
                $item['issues'][] = 'missing-hyperlink-content-type';
            }
        }

        $item['issues'] = array_values(array_unique($item['issues']));
        sort($item['issues'], SORT_STRING);
        $item['valid'] = $item['issues'] === [];

        return $item;
    }

    /**
     * @param array<string, string> $parts
     * @param array<string, array{id:string, type:string, target:string, targetMode:string, resolvedTarget:string}> $relationships
     * @param array{defaults:array<string, string>, overrides:array<string, string>} $contentTypes
     * @return array<string, mixed>
     */
    private function readDocumentMediaRelationships(
        array $parts,
        string $xml,
        string $documentPart,
        array $relationships,
        array $contentTypes
    ): array {
        $items = [];
        $byRelationshipId = [];
        $relationshipIds = [];
        $referencedRelationshipIds = [];
        $referencedImageRelationshipIds = [];
        $relationshipsPart = $this->relationshipsPartFor($documentPart);

        if ($xml !== '') {
            $dom = $this->loadXml($xml, $documentPart);
            $xpath = $this->xpath($dom);
            foreach ($this->elements($xpath, '//a:blip') as $blip) {
                $relationshipId = $blip->getAttributeNS(self::NS_R, 'embed');
                $referenceKind = 'embed';
                if ($relationshipId === '') {
                    $relationshipId = $blip->getAttributeNS(self::NS_R, 'link');
                    $referenceKind = $relationshipId === '' ? 'missing' : 'link';
                }

                $item = $this->documentMediaRelationshipItem(
                    $parts,
                    $relationships[$relationshipId] ?? null,
                    $documentPart,
                    $relationshipsPart,
                    $contentTypes,
                    $relationshipId,
                    count($items),
                    true,
                    $referenceKind,
                );
                $items[] = $item;

                $this->appendUniqueString($relationshipIds, $relationshipId);
                $this->appendUniqueString($referencedRelationshipIds, $relationshipId);
                if ($item['relationshipType'] === self::IMAGE_REL) {
                    $this->appendUniqueString($referencedImageRelationshipIds, $relationshipId);
                }
                if ($relationshipId !== '' && !isset($byRelationshipId[$relationshipId])) {
                    $byRelationshipId[$relationshipId] = $item;
                }
            }
            foreach ($this->elements($xpath, '//v:imagedata') as $imageData) {
                $relationshipId = $this->vmlImageRelationshipId($imageData);
                $item = $this->documentMediaRelationshipItem(
                    $parts,
                    $relationships[$relationshipId] ?? null,
                    $documentPart,
                    $relationshipsPart,
                    $contentTypes,
                    $relationshipId,
                    count($items),
                    true,
                    'vml',
                );
                $items[] = $item;

                $this->appendUniqueString($relationshipIds, $relationshipId);
                $this->appendUniqueString($referencedRelationshipIds, $relationshipId);
                if ($item['relationshipType'] === self::IMAGE_REL) {
                    $this->appendUniqueString($referencedImageRelationshipIds, $relationshipId);
                }
                if ($relationshipId !== '' && !isset($byRelationshipId[$relationshipId])) {
                    $byRelationshipId[$relationshipId] = $item;
                }
            }
        }

        $unreferencedRelationshipIds = [];
        foreach ($relationships as $relationship) {
            if ($relationship['type'] !== self::IMAGE_REL) {
                continue;
            }

            $relationshipId = $relationship['id'];
            if (in_array($relationshipId, $referencedImageRelationshipIds, true)) {
                continue;
            }

            $item = $this->documentMediaRelationshipItem(
                $parts,
                $relationship,
                $documentPart,
                $relationshipsPart,
                $contentTypes,
                $relationshipId,
                count($items),
                false,
                'relationship',
            );
            $items[] = $item;

            $this->appendUniqueString($relationshipIds, $relationshipId);
            $this->appendUniqueString($unreferencedRelationshipIds, $relationshipId);
            if (!isset($byRelationshipId[$relationshipId])) {
                $byRelationshipId[$relationshipId] = $item;
            }
        }

        $partNames = [];
        $externalTargets = [];
        $contentTypesSeen = [];
        $issueCodes = [];
        foreach ($items as $item) {
            if (($item['relationshipType'] ?? null) === self::IMAGE_REL) {
                $this->appendUniqueString($partNames, is_string($item['partName'] ?? null) ? $item['partName'] : null);
            }
            $this->appendUniqueString($contentTypesSeen, is_string($item['contentType'] ?? null) ? $item['contentType'] : null);
            if (($item['external'] ?? false) === true) {
                $this->appendUniqueString($externalTargets, is_string($item['target'] ?? null) ? $item['target'] : null);
            }
            foreach (($item['issues'] ?? []) as $issue) {
                if (is_string($issue) && $issue !== '') {
                    $issueCodes[$issue] = true;
                }
            }
        }
        ksort($issueCodes, SORT_STRING);

        return [
            'count' => count($items),
            'relationshipCount' => count(array_filter($relationships, static fn (array $relationship): bool => $relationship['type'] === self::IMAGE_REL)),
            'referencedCount' => count(array_filter($items, static fn (array $item): bool => $item['referenced'] === true)),
            'unreferencedRelationshipCount' => count($unreferencedRelationshipIds),
            'existingCount' => count(array_filter($items, static fn (array $item): bool => $item['relationshipType'] === self::IMAGE_REL && $item['external'] === false && $item['exists'] === true)),
            'missingCount' => count(array_filter($items, static fn (array $item): bool => in_array('missing-media-part', $item['issues'], true))),
            'externalCount' => count(array_filter($items, static fn (array $item): bool => $item['relationshipType'] === self::IMAGE_REL && $item['external'] === true)),
            'unsafeExternalTargetCount' => count(array_filter($items, static fn (array $item): bool => in_array('external-target-unsafe-scheme', $item['issues'], true))),
            'unresolvedCount' => count(array_filter(
                $items,
                static fn (array $item): bool => in_array('missing-relationship-id', $item['issues'], true) || in_array('unknown-relationship', $item['issues'], true),
            )),
            'unexpectedRelationshipTypeCount' => count(array_filter($items, static fn (array $item): bool => in_array('unexpected-relationship-type', $item['issues'], true))),
            'missingContentTypeCount' => count(array_filter($items, static fn (array $item): bool => in_array('missing-media-content-type', $item['issues'], true))),
            'unexpectedContentTypeCount' => count(array_filter($items, static fn (array $item): bool => in_array('unexpected-media-content-type', $item['issues'], true))),
            'issueCount' => count(array_filter($items, static fn (array $item): bool => $item['issues'] !== [])),
            'relationshipIds' => $relationshipIds,
            'referencedRelationshipIds' => $referencedRelationshipIds,
            'unreferencedRelationshipIds' => $unreferencedRelationshipIds,
            'partNames' => $partNames,
            'externalTargets' => $externalTargets,
            'contentTypes' => $contentTypesSeen,
            'issueCodes' => array_keys($issueCodes),
            'byRelationshipId' => $byRelationshipId,
            'items' => $items,
            'byteExposurePolicy' => 'document-media-bytes-blocked',
            'reviewPolicy' => 'document-media-metadata-only',
        ];
    }

    /**
     * @param array<string, string> $parts
     * @param array{id:string, type:string, target:string, targetMode:string, resolvedTarget:string}|null $relationship
     * @param array{defaults:array<string, string>, overrides:array<string, string>} $contentTypes
     * @return array<string, mixed>
     */
    private function documentMediaRelationshipItem(
        array $parts,
        ?array $relationship,
        string $documentPart,
        string $relationshipsPart,
        array $contentTypes,
        string $relationshipId,
        int $index,
        bool $referenced,
        string $referenceKind
    ): array {
        $item = [
            'index' => $index,
            'relationshipId' => $relationshipId,
            'referenced' => $referenced,
            'referenceKind' => $referenceKind,
            'relationshipType' => null,
            'target' => null,
            'targetMode' => null,
            'resolvedTarget' => null,
            'external' => false,
            'partName' => null,
            'targetPart' => null,
            'targetQuery' => null,
            'targetFragment' => null,
            'targetReferenceSuffix' => '',
            'exists' => false,
            'byteLength' => null,
            'crc32' => null,
            'sha256' => null,
            'contentType' => '',
            'contentTypeBase' => '',
            'contentTypeHasParameters' => false,
            'contentTypeParameterCount' => 0,
            'contentTypeParameters' => [],
            'contentTypeParameterMap' => [],
            'contentTypeSource' => 'missing',
            'defaultExtension' => null,
            'overridePartName' => null,
            'externalTargetKind' => null,
            'externalTargetScheme' => null,
            'externalTargetAllowed' => null,
            'byteExposurePolicy' => 'document-media-bytes-blocked',
            'reviewPolicy' => 'document-media-metadata-only',
            'valid' => false,
            'issues' => [],
            'relationship' => null,
        ];

        if ($relationshipId === '') {
            $item['issues'][] = 'missing-relationship-id';
            return $item;
        }

        if (!is_array($relationship)) {
            $item['issues'][] = 'unknown-relationship';
            return $item;
        }

        $summary = $this->relationshipInventorySummary($parts, $relationship, $documentPart, $relationshipsPart, $contentTypes);
        $targetPart = is_string($summary['targetPart'] ?? null) ? $summary['targetPart'] : null;
        $exists = (bool) $summary['exists'];

        $item['relationshipType'] = $summary['type'];
        $item['target'] = $summary['target'];
        $item['targetMode'] = $summary['targetMode'];
        $item['resolvedTarget'] = $summary['resolvedTarget'];
        $item['external'] = (bool) $summary['external'];
        $item['partName'] = $targetPart;
        $item['targetPart'] = $targetPart;
        $item['targetQuery'] = $summary['targetQuery'];
        $item['targetFragment'] = $summary['targetFragment'];
        $item['targetReferenceSuffix'] = $summary['targetReferenceSuffix'];
        $item['exists'] = $exists;
        $item['contentType'] = $summary['contentType'];
        $item['contentTypeBase'] = $summary['contentTypeBase'];
        $item['contentTypeHasParameters'] = $summary['contentTypeHasParameters'];
        $item['contentTypeParameterCount'] = $summary['contentTypeParameterCount'];
        $item['contentTypeParameters'] = $summary['contentTypeParameters'];
        $item['contentTypeParameterMap'] = $summary['contentTypeParameterMap'];
        $item['contentTypeSource'] = $summary['contentTypeSource'];
        $item['defaultExtension'] = $summary['defaultExtension'];
        $item['overridePartName'] = $summary['overridePartName'];
        $item['relationship'] = $summary;

        if ($relationship['type'] !== self::IMAGE_REL) {
            $item['issues'][] = 'unexpected-relationship-type';
        }

        if ($item['external']) {
            $externalPolicy = $this->externalRelationshipTargetPolicy($relationship['target']);
            $item['externalTargetKind'] = $externalPolicy['kind'];
            $item['externalTargetScheme'] = $externalPolicy['scheme'];
            $item['externalTargetAllowed'] = $externalPolicy['allowed'];
            $item['issues'][] = 'external-media-target';
            $item['issues'] = array_values(array_unique(array_merge($item['issues'], $externalPolicy['issues'])));
        } elseif ($targetPart !== null) {
            if ($exists) {
                $item['byteLength'] = strlen($parts[$targetPart]);
                $item['crc32'] = sprintf('%08x', crc32($parts[$targetPart]));
                $item['sha256'] = hash('sha256', $parts[$targetPart]);
            } else {
                $item['issues'][] = 'missing-media-part';
            }
            if (($summary['contentTypeSource'] ?? '') === 'missing') {
                $item['issues'][] = 'missing-media-content-type';
            } elseif ($relationship['type'] === self::IMAGE_REL && !str_starts_with((string) $summary['contentTypeBase'], 'image/')) {
                $item['issues'][] = 'unexpected-media-content-type';
            }
        }

        $item['issues'] = array_values(array_unique($item['issues']));
        sort($item['issues'], SORT_STRING);
        $item['valid'] = $item['issues'] === [];

        return $item;
    }

    /**
     * @param array<string, string> $parts
     * @param array{defaults:array<string, string>, overrides:array<string, string>} $contentTypes
     * @param array<string, mixed> $headers
     * @param array<string, mixed> $footers
     * @return array<string, mixed>
     */
    private function readHeaderFooterMediaRelationships(
        array $parts,
        array $contentTypes,
        array $headers,
        array $footers
    ): array {
        $items = [];

        foreach (['header' => $headers['items'] ?? [], 'footer' => $footers['items'] ?? []] as $sourceType => $sourceItems) {
            if (!is_array($sourceItems)) {
                continue;
            }

            foreach ($sourceItems as $sourceItem) {
                if (!is_array($sourceItem)) {
                    continue;
                }

                $sourcePart = is_string($sourceItem['partName'] ?? null) ? $sourceItem['partName'] : null;
                $relationshipsPart = is_string($sourceItem['relationshipsPart'] ?? null) ? $sourceItem['relationshipsPart'] : null;
                if ($sourcePart === null || $sourcePart === '' || $relationshipsPart === null || $relationshipsPart === '') {
                    continue;
                }

                $relationshipReferences = $this->headerFooterMediaRelationshipReferences($parts[$sourcePart] ?? '', $sourcePart);
                foreach ($this->readRelationshipsPart($parts, $relationshipsPart) as $relationship) {
                    if ($relationship['type'] !== self::IMAGE_REL) {
                        continue;
                    }

                    $items[] = $this->headerFooterMediaRelationshipItem(
                        $parts,
                        $relationship,
                        $sourceType,
                        $sourceItem,
                        $sourcePart,
                        $relationshipsPart,
                        $contentTypes,
                        count($items),
                        $relationshipReferences[$relationship['id']] ?? [],
                    );
                }
            }
        }

        $byRelationshipKey = [];
        $byRelationshipId = [];
        $relationshipKeys = [];
        $relationshipIds = [];
        $sourceParts = [];
        $relationshipsParts = [];
        $partNames = [];
        $externalTargets = [];
        $contentTypesSeen = [];
        $referenceKinds = [];
        $issueCodes = [];
        foreach ($items as $item) {
            $relationshipKey = is_string($item['relationshipKey'] ?? null) ? $item['relationshipKey'] : '';
            $relationshipId = is_string($item['relationshipId'] ?? null) ? $item['relationshipId'] : '';
            if ($relationshipKey !== '') {
                $byRelationshipKey[$relationshipKey] = $item;
                $this->appendUniqueString($relationshipKeys, $relationshipKey);
            }
            if ($relationshipId !== '') {
                $byRelationshipId[$relationshipId] ??= [];
                $byRelationshipId[$relationshipId][] = $item;
                $this->appendUniqueString($relationshipIds, $relationshipId);
            }
            $this->appendUniqueString($sourceParts, is_string($item['sourcePart'] ?? null) ? $item['sourcePart'] : null);
            $this->appendUniqueString($relationshipsParts, is_string($item['relationshipsPart'] ?? null) ? $item['relationshipsPart'] : null);
            if (($item['relationshipType'] ?? null) === self::IMAGE_REL) {
                $this->appendUniqueString($partNames, is_string($item['partName'] ?? null) ? $item['partName'] : null);
            }
            $this->appendUniqueString($contentTypesSeen, is_string($item['contentType'] ?? null) ? $item['contentType'] : null);
            if (($item['relationshipType'] ?? null) === self::IMAGE_REL && ($item['external'] ?? false) === true) {
                $this->appendUniqueString($externalTargets, is_string($item['target'] ?? null) ? $item['target'] : null);
            }
            foreach (($item['referenceKinds'] ?? []) as $referenceKind) {
                $this->appendUniqueString($referenceKinds, is_string($referenceKind) ? $referenceKind : null);
            }
            foreach (($item['issues'] ?? []) as $issue) {
                if (is_string($issue) && $issue !== '') {
                    $issueCodes[$issue] = true;
                }
            }
        }
        ksort($issueCodes, SORT_STRING);

        return [
            'count' => count($items),
            'relationshipCount' => count(array_filter($items, static fn (array $item): bool => $item['relationshipType'] === self::IMAGE_REL)),
            'headerCount' => count(array_filter($items, static fn (array $item): bool => $item['sourceType'] === 'header')),
            'footerCount' => count(array_filter($items, static fn (array $item): bool => $item['sourceType'] === 'footer')),
            'sourcePartCount' => count($sourceParts),
            'referencedCount' => count(array_filter($items, static fn (array $item): bool => $item['referenced'] === true)),
            'orphanedCount' => count(array_filter($items, static fn (array $item): bool => $item['orphaned'] === true)),
            'drawingReferenceCount' => count(array_filter($items, static fn (array $item): bool => in_array('embed', $item['referenceKinds'], true) || in_array('link', $item['referenceKinds'], true))),
            'vmlReferenceCount' => count(array_filter($items, static fn (array $item): bool => in_array('vml', $item['referenceKinds'], true))),
            'existingCount' => count(array_filter($items, static fn (array $item): bool => $item['relationshipType'] === self::IMAGE_REL && $item['external'] === false && $item['exists'] === true)),
            'missingCount' => count(array_filter($items, static fn (array $item): bool => in_array('missing-header-footer-media-part', $item['issues'], true))),
            'externalCount' => count(array_filter($items, static fn (array $item): bool => $item['relationshipType'] === self::IMAGE_REL && $item['external'] === true)),
            'unsafeExternalTargetCount' => count(array_filter($items, static fn (array $item): bool => in_array('external-target-unsafe-scheme', $item['issues'], true))),
            'missingContentTypeCount' => count(array_filter($items, static fn (array $item): bool => in_array('missing-header-footer-media-content-type', $item['issues'], true))),
            'unexpectedContentTypeCount' => count(array_filter($items, static fn (array $item): bool => in_array('unexpected-header-footer-media-content-type', $item['issues'], true))),
            'issueCount' => count(array_filter($items, static fn (array $item): bool => $item['issues'] !== [])),
            'relationshipKeys' => $relationshipKeys,
            'relationshipIds' => $relationshipIds,
            'sourceParts' => $sourceParts,
            'relationshipsParts' => $relationshipsParts,
            'partNames' => $partNames,
            'externalTargets' => $externalTargets,
            'contentTypes' => $contentTypesSeen,
            'referenceKinds' => $referenceKinds,
            'issueCodes' => array_keys($issueCodes),
            'byRelationshipKey' => $byRelationshipKey,
            'byRelationshipId' => $byRelationshipId,
            'items' => $items,
            'byteExposurePolicy' => 'header-footer-media-bytes-blocked',
            'reviewPolicy' => 'header-footer-media-metadata-only',
        ];
    }

    /**
     * @return array<string, list<string>>
     */
    private function headerFooterMediaRelationshipReferences(string $xml, string $partName): array
    {
        $dom = $this->loadXmlForProvenance($xml, $partName);
        if (!$dom instanceof \DOMDocument) {
            return [];
        }

        $references = [];
        $xpath = $this->xpath($dom);
        foreach ($this->elements($xpath, '//a:blip') as $blip) {
            $relationshipId = $blip->getAttributeNS(self::NS_R, 'embed');
            $referenceKind = 'embed';
            if ($relationshipId === '') {
                $relationshipId = $blip->getAttributeNS(self::NS_R, 'link');
                $referenceKind = $relationshipId === '' ? '' : 'link';
            }
            if ($relationshipId === '') {
                continue;
            }

            $references[$relationshipId] ??= [];
            $this->appendUniqueString($references[$relationshipId], $referenceKind);
        }

        foreach ($this->elements($xpath, '//v:imagedata') as $imageData) {
            $relationshipId = $this->vmlImageRelationshipId($imageData);
            if ($relationshipId === '') {
                continue;
            }

            $references[$relationshipId] ??= [];
            $this->appendUniqueString($references[$relationshipId], 'vml');
        }

        return $references;
    }

    /**
     * @param array<string, string> $parts
     * @param array{id:string, type:string, target:string, targetMode:string, resolvedTarget:string} $relationship
     * @param array<string, mixed> $sourceItem
     * @param array{defaults:array<string, string>, overrides:array<string, string>} $contentTypes
     * @param list<string> $referenceKinds
     * @return array<string, mixed>
     */
    private function headerFooterMediaRelationshipItem(
        array $parts,
        array $relationship,
        string $sourceType,
        array $sourceItem,
        string $sourcePart,
        string $relationshipsPart,
        array $contentTypes,
        int $index,
        array $referenceKinds = []
    ): array {
        $relationshipId = $relationship['id'];
        $relationshipKey = $relationshipsPart . '#' . $relationshipId;
        $summary = $this->relationshipInventorySummary($parts, $relationship, $sourcePart, $relationshipsPart, $contentTypes);
        $targetPart = is_string($summary['targetPart'] ?? null) ? $summary['targetPart'] : null;
        $exists = (bool) $summary['exists'];
        $sourceReferenceTypes = is_array($sourceItem['referenceTypes'] ?? null)
            ? array_values(array_map('strval', $sourceItem['referenceTypes']))
            : [];
        $sourceIssues = is_array($sourceItem['issues'] ?? null)
            ? array_values(array_map('strval', $sourceItem['issues']))
            : [];
        $referenceKinds = array_values(array_unique(array_filter(
            array_map('strval', $referenceKinds),
            static fn (string $referenceKind): bool => $referenceKind !== '',
        )));
        $referenced = $referenceKinds !== [];

        $item = [
            'index' => $index,
            'relationshipKey' => $relationshipKey,
            'relationshipId' => $relationshipId,
            'sourceType' => $sourceType,
            'sourcePart' => $sourcePart,
            'sourcePartExists' => (bool) ($sourceItem['exists'] ?? false),
            'sourcePartValidRoot' => (bool) ($sourceItem['validRoot'] ?? false),
            'sourceRootName' => is_string($sourceItem['rootName'] ?? null) ? $sourceItem['rootName'] : null,
            'sourceRelationshipId' => is_string($sourceItem['relationshipId'] ?? null) ? $sourceItem['relationshipId'] : '',
            'sourceReferenced' => (bool) ($sourceItem['referenced'] ?? false),
            'sourceReferenceTypes' => $sourceReferenceTypes,
            'sourceIssues' => $sourceIssues,
            'referenced' => $referenced,
            'orphaned' => !$referenced,
            'referenceKind' => $referenced ? $referenceKinds[0] : 'relationship',
            'referenceKinds' => $referenceKinds,
            'relationshipsPart' => $relationshipsPart,
            'relationshipType' => $summary['type'],
            'target' => $summary['target'],
            'targetMode' => $summary['targetMode'],
            'resolvedTarget' => $summary['resolvedTarget'],
            'external' => (bool) $summary['external'],
            'partName' => $targetPart,
            'targetPart' => $targetPart,
            'targetQuery' => $summary['targetQuery'],
            'targetFragment' => $summary['targetFragment'],
            'targetReferenceSuffix' => $summary['targetReferenceSuffix'],
            'exists' => $exists,
            'byteLength' => null,
            'crc32' => null,
            'sha256' => null,
            'contentType' => $summary['contentType'],
            'contentTypeBase' => $summary['contentTypeBase'],
            'contentTypeHasParameters' => $summary['contentTypeHasParameters'],
            'contentTypeParameterCount' => $summary['contentTypeParameterCount'],
            'contentTypeParameters' => $summary['contentTypeParameters'],
            'contentTypeParameterMap' => $summary['contentTypeParameterMap'],
            'contentTypeSource' => $summary['contentTypeSource'],
            'defaultExtension' => $summary['defaultExtension'],
            'overridePartName' => $summary['overridePartName'],
            'externalTargetKind' => $summary['externalTargetKind'],
            'externalTargetScheme' => $summary['externalTargetScheme'],
            'externalTargetAllowed' => $summary['externalTargetAllowed'],
            'byteExposurePolicy' => 'header-footer-media-bytes-blocked',
            'reviewPolicy' => 'header-footer-media-metadata-only',
            'valid' => false,
            'issues' => [],
            'relationship' => $summary,
        ];

        if ($relationship['type'] !== self::IMAGE_REL) {
            $item['issues'][] = 'unexpected-relationship-type';
        }

        if ($item['external'] === true) {
            $item['issues'][] = 'external-header-footer-media-target';
            $item['issues'] = array_values(array_unique(array_merge($item['issues'], $summary['externalTargetIssues'])));
        } elseif ($targetPart !== null) {
            if ($exists) {
                $item['byteLength'] = strlen($parts[$targetPart]);
                $item['crc32'] = sprintf('%08x', crc32($parts[$targetPart]));
                $item['sha256'] = hash('sha256', $parts[$targetPart]);
            } else {
                $item['issues'][] = 'missing-header-footer-media-part';
            }

            $contentType = is_string($summary['contentType'] ?? null) ? $summary['contentType'] : '';
            if (($summary['contentTypeSource'] ?? '') === 'missing') {
                $item['issues'][] = 'missing-header-footer-media-content-type';
            } elseif ($relationship['type'] === self::IMAGE_REL && !$this->isImageContentType($contentType)) {
                $item['issues'][] = 'unexpected-header-footer-media-content-type';
            }
        }

        $item['issues'] = array_values(array_unique($item['issues']));
        sort($item['issues'], SORT_STRING);
        $item['valid'] = $item['issues'] === [];

        return $item;
    }

    /**
     * @param array<string, string> $parts
     * @param array{defaults:array<string, string>, overrides:array<string, string>} $contentTypes
     * @param array<string, mixed> $headers
     * @param array<string, mixed> $footers
     * @return array<string, mixed>
     */
    private function readHeaderFooterHyperlinkRelationships(
        array $parts,
        array $contentTypes,
        array $headers,
        array $footers
    ): array {
        $items = [];

        foreach (['header' => $headers['items'] ?? [], 'footer' => $footers['items'] ?? []] as $sourceType => $sourceItems) {
            if (!is_array($sourceItems)) {
                continue;
            }

            foreach ($sourceItems as $sourceItem) {
                if (!is_array($sourceItem)) {
                    continue;
                }

                $sourcePart = is_string($sourceItem['partName'] ?? null) ? $sourceItem['partName'] : null;
                $relationshipsPart = is_string($sourceItem['relationshipsPart'] ?? null) ? $sourceItem['relationshipsPart'] : null;
                if ($sourcePart === null || $sourcePart === '' || $relationshipsPart === null || $relationshipsPart === '') {
                    continue;
                }

                $referencedRelationshipIds = $this->headerFooterHyperlinkRelationshipIds($parts[$sourcePart] ?? '', $sourcePart);
                foreach ($this->readRelationshipsPart($parts, $relationshipsPart) as $relationship) {
                    if ($relationship['type'] !== self::HYPERLINK_REL) {
                        continue;
                    }

                    $items[] = $this->headerFooterHyperlinkRelationshipItem(
                        $parts,
                        $relationship,
                        $sourceType,
                        $sourceItem,
                        $sourcePart,
                        $relationshipsPart,
                        $contentTypes,
                        count($items),
                        in_array($relationship['id'], $referencedRelationshipIds, true),
                    );
                }
            }
        }

        $byRelationshipKey = [];
        $byRelationshipId = [];
        $relationshipKeys = [];
        $relationshipIds = [];
        $sourceParts = [];
        $relationshipsParts = [];
        $partNames = [];
        $externalTargets = [];
        $contentTypesSeen = [];
        $issueCodes = [];
        foreach ($items as $item) {
            $relationshipKey = is_string($item['relationshipKey'] ?? null) ? $item['relationshipKey'] : '';
            $relationshipId = is_string($item['relationshipId'] ?? null) ? $item['relationshipId'] : '';
            if ($relationshipKey !== '') {
                $byRelationshipKey[$relationshipKey] = $item;
                $this->appendUniqueString($relationshipKeys, $relationshipKey);
            }
            if ($relationshipId !== '') {
                $byRelationshipId[$relationshipId] ??= [];
                $byRelationshipId[$relationshipId][] = $item;
                $this->appendUniqueString($relationshipIds, $relationshipId);
            }
            $this->appendUniqueString($sourceParts, is_string($item['sourcePart'] ?? null) ? $item['sourcePart'] : null);
            $this->appendUniqueString($relationshipsParts, is_string($item['relationshipsPart'] ?? null) ? $item['relationshipsPart'] : null);
            if (($item['external'] ?? false) !== true) {
                $this->appendUniqueString($partNames, is_string($item['targetPart'] ?? null) ? $item['targetPart'] : null);
            }
            $this->appendUniqueString($contentTypesSeen, is_string($item['contentType'] ?? null) ? $item['contentType'] : null);
            if (($item['external'] ?? false) === true) {
                $this->appendUniqueString($externalTargets, is_string($item['target'] ?? null) ? $item['target'] : null);
            }
            foreach (($item['issues'] ?? []) as $issue) {
                if (is_string($issue) && $issue !== '') {
                    $issueCodes[$issue] = true;
                }
            }
        }
        ksort($issueCodes, SORT_STRING);

        return [
            'count' => count($items),
            'relationshipCount' => count($items),
            'headerCount' => count(array_filter($items, static fn (array $item): bool => $item['sourceType'] === 'header')),
            'footerCount' => count(array_filter($items, static fn (array $item): bool => $item['sourceType'] === 'footer')),
            'sourcePartCount' => count($sourceParts),
            'referencedCount' => count(array_filter($items, static fn (array $item): bool => $item['referenced'] === true)),
            'orphanedCount' => count(array_filter($items, static fn (array $item): bool => $item['orphaned'] === true)),
            'internalCount' => count(array_filter($items, static fn (array $item): bool => $item['external'] === false)),
            'existingCount' => count(array_filter($items, static fn (array $item): bool => $item['external'] === false && $item['exists'] === true)),
            'missingCount' => count(array_filter($items, static fn (array $item): bool => in_array('missing-header-footer-hyperlink-target', $item['issues'], true))),
            'externalCount' => count(array_filter($items, static fn (array $item): bool => $item['external'] === true)),
            'unsafeExternalTargetCount' => count(array_filter($items, static fn (array $item): bool => in_array('external-target-unsafe-scheme', $item['issues'], true))),
            'missingContentTypeCount' => count(array_filter($items, static fn (array $item): bool => in_array('missing-header-footer-hyperlink-content-type', $item['issues'], true))),
            'issueCount' => count(array_filter($items, static fn (array $item): bool => $item['issues'] !== [])),
            'relationshipKeys' => $relationshipKeys,
            'relationshipIds' => $relationshipIds,
            'sourceParts' => $sourceParts,
            'relationshipsParts' => $relationshipsParts,
            'partNames' => $partNames,
            'externalTargets' => $externalTargets,
            'contentTypes' => $contentTypesSeen,
            'issueCodes' => array_keys($issueCodes),
            'byRelationshipKey' => $byRelationshipKey,
            'byRelationshipId' => $byRelationshipId,
            'items' => $items,
            'byteExposurePolicy' => 'header-footer-hyperlink-target-bytes-blocked',
            'reviewPolicy' => 'header-footer-hyperlink-metadata-only',
        ];
    }

    /**
     * @return list<string>
     */
    private function headerFooterHyperlinkRelationshipIds(string $xml, string $partName): array
    {
        $dom = $this->loadXmlForProvenance($xml, $partName);
        if (!$dom instanceof \DOMDocument) {
            return [];
        }

        $ids = [];
        $xpath = $this->xpath($dom);
        foreach ($this->elements($xpath, '//w:hyperlink[@r:id]') as $hyperlink) {
            $this->appendUniqueString($ids, $hyperlink->getAttributeNS(self::NS_R, 'id'));
        }

        return $ids;
    }

    /**
     * @param array<string, string> $parts
     * @param array{id:string, type:string, target:string, targetMode:string, resolvedTarget:string} $relationship
     * @param array<string, mixed> $sourceItem
     * @param array{defaults:array<string, string>, overrides:array<string, string>} $contentTypes
     * @return array<string, mixed>
     */
    private function headerFooterHyperlinkRelationshipItem(
        array $parts,
        array $relationship,
        string $sourceType,
        array $sourceItem,
        string $sourcePart,
        string $relationshipsPart,
        array $contentTypes,
        int $index,
        bool $referenced
    ): array {
        $relationshipId = $relationship['id'];
        $relationshipKey = $relationshipsPart . '#' . $relationshipId;
        $summary = $this->relationshipInventorySummary($parts, $relationship, $sourcePart, $relationshipsPart, $contentTypes);
        $targetPart = is_string($summary['targetPart'] ?? null) ? $summary['targetPart'] : null;
        $exists = (bool) $summary['exists'];
        $external = (bool) $summary['external'];
        $sourceReferenceTypes = is_array($sourceItem['referenceTypes'] ?? null)
            ? array_values(array_map('strval', $sourceItem['referenceTypes']))
            : [];
        $sourceIssues = is_array($sourceItem['issues'] ?? null)
            ? array_values(array_map('strval', $sourceItem['issues']))
            : [];

        $item = [
            'index' => $index,
            'relationshipKey' => $relationshipKey,
            'relationshipId' => $relationshipId,
            'sourceType' => $sourceType,
            'sourcePart' => $sourcePart,
            'sourcePartExists' => (bool) ($sourceItem['exists'] ?? false),
            'sourcePartValidRoot' => (bool) ($sourceItem['validRoot'] ?? false),
            'sourceRootName' => is_string($sourceItem['rootName'] ?? null) ? $sourceItem['rootName'] : null,
            'sourceRelationshipId' => is_string($sourceItem['relationshipId'] ?? null) ? $sourceItem['relationshipId'] : '',
            'sourceReferenced' => (bool) ($sourceItem['referenced'] ?? false),
            'sourceReferenceTypes' => $sourceReferenceTypes,
            'sourceIssues' => $sourceIssues,
            'relationshipsPart' => $relationshipsPart,
            'relationshipType' => $summary['type'],
            'target' => $summary['target'],
            'targetMode' => $summary['targetMode'],
            'resolvedTarget' => $summary['resolvedTarget'],
            'external' => $external,
            'targetPart' => $targetPart,
            'targetQuery' => $summary['targetQuery'],
            'targetFragment' => $summary['targetFragment'],
            'targetReferenceSuffix' => $summary['targetReferenceSuffix'],
            'exists' => $exists,
            'byteLength' => null,
            'crc32' => null,
            'sha256' => null,
            'contentType' => $summary['contentType'],
            'contentTypeBase' => $summary['contentTypeBase'],
            'contentTypeHasParameters' => $summary['contentTypeHasParameters'],
            'contentTypeParameterCount' => $summary['contentTypeParameterCount'],
            'contentTypeParameters' => $summary['contentTypeParameters'],
            'contentTypeParameterMap' => $summary['contentTypeParameterMap'],
            'contentTypeSource' => $summary['contentTypeSource'],
            'defaultExtension' => $summary['defaultExtension'],
            'overridePartName' => $summary['overridePartName'],
            'externalTargetKind' => $summary['externalTargetKind'],
            'externalTargetScheme' => $summary['externalTargetScheme'],
            'externalTargetAllowed' => $summary['externalTargetAllowed'],
            'referenced' => $referenced,
            'orphaned' => !$referenced,
            'byteExposurePolicy' => 'header-footer-hyperlink-target-bytes-blocked',
            'reviewPolicy' => 'header-footer-hyperlink-metadata-only',
            'valid' => false,
            'issues' => [],
            'relationship' => $summary,
        ];

        if ($relationship['type'] !== self::HYPERLINK_REL) {
            $item['issues'][] = 'unexpected-relationship-type';
        }

        if ($external) {
            $item['issues'] = array_values(array_unique(array_merge($item['issues'], $summary['externalTargetIssues'])));
        } elseif ($targetPart !== null) {
            if ($exists) {
                $item['byteLength'] = strlen($parts[$targetPart]);
                $item['crc32'] = sprintf('%08x', crc32($parts[$targetPart]));
                $item['sha256'] = hash('sha256', $parts[$targetPart]);
            } else {
                $item['issues'][] = 'missing-header-footer-hyperlink-target';
            }

            if (($summary['contentTypeSource'] ?? '') === 'missing') {
                $item['issues'][] = 'missing-header-footer-hyperlink-content-type';
            }
        }

        $item['issues'] = array_values(array_unique($item['issues']));
        sort($item['issues'], SORT_STRING);
        $item['valid'] = $item['issues'] === [];

        return $item;
    }

    /**
     * @param array<string, string> $parts
     * @param array{defaults:array<string, string>, overrides:array<string, string>} $contentTypes
     * @param list<array{sourceKind:string, summary:array<string, mixed>}> $sources
     * @return array<string, mixed>
     */
    private function readNoteCommentMediaRelationships(array $parts, array $contentTypes, array $sources): array
    {
        $items = [];
        $byRelationshipKey = [];
        $relationshipIds = [];
        $relationshipKeys = [];
        $partNames = [];
        $externalTargets = [];
        $contentTypesSeen = [];
        $issueCodes = [];
        $sourceCounts = ['footnote' => 0, 'endnote' => 0, 'comment' => 0];

        foreach ($sources as $source) {
            $sourceKind = $source['sourceKind'];
            $relationships = is_array($source['summary']['relationships'] ?? null)
                ? $source['summary']['relationships']
                : [];

            foreach ($relationships as $relationship) {
                if (!is_array($relationship) || ($relationship['type'] ?? null) !== self::IMAGE_REL) {
                    continue;
                }

                $item = $this->noteCommentMediaRelationshipItem(
                    $parts,
                    $contentTypes,
                    $sourceKind,
                    $relationship,
                    count($items),
                );
                $items[] = $item;
                $sourceCounts[$sourceKind] = ($sourceCounts[$sourceKind] ?? 0) + 1;

                $relationshipId = is_string($item['relationshipId'] ?? null) ? $item['relationshipId'] : '';
                $relationshipKey = is_string($item['relationshipKey'] ?? null) ? $item['relationshipKey'] : '';
                $this->appendUniqueString($relationshipIds, $relationshipId);
                $this->appendUniqueString($relationshipKeys, $relationshipKey);
                if ($relationshipKey !== '') {
                    $byRelationshipKey[$relationshipKey] = $item;
                }
                if (($item['external'] ?? false) === true) {
                    $this->appendUniqueString($externalTargets, is_string($item['target'] ?? null) ? $item['target'] : null);
                } else {
                    $this->appendUniqueString($partNames, is_string($item['partName'] ?? null) ? $item['partName'] : null);
                }
                $this->appendUniqueString($contentTypesSeen, is_string($item['contentType'] ?? null) ? $item['contentType'] : null);
                foreach (($item['issues'] ?? []) as $issue) {
                    if (is_string($issue) && $issue !== '') {
                        $issueCodes[$issue] = true;
                    }
                }
            }
        }

        sort($relationshipIds, SORT_STRING);
        sort($relationshipKeys, SORT_STRING);
        ksort($issueCodes, SORT_STRING);

        return [
            'count' => count($items),
            'relationshipCount' => count($items),
            'footnoteCount' => $sourceCounts['footnote'] ?? 0,
            'endnoteCount' => $sourceCounts['endnote'] ?? 0,
            'commentCount' => $sourceCounts['comment'] ?? 0,
            'referencedCount' => count(array_filter($items, static fn (array $item): bool => ($item['referenced'] ?? false) === true)),
            'orphanedCount' => count(array_filter($items, static fn (array $item): bool => ($item['orphaned'] ?? false) === true)),
            'existingCount' => count(array_filter($items, static fn (array $item): bool => ($item['external'] ?? false) === false && ($item['exists'] ?? false) === true)),
            'missingCount' => count(array_filter($items, static fn (array $item): bool => in_array('missing-note-comment-media-part', $item['issues'] ?? [], true))),
            'externalCount' => count(array_filter($items, static fn (array $item): bool => ($item['external'] ?? false) === true)),
            'unsafeExternalTargetCount' => count(array_filter($items, static fn (array $item): bool => in_array('external-target-unsafe-scheme', $item['issues'] ?? [], true))),
            'missingContentTypeCount' => count(array_filter($items, static fn (array $item): bool => in_array('missing-note-comment-media-content-type', $item['issues'] ?? [], true))),
            'unexpectedContentTypeCount' => count(array_filter($items, static fn (array $item): bool => in_array('unexpected-note-comment-media-content-type', $item['issues'] ?? [], true))),
            'issueCount' => count(array_filter($items, static fn (array $item): bool => ($item['issues'] ?? []) !== [])),
            'relationshipIds' => $relationshipIds,
            'relationshipKeys' => $relationshipKeys,
            'partNames' => $partNames,
            'externalTargets' => $externalTargets,
            'contentTypes' => $contentTypesSeen,
            'issueCodes' => array_keys($issueCodes),
            'byRelationshipKey' => $byRelationshipKey,
            'items' => $items,
            'byteExposurePolicy' => 'note-comment-media-bytes-blocked',
            'reviewPolicy' => 'note-comment-media-metadata-only',
        ];
    }

    /**
     * @param array<string, string> $parts
     * @param array{defaults:array<string, string>, overrides:array<string, string>} $contentTypes
     * @param array<string, mixed> $relationship
     * @return array<string, mixed>
     */
    private function noteCommentMediaRelationshipItem(
        array $parts,
        array $contentTypes,
        string $sourceKind,
        array $relationship,
        int $index
    ): array {
        $targetPart = is_string($relationship['targetPart'] ?? null) ? $relationship['targetPart'] : null;
        $exists = $targetPart !== null && isset($parts[$targetPart]);
        $external = ($relationship['external'] ?? false) === true;
        $contentTypeResolution = $targetPart === null
            ? $this->missingContentTypeResolution(null)
            : $this->contentTypeResolutionForPart($targetPart, $contentTypes);
        $issues = [];

        if ($external) {
            $issues[] = 'external-note-comment-media-target';
            foreach (($relationship['externalTargetIssues'] ?? []) as $issue) {
                if (is_string($issue) && $issue !== '') {
                    $issues[] = $issue;
                }
            }
        } else {
            if (!$exists) {
                $issues[] = 'missing-note-comment-media-part';
            }
            if (($contentTypeResolution['contentTypeSource'] ?? '') === 'missing') {
                $issues[] = 'missing-note-comment-media-content-type';
            } elseif (!str_starts_with((string) ($contentTypeResolution['contentTypeBase'] ?? ''), 'image/')) {
                $issues[] = 'unexpected-note-comment-media-content-type';
            }
        }

        $issues = array_values(array_unique($issues));
        sort($issues, SORT_STRING);

        $relationshipId = is_string($relationship['id'] ?? null) ? $relationship['id'] : '';
        $relationshipsPart = is_string($relationship['relationshipsPart'] ?? null) ? $relationship['relationshipsPart'] : '';

        return [
            'index' => $index,
            'sourceKind' => $sourceKind,
            'sourcePart' => is_string($relationship['sourcePart'] ?? null) ? $relationship['sourcePart'] : '',
            'relationshipsPart' => $relationshipsPart,
            'relationshipId' => $relationshipId,
            'relationshipKey' => $relationshipsPart . '#' . $relationshipId,
            'relationshipType' => is_string($relationship['type'] ?? null) ? $relationship['type'] : '',
            'target' => is_string($relationship['target'] ?? null) ? $relationship['target'] : '',
            'targetMode' => is_string($relationship['targetMode'] ?? null) ? $relationship['targetMode'] : '',
            'resolvedTarget' => is_string($relationship['resolvedTarget'] ?? null) ? $relationship['resolvedTarget'] : '',
            'external' => $external,
            'partName' => $targetPart,
            'targetPart' => $targetPart,
            'targetQuery' => $relationship['targetQuery'] ?? null,
            'targetFragment' => $relationship['targetFragment'] ?? null,
            'targetReferenceSuffix' => is_string($relationship['targetReferenceSuffix'] ?? null) ? $relationship['targetReferenceSuffix'] : '',
            'exists' => $exists,
            'byteLength' => $exists ? strlen($parts[$targetPart]) : null,
            'crc32' => $exists ? sprintf('%08x', crc32($parts[$targetPart])) : null,
            'sha256' => $exists ? hash('sha256', $parts[$targetPart]) : null,
            'contentType' => $contentTypeResolution['contentType'],
            'contentTypeBase' => $contentTypeResolution['contentTypeBase'],
            'contentTypeHasParameters' => $contentTypeResolution['contentTypeHasParameters'],
            'contentTypeParameterCount' => $contentTypeResolution['contentTypeParameterCount'],
            'contentTypeParameters' => $contentTypeResolution['contentTypeParameters'],
            'contentTypeParameterMap' => $contentTypeResolution['contentTypeParameterMap'],
            'contentTypeSource' => $contentTypeResolution['contentTypeSource'],
            'defaultExtension' => $contentTypeResolution['defaultExtension'],
            'overridePartName' => $contentTypeResolution['overridePartName'],
            'externalTargetKind' => $relationship['externalTargetKind'] ?? null,
            'externalTargetScheme' => $relationship['externalTargetScheme'] ?? null,
            'externalTargetAllowed' => $relationship['externalTargetAllowed'] ?? null,
            'referenced' => ($relationship['referenced'] ?? false) === true,
            'orphaned' => ($relationship['orphaned'] ?? false) === true,
            'referencedItemIds' => is_array($relationship['referencedItemIds'] ?? null) ? $relationship['referencedItemIds'] : [],
            'referencedItemCount' => (int) ($relationship['referencedItemCount'] ?? 0),
            'byteExposurePolicy' => 'note-comment-media-bytes-blocked',
            'reviewPolicy' => 'note-comment-media-metadata-only',
            'valid' => $issues === [],
            'issues' => $issues,
            'relationship' => $relationship,
        ];
    }

    /**
     * @param array<string, string> $parts
     * @param array{defaults:array<string, string>, overrides:array<string, string>} $contentTypes
     * @param list<array{sourceKind:string, summary:array<string, mixed>}> $sources
     * @return array<string, mixed>
     */
    private function readNoteCommentHyperlinkRelationships(array $parts, array $contentTypes, array $sources): array
    {
        $items = [];
        $byRelationshipKey = [];
        $relationshipIds = [];
        $relationshipKeys = [];
        $partNames = [];
        $externalTargets = [];
        $contentTypesSeen = [];
        $issueCodes = [];
        $sourceCounts = ['footnote' => 0, 'endnote' => 0, 'comment' => 0];

        foreach ($sources as $source) {
            $sourceKind = $source['sourceKind'];
            $relationships = is_array($source['summary']['relationships'] ?? null)
                ? $source['summary']['relationships']
                : [];

            foreach ($relationships as $relationship) {
                if (!is_array($relationship) || ($relationship['type'] ?? null) !== self::HYPERLINK_REL) {
                    continue;
                }

                $item = $this->noteCommentHyperlinkRelationshipItem(
                    $parts,
                    $contentTypes,
                    $sourceKind,
                    $relationship,
                    count($items),
                );
                $items[] = $item;
                $sourceCounts[$sourceKind] = ($sourceCounts[$sourceKind] ?? 0) + 1;

                $relationshipId = is_string($item['relationshipId'] ?? null) ? $item['relationshipId'] : '';
                $relationshipKey = is_string($item['relationshipKey'] ?? null) ? $item['relationshipKey'] : '';
                $this->appendUniqueString($relationshipIds, $relationshipId);
                $this->appendUniqueString($relationshipKeys, $relationshipKey);
                if ($relationshipKey !== '') {
                    $byRelationshipKey[$relationshipKey] = $item;
                }
                if (($item['external'] ?? false) === true) {
                    $this->appendUniqueString($externalTargets, is_string($item['target'] ?? null) ? $item['target'] : null);
                } else {
                    $this->appendUniqueString($partNames, is_string($item['partName'] ?? null) ? $item['partName'] : null);
                }
                $this->appendUniqueString($contentTypesSeen, is_string($item['contentType'] ?? null) ? $item['contentType'] : null);
                foreach (($item['issues'] ?? []) as $issue) {
                    if (is_string($issue) && $issue !== '') {
                        $issueCodes[$issue] = true;
                    }
                }
            }
        }

        sort($relationshipIds, SORT_STRING);
        sort($relationshipKeys, SORT_STRING);
        ksort($issueCodes, SORT_STRING);

        return [
            'count' => count($items),
            'relationshipCount' => count($items),
            'footnoteCount' => $sourceCounts['footnote'] ?? 0,
            'endnoteCount' => $sourceCounts['endnote'] ?? 0,
            'commentCount' => $sourceCounts['comment'] ?? 0,
            'referencedCount' => count(array_filter($items, static fn (array $item): bool => ($item['referenced'] ?? false) === true)),
            'orphanedCount' => count(array_filter($items, static fn (array $item): bool => ($item['orphaned'] ?? false) === true)),
            'internalCount' => count(array_filter($items, static fn (array $item): bool => ($item['external'] ?? false) === false)),
            'existingCount' => count(array_filter($items, static fn (array $item): bool => ($item['external'] ?? false) === false && ($item['exists'] ?? false) === true)),
            'missingCount' => count(array_filter($items, static fn (array $item): bool => in_array('missing-note-comment-hyperlink-target', $item['issues'] ?? [], true))),
            'externalCount' => count(array_filter($items, static fn (array $item): bool => ($item['external'] ?? false) === true)),
            'unsafeExternalTargetCount' => count(array_filter($items, static fn (array $item): bool => in_array('external-target-unsafe-scheme', $item['issues'] ?? [], true))),
            'missingContentTypeCount' => count(array_filter($items, static fn (array $item): bool => in_array('missing-note-comment-hyperlink-content-type', $item['issues'] ?? [], true))),
            'issueCount' => count(array_filter($items, static fn (array $item): bool => ($item['issues'] ?? []) !== [])),
            'relationshipIds' => $relationshipIds,
            'relationshipKeys' => $relationshipKeys,
            'partNames' => $partNames,
            'externalTargets' => $externalTargets,
            'contentTypes' => $contentTypesSeen,
            'issueCodes' => array_keys($issueCodes),
            'byRelationshipKey' => $byRelationshipKey,
            'items' => $items,
            'byteExposurePolicy' => 'note-comment-hyperlink-bytes-blocked',
            'reviewPolicy' => 'note-comment-hyperlink-metadata-only',
        ];
    }

    /**
     * @param array<string, string> $parts
     * @param array{defaults:array<string, string>, overrides:array<string, string>} $contentTypes
     * @param array<string, mixed> $relationship
     * @return array<string, mixed>
     */
    private function noteCommentHyperlinkRelationshipItem(
        array $parts,
        array $contentTypes,
        string $sourceKind,
        array $relationship,
        int $index
    ): array {
        $targetPart = is_string($relationship['targetPart'] ?? null) ? $relationship['targetPart'] : null;
        $exists = $targetPart !== null && isset($parts[$targetPart]);
        $external = ($relationship['external'] ?? false) === true;
        $contentTypeResolution = $targetPart === null
            ? $this->missingContentTypeResolution(null)
            : $this->contentTypeResolutionForPart($targetPart, $contentTypes);
        $issues = [];

        if ($external) {
            foreach (($relationship['externalTargetIssues'] ?? []) as $issue) {
                if (is_string($issue) && $issue !== '') {
                    $issues[] = $issue;
                }
            }
        } else {
            if (!$exists) {
                $issues[] = 'missing-note-comment-hyperlink-target';
            }
            if (($contentTypeResolution['contentTypeSource'] ?? '') === 'missing') {
                $issues[] = 'missing-note-comment-hyperlink-content-type';
            }
        }

        $issues = array_values(array_unique($issues));
        sort($issues, SORT_STRING);

        $relationshipId = is_string($relationship['id'] ?? null) ? $relationship['id'] : '';
        $relationshipsPart = is_string($relationship['relationshipsPart'] ?? null) ? $relationship['relationshipsPart'] : '';

        return [
            'index' => $index,
            'sourceKind' => $sourceKind,
            'sourcePart' => is_string($relationship['sourcePart'] ?? null) ? $relationship['sourcePart'] : '',
            'relationshipsPart' => $relationshipsPart,
            'relationshipId' => $relationshipId,
            'relationshipKey' => $relationshipsPart . '#' . $relationshipId,
            'relationshipType' => is_string($relationship['type'] ?? null) ? $relationship['type'] : '',
            'target' => is_string($relationship['target'] ?? null) ? $relationship['target'] : '',
            'targetMode' => is_string($relationship['targetMode'] ?? null) ? $relationship['targetMode'] : '',
            'resolvedTarget' => is_string($relationship['resolvedTarget'] ?? null) ? $relationship['resolvedTarget'] : '',
            'external' => $external,
            'partName' => $targetPart,
            'targetPart' => $targetPart,
            'targetQuery' => $relationship['targetQuery'] ?? null,
            'targetFragment' => $relationship['targetFragment'] ?? null,
            'targetReferenceSuffix' => is_string($relationship['targetReferenceSuffix'] ?? null) ? $relationship['targetReferenceSuffix'] : '',
            'targetParentTraversalCount' => (int) ($relationship['targetParentTraversalCount'] ?? 0),
            'targetHasParentTraversal' => ($relationship['targetHasParentTraversal'] ?? false) === true,
            'targetStartsAtPackageRoot' => ($relationship['targetStartsAtPackageRoot'] ?? false) === true,
            'sameSourcePart' => ($relationship['sameSourcePart'] ?? false) === true,
            'exists' => $exists,
            'byteLength' => $exists ? strlen($parts[$targetPart]) : null,
            'crc32' => $exists ? sprintf('%08x', crc32($parts[$targetPart])) : null,
            'sha256' => $exists ? hash('sha256', $parts[$targetPart]) : null,
            'contentType' => $contentTypeResolution['contentType'],
            'contentTypeBase' => $contentTypeResolution['contentTypeBase'],
            'contentTypeHasParameters' => $contentTypeResolution['contentTypeHasParameters'],
            'contentTypeParameterCount' => $contentTypeResolution['contentTypeParameterCount'],
            'contentTypeParameters' => $contentTypeResolution['contentTypeParameters'],
            'contentTypeParameterMap' => $contentTypeResolution['contentTypeParameterMap'],
            'contentTypeSource' => $contentTypeResolution['contentTypeSource'],
            'defaultExtension' => $contentTypeResolution['defaultExtension'],
            'overridePartName' => $contentTypeResolution['overridePartName'],
            'externalTargetKind' => $relationship['externalTargetKind'] ?? null,
            'externalTargetScheme' => $relationship['externalTargetScheme'] ?? null,
            'externalTargetAllowed' => $relationship['externalTargetAllowed'] ?? null,
            'referenced' => ($relationship['referenced'] ?? false) === true,
            'orphaned' => ($relationship['orphaned'] ?? false) === true,
            'referencedItemIds' => is_array($relationship['referencedItemIds'] ?? null) ? $relationship['referencedItemIds'] : [],
            'referencedItemCount' => (int) ($relationship['referencedItemCount'] ?? 0),
            'byteExposurePolicy' => 'note-comment-hyperlink-bytes-blocked',
            'reviewPolicy' => 'note-comment-hyperlink-metadata-only',
            'valid' => $issues === [],
            'issues' => $issues,
            'relationship' => $relationship,
        ];
    }

    /**
     * @param array<string, string> $parts
     * @param array<string, array{id:string, type:string, target:string, targetMode:string, resolvedTarget:string}> $relationships
     * @param array{defaults:array<string, string>, overrides:array<string, string>} $contentTypes
     * @return array<string, mixed>
     */
    private function readThemeMediaRelationships(
        array $parts,
        string $xml,
        string $themePart,
        bool $themeExists,
        string $relationshipsPart,
        array $relationships,
        array $contentTypes
    ): array {
        $items = [];
        $byRelationshipId = [];
        $relationshipIds = [];
        $referencedRelationshipIds = [];
        $referencedImageRelationshipIds = [];

        if ($xml !== '') {
            $dom = $this->loadXmlForProvenance($xml, $themePart);
            if ($dom instanceof \DOMDocument) {
                $xpath = $this->xpath($dom);
                foreach ($this->elements($xpath, '//a:blip') as $blip) {
                    $relationshipId = $blip->getAttributeNS(self::NS_R, 'embed');
                    $referenceKind = 'embed';
                    if ($relationshipId === '') {
                        $relationshipId = $blip->getAttributeNS(self::NS_R, 'link');
                        $referenceKind = $relationshipId === '' ? 'missing' : 'link';
                    }

                    $item = $this->themeMediaRelationshipItem(
                        $parts,
                        $relationships[$relationshipId] ?? null,
                        $themePart,
                        $themeExists,
                        $relationshipsPart,
                        $contentTypes,
                        $relationshipId,
                        count($items),
                        true,
                        $referenceKind,
                    );
                    $items[] = $item;

                    $this->appendUniqueString($relationshipIds, $relationshipId);
                    $this->appendUniqueString($referencedRelationshipIds, $relationshipId);
                    if ($item['relationshipType'] === self::IMAGE_REL) {
                        $this->appendUniqueString($referencedImageRelationshipIds, $relationshipId);
                    }
                    if ($relationshipId !== '' && !isset($byRelationshipId[$relationshipId])) {
                        $byRelationshipId[$relationshipId] = $item;
                    }
                }
            }
        }

        $unreferencedRelationshipIds = [];
        foreach ($relationships as $relationship) {
            if ($relationship['type'] !== self::IMAGE_REL) {
                continue;
            }

            $relationshipId = $relationship['id'];
            if (in_array($relationshipId, $referencedImageRelationshipIds, true)) {
                continue;
            }

            $item = $this->themeMediaRelationshipItem(
                $parts,
                $relationship,
                $themePart,
                $themeExists,
                $relationshipsPart,
                $contentTypes,
                $relationshipId,
                count($items),
                false,
                'relationship',
            );
            $items[] = $item;

            $this->appendUniqueString($relationshipIds, $relationshipId);
            $this->appendUniqueString($unreferencedRelationshipIds, $relationshipId);
            if (!isset($byRelationshipId[$relationshipId])) {
                $byRelationshipId[$relationshipId] = $item;
            }
        }

        $partNames = [];
        $externalTargets = [];
        $contentTypesSeen = [];
        $issueCodes = [];
        foreach ($items as $item) {
            if (($item['relationshipType'] ?? null) === self::IMAGE_REL) {
                $this->appendUniqueString($partNames, is_string($item['partName'] ?? null) ? $item['partName'] : null);
            }
            $this->appendUniqueString($contentTypesSeen, is_string($item['contentType'] ?? null) ? $item['contentType'] : null);
            if (($item['relationshipType'] ?? null) === self::IMAGE_REL && ($item['external'] ?? false) === true) {
                $this->appendUniqueString($externalTargets, is_string($item['target'] ?? null) ? $item['target'] : null);
            }
            foreach (($item['issues'] ?? []) as $issue) {
                if (is_string($issue) && $issue !== '') {
                    $issueCodes[$issue] = true;
                }
            }
        }
        ksort($issueCodes, SORT_STRING);

        return [
            'count' => count($items),
            'relationshipCount' => count(array_filter($relationships, static fn (array $relationship): bool => $relationship['type'] === self::IMAGE_REL)),
            'referencedCount' => count(array_filter($items, static fn (array $item): bool => $item['referenced'] === true)),
            'unreferencedRelationshipCount' => count($unreferencedRelationshipIds),
            'existingCount' => count(array_filter($items, static fn (array $item): bool => $item['relationshipType'] === self::IMAGE_REL && $item['external'] === false && $item['exists'] === true)),
            'missingCount' => count(array_filter($items, static fn (array $item): bool => in_array('missing-theme-media-part', $item['issues'], true))),
            'externalCount' => count(array_filter($items, static fn (array $item): bool => $item['relationshipType'] === self::IMAGE_REL && $item['external'] === true)),
            'unsafeExternalTargetCount' => count(array_filter($items, static fn (array $item): bool => in_array('external-target-unsafe-scheme', $item['issues'], true))),
            'unresolvedCount' => count(array_filter(
                $items,
                static fn (array $item): bool => in_array('missing-relationship-id', $item['issues'], true) || in_array('unknown-relationship', $item['issues'], true),
            )),
            'unexpectedRelationshipTypeCount' => count(array_filter($items, static fn (array $item): bool => in_array('unexpected-relationship-type', $item['issues'], true))),
            'missingContentTypeCount' => count(array_filter($items, static fn (array $item): bool => in_array('missing-theme-media-content-type', $item['issues'], true))),
            'unexpectedContentTypeCount' => count(array_filter($items, static fn (array $item): bool => in_array('unexpected-theme-media-content-type', $item['issues'], true))),
            'relationshipIds' => $relationshipIds,
            'referencedRelationshipIds' => $referencedRelationshipIds,
            'unreferencedRelationshipIds' => $unreferencedRelationshipIds,
            'partNames' => $partNames,
            'externalTargets' => $externalTargets,
            'contentTypes' => $contentTypesSeen,
            'issueCount' => count(array_filter($items, static fn (array $item): bool => $item['issues'] !== [])),
            'issueCodes' => array_keys($issueCodes),
            'byRelationshipId' => $byRelationshipId,
            'items' => $items,
            'byteExposurePolicy' => 'theme-media-bytes-blocked',
            'reviewPolicy' => 'theme-media-metadata-only',
        ];
    }

    /**
     * @param array<string, string> $parts
     * @param array{id:string, type:string, target:string, targetMode:string, resolvedTarget:string}|null $relationship
     * @param array{defaults:array<string, string>, overrides:array<string, string>} $contentTypes
     * @return array<string, mixed>
     */
    private function themeMediaRelationshipItem(
        array $parts,
        ?array $relationship,
        string $themePart,
        bool $themeExists,
        string $relationshipsPart,
        array $contentTypes,
        string $relationshipId,
        int $index,
        bool $referenced,
        string $referenceKind
    ): array {
        $item = [
            'index' => $index,
            'relationshipId' => $relationshipId,
            'sourcePart' => $themePart,
            'sourcePartExists' => $themeExists,
            'relationshipsPart' => $relationshipsPart,
            'referenced' => $referenced,
            'referenceKind' => $referenceKind,
            'relationshipType' => null,
            'target' => null,
            'targetMode' => null,
            'resolvedTarget' => null,
            'external' => false,
            'partName' => null,
            'targetPart' => null,
            'targetQuery' => null,
            'targetFragment' => null,
            'targetReferenceSuffix' => '',
            'exists' => false,
            'byteLength' => null,
            'crc32' => null,
            'sha256' => null,
            'contentType' => '',
            'contentTypeBase' => '',
            'contentTypeHasParameters' => false,
            'contentTypeParameterCount' => 0,
            'contentTypeParameters' => [],
            'contentTypeParameterMap' => [],
            'contentTypeSource' => 'missing',
            'defaultExtension' => null,
            'overridePartName' => null,
            'externalTargetKind' => null,
            'externalTargetScheme' => null,
            'externalTargetAllowed' => null,
            'byteExposurePolicy' => 'theme-media-bytes-blocked',
            'reviewPolicy' => 'theme-media-metadata-only',
            'valid' => false,
            'issues' => [],
            'relationship' => null,
        ];

        if ($relationshipId === '') {
            $item['issues'][] = 'missing-relationship-id';
            return $item;
        }

        if (!is_array($relationship)) {
            $item['issues'][] = 'unknown-relationship';
            return $item;
        }

        $summary = $this->relationshipInventorySummary($parts, $relationship, $themePart, $relationshipsPart, $contentTypes);
        $targetPart = is_string($summary['targetPart'] ?? null) ? $summary['targetPart'] : null;
        $exists = (bool) $summary['exists'];

        $item['relationshipType'] = $summary['type'];
        $item['target'] = $summary['target'];
        $item['targetMode'] = $summary['targetMode'];
        $item['resolvedTarget'] = $summary['resolvedTarget'];
        $item['external'] = (bool) $summary['external'];
        $item['partName'] = $targetPart;
        $item['targetPart'] = $targetPart;
        $item['targetQuery'] = $summary['targetQuery'];
        $item['targetFragment'] = $summary['targetFragment'];
        $item['targetReferenceSuffix'] = $summary['targetReferenceSuffix'];
        $item['exists'] = $exists;
        $item['contentType'] = $summary['contentType'];
        $item['contentTypeBase'] = $summary['contentTypeBase'];
        $item['contentTypeHasParameters'] = $summary['contentTypeHasParameters'];
        $item['contentTypeParameterCount'] = $summary['contentTypeParameterCount'];
        $item['contentTypeParameters'] = $summary['contentTypeParameters'];
        $item['contentTypeParameterMap'] = $summary['contentTypeParameterMap'];
        $item['contentTypeSource'] = $summary['contentTypeSource'];
        $item['defaultExtension'] = $summary['defaultExtension'];
        $item['overridePartName'] = $summary['overridePartName'];
        $item['externalTargetKind'] = $summary['externalTargetKind'];
        $item['externalTargetScheme'] = $summary['externalTargetScheme'];
        $item['externalTargetAllowed'] = $summary['externalTargetAllowed'];
        $item['relationship'] = $summary;

        if ($relationship['type'] !== self::IMAGE_REL) {
            $item['issues'][] = 'unexpected-relationship-type';
        }

        if ($item['external']) {
            $item['issues'][] = 'external-theme-media-target';
            $item['issues'] = array_values(array_unique(array_merge($item['issues'], $summary['externalTargetIssues'])));
        } elseif ($targetPart !== null) {
            if ($exists) {
                $item['byteLength'] = strlen($parts[$targetPart]);
                $item['crc32'] = sprintf('%08x', crc32($parts[$targetPart]));
                $item['sha256'] = hash('sha256', $parts[$targetPart]);
            } else {
                $item['issues'][] = 'missing-theme-media-part';
            }

            $contentType = is_string($summary['contentType'] ?? null) ? $summary['contentType'] : '';
            if (($summary['contentTypeSource'] ?? '') === 'missing') {
                $item['issues'][] = 'missing-theme-media-content-type';
            } elseif ($relationship['type'] === self::IMAGE_REL && !$this->isImageContentType($contentType)) {
                $item['issues'][] = 'unexpected-theme-media-content-type';
            }
        }

        $item['issues'] = array_values(array_unique($item['issues']));
        sort($item['issues'], SORT_STRING);
        $item['valid'] = $item['issues'] === [];

        return $item;
    }

    /**
     * @param array<string, string> $parts
     * @param array<string, array{id:string, type:string, target:string, targetMode:string, resolvedTarget:string}> $relationships
     * @param array{defaults:array<string, string>, overrides:array<string, string>} $contentTypes
     * @return array<string, mixed>
     */
    private function readDocumentBackgroundImages(
        array $parts,
        string $xml,
        string $documentPart,
        array $relationships,
        array $contentTypes
    ): array {
        $items = [];
        $byRelationshipId = [];
        $relationshipIds = [];
        $partNames = [];
        $externalTargets = [];
        $contentTypesSeen = [];
        $issueCodes = [];
        $relationshipsPart = $this->relationshipsPartFor($documentPart);

        foreach ($this->documentBackgroundImageReferences($xml, $documentPart) as $reference) {
            $relationshipId = $reference['relationshipId'];
            $item = $this->documentBackgroundImageItem(
                $parts,
                $relationships[$relationshipId] ?? null,
                $documentPart,
                $relationshipsPart,
                $contentTypes,
                $reference,
                count($items),
            );
            $items[] = $item;

            $this->appendUniqueString($relationshipIds, $relationshipId);
            if ($relationshipId !== '' && !isset($byRelationshipId[$relationshipId])) {
                $byRelationshipId[$relationshipId] = $item;
            }
            if (($item['relationshipType'] ?? null) === self::IMAGE_REL) {
                $this->appendUniqueString($partNames, is_string($item['partName'] ?? null) ? $item['partName'] : null);
            }
            $this->appendUniqueString($contentTypesSeen, is_string($item['contentType'] ?? null) ? $item['contentType'] : null);
            if (($item['relationshipType'] ?? null) === self::IMAGE_REL && ($item['external'] ?? false) === true) {
                $this->appendUniqueString($externalTargets, is_string($item['target'] ?? null) ? $item['target'] : null);
            }
            foreach (($item['issues'] ?? []) as $issue) {
                if (is_string($issue) && $issue !== '') {
                    $issueCodes[$issue] = true;
                }
            }
        }
        ksort($issueCodes, SORT_STRING);

        return [
            'count' => count($items),
            'relationshipCount' => count(array_filter($items, static fn (array $item): bool => $item['relationshipType'] === self::IMAGE_REL)),
            'existingCount' => count(array_filter($items, static fn (array $item): bool => $item['relationshipType'] === self::IMAGE_REL && $item['external'] === false && $item['exists'] === true)),
            'missingCount' => count(array_filter($items, static fn (array $item): bool => in_array('missing-background-image', $item['issues'], true))),
            'externalCount' => count(array_filter($items, static fn (array $item): bool => $item['relationshipType'] === self::IMAGE_REL && $item['external'] === true)),
            'unresolvedCount' => count(array_filter(
                $items,
                static fn (array $item): bool => in_array('missing-relationship-id', $item['issues'], true) || in_array('unknown-relationship', $item['issues'], true),
            )),
            'unexpectedRelationshipTypeCount' => count(array_filter($items, static fn (array $item): bool => in_array('unexpected-relationship-type', $item['issues'], true))),
            'missingContentTypeCount' => count(array_filter($items, static fn (array $item): bool => in_array('missing-background-image-content-type', $item['issues'], true))),
            'unexpectedContentTypeCount' => count(array_filter($items, static fn (array $item): bool => in_array('unexpected-background-image-content-type', $item['issues'], true))),
            'issueCount' => count(array_filter($items, static fn (array $item): bool => $item['issues'] !== [])),
            'relationshipIds' => $relationshipIds,
            'partNames' => $partNames,
            'externalTargets' => $externalTargets,
            'contentTypes' => $contentTypesSeen,
            'issueCodes' => array_keys($issueCodes),
            'byRelationshipId' => $byRelationshipId,
            'items' => $items,
            'byteExposurePolicy' => 'document-background-image-bytes-blocked',
            'reviewPolicy' => 'document-background-image-metadata-only',
        ];
    }

    /**
     * @return list<array{relationshipId:string, relationshipAttribute:string, backgroundIndex:int, backgroundColor:?string, elementNamespace:?string, elementLocalName:string, elementId:?string, fillTitle:?string, fillType:?string, fillColor2:?string, fillOpacity:?string, fillRecolor:?string}>
     */
    private function documentBackgroundImageReferences(string $xml, string $partName): array
    {
        if ($xml === '') {
            return [];
        }

        $dom = $this->loadXml($xml, $partName);
        $xpath = $this->xpath($dom);
        $references = [];
        foreach ($this->elements($xpath, '/w:document/w:background') as $backgroundIndex => $background) {
            $backgroundColor = $this->emptyStringToNull($background->getAttributeNS(self::NS_W, 'color'));
            $stack = [$background];
            while ($stack !== []) {
                $element = array_shift($stack);
                if (!$element instanceof \DOMElement) {
                    continue;
                }

                foreach (['id', 'embed', 'link'] as $attribute) {
                    $relationshipId = $this->emptyStringToNull($element->getAttributeNS(self::NS_R, $attribute));
                    if ($relationshipId === null) {
                        continue;
                    }

                    $references[] = [
                        'relationshipId' => $relationshipId,
                        'relationshipAttribute' => 'r:' . $attribute,
                        'backgroundIndex' => $backgroundIndex,
                        'backgroundColor' => $backgroundColor,
                        'elementNamespace' => $element->namespaceURI,
                        'elementLocalName' => $element->localName,
                        'elementId' => $this->emptyStringToNull($element->getAttribute('id')),
                        'fillTitle' => $this->emptyStringToNull($element->getAttributeNS(self::NS_O, 'title') ?: $element->getAttribute('title')),
                        'fillType' => $this->emptyStringToNull($element->getAttribute('type')),
                        'fillColor2' => $this->emptyStringToNull($element->getAttribute('color2')),
                        'fillOpacity' => $this->emptyStringToNull($element->getAttribute('opacity')),
                        'fillRecolor' => $this->emptyStringToNull($element->getAttribute('recolor')),
                    ];
                }

                foreach ($element->childNodes as $child) {
                    if ($child instanceof \DOMElement) {
                        $stack[] = $child;
                    }
                }
            }
        }

        return $references;
    }

    /**
     * @param array<string, string> $parts
     * @param array{id:string, type:string, target:string, targetMode:string, resolvedTarget:string}|null $relationship
     * @param array{defaults:array<string, string>, overrides:array<string, string>} $contentTypes
     * @param array{relationshipId:string, relationshipAttribute:string, backgroundIndex:int, backgroundColor:?string, elementNamespace:?string, elementLocalName:string, elementId:?string, fillTitle:?string, fillType:?string, fillColor2:?string, fillOpacity:?string, fillRecolor:?string} $reference
     * @return array<string, mixed>
     */
    private function documentBackgroundImageItem(
        array $parts,
        ?array $relationship,
        string $documentPart,
        string $relationshipsPart,
        array $contentTypes,
        array $reference,
        int $index,
    ): array {
        $relationshipId = $reference['relationshipId'];
        $item = [
            'index' => $index,
            'relationshipId' => $relationshipId,
            'relationshipAttribute' => $reference['relationshipAttribute'],
            'backgroundIndex' => $reference['backgroundIndex'],
            'backgroundColor' => $reference['backgroundColor'],
            'elementNamespace' => $reference['elementNamespace'],
            'elementLocalName' => $reference['elementLocalName'],
            'elementId' => $reference['elementId'],
            'fillTitle' => $reference['fillTitle'],
            'fillType' => $reference['fillType'],
            'fillColor2' => $reference['fillColor2'],
            'fillOpacity' => $reference['fillOpacity'],
            'fillRecolor' => $reference['fillRecolor'],
            'relationshipType' => null,
            'target' => null,
            'targetMode' => null,
            'resolvedTarget' => null,
            'external' => false,
            'partName' => null,
            'targetPart' => null,
            'targetQuery' => null,
            'targetFragment' => null,
            'targetReferenceSuffix' => '',
            'exists' => false,
            'byteLength' => null,
            'crc32' => null,
            'sha256' => null,
            'contentType' => '',
            'contentTypeBase' => '',
            'contentTypeHasParameters' => false,
            'contentTypeParameterCount' => 0,
            'contentTypeParameters' => [],
            'contentTypeParameterMap' => [],
            'contentTypeSource' => 'missing',
            'defaultExtension' => null,
            'overridePartName' => null,
            'relationshipsPart' => $relationshipsPart,
            'byteExposurePolicy' => 'document-background-image-bytes-blocked',
            'reviewPolicy' => 'document-background-image-metadata-only',
            'valid' => false,
            'issues' => [],
            'relationship' => null,
        ];

        if ($relationshipId === '') {
            $item['issues'][] = 'missing-relationship-id';
            return $item;
        }

        if (!is_array($relationship)) {
            $item['issues'][] = 'unknown-relationship';
            return $item;
        }

        $summary = $this->relationshipInventorySummary($parts, $relationship, $documentPart, $relationshipsPart, $contentTypes);
        $targetPart = is_string($summary['targetPart'] ?? null) ? $summary['targetPart'] : null;
        $exists = (bool) $summary['exists'];

        $item['relationshipType'] = $summary['type'];
        $item['target'] = $summary['target'];
        $item['targetMode'] = $summary['targetMode'];
        $item['resolvedTarget'] = $summary['resolvedTarget'];
        $item['external'] = (bool) $summary['external'];
        $item['partName'] = $targetPart;
        $item['targetPart'] = $targetPart;
        $item['targetQuery'] = $summary['targetQuery'];
        $item['targetFragment'] = $summary['targetFragment'];
        $item['targetReferenceSuffix'] = $summary['targetReferenceSuffix'];
        $item['exists'] = $exists;
        $item['byteLength'] = $targetPart !== null && $exists ? strlen($parts[$targetPart]) : null;
        $item['crc32'] = $targetPart !== null && $exists ? sprintf('%08x', crc32($parts[$targetPart])) : null;
        $item['sha256'] = $targetPart !== null && $exists ? hash('sha256', $parts[$targetPart]) : null;
        $item['contentType'] = $summary['contentType'];
        $item['contentTypeBase'] = $summary['contentTypeBase'];
        $item['contentTypeHasParameters'] = $summary['contentTypeHasParameters'];
        $item['contentTypeParameterCount'] = $summary['contentTypeParameterCount'];
        $item['contentTypeParameters'] = $summary['contentTypeParameters'];
        $item['contentTypeParameterMap'] = $summary['contentTypeParameterMap'];
        $item['contentTypeSource'] = $summary['contentTypeSource'];
        $item['defaultExtension'] = $summary['defaultExtension'];
        $item['overridePartName'] = $summary['overridePartName'];
        $item['relationship'] = $summary;

        if ($relationship['type'] !== self::IMAGE_REL) {
            $item['issues'][] = 'unexpected-relationship-type';
            return $item;
        }

        if ($item['external'] === true) {
            $item['issues'][] = 'external-background-image';
            return $item;
        }

        if (!$exists) {
            $item['issues'][] = 'missing-background-image';
        }

        $contentType = is_string($summary['contentType'] ?? null) ? $summary['contentType'] : '';
        if (($summary['contentTypeSource'] ?? '') === 'missing') {
            $item['issues'][] = 'missing-background-image-content-type';
        } elseif ($contentType === '' || !$this->isImageContentType($contentType)) {
            $item['issues'][] = 'unexpected-background-image-content-type';
        }

        $item['valid'] = $item['issues'] === [];

        return $item;
    }

    /**
     * @param array<string, string> $parts
     * @param array<string, array{id:string, type:string, target:string, targetMode:string, resolvedTarget:string}> $relationships
     * @param array{defaults:array<string, string>, overrides:array<string, string>} $contentTypes
     * @return array<string, mixed>
     */
    private function readBibliographyParts(
        array $parts,
        string $documentPart,
        array $relationships,
        array $contentTypes
    ): array {
        $items = [];
        $byRelationshipId = [];
        $byPartName = [];
        $relationshipIds = [];
        $targetedPartNames = [];
        $relationshipsPart = $this->relationshipsPartFor($documentPart);

        foreach ($relationships as $relationship) {
            if ($relationship['type'] !== self::BIBLIOGRAPHY_REL) {
                continue;
            }

            $relationshipId = $relationship['id'];
            $item = $this->bibliographyPartItem(
                $parts,
                $relationship,
                $documentPart,
                $relationshipsPart,
                $contentTypes,
                count($items),
            );
            $items[] = $item;

            $this->appendUniqueString($relationshipIds, $relationshipId);
            if ($relationshipId !== '' && !isset($byRelationshipId[$relationshipId])) {
                $byRelationshipId[$relationshipId] = $item;
            }

            $partName = is_string($item['partName'] ?? null) ? $item['partName'] : null;
            if ($partName !== null) {
                $targetedPartNames[$partName] = true;
                if (!isset($byPartName[$partName])) {
                    $byPartName[$partName] = $item;
                }
            }
        }

        $orphanPartNames = [];
        foreach ($parts as $partName => $_contents) {
            $contentTypeResolution = $this->contentTypeResolutionForPart($partName, $contentTypes);
            if (
                ($contentTypeResolution['contentTypeBase'] ?? '') !== self::CT_WORD_BIBLIOGRAPHY
                || isset($targetedPartNames[$partName])
            ) {
                continue;
            }

            $item = $this->bibliographyPartPackageItem($parts, $partName, $contentTypes, count($items));
            $items[] = $item;
            $orphanPartNames[] = $partName;
            if (!isset($byPartName[$partName])) {
                $byPartName[$partName] = $item;
            }
        }

        $partNames = [];
        $externalTargets = [];
        $contentTypesSeen = [];
        $issueCodes = [];
        $sourceTypeCounts = [];
        $sourceTags = [];
        $sourceCount = 0;
        $sourceTagCount = 0;
        $missingSourceTagCount = 0;
        $titleCount = 0;
        $authorPersonCount = 0;
        foreach ($items as $item) {
            $this->appendUniqueString($partNames, is_string($item['partName'] ?? null) ? $item['partName'] : null);
            $this->appendUniqueString($contentTypesSeen, is_string($item['contentType'] ?? null) ? $item['contentType'] : null);
            if (($item['external'] ?? false) === true) {
                $this->appendUniqueString($externalTargets, is_string($item['target'] ?? null) ? $item['target'] : null);
            }
            foreach (($item['issues'] ?? []) as $issue) {
                if (is_string($issue) && $issue !== '') {
                    $issueCodes[$issue] = true;
                }
            }
            $sourceCount += (int) ($item['sourceCount'] ?? 0);
            $sourceTagCount += (int) ($item['sourceTagCount'] ?? 0);
            $missingSourceTagCount += (int) ($item['missingSourceTagCount'] ?? 0);
            $titleCount += (int) ($item['titleCount'] ?? 0);
            $authorPersonCount += (int) ($item['authorPersonCount'] ?? 0);
            foreach (($item['uniqueSourceTags'] ?? []) as $tag) {
                $this->appendUniqueString($sourceTags, is_string($tag) ? $tag : null);
            }
            foreach (($item['sourceTypeCounts'] ?? []) as $type => $count) {
                if (is_string($type) && $type !== '') {
                    $sourceTypeCounts[$type] = ($sourceTypeCounts[$type] ?? 0) + (int) $count;
                }
            }
        }
        sort($sourceTags, SORT_STRING);
        ksort($sourceTypeCounts, SORT_STRING);
        ksort($issueCodes, SORT_STRING);

        return [
            'count' => count($items),
            'relationshipCount' => count(array_filter($relationships, static fn (array $relationship): bool => $relationship['type'] === self::BIBLIOGRAPHY_REL)),
            'orphanPartCount' => count($orphanPartNames),
            'existingCount' => count(array_filter($items, static fn (array $item): bool => $item['external'] === false && $item['exists'] === true)),
            'missingCount' => count(array_filter($items, static fn (array $item): bool => in_array('missing-bibliography-part', $item['issues'], true))),
            'externalCount' => count(array_filter($items, static fn (array $item): bool => $item['external'] === true)),
            'invalidXmlCount' => count(array_filter($items, static fn (array $item): bool => in_array('invalid-bibliography-xml', $item['issues'], true))),
            'unexpectedRootCount' => count(array_filter($items, static fn (array $item): bool => in_array('unexpected-bibliography-root', $item['issues'], true))),
            'missingContentTypeCount' => count(array_filter($items, static fn (array $item): bool => in_array('missing-bibliography-content-type', $item['issues'], true))),
            'unexpectedContentTypeCount' => count(array_filter($items, static fn (array $item): bool => in_array('unexpected-bibliography-content-type', $item['issues'], true))),
            'sourceCount' => $sourceCount,
            'sourceTagCount' => $sourceTagCount,
            'missingSourceTagCount' => $missingSourceTagCount,
            'uniqueSourceTags' => $sourceTags,
            'sourceTypeCounts' => $sourceTypeCounts,
            'titleCount' => $titleCount,
            'authorPersonCount' => $authorPersonCount,
            'relationshipIds' => $relationshipIds,
            'orphanPartNames' => $orphanPartNames,
            'partNames' => $partNames,
            'externalTargets' => $externalTargets,
            'contentTypes' => $contentTypesSeen,
            'issueCount' => count(array_filter($items, static fn (array $item): bool => $item['issues'] !== [])),
            'issueCodes' => array_keys($issueCodes),
            'byRelationshipId' => $byRelationshipId,
            'byPartName' => $byPartName,
            'items' => $items,
            'byteExposurePolicy' => 'bibliography-part-bytes-blocked',
            'reviewPolicy' => 'bibliography-part-metadata-only',
        ];
    }

    /**
     * @param array<string, string> $parts
     * @param array{id:string, type:string, target:string, targetMode:string, resolvedTarget:string} $relationship
     * @param array{defaults:array<string, string>, overrides:array<string, string>} $contentTypes
     * @return array<string, mixed>
     */
    private function bibliographyPartItem(
        array $parts,
        array $relationship,
        string $documentPart,
        string $relationshipsPart,
        array $contentTypes,
        int $index
    ): array {
        $item = $this->emptyBibliographyPartItem($index);
        $summary = $this->relationshipInventorySummary($parts, $relationship, $documentPart, $relationshipsPart, $contentTypes);
        $targetPart = is_string($summary['targetPart'] ?? null) ? $summary['targetPart'] : null;
        $exists = (bool) $summary['exists'];

        $item['relationshipId'] = $summary['id'];
        $item['relationshipPresent'] = true;
        $item['relationshipType'] = $summary['type'];
        $item['target'] = $summary['target'];
        $item['targetMode'] = $summary['targetMode'];
        $item['resolvedTarget'] = $summary['resolvedTarget'];
        $item['external'] = (bool) $summary['external'];
        $item['partName'] = $targetPart;
        $item['targetPart'] = $targetPart;
        $item['targetQuery'] = $summary['targetQuery'];
        $item['targetFragment'] = $summary['targetFragment'];
        $item['targetReferenceSuffix'] = $summary['targetReferenceSuffix'];
        $item['exists'] = $exists;
        $item['byteLength'] = $targetPart !== null && $exists ? strlen($parts[$targetPart]) : null;
        $item['crc32'] = $targetPart !== null && $exists ? sprintf('%08x', crc32($parts[$targetPart])) : null;
        $item['sha256'] = $targetPart !== null && $exists ? hash('sha256', $parts[$targetPart]) : null;
        $item['contentType'] = $summary['contentType'];
        $item['contentTypeBase'] = $summary['contentTypeBase'];
        $item['contentTypeHasParameters'] = $summary['contentTypeHasParameters'];
        $item['contentTypeParameterCount'] = $summary['contentTypeParameterCount'];
        $item['contentTypeParameters'] = $summary['contentTypeParameters'];
        $item['contentTypeParameterMap'] = $summary['contentTypeParameterMap'];
        $item['contentTypeSource'] = $summary['contentTypeSource'];
        $item['defaultExtension'] = $summary['defaultExtension'];
        $item['overridePartName'] = $summary['overridePartName'];
        $item['relationship'] = $summary;

        if ($item['external'] === true) {
            $item['issues'][] = 'external-bibliography-part';
            return $item;
        }

        if (!$exists) {
            $item['issues'][] = 'missing-bibliography-part';
        }

        $contentTypeBase = is_string($summary['contentTypeBase'] ?? null) ? $summary['contentTypeBase'] : '';
        if (($summary['contentTypeSource'] ?? '') === 'missing') {
            $item['issues'][] = 'missing-bibliography-content-type';
        } elseif ($contentTypeBase !== self::CT_WORD_BIBLIOGRAPHY) {
            $item['issues'][] = 'unexpected-bibliography-content-type';
        }

        if ($exists && $targetPart !== null) {
            $this->applyBibliographyPartXmlMetadata($item, $parts[$targetPart], $targetPart);
        }
        $item['valid'] = $item['issues'] === [];

        return $item;
    }

    /**
     * @param array<string, string> $parts
     * @param array{defaults:array<string, string>, overrides:array<string, string>} $contentTypes
     * @return array<string, mixed>
     */
    private function bibliographyPartPackageItem(array $parts, string $partName, array $contentTypes, int $index): array
    {
        $item = $this->emptyBibliographyPartItem($index);
        $contentTypeResolution = $this->contentTypeResolutionForPart($partName, $contentTypes);
        $item['orphan'] = true;
        $item['partName'] = $partName;
        $item['targetPart'] = $partName;
        $item['exists'] = true;
        $item['byteLength'] = strlen($parts[$partName]);
        $item['crc32'] = sprintf('%08x', crc32($parts[$partName]));
        $item['sha256'] = hash('sha256', $parts[$partName]);
        $item['contentType'] = $contentTypeResolution['contentType'];
        $item['contentTypeBase'] = $contentTypeResolution['contentTypeBase'];
        $item['contentTypeHasParameters'] = $contentTypeResolution['contentTypeHasParameters'];
        $item['contentTypeParameterCount'] = $contentTypeResolution['contentTypeParameterCount'];
        $item['contentTypeParameters'] = $contentTypeResolution['contentTypeParameters'];
        $item['contentTypeParameterMap'] = $contentTypeResolution['contentTypeParameterMap'];
        $item['contentTypeSource'] = $contentTypeResolution['contentTypeSource'];
        $item['defaultExtension'] = $contentTypeResolution['defaultExtension'];
        $item['overridePartName'] = $contentTypeResolution['overridePartName'];
        $this->applyBibliographyPartXmlMetadata($item, $parts[$partName], $partName);
        $item['valid'] = $item['issues'] === [];

        return $item;
    }

    /**
     * @return array<string, mixed>
     */
    private function emptyBibliographyPartItem(int $index): array
    {
        return [
            'index' => $index,
            'relationshipId' => null,
            'relationshipPresent' => false,
            'orphan' => false,
            'relationshipType' => null,
            'target' => null,
            'targetMode' => null,
            'resolvedTarget' => null,
            'external' => false,
            'partName' => null,
            'targetPart' => null,
            'targetQuery' => null,
            'targetFragment' => null,
            'targetReferenceSuffix' => '',
            'exists' => false,
            'byteLength' => null,
            'crc32' => null,
            'sha256' => null,
            'contentType' => '',
            'contentTypeBase' => '',
            'contentTypeHasParameters' => false,
            'contentTypeParameterCount' => 0,
            'contentTypeParameters' => [],
            'contentTypeParameterMap' => [],
            'contentTypeSource' => 'missing',
            'defaultExtension' => null,
            'overridePartName' => null,
            'expectedContentTypeBase' => self::CT_WORD_BIBLIOGRAPHY,
            'validXml' => null,
            'xmlParseError' => null,
            'rootNamespace' => null,
            'rootLocalName' => null,
            'validRoot' => null,
            'sourceCount' => 0,
            'sourceTagCount' => 0,
            'missingSourceTagCount' => 0,
            'uniqueSourceTags' => [],
            'duplicateSourceTags' => [],
            'sourceTypeCounts' => [],
            'titleCount' => 0,
            'authorPersonCount' => 0,
            'sources' => [],
            'byteExposurePolicy' => 'bibliography-part-bytes-blocked',
            'reviewPolicy' => 'bibliography-part-metadata-only',
            'valid' => false,
            'issues' => [],
            'relationship' => null,
        ];
    }

    /**
     * @param array<string, mixed> $item
     */
    private function applyBibliographyPartXmlMetadata(array &$item, string $xml, string $partName): void
    {
        $metadata = $this->bibliographyPartXmlMetadata($xml, $partName);
        foreach ($metadata as $key => $value) {
            $item[$key] = $value;
        }

        if ($metadata['validXml'] === false) {
            $item['issues'][] = 'invalid-bibliography-xml';
        } elseif ($metadata['validRoot'] === false) {
            $item['issues'][] = 'unexpected-bibliography-root';
        }
    }

    /**
     * @return array{validXml:bool, xmlParseError:?string, rootNamespace:?string, rootLocalName:?string, validRoot:bool, sourceCount:int, sourceTagCount:int, missingSourceTagCount:int, uniqueSourceTags:list<string>, duplicateSourceTags:list<string>, sourceTypeCounts:array<string, int>, titleCount:int, authorPersonCount:int, sources:list<array{index:int, tag:?string, sourceType:?string, title:?string, authorPersonCount:int}>}
     */
    private function bibliographyPartXmlMetadata(string $xml, string $partName): array
    {
        $metadata = [
            'validXml' => false,
            'xmlParseError' => null,
            'rootNamespace' => null,
            'rootLocalName' => null,
            'validRoot' => false,
            'sourceCount' => 0,
            'sourceTagCount' => 0,
            'missingSourceTagCount' => 0,
            'uniqueSourceTags' => [],
            'duplicateSourceTags' => [],
            'sourceTypeCounts' => [],
            'titleCount' => 0,
            'authorPersonCount' => 0,
            'sources' => [],
        ];

        $dom = $this->loadXmlForProvenance($xml, $partName);
        if (!$dom instanceof \DOMDocument) {
            $metadata['xmlParseError'] = $this->lastXmlPreflightError($xml, $partName);

            return $metadata;
        }

        $root = $dom->documentElement;
        if (!$root instanceof \DOMElement) {
            $metadata['xmlParseError'] = 'missing XML document element';

            return $metadata;
        }

        $metadata['validXml'] = true;
        $metadata['rootNamespace'] = $root->namespaceURI;
        $metadata['rootLocalName'] = $root->localName;
        $metadata['validRoot'] = $root->namespaceURI === self::NS_BIB && $root->localName === 'Sources';
        if (!$metadata['validRoot']) {
            return $metadata;
        }

        $xpath = $this->xpath($dom);
        $tagCounts = [];
        foreach ($this->elements($xpath, '/b:Sources/b:Source') as $source) {
            $tag = $this->firstBibliographyElementText($xpath, './b:Tag', $source);
            $sourceType = $this->firstBibliographyElementText($xpath, './b:SourceType', $source);
            $title = $this->firstBibliographyElementText($xpath, './b:Title', $source);
            $authorPersonCount = count($this->elements($xpath, './/b:Person', $source));

            if ($tag === null) {
                ++$metadata['missingSourceTagCount'];
            } else {
                ++$metadata['sourceTagCount'];
                $tagCounts[$tag] = ($tagCounts[$tag] ?? 0) + 1;
            }
            if ($sourceType !== null) {
                $metadata['sourceTypeCounts'][$sourceType] = ($metadata['sourceTypeCounts'][$sourceType] ?? 0) + 1;
            }
            if ($title !== null) {
                ++$metadata['titleCount'];
            }
            $metadata['authorPersonCount'] += $authorPersonCount;
            $metadata['sources'][] = [
                'index' => $metadata['sourceCount'],
                'tag' => $tag,
                'sourceType' => $sourceType,
                'title' => $title,
                'authorPersonCount' => $authorPersonCount,
            ];
            ++$metadata['sourceCount'];
        }

        ksort($tagCounts, SORT_STRING);
        ksort($metadata['sourceTypeCounts'], SORT_STRING);
        $metadata['uniqueSourceTags'] = array_keys($tagCounts);
        foreach ($tagCounts as $tag => $count) {
            if ($count > 1) {
                $metadata['duplicateSourceTags'][] = $tag;
            }
        }

        return $metadata;
    }

    private function firstBibliographyElementText(\DOMXPath $xpath, string $query, \DOMNode $context): ?string
    {
        $element = $this->firstElement($xpath, $query, $context);
        if (!$element instanceof \DOMElement) {
            return null;
        }

        $text = trim(preg_replace('/\s+/u', ' ', $element->textContent) ?? $element->textContent);

        return $text === '' ? null : $this->boundedMetadataString($text);
    }

    /**
     * @param array<string, string> $parts
     * @param list<array{sourceType:string, partName:string, relationshipsPart:string, relationships:array<string, array{id:string, type:string, target:string, targetMode:string, resolvedTarget:string}>, validRoot?:bool}> $definitions
     * @return list<array{sourceType:string, sourcePart:string, relationshipsPart:string, relationships:array<string, array{id:string, type:string, target:string, targetMode:string, resolvedTarget:string}>, xml:string}>
     */
    private function xmlRelationshipSources(array $parts, array $definitions): array
    {
        $sources = [];
        foreach ($definitions as $definition) {
            if (($definition['validRoot'] ?? true) !== true) {
                continue;
            }

            $sourceType = (string) ($definition['sourceType'] ?? '');
            $sourcePart = (string) ($definition['partName'] ?? '');
            $relationshipsPart = (string) ($definition['relationshipsPart'] ?? '');
            $relationships = is_array($definition['relationships'] ?? null) ? $definition['relationships'] : [];
            if ($sourceType === '' || $sourcePart === '' || $relationshipsPart === '' || !isset($parts[$sourcePart])) {
                continue;
            }

            $sources[] = [
                'sourceType' => $sourceType,
                'sourcePart' => $sourcePart,
                'relationshipsPart' => $relationshipsPart,
                'relationships' => $relationships,
                'xml' => $parts[$sourcePart],
            ];
        }

        return $sources;
    }

    /**
     * @param array<string, string> $parts
     * @param array<string, mixed> $headers
     * @param array<string, mixed> $footers
     * @return list<array{sourceType:string, sourcePart:string, relationshipsPart:string, relationships:array<string, array{id:string, type:string, target:string, targetMode:string, resolvedTarget:string}>, xml:string}>
     */
    private function headerFooterXmlRelationshipSources(array $parts, array $headers, array $footers): array
    {
        $sources = [];
        foreach (['header' => $headers['items'] ?? [], 'footer' => $footers['items'] ?? []] as $sourceType => $items) {
            if (!is_array($items)) {
                continue;
            }

            foreach ($items as $item) {
                if (!is_array($item) || ($item['validRoot'] ?? null) !== true) {
                    continue;
                }

                $sourcePart = is_string($item['partName'] ?? null) ? $item['partName'] : '';
                $relationshipsPart = is_string($item['relationshipsPart'] ?? null) ? $item['relationshipsPart'] : '';
                if ($sourcePart === '' || $relationshipsPart === '' || !isset($parts[$sourcePart])) {
                    continue;
                }

                $sources[] = [
                    'sourceType' => $sourceType,
                    'sourcePart' => $sourcePart,
                    'relationshipsPart' => $relationshipsPart,
                    'relationships' => $this->readRelationshipsPart($parts, $relationshipsPart),
                    'xml' => $parts[$sourcePart],
                ];
            }
        }

        return $sources;
    }

    private function relationshipKey(string $relationshipsPart, string $relationshipId): string
    {
        return $relationshipId === '' ? '' : $relationshipsPart . '#' . $relationshipId;
    }

    /**
     * @param array<string, string> $parts
     * @param list<array{sourceType:string, sourcePart:string, relationshipsPart:string, relationships:array<string, array{id:string, type:string, target:string, targetMode:string, resolvedTarget:string}>, xml:string}> $sources
     * @param array{defaults:array<string, string>, overrides:array<string, string>} $contentTypes
     * @return array<string, mixed>
     */
    private function readChartParts(
        array $parts,
        array $sources,
        array $contentTypes
    ): array {
        $items = [];
        $byRelationshipId = [];
        $byRelationshipKey = [];
        $relationshipIds = [];
        $relationshipKeys = [];
        $referencedRelationshipIds = [];
        $referencedRelationshipKeys = [];
        $referencedChartRelationshipKeys = [];
        $sourceTypes = [];
        $sourceParts = [];
        $relationshipsParts = [];
        $relationshipCount = 0;
        $unreferencedRelationshipIds = [];
        $unreferencedRelationshipKeys = [];

        foreach ($sources as $source) {
            $sourceType = $source['sourceType'];
            $sourcePart = $source['sourcePart'];
            $relationshipsPart = $source['relationshipsPart'];
            $relationships = $source['relationships'];
            $this->appendUniqueString($sourceTypes, $sourceType);
            $this->appendUniqueString($sourceParts, $sourcePart);
            $this->appendUniqueString($relationshipsParts, $relationshipsPart);

            $dom = $this->loadXmlForProvenance($source['xml'], $sourcePart);
            if ($dom instanceof \DOMDocument) {
                $xpath = $this->xpath($dom);
                foreach ($this->elements($xpath, '//c:chart') as $chart) {
                    $relationshipId = $chart->getAttributeNS(self::NS_R, 'id');
                    $relationshipKey = $this->relationshipKey($relationshipsPart, $relationshipId);
                    $item = $this->chartPartItem(
                        $parts,
                        $relationships[$relationshipId] ?? null,
                        $sourceType,
                        $sourcePart,
                        $relationshipsPart,
                        $contentTypes,
                        $relationshipId,
                        count($items),
                        true,
                    );
                    $items[] = $item;

                    $this->appendUniqueString($relationshipIds, $relationshipId);
                    $this->appendUniqueString($relationshipKeys, $relationshipKey);
                    $this->appendUniqueString($referencedRelationshipIds, $relationshipId);
                    $this->appendUniqueString($referencedRelationshipKeys, $relationshipKey);
                    if ($item['relationshipType'] === self::CHART_REL) {
                        $this->appendUniqueString($referencedChartRelationshipKeys, $relationshipKey);
                    }
                    if ($relationshipId !== '' && !isset($byRelationshipId[$relationshipId])) {
                        $byRelationshipId[$relationshipId] = $item;
                    }
                    if ($relationshipKey !== '') {
                        $byRelationshipKey[$relationshipKey] = $item;
                    }
                }
            }

            foreach ($relationships as $relationship) {
                if ($relationship['type'] !== self::CHART_REL) {
                    continue;
                }

                ++$relationshipCount;
                $relationshipId = $relationship['id'];
                $relationshipKey = $this->relationshipKey($relationshipsPart, $relationshipId);
                if (in_array($relationshipKey, $referencedChartRelationshipKeys, true)) {
                    continue;
                }

                $item = $this->chartPartItem(
                    $parts,
                    $relationship,
                    $sourceType,
                    $sourcePart,
                    $relationshipsPart,
                    $contentTypes,
                    $relationshipId,
                    count($items),
                    false,
                );
                $items[] = $item;

                $this->appendUniqueString($relationshipIds, $relationshipId);
                $this->appendUniqueString($relationshipKeys, $relationshipKey);
                $this->appendUniqueString($unreferencedRelationshipIds, $relationshipId);
                $this->appendUniqueString($unreferencedRelationshipKeys, $relationshipKey);
                if (!isset($byRelationshipId[$relationshipId])) {
                    $byRelationshipId[$relationshipId] = $item;
                }
                if ($relationshipKey !== '') {
                    $byRelationshipKey[$relationshipKey] = $item;
                }
            }
        }

        $partNames = [];
        $externalTargets = [];
        $contentTypesSeen = [];
        $sourceTypeCounts = [];
        $issueCodes = [];
        $embeddedPackageRelationshipIds = [];
        $embeddedPackagePartNames = [];
        $embeddedPackageExternalTargets = [];
        $embeddedPackageIssueCodes = [];
        $embeddedPackageCount = 0;
        $embeddedPackageExistingCount = 0;
        $embeddedPackageMissingCount = 0;
        $embeddedPackageExternalCount = 0;
        $embeddedPackageIssueCount = 0;
        $chartSeriesCount = 0;
        $chartDataPointCount = 0;
        foreach ($items as $item) {
            if (($item['relationshipType'] ?? null) === self::CHART_REL) {
                $this->appendUniqueString($partNames, is_string($item['partName'] ?? null) ? $item['partName'] : null);
            }
            if (is_array($item['chartMetadata'] ?? null)) {
                $chartSeriesCount += (int) ($item['chartMetadata']['seriesCount'] ?? 0);
                $chartDataPointCount += (int) ($item['chartMetadata']['dataPointCount'] ?? 0);
            }
            $itemSourceType = is_string($item['sourceType'] ?? null) ? $item['sourceType'] : '';
            if ($itemSourceType !== '') {
                $sourceTypeCounts[$itemSourceType] = ($sourceTypeCounts[$itemSourceType] ?? 0) + 1;
            }
            $this->appendUniqueString($contentTypesSeen, is_string($item['contentType'] ?? null) ? $item['contentType'] : null);
            if (($item['external'] ?? false) === true) {
                $this->appendUniqueString($externalTargets, is_string($item['target'] ?? null) ? $item['target'] : null);
            }
            foreach (($item['issues'] ?? []) as $issue) {
                if (is_string($issue) && $issue !== '') {
                    $issueCodes[$issue] = true;
                }
            }
            $embeddedPackages = is_array($item['embeddedPackages'] ?? null) ? $item['embeddedPackages'] : [];
            $embeddedPackageCount += (int) ($embeddedPackages['count'] ?? 0);
            $embeddedPackageExistingCount += (int) ($embeddedPackages['existingCount'] ?? 0);
            $embeddedPackageMissingCount += (int) ($embeddedPackages['missingCount'] ?? 0);
            $embeddedPackageExternalCount += (int) ($embeddedPackages['externalCount'] ?? 0);
            $embeddedPackageIssueCount += (int) ($embeddedPackages['issueCount'] ?? 0);
            foreach (($embeddedPackages['relationshipIds'] ?? []) as $relationshipId) {
                $this->appendUniqueString($embeddedPackageRelationshipIds, is_string($relationshipId) ? $relationshipId : null);
            }
            foreach (($embeddedPackages['partNames'] ?? []) as $partName) {
                $this->appendUniqueString($embeddedPackagePartNames, is_string($partName) ? $partName : null);
            }
            foreach (($embeddedPackages['externalTargets'] ?? []) as $target) {
                $this->appendUniqueString($embeddedPackageExternalTargets, is_string($target) ? $target : null);
            }
            foreach (($embeddedPackages['issueCodes'] ?? []) as $issue) {
                if (is_string($issue) && $issue !== '') {
                    $embeddedPackageIssueCodes[$issue] = true;
                }
            }
        }
        ksort($sourceTypeCounts, SORT_STRING);
        ksort($issueCodes, SORT_STRING);
        ksort($embeddedPackageIssueCodes, SORT_STRING);

        return [
            'count' => count($items),
            'relationshipCount' => $relationshipCount,
            'sourcePartCount' => count($sourceParts),
            'sourceTypes' => $sourceTypes,
            'sourceTypeCounts' => $sourceTypeCounts,
            'sourceParts' => $sourceParts,
            'relationshipsParts' => $relationshipsParts,
            'referencedCount' => count(array_filter($items, static fn (array $item): bool => $item['referenced'] === true)),
            'unreferencedRelationshipCount' => count($unreferencedRelationshipIds),
            'existingCount' => count(array_filter($items, static fn (array $item): bool => $item['relationshipType'] === self::CHART_REL && $item['external'] === false && $item['exists'] === true)),
            'missingCount' => count(array_filter($items, static fn (array $item): bool => in_array('missing-chart-part', $item['issues'], true))),
            'externalCount' => count(array_filter($items, static fn (array $item): bool => $item['relationshipType'] === self::CHART_REL && $item['external'] === true)),
            'unresolvedCount' => count(array_filter(
                $items,
                static fn (array $item): bool => in_array('missing-relationship-id', $item['issues'], true) || in_array('unknown-relationship', $item['issues'], true),
            )),
            'invalidXmlCount' => count(array_filter($items, static fn (array $item): bool => in_array('invalid-chart-xml', $item['issues'], true))),
            'unexpectedRootCount' => count(array_filter($items, static fn (array $item): bool => in_array('unexpected-chart-root', $item['issues'], true))),
            'unexpectedRelationshipTypeCount' => count(array_filter($items, static fn (array $item): bool => in_array('unexpected-relationship-type', $item['issues'], true))),
            'missingContentTypeCount' => count(array_filter($items, static fn (array $item): bool => in_array('missing-chart-content-type', $item['issues'], true))),
            'unexpectedContentTypeCount' => count(array_filter($items, static fn (array $item): bool => in_array('unexpected-chart-content-type', $item['issues'], true))),
            'issueCount' => count(array_filter($items, static fn (array $item): bool => $item['issues'] !== [])),
            'seriesCount' => $chartSeriesCount,
            'dataPointCount' => $chartDataPointCount,
            'relationshipIds' => $relationshipIds,
            'relationshipKeys' => $relationshipKeys,
            'referencedRelationshipIds' => $referencedRelationshipIds,
            'referencedRelationshipKeys' => $referencedRelationshipKeys,
            'unreferencedRelationshipIds' => $unreferencedRelationshipIds,
            'unreferencedRelationshipKeys' => $unreferencedRelationshipKeys,
            'partNames' => $partNames,
            'externalTargets' => $externalTargets,
            'contentTypes' => $contentTypesSeen,
            'embeddedPackageCount' => $embeddedPackageCount,
            'embeddedPackageExistingCount' => $embeddedPackageExistingCount,
            'embeddedPackageMissingCount' => $embeddedPackageMissingCount,
            'embeddedPackageExternalCount' => $embeddedPackageExternalCount,
            'embeddedPackageIssueCount' => $embeddedPackageIssueCount,
            'embeddedPackageRelationshipIds' => $embeddedPackageRelationshipIds,
            'embeddedPackagePartNames' => $embeddedPackagePartNames,
            'embeddedPackageExternalTargets' => $embeddedPackageExternalTargets,
            'embeddedPackageIssueCodes' => array_keys($embeddedPackageIssueCodes),
            'issueCodes' => array_keys($issueCodes),
            'byRelationshipId' => $byRelationshipId,
            'byRelationshipKey' => $byRelationshipKey,
            'items' => $items,
            'byteExposurePolicy' => 'chart-part-bytes-blocked',
            'reviewPolicy' => 'chart-part-metadata-only',
        ];
    }

    /**
     * @param array<string, string> $parts
     * @param array{id:string, type:string, target:string, targetMode:string, resolvedTarget:string}|null $relationship
     * @param array{defaults:array<string, string>, overrides:array<string, string>} $contentTypes
     * @return array<string, mixed>
     */
    private function chartPartItem(
        array $parts,
        ?array $relationship,
        string $sourceType,
        string $sourcePart,
        string $relationshipsPart,
        array $contentTypes,
        string $relationshipId,
        int $index,
        bool $referenced
    ): array {
        $item = [
            'index' => $index,
            'relationshipId' => $relationshipId,
            'relationshipKey' => $this->relationshipKey($relationshipsPart, $relationshipId),
            'sourceType' => $sourceType,
            'sourcePart' => $sourcePart,
            'referenced' => $referenced,
            'relationshipType' => null,
            'target' => null,
            'targetMode' => null,
            'resolvedTarget' => null,
            'external' => false,
            'partName' => null,
            'targetPart' => null,
            'targetQuery' => null,
            'targetFragment' => null,
            'targetReferenceSuffix' => '',
            'exists' => false,
            'byteLength' => null,
            'crc32' => null,
            'sha256' => null,
            'contentType' => '',
            'contentTypeBase' => '',
            'contentTypeHasParameters' => false,
            'contentTypeParameterCount' => 0,
            'contentTypeParameters' => [],
            'contentTypeParameterMap' => [],
            'contentTypeSource' => 'missing',
            'defaultExtension' => null,
            'overridePartName' => null,
            'expectedContentTypeBase' => self::CT_CHART,
            'relationshipsPart' => $relationshipsPart,
            'chartRelationshipsPart' => null,
            'chartRelationshipCount' => 0,
            'externalDataRelationshipIds' => [],
            'embeddedPackages' => $this->emptyChartEmbeddedPackageParts(),
            'chartMetadata' => $this->emptyChartMetadata(),
            'validXml' => null,
            'xmlParseError' => null,
            'rootNamespace' => null,
            'rootLocalName' => null,
            'validRoot' => null,
            'byteExposurePolicy' => 'chart-part-bytes-blocked',
            'reviewPolicy' => 'chart-part-metadata-only',
            'valid' => false,
            'issues' => [],
            'relationship' => null,
        ];

        if ($relationshipId === '') {
            $item['issues'][] = 'missing-relationship-id';
            return $item;
        }

        if (!is_array($relationship)) {
            $item['issues'][] = 'unknown-relationship';
            return $item;
        }

        $summary = $this->relationshipInventorySummary($parts, $relationship, $sourcePart, $relationshipsPart, $contentTypes);
        $targetPart = is_string($summary['targetPart'] ?? null) ? $summary['targetPart'] : null;
        $exists = (bool) $summary['exists'];
        $chartRelationshipsPart = $targetPart === null ? null : $this->relationshipsPartFor($targetPart);
        $chartRelationships = $chartRelationshipsPart === null ? [] : $this->readRelationshipsPart($parts, $chartRelationshipsPart);

        $item['relationshipType'] = $summary['type'];
        $item['target'] = $summary['target'];
        $item['targetMode'] = $summary['targetMode'];
        $item['resolvedTarget'] = $summary['resolvedTarget'];
        $item['external'] = (bool) $summary['external'];
        $item['partName'] = $targetPart;
        $item['targetPart'] = $targetPart;
        $item['targetQuery'] = $summary['targetQuery'];
        $item['targetFragment'] = $summary['targetFragment'];
        $item['targetReferenceSuffix'] = $summary['targetReferenceSuffix'];
        $item['exists'] = $exists;
        $item['byteLength'] = $targetPart !== null && $exists ? strlen($parts[$targetPart]) : null;
        $item['crc32'] = $targetPart !== null && $exists ? sprintf('%08x', crc32($parts[$targetPart])) : null;
        $item['sha256'] = $targetPart !== null && $exists ? hash('sha256', $parts[$targetPart]) : null;
        $item['contentType'] = $summary['contentType'];
        $item['contentTypeBase'] = $summary['contentTypeBase'];
        $item['contentTypeHasParameters'] = $summary['contentTypeHasParameters'];
        $item['contentTypeParameterCount'] = $summary['contentTypeParameterCount'];
        $item['contentTypeParameters'] = $summary['contentTypeParameters'];
        $item['contentTypeParameterMap'] = $summary['contentTypeParameterMap'];
        $item['contentTypeSource'] = $summary['contentTypeSource'];
        $item['defaultExtension'] = $summary['defaultExtension'];
        $item['overridePartName'] = $summary['overridePartName'];
        $item['chartRelationshipsPart'] = $chartRelationshipsPart;
        $item['chartRelationshipCount'] = count($chartRelationships);
        $item['relationship'] = $summary;

        if ($relationship['type'] !== self::CHART_REL) {
            $item['issues'][] = 'unexpected-relationship-type';
            return $item;
        }

        if ($item['external'] === true) {
            $item['issues'][] = 'external-chart-part';
            return $item;
        }

        if (!$exists) {
            $item['issues'][] = 'missing-chart-part';
        }

        $contentTypeBase = is_string($summary['contentTypeBase'] ?? null) ? $summary['contentTypeBase'] : '';
        if (($summary['contentTypeSource'] ?? '') === 'missing') {
            $item['issues'][] = 'missing-chart-content-type';
        } elseif ($contentTypeBase !== self::CT_CHART) {
            $item['issues'][] = 'unexpected-chart-content-type';
        }

        if ($exists && $targetPart !== null) {
            $root = $this->xmlRootProvenance($parts[$targetPart], $targetPart);
            $item['validXml'] = $root['validXml'];
            $item['xmlParseError'] = $root['xmlParseError'];
            $item['rootNamespace'] = $root['namespace'];
            $item['rootLocalName'] = $root['localName'];
            $item['validRoot'] = $root['namespace'] === self::NS_C && $root['localName'] === 'chartSpace';
            if ($root['validXml'] === false) {
                $item['issues'][] = 'invalid-chart-xml';
            } elseif ($item['validRoot'] === false) {
                $item['issues'][] = 'unexpected-chart-root';
            } else {
                $item['externalDataRelationshipIds'] = $this->chartExternalDataRelationshipIds($parts[$targetPart], $targetPart);
                $item['chartMetadata'] = $this->chartMetadata($parts[$targetPart], $targetPart);
            }
        }

        $item['embeddedPackages'] = $this->chartEmbeddedPackageParts(
            $parts,
            $targetPart,
            $chartRelationshipsPart,
            $chartRelationships,
            $contentTypes,
            $item['externalDataRelationshipIds'],
        );
        $item['valid'] = $item['issues'] === [] && (int) $item['embeddedPackages']['issueCount'] === 0;

        return $item;
    }

    /**
     * @return list<string>
     */
    private function chartExternalDataRelationshipIds(string $xml, string $partName): array
    {
        $dom = $this->loadXmlForProvenance($xml, $partName);
        if (!$dom instanceof \DOMDocument) {
            return [];
        }

        $relationshipIds = [];
        $xpath = $this->xpath($dom);
        foreach ($this->elements($xpath, '//c:externalData') as $externalData) {
            $this->appendUniqueString($relationshipIds, $this->chartExternalDataRelationshipId($externalData));
        }

        return $relationshipIds;
    }

    /**
     * @return string
     */
    private function chartExternalDataRelationshipId(\DOMElement $externalData): string
    {
        $relationshipId = trim($externalData->getAttributeNS(self::NS_R, 'id'));
        if ($relationshipId !== '') {
            return $relationshipId;
        }

        return trim($externalData->getAttribute('id'));
    }

    /**
     * @return array<string, mixed>
     */
    private function emptyChartMetadata(): array
    {
        return [
            'chartTypeCount' => 0,
            'chartTypes' => [],
            'seriesCount' => 0,
            'dataPointCount' => 0,
            'series' => [],
        ];
    }

    /**
     * @return array<string, mixed>
     */
    private function chartMetadata(string $xml, string $partName): array
    {
        $dom = $this->loadXmlForProvenance($xml, $partName);
        if (!$dom instanceof \DOMDocument || !$dom->documentElement instanceof \DOMElement) {
            return $this->emptyChartMetadata();
        }

        $xpath = $this->xpath($dom);
        $plotArea = $this->firstElement($xpath, '/c:chartSpace/c:chart/c:plotArea', $dom->documentElement);
        if (!$plotArea instanceof \DOMElement) {
            return $this->emptyChartMetadata();
        }

        $chartTypes = [];
        $series = [];
        $dataPointCount = 0;
        foreach ($this->chartChildElements($plotArea, null) as $chartTypeElement) {
            if (!str_ends_with($chartTypeElement->localName, 'Chart')) {
                continue;
            }

            $chartType = $this->chartTypeName($chartTypeElement);
            $this->appendUniqueString($chartTypes, $chartType);
            foreach ($this->chartChildElements($chartTypeElement, 'ser') as $seriesElement) {
                $seriesItem = $this->chartSeriesMetadata($seriesElement, $chartType);
                $dataPointCount += (int) ($seriesItem['dataPointCount'] ?? 0);
                $series[] = $seriesItem;
            }
        }

        return [
            'chartTypeCount' => count($chartTypes),
            'chartTypes' => $chartTypes,
            'seriesCount' => count($series),
            'dataPointCount' => $dataPointCount,
            'series' => $series,
        ];
    }

    private function chartTypeName(\DOMElement $chartTypeElement): string
    {
        $type = preg_replace('/Chart$/', '', $chartTypeElement->localName) ?? $chartTypeElement->localName;

        return strtolower($type);
    }

    /**
     * @return array<string, mixed>
     */
    private function chartSeriesMetadata(\DOMElement $seriesElement, string $plotType): array
    {
        $categoryCache = $this->chartCacheSummaryFor($seriesElement, ['cat', 'xVal']);
        $valueCache = $this->chartCacheSummaryFor($seriesElement, ['val', 'yVal']);
        $series = [
            'name' => '',
            'categories' => $categoryCache['values'],
            'values' => $valueCache['values'],
            'plotType' => $plotType,
        ];
        $this->addChartCacheMetadata($series, 'category', $categoryCache);
        $this->addChartCacheMetadata($series, 'value', $valueCache);

        $index = $this->chartFirstChildElement($seriesElement, 'idx');
        if ($index instanceof \DOMElement && $index->getAttribute('val') !== '') {
            $series['index'] = $index->getAttribute('val');
        }

        $order = $this->chartFirstChildElement($seriesElement, 'order');
        if ($order instanceof \DOMElement && $order->getAttribute('val') !== '') {
            $series['order'] = $order->getAttribute('val');
        }

        $text = $this->chartFirstChildElement($seriesElement, 'tx');
        if ($text instanceof \DOMElement) {
            $series['name'] = $this->chartElementText($text);
            $this->addChartCacheMetadata($series, 'name', $this->chartCacheSummary($text));
        }

        foreach ([
            'invertIfNegative' => 'invertIfNegative',
            'smooth' => 'smooth',
        ] as $source => $target) {
            $value = $this->chartBooleanChildValue($seriesElement, $source);
            if ($value !== null) {
                $series[$target] = $value;
            }
        }

        $explosion = $this->chartIntChildValue($seriesElement, 'explosion');
        if ($explosion !== null) {
            $series['explosion'] = $explosion;
        }

        $marker = $this->chartMarkerMetadata($seriesElement);
        if ($marker !== []) {
            $series['marker'] = $marker;
        }

        $dataPoints = $this->chartDataPoints($seriesElement);
        if ($dataPoints !== []) {
            $series['dataPoints'] = $dataPoints;
            $series['dataPointCount'] = count($dataPoints);
        }

        return $series;
    }

    private function chartBooleanChildValue(\DOMElement $parent, string $localName): ?bool
    {
        $child = $this->chartFirstChildElement($parent, $localName);
        if (!$child instanceof \DOMElement) {
            return null;
        }

        return $child->hasAttribute('val') ? $this->xmlBooleanValue($child->getAttribute('val')) : true;
    }

    private function chartIntChildValue(\DOMElement $parent, string $localName): ?int
    {
        $child = $this->chartFirstChildElement($parent, $localName);
        if (!$child instanceof \DOMElement) {
            return null;
        }

        return $this->integerAttribute($child, 'val');
    }

    /**
     * @return array<string, mixed>
     */
    private function chartMarkerMetadata(\DOMElement $container): array
    {
        $marker = $this->chartFirstChildElement($container, 'marker');
        if (!$marker instanceof \DOMElement) {
            return [];
        }

        $metadata = [];
        $symbol = $this->chartFirstChildElement($marker, 'symbol');
        if ($symbol instanceof \DOMElement && trim($symbol->getAttribute('val')) !== '') {
            $metadata['symbol'] = trim($symbol->getAttribute('val'));
        }

        $size = $this->chartIntChildValue($marker, 'size');
        if ($size !== null) {
            $metadata['size'] = $size;
        }

        return $metadata;
    }

    /**
     * @return list<array<string, mixed>>
     */
    private function chartDataPoints(\DOMElement $seriesElement): array
    {
        $points = [];
        foreach ($this->chartChildElements($seriesElement, 'dPt') as $dataPoint) {
            $point = [];
            $index = $this->chartIntChildValue($dataPoint, 'idx');
            if ($index !== null) {
                $point['pointIndex'] = $index;
            }

            foreach ([
                'invertIfNegative' => 'invertIfNegative',
                'bubble3D' => 'bubble3D',
            ] as $source => $target) {
                $value = $this->chartBooleanChildValue($dataPoint, $source);
                if ($value !== null) {
                    $point[$target] = $value;
                }
            }

            $explosion = $this->chartIntChildValue($dataPoint, 'explosion');
            if ($explosion !== null) {
                $point['explosion'] = $explosion;
            }

            $marker = $this->chartMarkerMetadata($dataPoint);
            if ($marker !== []) {
                $point['marker'] = $marker;
            }

            $shapeProperties = $this->chartFirstChildElement($dataPoint, 'spPr');
            if ($shapeProperties instanceof \DOMElement) {
                $shape = $this->chartShapePropertiesMetadata($shapeProperties);
                if ($shape !== []) {
                    $point['shape'] = $shape;
                }
            }

            if ($point !== []) {
                $points[] = $point;
            }
        }

        return $points;
    }

    /**
     * @return array<string, mixed>
     */
    private function chartShapePropertiesMetadata(\DOMElement $shapeProperties): array
    {
        $metadata = [];
        $fill = $this->drawingFillMetadata($shapeProperties);
        if (is_string($fill['color'] ?? null) && $fill['color'] !== '') {
            $metadata['fillColor'] = $fill['color'];
            if (is_array($fill['transforms'] ?? null) && $fill['transforms'] !== []) {
                $metadata['fillColorTransforms'] = $fill['transforms'];
            }
        }

        $line = $this->drawingFirstChildElement($shapeProperties, 'ln');
        if ($line instanceof \DOMElement) {
            $lineStyle = $this->drawingLineStyleMetadata($line);
            if ($lineStyle !== []) {
                $metadata['line'] = $lineStyle;
            }
        }

        return $metadata;
    }

    /**
     * @param list<string> $containers
     * @return array{values:list<string>, pointIndexes:list<string>, pointCount?:int, formula?:string}
     */
    private function chartCacheSummaryFor(\DOMElement $seriesElement, array $containers): array
    {
        foreach ($this->chartChildElements($seriesElement, null) as $child) {
            if (in_array($child->localName, $containers, true)) {
                return $this->chartCacheSummary($child);
            }
        }

        return [
            'values' => [],
            'pointIndexes' => [],
        ];
    }

    /**
     * @param array<string, mixed> $series
     * @param array{values:list<string>, pointIndexes:list<string>, pointCount?:int, formula?:string} $cache
     */
    private function addChartCacheMetadata(array &$series, string $prefix, array $cache): void
    {
        if (is_string($cache['formula'] ?? null) && $cache['formula'] !== '') {
            $series[$prefix . 'Formula'] = $cache['formula'];
        }
        if (is_int($cache['pointCount'] ?? null)) {
            $series[$prefix . 'PointCount'] = $cache['pointCount'];
        }
        if ($cache['pointIndexes'] !== []) {
            $series[$prefix . 'PointIndexes'] = $cache['pointIndexes'];
        }
    }

    /**
     * @return array{values:list<string>, pointIndexes:list<string>, pointCount?:int, formula?:string}
     */
    private function chartCacheSummary(\DOMElement $container): array
    {
        $summary = [
            'values' => [],
            'pointIndexes' => [],
        ];
        $formula = $this->chartFirstDescendantElement($container, 'f');
        if ($formula instanceof \DOMElement) {
            $text = trim($formula->textContent);
            if ($text !== '') {
                $summary['formula'] = $text;
            }
        }

        $pointCount = $this->chartFirstDescendantElement($container, 'ptCount');
        if ($pointCount instanceof \DOMElement) {
            $count = $this->integerAttribute($pointCount, 'val');
            if ($count !== null) {
                $summary['pointCount'] = $count;
            }
        }

        $values = [];
        $pointIndexes = [];
        foreach ($this->chartDescendantElements($container, 'pt') as $point) {
            $pointIndex = trim($point->getAttribute('idx'));
            if ($pointIndex !== '') {
                $pointIndexes[] = $pointIndex;
            }

            $value = $this->chartFirstChildElement($point, 'v');
            if ($value instanceof \DOMElement) {
                $text = $this->chartElementText($value);
                if ($text !== '') {
                    $values[] = $text;
                }
            }
        }
        if ($values !== []) {
            $summary['values'] = $values;
            $summary['pointIndexes'] = array_values(array_unique($pointIndexes));

            return $summary;
        }

        foreach ($this->chartDescendantElements($container, 'v') as $value) {
            $text = $this->chartElementText($value);
            if ($text !== '') {
                $values[] = $text;
            }
        }

        $summary['values'] = $values;

        return $summary;
    }

    private function chartElementText(\DOMElement $element): string
    {
        $texts = [];
        if (in_array($element->localName, ['t', 'v'], true)) {
            $text = trim($element->textContent);
            if ($text !== '') {
                $texts[] = $text;
            }
        }

        foreach ($element->getElementsByTagName('*') as $child) {
            if (!$child instanceof \DOMElement || !in_array($child->localName, ['t', 'v'], true)) {
                continue;
            }

            $text = trim($child->textContent);
            if ($text !== '') {
                $texts[] = $text;
            }
        }

        return trim(implode(' ', $texts));
    }

    /**
     * @return array<string, mixed>
     */
    private function drawingFillMetadata(\DOMElement $properties): array
    {
        foreach ($this->drawingChildElements($properties, null) as $child) {
            if (!in_array($child->localName, ['solidFill', 'fill', 'fillRef'], true)) {
                continue;
            }

            $metadata = $this->drawingColorMetadata($child);
            if (is_string($metadata['color'] ?? null) && $metadata['color'] !== '') {
                return $metadata;
            }
        }

        return [];
    }

    /**
     * @return array<string, mixed>
     */
    private function drawingLineStyleMetadata(\DOMElement $line): array
    {
        $style = [];
        $color = $this->drawingColorMetadata($line);
        if (is_string($color['color'] ?? null) && $color['color'] !== '') {
            $style['color'] = $color['color'];
            if (is_array($color['transforms'] ?? null) && $color['transforms'] !== []) {
                $style['colorTransforms'] = $color['transforms'];
            }
        }

        $width = $this->integerAttribute($line, 'w');
        if ($width !== null) {
            $style['width'] = $width;
        }

        foreach (['cap', 'cmpd', 'algn'] as $attribute) {
            $value = trim($line->getAttribute($attribute));
            if ($value !== '') {
                $style[$attribute] = $value;
            }
        }

        $dash = $this->drawingFirstChildElement($line, 'prstDash');
        if ($dash instanceof \DOMElement && $dash->getAttribute('val') !== '') {
            $style['dash'] = $dash->getAttribute('val');
        }

        return $style;
    }

    /**
     * @return array<string, mixed>
     */
    private function drawingColorMetadata(\DOMElement $container): array
    {
        $value = $this->drawingColorValueFromElement($container);
        if ($value !== '') {
            return $this->drawingColorMetadataFromValue($container, $value);
        }

        foreach ($container->getElementsByTagName('*') as $element) {
            if (!$element instanceof \DOMElement || $element->namespaceURI !== self::NS_A) {
                continue;
            }

            $value = $this->drawingColorValueFromElement($element);
            if ($value !== '') {
                return $this->drawingColorMetadataFromValue($element, $value);
            }
        }

        return [];
    }

    /**
     * @return array<string, mixed>
     */
    private function drawingColorMetadataFromValue(\DOMElement $element, string $value): array
    {
        $metadata = ['color' => $value];
        $transforms = $this->drawingColorTransforms($element);
        if ($transforms !== []) {
            $metadata['transforms'] = $transforms;
        }

        return $metadata;
    }

    /**
     * @return array<string, int>
     */
    private function drawingColorTransforms(\DOMElement $colorElement): array
    {
        $transforms = [];
        foreach ($this->drawingChildElements($colorElement, null) as $child) {
            if (!in_array($child->localName, ['lumMod', 'lumOff', 'shade', 'tint'], true)) {
                continue;
            }

            $value = $this->integerAttribute($child, 'val');
            if ($value !== null) {
                $transforms[$child->localName] = $value;
            }
        }

        return $transforms;
    }

    private function drawingColorValueFromElement(\DOMElement $element): string
    {
        if ($element->localName === 'srgbClr') {
            $value = strtoupper(trim($element->getAttribute('val')));

            return preg_match('/^[0-9A-F]{6}$/', $value) === 1 ? $value : '';
        }

        if ($element->localName === 'sysClr') {
            $value = strtoupper(trim($element->getAttribute('lastClr')));
            if (preg_match('/^[0-9A-F]{6}$/', $value) === 1) {
                return $value;
            }

            $system = trim($element->getAttribute('val'));

            return $system !== '' ? 'system:' . $system : '';
        }

        if ($element->localName === 'schemeClr') {
            $value = trim($element->getAttribute('val'));

            return $value !== '' ? 'theme:' . $value : '';
        }

        if ($element->localName === 'prstClr') {
            $value = trim($element->getAttribute('val'));

            return $value !== '' ? 'preset:' . $value : '';
        }

        return '';
    }

    /**
     * @return list<\DOMElement>
     */
    private function chartChildElements(\DOMElement $parent, ?string $localName): array
    {
        return $this->namespaceChildElements($parent, self::NS_C, $localName);
    }

    private function chartFirstChildElement(\DOMElement $parent, string $localName): ?\DOMElement
    {
        return $this->namespaceFirstChildElement($parent, self::NS_C, $localName);
    }

    private function chartFirstDescendantElement(\DOMElement $parent, string $localName): ?\DOMElement
    {
        foreach ($parent->getElementsByTagName('*') as $child) {
            if ($child instanceof \DOMElement && $child->namespaceURI === self::NS_C && $child->localName === $localName) {
                return $child;
            }
        }

        return null;
    }

    /**
     * @return list<\DOMElement>
     */
    private function chartDescendantElements(\DOMElement $parent, string $localName): array
    {
        $elements = [];
        foreach ($parent->getElementsByTagName('*') as $child) {
            if ($child instanceof \DOMElement && $child->namespaceURI === self::NS_C && $child->localName === $localName) {
                $elements[] = $child;
            }
        }

        return $elements;
    }

    /**
     * @return list<\DOMElement>
     */
    private function drawingChildElements(\DOMElement $parent, ?string $localName): array
    {
        return $this->namespaceChildElements($parent, self::NS_A, $localName);
    }

    private function drawingFirstChildElement(\DOMElement $parent, string $localName): ?\DOMElement
    {
        return $this->namespaceFirstChildElement($parent, self::NS_A, $localName);
    }

    /**
     * @return list<\DOMElement>
     */
    private function namespaceChildElements(\DOMElement $parent, string $namespaceUri, ?string $localName): array
    {
        $children = [];
        foreach ($parent->childNodes as $child) {
            if ($child instanceof \DOMElement && $child->namespaceURI === $namespaceUri && ($localName === null || $child->localName === $localName)) {
                $children[] = $child;
            }
        }

        return $children;
    }

    private function namespaceFirstChildElement(\DOMElement $parent, string $namespaceUri, string $localName): ?\DOMElement
    {
        foreach ($parent->childNodes as $child) {
            if ($child instanceof \DOMElement && $child->namespaceURI === $namespaceUri && $child->localName === $localName) {
                return $child;
            }
        }

        return null;
    }

    private function integerAttribute(\DOMElement $element, string $name): ?int
    {
        $value = $element->getAttribute($name);

        return preg_match('/^-?\d+$/', $value) === 1 ? (int) $value : null;
    }

    private function xmlBooleanValue(string $value): bool
    {
        $value = strtolower(trim($value));

        return in_array($value, ['1', 'true', 'on'], true);
    }

    /**
     * @return array<string, mixed>
     */
    private function emptyChartEmbeddedPackageParts(): array
    {
        return [
            'count' => 0,
            'relationshipCount' => 0,
            'referencedCount' => 0,
            'unreferencedRelationshipCount' => 0,
            'existingCount' => 0,
            'missingCount' => 0,
            'externalCount' => 0,
            'missingContentTypeCount' => 0,
            'issueCount' => 0,
            'relationshipIds' => [],
            'referencedRelationshipIds' => [],
            'unreferencedRelationshipIds' => [],
            'partNames' => [],
            'externalTargets' => [],
            'contentTypes' => [],
            'issueCodes' => [],
            'byRelationshipId' => [],
            'items' => [],
            'byteExposurePolicy' => 'chart-embedded-package-bytes-blocked',
            'reviewPolicy' => 'chart-embedded-package-metadata-only',
        ];
    }

    /**
     * @param array<string, string> $parts
     * @param array<string, array{id:string, type:string, target:string, targetMode:string, resolvedTarget:string}> $relationships
     * @param array{defaults:array<string, string>, overrides:array<string, string>} $contentTypes
     * @param list<string> $referencedRelationshipIds
     * @return array<string, mixed>
     */
    private function chartEmbeddedPackageParts(
        array $parts,
        ?string $sourcePart,
        ?string $relationshipsPart,
        array $relationships,
        array $contentTypes,
        array $referencedRelationshipIds,
    ): array {
        if ($sourcePart === null || $relationshipsPart === null) {
            return $this->emptyChartEmbeddedPackageParts();
        }

        $items = [];
        $byRelationshipId = [];
        $relationshipIds = [];
        $referencedPackageRelationshipIds = [];
        $unreferencedRelationshipIds = [];
        $partNames = [];
        $externalTargets = [];
        $contentTypesSeen = [];
        $issueCodes = [];

        foreach ($relationships as $relationship) {
            if ($relationship['type'] !== self::EMBEDDED_PACKAGE_REL) {
                continue;
            }

            $relationshipId = $relationship['id'];
            $referenced = in_array($relationshipId, $referencedRelationshipIds, true);
            $item = $this->chartEmbeddedPackagePartItem(
                $parts,
                $relationship,
                $sourcePart,
                $relationshipsPart,
                $contentTypes,
                count($items),
                $referenced,
            );
            $items[] = $item;
            $byRelationshipId[$relationshipId] = $item;
            $relationshipIds[] = $relationshipId;
            if ($referenced) {
                $referencedPackageRelationshipIds[] = $relationshipId;
            } else {
                $unreferencedRelationshipIds[] = $relationshipId;
            }
            $this->appendUniqueString($partNames, is_string($item['targetPart'] ?? null) ? $item['targetPart'] : null);
            $this->appendUniqueString($contentTypesSeen, is_string($item['contentType'] ?? null) ? $item['contentType'] : null);
            if (($item['external'] ?? false) === true) {
                $this->appendUniqueString($externalTargets, is_string($item['target'] ?? null) ? $item['target'] : null);
            }
            foreach (($item['issues'] ?? []) as $issue) {
                if (is_string($issue) && $issue !== '') {
                    $issueCodes[$issue] = true;
                }
            }
        }
        ksort($issueCodes, SORT_STRING);

        return [
            'count' => count($items),
            'relationshipCount' => count($items),
            'referencedCount' => count($referencedPackageRelationshipIds),
            'unreferencedRelationshipCount' => count($unreferencedRelationshipIds),
            'existingCount' => count(array_filter($items, static fn (array $item): bool => $item['external'] === false && $item['exists'] === true)),
            'missingCount' => count(array_filter($items, static fn (array $item): bool => in_array('missing-chart-embedded-package', $item['issues'], true))),
            'externalCount' => count(array_filter($items, static fn (array $item): bool => $item['external'] === true)),
            'missingContentTypeCount' => count(array_filter($items, static fn (array $item): bool => in_array('missing-chart-embedded-package-content-type', $item['issues'], true))),
            'issueCount' => count(array_filter($items, static fn (array $item): bool => $item['issues'] !== [])),
            'relationshipIds' => $relationshipIds,
            'referencedRelationshipIds' => $referencedPackageRelationshipIds,
            'unreferencedRelationshipIds' => $unreferencedRelationshipIds,
            'partNames' => $partNames,
            'externalTargets' => $externalTargets,
            'contentTypes' => $contentTypesSeen,
            'issueCodes' => array_keys($issueCodes),
            'byRelationshipId' => $byRelationshipId,
            'items' => $items,
            'byteExposurePolicy' => 'chart-embedded-package-bytes-blocked',
            'reviewPolicy' => 'chart-embedded-package-metadata-only',
        ];
    }

    /**
     * @param array<string, string> $parts
     * @param array{id:string, type:string, target:string, targetMode:string, resolvedTarget:string} $relationship
     * @param array{defaults:array<string, string>, overrides:array<string, string>} $contentTypes
     * @return array<string, mixed>
     */
    private function chartEmbeddedPackagePartItem(
        array $parts,
        array $relationship,
        string $sourcePart,
        string $relationshipsPart,
        array $contentTypes,
        int $index,
        bool $referenced,
    ): array {
        $summary = $this->relationshipInventorySummary($parts, $relationship, $sourcePart, $relationshipsPart, $contentTypes);
        $targetPart = is_string($summary['targetPart'] ?? null) ? $summary['targetPart'] : null;
        $external = (bool) ($summary['external'] ?? false);
        $exists = (bool) ($summary['exists'] ?? false);
        $issues = [];

        if ($external) {
            $issues[] = 'external-chart-embedded-package';
        } else {
            if (!$exists) {
                $issues[] = 'missing-chart-embedded-package';
            }
            if (($summary['contentTypeSource'] ?? '') === 'missing') {
                $issues[] = 'missing-chart-embedded-package-content-type';
            }
        }

        return [
            'index' => $index,
            'source' => $sourcePart,
            'referenced' => $referenced,
            'id' => $summary['id'],
            'type' => $summary['type'],
            'target' => $summary['target'],
            'targetMode' => $summary['targetMode'],
            'resolvedTarget' => $summary['resolvedTarget'],
            'targetPart' => $targetPart,
            'targetQuery' => $summary['targetQuery'],
            'targetFragment' => $summary['targetFragment'],
            'targetReferenceSuffix' => $summary['targetReferenceSuffix'],
            'contentType' => $summary['contentType'],
            'contentTypeBase' => $summary['contentTypeBase'],
            'contentTypeHasParameters' => $summary['contentTypeHasParameters'],
            'contentTypeParameterCount' => $summary['contentTypeParameterCount'],
            'contentTypeParameters' => $summary['contentTypeParameters'],
            'contentTypeParameterMap' => $summary['contentTypeParameterMap'],
            'contentTypeSource' => $summary['contentTypeSource'],
            'defaultExtension' => $summary['defaultExtension'],
            'overridePartName' => $summary['overridePartName'],
            'external' => $external,
            'exists' => $exists,
            'relationshipsPart' => $relationshipsPart,
            'byteLength' => $targetPart !== null && $exists ? strlen($parts[$targetPart]) : null,
            'crc32' => $targetPart !== null && $exists ? sprintf('%08x', crc32($parts[$targetPart])) : null,
            'sha256' => $targetPart !== null && $exists ? hash('sha256', $parts[$targetPart]) : null,
            'byteExposurePolicy' => 'chart-embedded-package-bytes-blocked',
            'reviewPolicy' => 'chart-embedded-package-metadata-only',
            'valid' => $issues === [],
            'issues' => $issues,
            'relationship' => $summary,
        ];
    }

    /**
     * @param array<string, string> $parts
     * @param list<array{sourceType:string, sourcePart:string, relationshipsPart:string, relationships:array<string, array{id:string, type:string, target:string, targetMode:string, resolvedTarget:string}>, xml:string}> $sources
     * @param array{defaults:array<string, string>, overrides:array<string, string>} $contentTypes
     * @return array<string, mixed>
     */
    private function readDiagramParts(
        array $parts,
        array $sources,
        array $contentTypes
    ): array {
        $items = [];
        $byRelationshipId = [];
        $byRelationshipKey = [];
        $relationshipIds = [];
        $relationshipKeys = [];
        $referencedRelationshipIds = [];
        $referencedRelationshipKeys = [];
        $referencedDiagramRelationshipKeys = [];
        $sourceTypes = [];
        $sourceParts = [];
        $relationshipsParts = [];
        $relationshipCount = 0;
        $unreferencedRelationshipIds = [];
        $unreferencedRelationshipKeys = [];
        $roleDefinitions = $this->diagramRoleDefinitions();

        foreach ($sources as $source) {
            $sourceType = $source['sourceType'];
            $sourcePart = $source['sourcePart'];
            $relationshipsPart = $source['relationshipsPart'];
            $relationships = $source['relationships'];
            $this->appendUniqueString($sourceTypes, $sourceType);
            $this->appendUniqueString($sourceParts, $sourcePart);
            $this->appendUniqueString($relationshipsParts, $relationshipsPart);

            $dom = $this->loadXmlForProvenance($source['xml'], $sourcePart);
            if ($dom instanceof \DOMDocument) {
                $xpath = $this->xpath($dom);
                foreach ($this->elements($xpath, '//dgm:relIds') as $relIds) {
                    foreach ($roleDefinitions as $definition) {
                        $attribute = $definition['attribute'];
                        if (!$relIds->hasAttributeNS(self::NS_R, $attribute)) {
                            continue;
                        }

                        $relationshipId = $relIds->getAttributeNS(self::NS_R, $attribute);
                        $relationshipKey = $this->relationshipKey($relationshipsPart, $relationshipId);
                        $item = $this->diagramPartItem(
                            $parts,
                            $relationships[$relationshipId] ?? null,
                            $sourceType,
                            $sourcePart,
                            $relationshipsPart,
                            $contentTypes,
                            $relationshipId,
                            count($items),
                            true,
                            $definition,
                        );
                        $items[] = $item;

                        $this->appendUniqueString($relationshipIds, $relationshipId);
                        $this->appendUniqueString($relationshipKeys, $relationshipKey);
                        $this->appendUniqueString($referencedRelationshipIds, $relationshipId);
                        $this->appendUniqueString($referencedRelationshipKeys, $relationshipKey);
                        if ($item['relationshipType'] === $definition['relationshipType']) {
                            $this->appendUniqueString($referencedDiagramRelationshipKeys, $relationshipKey);
                        }
                        if ($relationshipId !== '' && !isset($byRelationshipId[$relationshipId])) {
                            $byRelationshipId[$relationshipId] = $item;
                        }
                        if ($relationshipKey !== '') {
                            $byRelationshipKey[$relationshipKey] = $item;
                        }
                    }
                }
            }

            foreach ($relationships as $relationship) {
                if (!$this->isDiagramRelationshipType($relationship['type'])) {
                    continue;
                }

                ++$relationshipCount;
                $relationshipId = $relationship['id'];
                $relationshipKey = $this->relationshipKey($relationshipsPart, $relationshipId);
                if (in_array($relationshipKey, $referencedDiagramRelationshipKeys, true)) {
                    continue;
                }

                $definition = $this->diagramRoleDefinitionForRelationshipType($relationship['type']);
                if ($definition === null) {
                    continue;
                }

                $item = $this->diagramPartItem(
                    $parts,
                    $relationship,
                    $sourceType,
                    $sourcePart,
                    $relationshipsPart,
                    $contentTypes,
                    $relationshipId,
                    count($items),
                    false,
                    $definition,
                );
                $items[] = $item;

                $this->appendUniqueString($relationshipIds, $relationshipId);
                $this->appendUniqueString($relationshipKeys, $relationshipKey);
                $this->appendUniqueString($unreferencedRelationshipIds, $relationshipId);
                $this->appendUniqueString($unreferencedRelationshipKeys, $relationshipKey);
                if (!isset($byRelationshipId[$relationshipId])) {
                    $byRelationshipId[$relationshipId] = $item;
                }
                if ($relationshipKey !== '') {
                    $byRelationshipKey[$relationshipKey] = $item;
                }
            }
        }

        $partNames = [];
        $externalTargets = [];
        $contentTypesSeen = [];
        $roleCounts = [];
        $sourceTypeCounts = [];
        $issueCodes = [];
        $embeddedPackageRelationshipIds = [];
        $embeddedPackagePartNames = [];
        $embeddedPackageExternalTargets = [];
        $embeddedPackageIssueCodes = [];
        $embeddedPackageCount = 0;
        $embeddedPackageExistingCount = 0;
        $embeddedPackageMissingCount = 0;
        $embeddedPackageExternalCount = 0;
        $embeddedPackageIssueCount = 0;
        foreach ($items as $item) {
            $role = is_string($item['role'] ?? null) ? $item['role'] : '';
            if ($role !== '') {
                $roleCounts[$role] = ($roleCounts[$role] ?? 0) + 1;
            }
            $itemSourceType = is_string($item['sourceType'] ?? null) ? $item['sourceType'] : '';
            if ($itemSourceType !== '') {
                $sourceTypeCounts[$itemSourceType] = ($sourceTypeCounts[$itemSourceType] ?? 0) + 1;
            }
            if ($this->isDiagramRelationshipType((string) ($item['relationshipType'] ?? ''))) {
                $this->appendUniqueString($partNames, is_string($item['partName'] ?? null) ? $item['partName'] : null);
            }
            $this->appendUniqueString($contentTypesSeen, is_string($item['contentType'] ?? null) ? $item['contentType'] : null);
            if (($item['external'] ?? false) === true) {
                $this->appendUniqueString($externalTargets, is_string($item['target'] ?? null) ? $item['target'] : null);
            }
            foreach (($item['issues'] ?? []) as $issue) {
                if (is_string($issue) && $issue !== '') {
                    $issueCodes[$issue] = true;
                }
            }
            $embeddedPackages = is_array($item['embeddedPackages'] ?? null) ? $item['embeddedPackages'] : [];
            $embeddedPackageCount += (int) ($embeddedPackages['count'] ?? 0);
            $embeddedPackageExistingCount += (int) ($embeddedPackages['existingCount'] ?? 0);
            $embeddedPackageMissingCount += (int) ($embeddedPackages['missingCount'] ?? 0);
            $embeddedPackageExternalCount += (int) ($embeddedPackages['externalCount'] ?? 0);
            $embeddedPackageIssueCount += (int) ($embeddedPackages['issueCount'] ?? 0);
            foreach (($embeddedPackages['relationshipIds'] ?? []) as $packageRelationshipId) {
                $this->appendUniqueString($embeddedPackageRelationshipIds, is_string($packageRelationshipId) ? $packageRelationshipId : null);
            }
            foreach (($embeddedPackages['partNames'] ?? []) as $partName) {
                $this->appendUniqueString($embeddedPackagePartNames, is_string($partName) ? $partName : null);
            }
            foreach (($embeddedPackages['externalTargets'] ?? []) as $target) {
                $this->appendUniqueString($embeddedPackageExternalTargets, is_string($target) ? $target : null);
            }
            foreach (($embeddedPackages['issueCodes'] ?? []) as $issue) {
                if (is_string($issue) && $issue !== '') {
                    $embeddedPackageIssueCodes[$issue] = true;
                }
            }
        }
        ksort($sourceTypeCounts, SORT_STRING);
        ksort($roleCounts, SORT_STRING);
        ksort($issueCodes, SORT_STRING);
        ksort($embeddedPackageIssueCodes, SORT_STRING);

        return [
            'count' => count($items),
            'relationshipCount' => $relationshipCount,
            'sourcePartCount' => count($sourceParts),
            'sourceTypes' => $sourceTypes,
            'sourceTypeCounts' => $sourceTypeCounts,
            'sourceParts' => $sourceParts,
            'relationshipsParts' => $relationshipsParts,
            'referencedCount' => count(array_filter($items, static fn (array $item): bool => $item['referenced'] === true)),
            'unreferencedRelationshipCount' => count($unreferencedRelationshipIds),
            'existingCount' => count(array_filter($items, fn (array $item): bool => $this->isDiagramRelationshipType((string) ($item['relationshipType'] ?? '')) && $item['external'] === false && $item['exists'] === true)),
            'missingCount' => count(array_filter($items, static fn (array $item): bool => in_array('missing-diagram-part', $item['issues'], true))),
            'externalCount' => count(array_filter($items, fn (array $item): bool => $this->isDiagramRelationshipType((string) ($item['relationshipType'] ?? '')) && $item['external'] === true)),
            'unresolvedCount' => count(array_filter(
                $items,
                static fn (array $item): bool => in_array('missing-relationship-id', $item['issues'], true) || in_array('unknown-relationship', $item['issues'], true),
            )),
            'invalidXmlCount' => count(array_filter($items, static fn (array $item): bool => in_array('invalid-diagram-xml', $item['issues'], true))),
            'unexpectedRootCount' => count(array_filter($items, static fn (array $item): bool => in_array('unexpected-diagram-root', $item['issues'], true))),
            'unexpectedRelationshipTypeCount' => count(array_filter($items, static fn (array $item): bool => in_array('unexpected-relationship-type', $item['issues'], true))),
            'missingContentTypeCount' => count(array_filter($items, static fn (array $item): bool => in_array('missing-diagram-content-type', $item['issues'], true))),
            'unexpectedContentTypeCount' => count(array_filter($items, static fn (array $item): bool => in_array('unexpected-diagram-content-type', $item['issues'], true))),
            'issueCount' => count(array_filter($items, static fn (array $item): bool => $item['issues'] !== [])),
            'relationshipIds' => $relationshipIds,
            'relationshipKeys' => $relationshipKeys,
            'referencedRelationshipIds' => $referencedRelationshipIds,
            'referencedRelationshipKeys' => $referencedRelationshipKeys,
            'unreferencedRelationshipIds' => $unreferencedRelationshipIds,
            'unreferencedRelationshipKeys' => $unreferencedRelationshipKeys,
            'partNames' => $partNames,
            'externalTargets' => $externalTargets,
            'contentTypes' => $contentTypesSeen,
            'roleCounts' => $roleCounts,
            'embeddedPackageCount' => $embeddedPackageCount,
            'embeddedPackageExistingCount' => $embeddedPackageExistingCount,
            'embeddedPackageMissingCount' => $embeddedPackageMissingCount,
            'embeddedPackageExternalCount' => $embeddedPackageExternalCount,
            'embeddedPackageIssueCount' => $embeddedPackageIssueCount,
            'embeddedPackageRelationshipIds' => $embeddedPackageRelationshipIds,
            'embeddedPackagePartNames' => $embeddedPackagePartNames,
            'embeddedPackageExternalTargets' => $embeddedPackageExternalTargets,
            'embeddedPackageIssueCodes' => array_keys($embeddedPackageIssueCodes),
            'issueCodes' => array_keys($issueCodes),
            'byRelationshipId' => $byRelationshipId,
            'byRelationshipKey' => $byRelationshipKey,
            'items' => $items,
            'byteExposurePolicy' => 'diagram-part-bytes-blocked',
            'reviewPolicy' => 'diagram-part-metadata-only',
        ];
    }

    /**
     * @param array<string, string> $parts
     * @param array{id:string, type:string, target:string, targetMode:string, resolvedTarget:string}|null $relationship
     * @param array{defaults:array<string, string>, overrides:array<string, string>} $contentTypes
     * @param array{attribute:string, role:string, relationshipType:string, contentTypeBase:string, rootLocalName:string} $definition
     * @return array<string, mixed>
     */
    private function diagramPartItem(
        array $parts,
        ?array $relationship,
        string $sourceType,
        string $sourcePart,
        string $relationshipsPart,
        array $contentTypes,
        string $relationshipId,
        int $index,
        bool $referenced,
        array $definition,
    ): array {
        $item = [
            'index' => $index,
            'relationshipId' => $relationshipId,
            'relationshipKey' => $this->relationshipKey($relationshipsPart, $relationshipId),
            'sourceType' => $sourceType,
            'sourcePart' => $sourcePart,
            'referenced' => $referenced,
            'role' => $definition['role'],
            'attributeName' => $definition['attribute'],
            'relationshipType' => null,
            'expectedRelationshipType' => $definition['relationshipType'],
            'target' => null,
            'targetMode' => null,
            'resolvedTarget' => null,
            'external' => false,
            'partName' => null,
            'targetPart' => null,
            'targetQuery' => null,
            'targetFragment' => null,
            'targetReferenceSuffix' => '',
            'exists' => false,
            'byteLength' => null,
            'crc32' => null,
            'sha256' => null,
            'contentType' => '',
            'contentTypeBase' => '',
            'contentTypeHasParameters' => false,
            'contentTypeParameterCount' => 0,
            'contentTypeParameters' => [],
            'contentTypeParameterMap' => [],
            'contentTypeSource' => 'missing',
            'defaultExtension' => null,
            'overridePartName' => null,
            'expectedContentTypeBase' => $definition['contentTypeBase'],
            'relationshipsPart' => $relationshipsPart,
            'diagramRelationshipsPart' => null,
            'diagramRelationshipCount' => 0,
            'embeddedPackageRelationshipIds' => [],
            'embeddedPackages' => $this->emptyDiagramEmbeddedPackageParts(),
            'validXml' => null,
            'xmlParseError' => null,
            'rootNamespace' => null,
            'rootLocalName' => null,
            'expectedRootLocalName' => $definition['rootLocalName'],
            'validRoot' => null,
            'byteExposurePolicy' => 'diagram-part-bytes-blocked',
            'reviewPolicy' => 'diagram-part-metadata-only',
            'valid' => false,
            'issues' => [],
            'relationship' => null,
        ];

        if ($relationshipId === '') {
            $item['issues'][] = 'missing-relationship-id';
            return $item;
        }

        if (!is_array($relationship)) {
            $item['issues'][] = 'unknown-relationship';
            return $item;
        }

        $summary = $this->relationshipInventorySummary($parts, $relationship, $sourcePart, $relationshipsPart, $contentTypes);
        $targetPart = is_string($summary['targetPart'] ?? null) ? $summary['targetPart'] : null;
        $exists = (bool) $summary['exists'];
        $diagramRelationshipsPart = $targetPart === null ? null : $this->relationshipsPartFor($targetPart);
        $diagramRelationships = $diagramRelationshipsPart === null || (bool) $summary['external']
            ? []
            : $this->readRelationshipsPart($parts, $diagramRelationshipsPart);

        $item['relationshipType'] = $summary['type'];
        $item['target'] = $summary['target'];
        $item['targetMode'] = $summary['targetMode'];
        $item['resolvedTarget'] = $summary['resolvedTarget'];
        $item['external'] = (bool) $summary['external'];
        $item['partName'] = $targetPart;
        $item['targetPart'] = $targetPart;
        $item['targetQuery'] = $summary['targetQuery'];
        $item['targetFragment'] = $summary['targetFragment'];
        $item['targetReferenceSuffix'] = $summary['targetReferenceSuffix'];
        $item['exists'] = $exists;
        $item['byteLength'] = $targetPart !== null && $exists ? strlen($parts[$targetPart]) : null;
        $item['crc32'] = $targetPart !== null && $exists ? sprintf('%08x', crc32($parts[$targetPart])) : null;
        $item['sha256'] = $targetPart !== null && $exists ? hash('sha256', $parts[$targetPart]) : null;
        $item['contentType'] = $summary['contentType'];
        $item['contentTypeBase'] = $summary['contentTypeBase'];
        $item['contentTypeHasParameters'] = $summary['contentTypeHasParameters'];
        $item['contentTypeParameterCount'] = $summary['contentTypeParameterCount'];
        $item['contentTypeParameters'] = $summary['contentTypeParameters'];
        $item['contentTypeParameterMap'] = $summary['contentTypeParameterMap'];
        $item['contentTypeSource'] = $summary['contentTypeSource'];
        $item['defaultExtension'] = $summary['defaultExtension'];
        $item['overridePartName'] = $summary['overridePartName'];
        $item['diagramRelationshipsPart'] = $diagramRelationshipsPart;
        $item['diagramRelationshipCount'] = count($diagramRelationships);
        $item['relationship'] = $summary;

        if ($relationship['type'] !== $definition['relationshipType']) {
            $item['issues'][] = 'unexpected-relationship-type';
            return $item;
        }

        if ($item['external'] === true) {
            $item['issues'][] = 'external-diagram-part';
            return $item;
        }

        if (!$exists) {
            $item['issues'][] = 'missing-diagram-part';
        }

        $contentTypeBase = is_string($summary['contentTypeBase'] ?? null) ? $summary['contentTypeBase'] : '';
        if (($summary['contentTypeSource'] ?? '') === 'missing') {
            $item['issues'][] = 'missing-diagram-content-type';
        } elseif ($contentTypeBase !== $definition['contentTypeBase']) {
            $item['issues'][] = 'unexpected-diagram-content-type';
        }

        if ($exists && $targetPart !== null) {
            $root = $this->xmlRootProvenance($parts[$targetPart], $targetPart);
            $item['validXml'] = $root['validXml'];
            $item['xmlParseError'] = $root['xmlParseError'];
            $item['rootNamespace'] = $root['namespace'];
            $item['rootLocalName'] = $root['localName'];
            $item['validRoot'] = $root['namespace'] === self::NS_DGM && $root['localName'] === $definition['rootLocalName'];
            if ($root['validXml'] === false) {
                $item['issues'][] = 'invalid-diagram-xml';
            } elseif ($item['validRoot'] === false) {
                $item['issues'][] = 'unexpected-diagram-root';
            } else {
                $item['embeddedPackageRelationshipIds'] = $this->diagramEmbeddedPackageRelationshipIds($parts[$targetPart], $targetPart);
            }
        }

        $item['embeddedPackages'] = $this->diagramEmbeddedPackageParts(
            $parts,
            $targetPart,
            $diagramRelationshipsPart,
            $diagramRelationships,
            $contentTypes,
            $item['embeddedPackageRelationshipIds'],
        );
        $item['valid'] = $item['issues'] === [] && (int) $item['embeddedPackages']['issueCount'] === 0;

        return $item;
    }

    /**
     * @return list<string>
     */
    private function diagramEmbeddedPackageRelationshipIds(string $xml, string $partName): array
    {
        $dom = $this->loadXmlForProvenance($xml, $partName);
        if (!$dom instanceof \DOMDocument || !$dom->documentElement instanceof \DOMElement) {
            return [];
        }

        return $this->relationshipIdsInElement($dom->documentElement);
    }

    /**
     * @return array<string, mixed>
     */
    private function emptyDiagramEmbeddedPackageParts(): array
    {
        return [
            'count' => 0,
            'relationshipCount' => 0,
            'referencedCount' => 0,
            'unreferencedRelationshipCount' => 0,
            'existingCount' => 0,
            'missingCount' => 0,
            'externalCount' => 0,
            'missingContentTypeCount' => 0,
            'issueCount' => 0,
            'relationshipIds' => [],
            'referencedRelationshipIds' => [],
            'unreferencedRelationshipIds' => [],
            'partNames' => [],
            'externalTargets' => [],
            'contentTypes' => [],
            'issueCodes' => [],
            'byRelationshipId' => [],
            'items' => [],
            'byteExposurePolicy' => 'diagram-embedded-package-bytes-blocked',
            'reviewPolicy' => 'diagram-embedded-package-metadata-only',
        ];
    }

    /**
     * @param array<string, string> $parts
     * @param array<string, array{id:string, type:string, target:string, targetMode:string, resolvedTarget:string}> $relationships
     * @param array{defaults:array<string, string>, overrides:array<string, string>} $contentTypes
     * @param list<string> $referencedRelationshipIds
     * @return array<string, mixed>
     */
    private function diagramEmbeddedPackageParts(
        array $parts,
        ?string $sourcePart,
        ?string $relationshipsPart,
        array $relationships,
        array $contentTypes,
        array $referencedRelationshipIds,
    ): array {
        if ($sourcePart === null || $relationshipsPart === null) {
            return $this->emptyDiagramEmbeddedPackageParts();
        }

        $items = [];
        $byRelationshipId = [];
        $relationshipIds = [];
        $referencedPackageRelationshipIds = [];
        $unreferencedRelationshipIds = [];
        $partNames = [];
        $externalTargets = [];
        $contentTypesSeen = [];
        $issueCodes = [];

        foreach ($relationships as $relationship) {
            if ($relationship['type'] !== self::EMBEDDED_PACKAGE_REL) {
                continue;
            }

            $relationshipId = $relationship['id'];
            $referenced = in_array($relationshipId, $referencedRelationshipIds, true);
            $item = $this->diagramEmbeddedPackagePartItem(
                $parts,
                $relationship,
                $sourcePart,
                $relationshipsPart,
                $contentTypes,
                count($items),
                $referenced,
            );
            $items[] = $item;
            $byRelationshipId[$relationshipId] = $item;
            $relationshipIds[] = $relationshipId;
            if ($referenced) {
                $referencedPackageRelationshipIds[] = $relationshipId;
            } else {
                $unreferencedRelationshipIds[] = $relationshipId;
            }
            $this->appendUniqueString($partNames, is_string($item['targetPart'] ?? null) ? $item['targetPart'] : null);
            $this->appendUniqueString($contentTypesSeen, is_string($item['contentType'] ?? null) ? $item['contentType'] : null);
            if (($item['external'] ?? false) === true) {
                $this->appendUniqueString($externalTargets, is_string($item['target'] ?? null) ? $item['target'] : null);
            }
            foreach (($item['issues'] ?? []) as $issue) {
                if (is_string($issue) && $issue !== '') {
                    $issueCodes[$issue] = true;
                }
            }
        }
        ksort($issueCodes, SORT_STRING);

        return [
            'count' => count($items),
            'relationshipCount' => count($items),
            'referencedCount' => count($referencedPackageRelationshipIds),
            'unreferencedRelationshipCount' => count($unreferencedRelationshipIds),
            'existingCount' => count(array_filter($items, static fn (array $item): bool => $item['external'] === false && $item['exists'] === true)),
            'missingCount' => count(array_filter($items, static fn (array $item): bool => in_array('missing-diagram-embedded-package', $item['issues'], true))),
            'externalCount' => count(array_filter($items, static fn (array $item): bool => $item['external'] === true)),
            'missingContentTypeCount' => count(array_filter($items, static fn (array $item): bool => in_array('missing-diagram-embedded-package-content-type', $item['issues'], true))),
            'issueCount' => count(array_filter($items, static fn (array $item): bool => $item['issues'] !== [])),
            'relationshipIds' => $relationshipIds,
            'referencedRelationshipIds' => $referencedPackageRelationshipIds,
            'unreferencedRelationshipIds' => $unreferencedRelationshipIds,
            'partNames' => $partNames,
            'externalTargets' => $externalTargets,
            'contentTypes' => $contentTypesSeen,
            'issueCodes' => array_keys($issueCodes),
            'byRelationshipId' => $byRelationshipId,
            'items' => $items,
            'byteExposurePolicy' => 'diagram-embedded-package-bytes-blocked',
            'reviewPolicy' => 'diagram-embedded-package-metadata-only',
        ];
    }

    /**
     * @param array<string, string> $parts
     * @param array{id:string, type:string, target:string, targetMode:string, resolvedTarget:string} $relationship
     * @param array{defaults:array<string, string>, overrides:array<string, string>} $contentTypes
     * @return array<string, mixed>
     */
    private function diagramEmbeddedPackagePartItem(
        array $parts,
        array $relationship,
        string $sourcePart,
        string $relationshipsPart,
        array $contentTypes,
        int $index,
        bool $referenced,
    ): array {
        $summary = $this->relationshipInventorySummary($parts, $relationship, $sourcePart, $relationshipsPart, $contentTypes);
        $targetPart = is_string($summary['targetPart'] ?? null) ? $summary['targetPart'] : null;
        $external = (bool) ($summary['external'] ?? false);
        $exists = (bool) ($summary['exists'] ?? false);
        $issues = [];

        if ($external) {
            $issues[] = 'external-diagram-embedded-package';
        } else {
            if (!$exists) {
                $issues[] = 'missing-diagram-embedded-package';
            }
            if (($summary['contentTypeSource'] ?? '') === 'missing') {
                $issues[] = 'missing-diagram-embedded-package-content-type';
            }
        }

        return [
            'index' => $index,
            'source' => $sourcePart,
            'referenced' => $referenced,
            'id' => $summary['id'],
            'type' => $summary['type'],
            'target' => $summary['target'],
            'targetMode' => $summary['targetMode'],
            'resolvedTarget' => $summary['resolvedTarget'],
            'targetPart' => $targetPart,
            'targetQuery' => $summary['targetQuery'],
            'targetFragment' => $summary['targetFragment'],
            'targetReferenceSuffix' => $summary['targetReferenceSuffix'],
            'contentType' => $summary['contentType'],
            'contentTypeBase' => $summary['contentTypeBase'],
            'contentTypeHasParameters' => $summary['contentTypeHasParameters'],
            'contentTypeParameterCount' => $summary['contentTypeParameterCount'],
            'contentTypeParameters' => $summary['contentTypeParameters'],
            'contentTypeParameterMap' => $summary['contentTypeParameterMap'],
            'contentTypeSource' => $summary['contentTypeSource'],
            'defaultExtension' => $summary['defaultExtension'],
            'overridePartName' => $summary['overridePartName'],
            'external' => $external,
            'exists' => $exists,
            'relationshipsPart' => $relationshipsPart,
            'byteLength' => $targetPart !== null && $exists ? strlen($parts[$targetPart]) : null,
            'crc32' => $targetPart !== null && $exists ? sprintf('%08x', crc32($parts[$targetPart])) : null,
            'sha256' => $targetPart !== null && $exists ? hash('sha256', $parts[$targetPart]) : null,
            'byteExposurePolicy' => 'diagram-embedded-package-bytes-blocked',
            'reviewPolicy' => 'diagram-embedded-package-metadata-only',
            'valid' => $issues === [],
            'issues' => $issues,
            'relationship' => $summary,
        ];
    }

    /**
     * @return array<string, array{attribute:string, role:string, relationshipType:string, contentTypeBase:string, rootLocalName:string}>
     */
    private function diagramRoleDefinitions(): array
    {
        return [
            'data' => [
                'attribute' => 'dm',
                'role' => 'data',
                'relationshipType' => self::DIAGRAM_DATA_REL,
                'contentTypeBase' => self::CT_DIAGRAM_DATA,
                'rootLocalName' => 'dataModel',
            ],
            'layout' => [
                'attribute' => 'lo',
                'role' => 'layout',
                'relationshipType' => self::DIAGRAM_LAYOUT_REL,
                'contentTypeBase' => self::CT_DIAGRAM_LAYOUT,
                'rootLocalName' => 'layoutDef',
            ],
            'quick-style' => [
                'attribute' => 'qs',
                'role' => 'quick-style',
                'relationshipType' => self::DIAGRAM_QUICK_STYLE_REL,
                'contentTypeBase' => self::CT_DIAGRAM_QUICK_STYLE,
                'rootLocalName' => 'styleDef',
            ],
            'colors' => [
                'attribute' => 'cs',
                'role' => 'colors',
                'relationshipType' => self::DIAGRAM_COLORS_REL,
                'contentTypeBase' => self::CT_DIAGRAM_COLORS,
                'rootLocalName' => 'colorsDef',
            ],
        ];
    }

    /**
     * @return array{attribute:string, role:string, relationshipType:string, contentTypeBase:string, rootLocalName:string}|null
     */
    private function diagramRoleDefinitionForRelationshipType(string $relationshipType): ?array
    {
        foreach ($this->diagramRoleDefinitions() as $definition) {
            if ($definition['relationshipType'] === $relationshipType) {
                return $definition;
            }
        }

        return null;
    }

    private function isDiagramRelationshipType(string $relationshipType): bool
    {
        return $relationshipType === self::DIAGRAM_DATA_REL
            || $relationshipType === self::DIAGRAM_LAYOUT_REL
            || $relationshipType === self::DIAGRAM_QUICK_STYLE_REL
            || $relationshipType === self::DIAGRAM_COLORS_REL;
    }

    /**
     * @param array<string, string> $parts
     * @param array<string, array{id:string, type:string, target:string, targetMode:string, resolvedTarget:string}> $relationships
     * @param array{defaults:array<string, string>, overrides:array<string, string>} $contentTypes
     * @return array<string, mixed>
     */
    private function readActiveXControls(
        array $parts,
        string $xml,
        string $documentPart,
        array $relationships,
        array $contentTypes
    ): array {
        $items = [];
        $byRelationshipId = [];
        $relationshipIds = [];
        $referencedRelationshipIds = [];
        $referencedActiveXRelationshipIds = [];
        $relationshipsPart = $this->relationshipsPartFor($documentPart);

        if ($xml !== '') {
            $dom = $this->loadXml($xml, $documentPart);
            $xpath = $this->xpath($dom);
            foreach ($this->elements($xpath, '//w:control') as $control) {
                $relationshipId = $this->activeXRelationshipId($control);
                $item = $this->activeXControlItem(
                    $parts,
                    $relationships[$relationshipId] ?? null,
                    $documentPart,
                    $relationshipsPart,
                    $contentTypes,
                    $relationshipId,
                    count($items),
                    true,
                    $this->activeXControlDescriptor($control),
                );
                $items[] = $item;

                $this->appendUniqueString($relationshipIds, $relationshipId);
                $this->appendUniqueString($referencedRelationshipIds, $relationshipId);
                if ($item['relationshipType'] === self::ACTIVEX_CONTROL_REL) {
                    $this->appendUniqueString($referencedActiveXRelationshipIds, $relationshipId);
                }
                if ($relationshipId !== '' && !isset($byRelationshipId[$relationshipId])) {
                    $byRelationshipId[$relationshipId] = $item;
                }
            }
        }

        $unreferencedRelationshipIds = [];
        foreach ($relationships as $relationship) {
            if ($relationship['type'] !== self::ACTIVEX_CONTROL_REL) {
                continue;
            }

            $relationshipId = $relationship['id'];
            if (in_array($relationshipId, $referencedActiveXRelationshipIds, true)) {
                continue;
            }

            $item = $this->activeXControlItem(
                $parts,
                $relationship,
                $documentPart,
                $relationshipsPart,
                $contentTypes,
                $relationshipId,
                count($items),
                false,
                null,
            );
            $items[] = $item;

            $this->appendUniqueString($relationshipIds, $relationshipId);
            $this->appendUniqueString($unreferencedRelationshipIds, $relationshipId);
            if (!isset($byRelationshipId[$relationshipId])) {
                $byRelationshipId[$relationshipId] = $item;
            }
        }

        $partNames = [];
        $binaryPartNames = [];
        $externalTargets = [];
        $unsafeBinaryExternalTargets = [];
        $contentTypesSeen = [];
        $ocxClassIds = [];
        $ocxPersistenceModes = [];
        $ocxPersistenceModeCounts = [];
        $issueCodes = [];
        $binaryExternalTargetIssueCodes = [];
        $allowedExternalBinaryCount = 0;
        $unsafeExternalBinaryCount = 0;
        foreach ($items as $item) {
            $this->appendUniqueString($partNames, is_string($item['partName'] ?? null) ? $item['partName'] : null);
            $this->appendUniqueString($contentTypesSeen, is_string($item['contentType'] ?? null) ? $item['contentType'] : null);
            $this->appendUniqueString($ocxClassIds, is_string($item['ocxClassId'] ?? null) ? $item['ocxClassId'] : null);
            $ocxPersistence = is_string($item['ocxPersistence'] ?? null) ? $item['ocxPersistence'] : null;
            $this->appendUniqueString($ocxPersistenceModes, $ocxPersistence);
            if ($ocxPersistence !== null) {
                $ocxPersistenceModeCounts[$ocxPersistence] = ($ocxPersistenceModeCounts[$ocxPersistence] ?? 0) + 1;
            }
            if (($item['external'] ?? false) === true) {
                $this->appendUniqueString($externalTargets, is_string($item['target'] ?? null) ? $item['target'] : null);
            }
            foreach (($item['issues'] ?? []) as $issue) {
                if (is_string($issue) && $issue !== '') {
                    $issueCodes[$issue] = true;
                }
            }
            foreach (($item['binaries']['items'] ?? []) as $binary) {
                if (!is_array($binary)) {
                    continue;
                }
                $this->appendUniqueString($binaryPartNames, is_string($binary['targetPart'] ?? null) ? $binary['targetPart'] : null);
                $this->appendUniqueString($contentTypesSeen, is_string($binary['contentType'] ?? null) ? $binary['contentType'] : null);
                if (($binary['external'] ?? false) === true) {
                    $this->appendUniqueString($externalTargets, is_string($binary['target'] ?? null) ? $binary['target'] : null);
                    if (($binary['externalTargetAllowed'] ?? null) === true) {
                        ++$allowedExternalBinaryCount;
                    } else {
                        ++$unsafeExternalBinaryCount;
                        $this->appendUniqueString($unsafeBinaryExternalTargets, is_string($binary['target'] ?? null) ? $binary['target'] : null);
                    }
                    foreach (($binary['externalTargetIssues'] ?? []) as $issue) {
                        if (is_string($issue) && $issue !== '') {
                            $binaryExternalTargetIssueCodes[$issue] = true;
                        }
                    }
                }
                foreach (($binary['issues'] ?? []) as $issue) {
                    if (is_string($issue) && $issue !== '') {
                        $issueCodes[$issue] = true;
                    }
                }
            }
        }
        ksort($issueCodes, SORT_STRING);
        ksort($binaryExternalTargetIssueCodes, SORT_STRING);
        ksort($ocxPersistenceModeCounts, SORT_STRING);

        return [
            'count' => count($items),
            'relationshipCount' => count(array_filter($relationships, static fn (array $relationship): bool => $relationship['type'] === self::ACTIVEX_CONTROL_REL)),
            'referencedCount' => count(array_filter($items, static fn (array $item): bool => $item['referenced'] === true)),
            'unreferencedRelationshipCount' => count($unreferencedRelationshipIds),
            'existingCount' => count(array_filter($items, static fn (array $item): bool => $item['relationshipType'] === self::ACTIVEX_CONTROL_REL && $item['external'] === false && $item['exists'] === true)),
            'missingCount' => count(array_filter($items, static fn (array $item): bool => in_array('missing-control-part', $item['issues'], true))),
            'externalCount' => count(array_filter($items, static fn (array $item): bool => $item['relationshipType'] === self::ACTIVEX_CONTROL_REL && $item['external'] === true)),
            'unresolvedCount' => count(array_filter(
                $items,
                static fn (array $item): bool => in_array('missing-relationship-id', $item['issues'], true) || in_array('unknown-relationship', $item['issues'], true),
            )),
            'invalidXmlCount' => count(array_filter($items, static fn (array $item): bool => in_array('invalid-control-xml', $item['issues'], true))),
            'unexpectedRootCount' => count(array_filter($items, static fn (array $item): bool => in_array('unexpected-control-root', $item['issues'], true))),
            'unexpectedRelationshipTypeCount' => count(array_filter($items, static fn (array $item): bool => in_array('unexpected-relationship-type', $item['issues'], true))),
            'missingContentTypeCount' => count(array_filter($items, static fn (array $item): bool => in_array('missing-control-content-type', $item['issues'], true))),
            'unexpectedContentTypeCount' => count(array_filter($items, static fn (array $item): bool => in_array('unexpected-control-content-type', $item['issues'], true))),
            'binaryCount' => array_sum(array_map(static fn (array $item): int => (int) ($item['binaries']['count'] ?? 0), $items)),
            'existingBinaryCount' => array_sum(array_map(static fn (array $item): int => (int) ($item['binaries']['existingCount'] ?? 0), $items)),
            'missingBinaryCount' => array_sum(array_map(static fn (array $item): int => (int) ($item['binaries']['missingCount'] ?? 0), $items)),
            'externalBinaryCount' => array_sum(array_map(static fn (array $item): int => (int) ($item['binaries']['externalCount'] ?? 0), $items)),
            'allowedExternalBinaryCount' => $allowedExternalBinaryCount,
            'unsafeExternalBinaryCount' => $unsafeExternalBinaryCount,
            'unexpectedBinaryContentTypeCount' => array_sum(array_map(static fn (array $item): int => (int) ($item['binaries']['unexpectedContentTypeCount'] ?? 0), $items)),
            'issueCount' => count(array_filter(
                $items,
                static fn (array $item): bool => $item['issues'] !== [] || (int) ($item['binaries']['issueCount'] ?? 0) > 0,
            )),
            'relationshipIds' => $relationshipIds,
            'referencedRelationshipIds' => $referencedRelationshipIds,
            'unreferencedRelationshipIds' => $unreferencedRelationshipIds,
            'partNames' => $partNames,
            'binaryPartNames' => $binaryPartNames,
            'externalTargets' => $externalTargets,
            'unsafeBinaryExternalTargets' => $unsafeBinaryExternalTargets,
            'ocxClassIdCount' => count($ocxClassIds),
            'ocxClassIds' => $ocxClassIds,
            'ocxPersistenceModes' => $ocxPersistenceModes,
            'ocxPersistenceModeCounts' => $ocxPersistenceModeCounts,
            'contentTypes' => $contentTypesSeen,
            'issueCodes' => array_keys($issueCodes),
            'binaryExternalTargetIssueCodes' => array_keys($binaryExternalTargetIssueCodes),
            'byRelationshipId' => $byRelationshipId,
            'items' => $items,
            'byteExposurePolicy' => 'activex-bytes-blocked',
            'reviewPolicy' => 'activex-metadata-only',
        ];
    }

    /**
     * @return string
     */
    private function activeXRelationshipId(\DOMElement $control): string
    {
        $relationshipId = trim($control->getAttributeNS(self::NS_R, 'id'));
        if ($relationshipId !== '') {
            return $relationshipId;
        }

        return trim($control->getAttribute('id'));
    }

    /**
     * @return ?string
     */
    private function activeXControlAttribute(\DOMElement $control, string $localName): ?string
    {
        $value = $this->emptyStringToNull($control->getAttributeNS(self::NS_W, $localName));
        if ($value !== null) {
            return $value;
        }

        return $this->emptyStringToNull($control->getAttribute($localName));
    }

    /**
     * @return array{controlName:?string, shapeId:?string}
     */
    private function activeXControlDescriptor(\DOMElement $control): array
    {
        return [
            'controlName' => $this->activeXControlAttribute($control, 'name'),
            'shapeId' => $this->activeXControlAttribute($control, 'shapeid'),
        ];
    }

    /**
     * @return ?string
     */
    private function activeXPartRootAttribute(\DOMElement $root, string $localName): ?string
    {
        $value = $this->emptyStringToNull($root->getAttributeNS(self::NS_ACTIVEX, $localName));
        if ($value !== null) {
            return $value;
        }

        return $this->emptyStringToNull($root->getAttribute($localName));
    }

    /**
     * @param array<string, string> $parts
     * @param array{id:string, type:string, target:string, targetMode:string, resolvedTarget:string}|null $relationship
     * @param array{defaults:array<string, string>, overrides:array<string, string>} $contentTypes
     * @param array{controlName:?string, shapeId:?string}|null $descriptor
     * @return array<string, mixed>
     */
    private function activeXControlItem(
        array $parts,
        ?array $relationship,
        string $documentPart,
        string $relationshipsPart,
        array $contentTypes,
        string $relationshipId,
        int $index,
        bool $referenced,
        ?array $descriptor
    ): array {
        $item = [
            'index' => $index,
            'relationshipId' => $relationshipId,
            'referenced' => $referenced,
            'controlName' => $descriptor['controlName'] ?? null,
            'shapeId' => $descriptor['shapeId'] ?? null,
            'relationshipType' => null,
            'target' => null,
            'targetMode' => null,
            'resolvedTarget' => null,
            'external' => false,
            'partName' => null,
            'targetPart' => null,
            'targetQuery' => null,
            'targetFragment' => null,
            'targetReferenceSuffix' => '',
            'exists' => false,
            'byteLength' => null,
            'crc32' => null,
            'sha256' => null,
            'contentType' => '',
            'contentTypeBase' => '',
            'contentTypeHasParameters' => false,
            'contentTypeParameterCount' => 0,
            'contentTypeParameters' => [],
            'contentTypeParameterMap' => [],
            'contentTypeSource' => 'missing',
            'defaultExtension' => null,
            'overridePartName' => null,
            'expectedContentTypeBase' => self::CT_ACTIVEX_XML,
            'relationshipsPart' => null,
            'controlRelationshipsPart' => null,
            'controlRelationshipCount' => 0,
            'validXml' => null,
            'xmlParseError' => null,
            'rootNamespace' => null,
            'rootLocalName' => null,
            'ocxClassId' => null,
            'ocxPersistence' => null,
            'validRoot' => null,
            'binaries' => $this->emptyActiveXBinaryParts(),
            'byteExposurePolicy' => 'activex-control-bytes-blocked',
            'reviewPolicy' => 'activex-metadata-only',
            'valid' => false,
            'issues' => [],
            'relationship' => null,
        ];

        if ($relationshipId === '') {
            $item['issues'][] = 'missing-relationship-id';
            return $item;
        }

        if (!is_array($relationship)) {
            $item['issues'][] = 'unknown-relationship';
            return $item;
        }

        $summary = $this->relationshipInventorySummary($parts, $relationship, $documentPart, $relationshipsPart, $contentTypes);
        $targetPart = is_string($summary['targetPart'] ?? null) ? $summary['targetPart'] : null;
        $exists = (bool) $summary['exists'];
        $controlRelationshipsPart = $targetPart === null ? null : $this->relationshipsPartFor($targetPart);
        $controlRelationships = $controlRelationshipsPart === null ? [] : $this->readRelationshipsPart($parts, $controlRelationshipsPart);

        $item['relationshipType'] = $summary['type'];
        $item['target'] = $summary['target'];
        $item['targetMode'] = $summary['targetMode'];
        $item['resolvedTarget'] = $summary['resolvedTarget'];
        $item['external'] = (bool) $summary['external'];
        $item['partName'] = $targetPart;
        $item['targetPart'] = $targetPart;
        $item['targetQuery'] = $summary['targetQuery'];
        $item['targetFragment'] = $summary['targetFragment'];
        $item['targetReferenceSuffix'] = $summary['targetReferenceSuffix'];
        $item['exists'] = $exists;
        $item['byteLength'] = $targetPart !== null && $exists ? strlen($parts[$targetPart]) : null;
        $item['crc32'] = $targetPart !== null && $exists ? sprintf('%08x', crc32($parts[$targetPart])) : null;
        $item['sha256'] = $targetPart !== null && $exists ? hash('sha256', $parts[$targetPart]) : null;
        $item['contentType'] = $summary['contentType'];
        $item['contentTypeBase'] = $summary['contentTypeBase'];
        $item['contentTypeHasParameters'] = $summary['contentTypeHasParameters'];
        $item['contentTypeParameterCount'] = $summary['contentTypeParameterCount'];
        $item['contentTypeParameters'] = $summary['contentTypeParameters'];
        $item['contentTypeParameterMap'] = $summary['contentTypeParameterMap'];
        $item['contentTypeSource'] = $summary['contentTypeSource'];
        $item['defaultExtension'] = $summary['defaultExtension'];
        $item['overridePartName'] = $summary['overridePartName'];
        $item['relationshipsPart'] = $relationshipsPart;
        $item['controlRelationshipsPart'] = $controlRelationshipsPart;
        $item['controlRelationshipCount'] = count($controlRelationships);
        $item['relationship'] = $summary;

        if ($relationship['type'] !== self::ACTIVEX_CONTROL_REL) {
            $item['issues'][] = 'unexpected-relationship-type';
            return $item;
        }

        if ($item['external'] === true) {
            $item['issues'][] = 'external-activex-control';
            return $item;
        }

        if (!$exists) {
            $item['issues'][] = 'missing-control-part';
        }

        $contentTypeBase = is_string($summary['contentTypeBase'] ?? null) ? $summary['contentTypeBase'] : '';
        if (($summary['contentTypeSource'] ?? '') === 'missing') {
            $item['issues'][] = 'missing-control-content-type';
        } elseif ($contentTypeBase !== self::CT_ACTIVEX_XML) {
            $item['issues'][] = 'unexpected-control-content-type';
        }

        if ($exists && $targetPart !== null) {
            $root = $this->xmlRootProvenance($parts[$targetPart], $targetPart);
            $item['validXml'] = $root['validXml'];
            $item['xmlParseError'] = $root['xmlParseError'];
            $item['rootNamespace'] = $root['namespace'];
            $item['rootLocalName'] = $root['localName'];
            $item['validRoot'] = $root['namespace'] === self::NS_ACTIVEX && $root['localName'] === 'ocx';
            if ($root['validXml'] === false) {
                $item['issues'][] = 'invalid-control-xml';
            } elseif ($item['validRoot'] === false) {
                $item['issues'][] = 'unexpected-control-root';
            } else {
                $dom = $this->loadXmlForProvenance($parts[$targetPart], $targetPart);
                $rootElement = $dom instanceof \DOMDocument ? $dom->documentElement : null;
                if ($rootElement instanceof \DOMElement) {
                    $item['ocxClassId'] = $this->activeXPartRootAttribute($rootElement, 'classid');
                    $item['ocxPersistence'] = $this->activeXPartRootAttribute($rootElement, 'persistence');
                }
            }
        }

        $item['binaries'] = $this->activeXBinaryParts(
            $parts,
            $targetPart,
            $controlRelationshipsPart,
            $controlRelationships,
            $contentTypes,
        );
        $item['valid'] = $item['issues'] === [] && (int) $item['binaries']['issueCount'] === 0;

        return $item;
    }

    /**
     * @return array<string, mixed>
     */
    private function emptyActiveXBinaryParts(): array
    {
        return [
            'count' => 0,
            'existingCount' => 0,
            'missingCount' => 0,
            'externalCount' => 0,
            'allowedExternalTargetCount' => 0,
            'unsafeExternalTargetCount' => 0,
            'unexpectedContentTypeCount' => 0,
            'issueCount' => 0,
            'relationshipIds' => [],
            'partNames' => [],
            'externalTargets' => [],
            'unsafeExternalTargets' => [],
            'externalTargetIssueCodes' => [],
            'contentTypes' => [],
            'issueCodes' => [],
            'byRelationshipId' => [],
            'items' => [],
        ];
    }

    /**
     * @param array<string, string> $parts
     * @param array<string, array{id:string, type:string, target:string, targetMode:string, resolvedTarget:string}> $relationships
     * @param array{defaults:array<string, string>, overrides:array<string, string>} $contentTypes
     * @return array<string, mixed>
     */
    private function activeXBinaryParts(
        array $parts,
        ?string $sourcePart,
        ?string $relationshipsPart,
        array $relationships,
        array $contentTypes,
    ): array {
        if ($sourcePart === null || $relationshipsPart === null) {
            return $this->emptyActiveXBinaryParts();
        }

        $items = [];
        $byRelationshipId = [];
        $relationshipIds = [];
        $partNames = [];
        $externalTargets = [];
        $unsafeExternalTargets = [];
        $contentTypesSeen = [];
        $issueCodes = [];
        $externalTargetIssueCodes = [];
        foreach ($relationships as $relationship) {
            if ($relationship['type'] !== self::ACTIVEX_BINARY_REL) {
                continue;
            }

            $item = $this->activeXBinaryPartItem($parts, $relationship, $sourcePart, $relationshipsPart, $contentTypes, count($items));
            $items[] = $item;
            $byRelationshipId[(string) $item['id']] = $item;
            $relationshipIds[] = (string) $item['id'];
            $this->appendUniqueString($partNames, is_string($item['targetPart'] ?? null) ? $item['targetPart'] : null);
            $this->appendUniqueString($contentTypesSeen, is_string($item['contentType'] ?? null) ? $item['contentType'] : null);
            if (($item['external'] ?? false) === true) {
                $this->appendUniqueString($externalTargets, is_string($item['target'] ?? null) ? $item['target'] : null);
                if (($item['externalTargetAllowed'] ?? null) !== true) {
                    $this->appendUniqueString($unsafeExternalTargets, is_string($item['target'] ?? null) ? $item['target'] : null);
                }
                foreach (($item['externalTargetIssues'] ?? []) as $issue) {
                    if (is_string($issue) && $issue !== '') {
                        $externalTargetIssueCodes[$issue] = true;
                    }
                }
            }
            foreach (($item['issues'] ?? []) as $issue) {
                if (is_string($issue) && $issue !== '') {
                    $issueCodes[$issue] = true;
                }
            }
        }
        ksort($issueCodes, SORT_STRING);
        ksort($externalTargetIssueCodes, SORT_STRING);

        return [
            'count' => count($items),
            'existingCount' => count(array_filter($items, static fn (array $item): bool => $item['external'] === false && $item['exists'] === true)),
            'missingCount' => count(array_filter($items, static fn (array $item): bool => in_array('missing-activex-binary', $item['issues'], true))),
            'externalCount' => count(array_filter($items, static fn (array $item): bool => $item['external'] === true)),
            'allowedExternalTargetCount' => count(array_filter($items, static fn (array $item): bool => $item['external'] === true && $item['externalTargetAllowed'] === true)),
            'unsafeExternalTargetCount' => count(array_filter($items, static fn (array $item): bool => $item['external'] === true && $item['externalTargetAllowed'] !== true)),
            'unexpectedContentTypeCount' => count(array_filter($items, static fn (array $item): bool => in_array('unexpected-binary-content-type', $item['issues'], true))),
            'issueCount' => count(array_filter($items, static fn (array $item): bool => $item['issues'] !== [])),
            'relationshipIds' => $relationshipIds,
            'partNames' => $partNames,
            'externalTargets' => $externalTargets,
            'unsafeExternalTargets' => $unsafeExternalTargets,
            'externalTargetIssueCodes' => array_keys($externalTargetIssueCodes),
            'contentTypes' => $contentTypesSeen,
            'issueCodes' => array_keys($issueCodes),
            'byRelationshipId' => $byRelationshipId,
            'items' => $items,
        ];
    }

    /**
     * @param array<string, string> $parts
     * @param array{id:string, type:string, target:string, targetMode:string, resolvedTarget:string} $relationship
     * @param array{defaults:array<string, string>, overrides:array<string, string>} $contentTypes
     * @return array<string, mixed>
     */
    private function activeXBinaryPartItem(
        array $parts,
        array $relationship,
        string $sourcePart,
        string $relationshipsPart,
        array $contentTypes,
        int $index,
    ): array {
        $summary = $this->relationshipInventorySummary($parts, $relationship, $sourcePart, $relationshipsPart, $contentTypes);
        $targetPart = is_string($summary['targetPart'] ?? null) ? $summary['targetPart'] : null;
        $external = (bool) ($summary['external'] ?? false);
        $exists = (bool) ($summary['exists'] ?? false);
        $contentTypeBase = is_string($summary['contentTypeBase'] ?? null) ? $summary['contentTypeBase'] : '';
        $issues = [];

        if ($external) {
            $issues[] = 'external-activex-binary';
        } elseif (!$exists) {
            $issues[] = 'missing-activex-binary';
        }
        if (!$external && ($summary['contentTypeSource'] ?? '') === 'missing') {
            $issues[] = 'missing-binary-content-type';
        } elseif (!$external && $contentTypeBase !== '' && $contentTypeBase !== self::CT_ACTIVEX_BINARY) {
            $issues[] = 'unexpected-binary-content-type';
        }

        return [
            'index' => $index,
            'source' => $sourcePart,
            'id' => $summary['id'],
            'type' => $summary['type'],
            'target' => $summary['target'],
            'targetMode' => $summary['targetMode'],
            'resolvedTarget' => $summary['resolvedTarget'],
            'targetPart' => $targetPart,
            'targetQuery' => $summary['targetQuery'],
            'targetFragment' => $summary['targetFragment'],
            'targetReferenceSuffix' => $summary['targetReferenceSuffix'],
            'externalTargetKind' => $summary['externalTargetKind'],
            'externalTargetScheme' => $summary['externalTargetScheme'],
            'externalTargetAllowed' => $summary['externalTargetAllowed'],
            'externalTargetIssues' => $summary['externalTargetIssues'],
            'contentType' => $summary['contentType'],
            'contentTypeBase' => $summary['contentTypeBase'],
            'contentTypeHasParameters' => $summary['contentTypeHasParameters'],
            'contentTypeParameterCount' => $summary['contentTypeParameterCount'],
            'contentTypeParameters' => $summary['contentTypeParameters'],
            'contentTypeParameterMap' => $summary['contentTypeParameterMap'],
            'contentTypeSource' => $summary['contentTypeSource'],
            'defaultExtension' => $summary['defaultExtension'],
            'overridePartName' => $summary['overridePartName'],
            'expectedContentTypeBase' => self::CT_ACTIVEX_BINARY,
            'external' => $external,
            'exists' => $exists,
            'relationshipsPart' => $relationshipsPart,
            'byteLength' => $targetPart !== null && $exists ? strlen($parts[$targetPart]) : null,
            'crc32' => $targetPart !== null && $exists ? sprintf('%08x', crc32($parts[$targetPart])) : null,
            'sha256' => $targetPart !== null && $exists ? hash('sha256', $parts[$targetPart]) : null,
            'byteExposurePolicy' => 'activex-binary-bytes-blocked',
            'reviewPolicy' => 'activex-metadata-only',
            'valid' => $issues === [],
            'issues' => $issues,
            'relationship' => $summary,
        ];
    }

    /**
     * @param array<string, string> $parts
     * @param array<string, array{id:string, type:string, target:string, targetMode:string, resolvedTarget:string}> $relationships
     * @param array{defaults:array<string, string>, overrides:array<string, string>} $contentTypes
     * @return array<string, mixed>
     */
    private function readVbaProjects(
        array $parts,
        string $documentPart,
        array $relationships,
        array $contentTypes,
    ): array {
        $items = [];
        $byRelationshipId = [];
        $relationshipIds = [];
        $partNames = [];
        $signaturePartNames = [];
        $dataPartNames = [];
        $externalTargets = [];
        $unsafeExternalTargets = [];
        $contentTypesSeen = [];
        $issueCodes = [];
        $projectExternalTargetIssueCodes = [];
        $signatureExternalTargetIssueCodes = [];
        $dataPartExternalTargetIssueCodes = [];
        $relationshipsPart = $this->relationshipsPartFor($documentPart);

        foreach ($relationships as $relationship) {
            if ($relationship['type'] !== self::VBA_PROJECT_REL) {
                continue;
            }

            $item = $this->vbaProjectItem($parts, $relationship, $documentPart, $relationshipsPart, $contentTypes, count($items));
            $items[] = $item;
            $byRelationshipId[(string) $item['relationshipId']] = $item;
            $relationshipIds[] = (string) $item['relationshipId'];
            $this->appendUniqueString($partNames, is_string($item['targetPart'] ?? null) ? $item['targetPart'] : null);
            $this->appendUniqueString($contentTypesSeen, is_string($item['contentType'] ?? null) ? $item['contentType'] : null);
            if (($item['external'] ?? false) === true) {
                $this->appendUniqueString($externalTargets, is_string($item['target'] ?? null) ? $item['target'] : null);
                if (($item['externalTargetAllowed'] ?? null) !== true) {
                    $this->appendUniqueString($unsafeExternalTargets, is_string($item['target'] ?? null) ? $item['target'] : null);
                }
                foreach (($item['externalTargetIssues'] ?? []) as $issue) {
                    if (is_string($issue) && $issue !== '') {
                        $projectExternalTargetIssueCodes[$issue] = true;
                    }
                }
            }
            foreach (($item['issues'] ?? []) as $issue) {
                if (is_string($issue) && $issue !== '') {
                    $issueCodes[$issue] = true;
                }
            }

            foreach (($item['signatureParts']['items'] ?? []) as $signature) {
                if (!is_array($signature)) {
                    continue;
                }
                $this->appendUniqueString($signaturePartNames, is_string($signature['targetPart'] ?? null) ? $signature['targetPart'] : null);
                $this->appendUniqueString($contentTypesSeen, is_string($signature['contentType'] ?? null) ? $signature['contentType'] : null);
                if (($signature['external'] ?? false) === true) {
                    $this->appendUniqueString($externalTargets, is_string($signature['target'] ?? null) ? $signature['target'] : null);
                    if (($signature['externalTargetAllowed'] ?? null) !== true) {
                        $this->appendUniqueString($unsafeExternalTargets, is_string($signature['target'] ?? null) ? $signature['target'] : null);
                    }
                    foreach (($signature['externalTargetIssues'] ?? []) as $issue) {
                        if (is_string($issue) && $issue !== '') {
                            $signatureExternalTargetIssueCodes[$issue] = true;
                        }
                    }
                }
                foreach (($signature['issues'] ?? []) as $issue) {
                    if (is_string($issue) && $issue !== '') {
                        $issueCodes[$issue] = true;
                    }
                }
            }

            foreach (($item['dataParts']['items'] ?? []) as $dataPart) {
                if (!is_array($dataPart)) {
                    continue;
                }
                $this->appendUniqueString($dataPartNames, is_string($dataPart['targetPart'] ?? null) ? $dataPart['targetPart'] : null);
                $this->appendUniqueString($contentTypesSeen, is_string($dataPart['contentType'] ?? null) ? $dataPart['contentType'] : null);
                if (($dataPart['external'] ?? false) === true) {
                    $this->appendUniqueString($externalTargets, is_string($dataPart['target'] ?? null) ? $dataPart['target'] : null);
                    if (($dataPart['externalTargetAllowed'] ?? null) !== true) {
                        $this->appendUniqueString($unsafeExternalTargets, is_string($dataPart['target'] ?? null) ? $dataPart['target'] : null);
                    }
                    foreach (($dataPart['externalTargetIssues'] ?? []) as $issue) {
                        if (is_string($issue) && $issue !== '') {
                            $dataPartExternalTargetIssueCodes[$issue] = true;
                        }
                    }
                }
                foreach (($dataPart['issues'] ?? []) as $issue) {
                    if (is_string($issue) && $issue !== '') {
                        $issueCodes[$issue] = true;
                    }
                }
            }
        }
        ksort($issueCodes, SORT_STRING);
        ksort($projectExternalTargetIssueCodes, SORT_STRING);
        ksort($signatureExternalTargetIssueCodes, SORT_STRING);
        ksort($dataPartExternalTargetIssueCodes, SORT_STRING);

        return [
            'count' => count($items),
            'relationshipCount' => count(array_filter($relationships, static fn (array $relationship): bool => $relationship['type'] === self::VBA_PROJECT_REL)),
            'existingCount' => count(array_filter($items, static fn (array $item): bool => $item['external'] === false && $item['exists'] === true)),
            'missingCount' => count(array_filter($items, static fn (array $item): bool => in_array('missing-vba-project', $item['issues'], true))),
            'externalCount' => count(array_filter($items, static fn (array $item): bool => $item['external'] === true)),
            'allowedExternalProjectCount' => count(array_filter($items, static fn (array $item): bool => $item['external'] === true && ($item['externalTargetAllowed'] ?? null) === true)),
            'unsafeExternalProjectCount' => count(array_filter($items, static fn (array $item): bool => $item['external'] === true && ($item['externalTargetAllowed'] ?? null) !== true)),
            'missingContentTypeCount' => count(array_filter($items, static fn (array $item): bool => in_array('missing-project-content-type', $item['issues'], true))),
            'unexpectedContentTypeCount' => count(array_filter($items, static fn (array $item): bool => in_array('unexpected-project-content-type', $item['issues'], true))),
            'signatureCount' => array_sum(array_map(static fn (array $item): int => (int) ($item['signatureParts']['count'] ?? 0), $items)),
            'existingSignatureCount' => array_sum(array_map(static fn (array $item): int => (int) ($item['signatureParts']['existingCount'] ?? 0), $items)),
            'missingSignatureCount' => array_sum(array_map(static fn (array $item): int => (int) ($item['signatureParts']['missingCount'] ?? 0), $items)),
            'externalSignatureCount' => array_sum(array_map(static fn (array $item): int => (int) ($item['signatureParts']['externalCount'] ?? 0), $items)),
            'allowedExternalSignatureCount' => array_sum(array_map(static fn (array $item): int => (int) ($item['signatureParts']['allowedExternalTargetCount'] ?? 0), $items)),
            'unsafeExternalSignatureCount' => array_sum(array_map(static fn (array $item): int => (int) ($item['signatureParts']['unsafeExternalTargetCount'] ?? 0), $items)),
            'dataPartCount' => array_sum(array_map(static fn (array $item): int => (int) ($item['dataParts']['count'] ?? 0), $items)),
            'existingDataPartCount' => array_sum(array_map(static fn (array $item): int => (int) ($item['dataParts']['existingCount'] ?? 0), $items)),
            'missingDataPartCount' => array_sum(array_map(static fn (array $item): int => (int) ($item['dataParts']['missingCount'] ?? 0), $items)),
            'externalDataPartCount' => array_sum(array_map(static fn (array $item): int => (int) ($item['dataParts']['externalCount'] ?? 0), $items)),
            'allowedExternalDataPartCount' => array_sum(array_map(static fn (array $item): int => (int) ($item['dataParts']['allowedExternalTargetCount'] ?? 0), $items)),
            'unsafeExternalDataPartCount' => array_sum(array_map(static fn (array $item): int => (int) ($item['dataParts']['unsafeExternalTargetCount'] ?? 0), $items)),
            'dataPartInvalidXmlCount' => array_sum(array_map(static fn (array $item): int => (int) ($item['dataParts']['invalidXmlCount'] ?? 0), $items)),
            'dataPartUnexpectedRootCount' => array_sum(array_map(static fn (array $item): int => (int) ($item['dataParts']['unexpectedRootCount'] ?? 0), $items)),
            'issueCount' => count(array_filter(
                $items,
                static fn (array $item): bool => $item['issues'] !== []
                    || (int) ($item['signatureParts']['issueCount'] ?? 0) > 0
                    || (int) ($item['dataParts']['issueCount'] ?? 0) > 0,
            )),
            'relationshipIds' => $relationshipIds,
            'partNames' => $partNames,
            'signaturePartNames' => $signaturePartNames,
            'dataPartNames' => $dataPartNames,
            'externalTargets' => $externalTargets,
            'unsafeExternalTargets' => $unsafeExternalTargets,
            'contentTypes' => $contentTypesSeen,
            'issueCodes' => array_keys($issueCodes),
            'projectExternalTargetIssueCodes' => array_keys($projectExternalTargetIssueCodes),
            'signatureExternalTargetIssueCodes' => array_keys($signatureExternalTargetIssueCodes),
            'dataPartExternalTargetIssueCodes' => array_keys($dataPartExternalTargetIssueCodes),
            'byRelationshipId' => $byRelationshipId,
            'items' => $items,
            'byteExposurePolicy' => 'vba-project-bytes-blocked',
            'reviewPolicy' => 'vba-project-metadata-only',
        ];
    }

    /**
     * @param array<string, string> $parts
     * @param array{id:string, type:string, target:string, targetMode:string, resolvedTarget:string} $relationship
     * @param array{defaults:array<string, string>, overrides:array<string, string>} $contentTypes
     * @return array<string, mixed>
     */
    private function vbaProjectItem(
        array $parts,
        array $relationship,
        string $documentPart,
        string $relationshipsPart,
        array $contentTypes,
        int $index,
    ): array {
        $summary = $this->relationshipInventorySummary($parts, $relationship, $documentPart, $relationshipsPart, $contentTypes);
        $targetPart = is_string($summary['targetPart'] ?? null) ? $summary['targetPart'] : null;
        $external = (bool) ($summary['external'] ?? false);
        $exists = (bool) ($summary['exists'] ?? false);
        $projectRelationshipsPart = $targetPart === null ? null : $this->relationshipsPartFor($targetPart);
        $projectRelationships = $projectRelationshipsPart === null ? [] : $this->readRelationshipsPart($parts, $projectRelationshipsPart);
        $contentTypeBase = is_string($summary['contentTypeBase'] ?? null) ? $summary['contentTypeBase'] : '';
        $issues = [];

        if ($external) {
            $issues[] = 'external-vba-project';
        } else {
            if (!$exists) {
                $issues[] = 'missing-vba-project';
            }
            if (($summary['contentTypeSource'] ?? '') === 'missing') {
                $issues[] = 'missing-project-content-type';
            } elseif ($contentTypeBase !== self::CT_VBA_PROJECT) {
                $issues[] = 'unexpected-project-content-type';
            }
        }

        $signatureParts = $this->vbaProjectRelatedParts(
            $parts,
            $targetPart,
            $projectRelationshipsPart,
            $projectRelationships,
            $contentTypes,
            self::VBA_PROJECT_SIGNATURE_REL,
            self::CT_VBA_PROJECT_SIGNATURE,
            'project-signature',
        );
        $dataParts = $this->vbaProjectRelatedParts(
            $parts,
            $targetPart,
            $projectRelationshipsPart,
            $projectRelationships,
            $contentTypes,
            self::VBA_DATA_REL,
            self::CT_VBA_DATA,
            'data',
        );

        return [
            'index' => $index,
            'relationshipId' => $summary['id'],
            'relationshipType' => $summary['type'],
            'target' => $summary['target'],
            'targetMode' => $summary['targetMode'],
            'resolvedTarget' => $summary['resolvedTarget'],
            'external' => $external,
            'partName' => $targetPart,
            'targetPart' => $targetPart,
            'targetQuery' => $summary['targetQuery'],
            'targetFragment' => $summary['targetFragment'],
            'targetReferenceSuffix' => $summary['targetReferenceSuffix'],
            'externalTargetKind' => $summary['externalTargetKind'],
            'externalTargetScheme' => $summary['externalTargetScheme'],
            'externalTargetAllowed' => $summary['externalTargetAllowed'],
            'externalTargetIssues' => $summary['externalTargetIssues'],
            'exists' => $exists,
            'byteLength' => $targetPart !== null && $exists ? strlen($parts[$targetPart]) : null,
            'crc32' => $targetPart !== null && $exists ? sprintf('%08x', crc32($parts[$targetPart])) : null,
            'sha256' => $targetPart !== null && $exists ? hash('sha256', $parts[$targetPart]) : null,
            'contentType' => $summary['contentType'],
            'contentTypeBase' => $summary['contentTypeBase'],
            'contentTypeHasParameters' => $summary['contentTypeHasParameters'],
            'contentTypeParameterCount' => $summary['contentTypeParameterCount'],
            'contentTypeParameters' => $summary['contentTypeParameters'],
            'contentTypeParameterMap' => $summary['contentTypeParameterMap'],
            'contentTypeSource' => $summary['contentTypeSource'],
            'defaultExtension' => $summary['defaultExtension'],
            'overridePartName' => $summary['overridePartName'],
            'expectedContentTypeBase' => self::CT_VBA_PROJECT,
            'relationshipsPart' => $relationshipsPart,
            'projectRelationshipsPart' => $projectRelationshipsPart,
            'projectRelationshipCount' => count($projectRelationships),
            'signatureParts' => $signatureParts,
            'dataParts' => $dataParts,
            'byteExposurePolicy' => 'vba-project-bytes-blocked',
            'reviewPolicy' => 'vba-project-metadata-only',
            'valid' => $issues === [] && (int) $signatureParts['issueCount'] === 0 && (int) $dataParts['issueCount'] === 0,
            'issues' => $issues,
            'relationship' => $summary,
        ];
    }

    /**
     * @return array<string, mixed>
     */
    private function emptyVbaProjectRelatedParts(): array
    {
        return [
            'count' => 0,
            'existingCount' => 0,
            'missingCount' => 0,
            'externalCount' => 0,
            'allowedExternalTargetCount' => 0,
            'unsafeExternalTargetCount' => 0,
            'unexpectedContentTypeCount' => 0,
            'invalidXmlCount' => 0,
            'unexpectedRootCount' => 0,
            'issueCount' => 0,
            'relationshipIds' => [],
            'partNames' => [],
            'externalTargets' => [],
            'unsafeExternalTargets' => [],
            'contentTypes' => [],
            'externalTargetIssueCodes' => [],
            'issueCodes' => [],
            'byRelationshipId' => [],
            'items' => [],
        ];
    }

    /**
     * @param array<string, string> $parts
     * @param array<string, array{id:string, type:string, target:string, targetMode:string, resolvedTarget:string}> $relationships
     * @param array{defaults:array<string, string>, overrides:array<string, string>} $contentTypes
     * @return array<string, mixed>
     */
    private function vbaProjectRelatedParts(
        array $parts,
        ?string $sourcePart,
        ?string $relationshipsPart,
        array $relationships,
        array $contentTypes,
        string $relationshipType,
        string $expectedContentTypeBase,
        string $kind,
    ): array {
        if ($sourcePart === null || $relationshipsPart === null) {
            return $this->emptyVbaProjectRelatedParts();
        }

        $items = [];
        $byRelationshipId = [];
        $relationshipIds = [];
        $partNames = [];
        $externalTargets = [];
        $unsafeExternalTargets = [];
        $contentTypesSeen = [];
        $externalTargetIssueCodes = [];
        $issueCodes = [];
        foreach ($relationships as $relationship) {
            if ($relationship['type'] !== $relationshipType) {
                continue;
            }

            $item = $this->vbaProjectRelatedPartItem(
                $parts,
                $relationship,
                $sourcePart,
                $relationshipsPart,
                $contentTypes,
                $expectedContentTypeBase,
                $kind,
                count($items),
            );
            $items[] = $item;
            $byRelationshipId[(string) $item['id']] = $item;
            $relationshipIds[] = (string) $item['id'];
            $this->appendUniqueString($partNames, is_string($item['targetPart'] ?? null) ? $item['targetPart'] : null);
            $this->appendUniqueString($contentTypesSeen, is_string($item['contentType'] ?? null) ? $item['contentType'] : null);
            if (($item['external'] ?? false) === true) {
                $this->appendUniqueString($externalTargets, is_string($item['target'] ?? null) ? $item['target'] : null);
                if (($item['externalTargetAllowed'] ?? null) !== true) {
                    $this->appendUniqueString($unsafeExternalTargets, is_string($item['target'] ?? null) ? $item['target'] : null);
                }
                foreach (($item['externalTargetIssues'] ?? []) as $issue) {
                    if (is_string($issue) && $issue !== '') {
                        $externalTargetIssueCodes[$issue] = true;
                    }
                }
            }
            foreach (($item['issues'] ?? []) as $issue) {
                if (is_string($issue) && $issue !== '') {
                    $issueCodes[$issue] = true;
                }
            }
        }
        ksort($externalTargetIssueCodes, SORT_STRING);
        ksort($issueCodes, SORT_STRING);

        return [
            'count' => count($items),
            'existingCount' => count(array_filter($items, static fn (array $item): bool => $item['external'] === false && $item['exists'] === true)),
            'missingCount' => count(array_filter($items, static fn (array $item): bool => in_array('missing-vba-' . $kind, $item['issues'], true))),
            'externalCount' => count(array_filter($items, static fn (array $item): bool => $item['external'] === true)),
            'allowedExternalTargetCount' => count(array_filter($items, static fn (array $item): bool => $item['external'] === true && ($item['externalTargetAllowed'] ?? null) === true)),
            'unsafeExternalTargetCount' => count(array_filter($items, static fn (array $item): bool => $item['external'] === true && ($item['externalTargetAllowed'] ?? null) !== true)),
            'unexpectedContentTypeCount' => count(array_filter($items, static fn (array $item): bool => in_array('unexpected-vba-' . $kind . '-content-type', $item['issues'], true))),
            'invalidXmlCount' => count(array_filter($items, static fn (array $item): bool => in_array('invalid-vba-' . $kind . '-xml', $item['issues'], true))),
            'unexpectedRootCount' => count(array_filter($items, static fn (array $item): bool => in_array('unexpected-vba-' . $kind . '-root', $item['issues'], true))),
            'issueCount' => count(array_filter($items, static fn (array $item): bool => $item['issues'] !== [])),
            'relationshipIds' => $relationshipIds,
            'partNames' => $partNames,
            'externalTargets' => $externalTargets,
            'unsafeExternalTargets' => $unsafeExternalTargets,
            'contentTypes' => $contentTypesSeen,
            'externalTargetIssueCodes' => array_keys($externalTargetIssueCodes),
            'issueCodes' => array_keys($issueCodes),
            'byRelationshipId' => $byRelationshipId,
            'items' => $items,
        ];
    }

    /**
     * @param array<string, string> $parts
     * @param array{id:string, type:string, target:string, targetMode:string, resolvedTarget:string} $relationship
     * @param array{defaults:array<string, string>, overrides:array<string, string>} $contentTypes
     * @return array<string, mixed>
     */
    private function vbaProjectRelatedPartItem(
        array $parts,
        array $relationship,
        string $sourcePart,
        string $relationshipsPart,
        array $contentTypes,
        string $expectedContentTypeBase,
        string $kind,
        int $index,
    ): array {
        $summary = $this->relationshipInventorySummary($parts, $relationship, $sourcePart, $relationshipsPart, $contentTypes);
        $targetPart = is_string($summary['targetPart'] ?? null) ? $summary['targetPart'] : null;
        $external = (bool) ($summary['external'] ?? false);
        $exists = (bool) ($summary['exists'] ?? false);
        $contentTypeBase = is_string($summary['contentTypeBase'] ?? null) ? $summary['contentTypeBase'] : '';
        $validXml = null;
        $xmlParseError = null;
        $rootNamespace = null;
        $rootLocalName = null;
        $validRoot = null;
        $issues = [];

        if ($external) {
            $issues[] = 'external-vba-' . $kind;
        } else {
            if (!$exists) {
                $issues[] = 'missing-vba-' . $kind;
            }
            if (($summary['contentTypeSource'] ?? '') === 'missing') {
                $issues[] = 'missing-vba-' . $kind . '-content-type';
            } elseif ($contentTypeBase !== $expectedContentTypeBase) {
                $issues[] = 'unexpected-vba-' . $kind . '-content-type';
            }
        }

        if ($kind === 'data' && !$external && $exists && $contentTypeBase === $expectedContentTypeBase && $targetPart !== null) {
            $root = $this->xmlRootProvenance($parts[$targetPart], $targetPart);
            $validXml = $root['validXml'];
            $xmlParseError = $root['xmlParseError'];
            $rootNamespace = $root['namespace'];
            $rootLocalName = $root['localName'];
            $validRoot = $root['namespace'] === self::NS_WNE && $root['localName'] === 'vbaSuppData';
            if ($root['validXml'] === false) {
                $validRoot = false;
                $issues[] = 'invalid-vba-data-xml';
            } elseif ($validRoot === false) {
                $issues[] = 'unexpected-vba-data-root';
            }
        }

        return [
            'index' => $index,
            'source' => $sourcePart,
            'id' => $summary['id'],
            'type' => $summary['type'],
            'target' => $summary['target'],
            'targetMode' => $summary['targetMode'],
            'resolvedTarget' => $summary['resolvedTarget'],
            'targetPart' => $targetPart,
            'targetQuery' => $summary['targetQuery'],
            'targetFragment' => $summary['targetFragment'],
            'targetReferenceSuffix' => $summary['targetReferenceSuffix'],
            'externalTargetKind' => $summary['externalTargetKind'],
            'externalTargetScheme' => $summary['externalTargetScheme'],
            'externalTargetAllowed' => $summary['externalTargetAllowed'],
            'externalTargetIssues' => $summary['externalTargetIssues'],
            'contentType' => $summary['contentType'],
            'contentTypeBase' => $summary['contentTypeBase'],
            'contentTypeHasParameters' => $summary['contentTypeHasParameters'],
            'contentTypeParameterCount' => $summary['contentTypeParameterCount'],
            'contentTypeParameters' => $summary['contentTypeParameters'],
            'contentTypeParameterMap' => $summary['contentTypeParameterMap'],
            'contentTypeSource' => $summary['contentTypeSource'],
            'defaultExtension' => $summary['defaultExtension'],
            'overridePartName' => $summary['overridePartName'],
            'expectedContentTypeBase' => $expectedContentTypeBase,
            'validXml' => $validXml,
            'xmlParseError' => $xmlParseError,
            'rootNamespace' => $rootNamespace,
            'rootLocalName' => $rootLocalName,
            'validRoot' => $validRoot,
            'external' => $external,
            'exists' => $exists,
            'relationshipsPart' => $relationshipsPart,
            'byteLength' => $targetPart !== null && $exists ? strlen($parts[$targetPart]) : null,
            'crc32' => $targetPart !== null && $exists ? sprintf('%08x', crc32($parts[$targetPart])) : null,
            'sha256' => $targetPart !== null && $exists ? hash('sha256', $parts[$targetPart]) : null,
            'byteExposurePolicy' => 'vba-' . $kind . '-bytes-blocked',
            'reviewPolicy' => 'vba-project-metadata-only',
            'valid' => $issues === [],
            'issues' => $issues,
            'relationship' => $summary,
        ];
    }

    /**
     * @param array<string, string> $parts
     * @param array<string, array{id:string, type:string, target:string, targetMode:string, resolvedTarget:string}> $settingsRelationships
     * @param array{defaults:array<string, string>, overrides:array<string, string>} $contentTypes
     * @return array<string, mixed>
     */
    private function readSettingsRelationshipInventory(
        array $parts,
        string $settingsPart,
        bool $settingsExists,
        string $settingsRelationshipsPart,
        array $settingsRelationships,
        array $contentTypes
    ): array {
        $items = [];
        $byRelationshipId = [];
        $relationshipIds = [];
        $relationshipTypeCounts = [];
        $targetParts = [];
        $externalTargets = [];
        $unsafeExternalTargets = [];
        $externalTargetKindCounts = [];
        $externalTargetSchemeCounts = [];
        $targetReferenceSuffixes = [];
        $contentTypesSeen = [];
        $contentTypeBaseCounts = [];
        $issueCodes = [];

        foreach ($settingsRelationships as $relationship) {
            $summary = $this->relationshipInventorySummary(
                $parts,
                $relationship,
                $settingsPart,
                $settingsRelationshipsPart,
                $contentTypes,
            );
            $external = (bool) ($summary['external'] ?? false);
            $targetPart = is_string($summary['targetPart'] ?? null) ? $summary['targetPart'] : null;
            $exists = (bool) ($summary['exists'] ?? false);
            $relationshipType = is_string($summary['type'] ?? null) ? $summary['type'] : '';
            $relationshipId = is_string($summary['id'] ?? null) ? $summary['id'] : '';
            $contentType = is_string($summary['contentType'] ?? null) ? $summary['contentType'] : '';
            $contentTypeBase = is_string($summary['contentTypeBase'] ?? null) ? $summary['contentTypeBase'] : '';
            $targetReferenceSuffix = is_string($summary['targetReferenceSuffix'] ?? null) ? $summary['targetReferenceSuffix'] : '';
            $issues = [];

            if ($external) {
                foreach (($summary['externalTargetIssues'] ?? []) as $issue) {
                    if (is_string($issue) && $issue !== '') {
                        $issues[] = $issue;
                    }
                }
            } else {
                if (!$exists) {
                    $issues[] = 'missing-settings-relationship-target';
                }
                if (($summary['contentTypeSource'] ?? 'missing') === 'missing') {
                    $issues[] = 'missing-settings-relationship-content-type';
                }
            }
            $issues = array_values(array_unique($issues));
            sort($issues, SORT_STRING);

            $item = [
                'index' => count($items),
                'relationshipId' => $relationshipId,
                'relationshipKey' => $settingsRelationshipsPart . '#' . $relationshipId,
                'sourcePart' => $settingsPart,
                'sourcePartExists' => $settingsExists,
                'relationshipsPart' => $settingsRelationshipsPart,
                'relationshipsPartExists' => isset($parts[$settingsRelationshipsPart]),
                'relationshipType' => $relationshipType,
                'target' => $summary['target'],
                'targetMode' => $summary['targetMode'],
                'external' => $external,
                'resolvedTarget' => $summary['resolvedTarget'],
                'partName' => $targetPart,
                'targetPart' => $targetPart,
                'targetQuery' => $summary['targetQuery'],
                'targetFragment' => $summary['targetFragment'],
                'targetReferenceSuffix' => $targetReferenceSuffix,
                'targetParentTraversalCount' => $summary['targetParentTraversalCount'],
                'targetHasParentTraversal' => $summary['targetHasParentTraversal'],
                'targetStartsAtPackageRoot' => $summary['targetStartsAtPackageRoot'],
                'sameSourcePart' => $summary['sameSourcePart'],
                'externalTargetKind' => $summary['externalTargetKind'],
                'externalTargetScheme' => $summary['externalTargetScheme'],
                'externalTargetAllowed' => $summary['externalTargetAllowed'],
                'externalTargetIssues' => $summary['externalTargetIssues'],
                'exists' => $exists,
                'byteLength' => !$external && $targetPart !== null && $exists ? strlen($parts[$targetPart]) : null,
                'crc32' => !$external && $targetPart !== null && $exists ? sprintf('%08x', crc32($parts[$targetPart])) : null,
                'sha256' => !$external && $targetPart !== null && $exists ? hash('sha256', $parts[$targetPart]) : null,
                'contentType' => $contentType,
                'contentTypeBase' => $contentTypeBase,
                'contentTypeHasParameters' => $summary['contentTypeHasParameters'],
                'contentTypeParameterCount' => $summary['contentTypeParameterCount'],
                'contentTypeParameters' => $summary['contentTypeParameters'],
                'contentTypeParameterMap' => $summary['contentTypeParameterMap'],
                'contentTypeSource' => $summary['contentTypeSource'],
                'defaultExtension' => $summary['defaultExtension'],
                'overridePartName' => $summary['overridePartName'],
                'byteExposurePolicy' => 'settings-relationship-bytes-blocked',
                'reviewPolicy' => 'settings-relationship-metadata-only',
                'valid' => $issues === [],
                'issues' => $issues,
                'relationship' => $summary,
            ];

            $items[] = $item;
            if ($relationshipId !== '' && !isset($byRelationshipId[$relationshipId])) {
                $byRelationshipId[$relationshipId] = $item;
            }
            $this->appendUniqueString($relationshipIds, $relationshipId);
            $relationshipTypeCounts[$relationshipType] = ($relationshipTypeCounts[$relationshipType] ?? 0) + 1;
            if ($targetPart !== null) {
                $this->appendUniqueString($targetParts, $targetPart);
            }
            if ($external) {
                $this->appendUniqueString($externalTargets, is_string($summary['target'] ?? null) ? $summary['target'] : null);
                if (($summary['externalTargetAllowed'] ?? null) !== true) {
                    $this->appendUniqueString($unsafeExternalTargets, is_string($summary['target'] ?? null) ? $summary['target'] : null);
                }
                $kind = is_string($summary['externalTargetKind'] ?? null) ? $summary['externalTargetKind'] : '(unknown)';
                $scheme = is_string($summary['externalTargetScheme'] ?? null) ? $summary['externalTargetScheme'] : '(none)';
                $externalTargetKindCounts[$kind] = ($externalTargetKindCounts[$kind] ?? 0) + 1;
                $externalTargetSchemeCounts[$scheme] = ($externalTargetSchemeCounts[$scheme] ?? 0) + 1;
            }
            $this->appendUniqueString($targetReferenceSuffixes, $targetReferenceSuffix);
            if ($contentType !== '') {
                $this->appendUniqueString($contentTypesSeen, $contentType);
            }
            if ($contentTypeBase !== '') {
                $contentTypeBaseCounts[$contentTypeBase] = ($contentTypeBaseCounts[$contentTypeBase] ?? 0) + 1;
            }
            foreach ($issues as $issue) {
                $issueCodes[$issue] = true;
            }
        }

        ksort($relationshipTypeCounts, SORT_STRING);
        ksort($externalTargetKindCounts, SORT_STRING);
        ksort($externalTargetSchemeCounts, SORT_STRING);
        ksort($contentTypeBaseCounts, SORT_STRING);
        ksort($issueCodes, SORT_STRING);

        return [
            'sourcePart' => $settingsPart,
            'sourcePartExists' => $settingsExists,
            'relationshipsPart' => $settingsRelationshipsPart,
            'relationshipsPartExists' => isset($parts[$settingsRelationshipsPart]),
            'count' => count($items),
            'relationshipCount' => count($settingsRelationships),
            'internalCount' => count(array_filter($items, static fn (array $item): bool => $item['external'] === false)),
            'externalCount' => count(array_filter($items, static fn (array $item): bool => $item['external'] === true)),
            'allowedExternalTargetCount' => count(array_filter($items, static fn (array $item): bool => $item['external'] === true && ($item['externalTargetAllowed'] ?? null) === true)),
            'unsafeExternalTargetCount' => count(array_filter($items, static fn (array $item): bool => $item['external'] === true && ($item['externalTargetAllowed'] ?? null) !== true)),
            'existingCount' => count(array_filter($items, static fn (array $item): bool => $item['external'] === false && $item['exists'] === true)),
            'missingCount' => count(array_filter($items, static fn (array $item): bool => in_array('missing-settings-relationship-target', $item['issues'], true))),
            'missingContentTypeCount' => count(array_filter($items, static fn (array $item): bool => in_array('missing-settings-relationship-content-type', $item['issues'], true))),
            'issueCount' => count(array_filter($items, static fn (array $item): bool => $item['issues'] !== [])),
            'relationshipIds' => $relationshipIds,
            'relationshipTypeCounts' => $relationshipTypeCounts,
            'targetParts' => $targetParts,
            'externalTargets' => $externalTargets,
            'unsafeExternalTargets' => $unsafeExternalTargets,
            'externalTargetKindCounts' => $externalTargetKindCounts,
            'externalTargetSchemeCounts' => $externalTargetSchemeCounts,
            'targetReferenceSuffixes' => $targetReferenceSuffixes,
            'contentTypes' => $contentTypesSeen,
            'contentTypeBaseCounts' => $contentTypeBaseCounts,
            'issueCodes' => array_keys($issueCodes),
            'byRelationshipId' => $byRelationshipId,
            'items' => $items,
            'byteExposurePolicy' => 'settings-relationship-bytes-blocked',
            'reviewPolicy' => 'settings-relationship-metadata-only',
        ];
    }

    /**
     * @param array<string, string> $parts
     * @param array<string, array{id:string, type:string, target:string, targetMode:string, resolvedTarget:string}> $settingsRelationships
     * @param array{defaults:array<string, string>, overrides:array<string, string>} $contentTypes
     * @return array<string, mixed>
     */
    private function readAttachedTemplates(
        array $parts,
        string $settingsXml,
        string $settingsPart,
        string $settingsRelationshipsPart,
        array $settingsRelationships,
        array $contentTypes
    ): array {
        $items = [];
        $byRelationshipId = [];
        $relationshipIds = [];
        $referencedRelationshipIds = [];
        $referencedAttachedTemplateRelationshipIds = [];

        if ($settingsXml !== '') {
            $dom = $this->loadXml($settingsXml, $settingsPart);
            $xpath = $this->xpath($dom);
            foreach ($this->elements($xpath, '/w:settings/w:attachedTemplate') as $template) {
                $relationshipId = $template->getAttributeNS(self::NS_R, 'id');
                $item = $this->attachedTemplateItem(
                    $parts,
                    $settingsRelationships[$relationshipId] ?? null,
                    $settingsPart,
                    $settingsRelationshipsPart,
                    $contentTypes,
                    $relationshipId,
                    count($items),
                    true,
                );
                $items[] = $item;

                $this->appendUniqueString($relationshipIds, $relationshipId);
                $this->appendUniqueString($referencedRelationshipIds, $relationshipId);
                if ($item['relationshipType'] === self::ATTACHED_TEMPLATE_REL) {
                    $this->appendUniqueString($referencedAttachedTemplateRelationshipIds, $relationshipId);
                }
                if ($relationshipId !== '' && !isset($byRelationshipId[$relationshipId])) {
                    $byRelationshipId[$relationshipId] = $item;
                }
            }
        }

        $unreferencedRelationshipIds = [];
        foreach ($settingsRelationships as $relationship) {
            if ($relationship['type'] !== self::ATTACHED_TEMPLATE_REL) {
                continue;
            }

            $relationshipId = $relationship['id'];
            if (in_array($relationshipId, $referencedAttachedTemplateRelationshipIds, true)) {
                continue;
            }

            $item = $this->attachedTemplateItem(
                $parts,
                $relationship,
                $settingsPart,
                $settingsRelationshipsPart,
                $contentTypes,
                $relationshipId,
                count($items),
                false,
            );
            $items[] = $item;

            $this->appendUniqueString($relationshipIds, $relationshipId);
            $this->appendUniqueString($unreferencedRelationshipIds, $relationshipId);
            if (!isset($byRelationshipId[$relationshipId])) {
                $byRelationshipId[$relationshipId] = $item;
            }
        }

        $partNames = [];
        $externalTargets = [];
        $externalTargetKindCounts = [];
        $externalTargetSchemeCounts = [];
        $externalTargetIssueCodes = [];
        $contentTypesSeen = [];
        $issueCodes = [];
        $issueCount = 0;
        foreach ($items as $item) {
            $this->appendUniqueString($partNames, is_string($item['partName'] ?? null) ? $item['partName'] : null);
            $this->appendUniqueString($contentTypesSeen, is_string($item['contentType'] ?? null) ? $item['contentType'] : null);
            if (($item['relationshipType'] ?? null) === self::ATTACHED_TEMPLATE_REL && ($item['external'] ?? false) === true) {
                $this->appendUniqueString($externalTargets, is_string($item['target'] ?? null) ? $item['target'] : null);
                $kind = is_string($item['externalTargetKind'] ?? null) ? $item['externalTargetKind'] : '(unknown)';
                $scheme = is_string($item['externalTargetScheme'] ?? null) ? $item['externalTargetScheme'] : '(none)';
                $externalTargetKindCounts[$kind] = ($externalTargetKindCounts[$kind] ?? 0) + 1;
                $externalTargetSchemeCounts[$scheme] = ($externalTargetSchemeCounts[$scheme] ?? 0) + 1;
                foreach (($item['externalTargetIssues'] ?? []) as $issue) {
                    if (is_string($issue) && $issue !== '') {
                        $externalTargetIssueCodes[$issue] = true;
                    }
                }
            }
            foreach (($item['issues'] ?? []) as $issue) {
                if (is_string($issue) && $issue !== '') {
                    $issueCodes[$issue] = true;
                }
            }
            $issueCount += count($item['issues']);
        }
        ksort($issueCodes, SORT_STRING);
        ksort($externalTargetKindCounts, SORT_STRING);
        ksort($externalTargetSchemeCounts, SORT_STRING);
        ksort($externalTargetIssueCodes, SORT_STRING);

        return [
            'count' => count($items),
            'relationshipCount' => count(array_filter($settingsRelationships, static fn (array $relationship): bool => $relationship['type'] === self::ATTACHED_TEMPLATE_REL)),
            'referencedCount' => count(array_filter($items, static fn (array $item): bool => $item['referenced'] === true)),
            'unreferencedRelationshipCount' => count($unreferencedRelationshipIds),
            'internalCount' => count(array_filter($items, static fn (array $item): bool => $item['relationshipType'] === self::ATTACHED_TEMPLATE_REL && $item['external'] === false)),
            'externalCount' => count(array_filter($items, static fn (array $item): bool => $item['relationshipType'] === self::ATTACHED_TEMPLATE_REL && $item['external'] === true)),
            'allowedExternalTargetCount' => count(array_filter($items, static fn (array $item): bool => $item['relationshipType'] === self::ATTACHED_TEMPLATE_REL && $item['external'] === true && ($item['externalTargetAllowed'] ?? null) === true)),
            'unsafeExternalTargetCount' => count(array_filter($items, static fn (array $item): bool => $item['relationshipType'] === self::ATTACHED_TEMPLATE_REL && $item['external'] === true && ($item['externalTargetAllowed'] ?? null) !== true)),
            'externalTargetKindCounts' => $externalTargetKindCounts,
            'externalTargetSchemeCounts' => $externalTargetSchemeCounts,
            'externalTargetIssueCodes' => array_keys($externalTargetIssueCodes),
            'existingCount' => count(array_filter($items, static fn (array $item): bool => $item['relationshipType'] === self::ATTACHED_TEMPLATE_REL && $item['exists'] === true)),
            'missingCount' => count(array_filter($items, static fn (array $item): bool => in_array('missing-in-package', $item['issues'], true))),
            'unresolvedCount' => count(array_filter(
                $items,
                static fn (array $item): bool => in_array('missing-relationship-id', $item['issues'], true) || in_array('unknown-relationship', $item['issues'], true),
            )),
            'unexpectedRelationshipTypeCount' => count(array_filter($items, static fn (array $item): bool => in_array('unexpected-relationship-type', $item['issues'], true))),
            'missingContentTypeCount' => count(array_filter($items, static fn (array $item): bool => in_array('missing-content-type', $item['issues'], true))),
            'issueCount' => $issueCount,
            'relationshipIds' => $relationshipIds,
            'referencedRelationshipIds' => $referencedRelationshipIds,
            'unreferencedRelationshipIds' => $unreferencedRelationshipIds,
            'partNames' => $partNames,
            'externalTargets' => $externalTargets,
            'contentTypes' => $contentTypesSeen,
            'issueCodes' => array_keys($issueCodes),
            'byRelationshipId' => $byRelationshipId,
            'items' => $items,
            'byteExposurePolicy' => 'attached-template-bytes-blocked',
            'reviewPolicy' => 'attached-template-metadata-only',
        ];
    }

    /**
     * @param array<string, string> $parts
     * @param array{id:string, type:string, target:string, targetMode:string, resolvedTarget:string}|null $relationship
     * @param array{defaults:array<string, string>, overrides:array<string, string>} $contentTypes
     * @return array<string, mixed>
     */
    private function attachedTemplateItem(
        array $parts,
        ?array $relationship,
        string $settingsPart,
        string $settingsRelationshipsPart,
        array $contentTypes,
        string $relationshipId,
        int $index,
        bool $referenced
    ): array {
        $item = [
            'index' => $index,
            'relationshipId' => $relationshipId,
            'referenced' => $referenced,
            'relationshipType' => null,
            'target' => null,
            'targetMode' => null,
            'resolvedTarget' => null,
            'external' => false,
            'partName' => null,
            'targetPart' => null,
            'targetQuery' => null,
            'targetFragment' => null,
            'targetReferenceSuffix' => '',
            'exists' => false,
            'bytes' => 0,
            'byteLength' => null,
            'crc32' => null,
            'sha256' => null,
            'contentType' => '',
            'contentTypeBase' => '',
            'contentTypeHasParameters' => false,
            'contentTypeParameterCount' => 0,
            'contentTypeParameters' => [],
            'contentTypeParameterMap' => [],
            'contentTypeSource' => 'missing',
            'defaultExtension' => null,
            'overridePartName' => null,
            'externalTargetKind' => null,
            'externalTargetScheme' => null,
            'externalTargetAllowed' => null,
            'externalTargetIssues' => [],
            'settingsPart' => $settingsPart,
            'settingsRelationshipsPart' => $settingsRelationshipsPart,
            'byteExposurePolicy' => 'attached-template-bytes-blocked',
            'reviewPolicy' => 'attached-template-metadata-only',
            'relationship' => null,
            'issues' => [],
        ];

        if ($relationshipId === '') {
            $item['issues'][] = 'missing-relationship-id';
            return $item;
        }

        if (!is_array($relationship)) {
            $item['issues'][] = 'unknown-relationship';
            return $item;
        }

        $summary = $this->relationshipInventorySummary($parts, $relationship, $settingsPart, $settingsRelationshipsPart, $contentTypes);
        $targetPart = is_string($summary['targetPart'] ?? null) ? $summary['targetPart'] : null;
        $exists = (bool) $summary['exists'];

        $item['relationshipType'] = $summary['type'];
        $item['target'] = $summary['target'];
        $item['targetMode'] = $summary['targetMode'];
        $item['resolvedTarget'] = $summary['resolvedTarget'];
        $item['external'] = (bool) $summary['external'];
        $item['partName'] = $targetPart;
        $item['targetPart'] = $targetPart;
        $item['targetQuery'] = $summary['targetQuery'];
        $item['targetFragment'] = $summary['targetFragment'];
        $item['targetReferenceSuffix'] = $summary['targetReferenceSuffix'];
        $item['exists'] = $exists;
        $item['bytes'] = $exists && $targetPart !== null ? strlen($parts[$targetPart]) : 0;
        $item['byteLength'] = $exists && $targetPart !== null ? strlen($parts[$targetPart]) : null;
        $item['crc32'] = $exists && $targetPart !== null ? sprintf('%08x', crc32($parts[$targetPart])) : null;
        $item['sha256'] = $exists && $targetPart !== null ? hash('sha256', $parts[$targetPart]) : null;
        $item['contentType'] = $summary['contentType'];
        $item['contentTypeBase'] = $summary['contentTypeBase'];
        $item['contentTypeHasParameters'] = $summary['contentTypeHasParameters'];
        $item['contentTypeParameterCount'] = $summary['contentTypeParameterCount'];
        $item['contentTypeParameters'] = $summary['contentTypeParameters'];
        $item['contentTypeParameterMap'] = $summary['contentTypeParameterMap'];
        $item['contentTypeSource'] = $summary['contentTypeSource'];
        $item['defaultExtension'] = $summary['defaultExtension'];
        $item['overridePartName'] = $summary['overridePartName'];
        $item['externalTargetKind'] = $summary['externalTargetKind'];
        $item['externalTargetScheme'] = $summary['externalTargetScheme'];
        $item['externalTargetAllowed'] = $summary['externalTargetAllowed'];
        $item['externalTargetIssues'] = $summary['externalTargetIssues'];
        $item['relationship'] = $summary;

        if ($relationship['type'] !== self::ATTACHED_TEMPLATE_REL) {
            $item['issues'][] = 'unexpected-relationship-type';
            return $item;
        }

        if ($item['external'] === true) {
            foreach ($summary['externalTargetIssues'] as $issue) {
                if (is_string($issue) && $issue !== '') {
                    $this->appendUniqueString($item['issues'], $issue);
                }
            }
            return $item;
        }

        if (!$exists) {
            $item['issues'][] = 'missing-in-package';
        }

        if ($item['contentTypeSource'] === 'missing') {
            $item['issues'][] = 'missing-content-type';
        }

        return $item;
    }

    /**
     * @param array<string, string> $parts
     * @param array<string, array{id:string, type:string, target:string, targetMode:string, resolvedTarget:string}> $settingsRelationships
     * @param array{defaults:array<string, string>, overrides:array<string, string>} $contentTypes
     * @return array<string, mixed>
     */
    private function readPrinterSettings(
        array $parts,
        string $settingsPart,
        bool $settingsExists,
        string $settingsRelationshipsPart,
        array $settingsRelationships,
        array $contentTypes
    ): array {
        $items = [];
        $byRelationshipId = [];
        $byPartName = [];
        $relationshipIds = [];
        $partNames = [];
        $existingPartNames = [];
        $missingPartNames = [];
        $externalTargets = [];
        $unsafeExternalTargets = [];
        $targetReferenceSuffixes = [];
        $contentTypesSeen = [];
        $contentTypeBaseCounts = [];
        $externalTargetKindCounts = [];
        $externalTargetSchemeCounts = [];
        $externalTargetIssueCodes = [];
        $issueCodes = [];
        $issueCount = 0;

        foreach ($settingsRelationships as $relationship) {
            if ($relationship['type'] !== self::PRINTER_SETTINGS_REL) {
                continue;
            }

            $summary = $this->relationshipInventorySummary(
                $parts,
                $relationship,
                $settingsPart,
                $settingsRelationshipsPart,
                $contentTypes,
            );
            $relationshipId = is_string($summary['id'] ?? null) ? $summary['id'] : '';
            $external = (bool) ($summary['external'] ?? false);
            $targetPart = is_string($summary['targetPart'] ?? null) ? $summary['targetPart'] : null;
            $exists = (bool) ($summary['exists'] ?? false);
            $contentType = is_string($summary['contentType'] ?? null) ? $summary['contentType'] : '';
            $contentTypeBase = is_string($summary['contentTypeBase'] ?? null) ? $summary['contentTypeBase'] : '';
            $targetReferenceSuffix = is_string($summary['targetReferenceSuffix'] ?? null) ? $summary['targetReferenceSuffix'] : '';
            $issues = [];

            if ($external) {
                $issues[] = 'external-printer-settings';
                foreach (($summary['externalTargetIssues'] ?? []) as $issue) {
                    if (is_string($issue) && $issue !== '') {
                        $issues[] = $issue;
                        $externalTargetIssueCodes[$issue] = true;
                    }
                }
            } else {
                if (!$exists) {
                    $issues[] = 'missing-printer-settings';
                }
                if (($summary['contentTypeSource'] ?? 'missing') === 'missing') {
                    $issues[] = 'missing-printer-settings-content-type';
                } elseif ($contentTypeBase !== self::CT_WORD_PRINTER_SETTINGS) {
                    $issues[] = 'unexpected-printer-settings-content-type';
                }
            }

            $issues = array_values(array_unique($issues));
            sort($issues, SORT_STRING);

            $item = [
                'index' => count($items),
                'relationshipId' => $relationshipId,
                'relationshipKey' => $settingsRelationshipsPart . '#' . $relationshipId,
                'sourcePart' => $settingsPart,
                'sourcePartExists' => $settingsExists,
                'relationshipsPart' => $settingsRelationshipsPart,
                'relationshipsPartExists' => isset($parts[$settingsRelationshipsPart]),
                'relationshipType' => $summary['type'],
                'target' => $summary['target'],
                'targetMode' => $summary['targetMode'],
                'external' => $external,
                'resolvedTarget' => $summary['resolvedTarget'],
                'partName' => $targetPart,
                'targetPart' => $targetPart,
                'targetQuery' => $summary['targetQuery'],
                'targetFragment' => $summary['targetFragment'],
                'targetReferenceSuffix' => $targetReferenceSuffix,
                'targetParentTraversalCount' => $summary['targetParentTraversalCount'],
                'targetHasParentTraversal' => $summary['targetHasParentTraversal'],
                'targetStartsAtPackageRoot' => $summary['targetStartsAtPackageRoot'],
                'sameSourcePart' => $summary['sameSourcePart'],
                'externalTargetKind' => $summary['externalTargetKind'],
                'externalTargetScheme' => $summary['externalTargetScheme'],
                'externalTargetAllowed' => $summary['externalTargetAllowed'],
                'externalTargetIssues' => $summary['externalTargetIssues'],
                'exists' => $exists,
                'byteLength' => !$external && $targetPart !== null && $exists ? strlen($parts[$targetPart]) : null,
                'crc32' => !$external && $targetPart !== null && $exists ? sprintf('%08x', crc32($parts[$targetPart])) : null,
                'sha256' => !$external && $targetPart !== null && $exists ? hash('sha256', $parts[$targetPart]) : null,
                'contentType' => $contentType,
                'contentTypeBase' => $contentTypeBase,
                'expectedContentTypeBase' => self::CT_WORD_PRINTER_SETTINGS,
                'contentTypeMatchesExpected' => $contentTypeBase === self::CT_WORD_PRINTER_SETTINGS,
                'contentTypeHasParameters' => $summary['contentTypeHasParameters'],
                'contentTypeParameterCount' => $summary['contentTypeParameterCount'],
                'contentTypeParameters' => $summary['contentTypeParameters'],
                'contentTypeParameterMap' => $summary['contentTypeParameterMap'],
                'contentTypeSource' => $summary['contentTypeSource'],
                'defaultExtension' => $summary['defaultExtension'],
                'overridePartName' => $summary['overridePartName'],
                'byteExposurePolicy' => 'printer-settings-bytes-blocked',
                'reviewPolicy' => 'printer-settings-metadata-only',
                'valid' => $issues === [],
                'issues' => $issues,
                'relationship' => $summary,
            ];

            $items[] = $item;
            if ($relationshipId !== '' && !isset($byRelationshipId[$relationshipId])) {
                $byRelationshipId[$relationshipId] = $item;
            }
            if ($targetPart !== null && !isset($byPartName[$targetPart])) {
                $byPartName[$targetPart] = $item;
            }

            $this->appendUniqueString($relationshipIds, $relationshipId);
            $this->appendUniqueString($partNames, $targetPart);
            $this->appendUniqueString($targetReferenceSuffixes, $targetReferenceSuffix);
            if ($contentType !== '') {
                $this->appendUniqueString($contentTypesSeen, $contentType);
            }
            if ($contentTypeBase !== '') {
                $contentTypeBaseCounts[$contentTypeBase] = ($contentTypeBaseCounts[$contentTypeBase] ?? 0) + 1;
            }
            if ($external) {
                $this->appendUniqueString($externalTargets, is_string($summary['target'] ?? null) ? $summary['target'] : null);
                if (($summary['externalTargetAllowed'] ?? null) !== true) {
                    $this->appendUniqueString($unsafeExternalTargets, is_string($summary['target'] ?? null) ? $summary['target'] : null);
                }
                $kind = is_string($summary['externalTargetKind'] ?? null) ? $summary['externalTargetKind'] : '(unknown)';
                $scheme = is_string($summary['externalTargetScheme'] ?? null) ? $summary['externalTargetScheme'] : '(none)';
                $externalTargetKindCounts[$kind] = ($externalTargetKindCounts[$kind] ?? 0) + 1;
                $externalTargetSchemeCounts[$scheme] = ($externalTargetSchemeCounts[$scheme] ?? 0) + 1;
            } elseif ($exists) {
                $this->appendUniqueString($existingPartNames, $targetPart);
            } else {
                $this->appendUniqueString($missingPartNames, $targetPart);
            }
            foreach ($issues as $issue) {
                $issueCodes[$issue] = true;
            }
            $issueCount += count($issues);
        }

        ksort($contentTypeBaseCounts, SORT_STRING);
        ksort($externalTargetKindCounts, SORT_STRING);
        ksort($externalTargetSchemeCounts, SORT_STRING);
        ksort($externalTargetIssueCodes, SORT_STRING);
        ksort($issueCodes, SORT_STRING);

        return [
            'sourcePart' => $settingsPart,
            'sourcePartExists' => $settingsExists,
            'relationshipsPart' => $settingsRelationshipsPart,
            'relationshipsPartExists' => isset($parts[$settingsRelationshipsPart]),
            'count' => count($items),
            'relationshipCount' => count($items),
            'internalCount' => count(array_filter($items, static fn (array $item): bool => $item['external'] === false)),
            'externalCount' => count(array_filter($items, static fn (array $item): bool => $item['external'] === true)),
            'allowedExternalTargetCount' => count(array_filter($items, static fn (array $item): bool => $item['external'] === true && ($item['externalTargetAllowed'] ?? null) === true)),
            'unsafeExternalTargetCount' => count(array_filter($items, static fn (array $item): bool => $item['external'] === true && ($item['externalTargetAllowed'] ?? null) !== true)),
            'existingCount' => count(array_filter($items, static fn (array $item): bool => $item['external'] === false && $item['exists'] === true)),
            'missingCount' => count(array_filter($items, static fn (array $item): bool => in_array('missing-printer-settings', $item['issues'], true))),
            'missingContentTypeCount' => count(array_filter($items, static fn (array $item): bool => in_array('missing-printer-settings-content-type', $item['issues'], true))),
            'unexpectedContentTypeCount' => count(array_filter($items, static fn (array $item): bool => in_array('unexpected-printer-settings-content-type', $item['issues'], true))),
            'issueCount' => $issueCount,
            'relationshipIds' => $relationshipIds,
            'partNames' => $partNames,
            'existingPartNames' => $existingPartNames,
            'missingPartNames' => $missingPartNames,
            'externalTargets' => $externalTargets,
            'unsafeExternalTargets' => $unsafeExternalTargets,
            'externalTargetKindCounts' => $externalTargetKindCounts,
            'externalTargetSchemeCounts' => $externalTargetSchemeCounts,
            'externalTargetIssueCodes' => array_keys($externalTargetIssueCodes),
            'targetReferenceSuffixes' => $targetReferenceSuffixes,
            'contentTypes' => $contentTypesSeen,
            'contentTypeBaseCounts' => $contentTypeBaseCounts,
            'expectedContentTypeBase' => self::CT_WORD_PRINTER_SETTINGS,
            'issueCodes' => array_keys($issueCodes),
            'byRelationshipId' => $byRelationshipId,
            'byPartName' => $byPartName,
            'items' => $items,
            'byteExposurePolicy' => 'printer-settings-bytes-blocked',
            'reviewPolicy' => 'printer-settings-metadata-only',
        ];
    }

    /**
     * @param array<string, string> $parts
     * @param array<string, array{id:string, type:string, target:string, targetMode:string, resolvedTarget:string}> $relationships
     * @param array{defaults:array<string, string>, overrides:array<string, string>} $contentTypes
     * @return array<string, mixed>
     */
    private function readCustomXmlParts(
        array $parts,
        string $documentPart,
        array $relationships,
        array $contentTypes
    ): array {
        $items = [];
        $byRelationshipId = [];
        $relationshipIds = [];
        $partNames = [];
        $relationshipsPart = $this->relationshipsPartFor($documentPart);

        foreach ($relationships as $relationship) {
            if ($relationship['type'] !== self::CUSTOM_XML_REL) {
                continue;
            }

            $relationshipId = $relationship['id'];
            $item = $this->customXmlPartItem(
                $parts,
                $relationship,
                $documentPart,
                $relationshipsPart,
                $contentTypes,
                count($items),
            );
            $items[] = $item;
        }

        $storeItemSummary = $this->annotateCustomXmlDuplicateStoreItemIds($items);
        $issueCount = 0;

        foreach ($items as $item) {
            $relationshipId = is_string($item['relationshipId'] ?? null) ? $item['relationshipId'] : '';
            if ($relationshipId === '') {
                continue;
            }
            $byRelationshipId[$relationshipId] = $item;
            $relationshipIds[] = $relationshipId;
            $this->appendUniqueString($partNames, is_string($item['partName'] ?? null) ? $item['partName'] : null);
            $issueCount += count($item['issues']);
            foreach (($item['propertiesParts']['items'] ?? []) as $propertiesItem) {
                if (is_array($propertiesItem)) {
                    $issueCount += count($propertiesItem['issues'] ?? []);
                }
            }
        }

        $propertiesPartCount = 0;
        $existingPropertiesPartCount = 0;
        $missingPropertiesPartCount = 0;
        $externalPropertiesPartCount = 0;
        $allowedExternalPropertiesPartCount = 0;
        $unsafeExternalPropertiesPartCount = 0;
        $invalidPropertiesXmlCount = 0;
        $invalidPropertiesRootCount = 0;
        $missingPropertiesStoreItemIdCount = 0;
        $propertiesIssueCount = 0;
        $issueCodes = [];
        $propertiesIssueCodes = [];
        $externalTargetIssueCodes = [];
        $propertiesExternalTargetIssueCodes = [];
        $schemaRefs = [];
        $schemaRefCounts = [];
        $rootNames = [];
        $rootNamespaceCounts = [];
        $textPreviewCount = 0;
        $rootAttributeCount = 0;
        $rootNamespaceDeclarationCount = 0;
        foreach ($items as $item) {
            $this->appendUniqueString($rootNames, is_string($item['rootName'] ?? null) ? $item['rootName'] : null);
            $rootNamespace = is_string($item['rootNamespace'] ?? null) ? $item['rootNamespace'] : '';
            if ($rootNamespace !== '') {
                $rootNamespaceCounts[$rootNamespace] = ($rootNamespaceCounts[$rootNamespace] ?? 0) + 1;
            }
            if (($item['textPreview'] ?? null) !== null) {
                ++$textPreviewCount;
            }
            $rootAttributeCount += (int) ($item['rootAttributeCount'] ?? 0);
            $rootNamespaceDeclarationCount += (int) ($item['rootNamespaceDeclarationCount'] ?? 0);
            $propertiesParts = $item['propertiesParts'];
            $propertiesPartCount += (int) $propertiesParts['count'];
            $existingPropertiesPartCount += (int) $propertiesParts['existingCount'];
            $missingPropertiesPartCount += (int) $propertiesParts['missingCount'];
            $externalPropertiesPartCount += (int) $propertiesParts['externalCount'];
            $allowedExternalPropertiesPartCount += (int) ($propertiesParts['allowedExternalTargetCount'] ?? 0);
            $unsafeExternalPropertiesPartCount += (int) ($propertiesParts['unsafeExternalTargetCount'] ?? 0);
            $invalidPropertiesXmlCount += (int) $propertiesParts['invalidXmlCount'];
            $invalidPropertiesRootCount += (int) $propertiesParts['invalidRootCount'];
            $missingPropertiesStoreItemIdCount += (int) $propertiesParts['missingStoreItemIdCount'];
            foreach ($item['issues'] as $issue) {
                if (is_string($issue) && $issue !== '') {
                    $issueCodes[$issue] = true;
                }
            }
            foreach (($item['externalTargetIssues'] ?? []) as $issue) {
                if (is_string($issue) && $issue !== '') {
                    $externalTargetIssueCodes[$issue] = true;
                }
            }
            foreach (($propertiesParts['externalTargetIssueCodes'] ?? []) as $issue) {
                if (is_string($issue) && $issue !== '') {
                    $propertiesExternalTargetIssueCodes[$issue] = true;
                }
            }
            foreach ($propertiesParts['items'] as $propertiesItem) {
                foreach (($propertiesItem['issues'] ?? []) as $issue) {
                    if (is_string($issue) && $issue !== '') {
                        $issueCodes[$issue] = true;
                        $propertiesIssueCodes[$issue] = true;
                        ++$propertiesIssueCount;
                    }
                }
                foreach (($propertiesItem['schemaRefs'] ?? []) as $schemaRef) {
                    if (!is_string($schemaRef) || $schemaRef === '') {
                        continue;
                    }
                    $schemaRefs[] = $schemaRef;
                    $schemaRefCounts[$schemaRef] = ($schemaRefCounts[$schemaRef] ?? 0) + 1;
                }
            }
        }
        ksort($issueCodes);
        ksort($propertiesIssueCodes);
        ksort($externalTargetIssueCodes);
        ksort($propertiesExternalTargetIssueCodes);
        ksort($rootNamespaceCounts);
        ksort($schemaRefCounts);
        $duplicateSchemaRefs = [];
        foreach ($schemaRefCounts as $schemaRef => $count) {
            if ($count > 1) {
                $duplicateSchemaRefs[] = $schemaRef;
            }
        }

        return [
            'count' => count($items),
            'relationshipCount' => count($relationshipIds),
            'existingCount' => count(array_filter($items, static fn (array $item): bool => $item['exists'] === true)),
            'missingCount' => count(array_filter($items, static fn (array $item): bool => in_array('missing-item-part', $item['issues'], true))),
            'externalCount' => count(array_filter($items, static fn (array $item): bool => $item['external'] === true)),
            'allowedExternalCount' => count(array_filter($items, static fn (array $item): bool => $item['external'] === true && ($item['externalTargetAllowed'] ?? null) === true)),
            'unsafeExternalCount' => count(array_filter($items, static fn (array $item): bool => $item['external'] === true && ($item['externalTargetAllowed'] ?? null) !== true)),
            'externalTargetIssueCodes' => array_keys($externalTargetIssueCodes),
            'invalidXmlCount' => count(array_filter($items, static fn (array $item): bool => in_array('invalid-xml', $item['issues'], true))),
            'missingContentTypeCount' => count(array_filter($items, static fn (array $item): bool => in_array('missing-content-type', $item['issues'], true))),
            'missingPropertiesRelationshipCount' => count(array_filter($items, static fn (array $item): bool => in_array('missing-properties-relationship', $item['issues'], true))),
            'propertiesPartCount' => $propertiesPartCount,
            'existingPropertiesPartCount' => $existingPropertiesPartCount,
            'missingPropertiesPartCount' => $missingPropertiesPartCount,
            'externalPropertiesPartCount' => $externalPropertiesPartCount,
            'allowedExternalPropertiesPartCount' => $allowedExternalPropertiesPartCount,
            'unsafeExternalPropertiesPartCount' => $unsafeExternalPropertiesPartCount,
            'propertiesExternalTargetIssueCodes' => array_keys($propertiesExternalTargetIssueCodes),
            'invalidPropertiesXmlCount' => $invalidPropertiesXmlCount,
            'invalidPropertiesRootCount' => $invalidPropertiesRootCount,
            'missingPropertiesStoreItemIdCount' => $missingPropertiesStoreItemIdCount,
            'schemaRefCount' => count($schemaRefs),
            'uniqueSchemaRefCount' => count($schemaRefCounts),
            'schemaRefs' => $schemaRefs,
            'schemaRefCounts' => $schemaRefCounts,
            'duplicateSchemaRefCount' => count($duplicateSchemaRefs),
            'duplicateSchemaRefs' => $duplicateSchemaRefs,
            'storeItemIds' => $storeItemSummary['storeItemIds'],
            'duplicateStoreItemIdCount' => count($storeItemSummary['duplicateStoreItemIds']),
            'duplicateStoreItemIds' => $storeItemSummary['duplicateStoreItemIds'],
            'duplicateStoreItemIdReferences' => $storeItemSummary['duplicateStoreItemIdReferences'],
            'rootNames' => $rootNames,
            'rootNamespaceCounts' => $rootNamespaceCounts,
            'textPreviewCount' => $textPreviewCount,
            'rootAttributeCount' => $rootAttributeCount,
            'rootNamespaceDeclarationCount' => $rootNamespaceDeclarationCount,
            'issueCount' => $issueCount,
            'issueCodes' => array_keys($issueCodes),
            'propertiesIssueCount' => $propertiesIssueCount,
            'propertiesIssueCodes' => array_keys($propertiesIssueCodes),
            'relationshipIds' => $relationshipIds,
            'partNames' => $partNames,
            'byRelationshipId' => $byRelationshipId,
            'items' => $items,
        ];
    }

    /**
     * @param list<array<string, mixed>> $items
     * @return array{storeItemIds:list<string>, duplicateStoreItemIds:list<string>, duplicateStoreItemIdReferences:array<string, list<array<string, mixed>>>}
     */
    private function annotateCustomXmlDuplicateStoreItemIds(array &$items): array
    {
        $references = [];
        foreach ($items as $itemIndex => $item) {
            $propertiesItems = $item['propertiesParts']['items'] ?? [];
            if (!is_array($propertiesItems)) {
                continue;
            }

            foreach ($propertiesItems as $propertiesIndex => $propertiesItem) {
                if (!is_array($propertiesItem)) {
                    continue;
                }

                $itemId = is_string($propertiesItem['itemId'] ?? null) ? trim($propertiesItem['itemId']) : '';
                if ($itemId === '') {
                    continue;
                }

                $references[$itemId][] = [
                    'customXmlIndex' => (int) ($item['index'] ?? $itemIndex),
                    'customXmlRelationshipId' => is_string($item['relationshipId'] ?? null) ? $item['relationshipId'] : '',
                    'customXmlPartName' => is_string($item['partName'] ?? null) ? $item['partName'] : null,
                    'propertiesIndex' => (int) ($propertiesItem['index'] ?? $propertiesIndex),
                    'propertiesRelationshipId' => is_string($propertiesItem['relationshipId'] ?? null) ? $propertiesItem['relationshipId'] : '',
                    'propertiesPartName' => is_string($propertiesItem['partName'] ?? null) ? $propertiesItem['partName'] : null,
                ];
            }
        }

        ksort($references);
        $duplicateStoreItemIds = [];
        $duplicateStoreItemIdReferences = [];
        foreach ($references as $itemId => $itemReferences) {
            if (count($itemReferences) < 2) {
                continue;
            }

            $duplicateStoreItemIds[] = $itemId;
            $duplicateStoreItemIdReferences[$itemId] = $itemReferences;
        }

        if ($duplicateStoreItemIds !== []) {
            $duplicates = array_fill_keys($duplicateStoreItemIds, true);
            foreach ($items as $itemIndex => $item) {
                $propertiesItems = $item['propertiesParts']['items'] ?? [];
                if (!is_array($propertiesItems)) {
                    continue;
                }

                $itemHasDuplicate = false;
                foreach ($propertiesItems as $propertiesIndex => $propertiesItem) {
                    if (!is_array($propertiesItem)) {
                        continue;
                    }

                    $itemId = is_string($propertiesItem['itemId'] ?? null) ? trim($propertiesItem['itemId']) : '';
                    if ($itemId === '' || !isset($duplicates[$itemId])) {
                        continue;
                    }

                    $itemHasDuplicate = true;
                    $this->appendUniqueString($items[$itemIndex]['propertiesParts']['items'][$propertiesIndex]['issues'], 'duplicate-store-item-id');
                    $propertiesRelationshipId = is_string($propertiesItem['relationshipId'] ?? null) ? $propertiesItem['relationshipId'] : '';
                    if ($propertiesRelationshipId !== '' && isset($items[$itemIndex]['propertiesParts']['byRelationshipId'][$propertiesRelationshipId])) {
                        $this->appendUniqueString($items[$itemIndex]['propertiesParts']['byRelationshipId'][$propertiesRelationshipId]['issues'], 'duplicate-store-item-id');
                    }
                }

                if ($itemHasDuplicate) {
                    $this->appendUniqueString($items[$itemIndex]['issues'], 'duplicate-store-item-id');
                }
            }
        }

        return [
            'storeItemIds' => array_keys($references),
            'duplicateStoreItemIds' => $duplicateStoreItemIds,
            'duplicateStoreItemIdReferences' => $duplicateStoreItemIdReferences,
        ];
    }

    /**
     * @param array<string, string> $parts
     * @param array<string, mixed> $headers
     * @param array<string, mixed> $footers
     * @param array<string, mixed> $footnotesPart
     * @param array<string, mixed> $footnotes
     * @param array<string, mixed> $endnotesPart
     * @param array<string, mixed> $endnotes
     * @param array<string, mixed> $commentsPart
     * @param array<string, mixed> $comments
     * @param array<string, mixed> $glossaryDocumentPart
     * @param array<string, mixed> $glossaryDocument
     * @return list<array{sourceType:string, partName:string, xml:string}>
     */
    private function contentControlSources(
        array $parts,
        string $documentPart,
        array $headers,
        array $footers,
        array $footnotesPart,
        array $footnotes,
        array $endnotesPart,
        array $endnotes,
        array $commentsPart,
        array $comments,
        array $glossaryDocumentPart,
        array $glossaryDocument,
    ): array {
        $sources = [[
            'sourceType' => 'document',
            'partName' => $documentPart,
            'xml' => $parts[$documentPart],
        ]];

        foreach (['header' => $headers, 'footer' => $footers] as $sourceType => $collection) {
            foreach (($collection['items'] ?? []) as $item) {
                if (!is_array($item) || ($item['validRoot'] ?? null) !== true) {
                    continue;
                }

                $partName = is_string($item['partName'] ?? null) ? $item['partName'] : '';
                if ($partName === '' || !isset($parts[$partName])) {
                    continue;
                }

                $sources[] = [
                    'sourceType' => $sourceType,
                    'partName' => $partName,
                    'xml' => $parts[$partName],
                ];
            }
        }

        foreach ([
            'footnotes' => [$footnotesPart, $footnotes['summary'] ?? []],
            'endnotes' => [$endnotesPart, $endnotes['summary'] ?? []],
            'comments' => [$commentsPart, $comments['summary'] ?? []],
            'glossaryDocument' => [$glossaryDocumentPart, $glossaryDocument],
        ] as $sourceType => [$part, $summary]) {
            if (!is_array($part) || !is_array($summary)) {
                continue;
            }
            if (($part['exists'] ?? false) !== true) {
                continue;
            }

            $partName = is_string($part['partName'] ?? null) ? $part['partName'] : '';
            $xml = is_string($part['xml'] ?? null) ? $part['xml'] : '';
            if ($partName === '' || $xml === '') {
                continue;
            }
            $validRoot = ($summary['validRoot'] ?? null) === true;
            if (!$validRoot && $sourceType === 'comments') {
                $validRoot = $this->xmlPartHasRoot($xml, $partName, self::NS_W, 'comments');
            }
            if (!$validRoot) {
                continue;
            }

            $sources[] = [
                'sourceType' => $sourceType,
                'partName' => $partName,
                'xml' => $xml,
            ];
        }

        return $sources;
    }

    private function xmlPartHasRoot(string $xml, string $partName, string $namespace, string $localName): bool
    {
        $dom = $this->loadXmlForProvenance($xml, $partName);
        $root = $dom instanceof \DOMDocument ? $dom->documentElement : null;

        return $root instanceof \DOMElement
            && $root->namespaceURI === $namespace
            && $root->localName === $localName;
    }

    /**
     * @param list<array{sourceType:string, partName:string, xml:string}> $sources
     * @param array<string, mixed> $customXmlParts
     * @return array<string, mixed>
     */
    private function readContentControls(array $sources, array $customXmlParts): array
    {
        $storeItemReferences = $this->customXmlStoreItemReferences($customXmlParts);
        $items = [];
        $issueCodes = [];
        $scopeCounts = [];
        $sourceTypeCounts = [];
        $storeItemIds = [];
        $matchedStoreItemIds = [];
        $byStoreItemId = [];
        $partNames = [];
        $aliases = [];
        $tags = [];
        $lockValueCounts = [];
        $appearanceValueCounts = [];
        $placeholderDocPartValues = [];
        $controlTypeCounts = [];
        $contentKindCounts = [];
        $placeholderCount = 0;
        $temporaryCount = 0;
        $showingPlaceholderCount = 0;

        foreach ($sources as $source) {
            $sourceType = $source['sourceType'];
            $partName = $source['partName'];
            $xml = $source['xml'];
            foreach ($this->contentControlItems($xml, $partName, $sourceType, $storeItemReferences, count($items)) as $item) {
                $items[] = $item;

                $scope = is_string($item['scope'] ?? null) ? $item['scope'] : 'unknown';
                $scopeCounts[$scope] = ($scopeCounts[$scope] ?? 0) + 1;
                $itemSourceType = is_string($item['sourceType'] ?? null) ? $item['sourceType'] : 'unknown';
                $sourceTypeCounts[$itemSourceType] = ($sourceTypeCounts[$itemSourceType] ?? 0) + 1;
                $this->appendUniqueString($partNames, is_string($item['partName'] ?? null) ? $item['partName'] : null);
                $alias = is_string($item['alias'] ?? null) ? $item['alias'] : '';
                $this->appendUniqueString($aliases, $alias === '' ? null : $alias);
                $tag = is_string($item['tag'] ?? null) ? $item['tag'] : '';
                $this->appendUniqueString($tags, $tag === '' ? null : $tag);
                $lock = is_string($item['lock'] ?? null) ? $item['lock'] : '';
                if ($lock !== '') {
                    $lockValueCounts[$lock] = ($lockValueCounts[$lock] ?? 0) + 1;
                }
                $appearance = is_string($item['appearance'] ?? null) ? $item['appearance'] : '';
                if ($appearance !== '') {
                    $appearanceValueCounts[$appearance] = ($appearanceValueCounts[$appearance] ?? 0) + 1;
                }
                if (($item['placeholderPresent'] ?? false) === true) {
                    ++$placeholderCount;
                    $this->appendUniqueString(
                        $placeholderDocPartValues,
                        is_string($item['placeholderDocPart'] ?? null) ? $item['placeholderDocPart'] : null
                    );
                }
                if (($item['temporary'] ?? false) === true) {
                    ++$temporaryCount;
                }
                if (($item['showingPlaceholder'] ?? false) === true) {
                    ++$showingPlaceholderCount;
                }
                $controlType = is_string($item['controlType'] ?? null) ? $item['controlType'] : '';
                if ($controlType !== '') {
                    $controlTypeCounts[$controlType] = ($controlTypeCounts[$controlType] ?? 0) + 1;
                }
                foreach (($item['contentKinds'] ?? []) as $contentKind) {
                    if (!is_string($contentKind) || $contentKind === '') {
                        continue;
                    }
                    $contentKindCounts[$contentKind] = ($contentKindCounts[$contentKind] ?? 0) + 1;
                }

                $storeItemId = is_string($item['storeItemId'] ?? null) ? $item['storeItemId'] : '';
                if ($storeItemId !== '') {
                    $this->appendUniqueString($storeItemIds, $storeItemId);
                    $byStoreItemId[$storeItemId][] = $item;
                    if (($item['matchedStoreItem'] ?? false) === true) {
                        $this->appendUniqueString($matchedStoreItemIds, $storeItemId);
                    }
                }

                foreach (($item['issues'] ?? []) as $issue) {
                    if (is_string($issue) && $issue !== '') {
                        $issueCodes[$issue] = true;
                    }
                }
            }
        }

        ksort($issueCodes, SORT_STRING);
        ksort($scopeCounts, SORT_STRING);
        ksort($sourceTypeCounts, SORT_STRING);
        ksort($byStoreItemId, SORT_STRING);
        ksort($lockValueCounts, SORT_STRING);
        ksort($appearanceValueCounts, SORT_STRING);
        ksort($controlTypeCounts, SORT_STRING);
        ksort($contentKindCounts, SORT_STRING);
        sort($placeholderDocPartValues, SORT_STRING);

        return [
            'count' => count($items),
            'dataBindingCount' => count(array_filter($items, static fn (array $item): bool => $item['dataBindingPresent'] === true)),
            'matchedDataBindingCount' => count(array_filter($items, static fn (array $item): bool => $item['matchedStoreItem'] === true)),
            'unmatchedDataBindingCount' => count(array_filter($items, static fn (array $item): bool => in_array('unmatched-store-item-id', $item['issues'], true))),
            'missingStoreItemIdCount' => count(array_filter($items, static fn (array $item): bool => in_array('missing-store-item-id', $item['issues'], true))),
            'duplicateStoreItemBindingCount' => count(array_filter($items, static fn (array $item): bool => in_array('duplicate-store-item-id', $item['issues'], true))),
            'scopeCounts' => $scopeCounts,
            'sourceTypeCounts' => $sourceTypeCounts,
            'storyPartCount' => count($partNames),
            'partNames' => $partNames,
            'storeItemIds' => $storeItemIds,
            'matchedStoreItemIds' => $matchedStoreItemIds,
            'aliasCount' => count($aliases),
            'aliases' => $aliases,
            'tags' => $tags,
            'lockCount' => array_sum($lockValueCounts),
            'lockValueCounts' => $lockValueCounts,
            'appearanceCount' => array_sum($appearanceValueCounts),
            'appearanceValueCounts' => $appearanceValueCounts,
            'placeholderCount' => $placeholderCount,
            'placeholderDocPartValues' => $placeholderDocPartValues,
            'temporaryCount' => $temporaryCount,
            'showingPlaceholderCount' => $showingPlaceholderCount,
            'controlTypeCounts' => $controlTypeCounts,
            'contentKindCounts' => $contentKindCounts,
            'issueCount' => count(array_filter($items, static fn (array $item): bool => $item['issues'] !== [])),
            'issueCodes' => array_keys($issueCodes),
            'byStoreItemId' => $byStoreItemId,
            'items' => $items,
            'byteExposurePolicy' => 'content-control-data-binding-bytes-blocked',
            'reviewPolicy' => 'content-control-data-binding-metadata-only',
        ];
    }

    /**
     * @param array<string, mixed> $storeItemReferences
     * @return list<array<string, mixed>>
     */
    private function contentControlItems(
        string $xml,
        string $partName,
        string $sourceType,
        array $storeItemReferences,
        int $offset
    ): array {
        if ($xml === '') {
            return [];
        }

        $dom = $this->loadXmlForProvenance($xml, $partName);
        if (!$dom instanceof \DOMDocument) {
            return [];
        }

        $xpath = $this->xpath($dom);
        $items = [];
        foreach ($this->elements($xpath, '//w:sdt') as $contentControl) {
            $items[] = $this->contentControlItem(
                $contentControl,
                $xpath,
                $partName,
                $sourceType,
                $offset + count($items),
                $storeItemReferences,
            );
        }

        return $items;
    }

    /**
     * @return array<string, mixed>
     */
    private function emptyContentControlSummary(): array
    {
        return [
            'count' => 0,
            'dataBindingCount' => 0,
            'matchedDataBindingCount' => 0,
            'unmatchedDataBindingCount' => 0,
            'missingStoreItemIdCount' => 0,
            'duplicateStoreItemBindingCount' => 0,
            'scopeCounts' => [],
            'sourceTypeCounts' => [],
            'storyPartCount' => 0,
            'partNames' => [],
            'storeItemIds' => [],
            'matchedStoreItemIds' => [],
            'aliasCount' => 0,
            'aliases' => [],
            'tags' => [],
            'lockCount' => 0,
            'lockValueCounts' => [],
            'appearanceCount' => 0,
            'appearanceValueCounts' => [],
            'placeholderCount' => 0,
            'placeholderDocPartValues' => [],
            'temporaryCount' => 0,
            'showingPlaceholderCount' => 0,
            'controlTypeCounts' => [],
            'contentKindCounts' => [],
            'issueCount' => 0,
            'issueCodes' => [],
            'byStoreItemId' => [],
            'items' => [],
            'byteExposurePolicy' => 'content-control-data-binding-bytes-blocked',
            'reviewPolicy' => 'content-control-data-binding-metadata-only',
        ];
    }

    /**
     * @param array<string, mixed> $storeItemReferences
     * @return array<string, mixed>
     */
    private function contentControlItem(
        \DOMElement $contentControl,
        \DOMXPath $xpath,
        string $partName,
        string $sourceType,
        int $index,
        array $storeItemReferences
    ): array {
        $properties = $this->childElement($contentControl, 'sdtPr');
        $content = $this->childElement($contentControl, 'sdtContent');
        $dataBinding = $this->childElement($properties, 'dataBinding');
        $storeItemId = $dataBinding instanceof \DOMElement ? trim($dataBinding->getAttributeNS(self::NS_W, 'storeItemID')) : '';
        $xpathValue = $dataBinding instanceof \DOMElement ? trim($dataBinding->getAttributeNS(self::NS_W, 'xpath')) : '';
        $prefixMappings = $dataBinding instanceof \DOMElement ? trim($dataBinding->getAttributeNS(self::NS_W, 'prefixMappings')) : '';
        $matchingStoreItems = $storeItemId === '' ? [] : ($storeItemReferences['byStoreItemId'][$storeItemId] ?? []);
        $placeholder = $this->contentControlPlaceholder($properties);
        $temporary = $this->childElement($properties, 'temporary');
        $showingPlaceholder = $this->childElement($properties, 'showingPlcHdr');
        $issues = [];

        if ($dataBinding instanceof \DOMElement && $storeItemId === '') {
            $issues[] = 'missing-store-item-id';
        }
        if ($storeItemId !== '' && $matchingStoreItems === []) {
            $issues[] = 'unmatched-store-item-id';
        }
        if (count($matchingStoreItems) > 1) {
            $issues[] = 'duplicate-store-item-id';
        }

        return [
            'index' => $index,
            'sourceType' => $sourceType,
            'partName' => $partName,
            'scope' => $this->contentControlScope($contentControl),
            'alias' => $properties instanceof \DOMElement ? $this->emptyStringToNull($this->childAttr($properties, 'alias', 'val')) : null,
            'tag' => $properties instanceof \DOMElement ? $this->emptyStringToNull($this->childAttr($properties, 'tag', 'val')) : null,
            'id' => $this->contentControlId($properties),
            'lock' => $properties instanceof \DOMElement ? $this->emptyStringToNull($this->childAttr($properties, 'lock', 'val')) : null,
            'appearance' => $properties instanceof \DOMElement ? $this->emptyStringToNull($this->childAttr($properties, 'appearance', 'val')) : null,
            'placeholderPresent' => $placeholder['present'],
            'placeholderDocPart' => $placeholder['docPart'],
            'temporary' => $temporary instanceof \DOMElement && $this->wordBoolean($temporary),
            'showingPlaceholder' => $showingPlaceholder instanceof \DOMElement && $this->wordBoolean($showingPlaceholder),
            'controlType' => $this->contentControlType($properties),
            'contentKinds' => $this->contentControlContentKinds($content),
            'text' => $this->contentControlText($contentControl, $xpath),
            'relationshipIds' => $this->relationshipIdsInElement($contentControl),
            'dataBindingPresent' => $dataBinding instanceof \DOMElement,
            'storeItemId' => $storeItemId === '' ? null : $storeItemId,
            'xpath' => $xpathValue === '' ? null : $xpathValue,
            'prefixMappings' => $prefixMappings === '' ? null : $prefixMappings,
            'prefixMappingCount' => $prefixMappings === '' ? 0 : count(preg_split('/\s+/', $prefixMappings) ?: []),
            'matchedStoreItem' => $matchingStoreItems !== [],
            'storeItemReferenceCount' => count($matchingStoreItems),
            'storeItemReferences' => $matchingStoreItems,
            'byteExposurePolicy' => 'content-control-data-binding-bytes-blocked',
            'reviewPolicy' => 'content-control-data-binding-metadata-only',
            'issues' => $issues,
        ];
    }

    private function contentControlId(?\DOMElement $properties): ?int
    {
        $id = $this->childElement($properties, 'id');

        return $id instanceof \DOMElement ? $this->wordOptionalIntAttr($id, 'val') : null;
    }

    /**
     * @return array{present:bool, docPart:?string}
     */
    private function contentControlPlaceholder(?\DOMElement $properties): array
    {
        $placeholder = $this->childElement($properties, 'placeholder');
        if (!$placeholder instanceof \DOMElement) {
            return [
                'present' => false,
                'docPart' => null,
            ];
        }

        return [
            'present' => true,
            'docPart' => $this->emptyStringToNull($this->childAttr($placeholder, 'docPart', 'val')),
        ];
    }

    private function contentControlScope(\DOMElement $contentControl): string
    {
        $parent = $contentControl->parentNode;
        if (!$parent instanceof \DOMElement || $parent->namespaceURI !== self::NS_W) {
            return 'unknown';
        }

        return match ($parent->localName) {
            'p', 'r', 'hyperlink' => 'inline',
            'body', 'hdr', 'ftr', 'footnote', 'endnote', 'comment', 'docPartBody', 'tc', 'txbxContent', 'sdtContent' => 'block',
            'tbl' => 'table',
            'tr' => 'row',
            default => 'nested',
        };
    }

    private function contentControlType(?\DOMElement $properties): ?string
    {
        if (!$properties instanceof \DOMElement) {
            return null;
        }

        foreach ($properties->childNodes as $child) {
            if (!$child instanceof \DOMElement || $child->namespaceURI !== self::NS_W) {
                continue;
            }
            if (in_array($child->localName, [
                'alias',
                'tag',
                'id',
                'lock',
                'placeholder',
                'showingPlcHdr',
                'dataBinding',
                'temporary',
                'appearance',
                'color',
                'rPr',
                'sdtPrChange',
            ], true)) {
                continue;
            }

            return $child->localName;
        }

        return null;
    }

    /**
     * @return list<string>
     */
    private function contentControlContentKinds(?\DOMElement $content): array
    {
        if (!$content instanceof \DOMElement) {
            return [];
        }

        $kinds = [];
        foreach ($content->childNodes as $child) {
            if ($child instanceof \DOMElement && $child->namespaceURI === self::NS_W) {
                $this->appendUniqueString($kinds, $child->localName);
            }
        }

        return $kinds;
    }

    private function contentControlText(\DOMElement $contentControl, \DOMXPath $xpath): string
    {
        $text = '';
        foreach ($this->elements($xpath, './/w:t', $contentControl) as $textNode) {
            $text .= $textNode->textContent;
        }

        return $text;
    }

    /**
     * @param array<string, mixed> $customXmlParts
     * @return array{byStoreItemId:array<string, list<array<string, mixed>>>}
     */
    private function customXmlStoreItemReferences(array $customXmlParts): array
    {
        $byStoreItemId = [];
        $items = is_array($customXmlParts['items'] ?? null) ? $customXmlParts['items'] : [];
        foreach ($items as $item) {
            if (!is_array($item)) {
                continue;
            }

            $propertiesItems = $item['propertiesParts']['items'] ?? [];
            if (!is_array($propertiesItems)) {
                continue;
            }

            foreach ($propertiesItems as $propertiesItem) {
                if (!is_array($propertiesItem)) {
                    continue;
                }

                $storeItemId = is_string($propertiesItem['itemId'] ?? null) ? trim($propertiesItem['itemId']) : '';
                if ($storeItemId === '') {
                    continue;
                }

                $byStoreItemId[$storeItemId][] = [
                    'storeItemId' => $storeItemId,
                    'customXmlIndex' => (int) ($item['index'] ?? 0),
                    'customXmlRelationshipId' => is_string($item['relationshipId'] ?? null) ? $item['relationshipId'] : '',
                    'customXmlPartName' => is_string($item['partName'] ?? null) ? $item['partName'] : null,
                    'customXmlContentType' => is_string($item['contentType'] ?? null) ? $item['contentType'] : '',
                    'customXmlRootNamespace' => is_string($item['rootNamespace'] ?? null) ? $item['rootNamespace'] : null,
                    'customXmlRootLocalName' => is_string($item['rootLocalName'] ?? null) ? $item['rootLocalName'] : null,
                    'propertiesIndex' => (int) ($propertiesItem['index'] ?? 0),
                    'propertiesRelationshipId' => is_string($propertiesItem['relationshipId'] ?? null) ? $propertiesItem['relationshipId'] : '',
                    'propertiesPartName' => is_string($propertiesItem['partName'] ?? null) ? $propertiesItem['partName'] : null,
                    'propertiesContentType' => is_string($propertiesItem['contentType'] ?? null) ? $propertiesItem['contentType'] : '',
                    'schemaRefs' => is_array($propertiesItem['schemaRefs'] ?? null) ? $propertiesItem['schemaRefs'] : [],
                    'schemaRefCount' => (int) ($propertiesItem['schemaRefCount'] ?? 0),
                    'duplicateStoreItemId' => in_array('duplicate-store-item-id', $item['issues'] ?? [], true)
                        || in_array('duplicate-store-item-id', $propertiesItem['issues'] ?? [], true),
                ];
            }
        }

        ksort($byStoreItemId, SORT_STRING);

        return ['byStoreItemId' => $byStoreItemId];
    }

    /**
     * @param array<string, string> $parts
     * @param array{id:string, type:string, target:string, targetMode:string, resolvedTarget:string} $relationship
     * @param array{defaults:array<string, string>, overrides:array<string, string>} $contentTypes
     * @return array<string, mixed>
     */
    private function customXmlPartItem(
        array $parts,
        array $relationship,
        string $documentPart,
        string $relationshipsPart,
        array $contentTypes,
        int $index
    ): array {
        $summary = $this->relationshipInventorySummary($parts, $relationship, $documentPart, $relationshipsPart, $contentTypes);
        $targetPart = is_string($summary['targetPart'] ?? null) ? $summary['targetPart'] : null;
        $external = (bool) $summary['external'];
        $exists = (bool) $summary['exists'];
        $partRelationshipsPart = $targetPart === null ? null : $this->relationshipsPartFor($targetPart);
        $partRelationships = $partRelationshipsPart === null ? [] : $this->readRelationshipsPart($parts, $partRelationshipsPart);
        $propertiesParts = $this->customXmlPropertiesParts(
            $parts,
            $targetPart,
            $partRelationshipsPart,
            $partRelationships,
            $contentTypes,
        );
        $issues = [];

        if ($external) {
            $issues[] = 'external-custom-xml';
            foreach (($summary['externalTargetIssues'] ?? []) as $issue) {
                if (is_string($issue) && $issue !== '') {
                    $issues[] = $issue;
                }
            }
        } elseif (!$exists) {
            $issues[] = 'missing-item-part';
        }
        if (!$external && $summary['contentTypeSource'] === 'missing') {
            $issues[] = 'missing-content-type';
        }
        if ($exists && $propertiesParts['count'] === 0) {
            $issues[] = 'missing-properties-relationship';
        }

        $metadata = $this->emptyCustomXmlItemMetadata();
        if ($exists && $targetPart !== null) {
            $metadata = $this->customXmlItemMetadata($parts[$targetPart], $targetPart);
            if ($metadata['validXml'] === false) {
                $issues[] = 'invalid-xml';
            }
        }
        $issues = array_values(array_unique($issues));

        return [
            'index' => $index,
            'relationshipId' => $relationship['id'],
            'relationshipType' => $relationship['type'],
            'target' => $summary['target'],
            'targetMode' => $summary['targetMode'],
            'resolvedTarget' => $summary['resolvedTarget'],
            'external' => $external,
            'partName' => $targetPart,
            'targetPart' => $targetPart,
            'targetQuery' => $summary['targetQuery'],
            'targetFragment' => $summary['targetFragment'],
            'targetReferenceSuffix' => $summary['targetReferenceSuffix'],
            'externalTargetKind' => $summary['externalTargetKind'],
            'externalTargetScheme' => $summary['externalTargetScheme'],
            'externalTargetAllowed' => $summary['externalTargetAllowed'],
            'externalTargetIssues' => $summary['externalTargetIssues'],
            'exists' => $exists,
            'bytes' => $exists && $targetPart !== null ? strlen($parts[$targetPart]) : 0,
            'contentType' => $summary['contentType'],
            'contentTypeBase' => $summary['contentTypeBase'],
            'contentTypeHasParameters' => $summary['contentTypeHasParameters'],
            'contentTypeParameterCount' => $summary['contentTypeParameterCount'],
            'contentTypeParameters' => $summary['contentTypeParameters'],
            'contentTypeParameterMap' => $summary['contentTypeParameterMap'],
            'contentTypeSource' => $summary['contentTypeSource'],
            'defaultExtension' => $summary['defaultExtension'],
            'overridePartName' => $summary['overridePartName'],
            'validXml' => $metadata['validXml'],
            'xmlParseError' => $metadata['xmlParseError'],
            'rootName' => $metadata['rootName'],
            'rootPrefix' => $metadata['rootPrefix'],
            'rootNamespace' => $metadata['rootNamespace'],
            'rootLocalName' => $metadata['rootLocalName'],
            'rootAttributes' => $metadata['rootAttributes'],
            'rootAttributeMap' => $metadata['rootAttributeMap'],
            'rootAttributeCount' => $metadata['rootAttributeCount'],
            'rootAttributesTruncated' => $metadata['rootAttributesTruncated'],
            'rootNamespaceDeclarations' => $metadata['rootNamespaceDeclarations'],
            'rootNamespaceDeclarationMap' => $metadata['rootNamespaceDeclarationMap'],
            'rootNamespaceDeclarationCount' => $metadata['rootNamespaceDeclarationCount'],
            'rootNamespaceDeclarationsTruncated' => $metadata['rootNamespaceDeclarationsTruncated'],
            'textPreview' => $metadata['textPreview'],
            'textLength' => $metadata['textLength'],
            'relationshipsPart' => $partRelationshipsPart,
            'relationshipCount' => count($partRelationships),
            'propertiesParts' => $propertiesParts,
            'relationship' => $summary,
            'issues' => $issues,
        ];
    }

    /**
     * @param array<string, string> $parts
     * @param array<string, array{id:string, type:string, target:string, targetMode:string, resolvedTarget:string}> $relationships
     * @param array{defaults:array<string, string>, overrides:array<string, string>} $contentTypes
     * @return array<string, mixed>
     */
    private function customXmlPropertiesParts(
        array $parts,
        ?string $sourcePart,
        ?string $relationshipsPart,
        array $relationships,
        array $contentTypes
    ): array {
        $items = [];
        $byRelationshipId = [];
        $relationshipIds = [];
        $partNames = [];
        $externalTargets = [];
        $unsafeExternalTargets = [];
        $externalTargetIssueCodes = [];

        if ($sourcePart === null || $relationshipsPart === null) {
            return [
                'count' => 0,
                'existingCount' => 0,
                'missingCount' => 0,
                'externalCount' => 0,
                'allowedExternalTargetCount' => 0,
                'unsafeExternalTargetCount' => 0,
                'externalTargets' => [],
                'unsafeExternalTargets' => [],
                'externalTargetIssueCodes' => [],
                'invalidXmlCount' => 0,
                'invalidRootCount' => 0,
                'missingContentTypeCount' => 0,
                'unexpectedContentTypeCount' => 0,
                'missingStoreItemIdCount' => 0,
                'relationshipIds' => [],
                'partNames' => [],
                'byRelationshipId' => [],
                'items' => [],
            ];
        }

        foreach ($relationships as $relationship) {
            if ($relationship['type'] !== self::CUSTOM_XML_PROPS_REL) {
                continue;
            }

            $item = $this->customXmlPropertiesPartItem(
                $parts,
                $relationship,
                $sourcePart,
                $relationshipsPart,
                $contentTypes,
                count($items),
            );
            $items[] = $item;
            $byRelationshipId[$relationship['id']] = $item;
            $relationshipIds[] = $relationship['id'];
            $this->appendUniqueString($partNames, is_string($item['partName'] ?? null) ? $item['partName'] : null);
            if (($item['external'] ?? false) === true) {
                $this->appendUniqueString($externalTargets, is_string($item['target'] ?? null) ? $item['target'] : null);
                if (($item['externalTargetAllowed'] ?? null) !== true) {
                    $this->appendUniqueString($unsafeExternalTargets, is_string($item['target'] ?? null) ? $item['target'] : null);
                }
                foreach (($item['externalTargetIssues'] ?? []) as $issue) {
                    if (is_string($issue) && $issue !== '') {
                        $externalTargetIssueCodes[$issue] = true;
                    }
                }
            }
        }
        ksort($externalTargetIssueCodes, SORT_STRING);

        return [
            'count' => count($items),
            'existingCount' => count(array_filter($items, static fn (array $item): bool => $item['exists'] === true)),
            'missingCount' => count(array_filter($items, static fn (array $item): bool => in_array('missing-properties-part', $item['issues'], true))),
            'externalCount' => count(array_filter($items, static fn (array $item): bool => in_array('external-properties', $item['issues'], true))),
            'allowedExternalTargetCount' => count(array_filter($items, static fn (array $item): bool => $item['external'] === true && ($item['externalTargetAllowed'] ?? null) === true)),
            'unsafeExternalTargetCount' => count(array_filter($items, static fn (array $item): bool => $item['external'] === true && ($item['externalTargetAllowed'] ?? null) !== true)),
            'externalTargets' => $externalTargets,
            'unsafeExternalTargets' => $unsafeExternalTargets,
            'externalTargetIssueCodes' => array_keys($externalTargetIssueCodes),
            'invalidXmlCount' => count(array_filter($items, static fn (array $item): bool => in_array('invalid-xml', $item['issues'], true))),
            'invalidRootCount' => count(array_filter($items, static fn (array $item): bool => in_array('unexpected-root', $item['issues'], true))),
            'missingContentTypeCount' => count(array_filter($items, static fn (array $item): bool => in_array('missing-content-type', $item['issues'], true))),
            'unexpectedContentTypeCount' => count(array_filter($items, static fn (array $item): bool => in_array('unexpected-content-type', $item['issues'], true))),
            'missingStoreItemIdCount' => count(array_filter($items, static fn (array $item): bool => in_array('missing-store-item-id', $item['issues'], true))),
            'relationshipIds' => $relationshipIds,
            'partNames' => $partNames,
            'byRelationshipId' => $byRelationshipId,
            'items' => $items,
        ];
    }

    /**
     * @param array<string, string> $parts
     * @param array{id:string, type:string, target:string, targetMode:string, resolvedTarget:string} $relationship
     * @param array{defaults:array<string, string>, overrides:array<string, string>} $contentTypes
     * @return array<string, mixed>
     */
    private function customXmlPropertiesPartItem(
        array $parts,
        array $relationship,
        string $sourcePart,
        string $relationshipsPart,
        array $contentTypes,
        int $index
    ): array {
        $summary = $this->relationshipInventorySummary($parts, $relationship, $sourcePart, $relationshipsPart, $contentTypes);
        $targetPart = is_string($summary['targetPart'] ?? null) ? $summary['targetPart'] : null;
        $external = (bool) $summary['external'];
        $exists = (bool) $summary['exists'];
        $contentTypeMatchesExpected = null;
        $issues = [];

        if ($targetPart !== null) {
            $contentTypeMatchesExpected = $summary['contentTypeBase'] === self::CT_CUSTOM_XML_PROPERTIES;
            if (!$contentTypeMatchesExpected) {
                $issues[] = $summary['contentTypeSource'] === 'missing'
                    ? 'missing-content-type'
                    : 'unexpected-content-type';
            }
        }
        if ($external) {
            $issues[] = 'external-properties';
            foreach (($summary['externalTargetIssues'] ?? []) as $issue) {
                if (is_string($issue) && $issue !== '') {
                    $issues[] = $issue;
                }
            }
        } elseif (!$exists) {
            $issues[] = 'missing-properties-part';
        }

        $metadata = [
            'validXml' => null,
            'xmlParseError' => null,
            'rootNamespace' => null,
            'rootLocalName' => null,
            'validRoot' => null,
            'itemId' => null,
            'schemaRefs' => [],
            'schemaRefCount' => 0,
            'uniqueSchemaRefs' => [],
            'duplicateSchemaRefs' => [],
        ];
        if ($exists && $targetPart !== null) {
            $metadata = $this->customXmlPropertiesMetadata($parts[$targetPart], $targetPart);
            if ($metadata['validXml'] === false) {
                $issues[] = 'invalid-xml';
            } elseif ($metadata['validRoot'] === false) {
                $issues[] = 'unexpected-root';
            }
            if ($metadata['validRoot'] === true && $metadata['itemId'] === null) {
                $issues[] = 'missing-store-item-id';
            }
            if (($metadata['duplicateSchemaRefs'] ?? []) !== []) {
                $issues[] = 'duplicate-schema-ref';
            }
        }
        $issues = array_values(array_unique($issues));

        return [
            'index' => $index,
            'relationshipId' => $relationship['id'],
            'relationshipType' => $relationship['type'],
            'target' => $summary['target'],
            'targetMode' => $summary['targetMode'],
            'resolvedTarget' => $summary['resolvedTarget'],
            'external' => $external,
            'partName' => $targetPart,
            'targetPart' => $targetPart,
            'targetQuery' => $summary['targetQuery'],
            'targetFragment' => $summary['targetFragment'],
            'targetReferenceSuffix' => $summary['targetReferenceSuffix'],
            'externalTargetKind' => $summary['externalTargetKind'],
            'externalTargetScheme' => $summary['externalTargetScheme'],
            'externalTargetAllowed' => $summary['externalTargetAllowed'],
            'externalTargetIssues' => $summary['externalTargetIssues'],
            'exists' => $exists,
            'bytes' => $exists && $targetPart !== null ? strlen($parts[$targetPart]) : 0,
            'contentType' => $summary['contentType'],
            'contentTypeBase' => $summary['contentTypeBase'],
            'contentTypeHasParameters' => $summary['contentTypeHasParameters'],
            'contentTypeParameterCount' => $summary['contentTypeParameterCount'],
            'contentTypeParameters' => $summary['contentTypeParameters'],
            'contentTypeParameterMap' => $summary['contentTypeParameterMap'],
            'contentTypeSource' => $summary['contentTypeSource'],
            'defaultExtension' => $summary['defaultExtension'],
            'overridePartName' => $summary['overridePartName'],
            'expectedContentTypeBase' => self::CT_CUSTOM_XML_PROPERTIES,
            'contentTypeMatchesExpected' => $contentTypeMatchesExpected,
            'validXml' => $metadata['validXml'],
            'xmlParseError' => $metadata['xmlParseError'],
            'rootNamespace' => $metadata['rootNamespace'],
            'rootLocalName' => $metadata['rootLocalName'],
            'validRoot' => $metadata['validRoot'],
            'itemId' => $metadata['itemId'],
            'schemaRefs' => $metadata['schemaRefs'],
            'schemaRefCount' => $metadata['schemaRefCount'],
            'uniqueSchemaRefs' => $metadata['uniqueSchemaRefs'],
            'uniqueSchemaRefCount' => count($metadata['uniqueSchemaRefs']),
            'duplicateSchemaRefs' => $metadata['duplicateSchemaRefs'],
            'duplicateSchemaRefCount' => count($metadata['duplicateSchemaRefs']),
            'relationship' => $summary,
            'issues' => $issues,
        ];
    }

    /**
     * @return array{validXml:?bool, xmlParseError:?string, rootName:?string, rootPrefix:?string, rootNamespace:?string, rootLocalName:?string, rootAttributes:list<array{name:string, prefix:?string, namespace:?string, localName:string, value:string, valueLength:int, valueTruncated:bool}>, rootAttributeMap:array<string, array{name:string, prefix:?string, namespace:?string, localName:string, value:string, valueLength:int, valueTruncated:bool}>, rootAttributeCount:int, rootAttributesTruncated:bool, rootNamespaceDeclarations:list<array{name:string, prefix:string, uri:string}>, rootNamespaceDeclarationMap:array<string, string>, rootNamespaceDeclarationCount:int, rootNamespaceDeclarationsTruncated:bool, textPreview:?string, textLength:int}
     */
    private function emptyCustomXmlItemMetadata(): array
    {
        return [
            'validXml' => null,
            'xmlParseError' => null,
            'rootName' => null,
            'rootPrefix' => null,
            'rootNamespace' => null,
            'rootLocalName' => null,
            'rootAttributes' => [],
            'rootAttributeMap' => [],
            'rootAttributeCount' => 0,
            'rootAttributesTruncated' => false,
            'rootNamespaceDeclarations' => [],
            'rootNamespaceDeclarationMap' => [],
            'rootNamespaceDeclarationCount' => 0,
            'rootNamespaceDeclarationsTruncated' => false,
            'textPreview' => null,
            'textLength' => 0,
        ];
    }

    /**
     * @return array{validXml:bool, xmlParseError:?string, rootName:?string, rootPrefix:?string, rootNamespace:?string, rootLocalName:?string, rootAttributes:list<array{name:string, prefix:?string, namespace:?string, localName:string, value:string, valueLength:int, valueTruncated:bool}>, rootAttributeMap:array<string, array{name:string, prefix:?string, namespace:?string, localName:string, value:string, valueLength:int, valueTruncated:bool}>, rootAttributeCount:int, rootAttributesTruncated:bool, rootNamespaceDeclarations:list<array{name:string, prefix:string, uri:string}>, rootNamespaceDeclarationMap:array<string, string>, rootNamespaceDeclarationCount:int, rootNamespaceDeclarationsTruncated:bool, textPreview:?string, textLength:int}
     */
    private function customXmlItemMetadata(string $xml, string $partName): array
    {
        $metadata = $this->emptyCustomXmlItemMetadata();
        $dom = $this->loadXmlForProvenance($xml, $partName);
        if (!$dom instanceof \DOMDocument) {
            $metadata['validXml'] = false;
            $metadata['xmlParseError'] = $this->lastXmlPreflightError($xml, $partName);

            return $metadata;
        }

        $root = $dom->documentElement;
        if (!$root instanceof \DOMElement) {
            $metadata['validXml'] = false;
            $metadata['xmlParseError'] = 'missing XML document element';

            return $metadata;
        }

        $metadata['validXml'] = true;
        $metadata['rootName'] = $this->qualifiedDomName($root);
        $metadata['rootPrefix'] = $this->emptyStringToNull((string) $root->prefix);
        $metadata['rootNamespace'] = $root->namespaceURI;
        $metadata['rootLocalName'] = $root->localName;

        $attributeLimit = 32;
        $attributes = $root->attributes;
        if (!$attributes instanceof \DOMNamedNodeMap) {
            $attributes = [];
        }
        foreach ($attributes as $attribute) {
            if (!$attribute instanceof \DOMAttr) {
                continue;
            }

            $isNamespaceDeclaration = $attribute->namespaceURI === 'http://www.w3.org/2000/xmlns/' || $attribute->name === 'xmlns';
            if ($isNamespaceDeclaration) {
                $prefix = $attribute->name === 'xmlns' ? '' : $attribute->localName;
                if (array_key_exists($prefix, $metadata['rootNamespaceDeclarationMap'])) {
                    continue;
                }

                ++$metadata['rootNamespaceDeclarationCount'];
                if (count($metadata['rootNamespaceDeclarations']) >= $attributeLimit) {
                    $metadata['rootNamespaceDeclarationsTruncated'] = true;
                    continue;
                }

                $declaration = [
                    'name' => $attribute->name,
                    'prefix' => $prefix,
                    'uri' => $attribute->value,
                ];
                $metadata['rootNamespaceDeclarations'][] = $declaration;
                $metadata['rootNamespaceDeclarationMap'][$prefix] = $attribute->value;
                continue;
            }

            ++$metadata['rootAttributeCount'];
            if (count($metadata['rootAttributes']) >= $attributeLimit) {
                $metadata['rootAttributesTruncated'] = true;
                continue;
            }

            $attributeName = $this->qualifiedDomAttributeName($attribute);
            $record = [
                'name' => $attributeName,
                'prefix' => $this->emptyStringToNull((string) $attribute->prefix),
                'namespace' => $attribute->namespaceURI,
                'localName' => $attribute->localName,
                'value' => $this->boundedMetadataString($attribute->value),
                'valueLength' => strlen($attribute->value),
                'valueTruncated' => strlen($attribute->value) > 120,
            ];
            $metadata['rootAttributes'][] = $record;
            $metadata['rootAttributeMap'][$attributeName] = $record;
        }

        $xpath = new \DOMXPath($dom);
        $namespaceNodes = $xpath->query('namespace::*', $root);
        if ($namespaceNodes instanceof \DOMNodeList) {
            foreach ($namespaceNodes as $namespaceNode) {
                $prefix = $namespaceNode->nodeName === 'xmlns' ? '' : $namespaceNode->localName;
                $uri = (string) $namespaceNode->nodeValue;
                if ($prefix === 'xml' && $uri === 'http://www.w3.org/XML/1998/namespace') {
                    continue;
                }
                if (array_key_exists($prefix, $metadata['rootNamespaceDeclarationMap'])) {
                    continue;
                }

                ++$metadata['rootNamespaceDeclarationCount'];
                if (count($metadata['rootNamespaceDeclarations']) >= $attributeLimit) {
                    $metadata['rootNamespaceDeclarationsTruncated'] = true;
                    continue;
                }

                $declaration = [
                    'name' => $namespaceNode->nodeName,
                    'prefix' => $prefix,
                    'uri' => $uri,
                ];
                $metadata['rootNamespaceDeclarations'][] = $declaration;
                $metadata['rootNamespaceDeclarationMap'][$prefix] = $uri;
            }
        }

        ksort($metadata['rootAttributeMap']);
        ksort($metadata['rootNamespaceDeclarationMap']);

        $text = trim(preg_replace('/\s+/u', ' ', $root->textContent) ?? $root->textContent);
        $metadata['textPreview'] = $text === '' ? null : $this->boundedMetadataString($text);
        $metadata['textLength'] = strlen($text);

        return $metadata;
    }

    private function qualifiedDomName(\DOMElement $element): string
    {
        $prefix = $element->prefix;

        return is_string($prefix) && $prefix !== '' ? $prefix . ':' . $element->localName : $element->localName;
    }

    private function qualifiedDomAttributeName(\DOMAttr $attribute): string
    {
        $prefix = $attribute->prefix;

        return is_string($prefix) && $prefix !== '' ? $prefix . ':' . $attribute->localName : $attribute->localName;
    }

    private function boundedMetadataString(string $value): string
    {
        if (strlen($value) <= 120) {
            return $value;
        }

        if (function_exists('mb_substr')) {
            return mb_substr($value, 0, 120, 'UTF-8') . '...';
        }

        return substr($value, 0, 120) . '...';
    }

    /**
     * @return array{validXml:bool, xmlParseError:?string, rootNamespace:?string, rootLocalName:?string, validRoot:bool, itemId:?string, schemaRefs:list<string>, schemaRefCount:int, uniqueSchemaRefs:list<string>, duplicateSchemaRefs:list<string>}
     */
    private function customXmlPropertiesMetadata(string $xml, string $partName): array
    {
        $dom = $this->loadXmlForProvenance($xml, $partName);
        if (!$dom instanceof \DOMDocument) {
            return [
                'validXml' => false,
                'xmlParseError' => $this->lastXmlPreflightError($xml, $partName),
                'rootNamespace' => null,
                'rootLocalName' => null,
                'validRoot' => false,
                'itemId' => null,
                'schemaRefs' => [],
                'schemaRefCount' => 0,
                'uniqueSchemaRefs' => [],
                'duplicateSchemaRefs' => [],
            ];
        }

        $root = $dom->documentElement;
        $validRoot = $root instanceof \DOMElement
            && $root->namespaceURI === self::NS_DS
            && $root->localName === 'datastoreItem';
        $schemaRefs = [];
        $schemaRefCounts = [];
        if ($validRoot) {
            $xpath = $this->xpath($dom);
            foreach ($this->elements($xpath, '/ds:datastoreItem/ds:schemaRefs/ds:schemaRef') as $schemaRef) {
                $uri = $schemaRef->getAttributeNS(self::NS_DS, 'uri');
                if ($uri !== '') {
                    $schemaRefs[] = $uri;
                    $schemaRefCounts[$uri] = ($schemaRefCounts[$uri] ?? 0) + 1;
                }
            }
        }
        ksort($schemaRefCounts);
        $duplicateSchemaRefs = [];
        foreach ($schemaRefCounts as $uri => $count) {
            if ($count > 1) {
                $duplicateSchemaRefs[] = $uri;
            }
        }

        return [
            'validXml' => $root instanceof \DOMElement,
            'xmlParseError' => null,
            'rootNamespace' => $root instanceof \DOMElement ? $root->namespaceURI : null,
            'rootLocalName' => $root instanceof \DOMElement ? $root->localName : null,
            'validRoot' => $validRoot,
            'itemId' => $validRoot && $root instanceof \DOMElement ? $this->emptyStringToNull($root->getAttributeNS(self::NS_DS, 'itemID')) : null,
            'schemaRefs' => $schemaRefs,
            'schemaRefCount' => count($schemaRefs),
            'uniqueSchemaRefs' => array_keys($schemaRefCounts),
            'duplicateSchemaRefs' => $duplicateSchemaRefs,
        ];
    }

    private function loadXmlForProvenance(string $xml, string $partName): ?\DOMDocument
    {
        if ($xml === '') {
            return null;
        }

        $dom = new \DOMDocument();
        $previous = libxml_use_internal_errors(true);
        $ok = $dom->loadXML($xml, LIBXML_NONET | LIBXML_NOERROR | LIBXML_NOWARNING);
        libxml_clear_errors();
        libxml_use_internal_errors($previous);

        return $ok ? $dom : null;
    }

    private function lastXmlPreflightError(string $xml, string $partName): string
    {
        if ($xml === '') {
            return 'empty XML part';
        }

        $dom = new \DOMDocument();
        $previous = libxml_use_internal_errors(true);
        $ok = $dom->loadXML($xml, LIBXML_NONET | LIBXML_NOERROR | LIBXML_NOWARNING);
        if ($ok) {
            libxml_clear_errors();
            libxml_use_internal_errors($previous);

            return '';
        }
        $errors = libxml_get_errors();
        libxml_clear_errors();
        libxml_use_internal_errors($previous);

        return $errors === [] ? "Invalid DOCX XML part {$partName}" : trim($errors[0]->message);
    }

    /**
     * @param array<string, string> $parts
     * @param array<string, array{id:string, type:string, target:string, targetMode:string, resolvedTarget:string}> $relationships
     * @param array{defaults:array<string, string>, overrides:array<string, string>} $contentTypes
     * @return array<string, mixed>
     */
    private function relatedPartRelationshipDiagnostics(
        array $parts,
        array $relationships,
        string $sourcePart,
        string $relationshipsPart,
        array $contentTypes
    ): array {
        $items = [];
        $byId = [];
        $relationshipIds = [];
        $targetParts = [];
        $externalTargets = [];
        $targetReferenceSuffixes = [];
        $issueCodes = [];
        $internalCount = 0;
        $externalCount = 0;
        $existingCount = 0;
        $missingCount = 0;
        $missingContentTypeCount = 0;
        $issueCount = 0;
        $relationshipPart = $this->relationshipPartProvenance(
            $parts,
            $relationshipsPart,
            $sourcePart,
            $relationships,
            $contentTypes,
        );
        $relationshipRecords = is_array($relationshipPart['relationshipRecords'] ?? null)
            ? $relationshipPart['relationshipRecords']
            : [];

        foreach ($relationships as $relationship) {
            $item = $this->relationshipInventorySummary($parts, $relationship, $sourcePart, $relationshipsPart, $contentTypes);
            $issues = [];
            $this->appendUniqueString($relationshipIds, is_string($item['id'] ?? null) ? $item['id'] : null);
            if (($item['external'] ?? false) === true) {
                ++$externalCount;
                $this->appendUniqueString($externalTargets, is_string($item['target'] ?? null) ? $item['target'] : null);
            } else {
                ++$internalCount;
                $targetPart = is_string($item['targetPart'] ?? null) ? $item['targetPart'] : null;
                $this->appendUniqueString($targetParts, $targetPart);
                if (($item['exists'] ?? false) === true) {
                    ++$existingCount;
                } else {
                    ++$missingCount;
                    $issues[] = 'missing-target-part';
                }
                if (($item['contentTypeSource'] ?? 'missing') === 'missing') {
                    ++$missingContentTypeCount;
                    $issues[] = 'missing-target-content-type';
                }
            }

            $targetReferenceSuffix = is_string($item['targetReferenceSuffix'] ?? null) ? $item['targetReferenceSuffix'] : '';
            $this->appendUniqueString($targetReferenceSuffixes, $targetReferenceSuffix);
            foreach ($issues as $issue) {
                $issueCodes[$issue] = true;
            }
            if ($issues !== []) {
                ++$issueCount;
            }
            $item['issues'] = $issues;
            $items[] = $item;
            if (is_string($item['id'] ?? null) && $item['id'] !== '') {
                $byId[$item['id']] = $item;
            }
        }

        ksort($issueCodes, SORT_STRING);
        $targetCollisions = $this->relatedPartInternalExternalTargetCollisions($items);
        $internalTargetCollisions = $this->relatedPartSameModeTargetCollisions($items, false);
        $externalTargetCollisions = $this->relatedPartSameModeTargetCollisions($items, true);
        $repeatedTargetSuffixes = $this->relatedPartRepeatedTargetReferenceSuffixes($items);
        $recordTargetCollisions = $this->relatedPartInternalExternalTargetCollisions($relationshipRecords);
        $recordInternalTargetCollisions = $this->relatedPartSameModeTargetCollisions($relationshipRecords, false);
        $recordExternalTargetCollisions = $this->relatedPartSameModeTargetCollisions($relationshipRecords, true);
        $recordRepeatedTargetSuffixes = $this->relatedPartRepeatedTargetReferenceSuffixes($relationshipRecords);

        return [
            'sourcePart' => $sourcePart,
            'relationshipsPart' => $relationshipsPart,
            'relationshipCount' => count($items),
            'relationshipRecordCount' => (int) ($relationshipPart['relationshipRecordCount'] ?? count($relationshipRecords)),
            'duplicateRelationshipIdCount' => (int) ($relationshipPart['duplicateRelationshipIdCount'] ?? 0),
            'duplicateRelationshipRecordCount' => (int) ($relationshipPart['duplicateRelationshipRecordCount'] ?? 0),
            'duplicateRelationshipIds' => is_array($relationshipPart['duplicateRelationshipIds'] ?? null)
                ? $relationshipPart['duplicateRelationshipIds']
                : [],
            'duplicateRelationshipIdItems' => is_array($relationshipPart['duplicateRelationshipIdItems'] ?? null)
                ? $relationshipPart['duplicateRelationshipIdItems']
                : [],
            'invalidRelationshipRecordCount' => (int) ($relationshipPart['invalidRelationshipRecordCount'] ?? 0),
            'relationshipRecordIssueCount' => (int) ($relationshipPart['relationshipRecordIssueCount'] ?? 0),
            'relationshipRecordIssueCodes' => is_array($relationshipPart['relationshipRecordIssueCodes'] ?? null)
                ? $relationshipPart['relationshipRecordIssueCodes']
                : [],
            'invalidRelationshipRecords' => is_array($relationshipPart['invalidRelationshipRecords'] ?? null)
                ? $relationshipPart['invalidRelationshipRecords']
                : [],
            'internalRelationshipCount' => $internalCount,
            'externalRelationshipCount' => $externalCount,
            'existingTargetCount' => $existingCount,
            'missingTargetCount' => $missingCount,
            'missingContentTypeCount' => $missingContentTypeCount,
            'targetReferenceSuffixCount' => count($targetReferenceSuffixes),
            'relationshipIds' => $relationshipIds,
            'targetParts' => $targetParts,
            'externalTargets' => $externalTargets,
            'targetReferenceSuffixes' => $targetReferenceSuffixes,
            'internalExternalTargetCollisionCount' => $targetCollisions['groupCount'],
            'internalExternalTargetCollisionRelationshipCount' => $targetCollisions['relationshipCount'],
            'internalExternalTargetCollisions' => $targetCollisions['groups'],
            'internalTargetCollisionCount' => $internalTargetCollisions['groupCount'],
            'internalTargetCollisionRelationshipCount' => $internalTargetCollisions['relationshipCount'],
            'internalTargetCollisions' => $internalTargetCollisions['groups'],
            'externalTargetCollisionCount' => $externalTargetCollisions['groupCount'],
            'externalTargetCollisionRelationshipCount' => $externalTargetCollisions['relationshipCount'],
            'externalTargetCollisions' => $externalTargetCollisions['groups'],
            'repeatedTargetReferenceSuffixCount' => $repeatedTargetSuffixes['groupCount'],
            'repeatedTargetReferenceSuffixRelationshipCount' => $repeatedTargetSuffixes['relationshipCount'],
            'repeatedTargetReferenceSuffixes' => $repeatedTargetSuffixes['suffixes'],
            'repeatedTargetReferenceSuffixGroups' => $repeatedTargetSuffixes['groups'],
            'recordInternalExternalTargetCollisionCount' => $recordTargetCollisions['groupCount'],
            'recordInternalExternalTargetCollisionRelationshipCount' => $recordTargetCollisions['relationshipCount'],
            'recordInternalExternalTargetCollisions' => $recordTargetCollisions['groups'],
            'recordInternalTargetCollisionCount' => $recordInternalTargetCollisions['groupCount'],
            'recordInternalTargetCollisionRelationshipCount' => $recordInternalTargetCollisions['relationshipCount'],
            'recordInternalTargetCollisions' => $recordInternalTargetCollisions['groups'],
            'recordExternalTargetCollisionCount' => $recordExternalTargetCollisions['groupCount'],
            'recordExternalTargetCollisionRelationshipCount' => $recordExternalTargetCollisions['relationshipCount'],
            'recordExternalTargetCollisions' => $recordExternalTargetCollisions['groups'],
            'recordRepeatedTargetReferenceSuffixCount' => $recordRepeatedTargetSuffixes['groupCount'],
            'recordRepeatedTargetReferenceSuffixRelationshipCount' => $recordRepeatedTargetSuffixes['relationshipCount'],
            'recordRepeatedTargetReferenceSuffixes' => $recordRepeatedTargetSuffixes['suffixes'],
            'recordRepeatedTargetReferenceSuffixGroups' => $recordRepeatedTargetSuffixes['groups'],
            'issueCount' => $issueCount,
            'issueCodes' => array_keys($issueCodes),
            'byId' => $byId,
            'items' => $items,
            'relationshipRecords' => $relationshipRecords,
        ];
    }

    /**
     * @param list<array<string, mixed>> $items
     * @return array{groupCount:int, relationshipCount:int, groups:list<array<string, mixed>>}
     */
    private function relatedPartSameModeTargetCollisions(array $items, bool $external): array
    {
        $byTarget = [];
        foreach ($items as $item) {
            if ((($item['external'] ?? false) === true) !== $external) {
                continue;
            }

            $relationshipId = is_string($item['id'] ?? null) ? $item['id'] : '';
            $target = $external
                ? (is_string($item['resolvedTarget'] ?? null) ? $item['resolvedTarget'] : '')
                : (is_string($item['targetPart'] ?? null) ? $item['targetPart'] : '');
            if ($relationshipId === '' || $target === '') {
                continue;
            }

            $byTarget[$target] ??= [
                'target' => $target,
                'relationshipIds' => [],
                'ordinals' => [],
                'targetParts' => [],
                'externalTargets' => [],
                'targets' => [],
                'resolvedTargets' => [],
                'targetReferenceSuffixes' => [],
                'relationships' => [],
            ];
            if ($external) {
                $byTarget[$target]['externalTarget'] = $target;
            } else {
                $byTarget[$target]['targetPart'] = $target;
            }

            $this->appendUniqueString($byTarget[$target]['relationshipIds'], $relationshipId);
            if (is_int($item['ordinal'] ?? null)) {
                $byTarget[$target]['ordinals'][] = $item['ordinal'];
            }
            $this->appendUniqueString($byTarget[$target]['targetParts'], is_string($item['targetPart'] ?? null) ? $item['targetPart'] : null);
            if (($item['external'] ?? false) === true) {
                $this->appendUniqueString($byTarget[$target]['externalTargets'], is_string($item['resolvedTarget'] ?? null) ? $item['resolvedTarget'] : null);
            }
            $this->appendUniqueString($byTarget[$target]['targets'], is_string($item['target'] ?? null) ? $item['target'] : null);
            $this->appendUniqueString($byTarget[$target]['resolvedTargets'], is_string($item['resolvedTarget'] ?? null) ? $item['resolvedTarget'] : null);
            $this->appendUniqueString($byTarget[$target]['targetReferenceSuffixes'], is_string($item['targetReferenceSuffix'] ?? null) ? $item['targetReferenceSuffix'] : null);
            $byTarget[$target]['relationships'][] = $item;
        }

        $groups = [];
        $relationshipCount = 0;
        foreach ($byTarget as $group) {
            if (count($group['relationships']) < 2) {
                continue;
            }

            $groups[] = $group;
            $relationshipCount += count($group['relationships']);
        }

        return [
            'groupCount' => count($groups),
            'relationshipCount' => $relationshipCount,
            'groups' => $groups,
        ];
    }

    /**
     * @param list<array<string, mixed>> $items
     * @return array{groupCount:int, relationshipCount:int, groups:list<array<string, mixed>>}
     */
    private function relatedPartInternalExternalTargetCollisions(array $items): array
    {
        $byTarget = [];
        foreach ($items as $item) {
            $target = is_string($item['target'] ?? null) ? $this->stripQueryAndFragment($item['target']) : '';
            $relationshipId = is_string($item['id'] ?? null) ? $item['id'] : '';
            if ($target === '' || $relationshipId === '') {
                continue;
            }

            $byTarget[$target] ??= [
                'target' => $target,
                'relationshipIds' => [],
                'internalRelationshipIds' => [],
                'externalRelationshipIds' => [],
                'targetParts' => [],
                'externalTargets' => [],
                'targetReferenceSuffixes' => [],
                'relationships' => [],
            ];
            $this->appendUniqueString($byTarget[$target]['relationshipIds'], $relationshipId);
            if (($item['external'] ?? false) === true) {
                $this->appendUniqueString($byTarget[$target]['externalRelationshipIds'], $relationshipId);
                $this->appendUniqueString($byTarget[$target]['externalTargets'], is_string($item['resolvedTarget'] ?? null) ? $item['resolvedTarget'] : null);
            } else {
                $this->appendUniqueString($byTarget[$target]['internalRelationshipIds'], $relationshipId);
                $this->appendUniqueString($byTarget[$target]['targetParts'], is_string($item['targetPart'] ?? null) ? $item['targetPart'] : null);
            }
            $this->appendUniqueString($byTarget[$target]['targetReferenceSuffixes'], is_string($item['targetReferenceSuffix'] ?? null) ? $item['targetReferenceSuffix'] : null);
            $byTarget[$target]['relationships'][] = $item;
        }

        $groups = [];
        $relationshipCount = 0;
        foreach ($byTarget as $group) {
            if ($group['internalRelationshipIds'] === [] || $group['externalRelationshipIds'] === []) {
                continue;
            }

            $groups[] = $group;
            $relationshipCount += count($group['relationships']);
        }

        return [
            'groupCount' => count($groups),
            'relationshipCount' => $relationshipCount,
            'groups' => $groups,
        ];
    }

    /**
     * @param list<array<string, mixed>> $items
     * @return array{groupCount:int, relationshipCount:int, suffixes:list<string>, groups:list<array<string, mixed>>}
     */
    private function relatedPartRepeatedTargetReferenceSuffixes(array $items): array
    {
        $bySuffix = [];
        foreach ($items as $item) {
            $suffix = is_string($item['targetReferenceSuffix'] ?? null) ? $item['targetReferenceSuffix'] : '';
            $relationshipId = is_string($item['id'] ?? null) ? $item['id'] : '';
            if ($suffix === '' || $relationshipId === '') {
                continue;
            }

            $bySuffix[$suffix] ??= [
                'targetReferenceSuffix' => $suffix,
                'relationshipIds' => [],
                'targetParts' => [],
                'externalTargets' => [],
                'targets' => [],
                'relationships' => [],
            ];
            $this->appendUniqueString($bySuffix[$suffix]['relationshipIds'], $relationshipId);
            $this->appendUniqueString($bySuffix[$suffix]['targetParts'], is_string($item['targetPart'] ?? null) ? $item['targetPart'] : null);
            if (($item['external'] ?? false) === true) {
                $this->appendUniqueString($bySuffix[$suffix]['externalTargets'], is_string($item['resolvedTarget'] ?? null) ? $item['resolvedTarget'] : null);
            }
            $this->appendUniqueString($bySuffix[$suffix]['targets'], is_string($item['target'] ?? null) ? $item['target'] : null);
            $bySuffix[$suffix]['relationships'][] = $item;
        }

        $groups = [];
        $suffixes = [];
        $relationshipCount = 0;
        foreach ($bySuffix as $suffix => $group) {
            if (count($group['relationships']) < 2) {
                continue;
            }

            $groups[] = $group;
            $suffixes[] = $suffix;
            $relationshipCount += count($group['relationships']);
        }

        return [
            'groupCount' => count($groups),
            'relationshipCount' => $relationshipCount,
            'suffixes' => $suffixes,
            'groups' => $groups,
        ];
    }

    /**
     * @param list<array<string, mixed>> $items
     * @param array<string, array<string, mixed>> $byId
     * @param array<string, mixed> $relationshipDiagnostics
     * @return array<string, mixed>
     */
    private function noteCollectionSummary(array $items, array $byId, array $relationshipDiagnostics, array $xmlProvenance = []): array
    {
        $relationshipBacklinks = [];
        $referencedRelationshipIds = [];
        $missingReferencedRelationshipIds = [];
        $reconciledItems = [];
        $reconciledById = [];
        $relationships = is_array($relationshipDiagnostics['byId'] ?? null) ? $relationshipDiagnostics['byId'] : [];
        $relationshipRecords = is_array($relationshipDiagnostics['relationshipRecords'] ?? null) ? $relationshipDiagnostics['relationshipRecords'] : [];
        $relationshipRecordsById = [];
        foreach ($relationshipRecords as $record) {
            if (!is_array($record)) {
                continue;
            }

            $recordId = is_string($record['id'] ?? null) ? $record['id'] : '';
            if ($recordId === '') {
                continue;
            }

            $relationshipRecordsById[$recordId][] = $record;
        }

        $duplicateRelationshipIds = is_array($relationshipDiagnostics['duplicateRelationshipIds'] ?? null)
            ? array_values(array_filter(
                array_map('strval', $relationshipDiagnostics['duplicateRelationshipIds']),
                static fn (string $value): bool => $value !== '',
            ))
            : [];
        $duplicateRelationshipIdSet = array_fill_keys($duplicateRelationshipIds, true);

        foreach ($items as $item) {
            $relationshipIds = is_array($item['relationshipIds'] ?? null) ? $item['relationshipIds'] : [];
            $knownRelationshipIds = [];
            $itemDuplicateRelationshipIds = [];
            $itemReferencedRelationships = [];
            $itemReferencedRelationshipItems = [];
            $itemReferencedRelationshipRecords = [];
            $itemRelationshipBacklinks = [];
            foreach ($relationshipIds as $relationshipId) {
                if (!is_string($relationshipId) || $relationshipId === '') {
                    continue;
                }

                $itemId = is_string($item['id'] ?? null) ? $item['id'] : '';
                $backlink = [
                    'relationshipId' => $relationshipId,
                    'itemId' => $itemId,
                    'sourceType' => is_string($item['sourceType'] ?? null) ? $item['sourceType'] : null,
                    'known' => isset($relationships[$relationshipId]),
                ];
                $this->appendUniqueString($referencedRelationshipIds, $relationshipId);
                if (isset($relationships[$relationshipId])) {
                    $this->appendUniqueString($knownRelationshipIds, $relationshipId);
                    $itemReferencedRelationships[$relationshipId] = $relationships[$relationshipId];
                    $itemReferencedRelationshipItems[] = $relationships[$relationshipId];
                } else {
                    $this->appendUniqueString($missingReferencedRelationshipIds, $relationshipId);
                }
                if (isset($duplicateRelationshipIdSet[$relationshipId])) {
                    $this->appendUniqueString($itemDuplicateRelationshipIds, $relationshipId);
                }
                foreach ($relationshipRecordsById[$relationshipId] ?? [] as $record) {
                    $itemReferencedRelationshipRecords[] = $record;
                }

                $relationshipBacklinks[$relationshipId] ??= [];
                $relationshipBacklinks[$relationshipId][] = $backlink;
                $itemRelationshipBacklinks[] = $backlink;
            }

            $item['knownRelationshipIds'] = $knownRelationshipIds;
            $item['knownRelationshipCount'] = count($knownRelationshipIds);
            $item['referencedRelationshipIds'] = $knownRelationshipIds;
            $item['referencedRelationshipCount'] = count($knownRelationshipIds);
            $item['referencedDuplicateRelationshipIds'] = $itemDuplicateRelationshipIds;
            $item['referencedRelationships'] = $itemReferencedRelationships;
            $item['referencedRelationshipItems'] = $itemReferencedRelationshipItems;
            $item['missingRelationshipCount'] = count(is_array($item['missingRelationshipIds'] ?? null) ? $item['missingRelationshipIds'] : []);
            $item['duplicateRelationshipIds'] = $itemDuplicateRelationshipIds;
            $item['duplicateRelationshipCount'] = count($itemDuplicateRelationshipIds);
            $item['referencedRelationshipRecordCount'] = count($itemReferencedRelationshipRecords);
            $item['referencedRelationshipRecords'] = $itemReferencedRelationshipRecords;
            $item['relationshipBacklinks'] = $itemRelationshipBacklinks;
            $reconciledItems[] = $item;
            if (is_string($item['id'] ?? null) && $item['id'] !== '') {
                $reconciledById[$item['id']] = $item;
            }
        }

        $unreferencedRelationshipIds = [];
        foreach (($relationshipDiagnostics['relationshipIds'] ?? []) as $relationshipId) {
            if (!is_string($relationshipId) || $relationshipId === '') {
                continue;
            }

            $referenced = in_array($relationshipId, $referencedRelationshipIds, true);
            if (!$referenced) {
                $unreferencedRelationshipIds[] = $relationshipId;
            }

            if (isset($relationships[$relationshipId])) {
                $relationships[$relationshipId]['referenced'] = $referenced;
                $relationships[$relationshipId]['orphaned'] = !$referenced;
                $relationships[$relationshipId]['referencedItemIds'] = array_values(array_unique(array_map(
                    static fn (array $backlink): string => is_string($backlink['itemId'] ?? null) ? $backlink['itemId'] : '',
                    $relationshipBacklinks[$relationshipId] ?? [],
                )));
                $relationships[$relationshipId]['referencedItemIds'] = array_values(array_filter($relationships[$relationshipId]['referencedItemIds'], static fn (string $value): bool => $value !== ''));
                $relationships[$relationshipId]['referencedItemCount'] = count($relationships[$relationshipId]['referencedItemIds']);
                $relationships[$relationshipId]['referenceBacklinks'] = $relationshipBacklinks[$relationshipId] ?? [];
            }
        }

        $relationshipDiagnostics['referencedRelationshipIds'] = $referencedRelationshipIds;
        $relationshipDiagnostics['unreferencedRelationshipIds'] = $unreferencedRelationshipIds;
        $relationshipDiagnostics['orphanedRelationshipIds'] = $unreferencedRelationshipIds;
        $relationshipDiagnostics['missingReferencedRelationshipIds'] = $missingReferencedRelationshipIds;
        $relationshipDiagnostics['relationshipBacklinks'] = $relationshipBacklinks;
        $relationshipDiagnostics['byId'] = $relationships;
        $relationshipDiagnostics['items'] = array_values($relationships);
        $issueCodes = is_array($xmlProvenance['issueCodes'] ?? null) ? $xmlProvenance['issueCodes'] : [];

        return [
            'count' => count($reconciledItems),
            'ids' => array_column($reconciledItems, 'id'),
            'byId' => $reconciledById,
            'items' => $reconciledItems,
            'validXml' => $xmlProvenance['validXml'] ?? null,
            'xmlParseError' => $xmlProvenance['xmlParseError'] ?? null,
            'validRoot' => $xmlProvenance['validRoot'] ?? null,
            'rootNamespace' => $xmlProvenance['rootNamespace'] ?? null,
            'rootLocalName' => $xmlProvenance['rootLocalName'] ?? null,
            'invalidXmlCount' => (int) ($xmlProvenance['invalidXmlCount'] ?? 0),
            'invalidRootCount' => (int) ($xmlProvenance['invalidRootCount'] ?? 0),
            'issueCount' => (int) ($xmlProvenance['issueCount'] ?? count($issueCodes)),
            'issueCodes' => array_values($issueCodes),
            'relationshipsPart' => $relationshipDiagnostics['relationshipsPart'],
            'relationshipCount' => $relationshipDiagnostics['relationshipCount'],
            'relationshipRecordCount' => $relationshipDiagnostics['relationshipRecordCount'],
            'duplicateRelationshipIdCount' => $relationshipDiagnostics['duplicateRelationshipIdCount'],
            'duplicateRelationshipRecordCount' => $relationshipDiagnostics['duplicateRelationshipRecordCount'],
            'duplicateRelationshipIds' => $relationshipDiagnostics['duplicateRelationshipIds'],
            'duplicateRelationshipIdItems' => $relationshipDiagnostics['duplicateRelationshipIdItems'],
            'invalidRelationshipRecordCount' => $relationshipDiagnostics['invalidRelationshipRecordCount'],
            'relationshipRecordIssueCount' => $relationshipDiagnostics['relationshipRecordIssueCount'],
            'relationshipRecordIssueCodes' => $relationshipDiagnostics['relationshipRecordIssueCodes'],
            'invalidRelationshipRecords' => $relationshipDiagnostics['invalidRelationshipRecords'],
            'internalRelationshipCount' => $relationshipDiagnostics['internalRelationshipCount'],
            'externalRelationshipCount' => $relationshipDiagnostics['externalRelationshipCount'],
            'existingRelationshipTargetCount' => $relationshipDiagnostics['existingTargetCount'],
            'missingRelationshipTargetCount' => $relationshipDiagnostics['missingTargetCount'],
            'missingRelationshipContentTypeCount' => $relationshipDiagnostics['missingContentTypeCount'],
            'relationshipTargetReferenceSuffixCount' => $relationshipDiagnostics['targetReferenceSuffixCount'],
            'relationshipIds' => $relationshipDiagnostics['relationshipIds'],
            'referencedRelationshipIds' => $referencedRelationshipIds,
            'unreferencedRelationshipIds' => $unreferencedRelationshipIds,
            'orphanedRelationshipIds' => $unreferencedRelationshipIds,
            'missingReferencedRelationshipIds' => $missingReferencedRelationshipIds,
            'referencedRelationshipCount' => count($referencedRelationshipIds),
            'unreferencedRelationshipCount' => count($unreferencedRelationshipIds),
            'orphanedRelationshipCount' => count($unreferencedRelationshipIds),
            'missingReferencedRelationshipCount' => count($missingReferencedRelationshipIds),
            'relationshipTargetParts' => $relationshipDiagnostics['targetParts'],
            'relationshipExternalTargets' => $relationshipDiagnostics['externalTargets'],
            'relationshipTargetReferenceSuffixes' => $relationshipDiagnostics['targetReferenceSuffixes'],
            'internalExternalRelationshipTargetCollisionCount' => $relationshipDiagnostics['internalExternalTargetCollisionCount'],
            'internalExternalRelationshipTargetCollisionRelationshipCount' => $relationshipDiagnostics['internalExternalTargetCollisionRelationshipCount'],
            'internalExternalRelationshipTargetCollisions' => $relationshipDiagnostics['internalExternalTargetCollisions'],
            'internalRelationshipTargetCollisionCount' => $relationshipDiagnostics['internalTargetCollisionCount'],
            'internalRelationshipTargetCollisionRelationshipCount' => $relationshipDiagnostics['internalTargetCollisionRelationshipCount'],
            'internalRelationshipTargetCollisions' => $relationshipDiagnostics['internalTargetCollisions'],
            'externalRelationshipTargetCollisionCount' => $relationshipDiagnostics['externalTargetCollisionCount'],
            'externalRelationshipTargetCollisionRelationshipCount' => $relationshipDiagnostics['externalTargetCollisionRelationshipCount'],
            'externalRelationshipTargetCollisions' => $relationshipDiagnostics['externalTargetCollisions'],
            'repeatedRelationshipTargetReferenceSuffixCount' => $relationshipDiagnostics['repeatedTargetReferenceSuffixCount'],
            'repeatedRelationshipTargetReferenceSuffixRelationshipCount' => $relationshipDiagnostics['repeatedTargetReferenceSuffixRelationshipCount'],
            'repeatedRelationshipTargetReferenceSuffixes' => $relationshipDiagnostics['repeatedTargetReferenceSuffixes'],
            'repeatedRelationshipTargetReferenceSuffixGroups' => $relationshipDiagnostics['repeatedTargetReferenceSuffixGroups'],
            'recordInternalExternalRelationshipTargetCollisionCount' => $relationshipDiagnostics['recordInternalExternalTargetCollisionCount'],
            'recordInternalExternalRelationshipTargetCollisionRelationshipCount' => $relationshipDiagnostics['recordInternalExternalTargetCollisionRelationshipCount'],
            'recordInternalExternalRelationshipTargetCollisions' => $relationshipDiagnostics['recordInternalExternalTargetCollisions'],
            'recordInternalRelationshipTargetCollisionCount' => $relationshipDiagnostics['recordInternalTargetCollisionCount'],
            'recordInternalRelationshipTargetCollisionRelationshipCount' => $relationshipDiagnostics['recordInternalTargetCollisionRelationshipCount'],
            'recordInternalRelationshipTargetCollisions' => $relationshipDiagnostics['recordInternalTargetCollisions'],
            'recordExternalRelationshipTargetCollisionCount' => $relationshipDiagnostics['recordExternalTargetCollisionCount'],
            'recordExternalRelationshipTargetCollisionRelationshipCount' => $relationshipDiagnostics['recordExternalTargetCollisionRelationshipCount'],
            'recordExternalRelationshipTargetCollisions' => $relationshipDiagnostics['recordExternalTargetCollisions'],
