    /**
     * @param array<string, string> $parts
     * @return array<string, mixed>
     */
    private function zipPackageProvenance(?ZipPackage $sourcePackage, array $parts): array
    {
        if (!$sourcePackage instanceof ZipPackage) {
            $packageManifest = $this->emptyZipPackageManifestProvenance();

            return [
                'present' => false,
                'entryCount' => 0,
                'fileEntryCount' => 0,
                'directoryEntryCount' => 0,
                'loadedPartCount' => 0,
                'unsupportedCompressionMethodCount' => 0,
                'zeroByteEntryCount' => 0,
                'zeroByteFileCount' => 0,
                'emptyDirectoryEntryCount' => 0,
                'hasZeroByteEntries' => false,
                'unknownExpansionRatioEntryCount' => 0,
                'hasUnknownExpansionRatioEntries' => false,
                'compressedByteLength' => 0,
                'uncompressedByteLength' => 0,
                'expansionRatio' => null,
                'largestUncompressedEntry' => null,
                'zeroByteEntries' => [],
                'unknownExpansionRatioEntries' => [],
                'centralDirectoryOrderMatchesLocalHeaderOrder' => null,
                'centralDirectoryOrderNames' => [],
                'localHeaderOrderNames' => [],
                'directoryPackagePaths' => [],
                'loadedPartNames' => [],
                'compressionMethods' => [
                    'entryCount' => 0,
                    'supportedEntryCount' => 0,
                    'unsupportedCompressionMethodCount' => 0,
                    'storedEntryCount' => 0,
                    'deflatedEntryCount' => 0,
                    'storedCompressedBytes' => 0,
                    'storedUncompressedBytes' => 0,
                    'deflatedCompressedBytes' => 0,
                    'deflatedUncompressedBytes' => 0,
                    'unsupportedCompressedBytes' => 0,
                    'unsupportedUncompressedBytes' => 0,
                    'unsupportedEntries' => [],
                    'methodBuckets' => [],
                    'entries' => [],
                ],
                'localHeaderOrder' => [
                    'entryCount' => 0,
                    'centralDirectoryOffset' => null,
                    'centralDirectoryOrderNames' => [],
                    'localHeaderOrderNames' => [],
                    'hasCentralDirectoryOrderMismatch' => false,
                    'mismatchedEntryCount' => 0,
                    'mismatchedEntries' => [],
                    'entries' => [],
                ],
                'generalPurposeFlags' => $this->emptyZipGeneralPurposeFlagProvenance(),
                'dataDescriptors' => $this->emptyZipDataDescriptorProvenance(),
                'modificationTimes' => $this->emptyZipModificationTimeProvenance(),
                'sourceRecords' => $this->emptyZipSourceRecordProvenance(),
                'extraFields' => $this->emptyZipExtraFieldProvenance(),
                'namePolicy' => $this->emptyZipNamePolicyProvenance(),
                'comments' => $this->emptyZipCommentProvenance(),
                'packageManifestDirectoryRootCount' => 0,
                'packageManifestDirectoryRoots' => [],
                'packageManifestDirectoryRootSummaries' => [],
                'packageManifest' => $packageManifest,
                'byteExposurePolicy' => 'docx-zip-entry-metadata-only',
                'canExposeBytes' => false,
                'entries' => [],
                'byPackagePath' => [],
            ] + $this->zipPackageManifestPackageProvenance($packageManifest);
        }

        $localHeaderOrder = $sourcePackage->localHeaderOrderPreflight();
        $compressionMethods = $sourcePackage->compressionMethodPreflight();
        $compressionMethods['methodBuckets'] = $this->zipCompressionBucketsWithExpansionRatios(
            is_array($compressionMethods['methodBuckets'] ?? null) ? $compressionMethods['methodBuckets'] : [],
        );
        $compressionMethods['entries'] = $this->zipCompressionEntriesWithExpansionRatios(
            is_array($compressionMethods['entries'] ?? null) ? $compressionMethods['entries'] : [],
        );
        $sizePreflight = $sourcePackage->sizePreflight();
        $generalPurposeFlags = $this->zipGeneralPurposeFlagProvenance($sourcePackage->generalPurposeFlagPreflight());
        $dataDescriptors = $this->zipDataDescriptorProvenance($sourcePackage->dataDescriptorPreflight());
        $modificationTimes = $this->zipModificationTimeProvenance($sourcePackage->modificationTimePreflight());
        $sourceRecords = $this->zipSourceRecordProvenance($sourcePackage, $parts);
        $extraFields = $sourcePackage->extraFieldPreflight();
        $comments = $sourcePackage->commentPreflight();
        $packageManifest = $sourcePackage->packageManifestPreflight();
        $sizeEntriesByName = [];
        foreach (($sizePreflight['entries'] ?? []) as $sizeEntry) {
            if (is_array($sizeEntry) && is_string($sizeEntry['name'] ?? null)) {
                $sizeEntriesByName[$sizeEntry['name']] = $sizeEntry;
            }
        }
        $manifestEntriesByName = [];
        foreach (($packageManifest['entries'] ?? []) as $manifestEntry) {
            if (is_array($manifestEntry) && is_string($manifestEntry['name'] ?? null)) {
                $manifestEntriesByName[$manifestEntry['name']] = $manifestEntry;
            }
        }
        $extraFieldEntriesByName = [];
        foreach (($extraFields['entries'] ?? []) as $extraFieldEntry) {
            if (is_array($extraFieldEntry) && is_string($extraFieldEntry['name'] ?? null)) {
                $extraFieldEntriesByName[$extraFieldEntry['name']] = $extraFieldEntry;
            }
        }
        $commentEntriesByName = [];
        foreach (($comments['entries'] ?? []) as $commentEntry) {
            if (is_array($commentEntry) && is_string($commentEntry['name'] ?? null)) {
                $commentEntriesByName[$commentEntry['name']] = $commentEntry;
            }
        }
        $generalPurposeFlagsByName = [];
        foreach ($generalPurposeFlags['entries'] as $flagEntry) {
            if (is_array($flagEntry) && is_string($flagEntry['name'] ?? null)) {
                $generalPurposeFlagsByName[$flagEntry['name']] = $flagEntry;
            }
        }
        $dataDescriptorByName = [];
        foreach ($dataDescriptors['entries'] as $descriptorEntry) {
            if (is_array($descriptorEntry) && is_string($descriptorEntry['name'] ?? null)) {
                $dataDescriptorByName[$descriptorEntry['name']] = $descriptorEntry;
            }
        }
        $modificationTimeByName = [];
        foreach ($modificationTimes['entries'] as $modificationTimeEntry) {
            if (is_array($modificationTimeEntry) && is_string($modificationTimeEntry['name'] ?? null)) {
                $modificationTimeByName[$modificationTimeEntry['name']] = $modificationTimeEntry;
            }
        }
        $sourceRecordEntriesByName = [];
        foreach (($sourceRecords['byPackagePath'] ?? []) as $sourceRecordName => $sourceRecordEntry) {
            if (is_string($sourceRecordName) && is_array($sourceRecordEntry)) {
                $sourceRecordEntriesByName[$sourceRecordName] = $sourceRecordEntry;
            }
        }
        $localOrderByName = [];
        foreach ($localHeaderOrder['entries'] as $entry) {
            $localOrderByName[(string) $entry['name']] = $entry;
        }

        $entries = [];
        $byPackagePath = [];
        $directoryPackagePaths = [];
        $loadedPartNames = [];
        $fileEntryCount = 0;
        $directoryEntryCount = 0;
        $loadedPartCount = 0;
        foreach ($sourcePackage->entries() as $centralDirectoryIndex => $entry) {
            $isDirectory = $entry->isDirectory();
            $loadedPart = !$isDirectory && array_key_exists($entry->name, $parts);
            if ($isDirectory) {
                ++$directoryEntryCount;
                $directoryPackagePaths[] = $entry->name;
            } else {
                ++$fileEntryCount;
            }
            if ($loadedPart) {
                ++$loadedPartCount;
                $loadedPartNames[] = $entry->name;
            }

            $localOrder = $localOrderByName[$entry->name] ?? null;
            $extraFieldEntry = $extraFieldEntriesByName[$entry->name] ?? null;
            $commentEntry = $commentEntriesByName[$entry->name] ?? null;
            $manifestEntry = $manifestEntriesByName[$entry->name] ?? null;
            $sizeEntry = $sizeEntriesByName[$entry->name] ?? null;
            $expansionRatio = is_array($sizeEntry) && array_key_exists('expansionRatio', $sizeEntry)
                ? $sizeEntry['expansionRatio']
                : self::zipExpansionRatio($entry->uncompressedSize, $entry->compressedSize);
            $summary = [
                'packagePath' => $entry->name,
                'partName' => $isDirectory ? null : $entry->name,
                'directoryRoot' => is_array($manifestEntry) ? ($manifestEntry['directoryRoot'] ?? null) : null,
                'caseFoldKey' => is_array($manifestEntry) && is_string($manifestEntry['caseFoldKey'] ?? null)
                    ? $manifestEntry['caseFoldKey']
                    : null,
                'caseInsensitiveEquivalentEntryNames' => is_array($manifestEntry) && is_array($manifestEntry['caseInsensitiveEquivalentEntryNames'] ?? null)
                    ? $manifestEntry['caseInsensitiveEquivalentEntryNames']
                    : [],
                'hasCaseInsensitiveNameCollision' => is_array($manifestEntry)
                    ? (($manifestEntry['hasCaseInsensitiveNameCollision'] ?? false) === true)
                    : false,
                'caseInsensitiveNameCollisionIssues' => is_array($manifestEntry) && is_array($manifestEntry['caseInsensitiveNameCollisionIssues'] ?? null)
                    ? $manifestEntry['caseInsensitiveNameCollisionIssues']
                    : [],
                'packagePartExtension' => is_array($manifestEntry) ? ($manifestEntry['packagePartExtension'] ?? null) : null,
                'packagePartExtensionKey' => is_array($manifestEntry) && is_string($manifestEntry['packagePartExtensionKey'] ?? null)
                    ? $manifestEntry['packagePartExtensionKey']
                    : ($isDirectory ? '(directory)' : null),
                'extensionlessPackagePart' => is_array($manifestEntry) ? (($manifestEntry['extensionlessPackagePart'] ?? false) === true) : false,
                'roles' => $this->zipPackageEntryRoles($entry, $loadedPart),
                'centralDirectoryIndex' => $centralDirectoryIndex,
                'localHeaderOrder' => is_array($localOrder) ? $localOrder['localHeaderOrder'] : null,
                'localHeaderOffset' => $entry->localHeaderOffset,
                'localHeaderLength' => is_array($manifestEntry) ? ($manifestEntry['localHeaderLength'] ?? null) : null,
                'localHeaderSha256' => is_array($manifestEntry) ? ($manifestEntry['localHeaderSha256'] ?? null) : null,
                'localHeaderFixedHeaderBytes' => is_array($manifestEntry) ? ($manifestEntry['localHeaderFixedHeaderBytes'] ?? null) : null,
                'localHeaderVariableFieldOffset' => is_array($manifestEntry) ? ($manifestEntry['localHeaderVariableFieldOffset'] ?? null) : null,
                'localHeaderVariableFieldBytes' => is_array($manifestEntry) ? ($manifestEntry['localHeaderVariableFieldBytes'] ?? null) : null,
                'localHeaderVariableFieldSha256' => is_array($manifestEntry) ? ($manifestEntry['localHeaderVariableFieldSha256'] ?? null) : null,
                'localHeaderRawNameOffset' => is_array($manifestEntry) ? ($manifestEntry['localHeaderRawNameOffset'] ?? null) : null,
                'localHeaderRawNameBytes' => is_array($manifestEntry) ? ($manifestEntry['localHeaderRawNameBytes'] ?? null) : null,
                'localHeaderRawNameSha256' => is_array($manifestEntry) ? ($manifestEntry['localHeaderRawNameSha256'] ?? null) : null,
                'localHeaderExtraFieldOffset' => is_array($manifestEntry) ? ($manifestEntry['localHeaderExtraFieldOffset'] ?? null) : null,
                'localHeaderExtraFieldBytes' => is_array($manifestEntry) ? ($manifestEntry['localHeaderExtraFieldBytes'] ?? null) : null,
                'localHeaderExtraFieldSha256' => is_array($manifestEntry) ? ($manifestEntry['localHeaderExtraFieldSha256'] ?? null) : null,
                'localHeaderReviewFieldBytes' => is_array($manifestEntry) ? ($manifestEntry['localHeaderReviewFieldBytes'] ?? null) : null,
                'localRecordOffset' => is_array($manifestEntry) ? ($manifestEntry['localRecordOffset'] ?? null) : null,
                'localRecordBytes' => is_array($manifestEntry) ? ($manifestEntry['localRecordBytes'] ?? null) : null,
                'localRecordEnd' => is_array($manifestEntry) ? ($manifestEntry['localRecordEnd'] ?? null) : null,
                'localRecordSha256' => is_array($manifestEntry) ? ($manifestEntry['localRecordSha256'] ?? null) : null,
                'compressedDataOffset' => is_array($manifestEntry) ? ($manifestEntry['compressedDataOffset'] ?? null) : null,
                'compressedDataBytes' => is_array($manifestEntry) ? ($manifestEntry['compressedSize'] ?? null) : null,
                'compressedDataEnd' => is_array($manifestEntry) ? ($manifestEntry['compressedDataEnd'] ?? null) : null,
                'compressedDataSha256' => is_array($manifestEntry) ? ($manifestEntry['compressedDataSha256'] ?? null) : null,
                'usesDataDescriptor' => is_array($manifestEntry) ? (($manifestEntry['usesDataDescriptor'] ?? false) === true) : false,
                'dataDescriptorOffset' => is_array($manifestEntry) ? ($manifestEntry['dataDescriptorOffset'] ?? null) : null,
                'dataDescriptorBytes' => is_array($manifestEntry) ? ($manifestEntry['dataDescriptorBytes'] ?? null) : null,
                'dataDescriptorEnd' => is_array($manifestEntry) ? ($manifestEntry['dataDescriptorEnd'] ?? null) : null,
                'dataDescriptorSha256' => is_array($manifestEntry) ? ($manifestEntry['dataDescriptorSha256'] ?? null) : null,
                'centralDirectoryRecordOffset' => is_array($manifestEntry) ? ($manifestEntry['centralDirectoryRecordOffset'] ?? null) : null,
                'centralDirectoryRecordBytes' => is_array($manifestEntry) ? ($manifestEntry['centralDirectoryRecordBytes'] ?? null) : null,
                'centralDirectoryRecordEnd' => is_array($manifestEntry) ? ($manifestEntry['centralDirectoryRecordEnd'] ?? null) : null,
                'centralDirectoryRecordSha256' => is_array($manifestEntry) ? ($manifestEntry['centralDirectoryRecordSha256'] ?? null) : null,
                'centralDirectoryFixedHeaderBytes' => is_array($manifestEntry) ? ($manifestEntry['centralDirectoryFixedHeaderBytes'] ?? null) : null,
                'centralDirectoryVariableFieldOffset' => is_array($manifestEntry) ? ($manifestEntry['centralDirectoryVariableFieldOffset'] ?? null) : null,
                'centralDirectoryVariableFieldBytes' => is_array($manifestEntry) ? ($manifestEntry['centralDirectoryVariableFieldBytes'] ?? null) : null,
                'centralDirectoryVariableFieldSha256' => is_array($manifestEntry) ? ($manifestEntry['centralDirectoryVariableFieldSha256'] ?? null) : null,
                'centralDirectoryRawNameOffset' => is_array($manifestEntry) ? ($manifestEntry['centralDirectoryRawNameOffset'] ?? null) : null,
                'centralDirectoryRawNameBytes' => is_array($manifestEntry) ? ($manifestEntry['centralDirectoryRawNameBytes'] ?? null) : null,
                'centralDirectoryRawNameSha256' => is_array($manifestEntry) ? ($manifestEntry['centralDirectoryRawNameSha256'] ?? null) : null,
                'centralDirectoryExtraFieldOffset' => is_array($manifestEntry) ? ($manifestEntry['centralDirectoryExtraFieldOffset'] ?? null) : null,
                'centralDirectoryExtraFieldBytes' => is_array($manifestEntry) ? ($manifestEntry['centralDirectoryExtraFieldBytes'] ?? null) : null,
                'centralDirectoryExtraFieldSha256' => is_array($manifestEntry) ? ($manifestEntry['centralDirectoryExtraFieldSha256'] ?? null) : null,
                'centralDirectoryRawCommentOffset' => is_array($manifestEntry) ? ($manifestEntry['centralDirectoryRawCommentOffset'] ?? null) : null,
                'centralDirectoryRawCommentBytes' => is_array($manifestEntry) ? ($manifestEntry['centralDirectoryRawCommentBytes'] ?? null) : null,
                'centralDirectoryRawCommentSha256' => is_array($manifestEntry) ? ($manifestEntry['centralDirectoryRawCommentSha256'] ?? null) : null,
                'centralDirectoryReviewFieldBytes' => is_array($manifestEntry) ? ($manifestEntry['centralDirectoryReviewFieldBytes'] ?? null) : null,
                'matchesCentralDirectoryOrder' => is_array($localOrder)
                    ? $localOrder['matchesCentralDirectoryOrder']
                    : null,
                'compressionMethod' => $entry->compressionMethod,
                'compressionMethodName' => self::zipCompressionMethodName($entry->compressionMethod),
                'compressionSupported' => $entry->compressionMethod === 0 || $entry->compressionMethod === 8,
                'byteLength' => $entry->uncompressedSize,
                'compressedByteLength' => $entry->compressedSize,
                'expansionRatio' => $expansionRatio,
                'hasUnknownExpansionRatio' => $expansionRatio === null && $entry->uncompressedSize > 0,
                'crc32' => $entry->crc32Hex(),
                'zipEntryComment' => $entry->comment,
                'zipEntryCommentLength' => strlen($entry->rawComment),
                'zipEntryCommentEncoding' => $entry->commentEncoding,
                'zipEntryHasComment' => $entry->comment !== '',
                'zipEntryCommentIssues' => is_array($commentEntry) ? ($commentEntry['issues'] ?? []) : [],
                'centralExtraFieldIds' => is_array($extraFieldEntry) ? ($extraFieldEntry['centralExtraFieldIds'] ?? []) : [],
                'localExtraFieldIds' => is_array($extraFieldEntry) ? ($extraFieldEntry['localExtraFieldIds'] ?? []) : [],
                'duplicateCentralExtraFieldIds' => is_array($extraFieldEntry) ? ($extraFieldEntry['duplicateCentralExtraFieldIds'] ?? []) : [],
                'duplicateLocalExtraFieldIds' => is_array($extraFieldEntry) ? ($extraFieldEntry['duplicateLocalExtraFieldIds'] ?? []) : [],
                'centralOnlyExtraFieldIds' => is_array($extraFieldEntry) ? ($extraFieldEntry['centralOnlyExtraFieldIds'] ?? []) : [],
                'localOnlyExtraFieldIds' => is_array($extraFieldEntry) ? ($extraFieldEntry['localOnlyExtraFieldIds'] ?? []) : [],
                'mismatchedExtraFieldValueIds' => is_array($extraFieldEntry) ? ($extraFieldEntry['mismatchedExtraFieldValueIds'] ?? []) : [],
                'hasCentralExtraFields' => is_array($extraFieldEntry) ? (($extraFieldEntry['centralExtraFieldIds'] ?? []) !== []) : false,
                'hasLocalExtraFields' => is_array($extraFieldEntry) ? (($extraFieldEntry['localExtraFieldIds'] ?? []) !== []) : false,
                'hasZipExtraFieldProvenance' => is_array($extraFieldEntry)
                    ? (($extraFieldEntry['centralExtraFieldIds'] ?? []) !== [] || ($extraFieldEntry['localExtraFieldIds'] ?? []) !== [])
                    : false,
                'hasDuplicateExtraFieldIds' => is_array($extraFieldEntry) ? (bool) ($extraFieldEntry['hasDuplicateExtraFieldIds'] ?? false) : false,
                'hasMismatchedExtraFieldIds' => is_array($extraFieldEntry) ? (bool) ($extraFieldEntry['hasMismatchedExtraFieldIds'] ?? false) : false,
                'hasMismatchedExtraFieldValues' => is_array($extraFieldEntry) ? (bool) ($extraFieldEntry['hasMismatchedExtraFieldValues'] ?? false) : false,
                'isDirectory' => $isDirectory,
                'loadedPart' => $loadedPart,
                'canExposeBytes' => false,
                'byteExposurePolicy' => 'docx-zip-entry-metadata-only',
            ]
                + $this->zipGeneralPurposeFlagEntryProvenance($generalPurposeFlagsByName[$entry->name] ?? null)
                + $this->zipDataDescriptorEntryProvenance($dataDescriptorByName[$entry->name] ?? null)
                + $this->zipModificationTimeEntryProvenance($modificationTimeByName[$entry->name] ?? null)
                + $this->zipSourceRecordEntryProvenance($sourceRecordEntriesByName[$entry->name] ?? null);
            $entries[] = $summary;
            $byPackagePath[$entry->name] = $summary;
        }

        return [
            'present' => true,
            'entryCount' => count($entries),
            'fileEntryCount' => $fileEntryCount,
            'directoryEntryCount' => $directoryEntryCount,
            'loadedPartCount' => $loadedPartCount,
            'unsupportedCompressionMethodCount' => (int) $compressionMethods['unsupportedCompressionMethodCount'],
            'zeroByteEntryCount' => (int) ($sizePreflight['zeroByteEntryCount'] ?? 0),
            'zeroByteFileCount' => (int) ($sizePreflight['zeroByteFileCount'] ?? 0),
            'emptyDirectoryEntryCount' => (int) ($sizePreflight['emptyDirectoryEntryCount'] ?? 0),
            'hasZeroByteEntries' => ($sizePreflight['hasZeroByteEntries'] ?? false) === true,
            'unknownExpansionRatioEntryCount' => (int) ($sizePreflight['unknownExpansionRatioEntryCount'] ?? 0),
            'hasUnknownExpansionRatioEntries' => ($sizePreflight['hasUnknownExpansionRatioEntries'] ?? false) === true,
            'compressedByteLength' => (int) ($sizePreflight['compressedBytes'] ?? 0),
            'uncompressedByteLength' => (int) ($sizePreflight['uncompressedBytes'] ?? 0),
            'expansionRatio' => $sizePreflight['expansionRatio'] ?? null,
            'largestUncompressedEntry' => is_array($sizePreflight['largestEntry'] ?? null) ? $sizePreflight['largestEntry'] : null,
            'zeroByteEntries' => is_array($sizePreflight['zeroByteEntries'] ?? null) ? $sizePreflight['zeroByteEntries'] : [],
            'unknownExpansionRatioEntries' => is_array($sizePreflight['unknownExpansionRatioEntries'] ?? null)
                ? $sizePreflight['unknownExpansionRatioEntries']
                : [],
            'centralDirectoryOrderMatchesLocalHeaderOrder' => !$localHeaderOrder['hasCentralDirectoryOrderMismatch'],
            'centralDirectoryOrderNames' => $localHeaderOrder['centralDirectoryOrderNames'],
            'localHeaderOrderNames' => $localHeaderOrder['localHeaderOrderNames'],
            'directoryPackagePaths' => $directoryPackagePaths,
            'loadedPartNames' => $loadedPartNames,
            'compressionMethods' => $compressionMethods,
            'generalPurposeFlags' => $generalPurposeFlags,
            'dataDescriptors' => $dataDescriptors,
            'modificationTimes' => $modificationTimes,
            'sourceRecords' => $sourceRecords,
            'extraFields' => $extraFields,
            'namePolicy' => $this->zipNamePolicyProvenance($sourcePackage),
            'comments' => $comments,
            'packageManifestDirectoryRootCount' => (int) ($packageManifest['directoryRootCount'] ?? 0),
            'packageManifestDirectoryRoots' => is_array($packageManifest['directoryRoots'] ?? null)
                ? $packageManifest['directoryRoots']
                : [],
            'packageManifestDirectoryRootSummaries' => is_array($packageManifest['directoryRootSummaries'] ?? null)
                ? $packageManifest['directoryRootSummaries']
                : [],
            'packageManifest' => $packageManifest,
            'localHeaderOrder' => $localHeaderOrder,
            'byteExposurePolicy' => 'docx-zip-entry-metadata-only',
            'canExposeBytes' => false,
            'entries' => $entries,
            'byPackagePath' => $byPackagePath,
        ] + $this->zipPackageManifestPackageProvenance($packageManifest);
    }

    /**
     * @return array<string, mixed>
     */
    private function emptyZipGeneralPurposeFlagProvenance(): array
    {
        return [
            'present' => false,
            'entryCount' => 0,
            'supportedEntryCount' => 0,
            'unsupportedFlagEntryCount' => 0,
            'utf8NameEntryCount' => 0,
            'dataDescriptorEntryCount' => 0,
            'deflateOptionEntryCount' => 0,
            'strictReviewEntryCount' => 0,
            'issueCount' => 0,
            'issueCodes' => [],
            'unsupportedEntries' => [],
            'strictReviewEntries' => [],
            'entries' => [],
            'byteExposurePolicy' => 'docx-zip-entry-metadata-only',
            'canExposeBytes' => false,
        ];
    }

    /**
     * @param array<string, mixed> $flags
     * @return array<string, mixed>
     */
    private function zipGeneralPurposeFlagProvenance(array $flags): array
    {
        $issueCodes = [];
        foreach (($flags['entries'] ?? []) as $entry) {
            if (!is_array($entry)) {
                continue;
            }

            foreach (is_array($entry['issues'] ?? null) ? $entry['issues'] : [] as $issue) {
                if (is_string($issue) && $issue !== '' && !in_array($issue, $issueCodes, true)) {
                    $issueCodes[] = $issue;
                }
            }
        }
        sort($issueCodes, SORT_STRING);

        return [
            'present' => true,
            'entryCount' => (int) ($flags['entryCount'] ?? 0),
            'supportedEntryCount' => (int) ($flags['supportedEntryCount'] ?? 0),
            'unsupportedFlagEntryCount' => (int) ($flags['unsupportedFlagEntryCount'] ?? 0),
            'utf8NameEntryCount' => (int) ($flags['utf8NameEntryCount'] ?? 0),
            'dataDescriptorEntryCount' => (int) ($flags['dataDescriptorEntryCount'] ?? 0),
            'deflateOptionEntryCount' => (int) ($flags['deflateOptionEntryCount'] ?? 0),
            'strictReviewEntryCount' => (int) ($flags['strictReviewEntryCount'] ?? 0),
            'issueCount' => count($issueCodes),
            'issueCodes' => $issueCodes,
            'unsupportedEntries' => is_array($flags['unsupportedEntries'] ?? null) ? $flags['unsupportedEntries'] : [],
            'strictReviewEntries' => is_array($flags['strictReviewEntries'] ?? null) ? $flags['strictReviewEntries'] : [],
            'entries' => is_array($flags['entries'] ?? null) ? $flags['entries'] : [],
            'byteExposurePolicy' => 'docx-zip-entry-metadata-only',
            'canExposeBytes' => false,
        ];
    }

    /**
     * @param array<string, mixed>|null $entry
     * @return array<string, mixed>
     */
    private function zipGeneralPurposeFlagEntryProvenance(?array $entry): array
    {
        $issues = is_array($entry['issues'] ?? null) ? array_values(array_filter(
            $entry['issues'],
            static fn (mixed $issue): bool => is_string($issue)
        )) : [];

        return [
            'generalPurposeFlags' => $entry['generalPurposeFlags'] ?? null,
            'generalPurposeFlagNames' => is_array($entry['flagNames'] ?? null) ? $entry['flagNames'] : [],
            'generalPurposeUnsupportedFlagBits' => $entry['unsupportedFlagBits'] ?? 0,
            'generalPurposeFlagsSupportedByReader' => ($entry['isSupportedByReader'] ?? false) === true,
            'zipUsesUtf8Names' => ($entry['usesUtf8Names'] ?? false) === true,
            'zipUsesDataDescriptorFlag' => ($entry['usesDataDescriptor'] ?? false) === true,
            'zipDeflateOptionFlags' => $entry['deflateOptionFlags'] ?? 0,
            'zipDeflateOptionName' => $entry['deflateOptionName'] ?? null,
            'zipRequiresGeneralPurposeFlagReview' => ($entry['requiresStrictReview'] ?? false) === true,
            'generalPurposeFlagIssueCount' => count($issues),
            'generalPurposeFlagIssues' => $issues,
        ];
    }

