    /**
     * @param array<string, string> $parts
     * @return array<string, mixed>
     */
    private function zipSourceRecordProvenance(ZipPackage $sourcePackage, array $parts): array
    {
        $requests = [];
        foreach (array_keys($parts) as $partName) {
            if (!is_string($partName) || $partName === '') {
                continue;
            }

            $requests[] = [
                'name' => $partName,
                'required' => false,
                'kind' => 'file',
                'role' => 'loaded-package-part',
            ];
        }

        $preflight = $requests === []
            ? []
            : $sourcePackage->entryHandoffPreflight($requests);
        $sourceEntries = is_array($preflight['selectedSourceByteSpanEntries'] ?? null)
            ? $preflight['selectedSourceByteSpanEntries']
            : [];
        $platformAttributeEntriesByName = [];
        foreach (($preflight['selectedPlatformAttributeProvenanceEntries'] ?? []) as $platformAttributeEntry) {
            if (is_array($platformAttributeEntry) && is_string($platformAttributeEntry['name'] ?? null)) {
                $platformAttributeEntriesByName[$platformAttributeEntry['name']] = $platformAttributeEntry;
            }
        }
        $localHeaderFixedFieldEntriesByName = [];
        foreach (($preflight['selectedLocalHeaderFixedFieldEntries'] ?? []) as $localHeaderFixedFieldEntry) {
            if (is_array($localHeaderFixedFieldEntry) && is_string($localHeaderFixedFieldEntry['name'] ?? null)) {
                $localHeaderFixedFieldEntriesByName[$localHeaderFixedFieldEntry['name']] = $localHeaderFixedFieldEntry;
            }
        }
        $centralDirectoryFixedFieldEntriesByName = [];
        foreach (($preflight['selectedCentralDirectoryFixedFieldEntries'] ?? []) as $centralDirectoryFixedFieldEntry) {
            if (is_array($centralDirectoryFixedFieldEntry) && is_string($centralDirectoryFixedFieldEntry['name'] ?? null)) {
                $centralDirectoryFixedFieldEntriesByName[$centralDirectoryFixedFieldEntry['name']] = $centralDirectoryFixedFieldEntry;
            }
        }
        $entries = [];
        $byPackagePath = [];
        foreach ($sourceEntries as $entry) {
            if (!is_array($entry) || !is_string($entry['name'] ?? null)) {
                continue;
            }

            $sourceEntry = [
                'packagePath' => $entry['name'],
                'partName' => $entry['name'],
                'byteExposurePolicy' => 'docx-zip-entry-metadata-only',
                'canExposeBytes' => false,
            ] + $entry
                + ($platformAttributeEntriesByName[$entry['name']] ?? [])
                + ($localHeaderFixedFieldEntriesByName[$entry['name']] ?? [])
                + ($centralDirectoryFixedFieldEntriesByName[$entry['name']] ?? []);
            $entries[] = $sourceEntry;
            $byPackagePath[$entry['name']] = $sourceEntry;
        }
        $creatorHostSystems = $this->zipSourceRecordCreatorHostSystemProvenance($entries, $sourcePackage);

        $issues = array_values(array_filter(
            is_array($preflight['selectedSourceByteSpanIssues'] ?? null)
                ? $preflight['selectedSourceByteSpanIssues']
                : [],
            static fn (mixed $issue): bool => is_string($issue)
        ));

        return [
            'present' => true,
            'requestedEntryCount' => count($requests),
            'entryCount' => count($entries),
            'issueCount' => count($issues),
            'issues' => $issues,
            'localRecordBytes' => (int) ($preflight['selectedSourceLocalRecordBytes'] ?? 0),
            'localHeaderBytes' => (int) ($preflight['selectedSourceLocalHeaderBytes'] ?? 0),
            'localFixedHeaderBytes' => (int) ($preflight['selectedSourceLocalFixedHeaderBytes'] ?? 0),
            'localHeaderVariableFieldBytes' => (int) ($preflight['selectedSourceLocalHeaderVariableFieldBytes'] ?? 0),
            'localRawNameBytes' => (int) ($preflight['selectedSourceLocalRawNameBytes'] ?? 0),
            'localExtraFieldBytes' => (int) ($preflight['selectedSourceLocalExtraFieldBytes'] ?? 0),
            'localReviewFieldBytes' => (int) ($preflight['selectedSourceLocalReviewFieldBytes'] ?? 0),
            'compressedDataBytes' => (int) ($preflight['selectedSourceCompressedDataBytes'] ?? 0),
            'dataDescriptorBytes' => (int) ($preflight['selectedSourceDataDescriptorBytes'] ?? 0),
            'centralDirectoryRecordBytes' => (int) ($preflight['selectedSourceCentralDirectoryRecordBytes'] ?? 0),
            'centralDirectoryFixedHeaderBytes' => (int) ($preflight['selectedSourceCentralDirectoryFixedHeaderBytes'] ?? 0),
            'centralDirectoryVariableFieldBytes' => (int) ($preflight['selectedSourceCentralDirectoryVariableFieldBytes'] ?? 0),
            'centralDirectoryRawNameBytes' => (int) ($preflight['selectedSourceCentralDirectoryRawNameBytes'] ?? 0),
            'centralDirectoryExtraFieldBytes' => (int) ($preflight['selectedSourceCentralDirectoryExtraFieldBytes'] ?? 0),
            'centralDirectoryRawCommentBytes' => (int) ($preflight['selectedSourceCentralDirectoryRawCommentBytes'] ?? 0),
            'centralDirectoryReviewFieldBytes' => (int) ($preflight['selectedSourceCentralDirectoryReviewFieldBytes'] ?? 0),
            'platformAttributeProvenanceEntryCount' => (int) ($preflight['selectedPlatformAttributeProvenanceEntryCount'] ?? 0),
            'externalAttributeEntryCount' => (int) ($preflight['selectedExternalAttributeEntryCount'] ?? 0),
            'internalAttributeEntryCount' => (int) ($preflight['selectedInternalAttributeEntryCount'] ?? 0),
            'dosAttributeEntryCount' => (int) ($preflight['selectedDosAttributeEntryCount'] ?? 0),
            'unixModeEntryCount' => (int) ($preflight['selectedUnixModeEntryCount'] ?? 0),
            'executableFileEntryCount' => (int) ($preflight['selectedExecutableFileEntryCount'] ?? 0),
            'writablePermissionEntryCount' => (int) ($preflight['selectedWritablePermissionEntryCount'] ?? 0),
            'platformAttributeIssueEntryCount' => (int) ($preflight['selectedPlatformAttributeIssueEntryCount'] ?? 0),
            'platformAttributeIssues' => is_array($preflight['selectedPlatformAttributeIssues'] ?? null)
                ? $preflight['selectedPlatformAttributeIssues']
                : [],
            'platformAttributeProvenanceEntries' => is_array($preflight['selectedPlatformAttributeProvenanceEntries'] ?? null)
                ? $preflight['selectedPlatformAttributeProvenanceEntries']
                : [],
            'platformAttributeIssueEntries' => is_array($preflight['selectedPlatformAttributeIssueEntries'] ?? null)
                ? $preflight['selectedPlatformAttributeIssueEntries']
                : [],
            'creatorHostSystemEntryCount' => $creatorHostSystems['entryCount'],
            'knownCreatorHostSystemEntryCount' => $creatorHostSystems['knownHostSystemEntryCount'],
            'unknownCreatorHostSystemEntryCount' => $creatorHostSystems['unknownHostSystemEntryCount'],
            'creatorVersionMeetsNeededEntryCount' => $creatorHostSystems['creatorVersionMeetsNeededEntryCount'],
            'creatorVersionBelowNeededEntryCount' => $creatorHostSystems['creatorVersionBelowNeededEntryCount'],
            'creatorVersionEqualNeededEntryCount' => $creatorHostSystems['creatorVersionEqualNeededEntryCount'],
            'creatorVersionAboveNeededEntryCount' => $creatorHostSystems['creatorVersionAboveNeededEntryCount'],
            'creatorVersionComparisonCounts' => $creatorHostSystems['creatorVersionComparisonCounts'],
            'creatorHostSystems' => $creatorHostSystems['hostSystems'],
            'unknownCreatorHostSystemEntries' => $creatorHostSystems['unknownEntries'],
            'creatorVersionBelowNeededEntries' => $creatorHostSystems['creatorVersionBelowNeededEntries'],
            'creatorVersionEntries' => $creatorHostSystems['entries'],
            'localHeaderFixedFieldEntryCount' => (int) ($preflight['selectedLocalHeaderFixedFieldEntryCount'] ?? 0),
            'localHeaderFixedFieldIssueEntryCount' => (int) ($preflight['selectedLocalHeaderFixedFieldIssueEntryCount'] ?? 0),
            'localHeaderFixedFieldEntries' => is_array($preflight['selectedLocalHeaderFixedFieldEntries'] ?? null)
                ? $preflight['selectedLocalHeaderFixedFieldEntries']
                : [],
            'localHeaderFixedFieldIssueEntries' => is_array($preflight['selectedLocalHeaderFixedFieldIssueEntries'] ?? null)
                ? $preflight['selectedLocalHeaderFixedFieldIssueEntries']
                : [],
            'centralDirectoryFixedFieldEntryCount' => (int) ($preflight['selectedCentralDirectoryFixedFieldEntryCount'] ?? 0),
            'centralDirectoryFixedFieldIssueEntryCount' => (int) ($preflight['selectedCentralDirectoryFixedFieldIssueEntryCount'] ?? 0),
            'centralDirectoryFixedFieldEntries' => is_array($preflight['selectedCentralDirectoryFixedFieldEntries'] ?? null)
                ? $preflight['selectedCentralDirectoryFixedFieldEntries']
                : [],
            'centralDirectoryFixedFieldIssueEntries' => is_array($preflight['selectedCentralDirectoryFixedFieldIssueEntries'] ?? null)
                ? $preflight['selectedCentralDirectoryFixedFieldIssueEntries']
                : [],
            'totalRecordBytes' => (int) ($preflight['selectedSourceTotalRecordBytes'] ?? 0),
            'byteExposurePolicy' => 'docx-zip-entry-metadata-only',
            'canExposeBytes' => false,
            'entries' => $entries,
            'byPackagePath' => $byPackagePath,
        ];
    }

    /**
     * @param list<array<string, mixed>> $entries
     * @return array<string, mixed>
     */
    private function zipSourceRecordCreatorHostSystemProvenance(array $entries, ZipPackage $sourcePackage): array
    {
        $creatorEntries = [];
        $unknownEntries = [];
        $creatorVersionBelowNeededEntries = [];
        $hostSystems = [];
        $creatorVersionComparisonCounts = [
            'below-needed' => 0,
            'equals-needed' => 0,
            'above-needed' => 0,
        ];
        $packageCreatorEntriesByName = [];
        $packageCreatorHosts = $sourcePackage->creatorHostSystemPreflight();
        foreach (($packageCreatorHosts['entries'] ?? []) as $creatorEntry) {
            if (is_array($creatorEntry) && is_string($creatorEntry['name'] ?? null)) {
                $packageCreatorEntriesByName[$creatorEntry['name']] = $creatorEntry;
            }
        }

        foreach ($entries as $entry) {
            $entryName = is_string($entry['name'] ?? null) ? $entry['name'] : '';
            $creatorEntry = $packageCreatorEntriesByName[$entryName] ?? null;
            if (is_array($creatorEntry)) {
                $entry = $creatorEntry + $entry;
            }

            if (!is_int($entry['madeByHostSystem'] ?? null)) {
                continue;
            }

            $hostSystem = (int) $entry['madeByHostSystem'];
            $hostSystemName = is_string($entry['madeByHostSystemName'] ?? null)
                ? $entry['madeByHostSystemName']
                : 'unknown';
            $madeByVersion = is_int($entry['madeByVersion'] ?? null) ? $entry['madeByVersion'] : null;
            $versionNeededToExtract = is_int($entry['versionNeededToExtract'] ?? null)
                ? $entry['versionNeededToExtract']
                : null;
            $creatorVersionDelta = $madeByVersion !== null && $versionNeededToExtract !== null
                ? $madeByVersion - $versionNeededToExtract
                : 0;
            $creatorVersionComparison = $creatorVersionDelta < 0
                ? 'below-needed'
                : ($creatorVersionDelta === 0 ? 'equals-needed' : 'above-needed');
            $creatorVersionComparisonCounts[$creatorVersionComparison]++;
            $creatorVersionMeetsNeeded = $creatorVersionDelta >= 0;
            $isKnown = $hostSystemName !== 'unknown';
            $issues = [];
            if (!$isKnown) {
                $issues[] = 'unknown-creator-host-system';
            }
            if (!$creatorVersionMeetsNeeded) {
                $issues[] = 'creator-version-below-version-needed';
            }

            $summary = [
                'name' => $entryName,
                'madeByHostSystem' => $hostSystem,
                'madeByHostSystemName' => $hostSystemName,
                'madeByVersion' => $madeByVersion,
                'versionNeededToExtract' => $versionNeededToExtract,
                'creatorVersionMeetsNeeded' => $creatorVersionMeetsNeeded,
                'creatorVersionComparison' => $creatorVersionComparison,
                'creatorVersionDelta' => $creatorVersionDelta,
                'versionMadeBy' => is_int($entry['versionMadeBy'] ?? null) ? $entry['versionMadeBy'] : null,
                'isKnown' => $isKnown,
                'issues' => $issues,
            ];
            $creatorEntries[] = $summary;
            if (!$isKnown) {
                $unknownEntries[] = $summary;
            }
            if (!$creatorVersionMeetsNeeded) {
                $creatorVersionBelowNeededEntries[] = $summary;
            }

            if (!isset($hostSystems[$hostSystem])) {
                $hostSystems[$hostSystem] = [
                    'id' => $hostSystem,
                    'name' => $hostSystemName,
                    'isKnown' => $isKnown,
                    'entryCount' => 0,
                ];
            }
            ++$hostSystems[$hostSystem]['entryCount'];
        }

        ksort($hostSystems, SORT_NUMERIC);

        return [
            'entryCount' => count($creatorEntries),
            'knownHostSystemEntryCount' => count($creatorEntries) - count($unknownEntries),
            'unknownHostSystemEntryCount' => count($unknownEntries),
            'creatorVersionMeetsNeededEntryCount' => $creatorVersionComparisonCounts['equals-needed']
                + $creatorVersionComparisonCounts['above-needed'],
            'creatorVersionBelowNeededEntryCount' => count($creatorVersionBelowNeededEntries),
            'creatorVersionEqualNeededEntryCount' => $creatorVersionComparisonCounts['equals-needed'],
            'creatorVersionAboveNeededEntryCount' => $creatorVersionComparisonCounts['above-needed'],
            'creatorVersionComparisonCounts' => $creatorVersionComparisonCounts,
            'hostSystems' => array_values($hostSystems),
            'unknownEntries' => $unknownEntries,
            'creatorVersionBelowNeededEntries' => $creatorVersionBelowNeededEntries,
            'entries' => $creatorEntries,
        ];
    }

