            $partInventory[$partName]['zipEntryPresent'] = true;
            $partInventory[$partName]['zipDirectoryRoot'] = $entry['directoryRoot'] ?? null;
            $partInventory[$partName]['zipCaseFoldKey'] = $entry['caseFoldKey'] ?? null;
            $partInventory[$partName]['zipCaseInsensitiveEquivalentEntryNames'] = $entry['caseInsensitiveEquivalentEntryNames'] ?? [];
            $partInventory[$partName]['zipHasCaseInsensitiveNameCollision'] = $entry['hasCaseInsensitiveNameCollision'] ?? false;
            $partInventory[$partName]['zipCaseInsensitiveNameCollisionIssues'] = $entry['caseInsensitiveNameCollisionIssues'] ?? [];
            $partInventory[$partName]['centralDirectoryIndex'] = $entry['centralDirectoryIndex'] ?? null;
            $partInventory[$partName]['localHeaderOrder'] = $entry['localHeaderOrder'] ?? null;
            $partInventory[$partName]['localHeaderOffset'] = $entry['localHeaderOffset'] ?? null;
            $partInventory[$partName]['localHeaderLength'] = $entry['localHeaderLength'] ?? null;
            $partInventory[$partName]['localHeaderSha256'] = $entry['localHeaderSha256'] ?? null;
            $partInventory[$partName]['compressedDataOffset'] = $entry['compressedDataOffset'] ?? null;
            $partInventory[$partName]['compressedDataEnd'] = $entry['compressedDataEnd'] ?? null;
            $partInventory[$partName]['compressedDataSha256'] = $entry['compressedDataSha256'] ?? null;
            $partInventory[$partName]['centralDirectoryRecordOffset'] = $entry['centralDirectoryRecordOffset'] ?? null;
            $partInventory[$partName]['centralDirectoryRecordEnd'] = $entry['centralDirectoryRecordEnd'] ?? null;
            $partInventory[$partName]['centralDirectoryRecordSha256'] = $entry['centralDirectoryRecordSha256'] ?? null;
            $partInventory[$partName]['matchesCentralDirectoryOrder'] = $entry['matchesCentralDirectoryOrder'] ?? null;
            $partInventory[$partName]['compressionMethod'] = $entry['compressionMethod'] ?? null;
            $partInventory[$partName]['compressionMethodName'] = $entry['compressionMethodName'] ?? null;
            $partInventory[$partName]['compressionSupported'] = $entry['compressionSupported'] ?? null;
            $partInventory[$partName]['compressedByteLength'] = $entry['compressedByteLength'] ?? null;
            $partInventory[$partName]['zipExpansionRatio'] = $entry['expansionRatio'] ?? null;
            $partInventory[$partName]['zipHasUnknownExpansionRatio'] = $entry['hasUnknownExpansionRatio'] ?? false;
            $partInventory[$partName]['zipCrc32'] = $entry['crc32'] ?? null;
            $partInventory[$partName]['zipByteExposurePolicy'] = $entry['byteExposurePolicy'] ?? null;
            $partInventory[$partName]['zipCanExposeBytes'] = $entry['canExposeBytes'] ?? null;
            $partInventory[$partName]['zipEntryComment'] = $entry['zipEntryComment'] ?? '';
            $partInventory[$partName]['zipEntryCommentLength'] = $entry['zipEntryCommentLength'] ?? 0;
            $partInventory[$partName]['zipEntryCommentEncoding'] = $entry['zipEntryCommentEncoding'] ?? 'utf-8';
            $partInventory[$partName]['zipEntryHasComment'] = $entry['zipEntryHasComment'] ?? false;
            $partInventory[$partName]['zipEntryCommentIssues'] = $entry['zipEntryCommentIssues'] ?? [];
            $partInventory[$partName]['centralExtraFieldIds'] = $entry['centralExtraFieldIds'] ?? [];
            $partInventory[$partName]['localExtraFieldIds'] = $entry['localExtraFieldIds'] ?? [];
            $partInventory[$partName]['duplicateCentralExtraFieldIds'] = $entry['duplicateCentralExtraFieldIds'] ?? [];
            $partInventory[$partName]['duplicateLocalExtraFieldIds'] = $entry['duplicateLocalExtraFieldIds'] ?? [];
            $partInventory[$partName]['centralOnlyExtraFieldIds'] = $entry['centralOnlyExtraFieldIds'] ?? [];
            $partInventory[$partName]['localOnlyExtraFieldIds'] = $entry['localOnlyExtraFieldIds'] ?? [];
            $partInventory[$partName]['mismatchedExtraFieldValueIds'] = $entry['mismatchedExtraFieldValueIds'] ?? [];
            $partInventory[$partName]['hasCentralExtraFields'] = $entry['hasCentralExtraFields'] ?? false;
            $partInventory[$partName]['hasLocalExtraFields'] = $entry['hasLocalExtraFields'] ?? false;
            $partInventory[$partName]['hasZipExtraFieldProvenance'] = $entry['hasZipExtraFieldProvenance'] ?? false;
            $partInventory[$partName]['hasDuplicateExtraFieldIds'] = $entry['hasDuplicateExtraFieldIds'] ?? false;
            $partInventory[$partName]['hasMismatchedExtraFieldIds'] = $entry['hasMismatchedExtraFieldIds'] ?? false;
            $partInventory[$partName]['hasMismatchedExtraFieldValues'] = $entry['hasMismatchedExtraFieldValues'] ?? false;
            $partInventory[$partName]['generalPurposeFlags'] = $entry['generalPurposeFlags'] ?? null;
            $partInventory[$partName]['generalPurposeFlagNames'] = $entry['generalPurposeFlagNames'] ?? [];
            $partInventory[$partName]['generalPurposeUnsupportedFlagBits'] = $entry['generalPurposeUnsupportedFlagBits'] ?? 0;
            $partInventory[$partName]['generalPurposeFlagsSupportedByReader'] = $entry['generalPurposeFlagsSupportedByReader'] ?? false;
            $partInventory[$partName]['zipUsesUtf8Names'] = $entry['zipUsesUtf8Names'] ?? false;
            $partInventory[$partName]['zipUsesDataDescriptorFlag'] = $entry['zipUsesDataDescriptorFlag'] ?? false;
            $partInventory[$partName]['zipDeflateOptionFlags'] = $entry['zipDeflateOptionFlags'] ?? 0;
            $partInventory[$partName]['zipDeflateOptionName'] = $entry['zipDeflateOptionName'] ?? null;
            $partInventory[$partName]['zipRequiresGeneralPurposeFlagReview'] = $entry['zipRequiresGeneralPurposeFlagReview'] ?? false;
            $partInventory[$partName]['generalPurposeFlagIssueCount'] = $entry['generalPurposeFlagIssueCount'] ?? 0;
            $partInventory[$partName]['generalPurposeFlagIssues'] = $entry['generalPurposeFlagIssues'] ?? [];
            $partInventory[$partName]['usesDataDescriptor'] = $entry['usesDataDescriptor'] ?? false;
            $partInventory[$partName]['dataDescriptorHasSignature'] = $entry['dataDescriptorHasSignature'] ?? null;
            $partInventory[$partName]['dataDescriptorOffset'] = $entry['dataDescriptorOffset'] ?? null;
            $partInventory[$partName]['dataDescriptorValueOffset'] = $entry['dataDescriptorValueOffset'] ?? null;
            $partInventory[$partName]['dataDescriptorLength'] = $entry['dataDescriptorLength'] ?? null;
            $partInventory[$partName]['dataDescriptorEnd'] = $entry['dataDescriptorEnd'] ?? null;
            $partInventory[$partName]['dataDescriptorCrc32Hex'] = $entry['dataDescriptorCrc32Hex'] ?? null;
            $partInventory[$partName]['dataDescriptorValuesMatchCentral'] = $entry['dataDescriptorValuesMatchCentral'] ?? null;
            $partInventory[$partName]['hasZeroLocalHeaderPlaceholders'] = $entry['hasZeroLocalHeaderPlaceholders'] ?? null;
            $partInventory[$partName]['dataDescriptorIssueCount'] = $entry['dataDescriptorIssueCount'] ?? 0;
            $partInventory[$partName]['dataDescriptorIssues'] = $entry['dataDescriptorIssues'] ?? [];
            $partInventory[$partName]['zipModifiedDosTime'] = $entry['zipModifiedDosTime'] ?? null;
            $partInventory[$partName]['zipModifiedDosDate'] = $entry['zipModifiedDosDate'] ?? null;
            $partInventory[$partName]['zipHasDosTimestamp'] = $entry['zipHasDosTimestamp'] ?? false;
            $partInventory[$partName]['zipIsDosTimestampValid'] = $entry['zipIsDosTimestampValid'] ?? true;
            $partInventory[$partName]['zipDosModifiedAt'] = $entry['zipDosModifiedAt'] ?? null;
            $partInventory[$partName]['zipExtendedModifiedAt'] = $entry['zipExtendedModifiedAt'] ?? null;
            $partInventory[$partName]['zipNtfsModifiedAt'] = $entry['zipNtfsModifiedAt'] ?? null;
            $partInventory[$partName]['zipModifiedAt'] = $entry['zipModifiedAt'] ?? null;
            $partInventory[$partName]['zipTimestampSource'] = $entry['zipTimestampSource'] ?? null;
            $partInventory[$partName]['zipCentralExtendedModifiedAt'] = $entry['zipCentralExtendedModifiedAt'] ?? null;
            $partInventory[$partName]['zipCentralNtfsModifiedAt'] = $entry['zipCentralNtfsModifiedAt'] ?? null;
            $partInventory[$partName]['zipCentralModifiedAt'] = $entry['zipCentralModifiedAt'] ?? null;
            $partInventory[$partName]['zipCentralTimestampSource'] = $entry['zipCentralTimestampSource'] ?? null;
            $partInventory[$partName]['zipLocalExtendedModifiedAt'] = $entry['zipLocalExtendedModifiedAt'] ?? null;
            $partInventory[$partName]['zipLocalNtfsModifiedAt'] = $entry['zipLocalNtfsModifiedAt'] ?? null;
            $partInventory[$partName]['zipLocalModifiedAt'] = $entry['zipLocalModifiedAt'] ?? null;
            $partInventory[$partName]['zipLocalTimestampSource'] = $entry['zipLocalTimestampSource'] ?? null;
            $partInventory[$partName]['zipModificationTimeIssueCount'] = $entry['zipModificationTimeIssueCount'] ?? 0;
            $partInventory[$partName]['zipModificationTimeIssues'] = $entry['zipModificationTimeIssues'] ?? [];
            foreach ([
                'hasSourceByteSpanProvenance',
                'localRecordOffset',
                'localRecordBytes',
                'localRecordEnd',
                'localRecordSha256',
                'localHeaderBytes',
                'localHeaderEnd',
                'localHeaderSha256',
                'localHeaderFixedHeaderBytes',
                'localFixedHeaderBytes',
                'localHeaderVariableFieldOffset',
                'localHeaderVariableFieldBytes',
                'localHeaderVariableFieldSha256',
                'localHeaderRawNameOffset',
                'localHeaderRawNameBytes',
                'localHeaderRawNameSha256',
                'localRawNameOffset',
                'localRawNameBytes',
                'localRawNameSha256',
                'localHeaderExtraFieldOffset',
                'localHeaderExtraFieldBytes',
                'localHeaderExtraFieldSha256',
                'localExtraFieldOffset',
                'localExtraFieldBytes',
                'localExtraFieldSha256',
                'localHeaderReviewFieldBytes',
                'compressedDataOffset',
                'compressedDataBytes',
                'compressedDataEnd',
                'compressedDataSha256',
                'sourceByteSpanIncludesDataDescriptor',
                'dataDescriptorBytes',
                'dataDescriptorSha256',
                'centralDirectoryRecordOffset',
                'centralDirectoryRecordBytes',
                'centralDirectoryRecordEnd',
                'centralDirectoryRecordSha256',
                'centralDirectoryFixedHeaderBytes',
                'centralDirectoryVariableFieldOffset',
                'centralDirectoryVariableFieldBytes',
                'centralDirectoryVariableFieldSha256',
                'centralDirectoryRawNameOffset',
                'centralDirectoryRawNameBytes',
                'centralDirectoryRawNameSha256',
                'centralDirectoryExtraFieldOffset',
                'centralDirectoryExtraFieldBytes',
                'centralDirectoryExtraFieldSha256',
                'centralDirectoryRawCommentOffset',
                'centralDirectoryRawCommentBytes',
                'centralDirectoryRawCommentSha256',
                'centralDirectoryReviewFieldBytes',
                'sourceRecordBytes',
                'sourceByteSpanIssueCount',
                'sourceByteSpanIssues',
            ] as $sourceRecordField) {
                $partInventory[$partName][$sourceRecordField] = $entry[$sourceRecordField] ?? null;
            }
        }

        return $partInventory;
    }

    private static function zipCompressionMethodName(int $method): string
    {
        return match ($method) {
            0 => 'stored',
            8 => 'deflated',
            default => 'unsupported',
        };
    }

    private static function zipExpansionRatio(int $uncompressedBytes, int $compressedBytes): ?float
    {
        if ($uncompressedBytes === 0) {
            return 0.0;
        }

        if ($compressedBytes === 0) {
            return null;
        }

        return $uncompressedBytes / $compressedBytes;
    }

    /**
     * @param list<array<string, mixed>> $buckets
     * @return list<array<string, mixed>>
     */
    private function zipCompressionBucketsWithExpansionRatios(array $buckets): array
    {
        foreach ($buckets as &$bucket) {
            if (!is_array($bucket)) {
                continue;
            }

            $bucket['expansionRatio'] = self::zipExpansionRatio(
                (int) ($bucket['uncompressedBytes'] ?? 0),
                (int) ($bucket['compressedBytes'] ?? 0),
            );
        }
        unset($bucket);

        return $buckets;
    }

    /**
     * @param list<array<string, mixed>> $entries
     * @return list<array<string, mixed>>
     */
    private function zipCompressionEntriesWithExpansionRatios(array $entries): array
    {
        foreach ($entries as &$entry) {
            if (!is_array($entry)) {
                continue;
            }

            $entry['expansionRatio'] = self::zipExpansionRatio(
                (int) ($entry['uncompressedSize'] ?? 0),
                (int) ($entry['compressedSize'] ?? 0),
            );
        }
        unset($entry);

        return $entries;
    }

    /**
     * @param array<string, mixed> $contentTypesPart
     * @param array<string, array<string, mixed>> $relationshipParts
     * @param array<string, array<string, mixed>> $partInventory
     * @return array<string, mixed>
     */
    private function packageProvenanceSummary(array $contentTypesPart, array $relationshipParts, array $partInventory): array
    {
        $roleCounts = [];
        $roleByteLengths = [];
        $contentTypeSourceCounts = [];
        $contentTypeSourceByteLengths = [];
        $contentTypeBaseCounts = [];
        $contentTypeParameterPartCount = 0;
        $contentTypeParameterByteLength = 0;
        $contentTypeParameterNameCounts = [];
        $contentTypeParameterSourceCounts = [];
        $contentTypeParameterValueCounts = [];
        $contentTypeParameters = [];
        $partsWithContentTypeParameters = [];
        $packageByteLength = 0;
        $relationshipPartCount = 0;
        $relationshipPartByteLength = 0;
        $missingContentTypePartByteLength = 0;
        foreach ($partInventory as $part) {
            $bytes = (int) ($part['bytes'] ?? 0);
            $packageByteLength += $bytes;
            $source = (string) ($part['contentTypeSource'] ?? 'missing');
            $contentTypeSourceCounts[$source] = ($contentTypeSourceCounts[$source] ?? 0) + 1;
            $contentTypeSourceByteLengths[$source] = ($contentTypeSourceByteLengths[$source] ?? 0) + $bytes;
            $contentTypeBase = is_string($part['contentTypeBase'] ?? null) ? $part['contentTypeBase'] : '';
            if ($contentTypeBase !== '') {
                $contentTypeBaseCounts[$contentTypeBase] = ($contentTypeBaseCounts[$contentTypeBase] ?? 0) + 1;
            }
            $parameterMap = is_array($part['contentTypeParameterMap'] ?? null)
                ? $part['contentTypeParameterMap']
                : [];
            if ($parameterMap !== []) {
                ++$contentTypeParameterPartCount;
                $contentTypeParameterByteLength += $bytes;
                $contentTypeParameterSourceCounts[$source] =
                    ($contentTypeParameterSourceCounts[$source] ?? 0) + 1;
                $partsWithContentTypeParameters[] = [
                    'partName' => (string) ($part['partName'] ?? ''),
                    'contentType' => is_string($part['contentType'] ?? null) ? $part['contentType'] : '',
                    'contentTypeBase' => $contentTypeBase,
                    'contentTypeParameterCount' => (int) ($part['contentTypeParameterCount'] ?? count($parameterMap)),
                    'contentTypeParameters' => is_array($part['contentTypeParameters'] ?? null)
                        ? $part['contentTypeParameters']
                        : [],
                    'contentTypeParameterMap' => $parameterMap,
                    'contentTypeSource' => $source,
                    'defaultExtension' => is_string($part['defaultExtension'] ?? null) ? $part['defaultExtension'] : null,
                    'overridePartName' => is_string($part['overridePartName'] ?? null) ? $part['overridePartName'] : null,
                    'roles' => array_values(array_map('strval', $part['roles'] ?? [])),
                    'isRelationshipPart' => (bool) ($part['isRelationshipPart'] ?? false),
                ];
            }
            foreach ($parameterMap as $parameterName => $parameterValue) {
                if (!is_string($parameterName) || $parameterName === '') {
                    continue;
                }

                $parameterValue = is_scalar($parameterValue) ? (string) $parameterValue : '';
                $parameterValueKey = $parameterValue === '' ? '(empty)' : $parameterValue;
                if (!isset($contentTypeParameters[$parameterName])) {
                    $contentTypeParameters[$parameterName] = [
                        'name' => $parameterName,
                        'partCount' => 0,
                        'valueCounts' => [],
                        'contentTypeSourceCounts' => [],
                        'contentTypeBases' => [],
                        'contentTypes' => [],
                        'partNames' => [],
                    ];
                }

                $contentTypeParameterNameCounts[$parameterName] =
                    ($contentTypeParameterNameCounts[$parameterName] ?? 0) + 1;
                $contentTypeParameterValueCounts[$parameterName][$parameterValueKey] =
                    ($contentTypeParameterValueCounts[$parameterName][$parameterValueKey] ?? 0) + 1;
                ++$contentTypeParameters[$parameterName]['partCount'];
                $contentTypeParameters[$parameterName]['valueCounts'][$parameterValueKey] =
                    ($contentTypeParameters[$parameterName]['valueCounts'][$parameterValueKey] ?? 0) + 1;
                $contentTypeParameters[$parameterName]['contentTypeSourceCounts'][$source] =
                    ($contentTypeParameters[$parameterName]['contentTypeSourceCounts'][$source] ?? 0) + 1;
                $this->appendUniqueString(
                    $contentTypeParameters[$parameterName]['contentTypeBases'],
                    is_string($part['contentTypeBase'] ?? null) ? $part['contentTypeBase'] : null,
                );
                $this->appendUniqueString(
                    $contentTypeParameters[$parameterName]['contentTypes'],
                    is_string($part['contentType'] ?? null) ? $part['contentType'] : null,
                );
                $this->appendUniqueString(
                    $contentTypeParameters[$parameterName]['partNames'],
                    is_string($part['partName'] ?? null) ? $part['partName'] : null,
                );
            }
            foreach (($part['roles'] ?? []) as $role) {
                $role = (string) $role;
                $roleCounts[$role] = ($roleCounts[$role] ?? 0) + 1;
                $roleByteLengths[$role] = ($roleByteLengths[$role] ?? 0) + $bytes;
            }
            if (($part['isRelationshipPart'] ?? false) === true) {
                ++$relationshipPartCount;
                $relationshipPartByteLength += $bytes;
            }
            if ($source === 'missing') {
                $missingContentTypePartByteLength += $bytes;
            }
        }

        ksort($roleCounts);
        ksort($roleByteLengths);
        ksort($contentTypeSourceCounts);
        ksort($contentTypeSourceByteLengths);
        ksort($contentTypeBaseCounts);
        ksort($contentTypeParameterNameCounts);
        ksort($contentTypeParameterSourceCounts);
        ksort($contentTypeParameterValueCounts);
        foreach ($contentTypeParameterValueCounts as &$parameterValueCounts) {
            ksort($parameterValueCounts);
        }
        unset($parameterValueCounts);
        ksort($contentTypeParameters);
        foreach ($contentTypeParameters as &$contentTypeParameter) {
            ksort($contentTypeParameter['contentTypeSourceCounts']);
            ksort($contentTypeParameter['valueCounts']);
        }
        unset($contentTypeParameter);

        $partDirectories = $this->packagePartDirectorySummary($partInventory);
        $partDirectoryBaseNames = $this->packagePartDirectoryBaseNameSummary($partInventory);
        $partDirectoryBaseNameCounts = [];
        foreach ($partDirectoryBaseNames as $directoryBaseNameSummary) {
            $directoryBaseName = (string) ($directoryBaseNameSummary['directoryBaseName'] ?? '');
            $partDirectoryBaseNameCounts[$directoryBaseName] = (int) ($directoryBaseNameSummary['partCount'] ?? 0);
        }
        ksort($partDirectoryBaseNameCounts, SORT_STRING);
        $duplicatePartDirectoryBaseNames = [];
        foreach ($partDirectoryBaseNames as $directoryBaseNameSummary) {
            if ((int) ($directoryBaseNameSummary['directoryCount'] ?? 0) > 1) {
                $duplicatePartDirectoryBaseNames[] = (string) ($directoryBaseNameSummary['directoryBaseName'] ?? '');
            }
        }
        $partCaseFoldDirectoryBaseNames = $this->packagePartCaseFoldDirectoryBaseNameSummary($partInventory);
        $partCaseFoldDirectoryBaseNameCounts = [];
        foreach ($partCaseFoldDirectoryBaseNames as $caseFoldDirectoryBaseNameSummary) {
            $caseFoldDirectoryBaseName = (string) ($caseFoldDirectoryBaseNameSummary['caseFoldDirectoryBaseName'] ?? '');
            $partCaseFoldDirectoryBaseNameCounts[$caseFoldDirectoryBaseName] =
                (int) ($caseFoldDirectoryBaseNameSummary['partCount'] ?? 0);
        }
        ksort($partCaseFoldDirectoryBaseNameCounts, SORT_STRING);
        $duplicatePartCaseFoldDirectoryBaseNames = [];
        foreach ($partCaseFoldDirectoryBaseNames as $caseFoldDirectoryBaseNameSummary) {
            if ((int) ($caseFoldDirectoryBaseNameSummary['directoryCount'] ?? 0) > 1) {
                $duplicatePartCaseFoldDirectoryBaseNames[] =
                    (string) ($caseFoldDirectoryBaseNameSummary['caseFoldDirectoryBaseName'] ?? '');
            }
        }
        $partDirectoryBaseNameStems = $this->packagePartDirectoryBaseNameStemSummary($partInventory);
        $partDirectoryBaseNameStemCounts = [];
        foreach ($partDirectoryBaseNameStems as $directoryBaseNameStemSummary) {
            $directoryBaseNameStem = (string) ($directoryBaseNameStemSummary['directoryBaseNameStem'] ?? '');
            $partDirectoryBaseNameStemCounts[$directoryBaseNameStem] =
                (int) ($directoryBaseNameStemSummary['partCount'] ?? 0);
        }
        ksort($partDirectoryBaseNameStemCounts, SORT_STRING);
        $duplicatePartDirectoryBaseNameStems = [];
        foreach ($partDirectoryBaseNameStems as $directoryBaseNameStemSummary) {
            if ((int) ($directoryBaseNameStemSummary['directoryCount'] ?? 0) > 1) {
                $duplicatePartDirectoryBaseNameStems[] =
                    (string) ($directoryBaseNameStemSummary['directoryBaseNameStem'] ?? '');
            }
        }
        $partCaseFoldDirectoryBaseNameStems = $this->packagePartCaseFoldDirectoryBaseNameStemSummary($partInventory);
        $partCaseFoldDirectoryBaseNameStemCounts = [];
        foreach ($partCaseFoldDirectoryBaseNameStems as $caseFoldDirectoryBaseNameStemSummary) {
            $caseFoldDirectoryBaseNameStem =
                (string) ($caseFoldDirectoryBaseNameStemSummary['caseFoldDirectoryBaseNameStem'] ?? '');
            $partCaseFoldDirectoryBaseNameStemCounts[$caseFoldDirectoryBaseNameStem] =
                (int) ($caseFoldDirectoryBaseNameStemSummary['partCount'] ?? 0);
        }
        ksort($partCaseFoldDirectoryBaseNameStemCounts, SORT_STRING);
        $duplicatePartCaseFoldDirectoryBaseNameStems = [];
        foreach ($partCaseFoldDirectoryBaseNameStems as $caseFoldDirectoryBaseNameStemSummary) {
