            foreach ($targetContentTypeSummary['contentTypeParameterValueCounts'] as &$targetBucketParameterValueCounts) {
                ksort($targetBucketParameterValueCounts);
            }
            unset($targetBucketParameterValueCounts);
            ksort($targetContentTypeSummary['contentTypeParameterSourceCounts']);
            unset($targetContentTypeSummary['_seenExistingTargetParts']);
        }
        unset($targetContentTypeSummary);
        ksort($relationshipTargetContentTypeMediaTypeCounts, SORT_STRING);
        ksort($relationshipTargetContentTypeMediaTypes, SORT_STRING);
        foreach ($relationshipTargetContentTypeMediaTypes as &$targetContentTypeMediaTypeSummary) {
            sort($targetContentTypeMediaTypeSummary['contentTypes'], SORT_STRING);
            sort($targetContentTypeMediaTypeSummary['sourceParts'], SORT_STRING);
            sort($targetContentTypeMediaTypeSummary['relationshipParts'], SORT_STRING);
            sort($targetContentTypeMediaTypeSummary['relationshipIds'], SORT_STRING);
            sort($targetContentTypeMediaTypeSummary['targetParts'], SORT_STRING);
            ksort($targetContentTypeMediaTypeSummary['contentTypeBaseCounts'], SORT_STRING);
            ksort($targetContentTypeMediaTypeSummary['contentTypeSourceCounts'], SORT_STRING);
            ksort($targetContentTypeMediaTypeSummary['relationshipTypeCounts'], SORT_STRING);
            ksort($targetContentTypeMediaTypeSummary['targetDirectoryCounts'], SORT_STRING);
            ksort($targetContentTypeMediaTypeSummary['roleCounts'], SORT_STRING);
            unset($targetContentTypeMediaTypeSummary['_seenExistingTargetParts']);
        }
        unset($targetContentTypeMediaTypeSummary);
        ksort($relationshipTargetContentTypeSubtypeCounts);
        ksort($relationshipTargetContentTypeSubtypes);
        foreach ($relationshipTargetContentTypeSubtypes as &$targetContentTypeSubtypeSummary) {
            sort($targetContentTypeSubtypeSummary['contentTypes'], SORT_STRING);
            sort($targetContentTypeSubtypeSummary['sourceParts'], SORT_STRING);
            sort($targetContentTypeSubtypeSummary['relationshipParts'], SORT_STRING);
            sort($targetContentTypeSubtypeSummary['relationshipIds'], SORT_STRING);
            sort($targetContentTypeSubtypeSummary['targetParts'], SORT_STRING);
            ksort($targetContentTypeSubtypeSummary['contentTypeBaseCounts'], SORT_STRING);
            ksort($targetContentTypeSubtypeSummary['contentTypeSourceCounts'], SORT_STRING);
            ksort($targetContentTypeSubtypeSummary['mediaTypeCounts'], SORT_STRING);
            ksort($targetContentTypeSubtypeSummary['relationshipTypeCounts'], SORT_STRING);
            ksort($targetContentTypeSubtypeSummary['targetDirectoryCounts'], SORT_STRING);
            ksort($targetContentTypeSubtypeSummary['roleCounts'], SORT_STRING);
            unset($targetContentTypeSubtypeSummary['_seenExistingTargetParts']);
        }
        unset($targetContentTypeSubtypeSummary);
        ksort($relationshipTargetRoleCounts);
        ksort($relationshipTargetExistingRoleCounts);
        ksort($relationshipTargetMissingRoleCounts);
        ksort($relationshipTargetRoles);
        foreach ($relationshipTargetRoles as &$targetRoleSummary) {
            ksort($targetRoleSummary['contentTypeSourceCounts']);
            ksort($targetRoleSummary['contentTypeBaseCounts']);
            ksort($targetRoleSummary['relationshipTypeCounts']);
            unset($targetRoleSummary['_seenExistingTargetParts']);
        }
        unset($targetRoleSummary);
        usort(
            $relationshipSourceExistingParts,
            static fn (array $left, array $right): int => ((int) $right['sourceBytes'] <=> (int) $left['sourceBytes'])
                ?: strcmp((string) $left['sourcePart'], (string) $right['sourcePart']),
        );
        $largestRelationshipSourceParts = array_slice($relationshipSourceExistingParts, 0, 5);
