                ++$relationshipTargetPartExtensionExistingByteBucketCount;
            }
            if ((int) ($targetPartExtensionSummary['missingTargetCount'] ?? 0) > 0) {
                ++$relationshipTargetPartExtensionNonExistingBucketCount;
