                    'contentTypeParameterMap' => is_array($part['contentTypeParameterMap'] ?? null) ? $part['contentTypeParameterMap'] : [],
                    'defaultExtension' => is_string($part['defaultExtension'] ?? null) ? $part['defaultExtension'] : null,
