    /**
     * @param array<string, array<string, mixed>> $partInventory
     * @return list<array<string, mixed>>
     */
    private function packagePartContentTypeParameterSourceSummary(array $partInventory): array
    {
        $sources = [];
        foreach ($partInventory as $partName => $part) {
            $parameterMap = is_array($part['contentTypeParameterMap'] ?? null)
                ? $part['contentTypeParameterMap']
                : [];
            if ($parameterMap === []) {
                continue;
            }

            $validParameterMap = [];
            foreach ($parameterMap as $parameterName => $parameterValue) {
                if (!is_string($parameterName) || $parameterName === '') {
                    continue;
                }
                $validParameterMap[$parameterName] = is_scalar($parameterValue) ? (string) $parameterValue : '';
            }
            if ($validParameterMap === []) {
                continue;
            }

            $contentTypeSource = is_string($part['contentTypeSource'] ?? null)
                ? $part['contentTypeSource']
                : 'missing';
            if ($contentTypeSource === '') {
                $contentTypeSource = 'missing';
            }
            if (!isset($sources[$contentTypeSource])) {
                $sources[$contentTypeSource] = [
                    'contentTypeSource' => $contentTypeSource,
                    'partCount' => 0,
                    'parameterCount' => 0,
                    'byteLength' => 0,
                    'relationshipPartCount' => 0,
                    'parameterNameCounts' => [],
                    'parameterValueCounts' => [],
                    'contentTypes' => [],
                    'contentTypeBaseCounts' => [],
                    'defaultExtensions' => [],
                    'overridePartNames' => [],
                    'roleCounts' => [],
                    'partNames' => [],
                    'largestPart' => null,
                ];
            }

            $partName = (string) ($part['partName'] ?? $partName);
            $bytes = (int) ($part['bytes'] ?? 0);
            $contentTypeBase = is_string($part['contentTypeBase'] ?? null) ? $part['contentTypeBase'] : '';
            $contentTypeBaseKey = $contentTypeBase === '' ? '(missing)' : $contentTypeBase;

            ++$sources[$contentTypeSource]['partCount'];
            $sources[$contentTypeSource]['parameterCount'] += count($validParameterMap);
            $sources[$contentTypeSource]['byteLength'] += $bytes;
            $sources[$contentTypeSource]['partNames'][] = $partName;
            $sources[$contentTypeSource]['contentTypeBaseCounts'][$contentTypeBaseKey] =
                ($sources[$contentTypeSource]['contentTypeBaseCounts'][$contentTypeBaseKey] ?? 0) + 1;
            if (($part['isRelationshipPart'] ?? false) === true) {
                ++$sources[$contentTypeSource]['relationshipPartCount'];
            }

            foreach ($validParameterMap as $parameterName => $parameterValue) {
                $parameterValueKey = $parameterValue === '' ? '(empty)' : $parameterValue;
                $sources[$contentTypeSource]['parameterNameCounts'][$parameterName] =
                    ($sources[$contentTypeSource]['parameterNameCounts'][$parameterName] ?? 0) + 1;
                $parameterValueBucketKey = $parameterName . '=' . $parameterValueKey;
                $sources[$contentTypeSource]['parameterValueCounts'][$parameterValueBucketKey] =
                    ($sources[$contentTypeSource]['parameterValueCounts'][$parameterValueBucketKey] ?? 0) + 1;
            }

            $this->appendUniqueString(
                $sources[$contentTypeSource]['contentTypes'],
                is_string($part['contentType'] ?? null) ? $part['contentType'] : null,
            );
            $this->appendUniqueString(
                $sources[$contentTypeSource]['defaultExtensions'],
                is_string($part['defaultExtension'] ?? null) ? $part['defaultExtension'] : null,
            );
            $this->appendUniqueString(
                $sources[$contentTypeSource]['overridePartNames'],
                is_string($part['overridePartName'] ?? null) ? $part['overridePartName'] : null,
            );

            foreach (($part['roles'] ?? []) as $role) {
                $role = (string) $role;
                if ($role === '') {
                    continue;
                }
                $sources[$contentTypeSource]['roleCounts'][$role] =
                    ($sources[$contentTypeSource]['roleCounts'][$role] ?? 0) + 1;
            }

            $partSummary = [
                'partName' => $partName,
                'directory' => is_string($part['directory'] ?? null) ? $part['directory'] : $this->packagePartDirectory($partName),
                'baseName' => is_string($part['baseName'] ?? null) ? $part['baseName'] : $this->packagePartBaseName($partName),
                'partExtension' => is_string($part['partExtension'] ?? null) ? $part['partExtension'] : null,
                'bytes' => $bytes,
                'crc32' => is_string($part['crc32'] ?? null) ? $part['crc32'] : null,
                'sha256' => is_string($part['sha256'] ?? null) ? $part['sha256'] : null,
                'contentType' => is_string($part['contentType'] ?? null) ? $part['contentType'] : '',
                'contentTypeBase' => $contentTypeBase,
                'contentTypeSource' => $contentTypeSource,
                'contentTypeParameterMap' => $validParameterMap,
                'defaultExtension' => is_string($part['defaultExtension'] ?? null) ? $part['defaultExtension'] : null,
                'overridePartName' => is_string($part['overridePartName'] ?? null) ? $part['overridePartName'] : null,
                'isRelationshipPart' => (bool) ($part['isRelationshipPart'] ?? false),
                'roles' => array_values(array_map('strval', $part['roles'] ?? [])),
            ];
            $largestPart = $sources[$contentTypeSource]['largestPart'];
            if (
                !is_array($largestPart)
                || $partSummary['bytes'] > (int) ($largestPart['bytes'] ?? 0)
                || (
                    $partSummary['bytes'] === (int) ($largestPart['bytes'] ?? 0)
                    && strcmp($partSummary['partName'], (string) ($largestPart['partName'] ?? '')) < 0
                )
            ) {
                $sources[$contentTypeSource]['largestPart'] = $partSummary;
            }
        }

        ksort($sources, SORT_STRING);
        foreach ($sources as $sourceKey => $summary) {
            sort($summary['contentTypes'], SORT_STRING);
            sort($summary['defaultExtensions'], SORT_STRING);
            sort($summary['overridePartNames'], SORT_STRING);
            sort($summary['partNames'], SORT_STRING);
            ksort($summary['parameterNameCounts'], SORT_STRING);
            ksort($summary['parameterValueCounts'], SORT_STRING);
            ksort($summary['contentTypeBaseCounts'], SORT_STRING);
            ksort($summary['roleCounts'], SORT_STRING);
            $sources[$sourceKey] = $summary;
        }

        return array_values($sources);
    }

    /**
     * @param array<string, array<string, mixed>> $partInventory
     * @return list<array<string, mixed>>
     */
    private function packagePartContentTypeSourceSummary(array $partInventory): array
    {
        $sources = [];
        foreach ($partInventory as $partName => $part) {
            $contentTypeSource = is_string($part['contentTypeSource'] ?? null)
                ? $part['contentTypeSource']
                : 'missing';
            if ($contentTypeSource === '') {
                $contentTypeSource = 'missing';
            }

            if (!isset($sources[$contentTypeSource])) {
                $sources[$contentTypeSource] = [
                    'contentTypeSource' => $contentTypeSource,
                    'partCount' => 0,
                    'byteLength' => 0,
                    'relationshipPartCount' => 0,
                    'missingContentTypePartCount' => 0,
                    'parameterizedPartCount' => 0,
                    'structuredSyntaxPartCount' => 0,
                    'contentTypes' => [],
                    'contentTypeBaseCounts' => [],
                    'contentTypeSyntaxSuffixCounts' => [],
                    'partExtensionCounts' => [],
                    'defaultExtensions' => [],
                    'overridePartNames' => [],
                    'roleCounts' => [],
                    'partNames' => [],
                    'largestPart' => null,
                ];
            }

            ++$sources[$contentTypeSource]['partCount'];
            $bytes = (int) ($part['bytes'] ?? 0);
            $sources[$contentTypeSource]['byteLength'] += $bytes;
            $sources[$contentTypeSource]['partNames'][] = (string) ($part['partName'] ?? $partName);

            if (($part['isRelationshipPart'] ?? false) === true) {
                ++$sources[$contentTypeSource]['relationshipPartCount'];
            }
            if ($contentTypeSource === 'missing') {
                ++$sources[$contentTypeSource]['missingContentTypePartCount'];
            }
            if (($part['contentTypeHasParameters'] ?? false) === true) {
                ++$sources[$contentTypeSource]['parameterizedPartCount'];
            }

            $contentTypeBase = is_string($part['contentTypeBase'] ?? null) ? $part['contentTypeBase'] : '';
            $contentTypeBaseKey = $contentTypeBase === '' ? '(missing)' : $contentTypeBase;
            $sources[$contentTypeSource]['contentTypeBaseCounts'][$contentTypeBaseKey] =
                ($sources[$contentTypeSource]['contentTypeBaseCounts'][$contentTypeBaseKey] ?? 0) + 1;

            $contentTypeSuffix = $this->contentTypeStructuredSyntaxSuffix($contentTypeBase);
            $contentTypeSyntaxSuffixKey = $contentTypeBase === '' ? '(missing)' : ($contentTypeSuffix ?? '(none)');
            $sources[$contentTypeSource]['contentTypeSyntaxSuffixCounts'][$contentTypeSyntaxSuffixKey] =
                ($sources[$contentTypeSource]['contentTypeSyntaxSuffixCounts'][$contentTypeSyntaxSuffixKey] ?? 0) + 1;
            if ($contentTypeSuffix !== null) {
                ++$sources[$contentTypeSource]['structuredSyntaxPartCount'];
            }

            $partExtension = is_string($part['partExtension'] ?? null) ? $part['partExtension'] : null;
            $partExtensionKey = $partExtension ?? '(none)';
            $sources[$contentTypeSource]['partExtensionCounts'][$partExtensionKey] =
                ($sources[$contentTypeSource]['partExtensionCounts'][$partExtensionKey] ?? 0) + 1;

            $this->appendUniqueString(
                $sources[$contentTypeSource]['contentTypes'],
                is_string($part['contentType'] ?? null) ? $part['contentType'] : null,
            );
            $this->appendUniqueString(
                $sources[$contentTypeSource]['defaultExtensions'],
                is_string($part['defaultExtension'] ?? null) ? $part['defaultExtension'] : null,
            );
            $this->appendUniqueString(
                $sources[$contentTypeSource]['overridePartNames'],
                is_string($part['overridePartName'] ?? null) ? $part['overridePartName'] : null,
            );

            foreach (($part['roles'] ?? []) as $role) {
                $role = (string) $role;
                $sources[$contentTypeSource]['roleCounts'][$role] =
                    ($sources[$contentTypeSource]['roleCounts'][$role] ?? 0) + 1;
            }

            $partSummary = [
                'partName' => (string) ($part['partName'] ?? $partName),
                'directory' => is_string($part['directory'] ?? null)
                    ? $part['directory']
                    : $this->packagePartDirectory((string) $partName),
                'baseName' => is_string($part['baseName'] ?? null)
                    ? $part['baseName']
                    : $this->packagePartBaseName((string) $partName),
                'partExtension' => $partExtension,
                'bytes' => $bytes,
                'crc32' => is_string($part['crc32'] ?? null) ? $part['crc32'] : null,
                'sha256' => is_string($part['sha256'] ?? null) ? $part['sha256'] : null,
                'contentType' => is_string($part['contentType'] ?? null) ? $part['contentType'] : '',
                'contentTypeBase' => $contentTypeBase,
                'contentTypeSyntaxSuffix' => $contentTypeSuffix,
                'contentTypeSource' => $contentTypeSource,
                'defaultExtension' => is_string($part['defaultExtension'] ?? null) ? $part['defaultExtension'] : null,
                'overridePartName' => is_string($part['overridePartName'] ?? null) ? $part['overridePartName'] : null,
                'isRelationshipPart' => (bool) ($part['isRelationshipPart'] ?? false),
                'roles' => array_values(array_map('strval', $part['roles'] ?? [])),
            ];
            $largestPart = $sources[$contentTypeSource]['largestPart'];
            if (
                !is_array($largestPart)
                || $partSummary['bytes'] > (int) ($largestPart['bytes'] ?? 0)
                || (
                    $partSummary['bytes'] === (int) ($largestPart['bytes'] ?? 0)
                    && strcmp($partSummary['partName'], (string) ($largestPart['partName'] ?? '')) < 0
                )
            ) {
                $sources[$contentTypeSource]['largestPart'] = $partSummary;
            }
        }

        ksort($sources, SORT_STRING);
        foreach ($sources as $source => $summary) {
            sort($summary['contentTypes'], SORT_STRING);
            sort($summary['defaultExtensions'], SORT_STRING);
            sort($summary['overridePartNames'], SORT_STRING);
            sort($summary['partNames'], SORT_STRING);
            ksort($summary['contentTypeBaseCounts'], SORT_STRING);
            ksort($summary['contentTypeSyntaxSuffixCounts'], SORT_STRING);
            ksort($summary['partExtensionCounts'], SORT_STRING);
            ksort($summary['roleCounts'], SORT_STRING);
            $sources[$source] = $summary;
        }

        return array_values($sources);
    }

    /**
     * @param array<string, array<string, mixed>> $partInventory
     * @return list<array<string, mixed>>
     */
    private function packagePartContentTypeSyntaxSuffixSummary(array $partInventory): array
    {
        $suffixes = [];
        foreach ($partInventory as $partName => $part) {
            $contentTypeBase = is_string($part['contentTypeBase'] ?? null) ? $part['contentTypeBase'] : '';
            $contentTypeSuffix = $this->contentTypeStructuredSyntaxSuffix($contentTypeBase);
            $suffixKey = $contentTypeBase === '' ? '(missing)' : ($contentTypeSuffix ?? '(none)');
            if (!isset($suffixes[$suffixKey])) {
                $suffixes[$suffixKey] = [
                    'contentTypeSyntaxSuffixKey' => $suffixKey,
                    'contentTypeSyntaxSuffix' => $contentTypeSuffix,
                    'hasStructuredSyntaxSuffix' => $contentTypeSuffix !== null,
                    'partCount' => 0,
                    'structuredSyntaxPartCount' => 0,
                    'byteLength' => 0,
                    'relationshipPartCount' => 0,
                    'missingContentTypePartCount' => 0,
                    'parameterizedPartCount' => 0,
                    'contentTypes' => [],
                    'contentTypeBaseCounts' => [],
                    'contentTypeSourceCounts' => [],
                    'mediaTypeCounts' => [],
                    'roleCounts' => [],
                    'partNames' => [],
                    'largestPart' => null,
                ];
            }

            ++$suffixes[$suffixKey]['partCount'];
            if ($contentTypeSuffix !== null) {
                ++$suffixes[$suffixKey]['structuredSyntaxPartCount'];
            }

            $bytes = (int) ($part['bytes'] ?? 0);
            $suffixes[$suffixKey]['byteLength'] += $bytes;
            $suffixes[$suffixKey]['partNames'][] = (string) $partName;
            if (($part['isRelationshipPart'] ?? false) === true) {
                ++$suffixes[$suffixKey]['relationshipPartCount'];
            }
            if ($contentTypeBase === '') {
                ++$suffixes[$suffixKey]['missingContentTypePartCount'];
            }
            if (($part['contentTypeHasParameters'] ?? false) === true) {
                ++$suffixes[$suffixKey]['parameterizedPartCount'];
            }

            $contentTypeBaseKey = $contentTypeBase === '' ? '(missing)' : $contentTypeBase;
            $suffixes[$suffixKey]['contentTypeBaseCounts'][$contentTypeBaseKey] =
                ($suffixes[$suffixKey]['contentTypeBaseCounts'][$contentTypeBaseKey] ?? 0) + 1;

            $contentTypeSource = is_string($part['contentTypeSource'] ?? null) ? $part['contentTypeSource'] : 'missing';
            if ($contentTypeSource === '') {
                $contentTypeSource = 'missing';
            }
            $suffixes[$suffixKey]['contentTypeSourceCounts'][$contentTypeSource] =
                ($suffixes[$suffixKey]['contentTypeSourceCounts'][$contentTypeSource] ?? 0) + 1;

            $mediaType = $this->contentTypeMediaTypeKey($contentTypeBase);
            $suffixes[$suffixKey]['mediaTypeCounts'][$mediaType] =
                ($suffixes[$suffixKey]['mediaTypeCounts'][$mediaType] ?? 0) + 1;

            $this->appendUniqueString(
                $suffixes[$suffixKey]['contentTypes'],
                is_string($part['contentType'] ?? null) ? $part['contentType'] : null,
            );

            foreach (($part['roles'] ?? []) as $role) {
                $role = (string) $role;
                $suffixes[$suffixKey]['roleCounts'][$role] =
                    ($suffixes[$suffixKey]['roleCounts'][$role] ?? 0) + 1;
            }

            $partSummary = [
                'partName' => (string) ($part['partName'] ?? $partName),
                'directory' => is_string($part['directory'] ?? null) ? $part['directory'] : $this->packagePartDirectory((string) $partName),
                'baseName' => is_string($part['baseName'] ?? null) ? $part['baseName'] : $this->packagePartBaseName((string) $partName),
                'bytes' => $bytes,
                'crc32' => is_string($part['crc32'] ?? null) ? $part['crc32'] : null,
                'sha256' => is_string($part['sha256'] ?? null) ? $part['sha256'] : null,
                'contentType' => is_string($part['contentType'] ?? null) ? $part['contentType'] : '',
                'contentTypeBase' => $contentTypeBase,
                'contentTypeSyntaxSuffix' => $contentTypeSuffix,
                'contentTypeSource' => $contentTypeSource,
                'roles' => array_values(array_map('strval', $part['roles'] ?? [])),
            ];
            $largestPart = $suffixes[$suffixKey]['largestPart'];
            if (
                !is_array($largestPart)
                || $partSummary['bytes'] > (int) ($largestPart['bytes'] ?? 0)
                || (
                    $partSummary['bytes'] === (int) ($largestPart['bytes'] ?? 0)
                    && strcmp($partSummary['partName'], (string) ($largestPart['partName'] ?? '')) < 0
                )
            ) {
                $suffixes[$suffixKey]['largestPart'] = $partSummary;
            }
        }

        ksort($suffixes, SORT_STRING);
        foreach ($suffixes as $suffixKey => $summary) {
            sort($summary['contentTypes'], SORT_STRING);
            sort($summary['partNames'], SORT_STRING);
            ksort($summary['contentTypeBaseCounts'], SORT_STRING);
            ksort($summary['contentTypeSourceCounts'], SORT_STRING);
            ksort($summary['mediaTypeCounts'], SORT_STRING);
            ksort($summary['roleCounts'], SORT_STRING);
            $suffixes[$suffixKey] = $summary;
        }

        return array_values($suffixes);
    }

