                'contentType' => is_string($part['contentType'] ?? null) ? $part['contentType'] : '',
                'contentTypeBase' => $contentTypeBase,
                'contentTypeSource' => $contentTypeSource,
                'roles' => array_values(array_map('strval', $part['roles'] ?? [])),
            ];
            $largestPart = $directoryBaseNameStems[$directoryBaseNameStem]['largestPart'];
            if (
                !is_array($largestPart)
                || $partSummary['bytes'] > (int) ($largestPart['bytes'] ?? 0)
                || (
                    $partSummary['bytes'] === (int) ($largestPart['bytes'] ?? 0)
                    && strcmp($partSummary['partName'], (string) ($largestPart['partName'] ?? '')) < 0
                )
            ) {
                $directoryBaseNameStems[$directoryBaseNameStem]['largestPart'] = $partSummary;
            }
        }

        ksort($directoryBaseNameStems, SORT_STRING);
        foreach ($directoryBaseNameStems as $directoryBaseNameStem => $summary) {
            $directories = array_keys($summary['directories']);
            sort($directories, SORT_STRING);
            sort($summary['partNames'], SORT_STRING);
            ksort($summary['directoryBaseNameCounts'], SORT_STRING);
            ksort($summary['directoryDepthCounts'], SORT_NUMERIC);
            ksort($summary['topLevelSegmentCounts'], SORT_STRING);
            ksort($summary['contentTypeSourceCounts'], SORT_STRING);
            ksort($summary['contentTypeBaseCounts'], SORT_STRING);
            ksort($summary['roleCounts'], SORT_STRING);
            $summary['directories'] = $directories;
            $summary['directoryCount'] = count($directories);
            $summary['directoryBaseNameVariantCount'] = count($summary['directoryBaseNameCounts']);
            $directoryBaseNameStems[$directoryBaseNameStem] = $summary;
        }

        return array_values($directoryBaseNameStems);
    }

    /**
     * @param array<string, array<string, mixed>> $partInventory
     * @return list<array<string, mixed>>
     */
    private function packagePartCaseFoldDirectoryBaseNameStemSummary(array $partInventory): array
    {
        $directoryBaseNameStems = [];
        foreach ($partInventory as $partName => $part) {
            $partName = (string) ($part['partName'] ?? $partName);
            $directory = is_string($part['directory'] ?? null)
                ? $part['directory']
                : $this->packagePartDirectory($partName);
            $directoryBaseName = is_string($part['directoryBaseName'] ?? null)
                ? $part['directoryBaseName']
                : $this->packagePartDirectoryBaseName($directory);
            $directoryBaseNameStem = is_string($part['directoryBaseNameStem'] ?? null)
                ? $part['directoryBaseNameStem']
                : $this->packagePartBaseNameStemFromBaseName($directoryBaseName);
            $caseFoldDirectoryBaseNameStem = is_string($part['caseFoldDirectoryBaseNameStem'] ?? null)
                ? $part['caseFoldDirectoryBaseNameStem']
                : $this->packagePartCaseFoldKey($directoryBaseNameStem);
            if (!isset($directoryBaseNameStems[$caseFoldDirectoryBaseNameStem])) {
                $directoryBaseNameStems[$caseFoldDirectoryBaseNameStem] = [
                    'caseFoldDirectoryBaseNameStem' => $caseFoldDirectoryBaseNameStem,
                    'directoryBaseNameStemVariantCount' => 0,
                    'directoryBaseNameVariantCount' => 0,
                    'directoryCount' => 0,
                    'partCount' => 0,
                    'byteLength' => 0,
                    'relationshipPartCount' => 0,
                    'missingContentTypePartCount' => 0,
                    'parameterizedPartCount' => 0,
                    'directoryBaseNameStemCounts' => [],
                    'directoryBaseNameCounts' => [],
                    'directoryDepthCounts' => [],
                    'topLevelSegmentCounts' => [],
                    'contentTypeSourceCounts' => [],
                    'contentTypeBaseCounts' => [],
                    'roleCounts' => [],
                    'directories' => [],
                    'partNames' => [],
                    'largestPart' => null,
                ];
            }

            ++$directoryBaseNameStems[$caseFoldDirectoryBaseNameStem]['partCount'];
            $bytes = (int) ($part['bytes'] ?? 0);
            $directoryBaseNameStems[$caseFoldDirectoryBaseNameStem]['byteLength'] += $bytes;
            $directoryBaseNameStems[$caseFoldDirectoryBaseNameStem]['partNames'][] = $partName;
            $directoryBaseNameStems[$caseFoldDirectoryBaseNameStem]['directories'][$directory] = true;
            $directoryBaseNameStems[$caseFoldDirectoryBaseNameStem]['directoryBaseNameStemCounts'][$directoryBaseNameStem] =
                ($directoryBaseNameStems[$caseFoldDirectoryBaseNameStem]['directoryBaseNameStemCounts'][$directoryBaseNameStem] ?? 0) + 1;
            $directoryBaseNameStems[$caseFoldDirectoryBaseNameStem]['directoryBaseNameCounts'][$directoryBaseName] =
                ($directoryBaseNameStems[$caseFoldDirectoryBaseNameStem]['directoryBaseNameCounts'][$directoryBaseName] ?? 0) + 1;

            $directoryDepth = is_int($part['directoryDepth'] ?? null)
                ? (int) $part['directoryDepth']
                : $this->packagePartDirectoryDepth($directory);
            $directoryBaseNameStems[$caseFoldDirectoryBaseNameStem]['directoryDepthCounts'][$directoryDepth] =
                ($directoryBaseNameStems[$caseFoldDirectoryBaseNameStem]['directoryDepthCounts'][$directoryDepth] ?? 0) + 1;

            $topLevelSegment = is_string($part['topLevelSegment'] ?? null)
                ? $part['topLevelSegment']
                : ($this->packagePartPathSegments($partName)[0] ?? '');
            $topLevelSegmentKey = $topLevelSegment === '' ? '(none)' : $topLevelSegment;
            $directoryBaseNameStems[$caseFoldDirectoryBaseNameStem]['topLevelSegmentCounts'][$topLevelSegmentKey] =
                ($directoryBaseNameStems[$caseFoldDirectoryBaseNameStem]['topLevelSegmentCounts'][$topLevelSegmentKey] ?? 0) + 1;

            if (($part['isRelationshipPart'] ?? false) === true) {
                ++$directoryBaseNameStems[$caseFoldDirectoryBaseNameStem]['relationshipPartCount'];
            }
            if (($part['contentTypeHasParameters'] ?? false) === true) {
                ++$directoryBaseNameStems[$caseFoldDirectoryBaseNameStem]['parameterizedPartCount'];
            }

            $contentTypeSource = is_string($part['contentTypeSource'] ?? null)
                ? $part['contentTypeSource']
                : 'missing';
            if ($contentTypeSource === '') {
                $contentTypeSource = 'missing';
            }
            if ($contentTypeSource === 'missing') {
                ++$directoryBaseNameStems[$caseFoldDirectoryBaseNameStem]['missingContentTypePartCount'];
            }
            $directoryBaseNameStems[$caseFoldDirectoryBaseNameStem]['contentTypeSourceCounts'][$contentTypeSource] =
                ($directoryBaseNameStems[$caseFoldDirectoryBaseNameStem]['contentTypeSourceCounts'][$contentTypeSource] ?? 0) + 1;

            $contentTypeBase = is_string($part['contentTypeBase'] ?? null) ? $part['contentTypeBase'] : '';
            $contentTypeBaseKey = $contentTypeBase === '' ? '(missing)' : $contentTypeBase;
            $directoryBaseNameStems[$caseFoldDirectoryBaseNameStem]['contentTypeBaseCounts'][$contentTypeBaseKey] =
                ($directoryBaseNameStems[$caseFoldDirectoryBaseNameStem]['contentTypeBaseCounts'][$contentTypeBaseKey] ?? 0) + 1;

            foreach (($part['roles'] ?? []) as $role) {
                $role = (string) $role;
                if ($role === '') {
                    continue;
                }

                $directoryBaseNameStems[$caseFoldDirectoryBaseNameStem]['roleCounts'][$role] =
                    ($directoryBaseNameStems[$caseFoldDirectoryBaseNameStem]['roleCounts'][$role] ?? 0) + 1;
            }

            $partSummary = [
                'partName' => $partName,
                'directory' => $directory,
                'directoryBaseName' => $directoryBaseName,
                'directoryBaseNameStem' => $directoryBaseNameStem,
                'caseFoldDirectoryBaseNameStem' => $caseFoldDirectoryBaseNameStem,
                'directoryDepth' => $directoryDepth,
                'topLevelSegment' => $topLevelSegment,
                'baseName' => is_string($part['baseName'] ?? null) ? $part['baseName'] : $this->packagePartBaseName($partName),
                'bytes' => $bytes,
                'crc32' => is_string($part['crc32'] ?? null) ? $part['crc32'] : null,
                'sha256' => is_string($part['sha256'] ?? null) ? $part['sha256'] : null,
                'contentType' => is_string($part['contentType'] ?? null) ? $part['contentType'] : '',
                'contentTypeBase' => $contentTypeBase,
                'contentTypeSource' => $contentTypeSource,
                'roles' => array_values(array_map('strval', $part['roles'] ?? [])),
            ];
            $largestPart = $directoryBaseNameStems[$caseFoldDirectoryBaseNameStem]['largestPart'];
            if (
                !is_array($largestPart)
                || $partSummary['bytes'] > (int) ($largestPart['bytes'] ?? 0)
                || (
                    $partSummary['bytes'] === (int) ($largestPart['bytes'] ?? 0)
                    && strcmp($partSummary['partName'], (string) ($largestPart['partName'] ?? '')) < 0
                )
            ) {
                $directoryBaseNameStems[$caseFoldDirectoryBaseNameStem]['largestPart'] = $partSummary;
            }
        }

        ksort($directoryBaseNameStems, SORT_STRING);
        foreach ($directoryBaseNameStems as $caseFoldDirectoryBaseNameStem => $summary) {
            $directories = array_keys($summary['directories']);
            sort($directories, SORT_STRING);
            sort($summary['partNames'], SORT_STRING);
            ksort($summary['directoryBaseNameStemCounts'], SORT_STRING);
            ksort($summary['directoryBaseNameCounts'], SORT_STRING);
            ksort($summary['directoryDepthCounts'], SORT_NUMERIC);
            ksort($summary['topLevelSegmentCounts'], SORT_STRING);
            ksort($summary['contentTypeSourceCounts'], SORT_STRING);
            ksort($summary['contentTypeBaseCounts'], SORT_STRING);
            ksort($summary['roleCounts'], SORT_STRING);
            $summary['directories'] = $directories;
            $summary['directoryCount'] = count($directories);
            $summary['directoryBaseNameStemVariantCount'] = count($summary['directoryBaseNameStemCounts']);
            $summary['directoryBaseNameVariantCount'] = count($summary['directoryBaseNameCounts']);
            $directoryBaseNameStems[$caseFoldDirectoryBaseNameStem] = $summary;
        }

        return array_values($directoryBaseNameStems);
    }

    /**
     * @param array<string, array<string, mixed>> $partInventory
     * @return list<array<string, mixed>>
     */
    private function packagePartDirectoryDepthSummary(array $partInventory): array
    {
        $depths = [];
        foreach ($partInventory as $partName => $part) {
            $partName = (string) ($part['partName'] ?? $partName);
            $directory = is_string($part['directory'] ?? null)
                ? $part['directory']
                : $this->packagePartDirectory($partName);
            $directoryDepth = is_int($part['directoryDepth'] ?? null)
                ? (int) $part['directoryDepth']
                : $this->packagePartDirectoryDepth($directory);
            $directoryDepthKey = (string) $directoryDepth;
            if (!isset($depths[$directoryDepthKey])) {
                $depths[$directoryDepthKey] = [
                    'directoryDepth' => $directoryDepth,
                    'directoryCount' => 0,
                    'partCount' => 0,
                    'byteLength' => 0,
                    'relationshipPartCount' => 0,
                    'missingContentTypePartCount' => 0,
                    'parameterizedPartCount' => 0,
                    'directoryCounts' => [],
                    'contentTypeSourceCounts' => [],
                    'contentTypeBaseCounts' => [],
                    'roleCounts' => [],
                    'directories' => [],
                    'partNames' => [],
                    'largestPart' => null,
                ];
            }

            $bytes = (int) ($part['bytes'] ?? 0);
            $baseName = is_string($part['baseName'] ?? null) ? $part['baseName'] : $this->packagePartBaseName($partName);
            $pathSegmentCount = is_int($part['pathSegmentCount'] ?? null)
                ? (int) $part['pathSegmentCount']
                : count($this->packagePartPathSegments($partName));
            $contentType = is_string($part['contentType'] ?? null) ? $part['contentType'] : '';
            $contentTypeSource = is_string($part['contentTypeSource'] ?? null)
                ? $part['contentTypeSource']
                : 'missing';
            if ($contentTypeSource === '') {
                $contentTypeSource = 'missing';
            }
            $contentTypeBase = is_string($part['contentTypeBase'] ?? null) ? $part['contentTypeBase'] : '';
            $contentTypeBaseKey = $contentTypeBase === '' ? '(missing)' : $contentTypeBase;

            ++$depths[$directoryDepthKey]['partCount'];
            $depths[$directoryDepthKey]['byteLength'] += $bytes;
            $depths[$directoryDepthKey]['directoryCounts'][$directory] =
                ($depths[$directoryDepthKey]['directoryCounts'][$directory] ?? 0) + 1;
            $depths[$directoryDepthKey]['partNames'][] = $partName;
            if (($part['isRelationshipPart'] ?? false) === true) {
                ++$depths[$directoryDepthKey]['relationshipPartCount'];
            }
            if ($contentTypeSource === 'missing') {
                ++$depths[$directoryDepthKey]['missingContentTypePartCount'];
            }
            if (($part['contentTypeHasParameters'] ?? false) === true) {
                ++$depths[$directoryDepthKey]['parameterizedPartCount'];
            }
            $depths[$directoryDepthKey]['contentTypeSourceCounts'][$contentTypeSource] =
                ($depths[$directoryDepthKey]['contentTypeSourceCounts'][$contentTypeSource] ?? 0) + 1;
            $depths[$directoryDepthKey]['contentTypeBaseCounts'][$contentTypeBaseKey] =
                ($depths[$directoryDepthKey]['contentTypeBaseCounts'][$contentTypeBaseKey] ?? 0) + 1;

            foreach (($part['roles'] ?? []) as $role) {
                $role = (string) $role;
                if ($role === '') {
                    continue;
                }
                $depths[$directoryDepthKey]['roleCounts'][$role] =
                    ($depths[$directoryDepthKey]['roleCounts'][$role] ?? 0) + 1;
            }

            $partSummary = [
                'partName' => $partName,
                'directory' => $directory,
                'directoryDepth' => $directoryDepth,
                'baseName' => $baseName,
                'pathSegmentCount' => $pathSegmentCount,
                'bytes' => $bytes,
                'crc32' => is_string($part['crc32'] ?? null) ? $part['crc32'] : null,
                'sha256' => is_string($part['sha256'] ?? null) ? $part['sha256'] : null,
                'contentType' => $contentType,
                'contentTypeBase' => $contentTypeBase,
                'contentTypeSource' => $contentTypeSource,
                'isRelationshipPart' => (bool) ($part['isRelationshipPart'] ?? false),
                'roles' => array_values(array_map('strval', $part['roles'] ?? [])),
            ];
            $largestPart = $depths[$directoryDepthKey]['largestPart'];
            if (
                !is_array($largestPart)
                || $partSummary['bytes'] > (int) ($largestPart['bytes'] ?? 0)
                || (
                    $partSummary['bytes'] === (int) ($largestPart['bytes'] ?? 0)
                    && strcmp($partSummary['partName'], (string) ($largestPart['partName'] ?? '')) < 0
                )
            ) {
                $depths[$directoryDepthKey]['largestPart'] = $partSummary;
            }
        }

        ksort($depths, SORT_NUMERIC);
        foreach ($depths as $directoryDepthKey => $summary) {
            ksort($summary['directoryCounts'], SORT_STRING);
            ksort($summary['contentTypeSourceCounts'], SORT_STRING);
            ksort($summary['contentTypeBaseCounts'], SORT_STRING);
            ksort($summary['roleCounts'], SORT_STRING);
            $directories = array_keys($summary['directoryCounts']);
            sort($directories, SORT_STRING);
            sort($summary['partNames'], SORT_STRING);
            $summary['directoryCount'] = count($directories);
            $summary['directories'] = $directories;
            $depths[$directoryDepthKey] = $summary;
        }

        return array_values($depths);
    }

    /**
     * @param list<array<string, mixed>> $relationshipSources
     * @return list<array<string, mixed>>
     */
    private function relationshipSourcePathDepthSummary(array $relationshipSources): array
    {
        $depths = [];
        foreach ($relationshipSources as $source) {
            $depth = is_int($source['sourcePathDepth'] ?? null) ? (int) $source['sourcePathDepth'] : null;
            $depthKey = $depth === null ? '(invalid-source)' : (string) $depth;
            $sourcePart = is_string($source['sourcePart'] ?? null) ? $source['sourcePart'] : '';
            $pathSegmentCount = is_int($source['sourcePathSegmentCount'] ?? null)
                ? (int) $source['sourcePathSegmentCount']
                : count($sourcePart === '' ? [] : $this->packagePartPathSegments($sourcePart));
            if (!isset($depths[$depthKey])) {
                $depths[$depthKey] = [
                    'sourcePathDepthKey' => $depthKey,
                    'sourcePathDepth' => $depth,
                    'pathSegmentCount' => $pathSegmentCount,
                    'sourceCount' => 0,
                    'existingSourceCount' => 0,
                    'nonExistingSourceCount' => 0,
                    'relationshipCount' => 0,
                    'relationshipRecordCount' => 0,
                    'existingSourceByteLength' => 0,
                    'relationshipSourceKindCounts' => [],
                    'sourceDirectoryCounts' => [],
                    'sourceBaseNameCounts' => [],
                    'sourcePartExtensionCounts' => [],
                    'sourceContentTypeBaseCounts' => [],
                    'sourceContentTypeSourceCounts' => [],
                    'sourceRoleCounts' => [],
                    'sourceDirectories' => [],
                    'sourceParts' => [],
                    'relationshipParts' => [],
                    'largestExistingSourcePart' => null,
                ];
            }

            ++$depths[$depthKey]['sourceCount'];
            $sourceExists = ($source['sourceExists'] ?? false) === true;
            if ($sourceExists) {
                ++$depths[$depthKey]['existingSourceCount'];
            } else {
                ++$depths[$depthKey]['nonExistingSourceCount'];
            }
            $depths[$depthKey]['relationshipCount'] += (int) ($source['relationshipCount'] ?? 0);
            $depths[$depthKey]['relationshipRecordCount'] += (int) ($source['relationshipRecordCount'] ?? 0);

            $sourceKind = is_string($source['relationshipSourceKind'] ?? null)
                ? $source['relationshipSourceKind']
                : 'invalid-source';
            $depths[$depthKey]['relationshipSourceKindCounts'][$sourceKind] =
                ($depths[$depthKey]['relationshipSourceKindCounts'][$sourceKind] ?? 0) + 1;

            $directory = is_string($source['sourceDirectory'] ?? null) ? $source['sourceDirectory'] : '';
            $directoryKey = $directory === '' ? '(invalid-source)' : $directory;
            $depths[$depthKey]['sourceDirectoryCounts'][$directoryKey] =
                ($depths[$depthKey]['sourceDirectoryCounts'][$directoryKey] ?? 0) + 1;

            $baseName = is_string($source['sourceBaseName'] ?? null) ? $source['sourceBaseName'] : '';
            $baseNameKey = $baseName === '' ? '(invalid-source)' : $baseName;
            $depths[$depthKey]['sourceBaseNameCounts'][$baseNameKey] =
                ($depths[$depthKey]['sourceBaseNameCounts'][$baseNameKey] ?? 0) + 1;

            $extension = is_string($source['sourcePartExtension'] ?? null)
                ? $source['sourcePartExtension']
                : null;
            $extensionKey = $extension ?? '(none)';
            $depths[$depthKey]['sourcePartExtensionCounts'][$extensionKey] =
                ($depths[$depthKey]['sourcePartExtensionCounts'][$extensionKey] ?? 0) + 1;

            $contentTypeBase = is_string($source['sourceContentTypeBase'] ?? null)
                ? $source['sourceContentTypeBase']
                : '';
            $contentTypeBaseKey = $contentTypeBase === '' ? '(missing)' : $contentTypeBase;
            $depths[$depthKey]['sourceContentTypeBaseCounts'][$contentTypeBaseKey] =
                ($depths[$depthKey]['sourceContentTypeBaseCounts'][$contentTypeBaseKey] ?? 0) + 1;

            $contentTypeSource = is_string($source['sourceContentTypeSource'] ?? null)
                ? $source['sourceContentTypeSource']
                : '';
            $contentTypeSourceKey = $contentTypeSource === '' ? '(missing)' : $contentTypeSource;
            $depths[$depthKey]['sourceContentTypeSourceCounts'][$contentTypeSourceKey] =
                ($depths[$depthKey]['sourceContentTypeSourceCounts'][$contentTypeSourceKey] ?? 0) + 1;

            foreach (($source['sourceRoles'] ?? []) as $role) {
                $role = (string) $role;
                $depths[$depthKey]['sourceRoleCounts'][$role] =
                    ($depths[$depthKey]['sourceRoleCounts'][$role] ?? 0) + 1;
            }

            $this->appendUniqueString($depths[$depthKey]['sourceDirectories'], $directory === '' ? null : $directory);
            $this->appendUniqueString(
                $depths[$depthKey]['sourceParts'],
                $sourcePart === '' ? null : $sourcePart,
            );
            $this->appendUniqueString(
                $depths[$depthKey]['relationshipParts'],
                is_string($source['relationshipsPart'] ?? null) ? $source['relationshipsPart'] : null,
            );

            if (is_int($source['sourceBytes'] ?? null)) {
                $sourceBytes = (int) $source['sourceBytes'];
                $depths[$depthKey]['existingSourceByteLength'] += $sourceBytes;
                $sourceSummary = [
                    'sourcePart' => $sourcePart,
                    'relationshipsPart' => is_string($source['relationshipsPart'] ?? null) ? $source['relationshipsPart'] : '',
                    'relationshipSourceKind' => $sourceKind,
                    'sourceDirectory' => $directory === '' ? null : $directory,
                    'sourcePathDepth' => $depth,
                    'sourceDirectoryDepth' => is_int($source['sourceDirectoryDepth'] ?? null)
                        ? (int) $source['sourceDirectoryDepth']
                        : $this->packagePartDirectoryDepth($directory),
                    'sourceBaseName' => $baseName === '' ? null : $baseName,
                    'sourcePartExtension' => $extension,
                    'sourcePathSegments' => is_array($source['sourcePathSegments'] ?? null)
                        ? array_values(array_map('strval', $source['sourcePathSegments']))
                        : ($sourcePart === '' ? [] : $this->packagePartPathSegments($sourcePart)),
                    'sourcePathSegmentCount' => $pathSegmentCount,
                    'sourceBytes' => $sourceBytes,
                    'sourceCrc32' => is_string($source['sourceCrc32'] ?? null) ? $source['sourceCrc32'] : null,
                    'sourceSha256' => is_string($source['sourceSha256'] ?? null) ? $source['sourceSha256'] : null,
                    'sourceContentTypeBase' => $contentTypeBase === '' ? null : $contentTypeBase,
                    'sourceContentTypeSource' => $contentTypeSource === '' ? null : $contentTypeSource,
                    'sourceRoles' => array_values(array_map('strval', $source['sourceRoles'] ?? [])),
                ];
                $largestPart = $depths[$depthKey]['largestExistingSourcePart'];
                if (
                    !is_array($largestPart)
                    || $sourceSummary['sourceBytes'] > (int) ($largestPart['sourceBytes'] ?? 0)
                    || (
                        $sourceSummary['sourceBytes'] === (int) ($largestPart['sourceBytes'] ?? 0)
                        && strcmp($sourceSummary['sourcePart'], (string) ($largestPart['sourcePart'] ?? '')) < 0
                    )
                ) {
                    $depths[$depthKey]['largestExistingSourcePart'] = $sourceSummary;
                }
            }
        }

        ksort($depths, SORT_STRING);
        foreach ($depths as $depthKey => $summary) {
            ksort($summary['relationshipSourceKindCounts'], SORT_STRING);
            ksort($summary['sourceDirectoryCounts'], SORT_STRING);
            ksort($summary['sourceBaseNameCounts'], SORT_STRING);
            ksort($summary['sourcePartExtensionCounts'], SORT_STRING);
            ksort($summary['sourceContentTypeBaseCounts'], SORT_STRING);
            ksort($summary['sourceContentTypeSourceCounts'], SORT_STRING);
            ksort($summary['sourceRoleCounts'], SORT_STRING);
            sort($summary['sourceDirectories'], SORT_STRING);
            sort($summary['sourceParts'], SORT_STRING);
            sort($summary['relationshipParts'], SORT_STRING);
            $depths[$depthKey] = $summary;
        }

        return array_values($depths);
    }

    /**
     * @param array<string, array<string, mixed>> $relationshipTargetDirectories
     * @return list<array<string, mixed>>
     */
    private function relationshipTargetDirectoryDepthSummary(array $relationshipTargetDirectories): array
    {
        $depths = [];
        foreach ($relationshipTargetDirectories as $directorySummary) {
            $directory = is_string($directorySummary['directory'] ?? null)
                ? $directorySummary['directory']
                : '';
            $depth = $this->packagePartDirectoryDepth($directory);
            $depthKey = (string) $depth;
            if (!isset($depths[$depthKey])) {
                $depths[$depthKey] = [
                    'targetDirectoryDepthKey' => $depthKey,
                    'targetDirectoryDepth' => $depth,
                    'targetDirectoryCount' => 0,
                    'relationshipCount' => 0,
                    'existingTargetCount' => 0,
                    'missingTargetCount' => 0,
                    'parameterizedTargetCount' => 0,
                    'targetDirectoryCounts' => [],
                    'contentTypeSourceCounts' => [],
                    'targetDirectories' => [],
                    'sourceParts' => [],
                    'relationshipParts' => [],
                    'relationshipIds' => [],
                    'relationshipTypes' => [],
                    'contentTypes' => [],
                    'targetParts' => [],
                ];
            }

            $relationshipCount = (int) ($directorySummary['relationshipCount'] ?? 0);
            ++$depths[$depthKey]['targetDirectoryCount'];
            $depths[$depthKey]['relationshipCount'] += $relationshipCount;
            $depths[$depthKey]['existingTargetCount'] += (int) ($directorySummary['existingTargetCount'] ?? 0);
            $depths[$depthKey]['missingTargetCount'] += (int) ($directorySummary['missingTargetCount'] ?? 0);
            $depths[$depthKey]['parameterizedTargetCount'] += (int) ($directorySummary['parameterizedTargetCount'] ?? 0);
            $depths[$depthKey]['targetDirectoryCounts'][$directory] =
                ($depths[$depthKey]['targetDirectoryCounts'][$directory] ?? 0) + $relationshipCount;
            $this->appendUniqueString($depths[$depthKey]['targetDirectories'], $directory);

            foreach (($directorySummary['contentTypeSourceCounts'] ?? []) as $source => $count) {
                if (!is_string($source)) {
                    continue;
                }
                $depths[$depthKey]['contentTypeSourceCounts'][$source] =
                    ($depths[$depthKey]['contentTypeSourceCounts'][$source] ?? 0) + (int) $count;
            }

            foreach (['sourceParts', 'relationshipParts', 'relationshipIds', 'relationshipTypes', 'contentTypes', 'targetParts'] as $listKey) {
                foreach (($directorySummary[$listKey] ?? []) as $value) {
                    $this->appendUniqueString($depths[$depthKey][$listKey], is_string($value) ? $value : null);
                }
            }
        }

        ksort($depths, SORT_NUMERIC);
        foreach ($depths as $depthKey => $summary) {
            ksort($summary['targetDirectoryCounts'], SORT_STRING);
            ksort($summary['contentTypeSourceCounts'], SORT_STRING);
            sort($summary['targetDirectories'], SORT_STRING);
            sort($summary['sourceParts'], SORT_STRING);
            sort($summary['relationshipParts'], SORT_STRING);
            sort($summary['relationshipIds'], SORT_STRING);
            sort($summary['relationshipTypes'], SORT_STRING);
            sort($summary['contentTypes'], SORT_STRING);
            sort($summary['targetParts'], SORT_STRING);
            $depths[$depthKey] = $summary;
        }

        return array_values($depths);
    }

    /**
     * @param list<array<string, mixed>> $relationshipTargets
     * @return list<array<string, mixed>>
     */
    private function relationshipTargetCaseFoldDirectoryBaseNameSummary(array $relationshipTargets): array
    {
        $directoryBaseNames = [];
        foreach ($relationshipTargets as $target) {
            $targetPart = is_string($target['targetPart'] ?? null) ? $target['targetPart'] : '';
            if ($targetPart === '') {
                continue;
            }

            $targetDirectory = is_string($target['targetDirectory'] ?? null)
                ? $target['targetDirectory']
                : $this->packagePartDirectory($targetPart);
            $targetDirectoryBaseName = is_string($target['targetDirectoryBaseName'] ?? null)
                ? $target['targetDirectoryBaseName']
                : $this->packagePartDirectoryBaseName($targetDirectory);
            $caseFoldDirectoryBaseName = is_string($target['targetCaseFoldDirectoryBaseName'] ?? null)
                ? $target['targetCaseFoldDirectoryBaseName']
                : $this->packagePartCaseFoldKey($targetDirectoryBaseName);
            if (!isset($directoryBaseNames[$caseFoldDirectoryBaseName])) {
                $directoryBaseNames[$caseFoldDirectoryBaseName] = [
                    'caseFoldDirectoryBaseName' => $caseFoldDirectoryBaseName,
                    'directoryBaseNameVariantCount' => 0,
                    'directoryCount' => 0,
                    'relationshipCount' => 0,
                    'existingTargetCount' => 0,
                    'missingTargetCount' => 0,
                    'missingContentTypeTargetCount' => 0,
                    'parameterizedTargetCount' => 0,
                    'existingTargetByteLength' => 0,
                    'directoryBaseNameCounts' => [],
                    'targetDirectoryCounts' => [],
                    'contentTypeSourceCounts' => [],
                    'contentTypeBaseCounts' => [],
                    'relationshipTypeCounts' => [],
                    'roleCounts' => [],
                    'targetDirectories' => [],
                    'sourceParts' => [],
                    'relationshipParts' => [],
                    'relationshipIds' => [],
                    'relationshipTypes' => [],
                    'contentTypes' => [],
                    'targetParts' => [],
                    'largestExistingTargetPart' => null,
                    '_seenExistingTargetParts' => [],
                ];
            }

            ++$directoryBaseNames[$caseFoldDirectoryBaseName]['relationshipCount'];
            $directoryBaseNames[$caseFoldDirectoryBaseName]['directoryBaseNameCounts'][$targetDirectoryBaseName] =
                ($directoryBaseNames[$caseFoldDirectoryBaseName]['directoryBaseNameCounts'][$targetDirectoryBaseName] ?? 0) + 1;
            $directoryBaseNames[$caseFoldDirectoryBaseName]['targetDirectoryCounts'][$targetDirectory] =
                ($directoryBaseNames[$caseFoldDirectoryBaseName]['targetDirectoryCounts'][$targetDirectory] ?? 0) + 1;

            $targetExists = ($target['targetExists'] ?? false) === true;
            if ($targetExists) {
                ++$directoryBaseNames[$caseFoldDirectoryBaseName]['existingTargetCount'];
            } else {
                ++$directoryBaseNames[$caseFoldDirectoryBaseName]['missingTargetCount'];
            }

            $targetContentTypeSource = is_string($target['targetContentTypeSource'] ?? null)
                ? $target['targetContentTypeSource']
                : 'missing';
            if ($targetContentTypeSource === '') {
                $targetContentTypeSource = 'missing';
            }
            $directoryBaseNames[$caseFoldDirectoryBaseName]['contentTypeSourceCounts'][$targetContentTypeSource] =
                ($directoryBaseNames[$caseFoldDirectoryBaseName]['contentTypeSourceCounts'][$targetContentTypeSource] ?? 0) + 1;
            if ($targetContentTypeSource === 'missing') {
                ++$directoryBaseNames[$caseFoldDirectoryBaseName]['missingContentTypeTargetCount'];
            }

            $targetContentTypeBase = is_string($target['targetContentTypeBase'] ?? null)
                ? $target['targetContentTypeBase']
                : '';
            $targetContentTypeBaseKey = $targetContentTypeBase === '' ? '(missing)' : $targetContentTypeBase;
            $directoryBaseNames[$caseFoldDirectoryBaseName]['contentTypeBaseCounts'][$targetContentTypeBaseKey] =
                ($directoryBaseNames[$caseFoldDirectoryBaseName]['contentTypeBaseCounts'][$targetContentTypeBaseKey] ?? 0) + 1;

            if (($target['targetContentTypeHasParameters'] ?? false) === true) {
                ++$directoryBaseNames[$caseFoldDirectoryBaseName]['parameterizedTargetCount'];
            }

            $relationshipType = is_string($target['relationshipType'] ?? null) ? $target['relationshipType'] : '';
            $relationshipTypeKey = is_string($target['relationshipTypeKey'] ?? null)
                ? $target['relationshipTypeKey']
                : ($relationshipType === '' ? '(missing-type)' : $relationshipType);
            $directoryBaseNames[$caseFoldDirectoryBaseName]['relationshipTypeCounts'][$relationshipTypeKey] =
                ($directoryBaseNames[$caseFoldDirectoryBaseName]['relationshipTypeCounts'][$relationshipTypeKey] ?? 0) + 1;

            $targetRoles = is_array($target['targetRoles'] ?? null)
                ? array_values(array_filter(
                    array_map('strval', $target['targetRoles']),
                    static fn (string $role): bool => $role !== '',
                ))
                : [];
            foreach ($targetRoles as $targetRole) {
                $directoryBaseNames[$caseFoldDirectoryBaseName]['roleCounts'][$targetRole] =
                    ($directoryBaseNames[$caseFoldDirectoryBaseName]['roleCounts'][$targetRole] ?? 0) + 1;
            }

            $this->appendUniqueString($directoryBaseNames[$caseFoldDirectoryBaseName]['targetDirectories'], $targetDirectory);
            $this->appendUniqueString(
                $directoryBaseNames[$caseFoldDirectoryBaseName]['sourceParts'],
                is_string($target['sourcePart'] ?? null) ? $target['sourcePart'] : null,
            );
            $this->appendUniqueString(
                $directoryBaseNames[$caseFoldDirectoryBaseName]['relationshipParts'],
                is_string($target['relationshipsPart'] ?? null) ? $target['relationshipsPart'] : null,
            );
            $this->appendUniqueString(
                $directoryBaseNames[$caseFoldDirectoryBaseName]['relationshipIds'],
                is_string($target['relationshipId'] ?? null) ? $target['relationshipId'] : null,
            );
            $this->appendUniqueString($directoryBaseNames[$caseFoldDirectoryBaseName]['relationshipTypes'], $relationshipType);
            $this->appendUniqueString(
                $directoryBaseNames[$caseFoldDirectoryBaseName]['contentTypes'],
                is_string($target['targetContentType'] ?? null) ? $target['targetContentType'] : null,
            );
            $this->appendUniqueString($directoryBaseNames[$caseFoldDirectoryBaseName]['targetParts'], $targetPart);

            $targetBytes = is_int($target['targetBytes'] ?? null) ? (int) $target['targetBytes'] : null;
            if (
                !$targetExists
                || $targetBytes === null
                || isset($directoryBaseNames[$caseFoldDirectoryBaseName]['_seenExistingTargetParts'][$targetPart])
            ) {
                continue;
            }

            $directoryBaseNames[$caseFoldDirectoryBaseName]['_seenExistingTargetParts'][$targetPart] = true;
            $targetSummary = [
                'partName' => $targetPart,
                'targetPart' => $targetPart,
                'directory' => $targetDirectory,
                'directoryBaseName' => $targetDirectoryBaseName,
                'caseFoldDirectoryBaseName' => $caseFoldDirectoryBaseName,
                'baseName' => is_string($target['targetBaseName'] ?? null)
                    ? $target['targetBaseName']
                    : $this->packagePartBaseName($targetPart),
                'targetPathDepth' => is_int($target['targetPathDepth'] ?? null)
                    ? (int) $target['targetPathDepth']
                    : count($this->packagePartPathSegments($targetPart)),
                'partExtension' => is_string($target['targetPartExtension'] ?? null)
                    ? $target['targetPartExtension']
                    : $this->packagePartExtension($targetPart),
                'bytes' => $targetBytes,
                'targetBytes' => $targetBytes,
                'crc32' => is_string($target['targetCrc32'] ?? null) ? $target['targetCrc32'] : null,
                'sha256' => is_string($target['targetSha256'] ?? null) ? $target['targetSha256'] : null,
                'contentType' => is_string($target['targetContentType'] ?? null) ? $target['targetContentType'] : '',
                'contentTypeBase' => $targetContentTypeBase,
                'contentTypeSource' => $targetContentTypeSource,
                'roles' => $targetRoles,
            ];
            $directoryBaseNames[$caseFoldDirectoryBaseName]['existingTargetByteLength'] += $targetBytes;
            $largestTarget = $directoryBaseNames[$caseFoldDirectoryBaseName]['largestExistingTargetPart'];
            if (
                !is_array($largestTarget)
                || $targetBytes > (int) ($largestTarget['bytes'] ?? 0)
                || (
                    $targetBytes === (int) ($largestTarget['bytes'] ?? 0)
                    && strcmp($targetPart, (string) ($largestTarget['partName'] ?? '')) < 0
                )
            ) {
                $directoryBaseNames[$caseFoldDirectoryBaseName]['largestExistingTargetPart'] = $targetSummary;
            }
        }

        ksort($directoryBaseNames, SORT_STRING);
        foreach ($directoryBaseNames as $caseFoldDirectoryBaseName => $summary) {
            ksort($summary['directoryBaseNameCounts'], SORT_STRING);
            ksort($summary['targetDirectoryCounts'], SORT_STRING);
            ksort($summary['contentTypeSourceCounts'], SORT_STRING);
            ksort($summary['contentTypeBaseCounts'], SORT_STRING);
            ksort($summary['relationshipTypeCounts'], SORT_STRING);
            ksort($summary['roleCounts'], SORT_STRING);
            sort($summary['targetDirectories'], SORT_STRING);
            sort($summary['sourceParts'], SORT_STRING);
            sort($summary['relationshipParts'], SORT_STRING);
            sort($summary['relationshipIds'], SORT_STRING);
            sort($summary['relationshipTypes'], SORT_STRING);
            sort($summary['contentTypes'], SORT_STRING);
            sort($summary['targetParts'], SORT_STRING);
            $summary['directoryBaseNameVariantCount'] = count($summary['directoryBaseNameCounts']);
            $summary['directoryCount'] = count($summary['targetDirectories']);
            unset($summary['_seenExistingTargetParts']);
            $directoryBaseNames[$caseFoldDirectoryBaseName] = $summary;
        }

        return array_values($directoryBaseNames);
    }

    /**
     * @param list<array<string, mixed>> $relationshipTargets
     * @return list<array<string, mixed>>
     */
    private function relationshipTargetPathSegmentSummary(array $relationshipTargets): array
    {
        $segments = [];
        foreach ($relationshipTargets as $target) {
            $targetPart = is_string($target['targetPart'] ?? null) ? $target['targetPart'] : '';
            if ($targetPart === '') {
                continue;
            }

            $pathSegments = is_array($target['targetPathSegments'] ?? null)
                ? array_values(array_filter(
                    array_map(
                        static fn (mixed $segment): string => is_scalar($segment) ? (string) $segment : '',
                        $target['targetPathSegments'],
                    ),
                    static fn (string $segment): bool => $segment !== '',
                ))
                : $this->packagePartPathSegments($targetPart);
            $targetDirectory = is_string($target['targetDirectory'] ?? null)
                ? $target['targetDirectory']
                : $this->packagePartDirectory($targetPart);
            $targetExists = ($target['targetExists'] ?? false) === true;
            $targetContentTypeSource = is_string($target['targetContentTypeSource'] ?? null)
                ? $target['targetContentTypeSource']
                : 'missing';
            if ($targetContentTypeSource === '') {
                $targetContentTypeSource = 'missing';
            }
            $targetContentTypeBase = is_string($target['targetContentTypeBase'] ?? null)
                ? $target['targetContentTypeBase']
                : '';
            $targetContentTypeBaseKey = $targetContentTypeBase === '' ? '(missing)' : $targetContentTypeBase;
            $targetContentType = is_string($target['targetContentType'] ?? null) ? $target['targetContentType'] : '';
            $relationshipType = is_string($target['relationshipType'] ?? null) ? $target['relationshipType'] : '';
            $relationshipTypeKey = is_string($target['relationshipTypeKey'] ?? null)
                ? $target['relationshipTypeKey']
                : ($relationshipType === '' ? '(missing-type)' : $relationshipType);
            $relationshipPart = is_string($target['relationshipsPart'] ?? null) ? $target['relationshipsPart'] : '';
            $relationshipId = is_string($target['relationshipId'] ?? null) ? $target['relationshipId'] : '';
            $sourcePart = is_string($target['sourcePart'] ?? null) ? $target['sourcePart'] : '';
            $targetRoles = array_values(array_filter(
                array_map('strval', $target['targetRoles'] ?? []),
                static fn (string $role): bool => $role !== '',
            ));

            $targetSummary = [
                'targetPart' => $targetPart,
                'targetDirectory' => $targetDirectory,
                'targetBaseName' => is_string($target['targetBaseName'] ?? null)
                    ? $target['targetBaseName']
                    : $this->packagePartBaseName($targetPart),
                'targetPathDepth' => is_int($target['targetPathDepth'] ?? null)
                    ? (int) $target['targetPathDepth']
                    : count($pathSegments),
                'targetPathSegments' => $pathSegments,
                'targetPartExtension' => is_string($target['targetPartExtension'] ?? null)
                    ? $target['targetPartExtension']
                    : $this->packagePartExtension($targetPart),
                'targetBytes' => is_int($target['targetBytes'] ?? null) ? (int) $target['targetBytes'] : null,
                'targetCrc32' => is_string($target['targetCrc32'] ?? null) ? $target['targetCrc32'] : null,
                'targetSha256' => is_string($target['targetSha256'] ?? null) ? $target['targetSha256'] : null,
                'targetContentType' => $targetContentType,
                'targetContentTypeBase' => $targetContentTypeBase,
                'targetContentTypeSource' => $targetContentTypeSource,
                'targetRoles' => $targetRoles,
            ];

            $segmentsSeenInTarget = [];
            foreach ($pathSegments as $pathSegmentIndex => $segment) {
                if (!isset($segments[$segment])) {
                    $segments[$segment] = [
                        'segment' => $segment,
                        'caseFoldSegment' => $this->packagePartCaseFoldKey($segment),
                        'occurrenceCount' => 0,
                        'relationshipCount' => 0,
                        'existingTargetCount' => 0,
                        'missingTargetCount' => 0,
                        'missingContentTypeTargetCount' => 0,
                        'parameterizedTargetCount' => 0,
                        'existingTargetByteLength' => 0,
                        'pathSegmentIndexCounts' => [],
                        'targetDirectoryCounts' => [],
                        'contentTypeSourceCounts' => [],
                        'contentTypeBaseCounts' => [],
                        'relationshipTypeCounts' => [],
                        'roleCounts' => [],
                        'sourceParts' => [],
                        'relationshipParts' => [],
                        'relationshipIds' => [],
                        'relationshipTypes' => [],
                        'contentTypes' => [],
                        'targetParts' => [],
                        'largestExistingTargetPart' => null,
                    ];
                }

                ++$segments[$segment]['occurrenceCount'];
                $segments[$segment]['pathSegmentIndexCounts'][$pathSegmentIndex] =
                    ($segments[$segment]['pathSegmentIndexCounts'][$pathSegmentIndex] ?? 0) + 1;

                if (isset($segmentsSeenInTarget[$segment])) {
                    continue;
                }
                $segmentsSeenInTarget[$segment] = true;

                ++$segments[$segment]['relationshipCount'];
                $segments[$segment]['targetDirectoryCounts'][$targetDirectory] =
                    ($segments[$segment]['targetDirectoryCounts'][$targetDirectory] ?? 0) + 1;
                $segments[$segment]['contentTypeSourceCounts'][$targetContentTypeSource] =
                    ($segments[$segment]['contentTypeSourceCounts'][$targetContentTypeSource] ?? 0) + 1;
                $segments[$segment]['contentTypeBaseCounts'][$targetContentTypeBaseKey] =
                    ($segments[$segment]['contentTypeBaseCounts'][$targetContentTypeBaseKey] ?? 0) + 1;
                $segments[$segment]['relationshipTypeCounts'][$relationshipTypeKey] =
                    ($segments[$segment]['relationshipTypeCounts'][$relationshipTypeKey] ?? 0) + 1;

                if ($targetExists) {
                    ++$segments[$segment]['existingTargetCount'];
                    if (is_int($targetSummary['targetBytes'])) {
                        $segments[$segment]['existingTargetByteLength'] += $targetSummary['targetBytes'];
                        $largestTarget = $segments[$segment]['largestExistingTargetPart'];
                        if (
                            !is_array($largestTarget)
                            || $targetSummary['targetBytes'] > (int) ($largestTarget['targetBytes'] ?? 0)
                            || (
                                $targetSummary['targetBytes'] === (int) ($largestTarget['targetBytes'] ?? 0)
                                && strcmp($targetSummary['targetPart'], (string) ($largestTarget['targetPart'] ?? '')) < 0
                            )
                        ) {
                            $segments[$segment]['largestExistingTargetPart'] = $targetSummary;
                        }
                    }
                } else {
                    ++$segments[$segment]['missingTargetCount'];
                }

                if ($targetContentTypeSource === 'missing') {
                    ++$segments[$segment]['missingContentTypeTargetCount'];
                }
                if (($target['targetContentTypeHasParameters'] ?? false) === true) {
                    ++$segments[$segment]['parameterizedTargetCount'];
                }
                foreach ($targetRoles as $targetRole) {
                    $segments[$segment]['roleCounts'][$targetRole] =
                        ($segments[$segment]['roleCounts'][$targetRole] ?? 0) + 1;
                }

                $this->appendUniqueString($segments[$segment]['sourceParts'], $sourcePart === '' ? null : $sourcePart);
                $this->appendUniqueString($segments[$segment]['relationshipParts'], $relationshipPart === '' ? null : $relationshipPart);
                $this->appendUniqueString($segments[$segment]['relationshipIds'], $relationshipId === '' ? null : $relationshipId);
                $this->appendUniqueString($segments[$segment]['relationshipTypes'], $relationshipType === '' ? null : $relationshipType);
                $this->appendUniqueString($segments[$segment]['contentTypes'], $targetContentType === '' ? null : $targetContentType);
                $this->appendUniqueString($segments[$segment]['targetParts'], $targetPart);
            }
        }

        ksort($segments, SORT_STRING);
        foreach ($segments as $segment => $summary) {
            ksort($summary['pathSegmentIndexCounts'], SORT_NUMERIC);
            ksort($summary['targetDirectoryCounts'], SORT_STRING);
            ksort($summary['contentTypeSourceCounts'], SORT_STRING);
            ksort($summary['contentTypeBaseCounts'], SORT_STRING);
            ksort($summary['relationshipTypeCounts'], SORT_STRING);
            ksort($summary['roleCounts'], SORT_STRING);
            sort($summary['sourceParts'], SORT_STRING);
            sort($summary['relationshipParts'], SORT_STRING);
            sort($summary['relationshipIds'], SORT_STRING);
            sort($summary['relationshipTypes'], SORT_STRING);
            sort($summary['contentTypes'], SORT_STRING);
            sort($summary['targetParts'], SORT_STRING);
            $segments[$segment] = $summary;
        }

        return array_values($segments);
    }

    /**
     * @param list<array<string, mixed>> $relationshipTargets
     * @return list<array<string, mixed>>
     */
    private function relationshipTargetPathSegmentPositionSummary(array $relationshipTargets): array
    {
        $positions = [];
        foreach ($relationshipTargets as $target) {
            $targetPart = is_string($target['targetPart'] ?? null) ? $target['targetPart'] : '';
            if ($targetPart === '') {
                continue;
            }

            $pathSegments = is_array($target['targetPathSegments'] ?? null)
                ? array_values(array_filter(
                    array_map(
                        static fn (mixed $segment): string => is_scalar($segment) ? (string) $segment : '',
                        $target['targetPathSegments'],
                    ),
                    static fn (string $segment): bool => $segment !== '',
                ))
                : $this->packagePartPathSegments($targetPart);
            $reviews = $this->packagePartPathSegmentPositionReviews($pathSegments);
            $targetDirectory = is_string($target['targetDirectory'] ?? null)
                ? $target['targetDirectory']
                : $this->packagePartDirectory($targetPart);
            $targetExists = ($target['targetExists'] ?? false) === true;
            $targetContentTypeSource = is_string($target['targetContentTypeSource'] ?? null)
                ? $target['targetContentTypeSource']
                : 'missing';
            if ($targetContentTypeSource === '') {
                $targetContentTypeSource = 'missing';
            }
            $targetContentTypeBase = is_string($target['targetContentTypeBase'] ?? null)
                ? $target['targetContentTypeBase']
                : '';
            $targetContentTypeBaseKey = $targetContentTypeBase === '' ? '(missing)' : $targetContentTypeBase;
            $targetContentType = is_string($target['targetContentType'] ?? null) ? $target['targetContentType'] : '';
            $relationshipType = is_string($target['relationshipType'] ?? null) ? $target['relationshipType'] : '';
            $relationshipTypeKey = is_string($target['relationshipTypeKey'] ?? null)
                ? $target['relationshipTypeKey']
                : ($relationshipType === '' ? '(missing-type)' : $relationshipType);
            $relationshipPart = is_string($target['relationshipsPart'] ?? null) ? $target['relationshipsPart'] : '';
            $relationshipId = is_string($target['relationshipId'] ?? null) ? $target['relationshipId'] : '';
            $sourcePart = is_string($target['sourcePart'] ?? null) ? $target['sourcePart'] : '';
            $targetRoles = array_values(array_filter(
                array_map('strval', $target['targetRoles'] ?? []),
                static fn (string $role): bool => $role !== '',
            ));

            $targetSummary = [
                'targetPart' => $targetPart,
                'targetDirectory' => $targetDirectory,
                'targetBaseName' => is_string($target['targetBaseName'] ?? null)
                    ? $target['targetBaseName']
                    : $this->packagePartBaseName($targetPart),
                'targetPathDepth' => is_int($target['targetPathDepth'] ?? null)
                    ? (int) $target['targetPathDepth']
                    : count($pathSegments),
                'targetPathSegments' => $pathSegments,
                'targetPartExtension' => is_string($target['targetPartExtension'] ?? null)
                    ? $target['targetPartExtension']
                    : $this->packagePartExtension($targetPart),
                'targetBytes' => is_int($target['targetBytes'] ?? null) ? (int) $target['targetBytes'] : null,
                'targetCrc32' => is_string($target['targetCrc32'] ?? null) ? $target['targetCrc32'] : null,
                'targetSha256' => is_string($target['targetSha256'] ?? null) ? $target['targetSha256'] : null,
                'targetContentType' => $targetContentType,
                'targetContentTypeBase' => $targetContentTypeBase,
                'targetContentTypeSource' => $targetContentTypeSource,
                'targetRoles' => $targetRoles,
            ];

            $positionsSeenInTarget = [];
            foreach ($reviews as $review) {
                $position = is_string($review['position'] ?? null) ? $review['position'] : '';
                $segment = is_string($review['segment'] ?? null) ? $review['segment'] : '';
                if ($position === '' || $segment === '') {
                    continue;
                }

                $pathSegmentIndex = (int) ($review['pathSegmentIndex'] ?? 0);
                if (!isset($positions[$position])) {
                    $positions[$position] = [
                        'position' => $position,
                        'occurrenceCount' => 0,
                        'relationshipCount' => 0,
                        'existingTargetCount' => 0,
                        'missingTargetCount' => 0,
                        'missingContentTypeTargetCount' => 0,
                        'parameterizedTargetCount' => 0,
                        'existingTargetByteLength' => 0,
                        'uniqueSegmentCount' => 0,
                        'segmentCounts' => [],
                        'segments' => [],
                        'pathSegmentIndexCounts' => [],
                        'targetDirectoryCounts' => [],
                        'contentTypeSourceCounts' => [],
                        'contentTypeBaseCounts' => [],
                        'relationshipTypeCounts' => [],
                        'roleCounts' => [],
                        'sourceParts' => [],
                        'relationshipParts' => [],
                        'relationshipIds' => [],
                        'relationshipTypes' => [],
                        'contentTypes' => [],
                        'targetParts' => [],
                        'largestExistingTargetPart' => null,
                    ];
                }

                ++$positions[$position]['occurrenceCount'];
                $positions[$position]['segmentCounts'][$segment] =
                    ($positions[$position]['segmentCounts'][$segment] ?? 0) + 1;
                $this->appendUniqueString($positions[$position]['segments'], $segment);
                $positions[$position]['pathSegmentIndexCounts'][$pathSegmentIndex] =
                    ($positions[$position]['pathSegmentIndexCounts'][$pathSegmentIndex] ?? 0) + 1;

                if (isset($positionsSeenInTarget[$position])) {
                    continue;
                }

                $positionsSeenInTarget[$position] = true;
                ++$positions[$position]['relationshipCount'];
                $positions[$position]['targetDirectoryCounts'][$targetDirectory] =
                    ($positions[$position]['targetDirectoryCounts'][$targetDirectory] ?? 0) + 1;
                $positions[$position]['contentTypeSourceCounts'][$targetContentTypeSource] =
                    ($positions[$position]['contentTypeSourceCounts'][$targetContentTypeSource] ?? 0) + 1;
                $positions[$position]['contentTypeBaseCounts'][$targetContentTypeBaseKey] =
                    ($positions[$position]['contentTypeBaseCounts'][$targetContentTypeBaseKey] ?? 0) + 1;
                $positions[$position]['relationshipTypeCounts'][$relationshipTypeKey] =
                    ($positions[$position]['relationshipTypeCounts'][$relationshipTypeKey] ?? 0) + 1;
                $this->appendUniqueString($positions[$position]['targetParts'], $targetPart);

                if ($targetExists) {
                    ++$positions[$position]['existingTargetCount'];
                    if (is_int($targetSummary['targetBytes'])) {
                        $positions[$position]['existingTargetByteLength'] += $targetSummary['targetBytes'];
                        $largestTarget = $positions[$position]['largestExistingTargetPart'];
                        if (
                            !is_array($largestTarget)
                            || $targetSummary['targetBytes'] > (int) ($largestTarget['targetBytes'] ?? 0)
                            || (
                                $targetSummary['targetBytes'] === (int) ($largestTarget['targetBytes'] ?? 0)
                                && strcmp($targetSummary['targetPart'], (string) ($largestTarget['targetPart'] ?? '')) < 0
                            )
                        ) {
                            $positions[$position]['largestExistingTargetPart'] = $targetSummary;
                        }
                    }
                } else {
                    ++$positions[$position]['missingTargetCount'];
                }

                if ($targetContentTypeSource === 'missing') {
                    ++$positions[$position]['missingContentTypeTargetCount'];
                }
                if (($target['targetContentTypeHasParameters'] ?? false) === true) {
                    ++$positions[$position]['parameterizedTargetCount'];
                }
                foreach ($targetRoles as $targetRole) {
                    $positions[$position]['roleCounts'][$targetRole] =
                        ($positions[$position]['roleCounts'][$targetRole] ?? 0) + 1;
                }

                $this->appendUniqueString($positions[$position]['sourceParts'], $sourcePart === '' ? null : $sourcePart);
                $this->appendUniqueString($positions[$position]['relationshipParts'], $relationshipPart === '' ? null : $relationshipPart);
                $this->appendUniqueString($positions[$position]['relationshipIds'], $relationshipId === '' ? null : $relationshipId);
                $this->appendUniqueString($positions[$position]['relationshipTypes'], $relationshipType === '' ? null : $relationshipType);
                $this->appendUniqueString($positions[$position]['contentTypes'], $targetContentType === '' ? null : $targetContentType);
            }
        }

        ksort($positions, SORT_STRING);
        foreach ($positions as $position => $summary) {
            sort($summary['segments'], SORT_STRING);
            sort($summary['sourceParts'], SORT_STRING);
            sort($summary['relationshipParts'], SORT_STRING);
            sort($summary['relationshipIds'], SORT_STRING);
            sort($summary['relationshipTypes'], SORT_STRING);
            sort($summary['contentTypes'], SORT_STRING);
            sort($summary['targetParts'], SORT_STRING);
            ksort($summary['segmentCounts'], SORT_STRING);
            ksort($summary['pathSegmentIndexCounts'], SORT_NUMERIC);
            ksort($summary['targetDirectoryCounts'], SORT_STRING);
            ksort($summary['contentTypeSourceCounts'], SORT_STRING);
            ksort($summary['contentTypeBaseCounts'], SORT_STRING);
            ksort($summary['relationshipTypeCounts'], SORT_STRING);
            ksort($summary['roleCounts'], SORT_STRING);
            $summary['uniqueSegmentCount'] = count($summary['segments']);
            $positions[$position] = $summary;
        }

        return array_values($positions);
    }

    /**
     * @param list<array<string, mixed>> $relationshipSources
     * @return list<array<string, mixed>>
     */
    private function relationshipSourceDirectoryDepthSummary(array $relationshipSources): array
    {
        $depths = [];
        foreach ($relationshipSources as $source) {
            $depth = is_int($source['sourceDirectoryDepth'] ?? null) ? (int) $source['sourceDirectoryDepth'] : null;
            $depthKey = $depth === null ? '(invalid-source)' : (string) $depth;
            if (!isset($depths[$depthKey])) {
                $depths[$depthKey] = [
                    'sourceDirectoryDepthKey' => $depthKey,
                    'sourceDirectoryDepth' => $depth,
                    'sourceCount' => 0,
                    'existingSourceCount' => 0,
                    'nonExistingSourceCount' => 0,
