            $depths[$pathSegmentCount]['directories'][$directory] = true;
            $depths[$pathSegmentCount]['partNames'][] = $partName;
            if (($part['isRelationshipPart'] ?? false) === true) {
                ++$depths[$pathSegmentCount]['relationshipPartCount'];
