            $depths[$pathSegmentCount]['contentTypeBaseCounts'][$contentTypeBaseKey] =
                ($depths[$pathSegmentCount]['contentTypeBaseCounts'][$contentTypeBaseKey] ?? 0) + 1;

            foreach (($part['roles'] ?? []) as $role) {
                $role = (string) $role;
                $depths[$pathSegmentCount]['roleCounts'][$role] =
                    ($depths[$pathSegmentCount]['roleCounts'][$role] ?? 0) + 1;
            }

            $largestPart = $depths[$pathSegmentCount]['largestPart'];
            if (
                !is_array($largestPart)
                || $partSummary['bytes'] > (int) ($largestPart['bytes'] ?? 0)
                || (
                    $partSummary['bytes'] === (int) ($largestPart['bytes'] ?? 0)
                    && strcmp($partSummary['partName'], (string) ($largestPart['partName'] ?? '')) < 0
                )
            ) {
                $depths[$pathSegmentCount]['largestPart'] = $partSummary;
            }
        }

        ksort($depths, SORT_NUMERIC);
        foreach ($depths as $depth => $summary) {
            $directories = array_keys($summary['directories']);
            sort($directories, SORT_STRING);
            sort($summary['partNames'], SORT_STRING);
            ksort($summary['contentTypeSourceCounts'], SORT_STRING);
            ksort($summary['contentTypeBaseCounts'], SORT_STRING);
            ksort($summary['roleCounts'], SORT_STRING);
            $summary['directories'] = $directories;
            $depths[$depth] = $summary;
        }

        return array_values($depths);
    }

    /**
     * @param array<string, array<string, mixed>> $partInventory
     * @return list<array<string, mixed>>
     */
    private function packagePartExtensionSummary(array $partInventory): array
    {
        $extensions = [];
        foreach ($partInventory as $partName => $part) {
            $extension = is_string($part['partExtension'] ?? null) ? $part['partExtension'] : null;
            $key = $extension ?? '';
            if (!isset($extensions[$key])) {
                $extensions[$key] = [
                    'extension' => $extension,
                    'defaultDeclared' => (bool) ($part['partExtensionDefaultDeclared'] ?? false),
                    'defaultContentType' => $part['partExtensionDefaultContentType'] ?? null,
                    'partCount' => 0,
                    'byteLength' => 0,
                    'relationshipPartCount' => 0,
                    'missingContentTypePartCount' => 0,
                    'parameterizedPartCount' => 0,
                    'contentTypeSourceCounts' => [],
                    'contentTypeBaseCounts' => [],
                    'roleCounts' => [],
                    'partNames' => [],
                    'largestPart' => null,
                ];
            }

            ++$extensions[$key]['partCount'];
            $bytes = (int) ($part['bytes'] ?? 0);
            $extensions[$key]['byteLength'] += $bytes;
            $extensions[$key]['partNames'][] = (string) $partName;
            if (($part['isRelationshipPart'] ?? false) === true) {
                ++$extensions[$key]['relationshipPartCount'];
            }

            $contentTypeSource = (string) ($part['contentTypeSource'] ?? 'missing');
            if ($contentTypeSource === 'missing') {
                ++$extensions[$key]['missingContentTypePartCount'];
            }
            $extensions[$key]['contentTypeSourceCounts'][$contentTypeSource] =
                ($extensions[$key]['contentTypeSourceCounts'][$contentTypeSource] ?? 0) + 1;
            if (($part['contentTypeHasParameters'] ?? false) === true) {
                ++$extensions[$key]['parameterizedPartCount'];
            }
            $contentTypeBase = is_string($part['contentTypeBase'] ?? null) ? $part['contentTypeBase'] : '';
            $contentTypeBaseKey = $contentTypeBase === '' ? '(missing)' : $contentTypeBase;
            $extensions[$key]['contentTypeBaseCounts'][$contentTypeBaseKey] =
                ($extensions[$key]['contentTypeBaseCounts'][$contentTypeBaseKey] ?? 0) + 1;

            foreach (($part['roles'] ?? []) as $role) {
                $role = (string) $role;
                $extensions[$key]['roleCounts'][$role] =
                    ($extensions[$key]['roleCounts'][$role] ?? 0) + 1;
            }

            $partSummary = [
                'partName' => (string) ($part['partName'] ?? $partName),
                'directory' => is_string($part['directory'] ?? null) ? $part['directory'] : $this->packagePartDirectory((string) $partName),
                'baseName' => is_string($part['baseName'] ?? null) ? $part['baseName'] : $this->packagePartBaseName((string) $partName),
                'bytes' => $bytes,
                'crc32' => is_string($part['crc32'] ?? null) ? $part['crc32'] : null,
                'sha256' => is_string($part['sha256'] ?? null) ? $part['sha256'] : null,
                'contentType' => is_string($part['contentType'] ?? null) ? $part['contentType'] : '',
                'contentTypeBase' => $contentTypeBase,
                'contentTypeSource' => $contentTypeSource,
                'defaultExtension' => is_string($part['defaultExtension'] ?? null) ? $part['defaultExtension'] : null,
                'overridePartName' => is_string($part['overridePartName'] ?? null) ? $part['overridePartName'] : null,
                'isRelationshipPart' => (bool) ($part['isRelationshipPart'] ?? false),
                'roles' => array_values(array_map('strval', $part['roles'] ?? [])),
            ];
            $largestPart = $extensions[$key]['largestPart'];
            if (
                !is_array($largestPart)
                || $partSummary['bytes'] > (int) ($largestPart['bytes'] ?? 0)
                || (
                    $partSummary['bytes'] === (int) ($largestPart['bytes'] ?? 0)
                    && strcmp($partSummary['partName'], (string) ($largestPart['partName'] ?? '')) < 0
                )
            ) {
                $extensions[$key]['largestPart'] = $partSummary;
            }
        }

        ksort($extensions, SORT_STRING);
        foreach ($extensions as $extension => $summary) {
            ksort($summary['contentTypeSourceCounts'], SORT_STRING);
            ksort($summary['contentTypeBaseCounts'], SORT_STRING);
            ksort($summary['roleCounts'], SORT_STRING);
            $extensions[$extension] = $summary;
        }

        return array_values($extensions);
    }

    /**
     * @param array<string, array<string, mixed>> $partInventory
     * @return array{count:int, issueCodes:list<string>, partNames:list<string>, extensionCounts:array<string, int>, contentTypeBaseCounts:array<string, int>, contentTypeSourceCounts:array<string, int>, items:list<array<string, mixed>>}
     */
    private function packagePartContentTypeExtensionMismatchSummary(array $partInventory): array
    {
        $items = [];
        $issueCodes = [];
        $partNames = [];
        $extensionCounts = [];
        $contentTypeBaseCounts = [];
        $contentTypeSourceCounts = [];

        foreach ($partInventory as $partName => $part) {
            $contentTypeBase = is_string($part['contentTypeBase'] ?? null) ? $part['contentTypeBase'] : '';
            $expectedExtensions = $this->expectedPackagePartExtensionsForContentType($contentTypeBase);
            if ($expectedExtensions === []) {
                continue;
            }

            $partExtension = is_string($part['partExtension'] ?? null) ? $part['partExtension'] : null;
            if ($partExtension !== null && in_array($partExtension, $expectedExtensions, true)) {
                continue;
            }

            $issues = ['content-type-extension-mismatch'];
            if ($partExtension === null) {
                $issues[] = 'missing-part-extension-for-content-type';
            }

            $contentTypeSource = is_string($part['contentTypeSource'] ?? null)
                ? $part['contentTypeSource']
                : 'missing';
            if ($contentTypeSource === '') {
                $contentTypeSource = 'missing';
            }
            $extensionKey = $partExtension ?? '(none)';
            $contentTypeBaseKey = $contentTypeBase === '' ? '(missing)' : $contentTypeBase;

            $partNames[] = (string) ($part['partName'] ?? $partName);
            $extensionCounts[$extensionKey] = ($extensionCounts[$extensionKey] ?? 0) + 1;
            $contentTypeBaseCounts[$contentTypeBaseKey] = ($contentTypeBaseCounts[$contentTypeBaseKey] ?? 0) + 1;
            $contentTypeSourceCounts[$contentTypeSource] = ($contentTypeSourceCounts[$contentTypeSource] ?? 0) + 1;
            foreach ($issues as $issue) {
                $issueCodes[$issue] = true;
            }

            $items[] = [
                'partName' => (string) ($part['partName'] ?? $partName),
                'directory' => is_string($part['directory'] ?? null)
                    ? $part['directory']
                    : $this->packagePartDirectory((string) $partName),
                'baseName' => is_string($part['baseName'] ?? null)
                    ? $part['baseName']
                    : $this->packagePartBaseName((string) $partName),
                'partExtension' => $partExtension,
                'expectedExtensions' => $expectedExtensions,
                'bytes' => (int) ($part['bytes'] ?? 0),
                'crc32' => is_string($part['crc32'] ?? null) ? $part['crc32'] : null,
                'sha256' => is_string($part['sha256'] ?? null) ? $part['sha256'] : null,
                'contentType' => is_string($part['contentType'] ?? null) ? $part['contentType'] : '',
                'contentTypeBase' => $contentTypeBase,
                'contentTypeSource' => $contentTypeSource,
                'defaultExtension' => is_string($part['defaultExtension'] ?? null) ? $part['defaultExtension'] : null,
                'overridePartName' => is_string($part['overridePartName'] ?? null) ? $part['overridePartName'] : null,
                'roles' => array_values(array_map('strval', $part['roles'] ?? [])),
                'issues' => $issues,
                'byteExposurePolicy' => 'docx-package-part-bytes-blocked',
                'reviewPolicy' => 'content-type-extension-mismatch-metadata-only',
            ];
        }

        sort($partNames, SORT_STRING);
        ksort($issueCodes, SORT_STRING);
        ksort($extensionCounts, SORT_STRING);
        ksort($contentTypeBaseCounts, SORT_STRING);
        ksort($contentTypeSourceCounts, SORT_STRING);
        usort(
            $items,
            static fn (array $left, array $right): int => strcmp((string) $left['partName'], (string) $right['partName']),
        );

        return [
            'count' => count($items),
            'issueCodes' => array_keys($issueCodes),
            'partNames' => $partNames,
            'extensionCounts' => $extensionCounts,
            'contentTypeBaseCounts' => $contentTypeBaseCounts,
            'contentTypeSourceCounts' => $contentTypeSourceCounts,
            'items' => $items,
        ];
    }

    /**
     * @return list<string>
     */
    private function expectedPackagePartExtensionsForContentType(string $contentTypeBase): array
    {
        if ($contentTypeBase === '') {
            return [];
        }

        if ($contentTypeBase === self::CT_PACKAGE_RELATIONSHIPS) {
            return ['rels'];
        }

        if (str_starts_with($contentTypeBase, 'image/')) {
            $subtype = substr($contentTypeBase, strlen('image/'));

            return match ($subtype) {
                'jpeg', 'pjpeg' => ['jpeg', 'jpg'],
                'png' => ['png'],
                'gif' => ['gif'],
                'bmp' => ['bmp'],
                'tiff' => ['tif', 'tiff'],
                'svg+xml' => ['svg'],
                default => [],
            };
        }

        if ($contentTypeBase === 'application/xml' || $contentTypeBase === 'text/xml' || str_ends_with($contentTypeBase, '+xml')) {
            return ['xml'];
        }

        return match ($contentTypeBase) {
            self::CT_ACTIVEX_BINARY,
            self::CT_VBA_PROJECT,
            self::CT_VBA_PROJECT_SIGNATURE => ['bin'],
            default => [],
        };
    }

    /**
     * @param array<string, array<string, mixed>> $partInventory
     * @return list<array<string, mixed>>
     */
    private function packagePartExtensionCaseVariantSummary(array $partInventory): array
    {
        $variantExtensions = [];
        foreach ($partInventory as $partName => $part) {
            $extension = is_string($part['partExtension'] ?? null) ? $part['partExtension'] : null;
            $rawExtension = is_string($part['rawPartExtension'] ?? null) ? $part['rawPartExtension'] : null;
            if ($extension === null || $rawExtension === null) {
                continue;
            }

            $hasUppercase = (bool) ($part['partExtensionHasUppercase'] ?? preg_match('/[A-Z]/', $rawExtension) === 1);
            if ($hasUppercase || $rawExtension !== $extension) {
                $variantExtensions[$extension] = true;
            }
        }

        $extensions = [];
        foreach ($partInventory as $partName => $part) {
            $extension = is_string($part['partExtension'] ?? null) ? $part['partExtension'] : null;
            $rawExtension = is_string($part['rawPartExtension'] ?? null) ? $part['rawPartExtension'] : null;
            if ($extension === null || $rawExtension === null) {
                continue;
            }

            $hasUppercase = (bool) ($part['partExtensionHasUppercase'] ?? preg_match('/[A-Z]/', $rawExtension) === 1);
            if (!isset($variantExtensions[$extension])) {
                continue;
            }

            if (!isset($extensions[$extension])) {
                $extensions[$extension] = [
                    'extension' => $extension,
                    'partCount' => 0,
                    'uppercasePartCount' => 0,
                    'byteLength' => 0,
                    'rawExtensionCounts' => [],
                    'rawExtensionPartNames' => [],
                    'contentTypeSourceCounts' => [],
                    'contentTypeBaseCounts' => [],
                    'roleCounts' => [],
                    'partNames' => [],
                    'largestPart' => null,
                ];
            }

            ++$extensions[$extension]['partCount'];
            if ($hasUppercase) {
                ++$extensions[$extension]['uppercasePartCount'];
            }
            $bytes = (int) ($part['bytes'] ?? 0);
            $extensions[$extension]['byteLength'] += $bytes;
            $extensions[$extension]['rawExtensionCounts'][$rawExtension] =
                ($extensions[$extension]['rawExtensionCounts'][$rawExtension] ?? 0) + 1;
            $extensions[$extension]['rawExtensionPartNames'][$rawExtension][] = (string) ($part['partName'] ?? $partName);
            $extensions[$extension]['partNames'][] = (string) ($part['partName'] ?? $partName);

            $contentTypeSource = is_string($part['contentTypeSource'] ?? null)
                ? $part['contentTypeSource']
                : 'missing';
            if ($contentTypeSource === '') {
                $contentTypeSource = 'missing';
            }
            $extensions[$extension]['contentTypeSourceCounts'][$contentTypeSource] =
                ($extensions[$extension]['contentTypeSourceCounts'][$contentTypeSource] ?? 0) + 1;

            $contentTypeBase = is_string($part['contentTypeBase'] ?? null) ? $part['contentTypeBase'] : '';
            $contentTypeBaseKey = $contentTypeBase === '' ? '(missing)' : $contentTypeBase;
            $extensions[$extension]['contentTypeBaseCounts'][$contentTypeBaseKey] =
                ($extensions[$extension]['contentTypeBaseCounts'][$contentTypeBaseKey] ?? 0) + 1;

            foreach (($part['roles'] ?? []) as $role) {
                $role = (string) $role;
                $extensions[$extension]['roleCounts'][$role] =
                    ($extensions[$extension]['roleCounts'][$role] ?? 0) + 1;
            }

            $partSummary = [
                'partName' => (string) ($part['partName'] ?? $partName),
                'directory' => is_string($part['directory'] ?? null)
                    ? $part['directory']
                    : $this->packagePartDirectory((string) $partName),
                'baseName' => is_string($part['baseName'] ?? null)
                    ? $part['baseName']
                    : $this->packagePartBaseName((string) $partName),
                'partExtension' => $extension,
                'rawPartExtension' => $rawExtension,
                'bytes' => $bytes,
                'crc32' => is_string($part['crc32'] ?? null) ? $part['crc32'] : null,
                'sha256' => is_string($part['sha256'] ?? null) ? $part['sha256'] : null,
                'contentTypeBase' => $contentTypeBase,
                'contentTypeSource' => $contentTypeSource,
                'roles' => array_values(array_map('strval', $part['roles'] ?? [])),
            ];
            $largestPart = $extensions[$extension]['largestPart'];
            if (
                !is_array($largestPart)
                || $partSummary['bytes'] > (int) ($largestPart['bytes'] ?? 0)
                || (
                    $partSummary['bytes'] === (int) ($largestPart['bytes'] ?? 0)
                    && strcmp($partSummary['partName'], (string) ($largestPart['partName'] ?? '')) < 0
                )
            ) {
                $extensions[$extension]['largestPart'] = $partSummary;
            }
        }

        ksort($extensions, SORT_STRING);
        foreach ($extensions as $extension => $summary) {
            sort($summary['partNames'], SORT_STRING);
            ksort($summary['rawExtensionCounts'], SORT_STRING);
            ksort($summary['rawExtensionPartNames'], SORT_STRING);
            foreach ($summary['rawExtensionPartNames'] as &$partNames) {
                sort($partNames, SORT_STRING);
            }
            unset($partNames);
            ksort($summary['contentTypeSourceCounts'], SORT_STRING);
            ksort($summary['contentTypeBaseCounts'], SORT_STRING);
            ksort($summary['roleCounts'], SORT_STRING);
            $extensions[$extension] = $summary;
        }

        return array_values($extensions);
    }

    /**
     * @param array<string, array<string, mixed>> $partInventory
     * @return list<array<string, mixed>>
     */
    private function packagePartBaseNameSummary(array $partInventory): array
    {
        $baseNames = [];
        foreach ($partInventory as $partName => $part) {
            $baseName = is_string($part['baseName'] ?? null)
                ? $part['baseName']
                : $this->packagePartBaseName((string) $partName);
            if (!isset($baseNames[$baseName])) {
                $baseNames[$baseName] = [
                    'baseName' => $baseName,
                    'partCount' => 0,
                    'byteLength' => 0,
                    'relationshipPartCount' => 0,
                    'missingContentTypePartCount' => 0,
                    'contentTypeSourceCounts' => [],
                    'contentTypeBaseCounts' => [],
                    'roleCounts' => [],
                    'directories' => [],
                    'partNames' => [],
                    'largestPart' => null,
                ];
            }

            ++$baseNames[$baseName]['partCount'];
            $bytes = (int) ($part['bytes'] ?? 0);
            $baseNames[$baseName]['byteLength'] += $bytes;
            $baseNames[$baseName]['partNames'][] = (string) $partName;
            $this->appendUniqueString(
                $baseNames[$baseName]['directories'],
                is_string($part['directory'] ?? null) ? $part['directory'] : $this->packagePartDirectory((string) $partName),
            );
            if (($part['isRelationshipPart'] ?? false) === true) {
                ++$baseNames[$baseName]['relationshipPartCount'];
            }

            $contentTypeSource = (string) ($part['contentTypeSource'] ?? 'missing');
            if ($contentTypeSource === 'missing') {
                ++$baseNames[$baseName]['missingContentTypePartCount'];
            }
            $baseNames[$baseName]['contentTypeSourceCounts'][$contentTypeSource] =
                ($baseNames[$baseName]['contentTypeSourceCounts'][$contentTypeSource] ?? 0) + 1;

            $contentTypeBase = is_string($part['contentTypeBase'] ?? null) ? $part['contentTypeBase'] : '';
            $contentTypeBaseKey = $contentTypeBase === '' ? '(missing)' : $contentTypeBase;
            $baseNames[$baseName]['contentTypeBaseCounts'][$contentTypeBaseKey] =
                ($baseNames[$baseName]['contentTypeBaseCounts'][$contentTypeBaseKey] ?? 0) + 1;

            foreach (($part['roles'] ?? []) as $role) {
                $role = (string) $role;
                $baseNames[$baseName]['roleCounts'][$role] =
                    ($baseNames[$baseName]['roleCounts'][$role] ?? 0) + 1;
            }

            $partSummary = [
                'partName' => (string) ($part['partName'] ?? $partName),
                'directory' => is_string($part['directory'] ?? null) ? $part['directory'] : $this->packagePartDirectory((string) $partName),
                'bytes' => $bytes,
                'crc32' => is_string($part['crc32'] ?? null) ? $part['crc32'] : null,
                'sha256' => is_string($part['sha256'] ?? null) ? $part['sha256'] : null,
                'contentTypeBase' => $contentTypeBase,
                'contentTypeSource' => $contentTypeSource,
                'roles' => array_values(array_map('strval', $part['roles'] ?? [])),
            ];
            $largestPart = $baseNames[$baseName]['largestPart'];
            if (
                !is_array($largestPart)
                || $partSummary['bytes'] > (int) ($largestPart['bytes'] ?? 0)
                || (
                    $partSummary['bytes'] === (int) ($largestPart['bytes'] ?? 0)
                    && strcmp($partSummary['partName'], (string) ($largestPart['partName'] ?? '')) < 0
                )
            ) {
                $baseNames[$baseName]['largestPart'] = $partSummary;
            }
        }

        ksort($baseNames, SORT_STRING);
        foreach ($baseNames as $baseName => $summary) {
            ksort($summary['contentTypeSourceCounts'], SORT_STRING);
            ksort($summary['contentTypeBaseCounts'], SORT_STRING);
            ksort($summary['roleCounts'], SORT_STRING);
            sort($summary['directories'], SORT_STRING);
            $baseNames[$baseName] = $summary;
        }

        return array_values($baseNames);
    }

