    /**
     * @param array<string, array<string, mixed>> $partInventory
     * @return list<array<string, mixed>>
     */
    private function packagePartCaseFoldPathSummary(array $partInventory): array
    {
        $paths = [];
        foreach ($partInventory as $partName => $part) {
            $partName = (string) ($part['partName'] ?? $partName);
            $caseFoldPartName = is_string($part['caseFoldPartName'] ?? null)
                ? $part['caseFoldPartName']
                : $this->packagePartCaseFoldKey($partName);
            if (!isset($paths[$caseFoldPartName])) {
                $paths[$caseFoldPartName] = [
                    'caseFoldPartName' => $caseFoldPartName,
                    'partCount' => 0,
                    'byteLength' => 0,
                    'caseVariantCount' => 0,
                    'relationshipPartCount' => 0,
                    'missingContentTypePartCount' => 0,
                    'parameterizedPartCount' => 0,
                    'partNameCounts' => [],
                    'contentTypeSourceCounts' => [],
                    'contentTypeBaseCounts' => [],
                    'roleCounts' => [],
                    'directories' => [],
                    'baseNames' => [],
                    'partNames' => [],
                    'largestPart' => null,
                ];
            }

            ++$paths[$caseFoldPartName]['partCount'];
            $bytes = (int) ($part['bytes'] ?? 0);
            $paths[$caseFoldPartName]['byteLength'] += $bytes;
            $paths[$caseFoldPartName]['partNameCounts'][$partName] =
                ($paths[$caseFoldPartName]['partNameCounts'][$partName] ?? 0) + 1;
            $paths[$caseFoldPartName]['partNames'][] = $partName;

            $directory = is_string($part['directory'] ?? null)
                ? $part['directory']
                : $this->packagePartDirectory($partName);
            $baseName = is_string($part['baseName'] ?? null)
                ? $part['baseName']
                : $this->packagePartBaseName($partName);
            $this->appendUniqueString($paths[$caseFoldPartName]['directories'], $directory);
            $this->appendUniqueString($paths[$caseFoldPartName]['baseNames'], $baseName);

            if (($part['isRelationshipPart'] ?? false) === true) {
                ++$paths[$caseFoldPartName]['relationshipPartCount'];
            }
            if (($part['contentTypeHasParameters'] ?? false) === true) {
                ++$paths[$caseFoldPartName]['parameterizedPartCount'];
            }

            $contentTypeSource = is_string($part['contentTypeSource'] ?? null)
                ? $part['contentTypeSource']
                : 'missing';
            if ($contentTypeSource === '') {
                $contentTypeSource = 'missing';
            }
            if ($contentTypeSource === 'missing') {
                ++$paths[$caseFoldPartName]['missingContentTypePartCount'];
            }
            $paths[$caseFoldPartName]['contentTypeSourceCounts'][$contentTypeSource] =
                ($paths[$caseFoldPartName]['contentTypeSourceCounts'][$contentTypeSource] ?? 0) + 1;

            $contentTypeBase = is_string($part['contentTypeBase'] ?? null)
                ? $part['contentTypeBase']
                : '';
            $contentTypeBaseKey = $contentTypeBase === '' ? '(missing)' : $contentTypeBase;
            $paths[$caseFoldPartName]['contentTypeBaseCounts'][$contentTypeBaseKey] =
                ($paths[$caseFoldPartName]['contentTypeBaseCounts'][$contentTypeBaseKey] ?? 0) + 1;

            foreach (($part['roles'] ?? []) as $role) {
                $role = (string) $role;
                if ($role === '') {
                    continue;
                }

                $paths[$caseFoldPartName]['roleCounts'][$role] =
                    ($paths[$caseFoldPartName]['roleCounts'][$role] ?? 0) + 1;
            }

            $partSummary = [
                'partName' => $partName,
                'caseFoldPartName' => $caseFoldPartName,
                'directory' => $directory,
                'baseName' => $baseName,
                'partExtension' => is_string($part['partExtension'] ?? null) ? $part['partExtension'] : null,
                'bytes' => $bytes,
                'crc32' => is_string($part['crc32'] ?? null) ? $part['crc32'] : null,
                'sha256' => is_string($part['sha256'] ?? null) ? $part['sha256'] : null,
                'contentType' => is_string($part['contentType'] ?? null) ? $part['contentType'] : '',
                'contentTypeBase' => $contentTypeBase,
                'contentTypeSource' => $contentTypeSource,
                'isRelationshipPart' => (bool) ($part['isRelationshipPart'] ?? false),
                'roles' => array_values(array_map('strval', $part['roles'] ?? [])),
            ];
            $largestPart = $paths[$caseFoldPartName]['largestPart'];
            if (
                !is_array($largestPart)
                || $partSummary['bytes'] > (int) ($largestPart['bytes'] ?? 0)
                || (
                    $partSummary['bytes'] === (int) ($largestPart['bytes'] ?? 0)
                    && strcmp($partSummary['partName'], (string) ($largestPart['partName'] ?? '')) < 0
                )
            ) {
                $paths[$caseFoldPartName]['largestPart'] = $partSummary;
            }
        }

        ksort($paths, SORT_STRING);
        foreach ($paths as $caseFoldPartName => $summary) {
            sort($summary['directories'], SORT_STRING);
            sort($summary['baseNames'], SORT_STRING);
            sort($summary['partNames'], SORT_STRING);
            ksort($summary['partNameCounts'], SORT_STRING);
            ksort($summary['contentTypeSourceCounts'], SORT_STRING);
            ksort($summary['contentTypeBaseCounts'], SORT_STRING);
            ksort($summary['roleCounts'], SORT_STRING);
            $summary['caseVariantCount'] = count($summary['partNameCounts']);
            $paths[$caseFoldPartName] = $summary;
        }

        return array_values($paths);
    }

    /**
     * @param array<string, array<string, mixed>> $partInventory
     * @return list<array<string, mixed>>
     */
    private function packagePartCaseFoldBaseNameSummary(array $partInventory): array
    {
        $baseNames = [];
        foreach ($partInventory as $partName => $part) {
            $baseName = is_string($part['baseName'] ?? null)
                ? $part['baseName']
                : $this->packagePartBaseName((string) $partName);
            $caseFoldBaseName = is_string($part['caseFoldBaseName'] ?? null)
                ? $part['caseFoldBaseName']
                : $this->packagePartCaseFoldKey($baseName);
            if (!isset($baseNames[$caseFoldBaseName])) {
                $baseNames[$caseFoldBaseName] = [
                    'caseFoldBaseName' => $caseFoldBaseName,
                    'partCount' => 0,
                    'byteLength' => 0,
                    'caseVariantCount' => 0,
                    'relationshipPartCount' => 0,
                    'missingContentTypePartCount' => 0,
                    'baseNameCounts' => [],
                    'contentTypeSourceCounts' => [],
                    'contentTypeBaseCounts' => [],
                    'roleCounts' => [],
                    'directories' => [],
                    'partNames' => [],
                    'largestPart' => null,
                ];
            }

            ++$baseNames[$caseFoldBaseName]['partCount'];
            $bytes = (int) ($part['bytes'] ?? 0);
            $baseNames[$caseFoldBaseName]['byteLength'] += $bytes;
            $baseNames[$caseFoldBaseName]['partNames'][] = (string) $partName;
            $baseNames[$caseFoldBaseName]['baseNameCounts'][$baseName] =
                ($baseNames[$caseFoldBaseName]['baseNameCounts'][$baseName] ?? 0) + 1;
            $this->appendUniqueString(
                $baseNames[$caseFoldBaseName]['directories'],
                is_string($part['directory'] ?? null) ? $part['directory'] : $this->packagePartDirectory((string) $partName),
            );
            if (($part['isRelationshipPart'] ?? false) === true) {
                ++$baseNames[$caseFoldBaseName]['relationshipPartCount'];
            }

            $contentTypeSource = (string) ($part['contentTypeSource'] ?? 'missing');
            if ($contentTypeSource === 'missing') {
                ++$baseNames[$caseFoldBaseName]['missingContentTypePartCount'];
            }
            $baseNames[$caseFoldBaseName]['contentTypeSourceCounts'][$contentTypeSource] =
                ($baseNames[$caseFoldBaseName]['contentTypeSourceCounts'][$contentTypeSource] ?? 0) + 1;

            $contentTypeBase = is_string($part['contentTypeBase'] ?? null) ? $part['contentTypeBase'] : '';
            $contentTypeBaseKey = $contentTypeBase === '' ? '(missing)' : $contentTypeBase;
            $baseNames[$caseFoldBaseName]['contentTypeBaseCounts'][$contentTypeBaseKey] =
                ($baseNames[$caseFoldBaseName]['contentTypeBaseCounts'][$contentTypeBaseKey] ?? 0) + 1;

            foreach (($part['roles'] ?? []) as $role) {
                $role = (string) $role;
                $baseNames[$caseFoldBaseName]['roleCounts'][$role] =
                    ($baseNames[$caseFoldBaseName]['roleCounts'][$role] ?? 0) + 1;
            }

            $partSummary = [
                'partName' => (string) ($part['partName'] ?? $partName),
                'directory' => is_string($part['directory'] ?? null) ? $part['directory'] : $this->packagePartDirectory((string) $partName),
                'baseName' => $baseName,
                'bytes' => $bytes,
                'crc32' => is_string($part['crc32'] ?? null) ? $part['crc32'] : null,
                'sha256' => is_string($part['sha256'] ?? null) ? $part['sha256'] : null,
                'contentTypeBase' => $contentTypeBase,
                'contentTypeSource' => $contentTypeSource,
                'roles' => array_values(array_map('strval', $part['roles'] ?? [])),
            ];
            $largestPart = $baseNames[$caseFoldBaseName]['largestPart'];
            if (
                !is_array($largestPart)
                || $partSummary['bytes'] > (int) ($largestPart['bytes'] ?? 0)
                || (
                    $partSummary['bytes'] === (int) ($largestPart['bytes'] ?? 0)
                    && strcmp($partSummary['partName'], (string) ($largestPart['partName'] ?? '')) < 0
                )
            ) {
                $baseNames[$caseFoldBaseName]['largestPart'] = $partSummary;
            }
        }

        ksort($baseNames, SORT_STRING);
        foreach ($baseNames as $caseFoldBaseName => $summary) {
            ksort($summary['baseNameCounts'], SORT_STRING);
            ksort($summary['contentTypeSourceCounts'], SORT_STRING);
            ksort($summary['contentTypeBaseCounts'], SORT_STRING);
            ksort($summary['roleCounts'], SORT_STRING);
            sort($summary['directories'], SORT_STRING);
            $summary['caseVariantCount'] = count($summary['baseNameCounts']);
            $baseNames[$caseFoldBaseName] = $summary;
        }

        return array_values($baseNames);
    }

    /**
     * @param array<string, array<string, mixed>> $partInventory
