            foreach (($source['sourceRoles'] ?? []) as $role) {
                $role = (string) $role;
                $sources[$sourceKey]['sourceRoleCounts'][$role] =
                    ($sources[$sourceKey]['sourceRoleCounts'][$role] ?? 0) + 1;
            }

            $this->appendUniqueString(
