                $baseNameStems[$baseNameStemKey]['contentTypes'],
                is_string($source['sourceContentType'] ?? null) ? $source['sourceContentType'] : null,
            );

            if (is_int($source['sourceBytes'] ?? null)) {
                $sourceBytes = (int) $source['sourceBytes'];
                $baseNameStems[$baseNameStemKey]['existingSourceByteLength'] += $sourceBytes;
                $sourceSummary = [
                    'sourcePart' => $sourcePart,
                    'relationshipsPart' => is_string($source['relationshipsPart'] ?? null) ? $source['relationshipsPart'] : '',
                    'relationshipSourceKind' => $sourceKind,
                    'sourceDirectory' => $directory === '' ? null : $directory,
                    'sourceBaseName' => $baseName === '' ? null : $baseName,
                    'sourceBaseNameStem' => $baseNameStem === '' ? null : $baseNameStem,
                    'sourcePartExtension' => $extension,
                    'sourceBytes' => $sourceBytes,
                    'sourceCrc32' => is_string($source['sourceCrc32'] ?? null) ? $source['sourceCrc32'] : null,
                    'sourceSha256' => is_string($source['sourceSha256'] ?? null) ? $source['sourceSha256'] : null,
                    'sourceContentType' => is_string($source['sourceContentType'] ?? null) ? $source['sourceContentType'] : null,
                    'sourceContentTypeBase' => $contentTypeBase === '' ? null : $contentTypeBase,
                    'sourceContentTypeSource' => $contentTypeSource === '' ? null : $contentTypeSource,
                    'sourceRoles' => array_values(array_map('strval', $source['sourceRoles'] ?? [])),
                    'relationshipCount' => (int) ($source['relationshipCount'] ?? 0),
                    'relationshipRecordCount' => (int) ($source['relationshipRecordCount'] ?? 0),
                ];
                $largestPart = $baseNameStems[$baseNameStemKey]['largestExistingSourcePart'];
                if (
                    !is_array($largestPart)
                    || $sourceSummary['sourceBytes'] > (int) ($largestPart['sourceBytes'] ?? 0)
                    || (
                        $sourceSummary['sourceBytes'] === (int) ($largestPart['sourceBytes'] ?? 0)
                        && strcmp($sourceSummary['sourcePart'], (string) ($largestPart['sourcePart'] ?? '')) < 0
                    )
                ) {
                    $baseNameStems[$baseNameStemKey]['largestExistingSourcePart'] = $sourceSummary;
                }
            }
        }

        ksort($baseNameStems, SORT_STRING);
        foreach ($baseNameStems as $baseNameStemKey => $summary) {
            ksort($summary['baseNameCounts'], SORT_STRING);
            ksort($summary['sourcePartExtensionCounts'], SORT_STRING);
            ksort($summary['relationshipSourceKindCounts'], SORT_STRING);
            ksort($summary['sourceContentTypeBaseCounts'], SORT_STRING);
            ksort($summary['sourceContentTypeSourceCounts'], SORT_STRING);
            ksort($summary['sourceDirectoryCounts'], SORT_STRING);
            ksort($summary['sourceRoleCounts'], SORT_STRING);
            sort($summary['sourceParts'], SORT_STRING);
            sort($summary['existingSourceParts'], SORT_STRING);
            sort($summary['nonExistingSourceParts'], SORT_STRING);
            sort($summary['relationshipParts'], SORT_STRING);
            sort($summary['contentTypes'], SORT_STRING);
            $summary['baseNameVariantCount'] = count($summary['baseNameCounts']);
            $summary['extensionVariantCount'] = count($summary['sourcePartExtensionCounts']);
            $baseNameStems[$baseNameStemKey] = $summary;
        }

        return array_values($baseNameStems);
    }

    /**
     * @param list<array<string, mixed>> $relationshipSources
     * @return list<array<string, mixed>>
     */
    private function relationshipSourcePartExtensionSummary(array $relationshipSources): array
    {
        $extensions = [];
        foreach ($relationshipSources as $source) {
            $extension = is_string($source['sourcePartExtension'] ?? null)
                ? $source['sourcePartExtension']
                : null;
            $extensionKey = $extension ?? '(none)';
            if (!isset($extensions[$extensionKey])) {
                $extensions[$extensionKey] = [
                    'sourcePartExtensionKey' => $extensionKey,
                    'sourcePartExtension' => $extension,
                    'sourceCount' => 0,
                    'existingSourceCount' => 0,
                    'nonExistingSourceCount' => 0,
                    'relationshipCount' => 0,
                    'relationshipRecordCount' => 0,
                    'existingSourceByteLength' => 0,
                    'relationshipSourceKindCounts' => [],
                    'sourceBaseNameCounts' => [],
                    'sourceContentTypeBaseCounts' => [],
                    'sourceContentTypeSourceCounts' => [],
                    'sourceRoleCounts' => [],
                    'sourceDirectories' => [],
                    'sourceParts' => [],
                    'relationshipParts' => [],
                    'largestExistingSourcePart' => null,
                ];
            }

            ++$extensions[$extensionKey]['sourceCount'];
            $sourceExists = ($source['sourceExists'] ?? false) === true;
            if ($sourceExists) {
                ++$extensions[$extensionKey]['existingSourceCount'];
            } else {
                ++$extensions[$extensionKey]['nonExistingSourceCount'];
            }
            $extensions[$extensionKey]['relationshipCount'] += (int) ($source['relationshipCount'] ?? 0);
            $extensions[$extensionKey]['relationshipRecordCount'] += (int) ($source['relationshipRecordCount'] ?? 0);
            if (is_int($source['sourceBytes'] ?? null)) {
                $extensions[$extensionKey]['existingSourceByteLength'] += (int) $source['sourceBytes'];
            }

            $sourceKind = is_string($source['relationshipSourceKind'] ?? null)
                ? $source['relationshipSourceKind']
                : 'invalid-source';
            $extensions[$extensionKey]['relationshipSourceKindCounts'][$sourceKind] =
                ($extensions[$extensionKey]['relationshipSourceKindCounts'][$sourceKind] ?? 0) + 1;

            $baseName = is_string($source['sourceBaseName'] ?? null) ? $source['sourceBaseName'] : '';
            $baseNameKey = $baseName === '' ? '(invalid-source)' : $baseName;
            $extensions[$extensionKey]['sourceBaseNameCounts'][$baseNameKey] =
                ($extensions[$extensionKey]['sourceBaseNameCounts'][$baseNameKey] ?? 0) + 1;

            $contentTypeBase = is_string($source['sourceContentTypeBase'] ?? null)
                ? $source['sourceContentTypeBase']
                : '';
            $contentTypeBaseKey = $contentTypeBase === '' ? '(missing)' : $contentTypeBase;
            $extensions[$extensionKey]['sourceContentTypeBaseCounts'][$contentTypeBaseKey] =
                ($extensions[$extensionKey]['sourceContentTypeBaseCounts'][$contentTypeBaseKey] ?? 0) + 1;

            $contentTypeSource = is_string($source['sourceContentTypeSource'] ?? null)
                ? $source['sourceContentTypeSource']
                : '';
            $contentTypeSourceKey = $contentTypeSource === '' ? '(missing)' : $contentTypeSource;
            $extensions[$extensionKey]['sourceContentTypeSourceCounts'][$contentTypeSourceKey] =
                ($extensions[$extensionKey]['sourceContentTypeSourceCounts'][$contentTypeSourceKey] ?? 0) + 1;

            foreach (($source['sourceRoles'] ?? []) as $role) {
                $role = (string) $role;
                $extensions[$extensionKey]['sourceRoleCounts'][$role] =
                    ($extensions[$extensionKey]['sourceRoleCounts'][$role] ?? 0) + 1;
            }

            $this->appendUniqueString(
                $extensions[$extensionKey]['sourceDirectories'],
                is_string($source['sourceDirectory'] ?? null) ? $source['sourceDirectory'] : null,
            );
            $this->appendUniqueString(
                $extensions[$extensionKey]['sourceParts'],
                is_string($source['sourcePart'] ?? null) ? $source['sourcePart'] : null,
            );
            $this->appendUniqueString(
                $extensions[$extensionKey]['relationshipParts'],
                is_string($source['relationshipsPart'] ?? null) ? $source['relationshipsPart'] : null,
            );

            if (is_int($source['sourceBytes'] ?? null)) {
                $sourceBytes = (int) $source['sourceBytes'];
                $sourceSummary = [
                    'sourcePart' => is_string($source['sourcePart'] ?? null) ? $source['sourcePart'] : '',
                    'relationshipsPart' => is_string($source['relationshipsPart'] ?? null) ? $source['relationshipsPart'] : '',
                    'relationshipSourceKind' => $sourceKind,
                    'sourceDirectory' => is_string($source['sourceDirectory'] ?? null) ? $source['sourceDirectory'] : null,
                    'sourceBaseName' => is_string($source['sourceBaseName'] ?? null) ? $source['sourceBaseName'] : null,
                    'sourcePartExtension' => $extension,
                    'sourceBytes' => $sourceBytes,
                    'sourceCrc32' => is_string($source['sourceCrc32'] ?? null) ? $source['sourceCrc32'] : null,
                    'sourceSha256' => is_string($source['sourceSha256'] ?? null) ? $source['sourceSha256'] : null,
                    'sourceContentTypeBase' => $contentTypeBase === '' ? null : $contentTypeBase,
                    'sourceContentTypeSource' => $contentTypeSource === '' ? null : $contentTypeSource,
                    'sourceRoles' => array_values(array_map('strval', $source['sourceRoles'] ?? [])),
                ];
                $largestPart = $extensions[$extensionKey]['largestExistingSourcePart'];
                if (
                    !is_array($largestPart)
                    || $sourceSummary['sourceBytes'] > (int) ($largestPart['sourceBytes'] ?? 0)
                    || (
                        $sourceSummary['sourceBytes'] === (int) ($largestPart['sourceBytes'] ?? 0)
                        && strcmp($sourceSummary['sourcePart'], (string) ($largestPart['sourcePart'] ?? '')) < 0
                    )
                ) {
                    $extensions[$extensionKey]['largestExistingSourcePart'] = $sourceSummary;
                }
            }
        }

        ksort($extensions, SORT_STRING);
        foreach ($extensions as $extensionKey => $summary) {
            ksort($summary['relationshipSourceKindCounts'], SORT_STRING);
            ksort($summary['sourceBaseNameCounts'], SORT_STRING);
            ksort($summary['sourceContentTypeBaseCounts'], SORT_STRING);
            ksort($summary['sourceContentTypeSourceCounts'], SORT_STRING);
            ksort($summary['sourceRoleCounts'], SORT_STRING);
            sort($summary['sourceDirectories'], SORT_STRING);
            sort($summary['sourceParts'], SORT_STRING);
            sort($summary['relationshipParts'], SORT_STRING);
            $extensions[$extensionKey] = $summary;
        }

        return array_values($extensions);
    }

    /**
     * @param array<string, array<string, mixed>> $relationshipParts
     * @param array<string, array<string, mixed>> $partInventory
     * @return list<array<string, mixed>>
     */
    private function relationshipTargetPartExtensionSummary(array $relationshipParts, array $partInventory): array
    {
        $extensions = [];
        foreach ($relationshipParts as $relationshipPart) {
            foreach (($relationshipPart['relationships'] ?? []) as $relationship) {
                if (!is_array($relationship) || ($relationship['external'] ?? false) === true) {
                    continue;
                }

                $targetPart = is_string($relationship['targetPart'] ?? null) ? $relationship['targetPart'] : '';
                if ($targetPart === '') {
                    continue;
                }

                $targetInventory = is_array($partInventory[$targetPart] ?? null) ? $partInventory[$targetPart] : null;
                $extension = $targetInventory !== null && is_string($targetInventory['partExtension'] ?? null)
                    ? $targetInventory['partExtension']
                    : $this->packagePartExtension($targetPart);
                $extensionKey = $extension ?? '(none)';
                $targetDirectory = $targetInventory !== null && is_string($targetInventory['directory'] ?? null)
                    ? $targetInventory['directory']
                    : $this->packagePartDirectory($targetPart);
                $targetPathDepth = $targetInventory !== null && is_int($targetInventory['pathSegmentCount'] ?? null)
                    ? (int) $targetInventory['pathSegmentCount']
                    : count($this->packagePartPathSegments($targetPart));
                $contentType = is_string($relationship['contentType'] ?? null) ? $relationship['contentType'] : '';
                $relationshipType = is_string($relationship['type'] ?? null) ? $relationship['type'] : '';
                $relationshipTypeKey = $relationshipType === '' ? '(missing-type)' : $relationshipType;
                if (!isset($extensions[$extensionKey])) {
                    $extensions[$extensionKey] = [
                        'targetPartExtensionKey' => $extensionKey,
                        'targetPartExtension' => $extension,
                        'partExtensionKey' => $extensionKey,
                        'partExtension' => $extension,
                        'relationshipCount' => 0,
                        'existingTargetCount' => 0,
                        'missingTargetCount' => 0,
                        'missingContentTypeTargetCount' => 0,
                        'parameterizedTargetCount' => 0,
                        'existingTargetByteLength' => 0,
                        'existingTargetPartByteLength' => 0,
                        'targetDirectoryCounts' => [],
                        'contentTypeBaseCounts' => [],
                        'contentTypeSourceCounts' => [],
                        'relationshipTypeCounts' => [],
                        'relationshipSourceKindCounts' => [],
                        'targetRoleCounts' => [],
                        'sourceParts' => [],
                        'relationshipParts' => [],
                        'relationshipIds' => [],
                        'relationshipTypes' => [],
                        'targetParts' => [],
                        'contentTypes' => [],
                        'existingTargetParts' => [],
                        'missingTargetParts' => [],
                        'largestExistingTargetPart' => null,
                    ];
                }

                ++$extensions[$extensionKey]['relationshipCount'];
                $exists = ($relationship['exists'] ?? false) === true;
                if ($exists) {
                    ++$extensions[$extensionKey]['existingTargetCount'];
                    $this->appendUniqueString($extensions[$extensionKey]['existingTargetParts'], $targetPart);
                } else {
                    ++$extensions[$extensionKey]['missingTargetCount'];
                    $this->appendUniqueString($extensions[$extensionKey]['missingTargetParts'], $targetPart);
                }
                if (($relationship['contentTypeHasParameters'] ?? false) === true) {
                    ++$extensions[$extensionKey]['parameterizedTargetCount'];
                }

                $contentTypeBase = is_string($relationship['contentTypeBase'] ?? null)
                    ? $relationship['contentTypeBase']
                    : '';
                $contentTypeBaseKey = $contentTypeBase === '' ? '(missing)' : $contentTypeBase;
                $extensions[$extensionKey]['contentTypeBaseCounts'][$contentTypeBaseKey] =
                    ($extensions[$extensionKey]['contentTypeBaseCounts'][$contentTypeBaseKey] ?? 0) + 1;

                $contentTypeSource = is_string($relationship['contentTypeSource'] ?? null)
                    ? $relationship['contentTypeSource']
                    : '';
                $contentTypeSourceKey = $contentTypeSource === '' ? 'missing' : $contentTypeSource;
                $extensions[$extensionKey]['contentTypeSourceCounts'][$contentTypeSourceKey] =
                    ($extensions[$extensionKey]['contentTypeSourceCounts'][$contentTypeSourceKey] ?? 0) + 1;
                if ($contentTypeSourceKey === 'missing') {
                    ++$extensions[$extensionKey]['missingContentTypeTargetCount'];
                }

                $extensions[$extensionKey]['targetDirectoryCounts'][$targetDirectory] =
                    ($extensions[$extensionKey]['targetDirectoryCounts'][$targetDirectory] ?? 0) + 1;
                $extensions[$extensionKey]['relationshipTypeCounts'][$relationshipTypeKey] =
                    ($extensions[$extensionKey]['relationshipTypeCounts'][$relationshipTypeKey] ?? 0) + 1;

                $sourceKind = is_string($relationship['relationshipSourceKind'] ?? null)
                    ? $relationship['relationshipSourceKind']
                    : 'invalid-source';
                $extensions[$extensionKey]['relationshipSourceKindCounts'][$sourceKind] =
                    ($extensions[$extensionKey]['relationshipSourceKindCounts'][$sourceKind] ?? 0) + 1;

                $targetRoles = [];
                if ($targetInventory !== null) {
                    foreach (($targetInventory['roles'] ?? []) as $targetRole) {
                        if (is_string($targetRole) && $targetRole !== '') {
                            $targetRoles[$targetRole] = true;
                        }
                    }
                }
                if ($targetRoles === []) {
                    $targetRoles[$exists ? 'relationship-target' : 'missing-relationship-target'] = true;
                }
                foreach (array_keys($targetRoles) as $targetRole) {
                    $extensions[$extensionKey]['targetRoleCounts'][$targetRole] =
                        ($extensions[$extensionKey]['targetRoleCounts'][$targetRole] ?? 0) + 1;
                }

                $this->appendUniqueString(
                    $extensions[$extensionKey]['sourceParts'],
                    is_string($relationship['sourcePart'] ?? null) ? $relationship['sourcePart'] : null,
                );
                $this->appendUniqueString(
                    $extensions[$extensionKey]['relationshipParts'],
                    is_string($relationship['relationshipsPart'] ?? null) ? $relationship['relationshipsPart'] : null,
                );
                $this->appendUniqueString(
                    $extensions[$extensionKey]['relationshipIds'],
                    is_string($relationship['id'] ?? null) ? $relationship['id'] : null,
                );
                $this->appendUniqueString(
                    $extensions[$extensionKey]['relationshipTypes'],
                    $relationshipType,
                );
                $this->appendUniqueString($extensions[$extensionKey]['targetParts'], $targetPart);
                $this->appendUniqueString($extensions[$extensionKey]['contentTypes'], $contentType);

                if ($targetInventory === null) {
                    continue;
                }

                $targetSummary = [
                    'partName' => $targetPart,
                    'directory' => is_string($targetInventory['directory'] ?? null)
                        ? $targetInventory['directory']
                        : $targetDirectory,
                    'topLevelSegment' => is_string($targetInventory['topLevelSegment'] ?? null)
                        ? $targetInventory['topLevelSegment']
                        : $this->packagePartTopLevelSegment($targetPart),
                    'targetPathDepth' => $targetPathDepth,
                    'partExtension' => $extension,
                    'bytes' => (int) ($targetInventory['bytes'] ?? 0),
                    'crc32' => is_string($targetInventory['crc32'] ?? null) ? $targetInventory['crc32'] : null,
                    'sha256' => is_string($targetInventory['sha256'] ?? null) ? $targetInventory['sha256'] : null,
                    'contentType' => is_string($targetInventory['contentType'] ?? null) ? $targetInventory['contentType'] : '',
                    'contentTypeBase' => is_string($targetInventory['contentTypeBase'] ?? null) ? $targetInventory['contentTypeBase'] : '',
                    'contentTypeSource' => is_string($targetInventory['contentTypeSource'] ?? null) ? $targetInventory['contentTypeSource'] : 'missing',
                    'roles' => array_values(array_map('strval', $targetInventory['roles'] ?? [])),
                ];
                $extensions[$extensionKey]['existingTargetByteLength'] += $targetSummary['bytes'];
                $extensions[$extensionKey]['existingTargetPartByteLength'] += $targetSummary['bytes'];
                $largestPart = $extensions[$extensionKey]['largestExistingTargetPart'];
                if (
                    !is_array($largestPart)
                    || $targetSummary['bytes'] > (int) ($largestPart['bytes'] ?? 0)
                    || (
                        $targetSummary['bytes'] === (int) ($largestPart['bytes'] ?? 0)
                        && strcmp($targetSummary['partName'], (string) ($largestPart['partName'] ?? '')) < 0
                    )
                ) {
                    $extensions[$extensionKey]['largestExistingTargetPart'] = $targetSummary;
                }
            }
        }

        ksort($extensions, SORT_STRING);
        foreach ($extensions as $extensionKey => $summary) {
            ksort($summary['targetDirectoryCounts'], SORT_STRING);
            ksort($summary['contentTypeBaseCounts'], SORT_STRING);
            ksort($summary['contentTypeSourceCounts'], SORT_STRING);
            ksort($summary['relationshipTypeCounts'], SORT_STRING);
            ksort($summary['relationshipSourceKindCounts'], SORT_STRING);
            ksort($summary['targetRoleCounts'], SORT_STRING);
            sort($summary['sourceParts'], SORT_STRING);
            sort($summary['relationshipParts'], SORT_STRING);
            sort($summary['relationshipIds'], SORT_STRING);
            sort($summary['relationshipTypes'], SORT_STRING);
            sort($summary['targetParts'], SORT_STRING);
            sort($summary['contentTypes'], SORT_STRING);
            sort($summary['existingTargetParts'], SORT_STRING);
            sort($summary['missingTargetParts'], SORT_STRING);
            $extensions[$extensionKey] = $summary;
        }

        return array_values($extensions);
    }

    /**
     * @param array<string, array<string, mixed>> $partInventory
     * @return array{partCount:int, flagCounts:array<string, int>, flagPartNames:array<string, list<string>>, parts:list<array<string, mixed>>}
     */
    private function packagePartNameCharacterSummary(array $partInventory): array
    {
        $flagCounts = [];
        $flagPartNames = [];
        $items = [];
        foreach ($partInventory as $partName => $part) {
            $partName = (string) ($part['partName'] ?? $partName);
            $flags = is_array($part['partNameCharacterFlags'] ?? null)
                ? array_values(array_map('strval', $part['partNameCharacterFlags']))
                : $this->packagePartNameCharacterFlags($partName);
            if ($flags === []) {
                continue;
            }

            foreach ($flags as $flag) {
                if ($flag === '') {
                    continue;
                }

                $flagCounts[$flag] = ($flagCounts[$flag] ?? 0) + 1;
                $flagPartNames[$flag][] = $partName;
            }

            $items[] = [
                'partName' => $partName,
                'directory' => is_string($part['directory'] ?? null)
                    ? $part['directory']
                    : $this->packagePartDirectory($partName),
                'baseName' => is_string($part['baseName'] ?? null)
                    ? $part['baseName']
                    : $this->packagePartBaseName($partName),
                'pathSegmentCount' => is_int($part['pathSegmentCount'] ?? null)
                    ? $part['pathSegmentCount']
                    : count($this->packagePartPathSegments($partName)),
                'bytes' => (int) ($part['bytes'] ?? 0),
                'contentTypeSource' => is_string($part['contentTypeSource'] ?? null)
                    ? $part['contentTypeSource']
                    : 'missing',
                'roles' => array_values(array_map('strval', $part['roles'] ?? [])),
                'flags' => $flags,
            ];
        }

        ksort($flagCounts, SORT_STRING);
        ksort($flagPartNames, SORT_STRING);
        foreach ($flagPartNames as &$partNames) {
            sort($partNames, SORT_STRING);
        }
        unset($partNames);

        usort(
            $items,
            static fn (array $left, array $right): int => strcmp((string) $left['partName'], (string) $right['partName']),
        );

        return [
            'partCount' => count($items),
            'flagCounts' => $flagCounts,
            'flagPartNames' => $flagPartNames,
            'parts' => $items,
        ];
    }

    /**
     * @param array<string, array<string, mixed>> $partInventory
     * @return array{partCount:int, flagCounts:array<string, int>, flagPartNames:array<string, list<string>>, flagBaseNames:array<string, list<string>>, parts:list<array<string, mixed>>}
     */
    private function packagePartBaseNameCharacterSummary(array $partInventory): array
    {
        $flagCounts = [];
        $flagPartNames = [];
        $flagBaseNames = [];
        $items = [];
        foreach ($partInventory as $partName => $part) {
            $partName = (string) ($part['partName'] ?? $partName);
            $baseName = is_string($part['baseName'] ?? null)
                ? $part['baseName']
                : $this->packagePartBaseName($partName);
            $flags = is_array($part['baseNameCharacterFlags'] ?? null)
                ? array_values(array_map('strval', $part['baseNameCharacterFlags']))
                : $this->packagePartNameCharacterFlags($baseName);
            $flags = array_values(array_filter($flags, static fn (string $flag): bool => $flag !== ''));
            if ($flags === []) {
                continue;
            }

            foreach ($flags as $flag) {
                $flagCounts[$flag] = ($flagCounts[$flag] ?? 0) + 1;
                $flagPartNames[$flag] ??= [];
                $flagBaseNames[$flag] ??= [];
                $this->appendUniqueString($flagPartNames[$flag], $partName);
                $this->appendUniqueString($flagBaseNames[$flag], $baseName);
            }

            $items[] = [
                'partName' => $partName,
                'directory' => is_string($part['directory'] ?? null)
                    ? $part['directory']
                    : $this->packagePartDirectory($partName),
                'baseName' => $baseName,
                'caseFoldBaseName' => $this->packagePartCaseFoldKey($baseName),
                'partExtension' => is_string($part['partExtension'] ?? null) ? $part['partExtension'] : null,
                'bytes' => (int) ($part['bytes'] ?? 0),
                'contentTypeSource' => is_string($part['contentTypeSource'] ?? null)
                    ? $part['contentTypeSource']
                    : 'missing',
                'contentTypeBase' => is_string($part['contentTypeBase'] ?? null)
                    ? $part['contentTypeBase']
                    : '',
                'roles' => array_values(array_map('strval', $part['roles'] ?? [])),
                'flags' => $flags,
            ];
        }

        ksort($flagCounts, SORT_STRING);
        ksort($flagPartNames, SORT_STRING);
        foreach ($flagPartNames as &$partNames) {
            sort($partNames, SORT_STRING);
        }
        unset($partNames);
        ksort($flagBaseNames, SORT_STRING);
        foreach ($flagBaseNames as &$baseNames) {
            sort($baseNames, SORT_STRING);
        }
        unset($baseNames);

        usort(
            $items,
            static fn (array $left, array $right): int => strcmp((string) $left['partName'], (string) $right['partName']),
        );

        return [
            'partCount' => count($items),
            'flagCounts' => $flagCounts,
            'flagPartNames' => $flagPartNames,
            'flagBaseNames' => $flagBaseNames,
            'parts' => $items,
        ];
    }

    /**
     * @param list<array<string, mixed>> $relationshipSources
     * @return array{sourceCount:int, relationshipCount:int, relationshipRecordCount:int, sourceParts:list<string>, flagSourceCounts:array<string, int>, flagSourceParts:array<string, list<string>>, sources:list<array<string, mixed>>}
     */
    private function relationshipSourceNameCharacterSummary(array $relationshipSources): array
    {
        $flagSourceCounts = [];
        $flagSourceParts = [];
        $sourceParts = [];
        $items = [];
        $totalRelationshipCount = 0;
        $totalRelationshipRecordCount = 0;

        foreach ($relationshipSources as $source) {
            $sourcePart = is_string($source['sourcePart'] ?? null) ? $source['sourcePart'] : '';
            if ($sourcePart === '' || $sourcePart === '/') {
                continue;
            }

            $flags = $this->packagePartNameCharacterFlags($sourcePart);
            if ($flags === []) {
                continue;
            }

            $relationshipCount = (int) ($source['relationshipCount'] ?? 0);
            $relationshipRecordCount = (int) ($source['relationshipRecordCount'] ?? 0);
            $totalRelationshipCount += $relationshipCount;
            $totalRelationshipRecordCount += $relationshipRecordCount;
            $sourceParts[$sourcePart] = true;

            foreach ($flags as $flag) {
                if ($flag === '') {
                    continue;
                }

                $flagSourceCounts[$flag] = ($flagSourceCounts[$flag] ?? 0) + 1;
                $flagSourceParts[$flag][$sourcePart] = true;
            }

            $sourcePathSegments = is_array($source['sourcePathSegments'] ?? null)
                ? array_values(array_map('strval', $source['sourcePathSegments']))
                : $this->packagePartPathSegments($sourcePart);
            $sourceRoles = is_array($source['sourceRoles'] ?? null)
                ? array_values(array_filter(
                    array_map('strval', $source['sourceRoles']),
                    static fn (string $role): bool => $role !== '',
                ))
                : [];

            $items[] = [
                'sourcePart' => $sourcePart,
                'sourceDirectory' => is_string($source['sourceDirectory'] ?? null)
                    ? $source['sourceDirectory']
                    : $this->packagePartDirectory($sourcePart),
                'sourceBaseName' => is_string($source['sourceBaseName'] ?? null)
                    ? $source['sourceBaseName']
                    : $this->packagePartBaseName($sourcePart),
                'sourcePathDepth' => is_int($source['sourcePathDepth'] ?? null)
                    ? (int) $source['sourcePathDepth']
                    : count($sourcePathSegments),
                'sourcePathSegments' => $sourcePathSegments,
                'sourcePartExtension' => is_string($source['sourcePartExtension'] ?? null)
                    ? $source['sourcePartExtension']
                    : $this->packagePartExtension($sourcePart),
                'sourceExists' => ($source['sourceExists'] ?? false) === true,
                'relationshipSourceKind' => is_string($source['relationshipSourceKind'] ?? null)
                    ? $source['relationshipSourceKind']
                    : 'invalid-source',
                'sourceContentTypeBase' => is_string($source['sourceContentTypeBase'] ?? null)
                    ? $source['sourceContentTypeBase']
                    : '',
                'sourceContentTypeSource' => is_string($source['sourceContentTypeSource'] ?? null)
                    ? $source['sourceContentTypeSource']
                    : 'missing',
                'sourceRoles' => $sourceRoles,
                'relationshipsPart' => is_string($source['relationshipsPart'] ?? null)
                    ? $source['relationshipsPart']
                    : '',
                'relationshipCount' => $relationshipCount,
                'relationshipRecordCount' => $relationshipRecordCount,
                'flags' => $flags,
                'reviewPolicy' => 'relationship-source-name-character-metadata-only',
            ];
        }

        ksort($flagSourceCounts, SORT_STRING);
        ksort($flagSourceParts, SORT_STRING);
        foreach ($flagSourceParts as &$flagParts) {
            $flagParts = array_keys($flagParts);
            sort($flagParts, SORT_STRING);
        }
        unset($flagParts);

        $sourceParts = array_keys($sourceParts);
        sort($sourceParts, SORT_STRING);

        usort(
            $items,
            static function (array $left, array $right): int {
                return strcmp((string) $left['sourcePart'], (string) $right['sourcePart'])
                    ?: strcmp((string) $left['relationshipsPart'], (string) $right['relationshipsPart']);
            },
        );

        return [
            'sourceCount' => count($items),
            'relationshipCount' => $totalRelationshipCount,
            'relationshipRecordCount' => $totalRelationshipRecordCount,
            'sourceParts' => $sourceParts,
            'flagSourceCounts' => $flagSourceCounts,
            'flagSourceParts' => $flagSourceParts,
            'sources' => $items,
        ];
    }

    /**
     * @param list<array<string, mixed>> $relationshipTargets
     * @return array{relationshipCount:int, targetParts:list<string>, flagRelationshipCounts:array<string, int>, flagTargetParts:array<string, list<string>>, targets:list<array<string, mixed>>}
     */
    private function relationshipTargetNameCharacterSummary(array $relationshipTargets): array
    {
        $flagRelationshipCounts = [];
        $flagTargetParts = [];
        $targetParts = [];
        $items = [];

        foreach ($relationshipTargets as $target) {
            $targetPart = is_string($target['targetPart'] ?? null) ? $target['targetPart'] : '';
            if ($targetPart === '') {
                continue;
            }

            $flags = $this->packagePartNameCharacterFlags($targetPart);
            if ($flags === []) {
                continue;
            }

            $targetParts[$targetPart] = true;
            foreach ($flags as $flag) {
                if ($flag === '') {
                    continue;
                }

                $flagRelationshipCounts[$flag] = ($flagRelationshipCounts[$flag] ?? 0) + 1;
                $flagTargetParts[$flag][$targetPart] = true;
            }

            $targetPathSegments = $this->packagePartPathSegments($targetPart);
            $targetDirectory = is_string($target['targetDirectory'] ?? null)
                ? $target['targetDirectory']
                : $this->packagePartDirectory($targetPart);
            $targetBaseName = is_string($target['targetBaseName'] ?? null)
                ? $target['targetBaseName']
                : $this->packagePartBaseName($targetPart);
            $targetPathDepth = is_int($target['targetPathDepth'] ?? null)
                ? (int) $target['targetPathDepth']
                : count($targetPathSegments);
            $targetRoles = is_array($target['targetRoles'] ?? null)
                ? array_values(array_map('strval', $target['targetRoles']))
                : [];

            $items[] = [
                'targetPart' => $targetPart,
                'targetDirectory' => $targetDirectory,
                'targetBaseName' => $targetBaseName,
                'targetPathDepth' => $targetPathDepth,
                'targetPathSegments' => $targetPathSegments,
                'targetPartExtension' => is_string($target['targetPartExtension'] ?? null)
                    ? $target['targetPartExtension']
                    : $this->packagePartExtension($targetPart),
                'targetExists' => ($target['targetExists'] ?? false) === true,
                'targetContentTypeBase' => is_string($target['targetContentTypeBase'] ?? null)
                    ? $target['targetContentTypeBase']
                    : '',
                'targetContentTypeSource' => is_string($target['targetContentTypeSource'] ?? null)
                    ? $target['targetContentTypeSource']
                    : 'missing',
                'targetRoles' => $targetRoles,
                'sourcePart' => is_string($target['sourcePart'] ?? null) ? $target['sourcePart'] : '',
                'relationshipsPart' => is_string($target['relationshipsPart'] ?? null) ? $target['relationshipsPart'] : '',
                'relationshipId' => is_string($target['relationshipId'] ?? null) ? $target['relationshipId'] : '',
                'relationshipType' => is_string($target['relationshipType'] ?? null) ? $target['relationshipType'] : '',
                'flags' => $flags,
                'reviewPolicy' => 'relationship-target-name-character-metadata-only',
            ];
        }

        ksort($flagRelationshipCounts, SORT_STRING);
        ksort($flagTargetParts, SORT_STRING);
        foreach ($flagTargetParts as &$partNames) {
            $partNames = array_keys($partNames);
            sort($partNames, SORT_STRING);
        }
        unset($partNames);

        $targetParts = array_keys($targetParts);
        sort($targetParts, SORT_STRING);

        usort(
            $items,
            static function (array $left, array $right): int {
                return strcmp((string) $left['targetPart'], (string) $right['targetPart'])
                    ?: strcmp((string) $left['relationshipsPart'], (string) $right['relationshipsPart'])
                    ?: strcmp((string) $left['relationshipId'], (string) $right['relationshipId']);
            },
        );

        return [
            'relationshipCount' => count($items),
            'targetParts' => $targetParts,
            'flagRelationshipCounts' => $flagRelationshipCounts,
            'flagTargetParts' => $flagTargetParts,
            'targets' => $items,
        ];
    }

    /**
     * @param array<string, string> $parts
     * @param array<string, array{id:string, type:string, target:string, targetMode:string, resolvedTarget:string}> $rootRelationships
     * @param array{defaults:array<string, string>, overrides:array<string, string>} $contentTypes
     * @return array<string, mixed>
     */
    private function packageThumbnailProvenance(array $parts, array $rootRelationships, array $contentTypes): array
    {
        $thumbnailRelationships = [];
        foreach ($rootRelationships as $relationship) {
            if ($relationship['type'] === self::THUMBNAIL_REL) {
                $thumbnailRelationships[] = $relationship;
            }
        }

        $items = [];
        $byRelationshipId = [];
        $relationshipIds = [];
        $targetParts = [];
        $externalTargets = [];
        $contentTypesSeen = [];
        $issueCodes = [];
        $rootHasMultipleThumbnails = count($thumbnailRelationships) > 1;
        foreach ($thumbnailRelationships as $relationship) {
            $summary = $this->relationshipInventorySummary($parts, $relationship, '/', '_rels/.rels', $contentTypes);
            $targetPart = is_string($summary['targetPart'] ?? null) ? $summary['targetPart'] : null;
            $external = (bool) ($summary['external'] ?? false);
            $exists = (bool) ($summary['exists'] ?? false);
            $contentTypeBase = is_string($summary['contentTypeBase'] ?? null) ? $summary['contentTypeBase'] : '';
            $relationshipsPart = $targetPart === null ? null : $this->relationshipsPartFor($targetPart);
            $targetHasRelationships = $relationshipsPart !== null && isset($parts[$relationshipsPart]);
            $issues = [];

            if ($rootHasMultipleThumbnails) {
                $issues[] = 'multiple-thumbnail-relationships-for-source';
            }
            if ($external) {
                $issues[] = 'external-thumbnail-target';
            } elseif (!$exists) {
                $issues[] = 'missing-in-package';
            }
            if (!$external && ($summary['contentTypeSource'] ?? '') === 'missing') {
                $issues[] = 'missing-content-type';
            }
            if ($contentTypeBase !== '' && !$this->isImageContentType($contentTypeBase)) {
                $issues[] = 'invalid-thumbnail-content-type';
            }
            if ($targetHasRelationships) {
                $issues[] = 'thumbnail-target-has-relationships';
            }

            $issues = array_values(array_unique($issues));
            foreach ($issues as $issue) {
                $issueCodes[$issue] = true;
            }

            $item = [
                'source' => '/',
                'id' => $summary['id'],
                'type' => $summary['type'],
                'target' => $summary['target'],
                'targetMode' => $summary['targetMode'],
                'resolvedTarget' => $summary['resolvedTarget'],
                'targetPart' => $targetPart,
                'targetQuery' => $summary['targetQuery'],
                'targetFragment' => $summary['targetFragment'],
                'targetReferenceSuffix' => $summary['targetReferenceSuffix'],
                'contentType' => $summary['contentType'],
                'contentTypeBase' => $summary['contentTypeBase'],
                'contentTypeHasParameters' => $summary['contentTypeHasParameters'],
                'contentTypeParameterCount' => $summary['contentTypeParameterCount'],
                'contentTypeParameters' => $summary['contentTypeParameters'],
                'contentTypeParameterMap' => $summary['contentTypeParameterMap'],
                'contentTypeSource' => $summary['contentTypeSource'],
                'defaultExtension' => $summary['defaultExtension'],
                'overridePartName' => $summary['overridePartName'],
                'expectedContentTypePrefix' => 'image/',
                'external' => $external,
                'exists' => $exists,
                'relationshipsPart' => '_rels/.rels',
                'targetRelationshipsPart' => $relationshipsPart,
                'targetHasRelationships' => $targetHasRelationships,
                'byteLength' => $targetPart !== null && $exists ? strlen($parts[$targetPart]) : null,
                'crc32' => $targetPart !== null && $exists ? sprintf('%08x', crc32($parts[$targetPart])) : null,
                'sha256' => $targetPart !== null && $exists ? hash('sha256', $parts[$targetPart]) : null,
                'storedByteLength' => null,
                'storedCrc32' => null,
                'canExposeAsDocumentMedia' => false,
                'reviewPolicy' => 'package-thumbnail-metadata-only',
                'valid' => $issues === [],
                'issues' => $issues,
            ];

            $items[] = $item;
            $byRelationshipId[(string) $item['id']] = $item;
            $relationshipIds[] = (string) $item['id'];
            $this->appendUniqueString($targetParts, $targetPart);
            if ($external) {
                $this->appendUniqueString($externalTargets, is_string($summary['target'] ?? null) ? $summary['target'] : null);
            }
            $this->appendUniqueString($contentTypesSeen, is_string($summary['contentType'] ?? null) ? $summary['contentType'] : null);
        }

        ksort($issueCodes, SORT_STRING);

        return [
            'count' => count($items),
            'readableCount' => count(array_filter(
                $items,
                static fn (array $item): bool => $item['external'] === false && $item['exists'] === true && $item['byteLength'] !== null,
            )),
            'missingCount' => count(array_filter(
                $items,
                static fn (array $item): bool => $item['external'] === false && $item['exists'] === false,
            )),
            'externalCount' => count(array_filter($items, static fn (array $item): bool => $item['external'] === true)),
            'invalidCount' => count(array_filter($items, static fn (array $item): bool => $item['valid'] !== true)),
            'issueCount' => count(array_filter($items, static fn (array $item): bool => $item['issues'] !== [])),
            'relationshipIds' => $relationshipIds,
            'targetParts' => $targetParts,
            'externalTargets' => $externalTargets,
            'contentTypes' => $contentTypesSeen,
            'issueCodes' => array_keys($issueCodes),
            'byRelationshipId' => $byRelationshipId,
            'items' => $items,
        ];
    }

    private function isImageContentType(string $contentType): bool
    {
        return str_starts_with(strtolower(trim(explode(';', $contentType, 2)[0])), 'image/');
    }

    /**
     * @param array<string, string> $parts
     * @param array<string, array{id:string, type:string, target:string, targetMode:string, resolvedTarget:string}> $rootRelationships
     * @param array{defaults:array<string, string>, overrides:array<string, string>} $contentTypes
     * @return array<string, mixed>
     */
    private function packageRootRelationshipResources(array $parts, array $rootRelationships, array $contentTypes): array
    {
        $items = [];
        $byRelationshipId = [];
        $relationshipIds = [];
        $relationshipTypes = [];
        $targetParts = [];
        $externalTargets = [];
        $contentTypesSeen = [];
        $targetRelationshipTypes = [];
        $targetRelationshipTargetParts = [];
        $targetRelationshipExternalTargets = [];
        $targetRelationshipExistingTargetParts = [];
        $targetRelationshipMissingTargetParts = [];
        $targetRelationshipAllowedExternalTargets = [];
        $targetRelationshipUnsafeExternalTargets = [];
        $targetRelationshipContentTypes = [];
        $targetRelationshipContentTypeBases = [];
        $targetRelationshipIssueCodes = [];
        $issueCodes = [];

        foreach ($rootRelationships as $relationship) {
            if (in_array($relationship['type'], self::STANDARD_PACKAGE_ROOT_RELATIONSHIP_TYPES, true)) {
                continue;
            }

            $summary = $this->relationshipInventorySummary($parts, $relationship, '/', '_rels/.rels', $contentTypes);
            $targetPart = is_string($summary['targetPart'] ?? null) ? $summary['targetPart'] : null;
            $external = (bool) ($summary['external'] ?? false);
            $exists = (bool) ($summary['exists'] ?? false);
            $relationshipsPart = $targetPart === null ? null : $this->relationshipsPartFor($targetPart);
            $targetHasRelationships = $relationshipsPart !== null && isset($parts[$relationshipsPart]);
            $targetRelationships = $targetHasRelationships && $relationshipsPart !== null
                ? $this->readRelationshipsPart($parts, $relationshipsPart)
                : [];
            $itemTargetRelationships = [];
            $targetRelationshipIds = [];
            $itemTargetRelationshipTypes = [];
            $itemTargetRelationshipTargetParts = [];
            $itemTargetRelationshipExternalTargets = [];
            $itemTargetRelationshipExistingTargetParts = [];
            $itemTargetRelationshipMissingTargetParts = [];
            $itemTargetRelationshipAllowedExternalTargets = [];
            $itemTargetRelationshipUnsafeExternalTargets = [];
            $itemTargetRelationshipContentTypes = [];
            $itemTargetRelationshipContentTypeBases = [];
            $itemTargetRelationshipIssueCodes = [];
            foreach ($targetRelationships as $targetRelationship) {
                $this->appendUniqueString($targetRelationshipIds, is_string($targetRelationship['id'] ?? null) ? $targetRelationship['id'] : null);
                $this->appendUniqueString($itemTargetRelationshipTypes, is_string($targetRelationship['type'] ?? null) ? $targetRelationship['type'] : null);
                $targetRelationshipSummary = $this->packageRootRelationshipTargetRelationshipItem(
                    $parts,
                    $targetRelationship,
                    $targetPart ?? '',
                    $relationshipsPart ?? '',
                    $contentTypes,
                );
                $itemTargetRelationships[] = $targetRelationshipSummary;

                if (($targetRelationshipSummary['external'] ?? false) === true) {
                    $externalTarget = is_string($targetRelationshipSummary['target'] ?? null)
                        ? $targetRelationshipSummary['target']
                        : null;
                    $this->appendUniqueString($itemTargetRelationshipExternalTargets, $externalTarget);
                    if (($targetRelationshipSummary['externalTargetAllowed'] ?? null) === true) {
                        $this->appendUniqueString($itemTargetRelationshipAllowedExternalTargets, $externalTarget);
                    } else {
                        $this->appendUniqueString($itemTargetRelationshipUnsafeExternalTargets, $externalTarget);
                    }
                } else {
                    $targetRelationshipTargetPart = is_string($targetRelationshipSummary['targetPart'] ?? null)
                        ? $targetRelationshipSummary['targetPart']
                        : null;
                    $this->appendUniqueString($itemTargetRelationshipTargetParts, $targetRelationshipTargetPart);
                    if (($targetRelationshipSummary['exists'] ?? false) === true) {
                        $this->appendUniqueString($itemTargetRelationshipExistingTargetParts, $targetRelationshipTargetPart);
                    } else {
                        $this->appendUniqueString($itemTargetRelationshipMissingTargetParts, $targetRelationshipTargetPart);
                    }
                    $this->appendUniqueString(
                        $itemTargetRelationshipContentTypes,
                        is_string($targetRelationshipSummary['contentType'] ?? null) ? $targetRelationshipSummary['contentType'] : null,
                    );
                    $this->appendUniqueString(
                        $itemTargetRelationshipContentTypeBases,
                        is_string($targetRelationshipSummary['contentTypeBase'] ?? null) ? $targetRelationshipSummary['contentTypeBase'] : null,
                    );
                }

                foreach (($targetRelationshipSummary['issues'] ?? []) as $issue) {
                    if (is_string($issue) && $issue !== '') {
                        $itemTargetRelationshipIssueCodes[$issue] = true;
                    }
                }
            }
            ksort($itemTargetRelationshipIssueCodes, SORT_STRING);
            $externalTargetIssues = is_array($summary['externalTargetIssues'] ?? null)
                ? array_values(array_map('strval', $summary['externalTargetIssues']))
                : [];
            $issues = [];

            if ($external) {
                $issues[] = 'external-package-root-relationship';
                $issues = array_merge($issues, $externalTargetIssues);
            } elseif (!$exists) {
                $issues[] = 'missing-package-root-target';
            }
            if (!$external && ($summary['contentTypeSource'] ?? '') === 'missing') {
                $issues[] = 'missing-package-root-content-type';
            }

            $issues = array_values(array_unique($issues));
            foreach ($issues as $issue) {
                $issueCodes[$issue] = true;
            }

            $item = [
                'source' => '/',
                'id' => $summary['id'],
                'type' => $summary['type'],
                'target' => $summary['target'],
                'targetMode' => $summary['targetMode'],
                'external' => $external,
                'resolvedTarget' => $summary['resolvedTarget'],
                'targetPart' => $targetPart,
                'targetQuery' => $summary['targetQuery'],
                'targetFragment' => $summary['targetFragment'],
                'targetReferenceSuffix' => $summary['targetReferenceSuffix'],
                'targetParentTraversalCount' => $summary['targetParentTraversalCount'],
                'targetHasParentTraversal' => $summary['targetHasParentTraversal'],
                'targetStartsAtPackageRoot' => $summary['targetStartsAtPackageRoot'],
                'sameSourcePart' => $summary['sameSourcePart'],
                'externalTargetKind' => $summary['externalTargetKind'],
                'externalTargetScheme' => $summary['externalTargetScheme'],
                'externalTargetAllowed' => $summary['externalTargetAllowed'],
                'externalTargetIssues' => $externalTargetIssues,
                'exists' => $exists,
                'contentType' => $summary['contentType'],
                'contentTypeBase' => $summary['contentTypeBase'],
                'contentTypeHasParameters' => $summary['contentTypeHasParameters'],
                'contentTypeParameterCount' => $summary['contentTypeParameterCount'],
                'contentTypeParameters' => $summary['contentTypeParameters'],
                'contentTypeParameterMap' => $summary['contentTypeParameterMap'],
                'contentTypeSource' => $summary['contentTypeSource'],
                'defaultExtension' => $summary['defaultExtension'],
                'overridePartName' => $summary['overridePartName'],
                'relationshipsPart' => '_rels/.rels',
                'targetRelationshipsPart' => $relationshipsPart,
                'targetHasRelationships' => $targetHasRelationships,
                'targetRelationshipRecordCount' => count($targetRelationships),
                'targetRelationshipIds' => $targetRelationshipIds,
                'targetRelationshipTypes' => $itemTargetRelationshipTypes,
                'targetRelationshipTargetParts' => $itemTargetRelationshipTargetParts,
                'targetRelationshipExternalTargets' => $itemTargetRelationshipExternalTargets,
                'targetRelationshipExistingTargetCount' => count($itemTargetRelationshipExistingTargetParts),
                'targetRelationshipMissingTargetCount' => count($itemTargetRelationshipMissingTargetParts),
                'targetRelationshipExternalTargetCount' => count($itemTargetRelationshipExternalTargets),
                'targetRelationshipAllowedExternalTargetCount' => count($itemTargetRelationshipAllowedExternalTargets),
                'targetRelationshipUnsafeExternalTargetCount' => count($itemTargetRelationshipUnsafeExternalTargets),
                'targetRelationshipMissingContentTypeTargetCount' => count(array_filter(
                    $itemTargetRelationships,
                    static fn (array $item): bool => ($item['external'] ?? false) !== true
                        && ($item['contentTypeSource'] ?? '') === 'missing',
                )),
                'targetRelationshipIssueCount' => count(array_filter(
                    $itemTargetRelationships,
                    static fn (array $item): bool => ($item['issues'] ?? []) !== [],
                )),
                'targetRelationshipIssueCodes' => array_keys($itemTargetRelationshipIssueCodes),
                'targetRelationshipExistingTargetParts' => $itemTargetRelationshipExistingTargetParts,
                'targetRelationshipMissingTargetParts' => $itemTargetRelationshipMissingTargetParts,
                'targetRelationshipAllowedExternalTargets' => $itemTargetRelationshipAllowedExternalTargets,
                'targetRelationshipUnsafeExternalTargets' => $itemTargetRelationshipUnsafeExternalTargets,
                'targetRelationshipContentTypes' => $itemTargetRelationshipContentTypes,
                'targetRelationshipContentTypeBases' => $itemTargetRelationshipContentTypeBases,
                'targetRelationships' => $itemTargetRelationships,
                'byteLength' => $targetPart !== null && $exists ? strlen($parts[$targetPart]) : null,
                'crc32' => $targetPart !== null && $exists ? sprintf('%08x', crc32($parts[$targetPart])) : null,
                'sha256' => $targetPart !== null && $exists ? hash('sha256', $parts[$targetPart]) : null,
                'canExposeBytes' => false,
                'byteExposurePolicy' => 'package-root-relationship-bytes-blocked',
                'reviewPolicy' => 'package-root-relationship-metadata-only',
                'valid' => $issues === [],
                'issues' => $issues,
            ];

            $items[] = $item;
            $byRelationshipId[(string) $item['id']] = $item;
            $relationshipIds[] = (string) $item['id'];
            $this->appendUniqueString($relationshipTypes, is_string($item['type'] ?? null) ? $item['type'] : null);
            $this->appendUniqueString($targetParts, $targetPart);
            if ($external) {
                $this->appendUniqueString($externalTargets, is_string($summary['target'] ?? null) ? $summary['target'] : null);
            }
            $this->appendUniqueString($contentTypesSeen, is_string($summary['contentType'] ?? null) ? $summary['contentType'] : null);
            foreach ($itemTargetRelationshipTypes as $targetRelationshipType) {
                $this->appendUniqueString($targetRelationshipTypes, is_string($targetRelationshipType) ? $targetRelationshipType : null);
            }
            foreach ($itemTargetRelationshipTargetParts as $targetRelationshipTargetPart) {
                $this->appendUniqueString($targetRelationshipTargetParts, is_string($targetRelationshipTargetPart) ? $targetRelationshipTargetPart : null);
            }
            foreach ($itemTargetRelationshipExternalTargets as $targetRelationshipExternalTarget) {
                $this->appendUniqueString($targetRelationshipExternalTargets, is_string($targetRelationshipExternalTarget) ? $targetRelationshipExternalTarget : null);
            }
            foreach ($itemTargetRelationshipExistingTargetParts as $targetRelationshipExistingTargetPart) {
                $this->appendUniqueString($targetRelationshipExistingTargetParts, is_string($targetRelationshipExistingTargetPart) ? $targetRelationshipExistingTargetPart : null);
            }
            foreach ($itemTargetRelationshipMissingTargetParts as $targetRelationshipMissingTargetPart) {
                $this->appendUniqueString($targetRelationshipMissingTargetParts, is_string($targetRelationshipMissingTargetPart) ? $targetRelationshipMissingTargetPart : null);
            }
            foreach ($itemTargetRelationshipAllowedExternalTargets as $targetRelationshipAllowedExternalTarget) {
                $this->appendUniqueString($targetRelationshipAllowedExternalTargets, is_string($targetRelationshipAllowedExternalTarget) ? $targetRelationshipAllowedExternalTarget : null);
            }
            foreach ($itemTargetRelationshipUnsafeExternalTargets as $targetRelationshipUnsafeExternalTarget) {
                $this->appendUniqueString($targetRelationshipUnsafeExternalTargets, is_string($targetRelationshipUnsafeExternalTarget) ? $targetRelationshipUnsafeExternalTarget : null);
            }
            foreach ($itemTargetRelationshipContentTypes as $targetRelationshipContentType) {
                $this->appendUniqueString($targetRelationshipContentTypes, is_string($targetRelationshipContentType) ? $targetRelationshipContentType : null);
            }
            foreach ($itemTargetRelationshipContentTypeBases as $targetRelationshipContentTypeBase) {
                $this->appendUniqueString($targetRelationshipContentTypeBases, is_string($targetRelationshipContentTypeBase) ? $targetRelationshipContentTypeBase : null);
            }
            foreach (array_keys($itemTargetRelationshipIssueCodes) as $targetRelationshipIssueCode) {
                $targetRelationshipIssueCodes[$targetRelationshipIssueCode] = true;
            }
        }

        ksort($issueCodes, SORT_STRING);
        ksort($targetRelationshipIssueCodes, SORT_STRING);

        return [
            'present' => $items !== [],
            'count' => count($items),
            'existingCount' => count(array_filter(
                $items,
                static fn (array $item): bool => $item['external'] === false && $item['exists'] === true,
            )),
            'missingCount' => count(array_filter(
                $items,
                static fn (array $item): bool => $item['external'] === false && $item['exists'] === false,
            )),
            'externalCount' => count(array_filter($items, static fn (array $item): bool => $item['external'] === true)),
            'targetRelationshipCount' => count(array_filter($items, static fn (array $item): bool => $item['targetHasRelationships'] === true)),
            'targetRelationshipRecordCount' => array_sum(array_map(static fn (array $item): int => (int) ($item['targetRelationshipRecordCount'] ?? 0), $items)),
            'targetRelationshipExistingTargetCount' => array_sum(array_map(static fn (array $item): int => (int) ($item['targetRelationshipExistingTargetCount'] ?? 0), $items)),
            'targetRelationshipMissingTargetCount' => array_sum(array_map(static fn (array $item): int => (int) ($item['targetRelationshipMissingTargetCount'] ?? 0), $items)),
            'targetRelationshipExternalTargetCount' => array_sum(array_map(static fn (array $item): int => (int) ($item['targetRelationshipExternalTargetCount'] ?? 0), $items)),
            'targetRelationshipAllowedExternalTargetCount' => array_sum(array_map(static fn (array $item): int => (int) ($item['targetRelationshipAllowedExternalTargetCount'] ?? 0), $items)),
            'targetRelationshipUnsafeExternalTargetCount' => array_sum(array_map(static fn (array $item): int => (int) ($item['targetRelationshipUnsafeExternalTargetCount'] ?? 0), $items)),
            'targetRelationshipMissingContentTypeTargetCount' => array_sum(array_map(static fn (array $item): int => (int) ($item['targetRelationshipMissingContentTypeTargetCount'] ?? 0), $items)),
            'targetRelationshipIssueCount' => array_sum(array_map(static fn (array $item): int => (int) ($item['targetRelationshipIssueCount'] ?? 0), $items)),
            'issueCount' => count(array_filter($items, static fn (array $item): bool => $item['issues'] !== [])),
            'relationshipIds' => $relationshipIds,
            'relationshipTypes' => $relationshipTypes,
            'targetParts' => $targetParts,
            'externalTargets' => $externalTargets,
            'contentTypes' => $contentTypesSeen,
            'targetRelationshipTypes' => $targetRelationshipTypes,
            'targetRelationshipTargetParts' => $targetRelationshipTargetParts,
            'targetRelationshipExternalTargets' => $targetRelationshipExternalTargets,
            'targetRelationshipExistingTargetParts' => $targetRelationshipExistingTargetParts,
            'targetRelationshipMissingTargetParts' => $targetRelationshipMissingTargetParts,
            'targetRelationshipAllowedExternalTargets' => $targetRelationshipAllowedExternalTargets,
            'targetRelationshipUnsafeExternalTargets' => $targetRelationshipUnsafeExternalTargets,
            'targetRelationshipContentTypes' => $targetRelationshipContentTypes,
            'targetRelationshipContentTypeBases' => $targetRelationshipContentTypeBases,
            'targetRelationshipIssueCodes' => array_keys($targetRelationshipIssueCodes),
            'byteExposurePolicy' => 'package-root-relationship-bytes-blocked',
            'reviewPolicy' => 'package-root-relationship-metadata-only',
            'canExposeBytes' => false,
            'issueCodes' => array_keys($issueCodes),
            'byRelationshipId' => $byRelationshipId,
            'items' => $items,
        ];
    }

    /**
     * @param array<string, string> $parts
     * @param array{id:string, type:string, target:string, targetMode:string, resolvedTarget:string} $relationship
     * @param array{defaults:array<string, string>, overrides:array<string, string>} $contentTypes
     * @return array<string, mixed>
     */
    private function packageRootRelationshipTargetRelationshipItem(
        array $parts,
        array $relationship,
        string $sourcePart,
        string $relationshipsPart,
        array $contentTypes
    ): array {
        $item = $this->relationshipInventorySummary($parts, $relationship, $sourcePart, $relationshipsPart, $contentTypes);
        $issues = [];
        if (($item['external'] ?? false) === true) {
            foreach (($item['externalTargetIssues'] ?? []) as $issue) {
                if (is_string($issue) && $issue !== '') {
                    $issues[] = $issue;
                }
            }
        } else {
            if (($item['exists'] ?? false) !== true) {
                $issues[] = 'missing-package-root-target-relationship-target';
            }
            if (($item['contentTypeSource'] ?? '') === 'missing') {
                $issues[] = 'missing-package-root-target-relationship-content-type';
            }
        }

        $item['canExposeBytes'] = false;
        $item['byteExposurePolicy'] = 'package-root-target-relationship-bytes-blocked';
        $item['reviewPolicy'] = 'package-root-target-relationship-metadata-only';
        $item['valid'] = $issues === [];
        $item['issues'] = array_values(array_unique($issues));

        return $item;
    }

    /**
     * @param array<string, string> $parts
     * @param array<string, array{id:string, type:string, target:string, targetMode:string, resolvedTarget:string}> $rootRelationships
     * @param array{defaults:array<string, string>, overrides:array<string, string>} $contentTypes
     * @return array<string, mixed>
     */
    private function packageCustomUiProvenance(array $parts, array $rootRelationships, array $contentTypes): array
    {
        $items = [];
        $byRelationshipId = [];
        $relationshipIds = [];
        $relationshipTypes = [];
        $targetParts = [];
        $externalTargets = [];
        $contentTypesSeen = [];
        $rootNamespaces = [];
        $kinds = [];
        $issueCodes = [];
        $imageRelationshipCount = 0;
        $imageExistingCount = 0;
        $imageMissingCount = 0;
        $imageExternalCount = 0;
        $imageIssueCount = 0;

        foreach ($rootRelationships as $relationship) {
            if (!$this->isCustomUiRelationshipType($relationship['type'])) {
                continue;
            }

            $summary = $this->relationshipInventorySummary($parts, $relationship, '/', '_rels/.rels', $contentTypes);
            $targetPart = is_string($summary['targetPart'] ?? null) ? $summary['targetPart'] : null;
            $external = (bool) ($summary['external'] ?? false);
            $exists = (bool) ($summary['exists'] ?? false);
            $relationshipType = is_string($summary['type'] ?? null) ? $summary['type'] : '';
            $kind = $this->customUiRelationshipKind($relationshipType);
            $expectedRootNamespace = $this->customUiExpectedRootNamespace($relationshipType);
            $rootProvenance = null;
            $validXml = null;
            $validRoot = null;
            $rootNamespace = null;
            $rootLocalName = null;
            $rootQualifiedName = null;
            $rootPrefix = null;
            $rootAttributeCount = 0;
            $rootNamespaceDeclarationCount = 0;
            $rootNamespacePrefixes = [];
            $xmlParseError = null;
            $issues = [];

            if ($external) {
                $issues[] = 'external-custom-ui-target';
                $externalTargetIssues = is_array($summary['externalTargetIssues'] ?? null)
                    ? array_values(array_map('strval', $summary['externalTargetIssues']))
                    : [];
                $issues = array_merge($issues, $externalTargetIssues);
            } elseif (!$exists) {
                $issues[] = 'missing-custom-ui-part';
            } elseif ($targetPart !== null) {
                $rootProvenance = $this->xmlRootProvenance($parts[$targetPart], $targetPart);
                $validXml = $rootProvenance['validXml'];
                $xmlParseError = $rootProvenance['xmlParseError'];
                $rootNamespace = $rootProvenance['namespace'];
                $rootLocalName = $rootProvenance['localName'];
                $rootQualifiedName = $rootProvenance['qualifiedName'];
                $rootPrefix = $rootProvenance['prefix'];
                $rootAttributeCount = $rootProvenance['attributeCount'];
                $rootNamespaceDeclarationCount = $rootProvenance['namespaceDeclarationCount'];
                $rootNamespacePrefixes = $rootProvenance['namespacePrefixes'];
                $validRoot = $validXml === true
                    && $rootNamespace === $expectedRootNamespace
                    && $rootLocalName === 'customUI';

                if ($validXml !== true) {
                    $issues[] = 'invalid-custom-ui-xml';
                } elseif ($validRoot !== true) {
                    $issues[] = 'unexpected-custom-ui-root';
                }
            }

            if (!$external && ($summary['contentTypeSource'] ?? '') === 'missing') {
                $issues[] = 'missing-custom-ui-content-type';
            } elseif (
                !$external
                && $summary['contentTypeBase'] !== ''
                && $summary['contentTypeBase'] !== 'application/xml'
            ) {
                $issues[] = 'unexpected-custom-ui-content-type';
            }

            $images = $targetPart === null
                ? $this->emptyCustomUiImageRelationships(null)
                : $this->customUiImageRelationships($parts, $targetPart, $contentTypes);
            $imageRelationshipCount += $images['count'];
            $imageExistingCount += $images['existingCount'];
            $imageMissingCount += $images['missingCount'];
            $imageExternalCount += $images['externalCount'];
            $imageIssueCount += $images['issueCount'];
            foreach ($images['issueCodes'] as $imageIssueCode) {
                if (is_string($imageIssueCode) && $imageIssueCode !== '') {
                    $issueCodes[$imageIssueCode] = true;
                }
            }

            $issues = array_values(array_unique($issues));
            sort($issues, SORT_STRING);
            foreach ($issues as $issue) {
                $issueCodes[$issue] = true;
            }

            $item = [
                'source' => '/',
                'id' => $summary['id'],
                'type' => $summary['type'],
                'kind' => $kind,
                'target' => $summary['target'],
                'targetMode' => $summary['targetMode'],
                'external' => $external,
                'resolvedTarget' => $summary['resolvedTarget'],
                'targetPart' => $targetPart,
                'targetQuery' => $summary['targetQuery'],
                'targetFragment' => $summary['targetFragment'],
                'targetReferenceSuffix' => $summary['targetReferenceSuffix'],
                'targetParentTraversalCount' => $summary['targetParentTraversalCount'],
                'targetHasParentTraversal' => $summary['targetHasParentTraversal'],
                'targetStartsAtPackageRoot' => $summary['targetStartsAtPackageRoot'],
                'sameSourcePart' => $summary['sameSourcePart'],
                'externalTargetKind' => $summary['externalTargetKind'],
                'externalTargetScheme' => $summary['externalTargetScheme'],
                'externalTargetAllowed' => $summary['externalTargetAllowed'],
                'externalTargetIssues' => $summary['externalTargetIssues'],
                'exists' => $exists,
                'contentType' => $summary['contentType'],
                'contentTypeBase' => $summary['contentTypeBase'],
                'contentTypeHasParameters' => $summary['contentTypeHasParameters'],
                'contentTypeParameterCount' => $summary['contentTypeParameterCount'],
                'contentTypeParameters' => $summary['contentTypeParameters'],
                'contentTypeParameterMap' => $summary['contentTypeParameterMap'],
                'contentTypeSource' => $summary['contentTypeSource'],
                'defaultExtension' => $summary['defaultExtension'],
                'overridePartName' => $summary['overridePartName'],
                'expectedContentTypeBase' => 'application/xml',
                'expectedRootNamespace' => $expectedRootNamespace,
                'expectedRootLocalName' => 'customUI',
                'validXml' => $validXml,
                'xmlParseError' => $xmlParseError,
                'validRoot' => $validRoot,
                'rootNamespace' => $rootNamespace,
                'rootLocalName' => $rootLocalName,
                'rootQualifiedName' => $rootQualifiedName,
                'rootPrefix' => $rootPrefix,
                'rootAttributeCount' => $rootAttributeCount,
                'rootNamespaceDeclarationCount' => $rootNamespaceDeclarationCount,
                'rootNamespacePrefixes' => $rootNamespacePrefixes,
                'relationshipsPart' => '_rels/.rels',
                'targetRelationshipsPart' => $images['relationshipsPart'],
                'targetRelationshipCount' => $images['relationshipCount'],
                'imageRelationships' => $images,
                'byteLength' => $targetPart !== null && $exists ? strlen($parts[$targetPart]) : null,
                'crc32' => $targetPart !== null && $exists ? sprintf('%08x', crc32($parts[$targetPart])) : null,
                'sha256' => $targetPart !== null && $exists ? hash('sha256', $parts[$targetPart]) : null,
                'canExposeBytes' => false,
                'byteExposurePolicy' => 'custom-ui-bytes-blocked',
                'reviewPolicy' => 'custom-ui-metadata-only',
                'valid' => $issues === [] && $images['issueCount'] === 0,
                'issues' => $issues,
            ];

            $items[] = $item;
            $byRelationshipId[(string) $item['id']] = $item;
            $relationshipIds[] = (string) $item['id'];
            $this->appendUniqueString($relationshipTypes, is_string($item['type'] ?? null) ? $item['type'] : null);
            $this->appendUniqueString($targetParts, $targetPart);
            if ($external) {
                $this->appendUniqueString($externalTargets, is_string($summary['target'] ?? null) ? $summary['target'] : null);
            }
            $this->appendUniqueString($contentTypesSeen, is_string($summary['contentType'] ?? null) ? $summary['contentType'] : null);
            $this->appendUniqueString($rootNamespaces, is_string($rootNamespace) ? $rootNamespace : null);
            $this->appendUniqueString($kinds, $kind);
        }

        ksort($issueCodes, SORT_STRING);

        return [
            'present' => $items !== [],
            'count' => count($items),
            'relationshipCount' => count($items),
            'existingCount' => count(array_filter(
                $items,
                static fn (array $item): bool => $item['external'] === false && $item['exists'] === true,
            )),
            'missingCount' => count(array_filter(
                $items,
                static fn (array $item): bool => $item['external'] === false && $item['exists'] === false,
            )),
            'externalCount' => count(array_filter($items, static fn (array $item): bool => $item['external'] === true)),
            'validRootCount' => count(array_filter($items, static fn (array $item): bool => $item['validRoot'] === true)),
            'invalidRootCount' => count(array_filter($items, static fn (array $item): bool => in_array('unexpected-custom-ui-root', $item['issues'], true))),
            'invalidXmlCount' => count(array_filter($items, static fn (array $item): bool => in_array('invalid-custom-ui-xml', $item['issues'], true))),
            'imageRelationshipCount' => $imageRelationshipCount,
            'imageExistingCount' => $imageExistingCount,
            'imageMissingCount' => $imageMissingCount,
            'imageExternalCount' => $imageExternalCount,
            'imageIssueCount' => $imageIssueCount,
            'issueCount' => count(array_filter($items, static fn (array $item): bool => $item['issues'] !== [])) + $imageIssueCount,
            'relationshipIds' => $relationshipIds,
            'relationshipTypes' => $relationshipTypes,
            'targetParts' => $targetParts,
            'externalTargets' => $externalTargets,
            'contentTypes' => $contentTypesSeen,
            'rootNamespaces' => $rootNamespaces,
            'kinds' => $kinds,
            'byteExposurePolicy' => 'custom-ui-bytes-blocked',
            'reviewPolicy' => 'custom-ui-metadata-only',
            'canExposeBytes' => false,
            'issueCodes' => array_keys($issueCodes),
            'byRelationshipId' => $byRelationshipId,
            'items' => $items,
        ];
    }

    /**
     * @return array<string, mixed>
     */
    private function emptyCustomUiImageRelationships(?string $relationshipsPart): array
    {
        return [
            'relationshipsPart' => $relationshipsPart,
            'relationshipCount' => 0,
            'count' => 0,
            'existingCount' => 0,
            'missingCount' => 0,
            'externalCount' => 0,
            'unexpectedRelationshipTypeCount' => 0,
            'issueCount' => 0,
            'relationshipIds' => [],
            'targetParts' => [],
            'externalTargets' => [],
            'contentTypes' => [],
            'issueCodes' => [],
            'byteExposurePolicy' => 'custom-ui-image-bytes-blocked',
            'reviewPolicy' => 'custom-ui-image-metadata-only',
            'canExposeBytes' => false,
            'byRelationshipId' => [],
            'items' => [],
        ];
    }

    /**
     * @param array<string, string> $parts
     * @param array{defaults:array<string, string>, overrides:array<string, string>} $contentTypes
     * @return array<string, mixed>
     */
    private function customUiImageRelationships(array $parts, string $customUiPart, array $contentTypes): array
    {
        $relationshipsPart = $this->relationshipsPartFor($customUiPart);
        if (!isset($parts[$relationshipsPart])) {
            return $this->emptyCustomUiImageRelationships($relationshipsPart);
        }

        $relationships = $this->readRelationshipsPart($parts, $relationshipsPart);
        $items = [];
        $byRelationshipId = [];
        $relationshipIds = [];
        $targetParts = [];
        $externalTargets = [];
        $contentTypesSeen = [];
        $issueCodes = [];
        $unexpectedRelationshipTypeCount = 0;

        foreach ($relationships as $relationship) {
            if ($relationship['type'] !== self::IMAGE_REL) {
                ++$unexpectedRelationshipTypeCount;
                $issueCodes['unexpected-custom-ui-relationship-type'] = true;
                continue;
            }

            $item = $this->customUiImageRelationshipItem(
                $parts,
                $relationship,
                $customUiPart,
                $relationshipsPart,
                $contentTypes,
                count($items),
            );
            $items[] = $item;
            $byRelationshipId[(string) $item['relationshipId']] = $item;
            $relationshipIds[] = (string) $item['relationshipId'];
            $this->appendUniqueString($targetParts, is_string($item['targetPart'] ?? null) ? $item['targetPart'] : null);
            if (($item['external'] ?? false) === true) {
                $this->appendUniqueString($externalTargets, is_string($item['target'] ?? null) ? $item['target'] : null);
            }
            $this->appendUniqueString($contentTypesSeen, is_string($item['contentType'] ?? null) ? $item['contentType'] : null);
            foreach (($item['issues'] ?? []) as $issue) {
                if (is_string($issue) && $issue !== '') {
                    $issueCodes[$issue] = true;
                }
            }
        }

        ksort($issueCodes, SORT_STRING);

        return [
            'relationshipsPart' => $relationshipsPart,
            'relationshipCount' => count($relationships),
            'count' => count($items),
            'existingCount' => count(array_filter(
                $items,
                static fn (array $item): bool => $item['external'] === false && $item['exists'] === true,
            )),
            'missingCount' => count(array_filter(
                $items,
                static fn (array $item): bool => $item['external'] === false && $item['exists'] === false,
            )),
            'externalCount' => count(array_filter($items, static fn (array $item): bool => $item['external'] === true)),
            'unexpectedRelationshipTypeCount' => $unexpectedRelationshipTypeCount,
            'issueCount' => count(array_filter($items, static fn (array $item): bool => $item['issues'] !== [])) + $unexpectedRelationshipTypeCount,
            'relationshipIds' => $relationshipIds,
            'targetParts' => $targetParts,
            'externalTargets' => $externalTargets,
            'contentTypes' => $contentTypesSeen,
            'issueCodes' => array_keys($issueCodes),
            'byteExposurePolicy' => 'custom-ui-image-bytes-blocked',
            'reviewPolicy' => 'custom-ui-image-metadata-only',
            'canExposeBytes' => false,
            'byRelationshipId' => $byRelationshipId,
            'items' => $items,
        ];
    }

    /**
     * @param array<string, string> $parts
     * @param array{id:string, type:string, target:string, targetMode:string, resolvedTarget:string} $relationship
     * @param array{defaults:array<string, string>, overrides:array<string, string>} $contentTypes
     * @return array<string, mixed>
     */
    private function customUiImageRelationshipItem(
        array $parts,
        array $relationship,
        string $customUiPart,
        string $relationshipsPart,
        array $contentTypes,
        int $index,
    ): array {
        $summary = $this->relationshipInventorySummary($parts, $relationship, $customUiPart, $relationshipsPart, $contentTypes);
        $targetPart = is_string($summary['targetPart'] ?? null) ? $summary['targetPart'] : null;
        $exists = (bool) ($summary['exists'] ?? false);
        $external = (bool) ($summary['external'] ?? false);
        $issues = [];

        if ($external) {
            $issues[] = 'external-custom-ui-image';
            $externalTargetIssues = is_array($summary['externalTargetIssues'] ?? null)
                ? array_values(array_map('strval', $summary['externalTargetIssues']))
                : [];
            $issues = array_merge($issues, $externalTargetIssues);
        } elseif (!$exists) {
            $issues[] = 'missing-custom-ui-image';
        }
        if (!$external && ($summary['contentTypeSource'] ?? '') === 'missing') {
            $issues[] = 'missing-custom-ui-image-content-type';
        } elseif (!$external && $summary['contentTypeBase'] !== '' && !$this->isImageContentType((string) $summary['contentTypeBase'])) {
            $issues[] = 'unexpected-custom-ui-image-content-type';
        }

        $issues = array_values(array_unique($issues));
        sort($issues, SORT_STRING);

        return [
            'index' => $index,
            'sourcePart' => $customUiPart,
            'relationshipsPart' => $relationshipsPart,
            'relationshipId' => $summary['id'],
            'type' => $summary['type'],
            'target' => $summary['target'],
            'targetMode' => $summary['targetMode'],
            'external' => $external,
            'resolvedTarget' => $summary['resolvedTarget'],
            'targetPart' => $targetPart,
            'targetQuery' => $summary['targetQuery'],
            'targetFragment' => $summary['targetFragment'],
            'targetReferenceSuffix' => $summary['targetReferenceSuffix'],
            'targetParentTraversalCount' => $summary['targetParentTraversalCount'],
            'targetHasParentTraversal' => $summary['targetHasParentTraversal'],
            'targetStartsAtPackageRoot' => $summary['targetStartsAtPackageRoot'],
            'sameSourcePart' => $summary['sameSourcePart'],
            'externalTargetKind' => $summary['externalTargetKind'],
            'externalTargetScheme' => $summary['externalTargetScheme'],
            'externalTargetAllowed' => $summary['externalTargetAllowed'],
            'externalTargetIssues' => $summary['externalTargetIssues'],
            'exists' => $exists,
            'contentType' => $summary['contentType'],
            'contentTypeBase' => $summary['contentTypeBase'],
            'contentTypeHasParameters' => $summary['contentTypeHasParameters'],
            'contentTypeParameterCount' => $summary['contentTypeParameterCount'],
            'contentTypeParameters' => $summary['contentTypeParameters'],
            'contentTypeParameterMap' => $summary['contentTypeParameterMap'],
            'contentTypeSource' => $summary['contentTypeSource'],
            'defaultExtension' => $summary['defaultExtension'],
            'overridePartName' => $summary['overridePartName'],
            'byteLength' => $targetPart !== null && $exists ? strlen($parts[$targetPart]) : null,
            'crc32' => $targetPart !== null && $exists ? sprintf('%08x', crc32($parts[$targetPart])) : null,
            'sha256' => $targetPart !== null && $exists ? hash('sha256', $parts[$targetPart]) : null,
            'canExposeBytes' => false,
            'byteExposurePolicy' => 'custom-ui-image-bytes-blocked',
            'reviewPolicy' => 'custom-ui-image-metadata-only',
            'valid' => $issues === [],
            'issues' => $issues,
        ];
    }

    private function isCustomUiRelationshipType(string $relationshipType): bool
    {
        return $relationshipType === self::CUSTOM_UI_REL
            || $relationshipType === self::CUSTOM_UI2_REL
            || $relationshipType === self::CUSTOM_UI_QAT_REL;
    }

    private function customUiRelationshipKind(string $relationshipType): string
    {
        return match ($relationshipType) {
            self::CUSTOM_UI2_REL => 'ribbon-custom-ui2',
            self::CUSTOM_UI_QAT_REL => 'quick-access-toolbar',
            default => 'ribbon-custom-ui',
        };
    }

    private function customUiExpectedRootNamespace(string $relationshipType): string
    {
        return $relationshipType === self::CUSTOM_UI2_REL ? self::NS_CUSTOM_UI2 : self::NS_CUSTOM_UI;
    }

    /**
     * @param array<string, string> $parts
     * @param array<string, array{id:string, type:string, target:string, targetMode:string, resolvedTarget:string}> $rootRelationships
     * @param array{defaults:array<string, string>, overrides:array<string, string>} $contentTypes
     * @return array<string, mixed>
     */
    private function packageDigitalSignatureProvenance(array $parts, array $rootRelationships, array $contentTypes): array
    {
        $originRelationships = [];
        foreach ($rootRelationships as $relationship) {
            if ($relationship['type'] === self::DIGITAL_SIGNATURE_ORIGIN_REL) {
                $originRelationships[] = $relationship;
            }
        }

        $origins = [];
        $signatures = [];
        $byOriginRelationshipId = [];
        $bySignatureRelationshipId = [];
        $originRelationshipIds = [];
        $signatureRelationshipIds = [];
        $originParts = [];
        $signatureParts = [];
        $originSha256s = [];
        $signatureSha256s = [];
        $externalTargets = [];
        $contentTypesSeen = [];
        $issueCodes = [];

        foreach ($originRelationships as $relationship) {
            $origin = $this->digitalSignatureOriginItem($parts, $relationship, $contentTypes, count($origins));
            $origins[] = $origin;
            $byOriginRelationshipId[(string) $origin['id']] = $origin;
            $originRelationshipIds[] = (string) $origin['id'];
            $this->appendUniqueString($originParts, is_string($origin['targetPart'] ?? null) ? $origin['targetPart'] : null);
            $this->appendUniqueString($originSha256s, is_string($origin['sha256'] ?? null) ? $origin['sha256'] : null);
            $this->appendUniqueString($contentTypesSeen, is_string($origin['contentType'] ?? null) ? $origin['contentType'] : null);
            if (($origin['external'] ?? false) === true) {
                $this->appendUniqueString($externalTargets, is_string($origin['target'] ?? null) ? $origin['target'] : null);
            }
            foreach (($origin['issues'] ?? []) as $issue) {
                $issueCodes[(string) $issue] = true;
            }

            foreach (($origin['signatures']['items'] ?? []) as $signature) {
                if (!is_array($signature)) {
                    continue;
                }
                $signatures[] = $signature;
                $bySignatureRelationshipId[(string) $signature['id']] = $signature;
                $signatureRelationshipIds[] = (string) $signature['id'];
                $this->appendUniqueString($signatureParts, is_string($signature['targetPart'] ?? null) ? $signature['targetPart'] : null);
                $this->appendUniqueString($signatureSha256s, is_string($signature['sha256'] ?? null) ? $signature['sha256'] : null);
                $this->appendUniqueString($contentTypesSeen, is_string($signature['contentType'] ?? null) ? $signature['contentType'] : null);
                if (($signature['external'] ?? false) === true) {
                    $this->appendUniqueString($externalTargets, is_string($signature['target'] ?? null) ? $signature['target'] : null);
                }
                foreach (($signature['issues'] ?? []) as $issue) {
                    $issueCodes[(string) $issue] = true;
                }
            }
        }

        ksort($issueCodes, SORT_STRING);

        $referenceUriKindCounts = [];
        $referenceUris = [];
        $referenceTransformAlgorithms = [];
        $digestMethodAlgorithms = [];
        $signatureMethodAlgorithms = [];
        $canonicalizationMethodAlgorithms = [];
        $referenceCount = 0;
        $packageReferenceCount = 0;
        $sameDocumentReferenceCount = 0;
        $externalReferenceCount = 0;
        $relativeReferenceCount = 0;
        $emptyReferenceCount = 0;
        $referenceTransformCount = 0;
        $referenceDigestValueCount = 0;
        $referenceDigestValueMissingCount = 0;
        $signatureValuePresentCount = 0;
        foreach ($signatures as $signature) {
            $referenceCount += (int) ($signature['referenceCount'] ?? 0);
            $packageReferenceCount += (int) ($signature['packageReferenceCount'] ?? 0);
            $sameDocumentReferenceCount += (int) ($signature['sameDocumentReferenceCount'] ?? 0);
            $externalReferenceCount += (int) ($signature['externalReferenceCount'] ?? 0);
            $relativeReferenceCount += (int) ($signature['relativeReferenceCount'] ?? 0);
            $emptyReferenceCount += (int) ($signature['emptyReferenceCount'] ?? 0);
            $referenceTransformCount += (int) ($signature['referenceTransformCount'] ?? 0);
            $referenceDigestValueCount += (int) ($signature['referenceDigestValueCount'] ?? 0);
            $referenceDigestValueMissingCount += (int) ($signature['referenceDigestValueMissingCount'] ?? 0);
            if (($signature['hasSignatureValue'] ?? false) === true) {
                ++$signatureValuePresentCount;
            }

            foreach (($signature['referenceUriKindCounts'] ?? []) as $kind => $count) {
                if (!is_string($kind) || $kind === '') {
                    continue;
                }
                $referenceUriKindCounts[$kind] = ($referenceUriKindCounts[$kind] ?? 0) + (int) $count;
            }
            foreach (($signature['referenceUris'] ?? []) as $uri) {
                $this->appendUniqueString($referenceUris, is_string($uri) ? $uri : null);
            }
            foreach (($signature['referenceTransformAlgorithms'] ?? []) as $algorithm) {
                $this->appendUniqueString($referenceTransformAlgorithms, is_string($algorithm) ? $algorithm : null);
            }
            foreach (($signature['digestMethodAlgorithms'] ?? []) as $algorithm) {
                $this->appendUniqueString($digestMethodAlgorithms, is_string($algorithm) ? $algorithm : null);
            }
            foreach (($signature['signatureMethodAlgorithms'] ?? []) as $algorithm) {
                $this->appendUniqueString($signatureMethodAlgorithms, is_string($algorithm) ? $algorithm : null);
            }
            foreach (($signature['canonicalizationMethodAlgorithms'] ?? []) as $algorithm) {
                $this->appendUniqueString($canonicalizationMethodAlgorithms, is_string($algorithm) ? $algorithm : null);
            }
        }
        ksort($referenceUriKindCounts, SORT_STRING);

        return [
            'present' => $origins !== [],
            'originCount' => count($origins),
            'existingOriginCount' => count(array_filter(
                $origins,
                static fn (array $origin): bool => $origin['external'] === false && $origin['exists'] === true,
            )),
            'missingOriginCount' => count(array_filter(
                $origins,
                static fn (array $origin): bool => $origin['external'] === false && $origin['exists'] === false,
            )),
            'externalOriginCount' => count(array_filter($origins, static fn (array $origin): bool => $origin['external'] === true)),
            'signatureCount' => count($signatures),
            'existingSignatureCount' => count(array_filter(
                $signatures,
                static fn (array $signature): bool => $signature['external'] === false && $signature['exists'] === true,
            )),
            'missingSignatureCount' => count(array_filter(
                $signatures,
                static fn (array $signature): bool => $signature['external'] === false && $signature['exists'] === false,
            )),
            'externalSignatureCount' => count(array_filter($signatures, static fn (array $signature): bool => $signature['external'] === true)),
            'invalidSignatureXmlCount' => count(array_filter(
                $signatures,
                static fn (array $signature): bool => in_array('invalid-signature-xml', $signature['issues'], true),
            )),
            'unexpectedSignatureRootCount' => count(array_filter(
                $signatures,
                static fn (array $signature): bool => in_array('unexpected-signature-root', $signature['issues'], true),
            )),
            'issueCount' => count(array_filter(
                array_merge($origins, $signatures),
                static fn (array $item): bool => $item['issues'] !== [],
            )),
            'originRelationshipIds' => $originRelationshipIds,
            'signatureRelationshipIds' => $signatureRelationshipIds,
            'originParts' => $originParts,
            'signatureParts' => $signatureParts,
            'originSha256Count' => count($originSha256s),
            'signatureSha256Count' => count($signatureSha256s),
            'originSha256s' => $originSha256s,
            'signatureSha256s' => $signatureSha256s,
            'externalTargets' => $externalTargets,
            'contentTypes' => $contentTypesSeen,
            'issueCodes' => array_keys($issueCodes),
            'referenceCount' => $referenceCount,
            'referenceUriKindCounts' => $referenceUriKindCounts,
            'referenceUris' => $referenceUris,
            'packageReferenceCount' => $packageReferenceCount,
            'sameDocumentReferenceCount' => $sameDocumentReferenceCount,
            'externalReferenceCount' => $externalReferenceCount,
            'relativeReferenceCount' => $relativeReferenceCount,
            'emptyReferenceCount' => $emptyReferenceCount,
            'referenceTransformCount' => $referenceTransformCount,
            'referenceTransformAlgorithms' => $referenceTransformAlgorithms,
            'referenceDigestValueCount' => $referenceDigestValueCount,
            'referenceDigestValueMissingCount' => $referenceDigestValueMissingCount,
            'digestMethodAlgorithms' => $digestMethodAlgorithms,
            'signatureMethodAlgorithms' => $signatureMethodAlgorithms,
            'canonicalizationMethodAlgorithms' => $canonicalizationMethodAlgorithms,
            'signatureValuePresentCount' => $signatureValuePresentCount,
            'byOriginRelationshipId' => $byOriginRelationshipId,
            'bySignatureRelationshipId' => $bySignatureRelationshipId,
            'origins' => $origins,
            'signatures' => $signatures,
            'cryptographicValidation' => false,
            'reviewPolicy' => 'digital-signature-metadata-only',
        ];
    }

    /**
     * @param array<string, string> $parts
     * @param array{id:string, type:string, target:string, targetMode:string, resolvedTarget:string} $relationship
     * @param array{defaults:array<string, string>, overrides:array<string, string>} $contentTypes
     * @return array<string, mixed>
     */
    private function digitalSignatureOriginItem(array $parts, array $relationship, array $contentTypes, int $index): array
    {
        $summary = $this->relationshipInventorySummary($parts, $relationship, '/', '_rels/.rels', $contentTypes);
        $targetPart = is_string($summary['targetPart'] ?? null) ? $summary['targetPart'] : null;
        $external = (bool) ($summary['external'] ?? false);
        $exists = (bool) ($summary['exists'] ?? false);
        $relationshipsPart = $targetPart === null ? null : $this->relationshipsPartFor($targetPart);
        $relationships = $relationshipsPart === null ? [] : $this->readRelationshipsPart($parts, $relationshipsPart);
        $contentTypeBase = is_string($summary['contentTypeBase'] ?? null) ? $summary['contentTypeBase'] : '';
        $issues = [];

        if ($external) {
            $issues[] = 'external-signature-origin';
        } elseif (!$exists) {
            $issues[] = 'missing-origin-part';
        }
        if (!$external && ($summary['contentTypeSource'] ?? '') === 'missing') {
            $issues[] = 'missing-origin-content-type';
        } elseif (!$external && $contentTypeBase !== '' && $contentTypeBase !== self::CT_DIGITAL_SIGNATURE_ORIGIN) {
            $issues[] = 'unexpected-origin-content-type';
        }
        if (!$external && $exists && $relationshipsPart !== null && !isset($parts[$relationshipsPart])) {
            $issues[] = 'missing-origin-relationships';
        }

        $signatures = $this->digitalSignatureParts(
            $parts,
            $targetPart,
            $relationshipsPart,
            $relationships,
            $contentTypes,
        );

        return [
            'index' => $index,
            'source' => '/',
            'id' => $summary['id'],
            'type' => $summary['type'],
            'target' => $summary['target'],
            'targetMode' => $summary['targetMode'],
            'resolvedTarget' => $summary['resolvedTarget'],
            'targetPart' => $targetPart,
            'targetQuery' => $summary['targetQuery'],
            'targetFragment' => $summary['targetFragment'],
            'targetReferenceSuffix' => $summary['targetReferenceSuffix'],
            'contentType' => $summary['contentType'],
            'contentTypeBase' => $summary['contentTypeBase'],
            'contentTypeHasParameters' => $summary['contentTypeHasParameters'],
            'contentTypeParameterCount' => $summary['contentTypeParameterCount'],
            'contentTypeParameters' => $summary['contentTypeParameters'],
            'contentTypeParameterMap' => $summary['contentTypeParameterMap'],
            'contentTypeSource' => $summary['contentTypeSource'],
            'defaultExtension' => $summary['defaultExtension'],
            'overridePartName' => $summary['overridePartName'],
            'expectedContentTypeBase' => self::CT_DIGITAL_SIGNATURE_ORIGIN,
            'external' => $external,
            'exists' => $exists,
            'relationshipsPart' => '_rels/.rels',
            'originRelationshipsPart' => $relationshipsPart,
            'originRelationshipCount' => count($relationships),
            'byteLength' => $targetPart !== null && $exists ? strlen($parts[$targetPart]) : null,
            'crc32' => $targetPart !== null && $exists ? sprintf('%08x', crc32($parts[$targetPart])) : null,
            'sha256' => $targetPart !== null && $exists ? hash('sha256', $parts[$targetPart]) : null,
            'signatures' => $signatures,
            'signatureCount' => $signatures['count'],
            'signatureIssueCount' => $signatures['issueCount'],
            'cryptographicValidation' => false,
            'reviewPolicy' => 'digital-signature-metadata-only',
            'valid' => $issues === [],
            'issues' => $issues,
            'relationship' => $summary,
        ];
    }

    /**
     * @param array<string, string> $parts
     * @param array<string, array{id:string, type:string, target:string, targetMode:string, resolvedTarget:string}> $relationships
     * @param array{defaults:array<string, string>, overrides:array<string, string>} $contentTypes
     * @return array<string, mixed>
     */
    private function digitalSignatureParts(
        array $parts,
        ?string $sourcePart,
        ?string $relationshipsPart,
        array $relationships,
        array $contentTypes,
    ): array {
        if ($sourcePart === null || $relationshipsPart === null) {
            return [
                'count' => 0,
                'existingCount' => 0,
                'missingCount' => 0,
                'externalCount' => 0,
                'invalidXmlCount' => 0,
                'unexpectedRootCount' => 0,
                'issueCount' => 0,
                'relationshipIds' => [],
                'partNames' => [],
                'externalTargets' => [],
                'contentTypes' => [],
                'issueCodes' => [],
                'byRelationshipId' => [],
                'items' => [],
            ];
        }

        $items = [];
        $byRelationshipId = [];
        $relationshipIds = [];
        $partNames = [];
        $externalTargets = [];
        $contentTypesSeen = [];
        $issueCodes = [];

        foreach ($relationships as $relationship) {
            if ($relationship['type'] !== self::DIGITAL_SIGNATURE_SIGNATURE_REL) {
                continue;
            }

            $item = $this->digitalSignaturePartItem(
                $parts,
                $relationship,
                $sourcePart,
                $relationshipsPart,
                $contentTypes,
                count($items),
            );
            $items[] = $item;
            $byRelationshipId[(string) $item['id']] = $item;
            $relationshipIds[] = (string) $item['id'];
            $this->appendUniqueString($partNames, is_string($item['targetPart'] ?? null) ? $item['targetPart'] : null);
            $this->appendUniqueString($contentTypesSeen, is_string($item['contentType'] ?? null) ? $item['contentType'] : null);
            if (($item['external'] ?? false) === true) {
                $this->appendUniqueString($externalTargets, is_string($item['target'] ?? null) ? $item['target'] : null);
            }
            foreach (($item['issues'] ?? []) as $issue) {
                $issueCodes[(string) $issue] = true;
            }
        }

        ksort($issueCodes, SORT_STRING);

        return [
            'count' => count($items),
            'existingCount' => count(array_filter(
                $items,
                static fn (array $item): bool => $item['external'] === false && $item['exists'] === true,
            )),
            'missingCount' => count(array_filter(
                $items,
                static fn (array $item): bool => $item['external'] === false && $item['exists'] === false,
            )),
            'externalCount' => count(array_filter($items, static fn (array $item): bool => $item['external'] === true)),
            'invalidXmlCount' => count(array_filter(
                $items,
                static fn (array $item): bool => in_array('invalid-signature-xml', $item['issues'], true),
            )),
            'unexpectedRootCount' => count(array_filter(
                $items,
                static fn (array $item): bool => in_array('unexpected-signature-root', $item['issues'], true),
            )),
            'issueCount' => count(array_filter($items, static fn (array $item): bool => $item['issues'] !== [])),
            'relationshipIds' => $relationshipIds,
            'partNames' => $partNames,
            'externalTargets' => $externalTargets,
            'contentTypes' => $contentTypesSeen,
            'issueCodes' => array_keys($issueCodes),
            'byRelationshipId' => $byRelationshipId,
            'items' => $items,
        ];
    }

    /**
     * @param array<string, string> $parts
     * @param array{id:string, type:string, target:string, targetMode:string, resolvedTarget:string} $relationship
     * @param array{defaults:array<string, string>, overrides:array<string, string>} $contentTypes
     * @return array<string, mixed>
     */
    private function digitalSignaturePartItem(
        array $parts,
        array $relationship,
        string $sourcePart,
        string $relationshipsPart,
        array $contentTypes,
        int $index,
    ): array {
        $summary = $this->relationshipInventorySummary($parts, $relationship, $sourcePart, $relationshipsPart, $contentTypes);
        $targetPart = is_string($summary['targetPart'] ?? null) ? $summary['targetPart'] : null;
        $external = (bool) ($summary['external'] ?? false);
        $exists = (bool) ($summary['exists'] ?? false);
        $contentTypeBase = is_string($summary['contentTypeBase'] ?? null) ? $summary['contentTypeBase'] : '';
        $issues = [];

        if ($external) {
            $issues[] = 'external-signature-target';
        } elseif (!$exists) {
            $issues[] = 'missing-signature-part';
        }
        if (!$external && ($summary['contentTypeSource'] ?? '') === 'missing') {
            $issues[] = 'missing-signature-content-type';
        } elseif (!$external && $contentTypeBase !== '' && $contentTypeBase !== self::CT_DIGITAL_SIGNATURE_XMLSIGNATURE) {
            $issues[] = 'unexpected-signature-content-type';
        }

        $metadata = $this->emptyDigitalSignatureXmlMetadata();
        if ($exists && $targetPart !== null) {
            $metadata = $this->digitalSignatureXmlMetadata($parts[$targetPart], $targetPart);
            if ($metadata['validXml'] === false) {
                $issues[] = 'invalid-signature-xml';
            } elseif ($metadata['validRoot'] === false) {
                $issues[] = 'unexpected-signature-root';
            }
        }

        return [
            'index' => $index,
            'source' => $sourcePart,
            'id' => $summary['id'],
            'type' => $summary['type'],
            'target' => $summary['target'],
            'targetMode' => $summary['targetMode'],
            'resolvedTarget' => $summary['resolvedTarget'],
            'targetPart' => $targetPart,
            'targetQuery' => $summary['targetQuery'],
            'targetFragment' => $summary['targetFragment'],
            'targetReferenceSuffix' => $summary['targetReferenceSuffix'],
            'contentType' => $summary['contentType'],
            'contentTypeBase' => $summary['contentTypeBase'],
            'contentTypeHasParameters' => $summary['contentTypeHasParameters'],
            'contentTypeParameterCount' => $summary['contentTypeParameterCount'],
            'contentTypeParameters' => $summary['contentTypeParameters'],
            'contentTypeParameterMap' => $summary['contentTypeParameterMap'],
            'contentTypeSource' => $summary['contentTypeSource'],
            'defaultExtension' => $summary['defaultExtension'],
            'overridePartName' => $summary['overridePartName'],
            'expectedContentTypeBase' => self::CT_DIGITAL_SIGNATURE_XMLSIGNATURE,
            'external' => $external,
            'exists' => $exists,
            'relationshipsPart' => $relationshipsPart,
            'byteLength' => $targetPart !== null && $exists ? strlen($parts[$targetPart]) : null,
            'crc32' => $targetPart !== null && $exists ? sprintf('%08x', crc32($parts[$targetPart])) : null,
            'sha256' => $targetPart !== null && $exists ? hash('sha256', $parts[$targetPart]) : null,
            'validXml' => $metadata['validXml'],
            'xmlParseError' => $metadata['xmlParseError'],
            'rootNamespace' => $metadata['rootNamespace'],
            'rootLocalName' => $metadata['rootLocalName'],
            'validRoot' => $metadata['validRoot'],
            'referenceCount' => $metadata['referenceCount'],
            'referenceUris' => $metadata['referenceUris'],
            'references' => $metadata['references'],
            'referenceUriKindCounts' => $metadata['referenceUriKindCounts'],
            'packageReferenceCount' => $metadata['packageReferenceCount'],
            'sameDocumentReferenceCount' => $metadata['sameDocumentReferenceCount'],
            'externalReferenceCount' => $metadata['externalReferenceCount'],
            'relativeReferenceCount' => $metadata['relativeReferenceCount'],
            'emptyReferenceCount' => $metadata['emptyReferenceCount'],
            'referenceTransformCount' => $metadata['referenceTransformCount'],
            'referenceTransformAlgorithms' => $metadata['referenceTransformAlgorithms'],
            'referenceDigestValueCount' => $metadata['referenceDigestValueCount'],
            'referenceDigestValueMissingCount' => $metadata['referenceDigestValueMissingCount'],
            'digestMethodAlgorithms' => $metadata['digestMethodAlgorithms'],
            'signatureMethodAlgorithms' => $metadata['signatureMethodAlgorithms'],
            'canonicalizationMethodAlgorithms' => $metadata['canonicalizationMethodAlgorithms'],
            'hasSignatureValue' => $metadata['hasSignatureValue'],
            'cryptographicValidation' => false,
            'reviewPolicy' => 'digital-signature-metadata-only',
            'valid' => $issues === [],
            'issues' => $issues,
            'relationship' => $summary,
        ];
    }

    /**
     * @return array<string, mixed>
     */
    private function emptyDigitalSignatureXmlMetadata(): array
    {
        return [
            'validXml' => null,
            'xmlParseError' => null,
            'rootNamespace' => null,
            'rootLocalName' => null,
            'validRoot' => null,
            'referenceCount' => 0,
            'referenceUris' => [],
            'references' => [],
            'referenceUriKindCounts' => [],
            'packageReferenceCount' => 0,
            'sameDocumentReferenceCount' => 0,
            'externalReferenceCount' => 0,
            'relativeReferenceCount' => 0,
            'emptyReferenceCount' => 0,
            'referenceTransformCount' => 0,
            'referenceTransformAlgorithms' => [],
            'referenceDigestValueCount' => 0,
            'referenceDigestValueMissingCount' => 0,
            'digestMethodAlgorithms' => [],
            'signatureMethodAlgorithms' => [],
            'canonicalizationMethodAlgorithms' => [],
            'hasSignatureValue' => null,
        ];
    }

    /**
     * @return array<string, mixed>
     */
    private function digitalSignatureXmlMetadata(string $xml, string $partName): array
    {
        $metadata = $this->emptyDigitalSignatureXmlMetadata();
        $dom = $this->loadXmlForProvenance($xml, $partName);
        if (!$dom instanceof \DOMDocument) {
            $metadata['validXml'] = false;
            $metadata['xmlParseError'] = $this->lastXmlPreflightError($xml, $partName);

            return $metadata;
        }

        $root = $dom->documentElement;
        $metadata['validXml'] = $root instanceof \DOMElement;
        $metadata['xmlParseError'] = null;
        $metadata['rootNamespace'] = $root instanceof \DOMElement ? $root->namespaceURI : null;
        $metadata['rootLocalName'] = $root instanceof \DOMElement ? $root->localName : null;
        $metadata['validRoot'] = $root instanceof \DOMElement
            && $root->namespaceURI === self::NS_XMLDSIG
            && $root->localName === 'Signature';

        if ($metadata['validRoot'] !== true || !$root instanceof \DOMElement) {
            return $metadata;
        }

        $metadata['referenceCount'] = 0;
        foreach ($root->getElementsByTagNameNS(self::NS_XMLDSIG, 'Reference') as $reference) {
            if (!$reference instanceof \DOMElement) {
                continue;
            }

            $item = $this->digitalSignatureReferenceMetadata($reference, $metadata['referenceCount']);
            ++$metadata['referenceCount'];
            $metadata['references'][] = $item;
            $metadata['referenceUriKindCounts'][$item['uriKind']] =
                ($metadata['referenceUriKindCounts'][$item['uriKind']] ?? 0) + 1;
            $this->appendUniqueString($metadata['referenceUris'], $item['uri']);
            if ($item['uriKind'] === 'package-part') {
                ++$metadata['packageReferenceCount'];
            } elseif ($item['uriKind'] === 'same-document') {
                ++$metadata['sameDocumentReferenceCount'];
            } elseif ($item['uriKind'] === 'external') {
                ++$metadata['externalReferenceCount'];
            } elseif ($item['uriKind'] === 'relative') {
                ++$metadata['relativeReferenceCount'];
            } elseif ($item['uriKind'] === 'empty') {
                ++$metadata['emptyReferenceCount'];
            }
            $metadata['referenceTransformCount'] += $item['transformCount'];
            foreach ($item['transformAlgorithms'] as $algorithm) {
                $this->appendUniqueString($metadata['referenceTransformAlgorithms'], $algorithm);
            }
            if ($item['digestMethodAlgorithm'] !== null) {
                $this->appendUniqueString($metadata['digestMethodAlgorithms'], $item['digestMethodAlgorithm']);
            }
            if ($item['digestValuePresent']) {
                ++$metadata['referenceDigestValueCount'];
            } else {
                ++$metadata['referenceDigestValueMissingCount'];
            }
        }
        ksort($metadata['referenceUriKindCounts'], SORT_STRING);

        foreach ($root->getElementsByTagNameNS(self::NS_XMLDSIG, 'SignatureMethod') as $signatureMethod) {
            if ($signatureMethod instanceof \DOMElement) {
                $this->appendUniqueString($metadata['signatureMethodAlgorithms'], $signatureMethod->getAttribute('Algorithm'));
            }
        }

        foreach ($root->getElementsByTagNameNS(self::NS_XMLDSIG, 'CanonicalizationMethod') as $canonicalizationMethod) {
            if ($canonicalizationMethod instanceof \DOMElement) {
                $this->appendUniqueString($metadata['canonicalizationMethodAlgorithms'], $canonicalizationMethod->getAttribute('Algorithm'));
            }
        }

        $metadata['hasSignatureValue'] = false;
        foreach ($root->getElementsByTagNameNS(self::NS_XMLDSIG, 'SignatureValue') as $signatureValue) {
            if ($signatureValue instanceof \DOMElement && trim($signatureValue->textContent) !== '') {
                $metadata['hasSignatureValue'] = true;
                break;
            }
        }

        return $metadata;
    }

    /**
     * @return array<string, mixed>
     */
    private function digitalSignatureReferenceMetadata(\DOMElement $reference, int $index): array
    {
        $uri = $reference->getAttribute('URI');
        $uriKind = $this->digitalSignatureReferenceUriKind($uri);
        $suffix = $this->targetReferenceSuffix($uri);
        $transforms = [];
        foreach ($reference->getElementsByTagNameNS(self::NS_XMLDSIG, 'Transform') as $transform) {
            if ($transform instanceof \DOMElement) {
                $this->appendUniqueString($transforms, $transform->getAttribute('Algorithm'));
            }
        }

        $digestMethod = $this->firstChildElementByNamespace($reference, self::NS_XMLDSIG, 'DigestMethod');
        $digestValue = $this->firstChildElementByNamespace($reference, self::NS_XMLDSIG, 'DigestValue');
        $digestValueText = $digestValue instanceof \DOMElement ? trim($digestValue->textContent) : '';

        return [
            'index' => $index,
            'uri' => $uri,
            'uriKind' => $uriKind,
            'targetPart' => $uriKind === 'package-part' ? $this->stripQueryAndFragment($uri) : null,
            'targetQuery' => $suffix['query'],
            'targetFragment' => $suffix['fragment'],
            'targetReferenceSuffix' => $suffix['suffix'],
            'external' => $uriKind === 'external',
            'sameDocument' => $uriKind === 'same-document' || $uriKind === 'empty',
            'startsAtPackageRoot' => str_starts_with($uri, '/'),
            'transformCount' => count($transforms),
            'transformAlgorithms' => $transforms,
            'digestMethodAlgorithm' => $digestMethod instanceof \DOMElement
                ? $this->emptyStringToNull($digestMethod->getAttribute('Algorithm'))
                : null,
            'digestValuePresent' => $digestValueText !== '',
            'digestValueLength' => strlen($digestValueText),
        ];
    }

    private function digitalSignatureReferenceUriKind(string $uri): string
    {
        $trimmed = trim($uri);
        if ($trimmed === '') {
            return 'empty';
        }
        if (str_starts_with($trimmed, '#')) {
            return 'same-document';
        }
        if (
            str_starts_with($trimmed, '//')
            || preg_match('/^[A-Za-z][A-Za-z0-9+.-]*:/', $trimmed) === 1
        ) {
            return 'external';
        }
        if (str_starts_with($trimmed, '/')) {
            return 'package-part';
        }

        return 'relative';
    }

    private function firstChildElementByNamespace(\DOMElement $parent, string $namespace, string $localName): ?\DOMElement
    {
        foreach ($parent->childNodes as $child) {
            if ($child instanceof \DOMElement && $child->namespaceURI === $namespace && $child->localName === $localName) {
                return $child;
            }
        }

        return null;
    }

    private function firstDescendantElementByNamespace(\DOMElement $parent, string $namespace, string $localName): ?\DOMElement
    {
        foreach ($parent->getElementsByTagNameNS($namespace, $localName) as $candidate) {
            if ($candidate instanceof \DOMElement) {
                return $candidate;
            }
        }

        return null;
    }

    /**
     * @param array{id:string, type:string, target:string, targetMode:string, resolvedTarget:string}|null $relationship
     * @return array<string, mixed>
     */
    private function selectedXmlPartDefinition(
        string $kind,
        string $partName,
        string $xml,
        bool $exists,
        ?array $relationship,
        string $relationshipSourcePart,
        string $relationshipsPart,
        bool $required,
        string $expectedRootNamespace,
        string $expectedRootLocalName,
        string $expectedContentTypeBase,
        array $expectedAlternativeContentTypeBases = [],
    ): array {
        $expectedContentTypeBases = array_values(array_unique(array_filter(
            array_merge([$expectedContentTypeBase], $expectedAlternativeContentTypeBases),
            static fn (string $contentTypeBase): bool => $contentTypeBase !== '',
        )));

        return [
            'kind' => $kind,
            'partName' => $partName,
            'xml' => $xml,
            'exists' => $exists,
            'relationship' => $relationship,
            'relationshipSourcePart' => $relationshipSourcePart,
            'relationshipsPart' => $relationshipsPart,
            'required' => $required,
            'expectedRootNamespace' => $expectedRootNamespace,
            'expectedRootLocalName' => $expectedRootLocalName,
            'expectedContentTypeBase' => $expectedContentTypeBase,
            'expectedContentTypeBases' => $expectedContentTypeBases,
        ];
    }

    /**
     * @param array<string, string> $parts
     * @param array{defaults:array<string, string>, overrides:array<string, string>} $contentTypes
     * @param list<array<string, mixed>> $definitions
     * @return array<string, mixed>
     */
    private function selectedXmlPartProvenance(array $parts, array $contentTypes, array $definitions): array
    {
        $items = [];
        $byKind = [];
        $issueKinds = [];
        $issueCount = 0;

        foreach ($definitions as $definition) {
            $item = $this->selectedXmlPartProvenanceItem($parts, $contentTypes, $definition);
            $items[] = $item;
            $byKind[$item['kind']] = $item;
            if ($item['issues'] !== []) {
                $issueKinds[] = $item['kind'];
                $issueCount += count($item['issues']);
            }
        }

        $rootNamespacePrefixes = [];
        $rootAttributeCount = 0;
        $rootNamespaceDeclarationCount = 0;
        $rootPrefixedCount = 0;
        $xmlDeclarationCount = 0;
        $xmlDeclarationEncodingCounts = [];
        $xmlStandaloneDeclarationCount = 0;
        $xmlStandaloneYesCount = 0;
        $xmlStandaloneNoCount = 0;
        $processingInstructionCount = 0;
        $processingInstructionTargets = [];
        $doctypeCount = 0;
        $doctypeExternalReferenceCount = 0;
        $doctypeInternalSubsetCount = 0;
        $doctypeEntityDeclarationCount = 0;
        $doctypeIssueCodes = [];
        foreach ($items as $item) {
            $rootAttributeCount += (int) ($item['rootAttributeCount'] ?? 0);
            $rootNamespaceDeclarationCount += (int) ($item['rootNamespaceDeclarationCount'] ?? 0);
            if (($item['rootPrefix'] ?? null) !== null) {
                ++$rootPrefixedCount;
            }
            if (($item['xmlDeclarationPresent'] ?? false) === true) {
                ++$xmlDeclarationCount;
            }
            $encoding = is_string($item['xmlDeclarationEncoding'] ?? null) ? $item['xmlDeclarationEncoding'] : '';
            if ($encoding !== '') {
                $xmlDeclarationEncodingCounts[$encoding] = ($xmlDeclarationEncodingCounts[$encoding] ?? 0) + 1;
            }
            if (is_bool($item['xmlDeclarationStandalone'] ?? null)) {
                ++$xmlStandaloneDeclarationCount;
                if ($item['xmlDeclarationStandalone'] === true) {
                    ++$xmlStandaloneYesCount;
                } else {
                    ++$xmlStandaloneNoCount;
                }
            }
            foreach (($item['rootNamespacePrefixes'] ?? []) as $prefix) {
                if (is_string($prefix)) {
                    $this->appendUniqueString($rootNamespacePrefixes, $prefix);
                }
            }
            $processingInstructionCount += (int) ($item['processingInstructionCount'] ?? 0);
            foreach (($item['processingInstructionTargets'] ?? []) as $target) {
                if (is_string($target)) {
                    $this->appendUniqueString($processingInstructionTargets, $target);
                }
            }
            if (($item['doctypePresent'] ?? false) === true) {
                ++$doctypeCount;
            }
            if (is_string($item['doctypeSystemId'] ?? null) || is_string($item['doctypePublicId'] ?? null)) {
                ++$doctypeExternalReferenceCount;
            }
            if (($item['doctypeInternalSubsetPresent'] ?? false) === true) {
                ++$doctypeInternalSubsetCount;
            }
            $doctypeEntityDeclarationCount += (int) ($item['doctypeEntityDeclarationCount'] ?? 0);
            foreach (($item['doctypeIssueCodes'] ?? []) as $issueCode) {
                if (is_string($issueCode) && $issueCode !== '') {
                    $doctypeIssueCodes[$issueCode] = true;
                }
            }
        }
        ksort($xmlDeclarationEncodingCounts, SORT_STRING);

        return [
            'count' => count($items),
            'existingCount' => count(array_filter($items, static fn (array $item): bool => $item['exists'] === true)),
            'relationshipSelectedCount' => count(array_filter($items, static fn (array $item): bool => $item['relationshipId'] !== null)),
            'byteDigestCount' => count(array_filter($items, static fn (array $item): bool => is_string($item['sha256'] ?? null))),
            'missingRequiredOrReferencedCount' => count(array_filter(
                $items,
                static fn (array $item): bool => in_array('missing-required-part', $item['issues'], true)
                    || in_array('missing-relationship-target', $item['issues'], true),
            )),
            'validRootCount' => count(array_filter($items, static fn (array $item): bool => $item['validRoot'] === true)),
            'invalidRootCount' => count(array_filter($items, static fn (array $item): bool => $item['validRoot'] === false)),
            'invalidXmlCount' => count(array_filter($items, static fn (array $item): bool => in_array('invalid-xml', $item['issues'], true))),
            'unexpectedContentTypeCount' => count(array_filter($items, static fn (array $item): bool => in_array('unexpected-content-type', $item['issues'], true))),
            'missingContentTypeCount' => count(array_filter($items, static fn (array $item): bool => in_array('missing-content-type', $item['issues'], true))),
            'rootPrefixedCount' => $rootPrefixedCount,
            'rootAttributeCount' => $rootAttributeCount,
            'rootNamespaceDeclarationCount' => $rootNamespaceDeclarationCount,
            'rootNamespacePrefixes' => $rootNamespacePrefixes,
            'xmlDeclarationCount' => $xmlDeclarationCount,
            'xmlDeclarationEncodingCounts' => $xmlDeclarationEncodingCounts,
            'xmlStandaloneDeclarationCount' => $xmlStandaloneDeclarationCount,
            'xmlStandaloneYesCount' => $xmlStandaloneYesCount,
            'xmlStandaloneNoCount' => $xmlStandaloneNoCount,
            'processingInstructionCount' => $processingInstructionCount,
            'processingInstructionTargets' => $processingInstructionTargets,
            'doctypeCount' => $doctypeCount,
            'doctypeExternalReferenceCount' => $doctypeExternalReferenceCount,
            'doctypeInternalSubsetCount' => $doctypeInternalSubsetCount,
            'doctypeEntityDeclarationCount' => $doctypeEntityDeclarationCount,
            'doctypeIssueCodes' => array_keys($doctypeIssueCodes),
            'issueCount' => $issueCount,
            'issueKinds' => $issueKinds,
            'byKind' => $byKind,
            'items' => $items,
        ];
    }

    /**
     * @param array<string, string> $parts
     * @param array{defaults:array<string, string>, overrides:array<string, string>} $contentTypes
     * @param array<string, mixed> $definition
     * @return array<string, mixed>
     */
    private function selectedXmlPartProvenanceItem(array $parts, array $contentTypes, array $definition): array
    {
        $kind = (string) $definition['kind'];
        $partName = (string) $definition['partName'];
        $exists = (bool) $definition['exists'];
        $required = (bool) $definition['required'];
        $relationship = is_array($definition['relationship']) ? $definition['relationship'] : null;
        $expectedRootNamespace = (string) $definition['expectedRootNamespace'];
        $expectedRootLocalName = (string) $definition['expectedRootLocalName'];
        $expectedContentTypeBase = (string) $definition['expectedContentTypeBase'];
        $expectedContentTypeBases = is_array($definition['expectedContentTypeBases'] ?? null)
            ? array_values(array_filter(
                array_map('strval', $definition['expectedContentTypeBases']),
                static fn (string $contentTypeBase): bool => $contentTypeBase !== '',
            ))
            : ($expectedContentTypeBase === '' ? [] : [$expectedContentTypeBase]);
        $contentTypeResolution = $this->contentTypeResolutionForPart($partName, $contentTypes);
        $partBytes = $exists && array_key_exists($partName, $parts) ? $parts[$partName] : null;
        $validateContentType = $exists || $required || $relationship !== null;
        $contentTypeMatchesExpected = null;
        $issues = [];

        if ($expectedContentTypeBases !== [] && $validateContentType) {
            $contentTypeMatchesExpected = in_array($contentTypeResolution['contentTypeBase'], $expectedContentTypeBases, true);
            if (!$contentTypeMatchesExpected) {
                $issues[] = $contentTypeResolution['contentTypeSource'] === 'missing'
                    ? 'missing-content-type'
                    : 'unexpected-content-type';
            }
        }

        $item = [
            'kind' => $kind,
            'partName' => $partName,
            'selectionSource' => $relationship !== null ? 'relationship' : ($exists ? 'conventional-part' : 'conventional-fallback'),
            'required' => $required,
            'exists' => $exists,
            'bytes' => $partBytes === null ? 0 : strlen($partBytes),
            'crc32' => $partBytes === null ? null : sprintf('%08x', crc32($partBytes)),
            'sha256' => $partBytes === null ? null : hash('sha256', $partBytes),
            'expectedRootNamespace' => $expectedRootNamespace,
            'expectedRootLocalName' => $expectedRootLocalName,
            'rootNamespace' => null,
            'rootLocalName' => null,
            'rootQualifiedName' => null,
            'rootPrefix' => null,
            'rootAttributeCount' => 0,
            'rootNamespaceDeclarationCount' => 0,
            'rootNamespacePrefixes' => [],
            'xmlDeclarationPresent' => false,
            'xmlDeclarationVersion' => null,
            'xmlDeclarationEncoding' => null,
            'xmlDeclarationStandalone' => null,
            'xmlDeclarationAttributeCount' => 0,
            'processingInstructionCount' => 0,
            'processingInstructionTargets' => [],
            'processingInstructions' => [],
            'doctypePresent' => false,
            'doctypeName' => null,
            'doctypePublicId' => null,
            'doctypeSystemId' => null,
            'doctypeInternalSubsetPresent' => false,
            'doctypeInternalSubsetByteLength' => 0,
            'doctypeEntityDeclarationCount' => 0,
            'doctypeByteLength' => 0,
            'doctypeSha256' => null,
            'doctypeIssueCodes' => [],
            'validRoot' => null,
            'xmlParseError' => null,
            'expectedContentTypeBase' => $expectedContentTypeBase,
            'expectedContentTypeBases' => $expectedContentTypeBases,
            'contentTypeMatchesExpected' => $contentTypeMatchesExpected,
            'relationshipId' => null,
            'relationshipType' => null,
            'relationshipSourcePart' => null,
            'relationshipsPart' => null,
            'relationshipTarget' => null,
            'relationshipTargetMode' => null,
            'relationshipResolvedTarget' => null,
            'targetReferenceSuffix' => '',
            'targetQuery' => null,
            'targetFragment' => null,
            'issues' => $issues,
        ] + $contentTypeResolution;

        if ($relationship !== null) {
            $suffix = $this->targetReferenceSuffix($relationship['resolvedTarget']);
            $item['relationshipId'] = $relationship['id'];
            $item['relationshipType'] = $relationship['type'];
            $item['relationshipSourcePart'] = (string) $definition['relationshipSourcePart'];
            $item['relationshipsPart'] = (string) $definition['relationshipsPart'];
            $item['relationshipTarget'] = $relationship['target'];
            $item['relationshipTargetMode'] = $relationship['targetMode'];
            $item['relationshipResolvedTarget'] = $relationship['resolvedTarget'];
            $item['targetReferenceSuffix'] = $suffix['suffix'];
            $item['targetQuery'] = $suffix['query'];
            $item['targetFragment'] = $suffix['fragment'];
        }

        if (!$exists) {
            if ($required) {
                $item['issues'][] = 'missing-required-part';
            }
            if ($relationship !== null) {
                $item['issues'][] = 'missing-relationship-target';
            }

            return $item;
        }

        $xml = is_string($definition['xml']) ? $definition['xml'] : ($parts[$partName] ?? '');
        $xmlDeclaration = $this->xmlDeclarationProvenance($xml);
        $item['xmlDeclarationPresent'] = $xmlDeclaration['present'];
        $item['xmlDeclarationVersion'] = $xmlDeclaration['version'];
        $item['xmlDeclarationEncoding'] = $xmlDeclaration['encoding'];
        $item['xmlDeclarationStandalone'] = $xmlDeclaration['standalone'];
        $item['xmlDeclarationAttributeCount'] = $xmlDeclaration['attributeCount'];
        $prolog = $this->xmlPrologProvenance($xml);
        $item['processingInstructionCount'] = $prolog['processingInstructionCount'];
        $item['processingInstructionTargets'] = $prolog['processingInstructionTargets'];
        $item['processingInstructions'] = $prolog['processingInstructions'];
        $item['doctypePresent'] = $prolog['doctypePresent'];
        $item['doctypeName'] = $prolog['doctypeName'];
        $item['doctypePublicId'] = $prolog['doctypePublicId'];
        $item['doctypeSystemId'] = $prolog['doctypeSystemId'];
        $item['doctypeInternalSubsetPresent'] = $prolog['doctypeInternalSubsetPresent'];
        $item['doctypeInternalSubsetByteLength'] = $prolog['doctypeInternalSubsetByteLength'];
        $item['doctypeEntityDeclarationCount'] = $prolog['doctypeEntityDeclarationCount'];
        $item['doctypeByteLength'] = $prolog['doctypeByteLength'];
        $item['doctypeSha256'] = $prolog['doctypeSha256'];
        $item['doctypeIssueCodes'] = $prolog['doctypeIssueCodes'];
        foreach ($prolog['doctypeIssueCodes'] as $issueCode) {
            $item['issues'][] = $issueCode;
        }
        if ($xml === '') {
            $item['validRoot'] = false;
            $item['issues'][] = 'empty-xml-part';

            return $item;
        }

        $root = $this->xmlRootProvenance($xml, $partName);
        if ($root['validXml'] === false) {
            $item['validRoot'] = false;
            $item['xmlParseError'] = $root['xmlParseError'];
            $item['issues'][] = 'invalid-xml';

            return $item;
        }

        $item['rootNamespace'] = $root['namespace'];
        $item['rootLocalName'] = $root['localName'];
        $item['rootQualifiedName'] = $root['qualifiedName'];
        $item['rootPrefix'] = $root['prefix'];
        $item['rootAttributeCount'] = $root['attributeCount'];
        $item['rootNamespaceDeclarationCount'] = $root['namespaceDeclarationCount'];
        $item['rootNamespacePrefixes'] = $root['namespacePrefixes'];
        $item['validRoot'] = $root['namespace'] === $expectedRootNamespace && $root['localName'] === $expectedRootLocalName;
        if ($item['validRoot'] === false) {
            $item['issues'][] = 'unexpected-root';
        }

        return $item;
    }

    /**
     * @return array{present:bool, version:?string, encoding:?string, standalone:?bool, attributeCount:int}
     */
    private function xmlDeclarationProvenance(string $xml): array
    {
        if (preg_match('/^(?:\xEF\xBB\xBF)?\s*<\?xml\s+([^?]*?)\?>/i', $xml, $match) !== 1) {
            return [
                'present' => false,
                'version' => null,
                'encoding' => null,
                'standalone' => null,
                'attributeCount' => 0,
            ];
        }

        $attributes = [];
        preg_match_all('/([A-Za-z_][A-Za-z0-9_.:-]*)\s*=\s*(["\'])(.*?)\2/s', (string) $match[1], $matches, PREG_SET_ORDER);
        foreach ($matches as $attribute) {
            $name = strtolower((string) $attribute[1]);
            if (array_key_exists($name, $attributes)) {
                continue;
            }

            $attributes[$name] = (string) $attribute[3];
        }

        $standalone = null;
        $standaloneValue = strtolower($attributes['standalone'] ?? '');
        if ($standaloneValue === 'yes') {
            $standalone = true;
        } elseif ($standaloneValue === 'no') {
            $standalone = false;
        }

        return [
            'present' => true,
            'version' => isset($attributes['version']) && $attributes['version'] !== '' ? $attributes['version'] : null,
            'encoding' => isset($attributes['encoding']) && $attributes['encoding'] !== '' ? $attributes['encoding'] : null,
            'standalone' => $standalone,
            'attributeCount' => count($attributes),
        ];
    }

    /**
     * @return array{processingInstructionCount:int, processingInstructionTargets:list<string>, processingInstructions:list<array{target:string, dataPreview:string, dataByteLength:int, dataTruncated:bool}>, doctypePresent:bool, doctypeName:?string, doctypePublicId:?string, doctypeSystemId:?string, doctypeInternalSubsetPresent:bool, doctypeInternalSubsetByteLength:int, doctypeEntityDeclarationCount:int, doctypeByteLength:int, doctypeSha256:?string, doctypeIssueCodes:list<string>}
     */
    private function xmlPrologProvenance(string $xml): array
    {
        $processingInstructions = [];
        $processingInstructionTargets = [];
        preg_match_all('/<\?\s*([A-Za-z_][A-Za-z0-9_.:-]*)(.*?)\?>/s', $xml, $matches, PREG_SET_ORDER);
        foreach ($matches as $match) {
            $target = (string) $match[1];
            if (strtolower($target) === 'xml') {
                continue;
            }

            $data = trim((string) ($match[2] ?? ''));
            $this->appendUniqueString($processingInstructionTargets, $target);
            if (count($processingInstructions) >= 16) {
                continue;
            }

            $processingInstructions[] = [
                'target' => $target,
                'dataPreview' => $this->boundedMetadataString($data),
                'dataByteLength' => strlen($data),
                'dataTruncated' => strlen($data) > 120,
            ];
        }

        $doctype = $this->xmlDoctypeProvenance($xml);

        return [
            'processingInstructionCount' => count($matches) - count(array_filter(
                $matches,
                static fn (array $match): bool => strtolower((string) $match[1]) === 'xml',
            )),
            'processingInstructionTargets' => $processingInstructionTargets,
            'processingInstructions' => $processingInstructions,
            'doctypePresent' => $doctype['present'],
            'doctypeName' => $doctype['name'],
            'doctypePublicId' => $doctype['publicId'],
            'doctypeSystemId' => $doctype['systemId'],
            'doctypeInternalSubsetPresent' => $doctype['internalSubsetPresent'],
            'doctypeInternalSubsetByteLength' => $doctype['internalSubsetByteLength'],
            'doctypeEntityDeclarationCount' => $doctype['entityDeclarationCount'],
            'doctypeByteLength' => $doctype['byteLength'],
            'doctypeSha256' => $doctype['sha256'],
            'doctypeIssueCodes' => $doctype['issueCodes'],
        ];
    }

    /**
     * @return array{present:bool, name:?string, publicId:?string, systemId:?string, internalSubsetPresent:bool, internalSubsetByteLength:int, entityDeclarationCount:int, byteLength:int, sha256:?string, issueCodes:list<string>}
     */
    private function xmlDoctypeProvenance(string $xml): array
    {
        $start = stripos($xml, '<!DOCTYPE');
        if ($start === false) {
            return [
                'present' => false,
                'name' => null,
                'publicId' => null,
                'systemId' => null,
                'internalSubsetPresent' => false,
                'internalSubsetByteLength' => 0,
                'entityDeclarationCount' => 0,
                'byteLength' => 0,
                'sha256' => null,
                'issueCodes' => [],
            ];
        }

        $end = $this->xmlDoctypeEndOffset($xml, $start);
        $declaration = $end === null ? substr($xml, $start) : substr($xml, $start, $end - $start + 1);
        $body = trim(preg_replace('/^<!DOCTYPE\s*/i', '', rtrim($declaration, '>')) ?? '');
        $name = null;
        $publicId = null;
        $systemId = null;
        $internalSubset = null;
        if (preg_match('/^([A-Za-z_][A-Za-z0-9_.:-]*)\b(.*)$/s', $body, $match) === 1) {
            $name = (string) $match[1];
            $remainder = trim((string) $match[2]);
            if (preg_match('/\bPUBLIC\s+(["\'])(.*?)\1\s+(["\'])(.*?)\3/is', $remainder, $publicMatch) === 1) {
                $publicId = (string) $publicMatch[2];
                $systemId = (string) $publicMatch[4];
            } elseif (preg_match('/\bSYSTEM\s+(["\'])(.*?)\1/is', $remainder, $systemMatch) === 1) {
                $systemId = (string) $systemMatch[2];
            }
        }

        $subsetStart = strpos($declaration, '[');
        $subsetEnd = strrpos($declaration, ']');
        if ($subsetStart !== false && $subsetEnd !== false && $subsetEnd > $subsetStart) {
            $internalSubset = substr($declaration, $subsetStart + 1, $subsetEnd - $subsetStart - 1);
        }

        $entityDeclarationCount = 0;
        if (is_string($internalSubset)) {
            preg_match_all('/<!ENTITY\b/i', $internalSubset, $entityMatches);
            $entityDeclarationCount = count($entityMatches[0]);
        }

        $issueCodes = ['xml-doctype-declaration'];
        if ($publicId !== null || $systemId !== null) {
            $issueCodes[] = 'xml-external-doctype-reference';
        }
        if ($entityDeclarationCount > 0) {
            $issueCodes[] = 'xml-entity-declaration';
        }
        if ($end === null) {
            $issueCodes[] = 'xml-doctype-unclosed';
        }

        return [
            'present' => true,
            'name' => $name,
            'publicId' => $publicId,
            'systemId' => $systemId,
            'internalSubsetPresent' => is_string($internalSubset),
            'internalSubsetByteLength' => is_string($internalSubset) ? strlen($internalSubset) : 0,
            'entityDeclarationCount' => $entityDeclarationCount,
            'byteLength' => strlen($declaration),
            'sha256' => hash('sha256', $declaration),
            'issueCodes' => array_values(array_unique($issueCodes)),
        ];
    }

    private function xmlDoctypeEndOffset(string $xml, int $start): ?int
    {
        $length = strlen($xml);
        $quote = null;
        $bracketDepth = 0;
        for ($offset = $start; $offset < $length; ++$offset) {
            $char = $xml[$offset];
            if ($quote !== null) {
                if ($char === $quote) {
                    $quote = null;
                }
                continue;
            }
            if ($char === '"' || $char === "'") {
                $quote = $char;
                continue;
            }
            if ($char === '[') {
                ++$bracketDepth;
                continue;
            }
            if ($char === ']' && $bracketDepth > 0) {
                --$bracketDepth;
                continue;
            }
            if ($char === '>' && $bracketDepth === 0) {
                return $offset;
            }
        }

        return null;
    }

    /**
     * @return array{validXml:bool, xmlParseError:?string, namespace:?string, localName:?string, qualifiedName:?string, prefix:?string, attributeCount:int, namespaceDeclarationCount:int, namespacePrefixes:list<string>}
     */
    private function xmlRootProvenance(string $xml, string $partName): array
    {
        $dom = $this->loadXmlForProvenance($xml, $partName);
        if (!$dom instanceof \DOMDocument) {
            return [
                'validXml' => false,
                'xmlParseError' => $this->lastXmlPreflightError($xml, $partName),
                'namespace' => null,
                'localName' => null,
                'qualifiedName' => null,
                'prefix' => null,
                'attributeCount' => 0,
                'namespaceDeclarationCount' => 0,
                'namespacePrefixes' => [],
            ];
        }

        $root = $dom->documentElement;
        if (!$root instanceof \DOMElement) {
            return [
                'validXml' => false,
                'xmlParseError' => 'missing XML document element',
                'namespace' => null,
                'localName' => null,
                'qualifiedName' => null,
                'prefix' => null,
                'attributeCount' => 0,
                'namespaceDeclarationCount' => 0,
                'namespacePrefixes' => [],
            ];
        }

        $attributeCount = 0;
        foreach ($root->attributes ?? [] as $attribute) {
            if (!$attribute instanceof \DOMAttr) {
                continue;
            }
            if ($attribute->namespaceURI === 'http://www.w3.org/2000/xmlns/' || $attribute->nodeName === 'xmlns') {
                continue;
            }

            ++$attributeCount;
        }
        $namespaceDeclarations = $this->rootNamespaceDeclarations($xml);

        return [
            'validXml' => true,
            'xmlParseError' => null,
            'namespace' => $root->namespaceURI,
            'localName' => $root->localName,
            'qualifiedName' => $root->tagName,
            'prefix' => $root->prefix === '' ? null : $root->prefix,
            'attributeCount' => $attributeCount,
            'namespaceDeclarationCount' => $namespaceDeclarations['count'],
            'namespacePrefixes' => $namespaceDeclarations['prefixes'],
        ];
    }

    /**
     * @return array{count:int, prefixes:list<string>}
     */
    private function rootNamespaceDeclarations(string $xml): array
    {
        if (preg_match('/<(?![?!])([A-Za-z_][A-Za-z0-9_.:-]*)([^>]*)>/s', $xml, $rootMatch) !== 1) {
            return [
                'count' => 0,
                'prefixes' => [],
            ];
        }

        $prefixes = [];
        preg_match_all('/\sxmlns(?::([A-Za-z_][A-Za-z0-9_.-]*))?\s*=\s*(["\'])(.*?)\2/s', (string) $rootMatch[2], $matches, PREG_SET_ORDER);
        foreach ($matches as $match) {
            $this->appendUniqueString($prefixes, ($match[1] ?? '') === '' ? 'default' : (string) $match[1]);
        }

        return [
            'count' => count($matches),
            'prefixes' => $prefixes,
        ];
    }

    /**
     * @param array<string, mixed> $relationship
     * @return array<string, mixed>
     */
    private function relationshipProvenanceSummaryItem(array $relationship): array
    {
        $externalTargetIssues = is_array($relationship['externalTargetIssues'] ?? null)
            ? array_values(array_map('strval', $relationship['externalTargetIssues']))
            : [];

        return [
            'id' => $relationship['id'] ?? '',
            'type' => $relationship['type'] ?? '',
            'sourcePart' => $relationship['sourcePart'] ?? '',
            'relationshipsPart' => $relationship['relationshipsPart'] ?? '',
            'target' => $relationship['target'] ?? '',
            'targetMode' => $relationship['targetMode'] ?? '',
            'resolvedTarget' => $relationship['resolvedTarget'] ?? '',
            'external' => (bool) ($relationship['external'] ?? false),
            'targetPart' => $relationship['targetPart'] ?? null,
            'targetReferenceSuffix' => $relationship['targetReferenceSuffix'] ?? '',
            'targetQuery' => $relationship['targetQuery'] ?? null,
            'targetQueryParameterCount' => (int) ($relationship['targetQueryParameterCount'] ?? 0),
            'targetQueryParameters' => is_array($relationship['targetQueryParameters'] ?? null)
                ? $relationship['targetQueryParameters']
                : [],
            'targetQueryParameterNames' => is_array($relationship['targetQueryParameterNames'] ?? null)
                ? $relationship['targetQueryParameterNames']
                : [],
            'targetQueryParameterMap' => is_array($relationship['targetQueryParameterMap'] ?? null)
                ? $relationship['targetQueryParameterMap']
                : [],
            'targetFragment' => $relationship['targetFragment'] ?? null,
            'targetParentTraversalCount' => (int) ($relationship['targetParentTraversalCount'] ?? 0),
            'targetHasParentTraversal' => (bool) ($relationship['targetHasParentTraversal'] ?? false),
            'targetStartsAtPackageRoot' => (bool) ($relationship['targetStartsAtPackageRoot'] ?? false),
            'sameSourcePart' => (bool) ($relationship['sameSourcePart'] ?? false),
            'externalTargetKind' => is_string($relationship['externalTargetKind'] ?? null) ? $relationship['externalTargetKind'] : null,
            'externalTargetScheme' => is_string($relationship['externalTargetScheme'] ?? null) ? $relationship['externalTargetScheme'] : null,
            'externalTargetAllowed' => is_bool($relationship['externalTargetAllowed'] ?? null) ? $relationship['externalTargetAllowed'] : null,
            'externalTargetIssues' => $externalTargetIssues,
            'exists' => (bool) ($relationship['exists'] ?? false),
            'contentType' => $relationship['contentType'] ?? null,
            'contentTypeBase' => $relationship['contentTypeBase'] ?? null,
            'contentTypeHasParameters' => (bool) ($relationship['contentTypeHasParameters'] ?? false),
            'contentTypeParameterCount' => (int) ($relationship['contentTypeParameterCount'] ?? 0),
            'contentTypeParameters' => $relationship['contentTypeParameters'] ?? [],
            'contentTypeParameterMap' => $relationship['contentTypeParameterMap'] ?? [],
            'contentTypeSource' => $relationship['contentTypeSource'] ?? 'missing',
            'defaultExtension' => $relationship['defaultExtension'] ?? null,
            'overridePartName' => $relationship['overridePartName'] ?? null,
        ];
    }

    /**
     * @param array<string, mixed> $relationshipPart
     * @return array<string, mixed>
     */
    private function missingRelationshipSourceSummary(string $relationshipsPart, array $relationshipPart): array
    {
        $relationships = [];
        $relationshipIds = [];
        $targetParts = [];
        $existingTargetParts = [];
        $missingTargetParts = [];
        $externalTargets = [];
        $missingContentTypeTargetParts = [];
        $targetReferenceSuffixes = [];
        $internalTargetCount = 0;
        $externalTargetCount = 0;
        $existingTargetCount = 0;
        $missingTargetCount = 0;
        $missingContentTypeCount = 0;

        foreach (($relationshipPart['relationships'] ?? []) as $relationship) {
            if (!is_array($relationship)) {
                continue;
            }

            $item = $this->relationshipProvenanceSummaryItem($relationship);
            $relationships[] = $item;
            $this->appendUniqueString($relationshipIds, is_string($item['id'] ?? null) ? $item['id'] : null);

            $targetReferenceSuffix = is_string($item['targetReferenceSuffix'] ?? null) ? $item['targetReferenceSuffix'] : '';
            if ($targetReferenceSuffix !== '') {
                $this->appendUniqueString($targetReferenceSuffixes, $targetReferenceSuffix);
            }

            if (($item['external'] ?? false) === true) {
                ++$externalTargetCount;
                $this->appendUniqueString($externalTargets, is_string($item['resolvedTarget'] ?? null) ? $item['resolvedTarget'] : null);
                continue;
            }

            ++$internalTargetCount;
            $targetPart = is_string($item['targetPart'] ?? null) ? $item['targetPart'] : null;
            $this->appendUniqueString($targetParts, $targetPart);

            if (($item['exists'] ?? false) === true) {
                ++$existingTargetCount;
                $this->appendUniqueString($existingTargetParts, $targetPart);
            } else {
                ++$missingTargetCount;
                $this->appendUniqueString($missingTargetParts, $targetPart);
            }

            if (($item['contentTypeSource'] ?? '') === 'missing') {
                ++$missingContentTypeCount;
                $this->appendUniqueString($missingContentTypeTargetParts, $targetPart);
            }
        }

        return [
            'relationshipsPart' => $relationshipsPart,
            'sourcePart' => is_string($relationshipPart['sourcePart'] ?? null) ? $relationshipPart['sourcePart'] : '',
            'sourceExists' => false,
            'relationshipCount' => count($relationships),
            'relationshipRecordCount' => (int) ($relationshipPart['relationshipRecordCount'] ?? count($relationships)),
            'internalTargetCount' => $internalTargetCount,
            'externalTargetCount' => $externalTargetCount,
            'existingTargetCount' => $existingTargetCount,
            'missingTargetCount' => $missingTargetCount,
            'missingContentTypeCount' => $missingContentTypeCount,
            'relationshipIds' => $relationshipIds,
            'targetParts' => $targetParts,
            'existingTargetParts' => $existingTargetParts,
            'missingTargetParts' => $missingTargetParts,
            'externalTargets' => $externalTargets,
            'missingContentTypeTargetParts' => $missingContentTypeTargetParts,
            'targetReferenceSuffixes' => $targetReferenceSuffixes,
            'relationships' => $relationships,
        ];
    }

    /**
     * @param array<string, string> $parts
     * @param array{defaults:array<string, string>, overrides:array<string, string>} $contentTypes
     * @param array<string, array{id:string, type:string, target:string, targetMode:string, resolvedTarget:string}> $rootRelationships
     * @param array<string, array{id:string, type:string, target:string, targetMode:string, resolvedTarget:string}> $documentRelationships
     * @return array<string, mixed>
     */
    private function packageRelationshipPartsProvenance(
        array $parts,
        array $contentTypes,
        string $documentPart,
        string $documentRelationshipsPart,
        array $rootRelationships,
        array $documentRelationships,
    ): array {
        $relationshipParts = [
            '_rels/.rels' => $this->relationshipPartProvenance($parts, '_rels/.rels', '/', $rootRelationships, $contentTypes),
            $documentRelationshipsPart => $this->relationshipPartProvenance(
                $parts,
                $documentRelationshipsPart,
                $documentPart,
                $documentRelationships,
                $contentTypes,
            ),
        ];

        foreach ($parts as $partName => $_contents) {
            if (!$this->isRelationshipPartName($partName) || isset($relationshipParts[$partName])) {
                continue;
            }

            $relationshipParts[$partName] = $this->relationshipPartProvenance(
                $parts,
                $partName,
                $this->relationshipSourcePartForInventory($partName),
                $this->readRelationshipsPart($parts, $partName),
                $contentTypes,
            );
        }

        return $relationshipParts;
    }

    /**
     * @param array<string, array<string, mixed>> $relationshipParts
     * @param array<string, array<string, mixed>> $partInventory
     * @return array<string, array<string, mixed>>
     */
    private function relationshipPartsWithSourceProvenance(array $relationshipParts, array $partInventory): array
    {
        foreach ($relationshipParts as $partName => $relationshipPart) {
            $sourcePart = is_string($relationshipPart['sourcePart'] ?? null) ? $relationshipPart['sourcePart'] : '';
            $source = $this->relationshipSourceProvenance($sourcePart, $partInventory);
            $relationshipPart += $source;

            foreach (['relationships', 'relationshipRecords'] as $collectionKey) {
                if (!is_array($relationshipPart[$collectionKey] ?? null)) {
                    continue;
                }

                foreach ($relationshipPart[$collectionKey] as $key => $relationship) {
                    if (!is_array($relationship)) {
                        continue;
                    }
                    $relationshipPart[$collectionKey][$key] = $relationship + $source;
                }
            }

            $relationshipParts[$partName] = $relationshipPart;
        }

        return $relationshipParts;
    }

    /**
     * @param array<string, array<string, mixed>> $partInventory
     * @return array<string, mixed>
     */
    private function relationshipSourceProvenance(string $sourcePart, array $partInventory): array
    {
        $sourceInventory = $sourcePart !== '' && $sourcePart !== '/'
            ? ($partInventory[$sourcePart] ?? null)
            : null;
        $sourceKind = $this->relationshipSourceKind($sourcePart, $sourceInventory);
        $isPackageRoot = $sourcePart === '/';
        $sourceExists = $isPackageRoot || is_array($sourceInventory);
        $sourcePathDepth = $sourcePart === ''
            ? null
            : count($this->packagePartPathSegments($sourcePart));
        $sourceDirectory = $isPackageRoot ? '/' : ($sourcePart === '' ? '' : $this->packagePartDirectory($sourcePart));
        $sourceDirectoryDepth = $sourceDirectory === '' ? null : $this->packagePartDirectoryDepth($sourceDirectory);

        return [
            'relationshipSourceKind' => $sourceKind,
            'sourceIsPackageRoot' => $isPackageRoot,
            'sourceIsRelationshipPart' => $sourcePart !== '' && $this->isRelationshipPartName($sourcePart),
            'sourceExists' => $sourceExists,
            'sourceDirectory' => $sourceDirectory,
            'sourceDirectoryDepth' => $sourceDirectoryDepth,
            'sourcePathDepth' => $sourcePathDepth,
            'sourceBaseName' => $isPackageRoot ? '/' : ($sourcePart === '' ? '' : $this->packagePartBaseName($sourcePart)),
            'sourcePartExtension' => $isPackageRoot || $sourcePart === '' ? null : $this->packagePartExtension($sourcePart),
            'sourceBytes' => is_array($sourceInventory) ? (int) ($sourceInventory['bytes'] ?? 0) : null,
            'sourceCrc32' => is_array($sourceInventory) && is_string($sourceInventory['crc32'] ?? null) ? $sourceInventory['crc32'] : null,
            'sourceSha256' => is_array($sourceInventory) && is_string($sourceInventory['sha256'] ?? null) ? $sourceInventory['sha256'] : null,
            'sourceContentType' => is_array($sourceInventory) && is_string($sourceInventory['contentType'] ?? null) ? $sourceInventory['contentType'] : null,
            'sourceContentTypeBase' => is_array($sourceInventory) && is_string($sourceInventory['contentTypeBase'] ?? null) ? $sourceInventory['contentTypeBase'] : null,
            'sourceContentTypeSource' => is_array($sourceInventory) && is_string($sourceInventory['contentTypeSource'] ?? null) ? $sourceInventory['contentTypeSource'] : null,
            'sourceContentTypeHasParameters' => is_array($sourceInventory) ? (bool) ($sourceInventory['contentTypeHasParameters'] ?? false) : false,
            'sourceContentTypeParameterCount' => is_array($sourceInventory) ? (int) ($sourceInventory['contentTypeParameterCount'] ?? 0) : 0,
            'sourceContentTypeParameters' => is_array($sourceInventory) && is_array($sourceInventory['contentTypeParameters'] ?? null) ? $sourceInventory['contentTypeParameters'] : [],
            'sourceContentTypeParameterMap' => is_array($sourceInventory) && is_array($sourceInventory['contentTypeParameterMap'] ?? null) ? $sourceInventory['contentTypeParameterMap'] : [],
            'sourceRoles' => $isPackageRoot
                ? ['package-root']
                : (is_array($sourceInventory) ? array_values(array_map('strval', $sourceInventory['roles'] ?? [])) : []),
        ];
    }

    /**
     * @param ?array<string, mixed> $sourceInventory
     */
    private function relationshipSourceKind(string $sourcePart, ?array $sourceInventory): string
    {
        if ($sourcePart === '') {
            return 'invalid-source';
        }

        if ($sourcePart === '/') {
            return 'package-root';
        }

        if ($this->isRelationshipPartName($sourcePart)) {
            return 'relationship-part';
        }

        if ($sourcePart === '[Content_Types].xml') {
            return 'content-types-item';
        }

        if (!is_array($sourceInventory)) {
            return 'missing-source';
        }

        return 'package-part';
    }

    /**
     * @param array<string, array<string, mixed>> $relationshipParts
     * @param array<string, array<string, mixed>> $partInventory
     * @return array<string, array<string, mixed>>
     */
    private function relationshipTypeProvenance(array $relationshipParts, array $partInventory): array
    {
        $types = [];
        foreach ($relationshipParts as $relationshipPart) {
            $relationships = $relationshipPart['relationships'] ?? [];
            if (!is_array($relationships)) {
                continue;
            }

            foreach ($relationships as $relationship) {
                if (!is_array($relationship)) {
                    continue;
                }

                $type = is_string($relationship['type'] ?? null) ? $relationship['type'] : '';
                $typeKey = $type === '' ? '(missing-type)' : $type;
                if (!isset($types[$typeKey])) {
                    $types[$typeKey] = [
                        'type' => $type,
                        'label' => $this->relationshipTypeLabel($type),
                        'count' => 0,
                        'internalCount' => 0,
                        'externalCount' => 0,
                        'existingTargetCount' => 0,
                        'missingTargetCount' => 0,
                        'missingContentTypeTargetCount' => 0,
                        'parameterizedContentTypeTargetCount' => 0,
                        'packageRootTargetCount' => 0,
                        'parentTraversalTargetCount' => 0,
                        'sameSourceTargetCount' => 0,
                        'allowedExternalTargetCount' => 0,
                        'unsafeExternalTargetCount' => 0,
                        'externalWithoutExternalTargetModeCount' => 0,
                        'externalRelativeReferenceTargetCount' => 0,
                        'externalTargetKindCounts' => [],
                        'externalTargetSchemeCounts' => [],
                        'externalTargetIssueCounts' => [],
                        'existingTargetPartByteLength' => 0,
                        'relationshipParts' => [],
                        'sourceParts' => [],
                        'sourceKindCounts' => [],
                        'sourceDirectoryCounts' => [],
                        'sourceContentTypeCounts' => [],
                        'sourceContentTypeSourceCounts' => [],
                        'sourceRoleCounts' => [],
                        'targetParts' => [],
                        'existingTargetParts' => [],
                        'missingTargetParts' => [],
                        'targetDirectories' => [],
                        'targetDirectoryCounts' => [],
                        'targetPartExtensions' => [],
                        'targetPartExtensionCounts' => [],
                        'targetPartWithoutExtensionCount' => 0,
                        'externalTargets' => [],
                        'externalTargetsWithoutExternalTargetMode' => [],
                        'externalRelativeReferenceTargets' => [],
                        'unsafeExternalTargets' => [],
                        'contentTypes' => [],
                        'targetContentTypeSourceCounts' => [],
                        'targetRoleCounts' => [],
                        'existingTargetPartDigests' => [],
                        'largestExistingTargetPart' => null,
                        'relationships' => [],
                        '_seenExistingTargetParts' => [],
                    ];
                }

                $external = (bool) ($relationship['external'] ?? false);
                $exists = (bool) ($relationship['exists'] ?? false);
                $targetPart = is_string($relationship['targetPart'] ?? null) ? $relationship['targetPart'] : null;
                $targetPartExtension = $targetPart === null ? null : $this->packagePartExtension($targetPart);
                $relationshipsPart = is_string($relationship['relationshipsPart'] ?? null) ? $relationship['relationshipsPart'] : '';
                $sourcePart = is_string($relationship['sourcePart'] ?? null) ? $relationship['sourcePart'] : '';
                $target = is_string($relationship['target'] ?? null) ? $relationship['target'] : '';
                $resolvedTarget = is_string($relationship['resolvedTarget'] ?? null) ? $relationship['resolvedTarget'] : '';
                $contentType = is_string($relationship['contentType'] ?? null) ? $relationship['contentType'] : '';
                $contentTypeParameters = is_array($relationship['contentTypeParameters'] ?? null) ? $relationship['contentTypeParameters'] : [];
                $contentTypeParameterMap = is_array($relationship['contentTypeParameterMap'] ?? null) ? $relationship['contentTypeParameterMap'] : [];
                $contentTypeParameterCount = is_int($relationship['contentTypeParameterCount'] ?? null)
                    ? $relationship['contentTypeParameterCount']
                    : count($contentTypeParameters);
                $contentTypeSource = is_string($relationship['contentTypeSource'] ?? null) ? $relationship['contentTypeSource'] : '';
                $targetContentTypeSource = $contentTypeSource === '' ? 'missing' : $contentTypeSource;
                $sourceKind = is_string($relationship['relationshipSourceKind'] ?? null)
                    ? $relationship['relationshipSourceKind']
                    : 'invalid-source';
                $sourceDirectory = is_string($relationship['sourceDirectory'] ?? null)
                    ? $relationship['sourceDirectory']
                    : '';
                $sourceContentTypeBase = is_string($relationship['sourceContentTypeBase'] ?? null)
                    ? $relationship['sourceContentTypeBase']
                    : '';
                $sourceContentTypeSource = is_string($relationship['sourceContentTypeSource'] ?? null)
                    ? $relationship['sourceContentTypeSource']
                    : '';

                $types[$typeKey]['count']++;
                $types[$typeKey]['sourceKindCounts'][$sourceKind] =
                    ($types[$typeKey]['sourceKindCounts'][$sourceKind] ?? 0) + 1;
                if ($sourceDirectory !== '') {
                    $types[$typeKey]['sourceDirectoryCounts'][$sourceDirectory] =
                        ($types[$typeKey]['sourceDirectoryCounts'][$sourceDirectory] ?? 0) + 1;
                }
                if ($sourceContentTypeBase !== '') {
                    $types[$typeKey]['sourceContentTypeCounts'][$sourceContentTypeBase] =
                        ($types[$typeKey]['sourceContentTypeCounts'][$sourceContentTypeBase] ?? 0) + 1;
                }
                if ($sourceContentTypeSource !== '') {
                    $types[$typeKey]['sourceContentTypeSourceCounts'][$sourceContentTypeSource] =
                        ($types[$typeKey]['sourceContentTypeSourceCounts'][$sourceContentTypeSource] ?? 0) + 1;
                }
                foreach (array_values(array_map('strval', $relationship['sourceRoles'] ?? [])) as $sourceRole) {
                    $types[$typeKey]['sourceRoleCounts'][$sourceRole] =
                        ($types[$typeKey]['sourceRoleCounts'][$sourceRole] ?? 0) + 1;
                }
                if ($external) {
                    $types[$typeKey]['externalCount']++;
                    $this->appendUniqueString($types[$typeKey]['externalTargets'], $target);
                    $targetMode = is_string($relationship['targetMode'] ?? null) ? $relationship['targetMode'] : '';
                    if ($targetMode !== 'External') {
                        $types[$typeKey]['externalWithoutExternalTargetModeCount']++;
                        $types[$typeKey]['externalTargetsWithoutExternalTargetMode'][] = $this->relationshipProvenanceSummaryItem($relationship);
                    }

                    $externalKind = is_string($relationship['externalTargetKind'] ?? null)
                        ? $relationship['externalTargetKind']
                        : '';
                    if ($externalKind !== '') {
                        $types[$typeKey]['externalTargetKindCounts'][$externalKind] =
                            ($types[$typeKey]['externalTargetKindCounts'][$externalKind] ?? 0) + 1;
                    }
                    if ($externalKind === 'relative-reference') {
                        $types[$typeKey]['externalRelativeReferenceTargetCount']++;
                        $types[$typeKey]['externalRelativeReferenceTargets'][] = $this->relationshipProvenanceSummaryItem($relationship);
                    }

                    $externalScheme = is_string($relationship['externalTargetScheme'] ?? null)
                        ? $relationship['externalTargetScheme']
                        : '(none)';
                    $types[$typeKey]['externalTargetSchemeCounts'][$externalScheme] =
                        ($types[$typeKey]['externalTargetSchemeCounts'][$externalScheme] ?? 0) + 1;

                    if (($relationship['externalTargetAllowed'] ?? null) === false) {
                        $types[$typeKey]['unsafeExternalTargetCount']++;
                        $types[$typeKey]['unsafeExternalTargets'][] = $this->relationshipProvenanceSummaryItem($relationship);
                    } elseif (($relationship['externalTargetAllowed'] ?? null) === true) {
                        $types[$typeKey]['allowedExternalTargetCount']++;
                    }

                    foreach (($relationship['externalTargetIssues'] ?? []) as $issue) {
                        $issue = (string) $issue;
                        if ($issue === '') {
                            continue;
                        }
                        $types[$typeKey]['externalTargetIssueCounts'][$issue] =
                            ($types[$typeKey]['externalTargetIssueCounts'][$issue] ?? 0) + 1;
                    }
                } else {
                    $types[$typeKey]['internalCount']++;
                    if (($relationship['targetHasParentTraversal'] ?? false) === true) {
                        $types[$typeKey]['parentTraversalTargetCount']++;
                    }
                    if (($relationship['targetStartsAtPackageRoot'] ?? false) === true) {
                        $types[$typeKey]['packageRootTargetCount']++;
                    }
                    if (($relationship['sameSourcePart'] ?? false) === true) {
                        $types[$typeKey]['sameSourceTargetCount']++;
                    }
                    $this->appendUniqueString($types[$typeKey]['targetParts'], $targetPart);
                    if ($targetPart !== null) {
                        $targetPartInventory = $partInventory[$targetPart] ?? null;
                        $targetDirectory = is_array($targetPartInventory) && is_string($targetPartInventory['directory'] ?? null)
                            ? $targetPartInventory['directory']
                            : $this->packagePartDirectory($targetPart);
                        $targetPartExtension = is_array($targetPartInventory) && is_string($targetPartInventory['partExtension'] ?? null)
                            ? $targetPartInventory['partExtension']
                            : $targetPartExtension;
                        $targetPartExtensionKey = $targetPartExtension ?? '(none)';
                        $types[$typeKey]['targetDirectoryCounts'][$targetDirectory] =
                            ($types[$typeKey]['targetDirectoryCounts'][$targetDirectory] ?? 0) + 1;
                        $this->appendUniqueString($types[$typeKey]['targetDirectories'], $targetDirectory);
                        $types[$typeKey]['targetPartExtensionCounts'][$targetPartExtensionKey] =
                            ($types[$typeKey]['targetPartExtensionCounts'][$targetPartExtensionKey] ?? 0) + 1;
                        if ($targetPartExtension === null) {
                            $types[$typeKey]['targetPartWithoutExtensionCount']++;
                        } else {
                            $this->appendUniqueString($types[$typeKey]['targetPartExtensions'], $targetPartExtension);
                        }

                        $types[$typeKey]['targetContentTypeSourceCounts'][$targetContentTypeSource] =
                            ($types[$typeKey]['targetContentTypeSourceCounts'][$targetContentTypeSource] ?? 0) + 1;
                        if ($targetContentTypeSource === 'missing') {
                            $types[$typeKey]['missingContentTypeTargetCount']++;
                        }
                        if ((bool) ($relationship['contentTypeHasParameters'] ?? false)) {
                            $types[$typeKey]['parameterizedContentTypeTargetCount']++;
                        }

                        if (is_array($targetPartInventory)) {
                            foreach (($targetPartInventory['roles'] ?? []) as $role) {
                                $role = (string) $role;
                                $types[$typeKey]['targetRoleCounts'][$role] =
                                    ($types[$typeKey]['targetRoleCounts'][$role] ?? 0) + 1;
                            }

                            if ($exists && !isset($types[$typeKey]['_seenExistingTargetParts'][$targetPart])) {
                                $types[$typeKey]['_seenExistingTargetParts'][$targetPart] = true;
                                $targetPartSummary = [
                                    'partName' => $targetPart,
                                    'directory' => $targetDirectory,
                                    'partExtension' => $targetPartExtension,
                                    'bytes' => (int) ($targetPartInventory['bytes'] ?? 0),
                                    'crc32' => is_string($targetPartInventory['crc32'] ?? null) ? $targetPartInventory['crc32'] : null,
                                    'sha256' => is_string($targetPartInventory['sha256'] ?? null) ? $targetPartInventory['sha256'] : null,
                                    'contentType' => is_string($targetPartInventory['contentType'] ?? null) ? $targetPartInventory['contentType'] : '',
                                    'contentTypeBase' => is_string($targetPartInventory['contentTypeBase'] ?? null) ? $targetPartInventory['contentTypeBase'] : '',
                                    'contentTypeSource' => is_string($targetPartInventory['contentTypeSource'] ?? null) ? $targetPartInventory['contentTypeSource'] : 'missing',
                                    'roles' => array_values(array_map('strval', $targetPartInventory['roles'] ?? [])),
                                ];
                                $types[$typeKey]['existingTargetPartByteLength'] += $targetPartSummary['bytes'];
                                $types[$typeKey]['existingTargetPartDigests'][] = $targetPartSummary;
                                $largest = $types[$typeKey]['largestExistingTargetPart'];
                                if (
                                    !is_array($largest)
                                    || $targetPartSummary['bytes'] > (int) ($largest['bytes'] ?? 0)
                                    || (
                                        $targetPartSummary['bytes'] === (int) ($largest['bytes'] ?? 0)
                                        && strcmp($targetPartSummary['partName'], (string) ($largest['partName'] ?? '')) < 0
                                    )
                                ) {
                                    $types[$typeKey]['largestExistingTargetPart'] = $targetPartSummary;
                                }
                            }
                        }
                    }
                    if ($exists) {
                        $types[$typeKey]['existingTargetCount']++;
                        $this->appendUniqueString($types[$typeKey]['existingTargetParts'], $targetPart);
                    } else {
                        $types[$typeKey]['missingTargetCount']++;
                        $this->appendUniqueString($types[$typeKey]['missingTargetParts'], $targetPart);
                    }
                }

                $this->appendUniqueString($types[$typeKey]['relationshipParts'], $relationshipsPart);
                $this->appendUniqueString($types[$typeKey]['sourceParts'], $sourcePart);
                $this->appendUniqueString($types[$typeKey]['contentTypes'], $contentType);
                $types[$typeKey]['relationships'][] = [
                    'id' => is_string($relationship['id'] ?? null) ? $relationship['id'] : '',
                    'sourcePart' => $sourcePart,
                    'relationshipsPart' => $relationshipsPart,
                    'relationshipSourceKind' => $sourceKind,
                    'sourceDirectory' => $sourceDirectory,
                    'sourceContentTypeBase' => $sourceContentTypeBase === '' ? null : $sourceContentTypeBase,
                    'sourceContentTypeSource' => $sourceContentTypeSource === '' ? null : $sourceContentTypeSource,
                    'sourceRoles' => array_values(array_map('strval', $relationship['sourceRoles'] ?? [])),
                    'target' => $target,
                    'targetMode' => is_string($relationship['targetMode'] ?? null) ? $relationship['targetMode'] : '',
                    'resolvedTarget' => $resolvedTarget,
                    'external' => $external,
                    'targetPart' => $targetPart,
                    'targetPartExtension' => $targetPartExtension,
                    'exists' => $exists,
                    'contentType' => $contentType,
                    'contentTypeBase' => is_string($relationship['contentTypeBase'] ?? null) ? $relationship['contentTypeBase'] : '',
                    'contentTypeHasParameters' => (bool) ($relationship['contentTypeHasParameters'] ?? false),
                    'contentTypeParameterCount' => $contentTypeParameterCount,
                    'contentTypeParameters' => $contentTypeParameters,
                    'contentTypeParameterMap' => $contentTypeParameterMap,
                    'contentTypeSource' => $contentTypeSource,
                    'defaultExtension' => is_string($relationship['defaultExtension'] ?? null) ? $relationship['defaultExtension'] : null,
                    'overridePartName' => is_string($relationship['overridePartName'] ?? null) ? $relationship['overridePartName'] : null,
                    'targetReferenceSuffix' => is_string($relationship['targetReferenceSuffix'] ?? null) ? $relationship['targetReferenceSuffix'] : '',
                    'targetQuery' => is_string($relationship['targetQuery'] ?? null) ? $relationship['targetQuery'] : null,
                    'targetQueryParameterCount' => (int) ($relationship['targetQueryParameterCount'] ?? 0),
                    'targetQueryParameters' => is_array($relationship['targetQueryParameters'] ?? null)
                        ? $relationship['targetQueryParameters']
                        : [],
                    'targetQueryParameterNames' => is_array($relationship['targetQueryParameterNames'] ?? null)
                        ? $relationship['targetQueryParameterNames']
                        : [],
                    'targetQueryParameterMap' => is_array($relationship['targetQueryParameterMap'] ?? null)
                        ? $relationship['targetQueryParameterMap']
                        : [],
                    'targetFragment' => is_string($relationship['targetFragment'] ?? null) ? $relationship['targetFragment'] : null,
                    'targetParentTraversalCount' => (int) ($relationship['targetParentTraversalCount'] ?? 0),
                    'targetHasParentTraversal' => (bool) ($relationship['targetHasParentTraversal'] ?? false),
                    'targetStartsAtPackageRoot' => (bool) ($relationship['targetStartsAtPackageRoot'] ?? false),
                    'sameSourcePart' => (bool) ($relationship['sameSourcePart'] ?? false),
                    'externalTargetKind' => is_string($relationship['externalTargetKind'] ?? null) ? $relationship['externalTargetKind'] : null,
                    'externalTargetScheme' => is_string($relationship['externalTargetScheme'] ?? null) ? $relationship['externalTargetScheme'] : null,
                    'externalTargetAllowed' => is_bool($relationship['externalTargetAllowed'] ?? null) ? $relationship['externalTargetAllowed'] : null,
                    'externalTargetIssues' => is_array($relationship['externalTargetIssues'] ?? null)
                        ? array_values(array_map('strval', $relationship['externalTargetIssues']))
                        : [],
                ];
            }
        }

        foreach ($types as &$type) {
            ksort($type['sourceKindCounts']);
            ksort($type['sourceDirectoryCounts']);
            ksort($type['sourceContentTypeCounts']);
            ksort($type['sourceContentTypeSourceCounts']);
            ksort($type['sourceRoleCounts']);
            ksort($type['targetDirectoryCounts']);
            ksort($type['targetPartExtensionCounts']);
            ksort($type['externalTargetKindCounts']);
            ksort($type['externalTargetSchemeCounts']);
            ksort($type['externalTargetIssueCounts']);
            sort($type['targetPartExtensions'], SORT_STRING);
            ksort($type['targetContentTypeSourceCounts']);
            ksort($type['targetRoleCounts']);
            usort(
                $type['existingTargetPartDigests'],
                static fn (array $left, array $right): int => strcmp((string) $left['partName'], (string) $right['partName']),
            );
            unset($type['_seenExistingTargetParts']);
        }
        unset($type);

        ksort($types);

        return $types;
    }

    private function relationshipTypeLabel(string $type): string
    {
        if ($type === '') {
            return 'missing-type';
        }

        $trimmed = rtrim($type, '/#');
        $slash = strrpos($trimmed, '/');
        $hash = strrpos($trimmed, '#');
        $position = max($slash === false ? -1 : $slash, $hash === false ? -1 : $hash);

        return $position >= 0 && $position < strlen($trimmed) - 1
            ? substr($trimmed, $position + 1)
            : $trimmed;
    }

    /**
     * @param list<string> $values
     */
    private function appendUniqueString(array &$values, ?string $value): void
    {
        if ($value === null || $value === '') {
            return;
        }

        if (!in_array($value, $values, true)) {
            $values[] = $value;
        }
    }

    /**
     * @param array<string, string> $parts
     * @param array{defaults:array<string, string>, overrides:array<string, string>} $contentTypes
     * @return array<string, mixed>
     */
    private function contentTypesPartProvenance(array $parts, array $contentTypes): array
    {
        $preflight = isset($parts['[Content_Types].xml'])
            ? OpcContentTypes::preflightXml($parts['[Content_Types].xml'])
            : null;
        $defaults = [];
        foreach ($contentTypes['defaults'] as $extension => $contentType) {
            $defaults[$extension] = [
                'extension' => $extension,
            ] + $this->contentTypeReport($contentType);
        }

        $overrides = [];
        foreach ($contentTypes['overrides'] as $partName => $contentType) {
            $overrides[$partName] = [
                'partName' => $partName,
                'exists' => isset($parts[$partName]),
            ] + $this->contentTypeReport($contentType);
        }
        $parameterizedContentTypes = $this->parameterizedContentTypeDeclarations($defaults, $overrides);
        $defaultDeclarationSummary = $this->contentTypeDefaultDeclarationSummary($parts, $contentTypes);
        $overrideDeclarationSummary = $this->contentTypeOverrideDeclarationSummary($parts, $overrides);
        $overrideCaseFoldPartSummary = $this->contentTypeOverrideCaseFoldPartSummary($parts, $overrides);
        $missingOverrides = array_values(array_filter(
            $overrideDeclarationSummary['declarations'],
            static fn (array $declaration): bool => ($declaration['exists'] ?? true) === false,
        ));
        usort(
            $missingOverrides,
            static fn (array $left, array $right): int => strcmp((string) $left['partName'], (string) $right['partName']),
        );
        $missingOverrideTargetSummary = $this->contentTypeMissingOverrideTargetSummary($missingOverrides);
        $invalidContentTypeRecords = $this->invalidContentTypeRecordSnapshots($preflight);
        $invalidContentTypeRecordIssueBuckets = $this->contentTypeRecordIssueBuckets($invalidContentTypeRecords);

        return [
            'partName' => '[Content_Types].xml',
            'exists' => isset($parts['[Content_Types].xml']),
            'bytes' => isset($parts['[Content_Types].xml']) ? strlen($parts['[Content_Types].xml']) : 0,
            'defaultCount' => count($defaults),
            'overrideCount' => count($overrides),
            'defaults' => $defaults,
            'overrides' => $overrides,
            'defaultDeclarationCount' => $defaultDeclarationSummary['declarationCount'],
            'usedDefaultDeclarationCount' => $defaultDeclarationSummary['usedDeclarationCount'],
            'unusedDefaultDeclarationCount' => $defaultDeclarationSummary['unusedDeclarationCount'],
            'defaultResolvedPartCount' => $defaultDeclarationSummary['defaultResolvedPartCount'],
            'overrideResolvedPartCount' => $defaultDeclarationSummary['overrideResolvedPartCount'],
            'missingDefaultContentTypePartCount' => $defaultDeclarationSummary['missingPartCount'],
            'extensionlessMissingContentTypePartCount' => $defaultDeclarationSummary['extensionlessMissingPartCount'],
            'unusedDefaultExtensions' => $defaultDeclarationSummary['unusedExtensions'],
            'missingDefaultExtensions' => $defaultDeclarationSummary['missingExtensions'],
            'parameterizedDefaultDeclarationCount' => $defaultDeclarationSummary['parameterizedDeclarationCount'],
            'defaultDeclarationContentTypeBaseCounts' => $defaultDeclarationSummary['contentTypeBaseCounts'],
            'defaultDeclarationContentTypeParameterNameCounts' => $defaultDeclarationSummary['contentTypeParameterNameCounts'],
            'defaultDeclarationIssueCounts' => $defaultDeclarationSummary['issueCounts'],
            'defaultDeclarationIssues' => $defaultDeclarationSummary['issues'],
            'defaultDeclarations' => $defaultDeclarationSummary['declarations'],
            'defaultDeclarationMissingParts' => $defaultDeclarationSummary['missingParts'],
            'overrideDeclarationCount' => $overrideDeclarationSummary['declarationCount'],
            'usedOverrideDeclarationCount' => $overrideDeclarationSummary['usedDeclarationCount'],
            'unusedOverrideDeclarationCount' => $overrideDeclarationSummary['unusedDeclarationCount'],
            'invalidOverrideDeclarationCount' => $overrideDeclarationSummary['invalidDeclarationCount'],
            'unusedOverridePartNames' => $overrideDeclarationSummary['unusedPartNames'],
            'parameterizedOverrideDeclarationCount' => $overrideDeclarationSummary['parameterizedDeclarationCount'],
            'overrideDeclarationContentTypeBaseCounts' => $overrideDeclarationSummary['contentTypeBaseCounts'],
            'overrideDeclarationContentTypeParameterNameCounts' => $overrideDeclarationSummary['contentTypeParameterNameCounts'],
            'overrideDeclarationIssueCounts' => $overrideDeclarationSummary['issueCounts'],
            'overrideDeclarationIssues' => $overrideDeclarationSummary['issues'],
            'overrideDeclarations' => $overrideDeclarationSummary['declarations'],
            'overrideCaseFoldPartCount' => $overrideCaseFoldPartSummary['caseFoldPartCount'],
            'duplicateOverrideCaseFoldPartCount' => $overrideCaseFoldPartSummary['duplicateGroupCount'],
            'duplicateOverrideCaseFoldDeclarationCount' => $overrideCaseFoldPartSummary['duplicateDeclarationCount'],
            'duplicateOverrideCaseFoldPartNameCount' => $overrideCaseFoldPartSummary['duplicatePartNameCount'],
            'duplicateOverrideCaseFoldPartNames' => $overrideCaseFoldPartSummary['duplicateCaseFoldPartNames'],
            'duplicateOverrideCaseFoldPartNameVariants' => $overrideCaseFoldPartSummary['duplicatePartNameVariants'],
            'duplicateOverrideCaseFoldPartGroups' => $overrideCaseFoldPartSummary['duplicateGroups'],
            'missingOverrideCount' => count($missingOverrides),
            'missingOverrideParts' => array_column($missingOverrides, 'partName'),
            'missingOverrides' => $missingOverrides,
            'missingOverrideTargetCount' => $missingOverrideTargetSummary['count'],
            'missingOverrideTargetItems' => $missingOverrideTargetSummary['items'],
            'missingOverrideTargetPartNames' => $missingOverrideTargetSummary['partNames'],
            'missingOverrideTargetRoleCounts' => $missingOverrideTargetSummary['roleCounts'],
            'missingOverrideTargetContentTypeBaseCounts' => $missingOverrideTargetSummary['contentTypeBaseCounts'],
            'missingOverrideTargetContentTypeParameterNameCounts' => $missingOverrideTargetSummary['contentTypeParameterNameCounts'],
            'missingOverrideTargetParameterizedCount' => $missingOverrideTargetSummary['parameterizedCount'],
            'missingOverrideTargetTopLevelSegmentCounts' => $missingOverrideTargetSummary['topLevelSegmentCounts'],
            'missingOverrideTargetDirectoryCounts' => $missingOverrideTargetSummary['directoryCounts'],
            'missingOverrideTargetExtensionCounts' => $missingOverrideTargetSummary['extensionCounts'],
            'parameterizedContentTypeCount' => count($parameterizedContentTypes),
            'parameterizedContentTypes' => $parameterizedContentTypes,
            'preflight' => $preflight,
            'valid' => $preflight === null ? false : $preflight['valid'],
            'xmlParseError' => $preflight === null ? null : $preflight['parseError'],
            'issues' => $preflight === null ? ['missing-content-types-part'] : $preflight['issues'],
            'issueCounts' => $preflight === null ? ['missing-content-types-part' => 1] : $preflight['issueCounts'],
            'recordCount' => $preflight === null ? 0 : $preflight['recordCount'],
            'invalidRecordCount' => $preflight === null ? 0 : $preflight['invalidCount'],
            'declaredDefaultRecordCount' => $preflight === null ? 0 : $preflight['defaultCount'],
            'declaredOverrideRecordCount' => $preflight === null ? 0 : $preflight['overrideCount'],
            'duplicateDefaultExtensionCount' => $preflight === null ? 0 : $preflight['duplicateDefaultExtensionCount'],
            'duplicateOverridePartNameCount' => $preflight === null ? 0 : $preflight['duplicateOverridePartNameCount'],
            'duplicateDefaultExtensions' => $preflight === null ? [] : $preflight['duplicateDefaultExtensions'],
            'duplicateOverridePartNames' => $preflight === null ? [] : $preflight['duplicateOverridePartNames'],
            'duplicateDefaultExtensionGroups' => $preflight === null ? [] : $preflight['duplicateDefaultExtensionGroups'],
            'duplicateOverridePartNameGroups' => $preflight === null ? [] : $preflight['duplicateOverridePartNameGroups'],
            'invalidContentTypeRecordIssueCounts' => $this->issueBucketCounts($invalidContentTypeRecordIssueBuckets),
            'invalidContentTypeRecordIssueCodes' => array_keys($invalidContentTypeRecordIssueBuckets),
            'invalidContentTypeRecordIssueBuckets' => $invalidContentTypeRecordIssueBuckets,
            'invalidContentTypeRecords' => $invalidContentTypeRecords,
        ];
    }

    /**
     * @param ?array<string, mixed> $preflight
     * @return list<array<string, mixed>>
     */
    private function invalidContentTypeRecordSnapshots(?array $preflight): array
    {
        if ($preflight === null || !is_array($preflight['records'] ?? null)) {
            return [];
        }

        $records = [];
        foreach ($preflight['records'] as $record) {
            if (!is_array($record) || ($record['valid'] ?? true) === true) {
                continue;
            }

            $records[] = [
                'recordIndex' => (int) ($record['recordIndex'] ?? count($records)),
                'kind' => is_string($record['kind'] ?? null) ? $record['kind'] : '',
                'extension' => is_string($record['extension'] ?? null) ? $record['extension'] : null,
                'normalizedExtension' => is_string($record['normalizedExtension'] ?? null) ? $record['normalizedExtension'] : null,
                'partName' => is_string($record['partName'] ?? null) ? $record['partName'] : null,
                'normalizedPartName' => is_string($record['normalizedPartName'] ?? null) ? $record['normalizedPartName'] : null,
                'contentType' => is_string($record['contentType'] ?? null) ? $record['contentType'] : null,
                'equivalenceKey' => is_string($record['equivalenceKey'] ?? null) ? $record['equivalenceKey'] : null,
                'issues' => is_array($record['issues'] ?? null)
                    ? array_values(array_map('strval', $record['issues']))
                    : [],
            ];
        }

        usort($records, static fn (array $left, array $right): int => $left['recordIndex'] <=> $right['recordIndex']);

        return $records;
    }

    /**
     * @param list<array<string, mixed>> $records
     * @return array<string, list<array<string, mixed>>>
     */
    private function contentTypeRecordIssueBuckets(array $records): array
    {
        $buckets = [];
        foreach ($records as $record) {
            $issues = is_array($record['issues'] ?? null) ? $record['issues'] : [];
            foreach ($issues as $issue) {
                $issue = (string) $issue;
                if ($issue === '') {
                    continue;
                }

                $buckets[$issue][] = [
                    'recordIndex' => (int) ($record['recordIndex'] ?? 0),
                    'kind' => is_string($record['kind'] ?? null) ? $record['kind'] : '',
                    'extension' => is_string($record['extension'] ?? null) ? $record['extension'] : null,
                    'normalizedExtension' => is_string($record['normalizedExtension'] ?? null) ? $record['normalizedExtension'] : null,
                    'partName' => is_string($record['partName'] ?? null) ? $record['partName'] : null,
                    'normalizedPartName' => is_string($record['normalizedPartName'] ?? null) ? $record['normalizedPartName'] : null,
                    'contentType' => is_string($record['contentType'] ?? null) ? $record['contentType'] : null,
                ];
            }
        }

        ksort($buckets, SORT_STRING);

        return $buckets;
    }

    /**
     * @param array<string, list<array<string, mixed>>> $buckets
     * @return array<string, int>
     */
    private function issueBucketCounts(array $buckets): array
    {
        $counts = [];
        foreach ($buckets as $issue => $records) {
            $counts[(string) $issue] = count($records);
        }

        return $counts;
    }

    /**
     * @param array<string, string> $parts
     * @param array{defaults:array<string, string>, overrides:array<string, string>} $contentTypes
     * @return array{declarationCount:int, usedDeclarationCount:int, unusedDeclarationCount:int, defaultResolvedPartCount:int, overrideResolvedPartCount:int, missingPartCount:int, extensionlessMissingPartCount:int, unusedExtensions:list<string>, missingExtensions:list<string>, issueCounts:array<string, int>, issues:list<string>, declarations:list<array<string, mixed>>, missingParts:list<array<string, mixed>>}
     */
    private function contentTypeDefaultDeclarationSummary(array $parts, array $contentTypes): array
    {
        $declarations = [];
        foreach ($contentTypes['defaults'] as $extension => $contentType) {
            $declarations[$extension] = [
                'extension' => $extension,
                'normalizedExtension' => strtolower($extension),
                'packagePartCount' => 0,
                'relationshipPartCount' => 0,
                'byteLength' => 0,
                'packageParts' => [],
                'valid' => true,
                'issues' => [],
            ] + $this->contentTypeReport($contentType);
        }

        $defaultResolvedPartCount = 0;
        $overrideResolvedPartCount = 0;
        $missingParts = [];
        $missingExtensions = [];
        $issueCounts = [];
        $contentTypeBaseCounts = [];
        $contentTypeParameterNameCounts = [];
        $parameterizedDeclarationCount = 0;
        $extensionlessMissingPartCount = 0;
        foreach ($declarations as $declaration) {
            $contentTypeBase = is_string($declaration['contentTypeBase'] ?? null) ? $declaration['contentTypeBase'] : '';
            $contentTypeBaseKey = $contentTypeBase === '' ? '(missing)' : $contentTypeBase;
            $contentTypeBaseCounts[$contentTypeBaseKey] = ($contentTypeBaseCounts[$contentTypeBaseKey] ?? 0) + 1;
            $parameterMap = is_array($declaration['contentTypeParameterMap'] ?? null)
                ? $declaration['contentTypeParameterMap']
                : [];
            if ($parameterMap !== []) {
                ++$parameterizedDeclarationCount;
            }
            foreach ($parameterMap as $parameterName => $_parameterValue) {
                if (is_string($parameterName) && $parameterName !== '') {
                    $contentTypeParameterNameCounts[$parameterName] = ($contentTypeParameterNameCounts[$parameterName] ?? 0) + 1;
                }
            }
        }

        foreach ($parts as $partName => $contents) {
            $resolution = $this->contentTypeResolutionForPart($partName, $contentTypes);
            $source = $resolution['contentTypeSource'] ?? 'missing';

            if ($source === 'override') {
                ++$overrideResolvedPartCount;
                continue;
            }

            if ($source === 'default') {
                ++$defaultResolvedPartCount;
                $defaultExtension = is_string($resolution['defaultExtension'] ?? null)
                    ? $resolution['defaultExtension']
                    : '';
                if (isset($declarations[$defaultExtension])) {
                    ++$declarations[$defaultExtension]['packagePartCount'];
                    $declarations[$defaultExtension]['byteLength'] += strlen($contents);
                    $declarations[$defaultExtension]['packageParts'][] = $partName;
                    if ($this->isRelationshipPartName($partName)) {
                        ++$declarations[$defaultExtension]['relationshipPartCount'];
                    }
                }
                continue;
            }

            $extension = is_string($resolution['defaultExtension'] ?? null)
                ? $resolution['defaultExtension']
                : null;
            $issues = ['missing-content-type'];
            if ($extension === null || $extension === '') {
                ++$extensionlessMissingPartCount;
                $extension = null;
                $issues[] = 'missing-content-type-extension';
            } else {
                $this->appendUniqueString($missingExtensions, $extension);
                $issues[] = 'missing-content-type-default';
            }

            foreach ($issues as $issue) {
                $issueCounts[$issue] = ($issueCounts[$issue] ?? 0) + 1;
            }

            $missingParts[] = [
                'partName' => $partName,
                'extension' => $extension,
                'bytes' => strlen($contents),
                'relationshipPart' => $this->isRelationshipPartName($partName),
                'issues' => $issues,
            ];
        }

        $usedDeclarationCount = 0;
        $unusedExtensions = [];
        foreach ($declarations as &$declaration) {
            sort($declaration['packageParts'], SORT_STRING);
            if ($declaration['packagePartCount'] > 0) {
                ++$usedDeclarationCount;
            } else {
                $unusedExtensions[] = $declaration['extension'];
            }
        }
        unset($declaration);

        sort($unusedExtensions, SORT_STRING);
        sort($missingExtensions, SORT_STRING);
        ksort($contentTypeBaseCounts, SORT_STRING);
        ksort($contentTypeParameterNameCounts, SORT_STRING);
        ksort($issueCounts, SORT_STRING);
        usort(
            $missingParts,
            static fn (array $left, array $right): int => strcmp((string) $left['partName'], (string) $right['partName'])
        );

        return [
            'declarationCount' => count($declarations),
            'usedDeclarationCount' => $usedDeclarationCount,
            'unusedDeclarationCount' => count($unusedExtensions),
            'defaultResolvedPartCount' => $defaultResolvedPartCount,
            'overrideResolvedPartCount' => $overrideResolvedPartCount,
            'missingPartCount' => count($missingParts),
            'extensionlessMissingPartCount' => $extensionlessMissingPartCount,
            'unusedExtensions' => $unusedExtensions,
            'missingExtensions' => $missingExtensions,
            'parameterizedDeclarationCount' => $parameterizedDeclarationCount,
            'contentTypeBaseCounts' => $contentTypeBaseCounts,
            'contentTypeParameterNameCounts' => $contentTypeParameterNameCounts,
            'issueCounts' => $issueCounts,
            'issues' => array_keys($issueCounts),
            'declarations' => array_values($declarations),
            'missingParts' => $missingParts,
        ];
    }

    /**
     * @param array<string, string> $parts
     * @param array<string, array<string, mixed>> $overrides
     * @return array{declarationCount:int, usedDeclarationCount:int, unusedDeclarationCount:int, invalidDeclarationCount:int, unusedPartNames:list<string>, parameterizedDeclarationCount:int, contentTypeBaseCounts:array<string, int>, contentTypeParameterNameCounts:array<string, int>, issueCounts:array<string, int>, issues:list<string>, declarations:list<array<string, mixed>>}
     */
    private function contentTypeOverrideDeclarationSummary(array $parts, array $overrides): array
    {
        $declarations = [];
        $unusedPartNames = [];
        $issueCounts = [];
        $contentTypeBaseCounts = [];
        $contentTypeParameterNameCounts = [];
        $usedDeclarationCount = 0;
        $invalidDeclarationCount = 0;
        $parameterizedDeclarationCount = 0;

        foreach ($overrides as $partName => $override) {
            $exists = isset($parts[$partName]);
            $relationshipPart = $this->isRelationshipPartName($partName);
            $relationshipSource = null;
            $relationshipSourceExists = null;
            $issues = [];

            if ($exists) {
                ++$usedDeclarationCount;
            } else {
                $issues[] = 'override-target-missing-part';
                $unusedPartNames[] = $partName;
            }

            $contentTypeBase = is_string($override['contentTypeBase'] ?? null)
                ? $override['contentTypeBase']
                : '';
            $contentTypeBaseKey = $contentTypeBase === '' ? '(missing)' : $contentTypeBase;
            $contentTypeBaseCounts[$contentTypeBaseKey] = ($contentTypeBaseCounts[$contentTypeBaseKey] ?? 0) + 1;
            $parameterMap = is_array($override['contentTypeParameterMap'] ?? null)
                ? $override['contentTypeParameterMap']
                : [];
            if ($parameterMap !== []) {
                ++$parameterizedDeclarationCount;
            }
            foreach ($parameterMap as $parameterName => $_parameterValue) {
                if (is_string($parameterName) && $parameterName !== '') {
                    $contentTypeParameterNameCounts[$parameterName] = ($contentTypeParameterNameCounts[$parameterName] ?? 0) + 1;
                }
            }

            if ($partName === '[Content_Types].xml') {
                $issues[] = 'content-types-override-target';
            }

            if ($relationshipPart) {
                $relationshipSource = $this->relationshipSourcePartForInventory($partName);
                $relationshipSourceExists = $this->relationshipSourceExists($parts, $relationshipSource);

                if ($contentTypeBase !== self::CT_PACKAGE_RELATIONSHIPS) {
                    $issues[] = 'invalid-relationship-content-type';
                }
                if (!$relationshipSourceExists) {
                    $issues[] = 'relationship-override-source-missing';
                }
            } elseif ($contentTypeBase === self::CT_PACKAGE_RELATIONSHIPS) {
                $issues[] = 'relationship-content-type-on-non-relationship-part';
            }

            $issues = array_values(array_unique($issues));
            sort($issues, SORT_STRING);
            if ($issues !== []) {
                ++$invalidDeclarationCount;
                foreach ($issues as $issue) {
                    $issueCounts[$issue] = ($issueCounts[$issue] ?? 0) + 1;
                }
            }

            $declarations[] = [
                'partName' => $partName,
                'contentType' => is_string($override['contentType'] ?? null) ? $override['contentType'] : '',
                'contentTypeBase' => $contentTypeBase,
                'contentTypeHasParameters' => (bool) ($override['contentTypeHasParameters'] ?? false),
                'contentTypeParameterCount' => (int) ($override['contentTypeParameterCount'] ?? 0),
                'contentTypeParameters' => is_array($override['contentTypeParameters'] ?? null) ? $override['contentTypeParameters'] : [],
                'contentTypeParameterMap' => is_array($override['contentTypeParameterMap'] ?? null) ? $override['contentTypeParameterMap'] : [],
                'exists' => $exists,
                'matchKind' => $exists ? 'exact' : 'missing',
                'relationshipPart' => $relationshipPart,
                'relationshipSource' => $relationshipSource,
                'relationshipSourceExists' => $relationshipSourceExists,
                'valid' => $issues === [],
                'issues' => $issues,
            ];
        }

        sort($unusedPartNames, SORT_STRING);
        ksort($contentTypeBaseCounts, SORT_STRING);
        ksort($contentTypeParameterNameCounts, SORT_STRING);
        ksort($issueCounts, SORT_STRING);

        return [
            'declarationCount' => count($declarations),
            'usedDeclarationCount' => $usedDeclarationCount,
            'unusedDeclarationCount' => count($unusedPartNames),
            'invalidDeclarationCount' => $invalidDeclarationCount,
            'unusedPartNames' => $unusedPartNames,
            'parameterizedDeclarationCount' => $parameterizedDeclarationCount,
            'contentTypeBaseCounts' => $contentTypeBaseCounts,
            'contentTypeParameterNameCounts' => $contentTypeParameterNameCounts,
            'issueCounts' => $issueCounts,
            'issues' => array_keys($issueCounts),
            'declarations' => $declarations,
        ];
    }

    /**
     * @param array<string, string> $parts
     * @param array<string, array<string, mixed>> $overrides
     * @return array<string, mixed>
     */
    private function contentTypeOverrideCaseFoldPartSummary(array $parts, array $overrides): array
    {
        $groups = [];
        foreach ($overrides as $partName => $override) {
            if (!is_string($partName) || $partName === '') {
                continue;
            }

            $caseFoldPartName = $this->packagePartCaseFoldKey($partName);
            $groups[$caseFoldPartName] ??= [
                'caseFoldPartName' => $caseFoldPartName,
                'declarationCount' => 0,
                'partNameVariantCount' => 0,
                'existingDeclarationCount' => 0,
                'missingDeclarationCount' => 0,
                'parameterizedDeclarationCount' => 0,
                'existingPartByteLength' => 0,
                'partNameCounts' => [],
                'contentTypeBaseCounts' => [],
                'contentTypeParameterNameCounts' => [],
                'partNames' => [],
                'existingPartNames' => [],
                'missingPartNames' => [],
                'contentTypes' => [],
                'contentTypeBases' => [],
                'largestExistingPart' => null,
                '_seenExistingPartNames' => [],
            ];

            ++$groups[$caseFoldPartName]['declarationCount'];
            $groups[$caseFoldPartName]['partNameCounts'][$partName] =
                (int) ($groups[$caseFoldPartName]['partNameCounts'][$partName] ?? 0) + 1;
            $groups[$caseFoldPartName]['partNameVariantCount'] = count($groups[$caseFoldPartName]['partNameCounts']);
            $this->appendUniqueString($groups[$caseFoldPartName]['partNames'], $partName);

            $exists = isset($parts[$partName]);
            if ($exists) {
                ++$groups[$caseFoldPartName]['existingDeclarationCount'];
                $this->appendUniqueString($groups[$caseFoldPartName]['existingPartNames'], $partName);
            } else {
                ++$groups[$caseFoldPartName]['missingDeclarationCount'];
                $this->appendUniqueString($groups[$caseFoldPartName]['missingPartNames'], $partName);
            }

            $contentType = is_string($override['contentType'] ?? null) ? $override['contentType'] : '';
            $contentTypeBase = is_string($override['contentTypeBase'] ?? null) ? $override['contentTypeBase'] : '';
            $contentTypeBaseKey = $contentTypeBase === '' ? '(missing)' : $contentTypeBase;
            $groups[$caseFoldPartName]['contentTypeBaseCounts'][$contentTypeBaseKey] =
                (int) ($groups[$caseFoldPartName]['contentTypeBaseCounts'][$contentTypeBaseKey] ?? 0) + 1;
            $this->appendUniqueString($groups[$caseFoldPartName]['contentTypes'], $contentType);
            $this->appendUniqueString($groups[$caseFoldPartName]['contentTypeBases'], $contentTypeBase);

            $parameterMap = is_array($override['contentTypeParameterMap'] ?? null)
                ? $override['contentTypeParameterMap']
                : [];
            if ($parameterMap !== []) {
                ++$groups[$caseFoldPartName]['parameterizedDeclarationCount'];
            }
            foreach ($parameterMap as $parameterName => $_parameterValue) {
                if (is_string($parameterName) && $parameterName !== '') {
                    $groups[$caseFoldPartName]['contentTypeParameterNameCounts'][$parameterName] =
                        (int) ($groups[$caseFoldPartName]['contentTypeParameterNameCounts'][$parameterName] ?? 0) + 1;
                }
            }

            if (!$exists || isset($groups[$caseFoldPartName]['_seenExistingPartNames'][$partName])) {
                continue;
            }

            $groups[$caseFoldPartName]['_seenExistingPartNames'][$partName] = true;
            $bytes = strlen($parts[$partName]);
            $groups[$caseFoldPartName]['existingPartByteLength'] += $bytes;
            $partSummary = [
                'partName' => $partName,
                'bytes' => $bytes,
                'sha256' => hash('sha256', $parts[$partName]),
                'contentType' => $contentType,
                'contentTypeBase' => $contentTypeBase,
                'contentTypeHasParameters' => (bool) ($override['contentTypeHasParameters'] ?? false),
                'contentTypeParameterMap' => $parameterMap,
            ];
            $largestExistingPart = $groups[$caseFoldPartName]['largestExistingPart'];
            if (
                !is_array($largestExistingPart)
                || $bytes > (int) ($largestExistingPart['bytes'] ?? 0)
                || (
                    $bytes === (int) ($largestExistingPart['bytes'] ?? 0)
                    && strcmp($partName, (string) ($largestExistingPart['partName'] ?? '')) < 0
                )
            ) {
                $groups[$caseFoldPartName]['largestExistingPart'] = $partSummary;
            }
        }

        ksort($groups, SORT_STRING);

        $duplicateGroups = [];
        $duplicateCaseFoldPartNames = [];
        $duplicatePartNameVariants = [];
        $duplicateDeclarationCount = 0;
        $duplicatePartNameCount = 0;
        foreach ($groups as &$group) {
            ksort($group['partNameCounts'], SORT_STRING);
            ksort($group['contentTypeBaseCounts'], SORT_STRING);
            ksort($group['contentTypeParameterNameCounts'], SORT_STRING);
            sort($group['partNames'], SORT_STRING);
            sort($group['existingPartNames'], SORT_STRING);
            sort($group['missingPartNames'], SORT_STRING);
            sort($group['contentTypes'], SORT_STRING);
            sort($group['contentTypeBases'], SORT_STRING);
            unset($group['_seenExistingPartNames']);

            if ((int) $group['partNameVariantCount'] < 2) {
                continue;
            }

            $duplicateGroups[] = $group;
            $duplicateCaseFoldPartNames[] = (string) $group['caseFoldPartName'];
            $duplicateDeclarationCount += (int) $group['declarationCount'];
            $duplicatePartNameCount += (int) $group['partNameVariantCount'];
            foreach ($group['partNames'] as $partName) {
                $this->appendUniqueString($duplicatePartNameVariants, is_string($partName) ? $partName : null);
            }
        }
        unset($group);

        sort($duplicateCaseFoldPartNames, SORT_STRING);
        sort($duplicatePartNameVariants, SORT_STRING);

        return [
            'caseFoldPartCount' => count($groups),
            'duplicateGroupCount' => count($duplicateGroups),
            'duplicateDeclarationCount' => $duplicateDeclarationCount,
            'duplicatePartNameCount' => $duplicatePartNameCount,
            'duplicateCaseFoldPartNames' => $duplicateCaseFoldPartNames,
            'duplicatePartNameVariants' => $duplicatePartNameVariants,
            'duplicateGroups' => $duplicateGroups,
        ];
    }

    /**
     * @param list<array<string, mixed>> $missingOverrides
     * @return array<string, mixed>
     */
    private function contentTypeMissingOverrideTargetSummary(array $missingOverrides): array
    {
        $items = [];
        $partNames = [];
        $roleCounts = [];
        $contentTypeBaseCounts = [];
        $contentTypeParameterNameCounts = [];
        $topLevelSegmentCounts = [];
        $directoryCounts = [];
        $extensionCounts = [];
        $parameterizedCount = 0;

        foreach ($missingOverrides as $declaration) {
            $partName = is_string($declaration['partName'] ?? null) ? $declaration['partName'] : '';
            if ($partName === '') {
                continue;
            }

            $directory = $this->packagePartDirectory($partName);
            $pathSegments = $this->packagePartPathSegments($partName);
            $partExtension = $this->packagePartExtension($partName);
            $extensionKey = $partExtension ?? '(none)';
            $contentTypeBase = is_string($declaration['contentTypeBase'] ?? null) ? $declaration['contentTypeBase'] : '';
            $contentTypeBaseKey = $contentTypeBase === '' ? '(missing)' : $contentTypeBase;
            $parameterMap = is_array($declaration['contentTypeParameterMap'] ?? null)
                ? $declaration['contentTypeParameterMap']
                : [];
            $roles = $this->missingOverrideTargetRoles($declaration);
            $topLevelSegment = $pathSegments[0] ?? '';

            $partNames[] = $partName;
            $contentTypeBaseCounts[$contentTypeBaseKey] = ($contentTypeBaseCounts[$contentTypeBaseKey] ?? 0) + 1;
            $topLevelSegmentCounts[$topLevelSegment] = ($topLevelSegmentCounts[$topLevelSegment] ?? 0) + 1;
            $directoryCounts[$directory] = ($directoryCounts[$directory] ?? 0) + 1;
            $extensionCounts[$extensionKey] = ($extensionCounts[$extensionKey] ?? 0) + 1;
            foreach ($roles as $role) {
                $roleCounts[$role] = ($roleCounts[$role] ?? 0) + 1;
            }
            if ($parameterMap !== []) {
                ++$parameterizedCount;
            }
            foreach ($parameterMap as $parameterName => $_parameterValue) {
                if (is_string($parameterName) && $parameterName !== '') {
                    $contentTypeParameterNameCounts[$parameterName] = ($contentTypeParameterNameCounts[$parameterName] ?? 0) + 1;
                }
            }

            $items[] = [
                'partName' => $partName,
                'directory' => $directory,
                'directoryDepth' => $this->packagePartDirectoryDepth($directory),
                'topLevelSegment' => $topLevelSegment,
                'baseName' => $this->packagePartBaseName($partName),
                'baseNameStem' => $this->packagePartBaseNameStem($partName),
                'pathSegments' => $pathSegments,
                'pathSegmentCount' => count($pathSegments),
                'partExtension' => $partExtension,
                'rawPartExtension' => $this->packagePartRawExtension($partName),
                'contentType' => is_string($declaration['contentType'] ?? null) ? $declaration['contentType'] : '',
                'contentTypeBase' => $contentTypeBase,
                'contentTypeHasParameters' => (bool) ($declaration['contentTypeHasParameters'] ?? false),
                'contentTypeParameterCount' => (int) ($declaration['contentTypeParameterCount'] ?? count($parameterMap)),
                'contentTypeParameters' => is_array($declaration['contentTypeParameters'] ?? null) ? $declaration['contentTypeParameters'] : [],
                'contentTypeParameterMap' => $parameterMap,
                'relationshipPart' => (bool) ($declaration['relationshipPart'] ?? false),
                'relationshipSource' => is_string($declaration['relationshipSource'] ?? null) ? $declaration['relationshipSource'] : null,
                'relationshipSourceExists' => $declaration['relationshipSourceExists'] ?? null,
                'exists' => false,
                'roles' => $roles,
                'issues' => is_array($declaration['issues'] ?? null) ? array_values(array_map('strval', $declaration['issues'])) : [],
                'byteExposurePolicy' => 'content-type-override-missing-target-no-bytes',
                'reviewPolicy' => 'content-type-override-missing-target-metadata-only',
            ];
        }

        sort($partNames, SORT_STRING);
        ksort($roleCounts, SORT_STRING);
        ksort($contentTypeBaseCounts, SORT_STRING);
        ksort($contentTypeParameterNameCounts, SORT_STRING);
        ksort($topLevelSegmentCounts, SORT_STRING);
        ksort($directoryCounts, SORT_STRING);
        ksort($extensionCounts, SORT_STRING);

        return [
            'count' => count($items),
            'items' => $items,
            'partNames' => $partNames,
            'roleCounts' => $roleCounts,
            'contentTypeBaseCounts' => $contentTypeBaseCounts,
            'contentTypeParameterNameCounts' => $contentTypeParameterNameCounts,
            'parameterizedCount' => $parameterizedCount,
            'topLevelSegmentCounts' => $topLevelSegmentCounts,
            'directoryCounts' => $directoryCounts,
            'extensionCounts' => $extensionCounts,
        ];
    }

    /**
     * @param array<string, mixed> $declaration
     * @return list<string>
     */
    private function missingOverrideTargetRoles(array $declaration): array
    {
        $roles = ['content-type-override-target', 'missing-package-part'];
        if (($declaration['relationshipPart'] ?? false) === true) {
            $roles[] = 'relationship-part';
            if (($declaration['relationshipSourceExists'] ?? null) === false) {
                $roles[] = 'missing-relationship-source';
            }
        }

        $contentTypeBase = is_string($declaration['contentTypeBase'] ?? null) ? $declaration['contentTypeBase'] : '';
        $contentTypeRole = $this->contentTypeBaseInventoryRole($contentTypeBase);
        if ($contentTypeRole !== null) {
            $roles[] = $contentTypeRole;
        }

        return array_values(array_unique($roles));
    }

    private function contentTypeBaseInventoryRole(string $contentTypeBase): ?string
    {
        return match (strtolower($contentTypeBase)) {
            self::CT_WORD_DOCUMENT,
            self::CT_WORD_TEMPLATE,
            self::CT_WORD_MACRO_ENABLED_DOCUMENT,
            self::CT_WORD_MACRO_ENABLED_TEMPLATE => 'office-document',
            self::CT_CORE_PROPERTIES => 'core-properties',
            self::CT_EXTENDED_PROPERTIES => 'extended-properties',
            self::CT_CUSTOM_PROPERTIES => 'custom-properties',
            self::CT_WORD_STYLES => 'styles',
            self::CT_WORD_STYLES_WITH_EFFECTS => 'styles-with-effects',
            self::CT_WORD_NUMBERING => 'numbering',
            self::CT_WORD_SETTINGS => 'settings',
            self::CT_WORD_PRINTER_SETTINGS => 'printer-settings',
            self::CT_WORD_WEB_SETTINGS => 'web-settings',
            self::CT_WORD_FONT_TABLE => 'font-table',
            self::CT_THEME => 'theme',
            self::CT_WORD_GLOSSARY_DOCUMENT => 'glossary-document',
            self::CT_WORD_FOOTNOTES => 'footnotes',
            self::CT_WORD_ENDNOTES => 'endnotes',
            self::CT_WORD_COMMENTS => 'comments',
            self::CT_WORD_COMMENTS_EXTENDED => 'comments-extended',
            self::CT_WORD_COMMENTS_IDS => 'comments-ids',
            self::CT_WORD_PEOPLE => 'people',
            self::CT_WORD_HEADER => 'header-part',
            self::CT_WORD_FOOTER => 'footer-part',
            self::CT_WORD_BIBLIOGRAPHY => 'bibliography-part',
            self::CT_CUSTOM_XML_PROPERTIES => 'custom-xml-properties',
            self::CT_PACKAGE_RELATIONSHIPS => 'relationship-part',
            self::CT_CHART => 'chart-part',
            self::CT_DIAGRAM_DATA => 'diagram-data',
            self::CT_DIAGRAM_LAYOUT => 'diagram-layout',
            self::CT_DIAGRAM_QUICK_STYLE => 'diagram-quick-style',
            self::CT_DIAGRAM_COLORS => 'diagram-colors',
            self::CT_ACTIVEX_XML => 'activex-control',
            self::CT_ACTIVEX_BINARY => 'activex-binary',
            self::CT_VBA_PROJECT => 'vba-project',
            self::CT_VBA_PROJECT_SIGNATURE => 'vba-project-signature',
            self::CT_VBA_DATA => 'vba-data',
            self::CT_DIGITAL_SIGNATURE_ORIGIN => 'digital-signature-origin',
            self::CT_DIGITAL_SIGNATURE_XMLSIGNATURE => 'digital-signature-signature',
            default => null,
        };
    }

    /**
     * @param array<string, string> $parts
     * @param array<string, array{id:string, type:string, target:string, targetMode:string, resolvedTarget:string}> $relationships
     * @param array{defaults:array<string, string>, overrides:array<string, string>} $contentTypes
     * @return array<string, mixed>
     */
    private function relationshipPartProvenance(
        array $parts,
        string $relationshipsPart,
        string $sourcePart,
        array $relationships,
        array $contentTypes,
    ): array {
        $recordDiagnostics = $this->readRelationshipRecordsPartDiagnostics($parts, $relationshipsPart);
        $relationshipSummaries = [];
        foreach ($relationships as $id => $relationship) {
            $relationshipSummaries[$id] = $this->relationshipInventorySummary($parts, $relationship, $sourcePart, $relationshipsPart, $contentTypes);
        }
        $relationshipRecords = $this->relationshipRecordProvenance(
            $parts,
            $relationshipsPart,
            $sourcePart,
            $contentTypes,
            $recordDiagnostics['records'],
        );
        $relationshipPartIssueCodes = array_values(array_map('strval', $recordDiagnostics['issues']));
        $duplicateIds = [];
        foreach ($relationshipRecords as $record) {
            if (($record['duplicateId'] ?? false) === true) {
                $duplicateIds[(string) $record['id']] = true;
            }
        }
        $duplicateItems = $this->duplicateRelationshipIdItems($relationshipRecords);
        $duplicateRecordCount = count(array_filter($relationshipRecords, static fn (array $record): bool => ($record['duplicateId'] ?? false) === true));
        $invalidRecords = array_values(array_filter($relationshipRecords, static fn (array $record): bool => ($record['valid'] ?? true) !== true));
        $recordIssueCodes = [];
        $recordIssueCount = 0;
        foreach ($invalidRecords as $record) {
            foreach (($record['issues'] ?? []) as $issue) {
                if (is_string($issue) && $issue !== '') {
                    $recordIssueCodes[$issue] = true;
                    ++$recordIssueCount;
                }
            }
        }
        ksort($recordIssueCodes);

        return [
            'partName' => $relationshipsPart,
            'sourcePart' => $sourcePart,
            'sourceExists' => $this->relationshipSourceExists($parts, $sourcePart),
            'exists' => isset($parts[$relationshipsPart]),
            'bytes' => isset($parts[$relationshipsPart]) ? strlen($parts[$relationshipsPart]) : 0,
            'validXml' => $recordDiagnostics['validXml'],
            'validRoot' => $recordDiagnostics['validRoot'],
            'rootNamespace' => $recordDiagnostics['rootNamespace'],
            'rootLocalName' => $recordDiagnostics['rootLocalName'],
            'xmlParseError' => $recordDiagnostics['xmlParseError'],
            'relationshipCount' => count($relationshipSummaries),
        ] + $this->relationshipPartTargetSummary($relationshipSummaries) + [
            'relationshipRecordCount' => count($relationshipRecords),
            'relationshipPartIssueCount' => count($relationshipPartIssueCodes),
            'relationshipPartIssueCodes' => $relationshipPartIssueCodes,
            'duplicateRelationshipIdCount' => count($duplicateIds),
            'duplicateRelationshipRecordCount' => $duplicateRecordCount,
            'duplicateRelationshipIds' => array_keys($duplicateIds),
            'duplicateRelationshipIdItems' => $duplicateItems,
            'invalidRelationshipRecordCount' => count($invalidRecords),
            'relationshipRecordIssueCount' => $recordIssueCount,
            'relationshipRecordIssueCodes' => array_keys($recordIssueCodes),
            'invalidRelationshipRecords' => $invalidRecords,
            'relationships' => $relationshipSummaries,
            'relationshipRecords' => $relationshipRecords,
        ];
    }

    /**
     * @param array<string, array<string, mixed>> $relationshipSummaries
     * @return array<string, mixed>
     */
    private function relationshipPartTargetSummary(array $relationshipSummaries): array
    {
        $internalRelationshipCount = 0;
        $externalRelationshipCount = 0;
        $existingTargetCount = 0;
        $missingTargetCount = 0;
        $missingContentTypeTargetCount = 0;
        $targetParts = [];
        $existingTargetParts = [];
        $missingTargetParts = [];
        $externalTargets = [];
        $contentTypes = [];
        $contentTypeBases = [];

        foreach ($relationshipSummaries as $relationship) {
            if (($relationship['external'] ?? false) === true) {
                ++$externalRelationshipCount;
                $this->appendUniqueString($externalTargets, is_string($relationship['target'] ?? null) ? $relationship['target'] : null);

                continue;
            }

            ++$internalRelationshipCount;
            $targetPart = is_string($relationship['targetPart'] ?? null) ? $relationship['targetPart'] : null;
            $this->appendUniqueString($targetParts, $targetPart);
            $this->appendUniqueString($contentTypes, is_string($relationship['contentType'] ?? null) ? $relationship['contentType'] : null);
            $this->appendUniqueString($contentTypeBases, is_string($relationship['contentTypeBase'] ?? null) ? $relationship['contentTypeBase'] : null);

            if (($relationship['exists'] ?? false) === true) {
                ++$existingTargetCount;
                $this->appendUniqueString($existingTargetParts, $targetPart);
            } else {
                ++$missingTargetCount;
                $this->appendUniqueString($missingTargetParts, $targetPart);
            }

            if (($relationship['contentTypeSource'] ?? '') === 'missing') {
                ++$missingContentTypeTargetCount;
            }
        }

        return [
            'internalRelationshipCount' => $internalRelationshipCount,
            'externalRelationshipCount' => $externalRelationshipCount,
            'existingTargetCount' => $existingTargetCount,
            'missingTargetCount' => $missingTargetCount,
            'missingContentTypeTargetCount' => $missingContentTypeTargetCount,
            'targetPartCount' => count($targetParts),
            'targetParts' => $targetParts,
            'existingTargetParts' => $existingTargetParts,
            'missingTargetParts' => $missingTargetParts,
            'externalTargets' => $externalTargets,
            'contentTypes' => $contentTypes,
            'contentTypeBases' => $contentTypeBases,
        ];
    }

    /**
     * @param array<string, string> $parts
     * @param array{defaults:array<string, string>, overrides:array<string, string>} $contentTypes
     * @param list<array{ordinal:int, id:string, type:string, target:string, targetMode:string, resolvedTarget:string}>|null $records
     * @return list<array<string, mixed>>
     */
    private function relationshipRecordProvenance(
        array $parts,
        string $relationshipsPart,
        string $sourcePart,
        array $contentTypes,
        ?array $records = null,
    ): array {
        $records ??= $this->readRelationshipRecordsPart($parts, $relationshipsPart);
        $idCounts = [];
        foreach ($records as $record) {
            $idCounts[$record['id']] = ($idCounts[$record['id']] ?? 0) + 1;
        }

        $items = [];
        foreach ($records as $record) {
            $issues = $this->relationshipRecordIssues($record);
            $summary = $this->relationshipInventorySummary($parts, $record, $sourcePart, $relationshipsPart, $contentTypes);
            $summary['ordinal'] = $record['ordinal'];
            $summary['valid'] = $issues === [];
            $summary['issues'] = $issues;
            $summary['duplicateId'] = $record['id'] !== '' && ($idCounts[$record['id']] ?? 0) > 1;
            $items[] = $summary;
        }

        return $items;
    }

    /**
     * @param array<string, mixed> $record
     * @return list<string>
     */
    private function relationshipRecordIssues(array $record): array
    {
        $issues = [];
        if (($record['id'] ?? '') === '') {
            $issues[] = 'missing-relationship-id';
        }
        if (($record['type'] ?? '') === '') {
            $issues[] = 'missing-relationship-type';
        }
        if (($record['target'] ?? '') === '') {
            $issues[] = 'missing-relationship-target';
        }

        $targetMode = is_string($record['targetMode'] ?? null) ? $record['targetMode'] : '';
        if ($targetMode !== '' && $targetMode !== 'Internal' && $targetMode !== 'External') {
            $issues[] = 'unexpected-relationship-target-mode';
        }

        return $issues;
    }

    /**
     * @param list<array<string, mixed>> $relationshipRecords
     * @return list<array<string, mixed>>
     */
    private function duplicateRelationshipIdItems(array $relationshipRecords): array
    {
        $byId = [];
        foreach ($relationshipRecords as $record) {
            $id = is_string($record['id'] ?? null) ? $record['id'] : '';
            if ($id === '') {
                continue;
            }

            $byId[$id][] = $record;
        }

        $items = [];
        foreach ($byId as $id => $records) {
            if (count($records) < 2) {
                continue;
            }

            $items[] = [
                'id' => $id,
                'relationshipsPart' => is_string($records[0]['relationshipsPart'] ?? null) ? $records[0]['relationshipsPart'] : '',
                'sourcePart' => is_string($records[0]['sourcePart'] ?? null) ? $records[0]['sourcePart'] : '',
                'ordinals' => array_column($records, 'ordinal'),
                'types' => array_column($records, 'type'),
                'targets' => array_column($records, 'target'),
                'targetModes' => array_column($records, 'targetMode'),
                'resolvedTargets' => array_column($records, 'resolvedTarget'),
                'targetParts' => array_column($records, 'targetPart'),
                'targetReferenceSuffixes' => array_column($records, 'targetReferenceSuffix'),
                'externalValues' => array_column($records, 'external'),
                'existsValues' => array_column($records, 'exists'),
                'contentTypes' => array_column($records, 'contentType'),
                'relationships' => $records,
            ];
        }

        return $items;
    }

    /**
     * @param array<string, string> $parts
     * @param array{id:string, type:string, target:string, targetMode:string, resolvedTarget:string} $relationship
     * @param array{defaults:array<string, string>, overrides:array<string, string>} $contentTypes
     * @return array<string, mixed>
     */
    private function relationshipInventorySummary(
        array $parts,
        array $relationship,
        string $sourcePart,
        string $relationshipsPart,
        array $contentTypes,
    ): array {
        $external = $this->isExternalRelationshipTarget($relationship);
        $externalPolicy = $external ? $this->externalRelationshipTargetPolicy($relationship['target']) : null;
        $targetPart = $external || $relationship['target'] === ''
            ? null
            : $this->stripQueryAndFragment($relationship['resolvedTarget']);
        $suffix = $this->targetReferenceSuffix($relationship['resolvedTarget']);
        $queryParameters = $this->targetQueryParameters($suffix['query']);
        $queryParameterNames = [];
        $queryParameterMap = [];
        foreach ($queryParameters as $parameter) {
            $parameterName = $parameter['name'];
            $this->appendUniqueString($queryParameterNames, $parameterName);
            $queryParameterMap[$parameterName][] = $parameter['value'];
        }
        $contentTypeResolution = $targetPart === null
            ? $this->missingContentTypeResolution(null)
            : $this->contentTypeResolutionForPart($targetPart, $contentTypes);
        $targetPath = $this->relationshipTargetPathProvenance(
            $relationship['target'],
            $relationship['targetMode'],
            $sourcePart,
            $targetPart,
            $external,
        );

        return [
            'id' => $relationship['id'],
            'type' => $relationship['type'],
            'sourcePart' => $sourcePart,
            'relationshipsPart' => $relationshipsPart,
            'target' => $relationship['target'],
            'targetMode' => $relationship['targetMode'],
            'external' => $external,
            'resolvedTarget' => $relationship['resolvedTarget'],
            'targetPart' => $targetPart,
            'targetQuery' => $suffix['query'],
            'targetQueryParameterCount' => count($queryParameters),
            'targetQueryParameters' => $queryParameters,
            'targetQueryParameterNames' => $queryParameterNames,
            'targetQueryParameterMap' => $queryParameterMap,
            'targetFragment' => $suffix['fragment'],
            'targetReferenceSuffix' => $suffix['suffix'],
            'targetParentTraversalCount' => $targetPath['parentTraversalCount'],
            'targetHasParentTraversal' => $targetPath['hasParentTraversal'],
            'targetStartsAtPackageRoot' => $targetPath['startsAtPackageRoot'],
            'sameSourcePart' => $targetPath['sameSourcePart'],
            'externalTargetKind' => is_array($externalPolicy) ? $externalPolicy['kind'] : null,
            'externalTargetScheme' => is_array($externalPolicy) ? $externalPolicy['scheme'] : null,
            'externalTargetAllowed' => is_array($externalPolicy) ? $externalPolicy['allowed'] : null,
            'externalTargetIssues' => is_array($externalPolicy) ? $externalPolicy['issues'] : [],
            'exists' => $targetPart !== null && isset($parts[$targetPart]),
            'contentType' => $contentTypeResolution['contentType'],
            'contentTypeBase' => $contentTypeResolution['contentTypeBase'],
            'contentTypeHasParameters' => $contentTypeResolution['contentTypeHasParameters'],
            'contentTypeParameterCount' => $contentTypeResolution['contentTypeParameterCount'],
            'contentTypeParameters' => $contentTypeResolution['contentTypeParameters'],
            'contentTypeParameterMap' => $contentTypeResolution['contentTypeParameterMap'],
            'contentTypeSource' => $contentTypeResolution['contentTypeSource'],
            'defaultExtension' => $contentTypeResolution['defaultExtension'],
            'overridePartName' => $contentTypeResolution['overridePartName'],
        ];
    }

    /**
     * @return array{parentTraversalCount:int, hasParentTraversal:bool, startsAtPackageRoot:bool, sameSourcePart:bool}
     */
    private function relationshipTargetPathProvenance(
        string $target,
        string $targetMode,
        string $sourcePart,
        ?string $targetPart,
        bool $external,
    ): array {
        if ($external || $target === '' || $targetMode === 'External') {
            return [
                'parentTraversalCount' => 0,
                'hasParentTraversal' => false,
                'startsAtPackageRoot' => false,
                'sameSourcePart' => false,
            ];
        }

        $rawTargetPart = preg_replace('/[#?].*$/', '', $target) ?? $target;
        $rawTargetPart = str_replace('\\', '/', $rawTargetPart);
        $segments = array_values(array_filter(
            explode('/', ltrim($rawTargetPart, '/')),
            static fn (string $segment): bool => $segment !== '' && $segment !== '.',
        ));
        $parentTraversalCount = count(array_filter($segments, static fn (string $segment): bool => $segment === '..'));
        $normalizedSourcePart = $this->normalizePartName($sourcePart);

        return [
            'parentTraversalCount' => $parentTraversalCount,
            'hasParentTraversal' => $parentTraversalCount > 0,
            'startsAtPackageRoot' => str_starts_with($rawTargetPart, '/'),
            'sameSourcePart' => $targetPart !== null
                && $normalizedSourcePart !== ''
                && $targetPart === $normalizedSourcePart,
        ];
    }

    /**
     * @param array<string, string> $parts
     * @param array{defaults:array<string, string>, overrides:array<string, string>} $contentTypes
     * @param array<string, array{id:string, type:string, target:string, targetMode:string, resolvedTarget:string}> $rootRelationships
     * @param array<string, array{id:string, type:string, target:string, targetMode:string, resolvedTarget:string}> $documentRelationships
     * @return array<string, array<string, mixed>>
     */
    private function packagePartInventory(
        array $parts,
        array $contentTypes,
        array $rootRelationships,
        string $documentPart,
        string $documentRelationshipsPart,
        array $documentRelationships,
    ): array {
        $rolesByPart = [];
        $this->addPartRole($rolesByPart, '[Content_Types].xml', 'content-types');
        $this->addPartRole($rolesByPart, '_rels/.rels', 'package-relationships');
        $this->addPartRole($rolesByPart, $documentPart, 'office-document');
        $this->addPartRole($rolesByPart, $documentRelationshipsPart, 'office-document-relationships');
        foreach ($parts as $partName => $_contents) {
            if ($this->isRelationshipPartName($partName)) {
                $this->addPartRole($rolesByPart, $partName, 'relationship-part');
            }
        }

        foreach ($rootRelationships as $relationship) {
            if ($this->isExternalRelationshipTarget($relationship)) {
                continue;
            }
            $targetPart = $this->stripQueryAndFragment($relationship['resolvedTarget']);
            $this->addPartRole($rolesByPart, $targetPart, 'root-relationship-target');
            $this->addRelationshipTargetInventoryRole($rolesByPart, $targetPart, $relationship['type']);
        }
        $customUiSourceParts = [];
        foreach ($rootRelationships as $relationship) {
            if (!$this->isCustomUiRelationshipType($relationship['type']) || $this->isExternalRelationshipTarget($relationship)) {
                continue;
            }

            $customUiSourceParts[$this->stripQueryAndFragment($relationship['resolvedTarget'])] = true;
        }
        foreach ($documentRelationships as $relationship) {
            if ($this->isExternalRelationshipTarget($relationship)) {
                continue;
            }
            $targetPart = $this->stripQueryAndFragment($relationship['resolvedTarget']);
            $this->addPartRole($rolesByPart, $targetPart, 'document-relationship-target');
            $this->addRelationshipTargetInventoryRole($rolesByPart, $targetPart, $relationship['type']);
        }
        $headerFooterSourceParts = [];
        $headerFooterSourceTypes = [];
        foreach ($documentRelationships as $relationship) {
            if (
                ($relationship['type'] !== self::HEADER_REL && $relationship['type'] !== self::FOOTER_REL)
                || $this->isExternalRelationshipTarget($relationship)
            ) {
                continue;
            }

            $targetPart = $this->stripQueryAndFragment($relationship['resolvedTarget']);
            $headerFooterSourceParts[$targetPart] = true;
            $headerFooterSourceTypes[$targetPart][$relationship['type'] === self::HEADER_REL ? 'header' : 'footer'] = true;
        }
        foreach ($parts as $relationshipPart => $_contents) {
            if (
                !$this->isRelationshipPartName($relationshipPart)
                || $relationshipPart === '_rels/.rels'
                || $relationshipPart === $documentRelationshipsPart
            ) {
                continue;
            }

            $relationshipSourcePart = $this->relationshipSourcePartForInventory($relationshipPart);
            $relationshipSourceContentTypeBase = '';
            if ($relationshipSourcePart !== '' && $relationshipSourcePart !== '/') {
                $relationshipSourceContentTypeBase = $this->contentTypeResolutionForPart($relationshipSourcePart, $contentTypes)['contentTypeBase'];
            }
            $isNumberingRelationshipPart = $relationshipSourceContentTypeBase === self::CT_WORD_NUMBERING;
            $isThemeRelationshipPart = $relationshipSourceContentTypeBase === self::CT_THEME;
            $isGlossaryRelationshipPart = $relationshipSourceContentTypeBase === self::CT_WORD_GLOSSARY_DOCUMENT;
            $isChartRelationshipPart = $relationshipSourceContentTypeBase === self::CT_CHART;
            $isDiagramRelationshipPart = in_array($relationshipSourceContentTypeBase, [
                self::CT_DIAGRAM_DATA,
                self::CT_DIAGRAM_LAYOUT,
                self::CT_DIAGRAM_QUICK_STYLE,
                self::CT_DIAGRAM_COLORS,
            ], true);
            $isCustomUiRelationshipPart = isset($customUiSourceParts[$relationshipSourcePart]);
            $isHeaderFooterRelationshipPart = isset($headerFooterSourceParts[$relationshipSourcePart])
                || in_array($relationshipSourceContentTypeBase, [self::CT_WORD_HEADER, self::CT_WORD_FOOTER], true);
            $isHeaderRelationshipPart = isset($headerFooterSourceTypes[$relationshipSourcePart]['header'])
                || $relationshipSourceContentTypeBase === self::CT_WORD_HEADER;
            $isFooterRelationshipPart = isset($headerFooterSourceTypes[$relationshipSourcePart]['footer'])
                || $relationshipSourceContentTypeBase === self::CT_WORD_FOOTER;
            $noteCommentMediaRole = match ($relationshipSourceContentTypeBase) {
                self::CT_WORD_FOOTNOTES => 'footnote-media',
                self::CT_WORD_ENDNOTES => 'endnote-media',
                self::CT_WORD_COMMENTS => 'comment-media',
                default => null,
            };
            $noteCommentHyperlinkRole = match ($relationshipSourceContentTypeBase) {
                self::CT_WORD_FOOTNOTES => 'footnote-hyperlink-target',
                self::CT_WORD_ENDNOTES => 'endnote-hyperlink-target',
                self::CT_WORD_COMMENTS => 'comment-hyperlink-target',
                default => null,
            };

            foreach ($this->readRelationshipsPart($parts, $relationshipPart) as $relationship) {
                if ($this->isExternalRelationshipTarget($relationship)) {
                    continue;
                }
                $targetPart = $this->stripQueryAndFragment($relationship['resolvedTarget']);
                $this->addPartRole($rolesByPart, $targetPart, 'relationship-target');
                $this->addRelationshipTargetInventoryRole($rolesByPart, $targetPart, $relationship['type']);
                if ($isNumberingRelationshipPart && $relationship['type'] === self::IMAGE_REL) {
                    $this->addPartRole($rolesByPart, $targetPart, 'numbering-picture-bullet');
                }
                if ($isThemeRelationshipPart && $relationship['type'] === self::IMAGE_REL) {
                    $this->addPartRole($rolesByPart, $targetPart, 'theme-media');
                }
                if ($isGlossaryRelationshipPart && $relationship['type'] === self::IMAGE_REL) {
                    $this->addPartRole($rolesByPart, $targetPart, 'glossary-document-media');
                }
                if ($isGlossaryRelationshipPart && $relationship['type'] === self::HYPERLINK_REL) {
                    $this->addPartRole($rolesByPart, $targetPart, 'glossary-document-hyperlink-target');
                }
                if ($isChartRelationshipPart && $relationship['type'] === self::EMBEDDED_PACKAGE_REL) {
                    $this->addPartRole($rolesByPart, $targetPart, 'chart-embedded-package');
                }
                if ($isDiagramRelationshipPart && $relationship['type'] === self::EMBEDDED_PACKAGE_REL) {
                    $this->addPartRole($rolesByPart, $targetPart, 'diagram-embedded-package');
                }
                if ($isCustomUiRelationshipPart && $relationship['type'] === self::IMAGE_REL) {
                    $this->addPartRole($rolesByPart, $targetPart, 'custom-ui-image');
                }
                if ($isHeaderFooterRelationshipPart && $relationship['type'] === self::IMAGE_REL) {
                    $this->addPartRole($rolesByPart, $targetPart, 'header-footer-media');
                }
                if ($isHeaderFooterRelationshipPart && $relationship['type'] === self::HYPERLINK_REL) {
                    $this->addPartRole($rolesByPart, $targetPart, 'header-footer-hyperlink-target');
                    if ($isHeaderRelationshipPart) {
                        $this->addPartRole($rolesByPart, $targetPart, 'header-hyperlink-target');
                    }
                    if ($isFooterRelationshipPart) {
                        $this->addPartRole($rolesByPart, $targetPart, 'footer-hyperlink-target');
                    }
                }
                if ($noteCommentMediaRole !== null && $relationship['type'] === self::IMAGE_REL) {
                    $this->addPartRole($rolesByPart, $targetPart, $noteCommentMediaRole);
                    $this->addPartRole($rolesByPart, $targetPart, 'note-comment-media');
                }
                if ($noteCommentHyperlinkRole !== null && $relationship['type'] === self::HYPERLINK_REL) {
                    $this->addPartRole($rolesByPart, $targetPart, $noteCommentHyperlinkRole);
                    $this->addPartRole($rolesByPart, $targetPart, 'note-comment-hyperlink-target');
                }
            }
        }

        $inventory = [];
        foreach ($parts as $partName => $contents) {
            $contentTypeResolution = $this->contentTypeResolutionForPart($partName, $contentTypes);
            $partExtension = $this->packagePartExtension($partName);
            $rawPartExtension = $this->packagePartRawExtension($partName);
            $directory = $this->packagePartDirectory($partName);
            $directoryBaseName = $this->packagePartDirectoryBaseName($directory);
            $directoryBaseNameStem = $this->packagePartDirectoryBaseNameStem($directory);
            $baseName = $this->packagePartBaseName($partName);
            $baseNameStem = $this->packagePartBaseNameStem($partName);
            $pathSegments = $this->packagePartPathSegments($partName);
            $roles = array_keys($rolesByPart[$partName] ?? []);
            if ($roles === []) {
                $roles = ['package-part'];
            }
            $partNameCharacterFlags = $this->packagePartNameCharacterFlags($partName);
            $baseNameCharacterFlags = $this->packagePartNameCharacterFlags($baseName);

            $entry = [
                'partName' => $partName,
                'directory' => $directory,
                'directoryBaseName' => $directoryBaseName,
                'directoryBaseNameStem' => $directoryBaseNameStem,
                'caseFoldDirectoryBaseName' => $this->packagePartCaseFoldKey($directoryBaseName),
                'caseFoldDirectoryBaseNameStem' => $this->packagePartCaseFoldKey($directoryBaseNameStem),
                'directoryDepth' => $this->packagePartDirectoryDepth($directory),
                'baseName' => $baseName,
                'baseNameStem' => $baseNameStem,
                'caseFoldPartName' => $this->packagePartCaseFoldKey($partName),
                'caseFoldBaseName' => $this->packagePartCaseFoldKey($baseName),
                'caseFoldBaseNameStem' => $this->packagePartCaseFoldKey($baseNameStem),
                'pathSegments' => $pathSegments,
                'pathSegmentPositionReviews' => $this->packagePartPathSegmentPositionReviews($pathSegments),
                'topLevelSegment' => $pathSegments[0] ?? '',
                'pathSegmentCount' => count($pathSegments),
                'partExtension' => $partExtension,
                'rawPartExtension' => $rawPartExtension,
                'partExtensionHasUppercase' => $rawPartExtension !== null && preg_match('/[A-Z]/', $rawPartExtension) === 1,
                'partExtensionWasNormalized' => $partExtension !== null && $rawPartExtension !== null && $rawPartExtension !== $partExtension,
                'partExtensionDefaultDeclared' => $partExtension !== null && isset($contentTypes['defaults'][$partExtension]),
                'partExtensionDefaultContentType' => $partExtension === null ? null : ($contentTypes['defaults'][$partExtension] ?? null),
                'bytes' => strlen($contents),
                'crc32' => sprintf('%08x', crc32($contents)),
                'sha256' => hash('sha256', $contents),
                'contentType' => $contentTypeResolution['contentType'],
                'contentTypeBase' => $contentTypeResolution['contentTypeBase'],
                'contentTypeHasParameters' => $contentTypeResolution['contentTypeHasParameters'],
                'contentTypeParameterCount' => $contentTypeResolution['contentTypeParameterCount'],
                'contentTypeParameters' => $contentTypeResolution['contentTypeParameters'],
                'contentTypeParameterMap' => $contentTypeResolution['contentTypeParameterMap'],
                'contentTypeSource' => $contentTypeResolution['contentTypeSource'],
                'defaultExtension' => $contentTypeResolution['defaultExtension'],
                'overridePartName' => $contentTypeResolution['overridePartName'],
                'isRelationshipPart' => $this->isRelationshipPartName($partName),
                'roles' => $roles,
                'partNameCharacterFlags' => $partNameCharacterFlags,
                'partNameHasUppercase' => in_array('uppercase', $partNameCharacterFlags, true),
                'partNameHasWhitespace' => in_array('whitespace', $partNameCharacterFlags, true),
                'partNameHasPercentEncodedOctet' => in_array('percent-encoded-octet', $partNameCharacterFlags, true),
                'partNameHasNonAscii' => in_array('non-ascii', $partNameCharacterFlags, true),
                'baseNameCharacterFlags' => $baseNameCharacterFlags,
                'baseNameHasUppercase' => in_array('uppercase', $baseNameCharacterFlags, true),
                'baseNameHasWhitespace' => in_array('whitespace', $baseNameCharacterFlags, true),
                'baseNameHasPercentEncodedOctet' => in_array('percent-encoded-octet', $baseNameCharacterFlags, true),
                'baseNameHasNonAscii' => in_array('non-ascii', $baseNameCharacterFlags, true),
            ];
            if ($entry['isRelationshipPart']) {
                $relationshipSourcePart = $this->relationshipSourcePartForInventory($partName);
                $entry['relationshipSourcePart'] = $relationshipSourcePart;
                $entry['relationshipSourceExists'] = $this->relationshipSourceExists($parts, $relationshipSourcePart);
            }
            $inventory[$partName] = $entry;
        }

        return $inventory;
    }

    /**
     * @return list<string>
     */
    private function packagePartNameCharacterFlags(string $partName): array
    {
        $flags = [];
        if (preg_match('/[A-Z]/', $partName) === 1) {
            $flags[] = 'uppercase';
        }
        if (preg_match('/[ \t\r\n\f\v]/', $partName) === 1) {
            $flags[] = 'whitespace';
        }
        if (preg_match('/%[0-9A-Fa-f]{2}/', $partName) === 1) {
            $flags[] = 'percent-encoded-octet';
        }
        if (preg_match('/[^\x00-\x7F]/', $partName) === 1) {
            $flags[] = 'non-ascii';
        }

        return $flags;
    }

    private function packagePartDirectory(string $partName): string
    {
        $position = strrpos($partName, '/');

        return $position === false ? '/' : substr($partName, 0, $position);
    }

    private function packagePartDirectoryBaseName(string $directory): string
    {
        if ($directory === '' || $directory === '/') {
            return '/';
        }

        $position = strrpos($directory, '/');

        return $position === false ? $directory : substr($directory, $position + 1);
    }

    private function packagePartDirectoryBaseNameStem(string $directory): string
    {
        return $this->packagePartBaseNameStemFromBaseName($this->packagePartDirectoryBaseName($directory));
    }

    private function packagePartBaseName(string $partName): string
    {
        $position = strrpos($partName, '/');

        return $position === false ? $partName : substr($partName, $position + 1);
    }

    private function packagePartBaseNameStem(string $partName): string
    {
        return $this->packagePartBaseNameStemFromBaseName($this->packagePartBaseName($partName));
    }

    private function packagePartBaseNameStemFromBaseName(string $baseName): string
    {
        if ($baseName === '' || $baseName === '/') {
            return $baseName;
        }

        $rawExtension = $this->packagePartRawExtension($baseName);
        if ($rawExtension === null) {
            return $baseName;
        }

        $stemLength = strlen($baseName) - strlen($rawExtension) - 1;
        if ($stemLength <= 0) {
            return $baseName;
        }

        return substr($baseName, 0, $stemLength);
    }

    /**
     * @return list<string>
     */
    private function packagePartPathSegments(string $partName): array
    {
        return array_values(array_filter(
            explode('/', trim($partName, '/')),
            static fn (string $segment): bool => $segment !== '',
        ));
    }

    /**
     * @param list<string> $pathSegments
     * @return list<array{pathSegmentIndex:int, segment:string, position:string, isFirst:bool, isLast:bool, isOnly:bool}>
     */
    private function packagePartPathSegmentPositionReviews(array $pathSegments): array
    {
        $reviews = [];
        $pathSegmentCount = count($pathSegments);
        foreach ($pathSegments as $pathSegmentIndex => $segment) {
            if (!is_string($segment) || $segment === '') {
                continue;
            }

            $isFirst = $pathSegmentIndex === 0;
            $isLast = $pathSegmentIndex === $pathSegmentCount - 1;
            $isOnly = $pathSegmentCount === 1;
            $position = match (true) {
                $isOnly => 'only',
                $isFirst => 'first',
                $isLast => 'last',
                default => 'middle',
            };

            $reviews[] = [
                'pathSegmentIndex' => $pathSegmentIndex,
                'segment' => $segment,
                'position' => $position,
                'isFirst' => $isFirst,
                'isLast' => $isLast,
                'isOnly' => $isOnly,
            ];
        }

        return $reviews;
    }

    private function packagePartDirectoryDepth(string $directory): int
    {
        if ($directory === '' || $directory === '/') {
            return 0;
        }

        return count(array_values(array_filter(
            explode('/', trim($directory, '/')),
            static fn (string $segment): bool => $segment !== '',
        )));
    }

    private function packagePartTopLevelSegment(string $partName): string
    {
        return $this->packagePartPathSegments($partName)[0] ?? '';
    }

    private function packagePartExtension(string $partName): ?string
    {
        $extension = strtolower(pathinfo($partName, PATHINFO_EXTENSION));

        return $extension === '' ? null : $extension;
    }

    private function packagePartRawExtension(string $partName): ?string
    {
        $extension = pathinfo($partName, PATHINFO_EXTENSION);

        return $extension === '' ? null : $extension;
    }

    private function packagePartCaseFoldKey(string $name): string
    {
        if (class_exists(\Normalizer::class)) {
            $normalized = \Normalizer::normalize($name, \Normalizer::FORM_C);
            if (is_string($normalized)) {
                $name = $normalized;
            }
        }

        return function_exists('mb_strtolower') ? mb_strtolower($name, 'UTF-8') : strtolower($name);
    }

    /**
     * @param array<string, array<string, true>> $rolesByPart
     */
    private function addPartRole(array &$rolesByPart, ?string $partName, string $role): void
    {
        if ($partName === null || $partName === '') {
            return;
        }

        $rolesByPart[$partName][$role] = true;
    }

    /**
     * @param array<string, array<string, true>> $rolesByPart
     */
    private function addRelationshipTargetInventoryRole(array &$rolesByPart, string $partName, string $relationshipType): void
    {
        $role = $this->relationshipTargetInventoryRole($relationshipType);
        if ($role === null) {
            return;
        }

        $this->addPartRole($rolesByPart, $partName, $role);
    }

    private function relationshipTargetInventoryRole(string $relationshipType): ?string
    {
        return match ($relationshipType) {
            self::OFFICE_DOCUMENT_REL => 'office-document',
            self::CORE_PROPERTIES_REL => 'core-properties',
            self::EXTENDED_PROPERTIES_REL => 'extended-properties',
            self::CUSTOM_PROPERTIES_REL => 'custom-properties',
            self::STYLES_REL => 'styles',
            self::STYLES_WITH_EFFECTS_REL => 'styles-with-effects',
            self::NUMBERING_REL => 'numbering',
            self::FOOTNOTES_REL => 'footnotes',
            self::ENDNOTES_REL => 'endnotes',
            self::COMMENTS_REL => 'comments',
            self::COMMENTS_EXTENDED_REL => 'comments-extended',
            self::COMMENTS_IDS_REL => 'comments-ids',
            self::PEOPLE_REL => 'people',
            self::SETTINGS_REL => 'settings',
            self::ATTACHED_TEMPLATE_REL => 'attached-template',
            self::PRINTER_SETTINGS_REL => 'printer-settings',
            self::MAIL_MERGE_SOURCE_REL => 'mail-merge-source',
            self::MAIL_MERGE_HEADER_SOURCE_REL => 'mail-merge-header-source',
            self::MAIL_MERGE_RECIPIENT_DATA_REL, self::MAIL_MERGE_RECIPIENT_DATA_COMPAT_REL => 'mail-merge-recipient-data',
            self::WEB_SETTINGS_REL => 'web-settings',
            self::FONT_TABLE_REL => 'font-table',
            self::FONT_REL => 'embedded-font',
            self::THEME_REL => 'theme',
            self::HEADER_REL => 'header-part',
            self::FOOTER_REL => 'footer-part',
            self::SUBDOCUMENT_REL => 'subdocument',
            self::CUSTOM_XML_REL => 'custom-xml-part',
            self::CUSTOM_XML_PROPS_REL => 'custom-xml-properties',
            self::ALT_CHUNK_REL => 'alternative-format-import',
            self::GLOSSARY_DOCUMENT_REL => 'glossary-document',
            self::OLE_OBJECT_REL => 'embedded-object',
            self::EMBEDDED_PACKAGE_REL => 'embedded-package',
            self::BIBLIOGRAPHY_REL => 'bibliography-part',
            self::CHART_REL => 'chart-part',
            self::DIAGRAM_DATA_REL => 'diagram-data',
            self::DIAGRAM_LAYOUT_REL => 'diagram-layout',
            self::DIAGRAM_QUICK_STYLE_REL => 'diagram-quick-style',
            self::DIAGRAM_COLORS_REL => 'diagram-colors',
            self::ACTIVEX_CONTROL_REL => 'activex-control',
            self::ACTIVEX_BINARY_REL => 'activex-binary',
            self::VBA_PROJECT_REL => 'vba-project',
            self::VBA_PROJECT_SIGNATURE_REL => 'vba-project-signature',
            self::VBA_DATA_REL => 'vba-data',
            self::CUSTOM_UI_REL => 'custom-ui',
            self::CUSTOM_UI2_REL => 'custom-ui2',
            self::CUSTOM_UI_QAT_REL => 'custom-ui-quick-access-toolbar',
            self::THUMBNAIL_REL => 'package-thumbnail',
            self::DIGITAL_SIGNATURE_ORIGIN_REL => 'digital-signature-origin',
            self::DIGITAL_SIGNATURE_SIGNATURE_REL => 'digital-signature-signature',
            default => null,
        };
    }

    /**
     * @param array<string, string> $parts
     */
    private function relationshipSourceExists(array $parts, string $sourcePart): bool
    {
        return $sourcePart === '/' || ($sourcePart !== '' && isset($parts[$sourcePart]));
    }

    /**
     * @param array{id:string, type:string, target:string, targetMode:string, resolvedTarget:string} $relationship
     */
    private function isExternalRelationshipTarget(array $relationship): bool
    {
        return $relationship['targetMode'] === 'External'
            || preg_match('/^[A-Za-z][A-Za-z0-9+.-]*:/', $relationship['resolvedTarget']) === 1;
    }

    /**
     * @return array{query:?string, fragment:?string, suffix:string}
     */
    private function targetReferenceSuffix(string $resolvedTarget): array
    {
        $fragment = null;
        $query = null;
        $suffix = '';
        $beforeFragment = $resolvedTarget;
        $fragmentPosition = strpos($resolvedTarget, '#');
        if ($fragmentPosition !== false) {
            $fragment = substr($resolvedTarget, $fragmentPosition + 1);
            $beforeFragment = substr($resolvedTarget, 0, $fragmentPosition);
            $suffix = '#' . $fragment;
        }

        $queryPosition = strpos($beforeFragment, '?');
        if ($queryPosition !== false) {
            $query = substr($beforeFragment, $queryPosition + 1);
            $suffix = '?' . $query . ($fragment === null ? '' : '#' . $fragment);
        }

        return [
            'query' => $query,
            'fragment' => $fragment,
            'suffix' => $suffix,
        ];
    }

    /**
     * @return list<array{ordinal:int, raw:string, rawName:string, rawValue:?string, name:string, value:?string, valueKey:string, hasValue:bool}>
     */
    private function targetQueryParameters(?string $query): array
    {
        if ($query === null || $query === '') {
            return [];
        }

        $parameters = [];
        foreach (explode('&', $query) as $segment) {
            if ($segment === '') {
                continue;
            }

            $separatorPosition = strpos($segment, '=');
            $hasValue = $separatorPosition !== false;
            $rawName = $hasValue ? substr($segment, 0, $separatorPosition) : $segment;
            if ($rawName === '') {
                continue;
            }

            $rawValue = $hasValue ? substr($segment, $separatorPosition + 1) : null;
            $name = rawurldecode($rawName);
            if ($name === '') {
                continue;
            }

            $value = $rawValue === null ? null : rawurldecode($rawValue);
            $parameters[] = [
                'ordinal' => count($parameters) + 1,
                'raw' => $segment,
                'rawName' => $rawName,
                'rawValue' => $rawValue,
                'name' => $name,
                'value' => $value,
                'valueKey' => $value === null ? '(missing)' : ($value === '' ? '(empty)' : $value),
                'hasValue' => $hasValue,
            ];
        }

        return $parameters;
    }

    /**
     * @param array{defaults:array<string, string>, overrides:array<string, string>} $contentTypes
     * @return array<string, mixed>
     */
    private function contentTypeResolutionForPart(string $partName, array $contentTypes): array
    {
        $partName = $this->stripQueryAndFragment($partName);
        if (isset($contentTypes['overrides'][$partName])) {
            return [
                'contentType' => $contentTypes['overrides'][$partName],
                'contentTypeSource' => 'override',
                'defaultExtension' => null,
                'overridePartName' => $partName,
            ] + $this->contentTypeReport($contentTypes['overrides'][$partName]);
        }

        $extension = strtolower(pathinfo($partName, PATHINFO_EXTENSION));
        if ($extension !== '' && isset($contentTypes['defaults'][$extension])) {
            return [
                'contentType' => $contentTypes['defaults'][$extension],
                'contentTypeSource' => 'default',
                'defaultExtension' => $extension,
                'overridePartName' => null,
            ] + $this->contentTypeReport($contentTypes['defaults'][$extension]);
        }

        return $this->missingContentTypeResolution($extension === '' ? null : $extension);
    }

    /**
     * @param array{defaults:array<string, string>, overrides:array<string, string>} $contentTypes
     * @return array<string, mixed>
     */
    private function documentPackageIdentity(string $documentPart, array $contentTypes): array
    {
        $contentType = $this->contentTypeResolutionForPart($documentPart, $contentTypes);
        $contentTypeBase = is_string($contentType['contentTypeBase'] ?? null) ? $contentType['contentTypeBase'] : '';
        $formatKind = match ($contentTypeBase) {
            self::CT_WORD_DOCUMENT => 'document',
            self::CT_WORD_TEMPLATE => 'template',
            self::CT_WORD_MACRO_ENABLED_DOCUMENT => 'macro-enabled-document',
            self::CT_WORD_MACRO_ENABLED_TEMPLATE => 'macro-enabled-template',
            '' => 'missing',
            default => 'unknown',
        };
        $issueCodes = match ($formatKind) {
            'missing' => ['missing-main-document-content-type'],
            'unknown' => ['unexpected-main-document-content-type'],
            default => [],
        };
        $identity = [
            'identityVersion' => 1,
            'reviewPolicy' => 'docx-main-document-package-identity',
            'packageType' => 'docx-openxml-main-document',
            'partName' => $documentPart,
            'contentType' => $contentType['contentType'],
            'contentTypeBase' => $contentTypeBase,
            'contentTypeSource' => $contentType['contentTypeSource'],
            'contentTypeHasParameters' => $contentType['contentTypeHasParameters'],
            'contentTypeParameterCount' => $contentType['contentTypeParameterCount'],
            'contentTypeParameters' => $contentType['contentTypeParameters'],
            'contentTypeParameterMap' => $contentType['contentTypeParameterMap'],
            'defaultExtension' => $contentType['defaultExtension'],
            'overridePartName' => $contentType['overridePartName'],
            'formatKind' => $formatKind,
            'template' => $formatKind === 'template' || $formatKind === 'macro-enabled-template',
            'macroEnabled' => $formatKind === 'macro-enabled-document' || $formatKind === 'macro-enabled-template',
            'validContentType' => $issueCodes === [],
            'issueCount' => count($issueCodes),
            'issueCodes' => $issueCodes,
        ];
        $identityJson = json_encode(
            self::canonicalIdentityValue($identity),
            JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE | JSON_THROW_ON_ERROR
        );
        $identity['identitySha256'] = hash('sha256', $identityJson);
        $identity['identityPayloadByteLength'] = strlen($identityJson);
        $identity['byteExposurePolicy'] = 'docx-main-document-package-identity-metadata-only';
        $identity['canExposeBytes'] = false;

        return $identity;
    }

    /**
     * @return array<string, mixed>
     */
    private function missingContentTypeResolution(?string $defaultExtension): array
    {
        return [
            'contentType' => '',
            'contentTypeBase' => '',
            'contentTypeHasParameters' => false,
            'contentTypeParameterCount' => 0,
            'contentTypeParameters' => [],
            'contentTypeParameterMap' => [],
            'contentTypeSource' => 'missing',
            'defaultExtension' => $defaultExtension,
            'overridePartName' => null,
        ];
    }

    /**
     * @return array{contentType:string, contentTypeBase:string, contentTypeHasParameters:bool, contentTypeParameterCount:int, contentTypeParameters:list<array{name:string, value:string, raw:string}>, contentTypeParameterMap:array<string, string>}
     */
    private function contentTypeReport(string $contentType): array
    {
        $segments = $this->contentTypeSegments($contentType);
        $base = strtolower(trim((string) array_shift($segments)));
        $parameters = [];
        $parameterMap = [];

        foreach ($segments as $segment) {
            $raw = trim($segment);
            if ($raw === '') {
                continue;
            }

            $equals = strpos($raw, '=');
            $name = $equals === false ? strtolower(trim($raw)) : strtolower(trim(substr($raw, 0, $equals)));
            if ($name === '') {
                continue;
            }

            $value = $equals === false ? '' : trim(substr($raw, $equals + 1));
            if (strlen($value) >= 2 && $value[0] === '"' && substr($value, -1) === '"') {
                $value = substr($value, 1, -1);
                $value = preg_replace('/\\\\([\x20-\x7E])/', '$1', $value) ?? $value;
            }

            $parameters[] = [
                'name' => $name,
                'value' => $value,
                'raw' => $raw,
            ];
            $parameterMap[$name] = $value;
        }

        return [
            'contentType' => $contentType,
            'contentTypeBase' => $base,
            'contentTypeHasParameters' => $parameters !== [],
            'contentTypeParameterCount' => count($parameters),
            'contentTypeParameters' => $parameters,
            'contentTypeParameterMap' => $parameterMap,
        ];
    }

    /**
     * @return list<string>
     */
    private function contentTypeSegments(string $contentType): array
    {
        $segments = [];
        $current = '';
        $inQuote = false;
        $escaped = false;
        $length = strlen($contentType);

        for ($index = 0; $index < $length; $index++) {
            $char = $contentType[$index];
            if ($escaped) {
                $current .= $char;
                $escaped = false;
                continue;
            }

            if ($inQuote && $char === '\\') {
                $current .= $char;
                $escaped = true;
                continue;
            }

            if ($char === '"') {
                $inQuote = !$inQuote;
                $current .= $char;
                continue;
            }

            if ($char === ';' && !$inQuote) {
                $segments[] = $current;
                $current = '';
                continue;
            }

            $current .= $char;
        }

        $segments[] = $current;

        return $segments;
    }

    private function contentTypeStructuredSyntaxSuffix(string $contentTypeBase): ?string
    {
        $slashPosition = strpos($contentTypeBase, '/');
        if ($slashPosition === false) {
            return null;
        }

        $subtype = substr($contentTypeBase, $slashPosition + 1);
        $plusPosition = strrpos($subtype, '+');
        if ($plusPosition === false || $plusPosition === strlen($subtype) - 1) {
            return null;
        }

        $suffix = strtolower(substr($subtype, $plusPosition + 1));

        return $suffix === '' ? null : $suffix;
    }

    private function contentTypeMediaTypeKey(string $contentTypeBase): string
    {
        if ($contentTypeBase === '') {
            return '(missing)';
        }

        $slashPosition = strpos($contentTypeBase, '/');
        if ($slashPosition === false || $slashPosition === 0) {
            return '(invalid)';
        }

        return strtolower(substr($contentTypeBase, 0, $slashPosition));
    }

    private function contentTypeSubtypeKey(string $contentTypeBase): string
    {
        if ($contentTypeBase === '') {
            return '(missing)';
        }

        $slashPosition = strpos($contentTypeBase, '/');
        if ($slashPosition === false || $slashPosition === 0 || $slashPosition === strlen($contentTypeBase) - 1) {
            return '(invalid)';
        }

        $subtype = substr($contentTypeBase, $slashPosition + 1);
        if ($subtype === '' || strpos($subtype, '/') !== false) {
            return '(invalid)';
        }

        return strtolower($subtype);
    }

    /**
     * @param array<string, array<string, mixed>> $defaults
     * @param array<string, array<string, mixed>> $overrides
     * @return list<array<string, mixed>>
     */
    private function parameterizedContentTypeDeclarations(array $defaults, array $overrides): array
    {
        $items = [];
        foreach ($defaults as $extension => $default) {
            if (($default['contentTypeHasParameters'] ?? false) !== true) {
                continue;
            }

            $items[] = [
                'kind' => 'default',
                'extension' => $extension,
                'contentType' => $default['contentType'],
                'contentTypeBase' => $default['contentTypeBase'],
                'contentTypeParameterCount' => $default['contentTypeParameterCount'],
                'contentTypeParameters' => $default['contentTypeParameters'],
                'contentTypeParameterMap' => $default['contentTypeParameterMap'],
            ];
        }

        foreach ($overrides as $partName => $override) {
            if (($override['contentTypeHasParameters'] ?? false) !== true) {
                continue;
            }

            $items[] = [
                'kind' => 'override',
                'partName' => $partName,
                'exists' => $override['exists'],
                'contentType' => $override['contentType'],
                'contentTypeBase' => $override['contentTypeBase'],
                'contentTypeParameterCount' => $override['contentTypeParameterCount'],
                'contentTypeParameters' => $override['contentTypeParameters'],
                'contentTypeParameterMap' => $override['contentTypeParameterMap'],
            ];
        }

        return $items;
    }

    private function isRelationshipPartName(string $partName): bool
    {
        return $partName === '_rels/.rels'
            || preg_match('~^_rels/[^/]+\.rels$~', $partName) === 1
            || (str_ends_with($partName, '.rels') && str_contains($partName, '/_rels/'));
    }

    private function relationshipSourcePartForInventory(string $relationshipPart): string
    {
        if ($relationshipPart === '_rels/.rels') {
            return '/';
        }

        return $this->sourcePartForRelationshipsPart($relationshipPart);
    }

    /**
     * @param array<string, array<string, mixed>> $pictureBullets
     * @return array<string, array{abstractNumId:string, levels:array<int, array<string, mixed>>}>
     */
    private function readNumbering(string $xml, string $partName, array $pictureBullets = []): array
    {
        if ($xml === '') {
            return [];
        }

        $dom = $this->loadXmlForProvenance($xml, $partName);
        if (!$dom instanceof \DOMDocument) {
            return [];
        }
        $xpath = $this->xpath($dom);
        $abstracts = [];
        foreach ($this->elements($xpath, '/w:numbering/w:abstractNum') as $abstract) {
            $abstractId = $abstract->getAttributeNS(self::NS_W, 'abstractNumId');
            if ($abstractId === '') {
                continue;
            }

            $levels = [];
            foreach ($this->elements($xpath, 'w:lvl', $abstract) as $level) {
                $ilvl = (int) $level->getAttributeNS(self::NS_W, 'ilvl');
                $levelDefinition = [
                    'format' => $this->childAttr($level, 'numFmt', 'val') ?: 'decimal',
                    'text' => $this->childAttr($level, 'lvlText', 'val') ?: '%' . ($ilvl + 1) . '.',
                    'start' => max(1, (int) ($this->childAttr($level, 'start', 'val') ?: '1')),
                ];
                $pictureBulletId = $this->childAttr($level, 'lvlPicBulletId', 'val');
                if ($pictureBulletId !== '') {
                    $levelDefinition['pictureBulletId'] = $pictureBulletId;
                    if (isset($pictureBullets[$pictureBulletId])) {
                        $levelDefinition['pictureBullet'] = $pictureBullets[$pictureBulletId];
                    }
                }
                $levels[$ilvl] = $levelDefinition;
            }
            $abstracts[$abstractId] = $levels;
        }

        $numbering = [];
        foreach ($this->elements($xpath, '/w:numbering/w:num') as $num) {
            $numId = $num->getAttributeNS(self::NS_W, 'numId');
            $abstractNumId = $this->childAttr($num, 'abstractNumId', 'val');
            if ($numId === '' || $abstractNumId === '' || !isset($abstracts[$abstractNumId])) {
                continue;
            }

            $levels = $abstracts[$abstractNumId];
            foreach ($this->elements($xpath, 'w:lvlOverride', $num) as $override) {
                $ilvl = (int) $override->getAttributeNS(self::NS_W, 'ilvl');
                $startOverride = $this->childAttr($override, 'startOverride', 'val');
                if ($startOverride !== '') {
                    $levels[$ilvl]['start'] = max(1, (int) $startOverride);
                }
            }

            $numbering[$numId] = [
                'abstractNumId' => $abstractNumId,
                'levels' => $levels,
            ];
        }

        return $numbering;
    }

    /**
     * @param array<string, string> $parts
     * @param array<string, array{id:string, type:string, target:string, targetMode:string, resolvedTarget:string}> $relationships
     * @param array{defaults:array<string, string>, overrides:array<string, string>} $contentTypes
     * @return array<string, mixed>
     */
    private function readNumberingPictureBullets(
        string $xml,
        string $partName,
        array $parts,
        string $relationshipsPart,
        array $relationships,
        array $contentTypes
    ): array {
        $empty = [
            'partName' => $partName,
            'relationshipsPart' => $relationshipsPart,
            'relationshipsPartExists' => isset($parts[$relationshipsPart]),
            'count' => 0,
            'relationshipCount' => count($relationships),
            'imageRelationshipCount' => 0,
            'referencedRelationshipCount' => 0,
            'unreferencedRelationshipCount' => 0,
            'existingCount' => 0,
            'missingCount' => 0,
            'externalCount' => 0,
            'unexpectedRelationshipTypeCount' => 0,
            'missingContentTypeCount' => 0,
            'unexpectedContentTypeCount' => 0,
            'issueCount' => 0,
            'ids' => [],
            'relationshipIds' => [],
            'referencedRelationshipIds' => [],
            'unreferencedRelationshipIds' => [],
            'partNames' => [],
            'externalTargets' => [],
            'contentTypes' => [],
            'issueCodes' => [],
            'byId' => [],
            'byRelationshipId' => [],
            'items' => [],
            'byteExposurePolicy' => 'numbering-picture-bullet-bytes-blocked',
            'reviewPolicy' => 'numbering-picture-bullet-metadata-only',
        ];

        if ($xml === '') {
            return $empty;
        }

        $dom = $this->loadXmlForProvenance($xml, $partName);
        if (!$dom instanceof \DOMDocument) {
            return $empty;
        }
        $xpath = $this->xpath($dom);
        $items = [];
        $byId = [];
        $byRelationshipId = [];
        $ids = [];
        $relationshipIds = [];
        $partNames = [];
        $externalTargets = [];
        $contentTypesSeen = [];
        $issueCodes = [];

        foreach ($this->elements($xpath, '/w:numbering/w:numPicBullet') as $pictureBullet) {
            $id = $pictureBullet->getAttributeNS(self::NS_W, 'numPicBulletId');
            if ($id === '') {
                continue;
            }

            $item = $this->numberingPictureBulletItem(
                $pictureBullet,
                $id,
                count($items),
                $parts,
                $partName,
                $relationshipsPart,
                $relationships,
                $contentTypes,
            );
            $items[] = $item;
            $byId[$id] = $item;
            $ids[] = $id;

            $relationshipId = is_string($item['relationshipId'] ?? null) ? $item['relationshipId'] : '';
            if ($relationshipId !== '') {
                $this->appendUniqueString($relationshipIds, $relationshipId);
                $byRelationshipId[$relationshipId] = $item;
            }
            if (($item['relationshipType'] ?? null) === self::IMAGE_REL) {
                $this->appendUniqueString($partNames, is_string($item['targetPart'] ?? null) ? $item['targetPart'] : null);
            }
            if (($item['external'] ?? false) === true) {
                $this->appendUniqueString($externalTargets, is_string($item['target'] ?? null) ? $item['target'] : null);
            }
            $this->appendUniqueString($contentTypesSeen, is_string($item['contentType'] ?? null) ? $item['contentType'] : null);
            foreach (($item['issues'] ?? []) as $issue) {
                if (is_string($issue) && $issue !== '') {
                    $issueCodes[$issue] = true;
                }
            }
        }

        $imageRelationshipIds = [];
        foreach ($relationships as $relationship) {
            if ($relationship['type'] === self::IMAGE_REL) {
                $this->appendUniqueString($imageRelationshipIds, $relationship['id']);
            }
        }
        $unreferencedRelationshipIds = array_values(array_diff($imageRelationshipIds, $relationshipIds));
        ksort($issueCodes, SORT_STRING);

        return [
            'partName' => $partName,
            'relationshipsPart' => $relationshipsPart,
            'relationshipsPartExists' => isset($parts[$relationshipsPart]),
            'count' => count($items),
            'relationshipCount' => count($relationships),
            'imageRelationshipCount' => count($imageRelationshipIds),
            'referencedRelationshipCount' => count($relationshipIds),
            'unreferencedRelationshipCount' => count($unreferencedRelationshipIds),
            'existingCount' => count(array_filter($items, static fn (array $item): bool => ($item['relationshipType'] ?? null) === self::IMAGE_REL && $item['external'] === false && $item['exists'] === true)),
            'missingCount' => count(array_filter($items, static fn (array $item): bool => in_array('missing-numbering-picture-bullet-image', $item['issues'], true))),
            'externalCount' => count(array_filter($items, static fn (array $item): bool => ($item['relationshipType'] ?? null) === self::IMAGE_REL && $item['external'] === true)),
            'unexpectedRelationshipTypeCount' => count(array_filter($items, static fn (array $item): bool => in_array('unexpected-relationship-type', $item['issues'], true))),
            'missingContentTypeCount' => count(array_filter($items, static fn (array $item): bool => in_array('missing-numbering-picture-bullet-content-type', $item['issues'], true))),
            'unexpectedContentTypeCount' => count(array_filter($items, static fn (array $item): bool => in_array('unexpected-numbering-picture-bullet-content-type', $item['issues'], true))),
            'issueCount' => count(array_filter($items, static fn (array $item): bool => $item['issues'] !== [])),
            'ids' => $ids,
            'relationshipIds' => $relationshipIds,
            'referencedRelationshipIds' => $relationshipIds,
            'unreferencedRelationshipIds' => $unreferencedRelationshipIds,
            'partNames' => $partNames,
            'externalTargets' => $externalTargets,
            'contentTypes' => $contentTypesSeen,
            'issueCodes' => array_keys($issueCodes),
            'byId' => $byId,
            'byRelationshipId' => $byRelationshipId,
            'items' => $items,
            'byteExposurePolicy' => 'numbering-picture-bullet-bytes-blocked',
            'reviewPolicy' => 'numbering-picture-bullet-metadata-only',
        ];
    }

    /**
     * @param array<string, string> $parts
     * @param array<string, array{id:string, type:string, target:string, targetMode:string, resolvedTarget:string}> $relationships
     * @param array{defaults:array<string, string>, overrides:array<string, string>} $contentTypes
     * @return array<string, mixed>
     */
    private function numberingPictureBulletItem(
        \DOMElement $pictureBullet,
        string $id,
        int $index,
        array $parts,
        string $partName,
        string $relationshipsPart,
        array $relationships,
        array $contentTypes
    ): array {
        $item = [
            'index' => $index,
            'id' => $id,
            'sourcePart' => $partName,
            'relationshipsPart' => $relationshipsPart,
            'relationshipsPartExists' => isset($parts[$relationshipsPart]),
            'relationshipId' => null,
            'relationshipType' => null,
            'target' => null,
            'targetMode' => null,
            'resolvedTarget' => null,
            'targetPart' => null,
            'targetQuery' => null,
            'targetFragment' => null,
            'targetReferenceSuffix' => '',
            'external' => false,
            'externalTargetKind' => null,
            'externalTargetScheme' => null,
            'externalTargetAllowed' => null,
            'exists' => false,
            'byteLength' => null,
            'bytes' => null,
            'crc32' => null,
            'sha256' => null,
            'contentType' => '',
            'contentTypeBase' => '',
            'contentTypeHasParameters' => false,
            'contentTypeParameterCount' => 0,
            'contentTypeParameters' => [],
            'contentTypeParameterMap' => [],
            'contentTypeSource' => 'missing',
            'defaultExtension' => null,
            'overridePartName' => null,
            'shapeAlt' => null,
            'title' => null,
            'byteExposurePolicy' => 'numbering-picture-bullet-bytes-blocked',
            'reviewPolicy' => 'numbering-picture-bullet-metadata-only',
            'valid' => false,
            'issues' => [],
            'relationship' => null,
        ];

        $imageData = $this->firstDescendantElementByNamespace($pictureBullet, self::NS_V, 'imagedata');
        if (!$imageData instanceof \DOMElement) {
            $item['issues'][] = 'missing-image-data';
            return $item;
        }

        $title = trim($imageData->getAttributeNS(self::NS_O, 'title'));
        if ($title !== '') {
            $item['title'] = $title;
        }
        $shape = $imageData->parentNode;
        if ($shape instanceof \DOMElement && $shape->namespaceURI === self::NS_V && $shape->localName === 'shape') {
            $alt = trim($shape->getAttribute('alt'));
            if ($alt !== '') {
                $item['shapeAlt'] = $alt;
            }
        }

        $relationshipId = $imageData->getAttributeNS(self::NS_R, 'id');
        if ($relationshipId === '') {
            $item['issues'][] = 'missing-relationship-id';
            return $item;
        }

        $item['relationshipId'] = $relationshipId;
        if (!isset($parts[$relationshipsPart])) {
            $item['issues'][] = 'missing-numbering-relationships';
            return $item;
        }

        $relationship = $relationships[$relationshipId] ?? null;
        if (!is_array($relationship)) {
            $item['issues'][] = 'missing-relationship';
            return $item;
        }

        $summary = $this->relationshipInventorySummary($parts, $relationship, $partName, $relationshipsPart, $contentTypes);
        $targetPart = is_string($summary['targetPart'] ?? null) ? $summary['targetPart'] : null;
        $exists = (bool) ($summary['exists'] ?? false);
        $external = (bool) ($summary['external'] ?? false);
        $contentTypeBase = is_string($summary['contentTypeBase'] ?? null) ? $summary['contentTypeBase'] : '';

        $item['relationshipType'] = $summary['type'];
        $item['target'] = $summary['target'];
        $item['targetMode'] = $summary['targetMode'];
        $item['resolvedTarget'] = $summary['resolvedTarget'];
        $item['targetPart'] = $targetPart;
        $item['targetQuery'] = $summary['targetQuery'];
        $item['targetFragment'] = $summary['targetFragment'];
        $item['targetReferenceSuffix'] = $summary['targetReferenceSuffix'];
        $item['external'] = $external;
        $item['externalTargetKind'] = $summary['externalTargetKind'];
        $item['externalTargetScheme'] = $summary['externalTargetScheme'];
        $item['externalTargetAllowed'] = $summary['externalTargetAllowed'];
        $item['exists'] = $exists;
        $item['byteLength'] = $targetPart !== null && $exists ? strlen($parts[$targetPart]) : null;
        $item['bytes'] = $item['byteLength'];
        $item['crc32'] = $targetPart !== null && $exists ? sprintf('%08x', crc32($parts[$targetPart])) : null;
        $item['sha256'] = $targetPart !== null && $exists ? hash('sha256', $parts[$targetPart]) : null;
        $item['contentType'] = $summary['contentType'];
        $item['contentTypeBase'] = $contentTypeBase;
        $item['contentTypeHasParameters'] = $summary['contentTypeHasParameters'];
        $item['contentTypeParameterCount'] = $summary['contentTypeParameterCount'];
        $item['contentTypeParameters'] = $summary['contentTypeParameters'];
        $item['contentTypeParameterMap'] = $summary['contentTypeParameterMap'];
        $item['contentTypeSource'] = $summary['contentTypeSource'];
        $item['defaultExtension'] = $summary['defaultExtension'];
        $item['overridePartName'] = $summary['overridePartName'];
        $item['relationship'] = $summary;

        if ($relationship['type'] !== self::IMAGE_REL) {
            $item['issues'][] = 'unexpected-relationship-type';
        }

        if ($external) {
            $item['issues'][] = 'external-numbering-picture-bullet';
            foreach (($summary['externalTargetIssues'] ?? []) as $issue) {
                if (is_string($issue) && $issue !== '') {
                    $item['issues'][] = $issue;
                }
            }
        } else {
            if (!$exists) {
                $item['issues'][] = 'missing-numbering-picture-bullet-image';
            }
            if (($summary['contentTypeSource'] ?? '') === 'missing') {
                $item['issues'][] = 'missing-numbering-picture-bullet-content-type';
            } elseif (!str_starts_with($contentTypeBase, 'image/')) {
                $item['issues'][] = 'unexpected-numbering-picture-bullet-content-type';
            }
        }

        $item['issues'] = array_values(array_unique($item['issues']));
        sort($item['issues'], SORT_STRING);
        $item['valid'] = $item['issues'] === [];

        return $item;
    }

    /**
     * @return array<string, mixed>
     */
    private function readCoreProperties(string $xml, string $partName): array
    {
        if ($xml === '') {
            return [];
        }

        $dom = $this->loadXml($xml, $partName);
        $xpath = $this->xpath($dom);
        $meta = [];
        foreach ([
            'title' => 'string(/cp:coreProperties/dc:title)',
            'creator' => 'string(/cp:coreProperties/dc:creator)',
            'description' => 'string(/cp:coreProperties/dc:description)',
            'subject' => 'string(/cp:coreProperties/dc:subject)',
            'keywords' => 'string(/cp:coreProperties/cp:keywords)',
            'created' => 'string(/cp:coreProperties/dcterms:created)',
            'modified' => 'string(/cp:coreProperties/dcterms:modified)',
        ] as $name => $query) {
            $value = trim((string) $xpath->evaluate($query));
            if ($value !== '') {
                $meta[$name] = $value;
            }
        }

        if (isset($meta['creator'])) {
            $meta['author'] = [$meta['creator']];
            $meta['authors'] = [$meta['creator']];
        }
        if (isset($meta['title'])) {
            $meta['titleInlines'] = [new AstNode('text', ['text' => $meta['title']])];
        }

        return $meta;
    }

    /**
     * @return array<string, mixed>
     */
    private function readExtendedProperties(string $xml, string $partName): array
    {
        if ($xml === '') {
            return [];
        }

        $dom = $this->loadXml($xml, $partName);
        $xpath = $this->xpath($dom);
        $properties = [];

        foreach ([
            'Template' => 'template',
            'Manager' => 'manager',
            'Company' => 'company',
            'Application' => 'application',
            'AppVersion' => 'appVersion',
            'HyperlinkBase' => 'hyperlinkBase',
        ] as $source => $target) {
            $value = $this->extendedPropertyText($xpath, $source);
            if ($value !== '') {
                $properties[$target] = $value;
            }
        }

        foreach ([
            'Pages' => 'pages',
            'Words' => 'words',
            'Characters' => 'characters',
            'CharactersWithSpaces' => 'charactersWithSpaces',
            'Lines' => 'lines',
            'Paragraphs' => 'paragraphs',
            'DocSecurity' => 'docSecurity',
        ] as $source => $target) {
            $value = $this->extendedPropertyText($xpath, $source);
            if ($value !== '' && is_numeric($value)) {
                $properties[$target] = (int) $value;
            }
        }

        foreach ([
            'ScaleCrop' => 'scaleCrop',
            'LinksUpToDate' => 'linksUpToDate',
            'SharedDoc' => 'sharedDoc',
            'HyperlinksChanged' => 'hyperlinksChanged',
        ] as $source => $target) {
            $element = $this->firstElement($xpath, '/ep:Properties/ep:' . $source, $dom);
            if ($element instanceof \DOMElement) {
                $properties[$target] = $this->openXmlBooleanText($element->textContent);
            }
        }

        $headingPairs = $this->extendedHeadingPairs($xpath, $dom);
        if ($headingPairs !== []) {
            $properties['headingPairs'] = $headingPairs;
        }

        $titlesOfParts = $this->extendedTitlesOfParts($xpath, $dom);
        if ($titlesOfParts !== []) {
            $properties['titlesOfParts'] = $titlesOfParts;
        }

        return $properties;
    }

    private function extendedPropertyText(\DOMXPath $xpath, string $localName): string
    {
        return trim((string) $xpath->evaluate('string(/ep:Properties/ep:' . $localName . ')'));
    }

    /**
     * @return list<array{name:string, count:int}>
     */
    private function extendedHeadingPairs(\DOMXPath $xpath, \DOMDocument $dom): array
    {
        $vector = $this->firstElement($xpath, '/ep:Properties/ep:HeadingPairs/vt:vector', $dom);
        if (!$vector instanceof \DOMElement) {
            return [];
        }

        $values = $this->docPropsVectorValues($vector);
        $pairs = [];
        for ($index = 0; $index + 1 < count($values); $index += 2) {
            $name = trim((string) $values[$index]);
            $count = $values[$index + 1];
            if ($name !== '' && is_int($count)) {
                $pairs[] = ['name' => $name, 'count' => $count];
            }
        }

        return $pairs;
    }

    /**
     * @return list<string>
     */
    private function extendedTitlesOfParts(\DOMXPath $xpath, \DOMDocument $dom): array
    {
        $vector = $this->firstElement($xpath, '/ep:Properties/ep:TitlesOfParts/vt:vector', $dom);
        if (!$vector instanceof \DOMElement) {
            return [];
        }

        $titles = [];
        foreach ($this->docPropsVectorValues($vector) as $value) {
            $title = trim((string) $value);
            if ($title !== '') {
                $titles[] = $title;
            }
        }

        return $titles;
    }

    /**
     * @return array{count:int, duplicateNameCount:int, duplicateNames:list<string>, items:list<array<string, mixed>>, byName:array<string, mixed>}
     */
    private function readCustomProperties(string $xml, string $partName): array
    {
        if ($xml === '') {
            return [];
        }

        $dom = $this->loadXml($xml, $partName);
        $xpath = $this->xpath($dom);
        $items = [];
        $byName = [];
        $seenNames = [];
        $duplicateNames = [];

        foreach ($this->elements($xpath, '/cust:Properties/cust:property') as $property) {
            $name = trim($property->getAttribute('name'));
            if ($name === '') {
                continue;
            }

            $valueElement = $this->firstDocPropsValueElement($property);
            if (!$valueElement instanceof \DOMElement) {
                continue;
            }

            $value = $this->docPropsTypedValue($valueElement);
            $duplicate = isset($seenNames[$name]);
            $seenNames[$name] = true;
            if ($duplicate) {
                $duplicateNames[$name] = true;
            } else {
                $byName[$name] = $value;
            }

            $item = [
                'name' => $name,
                'valueType' => $valueElement->localName,
                'value' => $value,
                'duplicate' => $duplicate,
            ] + $this->docPropsAggregateValueMetadata($valueElement);
            $pid = $property->getAttribute('pid');
            if ($pid !== '' && is_numeric($pid)) {
                $item['pid'] = (int) $pid;
            }
            $fmtid = trim($property->getAttribute('fmtid'));
            if ($fmtid !== '') {
                $item['fmtid'] = $fmtid;
            }

            $items[] = $item;
        }

        if ($items === []) {
            return [];
        }

        return [
            'count' => count($items),
            'duplicateNameCount' => count($duplicateNames),
            'duplicateNames' => array_keys($duplicateNames),
            'items' => $items,
            'byName' => $byName,
        ];
    }

    /**
     * @return list<mixed>
     */
    private function docPropsVectorValues(\DOMElement $vector): array
    {
        $values = [];
        foreach ($vector->childNodes as $child) {
            if (!$child instanceof \DOMElement || $child->namespaceURI !== self::NS_VT) {
                continue;
            }

            if ($child->localName === 'variant') {
                $valueElement = $this->firstDocPropsValueElement($child);
                if ($valueElement instanceof \DOMElement) {
                    $values[] = $this->docPropsTypedValue($valueElement);
                }
                continue;
            }

            $values[] = $this->docPropsTypedValue($child);
        }

        return $values;
    }

    private function firstDocPropsValueElement(\DOMElement $parent): ?\DOMElement
    {
        foreach ($parent->childNodes as $child) {
            if ($child instanceof \DOMElement && $child->namespaceURI === self::NS_VT) {
                return $child;
            }
        }

        return null;
    }

    private function docPropsTypedValue(\DOMElement $valueElement): mixed
    {
        $value = trim($valueElement->textContent);

        return match ($valueElement->localName) {
            'array', 'vector' => $this->docPropsVectorValues($valueElement),
            'bool' => $this->openXmlBooleanText($value),
            'i1', 'i2', 'i4', 'i8', 'int', 'ui1', 'ui2', 'ui4', 'ui8', 'uint' => is_numeric($value) ? (int) $value : 0,
            'r4', 'r8', 'decimal' => is_numeric($value) ? (float) $value : 0.0,
            default => $value,
        };
    }

    /**
     * @return array<string, mixed>
     */
    private function docPropsAggregateValueMetadata(\DOMElement $valueElement): array
    {
        if (!in_array($valueElement->localName, ['array', 'vector'], true)) {
            return [];
        }

        $metadata = [
            'valueCount' => count($this->docPropsVectorValues($valueElement)),
        ];

        $size = trim($valueElement->getAttribute('size'));
        if ($size !== '' && is_numeric($size)) {
            $metadata['declaredValueCount'] = (int) $size;
        }

        $baseType = trim($valueElement->getAttribute('baseType'));
        if ($baseType !== '') {
            $metadata['valueBaseType'] = $baseType;
        }

        if ($valueElement->localName === 'array') {
            $lowerBound = trim($valueElement->getAttribute('lBound'));
            if ($lowerBound === '') {
                $lowerBound = trim($valueElement->getAttribute('lbound'));
            }
            if ($lowerBound !== '' && is_numeric($lowerBound)) {
                $metadata['lowerBound'] = (int) $lowerBound;
            }
        }

        $itemTypes = $this->docPropsVectorValueTypes($valueElement);
        if ($itemTypes !== []) {
            $metadata['valueItemTypes'] = $itemTypes;
        }

        return $metadata;
    }

    /**
     * @return list<string>
     */
    private function docPropsVectorValueTypes(\DOMElement $vector): array
    {
        $types = [];
        foreach ($vector->childNodes as $child) {
            if (!$child instanceof \DOMElement || $child->namespaceURI !== self::NS_VT) {
                continue;
            }

            if ($child->localName === 'variant') {
                $valueElement = $this->firstDocPropsValueElement($child);
                if ($valueElement instanceof \DOMElement) {
                    $types[] = $valueElement->localName;
                }
                continue;
            }

            $types[] = $child->localName;
        }

        return $types;
    }

    private function openXmlBooleanText(string $value): bool
    {
        return in_array(strtolower(trim($value)), ['1', 'true', 'on', 'yes'], true);
    }

    /**
     * @return array<string, mixed>
     */
    private function readSettings(
        string $xml,
        string $partName,
        array $parts,
        string $relationshipsPart,
        array $relationships,
        array $contentTypes
    ): array
    {
        if ($xml === '') {
            return [];
        }

        $dom = $this->loadXml($xml, $partName);
        $xpath = $this->xpath($dom);
        $settings = [];

        foreach ([
            'trackRevisions' => 'trackRevisions',
            'doNotTrackMoves' => 'doNotTrackMoves',
            'doNotTrackFormatting' => 'doNotTrackFormatting',
            'evenAndOddHeaders' => 'evenAndOddHeaders',
            'updateFields' => 'updateFields',
        ] as $key => $localName) {
            $element = $this->firstElement($xpath, '/w:settings/w:' . $localName, $dom);
            if ($element instanceof \DOMElement) {
                $settings[$key] = $this->wordBoolean($element);
            }
        }

        $defaultTabStop = $this->firstElement($xpath, '/w:settings/w:defaultTabStop', $dom);
        if ($defaultTabStop instanceof \DOMElement && is_numeric($defaultTabStop->getAttributeNS(self::NS_W, 'val'))) {
            $settings['defaultTabStopTwips'] = (int) $defaultTabStop->getAttributeNS(self::NS_W, 'val');
        }

        $view = $this->firstElement($xpath, '/w:settings/w:view', $dom);
        if ($view instanceof \DOMElement) {
            $value = $view->getAttributeNS(self::NS_W, 'val');
            if ($value !== '') {
                $settings['view'] = $value;
            }
        }

        $zoom = $this->firstElement($xpath, '/w:settings/w:zoom', $dom);
        if ($zoom instanceof \DOMElement) {
            $settings['zoom'] = array_filter([
                'percent' => is_numeric($zoom->getAttributeNS(self::NS_W, 'percent'))
                    ? (int) $zoom->getAttributeNS(self::NS_W, 'percent')
                    : null,
                'value' => $zoom->getAttributeNS(self::NS_W, 'val') ?: null,
            ], static fn (mixed $value): bool => $value !== null && $value !== '');
        }

        foreach ([
            'decimalSymbol' => 'decimalSymbol',
            'listSeparator' => 'listSeparator',
        ] as $key => $localName) {
            $element = $this->firstElement($xpath, '/w:settings/w:' . $localName, $dom);
            if ($element instanceof \DOMElement) {
                $value = $element->getAttributeNS(self::NS_W, 'val');
                if ($value !== '') {
                    $settings[$key] = $value;
                }
            }
        }

        $themeFontLanguage = $this->firstElement($xpath, '/w:settings/w:themeFontLang', $dom);
        if ($themeFontLanguage instanceof \DOMElement) {
            $themeFontLanguageSettings = $this->wordAttributeMap($themeFontLanguage, ['val', 'eastAsia', 'bidi']);
            if ($themeFontLanguageSettings !== []) {
                $settings['themeFontLanguage'] = $themeFontLanguageSettings;
            }
        }

        $colorSchemeMapping = $this->firstElement($xpath, '/w:settings/w:clrSchemeMapping', $dom);
        if ($colorSchemeMapping instanceof \DOMElement) {
            $colorSchemeMappingSettings = $this->wordAttributeMap($colorSchemeMapping, [
                'bg1',
                't1',
                'bg2',
                't2',
                'accent1',
                'accent2',
                'accent3',
                'accent4',
                'accent5',
                'accent6',
                'hyperlink',
                'followedHyperlink',
            ]);
            if ($colorSchemeMappingSettings !== []) {
                $settings['colorSchemeMapping'] = $colorSchemeMappingSettings;
            }
        }

        $protection = $this->firstElement($xpath, '/w:settings/w:documentProtection', $dom);
        if ($protection instanceof \DOMElement) {
            $settings['documentProtection'] = $this->wordAttributeMap($protection, [
                'edit',
                'enforcement',
                'algorithmName',
                'hashValue',
                'saltValue',
                'spinCount',
                'cryptProviderType',
                'cryptAlgorithmClass',
                'cryptAlgorithmType',
                'cryptAlgorithmSid',
                'cryptSpinCount',
            ]);
            if (isset($settings['documentProtection']['enforcement'])) {
                $settings['documentProtection']['enforcement'] = $this->wordBoolean($protection, 'enforcement');
            }
            foreach (['spinCount', 'cryptAlgorithmSid', 'cryptSpinCount'] as $numericKey) {
                if (isset($settings['documentProtection'][$numericKey]) && is_numeric($settings['documentProtection'][$numericKey])) {
                    $settings['documentProtection'][$numericKey] = (int) $settings['documentProtection'][$numericKey];
                }
            }
        }

        $writeProtection = $this->firstElement($xpath, '/w:settings/w:writeProtection', $dom);
        if ($writeProtection instanceof \DOMElement) {
            $settings['writeProtection'] = $this->wordAttributeMap($writeProtection, [
                'recommended',
                'algorithmName',
                'hashValue',
                'saltValue',
                'spinCount',
                'cryptProviderType',
                'cryptAlgorithmClass',
                'cryptAlgorithmType',
                'cryptAlgorithmSid',
                'cryptSpinCount',
            ]);
            if (isset($settings['writeProtection']['recommended'])) {
                $settings['writeProtection']['recommended'] = $this->wordBoolean($writeProtection, 'recommended');
            }
            foreach (['spinCount', 'cryptAlgorithmSid', 'cryptSpinCount'] as $numericKey) {
                if (isset($settings['writeProtection'][$numericKey]) && is_numeric($settings['writeProtection'][$numericKey])) {
                    $settings['writeProtection'][$numericKey] = (int) $settings['writeProtection'][$numericKey];
                }
            }
        }

        $protectionDetails = $this->settingsProtectionDetails($settings);
        if ($protectionDetails !== []) {
            $settings['protectionDetails'] = $protectionDetails;
        }

        $revisionView = $this->firstElement($xpath, '/w:settings/w:revisionView', $dom);
        if ($revisionView instanceof \DOMElement) {
            $revisionViewSettings = [];
            foreach ([
                'markup',
                'comments',
                'insDel',
                'formatting',
                'inkAnnotations',
            ] as $attribute) {
                if ($revisionView->getAttributeNS(self::NS_W, $attribute) !== '') {
                    $revisionViewSettings[$attribute] = $this->wordBoolean($revisionView, $attribute);
                }
            }
            if ($revisionViewSettings !== []) {
                $settings['revisionView'] = $revisionViewSettings;
            }
        }

        $proofState = $this->firstElement($xpath, '/w:settings/w:proofState', $dom);
        if ($proofState instanceof \DOMElement) {
            $proofing = $this->wordAttributeMap($proofState, ['spelling', 'grammar']);
            if ($proofing !== []) {
                $settings['proofing'] = $proofing;
            }
        }

        $viewStateDetails = $this->settingsViewStateDetails($settings);
        if ($viewStateDetails !== []) {
            $settings['viewStateDetails'] = $viewStateDetails;
        }

        $hyphenation = [];
        foreach ([
            'autoHyphenation' => 'autoHyphenation',
            'doNotHyphenateCaps' => 'doNotHyphenateCaps',
        ] as $localName => $key) {
            $element = $this->firstElement($xpath, '/w:settings/w:' . $localName, $dom);
            if ($element instanceof \DOMElement) {
                $hyphenation[$key] = $this->wordBoolean($element);
            }
        }
        foreach ([
            'consecutiveHyphenLimit' => 'consecutiveHyphenLimit',
            'hyphenationZone' => 'hyphenationZoneTwips',
        ] as $localName => $key) {
            $element = $this->firstElement($xpath, '/w:settings/w:' . $localName, $dom);
            if ($element instanceof \DOMElement && is_numeric($element->getAttributeNS(self::NS_W, 'val'))) {
                $hyphenation[$key] = (int) $element->getAttributeNS(self::NS_W, 'val');
            }
        }
        if ($hyphenation !== []) {
            $settings['hyphenation'] = $hyphenation;
        }

        $savePolicy = [];
        foreach ([
            'saveFormsData' => 'saveFormsData',
            'savePreviewPicture' => 'savePreviewPicture',
            'doNotEmbedSmartTags' => 'doNotEmbedSmartTags',
            'embedTrueTypeFonts' => 'embedTrueTypeFonts',
            'embedSystemFonts' => 'embedSystemFonts',
            'saveSubsetFonts' => 'saveSubsetFonts',
        ] as $localName => $key) {
            $element = $this->firstElement($xpath, '/w:settings/w:' . $localName, $dom);
            if ($element instanceof \DOMElement) {
                $savePolicy[$key] = $this->wordBoolean($element);
            }
        }
        if ($savePolicy !== []) {
            $settings['savePolicy'] = $savePolicy;
        }

        $mathProperties = $this->readSettingsMathProperties($xpath, $dom);
        if ($mathProperties !== []) {
            $settings['mathProperties'] = $mathProperties;
        }

        $compatibility = $this->readSettingsCompatibility($xpath, $dom);
        if ($compatibility['flatItems'] !== []) {
            $settings['compatibility'] = $compatibility['flatItems'];
            unset($compatibility['flatItems']);
            $settings['compatibilityDetails'] = $compatibility;
        }

        $documentVariables = $this->readSettingsDocumentVariables($xpath, $dom);
        if ($documentVariables['byName'] !== []) {
            $settings['documentVariables'] = $documentVariables['byName'];
        }
        if ($documentVariables['items'] !== []) {
            $settings['documentVariableDetails'] = $documentVariables;
        }

        $rsidDetails = $this->readSettingsRsids($xpath, $dom);
        if ($rsidDetails['rootPresent'] || $rsidDetails['items'] !== []) {
            $settings['rsidDetails'] = $rsidDetails;
        }
        if ($rsidDetails['nonEmptyValues'] !== []) {
            $settings['rsids'] = $rsidDetails['nonEmptyValues'];
        }

        $mailMerge = $this->readMailMergeSettings(
            $dom,
            $parts,
            $partName,
            $relationshipsPart,
            $relationships,
            $contentTypes,
        );
        if ($mailMerge !== []) {
            $settings['mailMerge'] = $mailMerge;
        }

        return $settings;
    }

    /**
     * @param array<string, mixed> $settings
     * @return array<string, mixed>
     */
    private function settingsProtectionDetails(array $settings): array
    {
        $items = [];
        $byKind = [];
        foreach (['documentProtection', 'writeProtection'] as $kind) {
            $protection = $settings[$kind] ?? null;
            if (!is_array($protection) || $protection === []) {
                continue;
            }

            $item = [
                'kind' => $kind,
                'attributeCount' => count($protection),
                'edit' => is_string($protection['edit'] ?? null) ? $protection['edit'] : null,
                'enforcement' => is_bool($protection['enforcement'] ?? null) ? $protection['enforcement'] : null,
                'recommended' => is_bool($protection['recommended'] ?? null) ? $protection['recommended'] : null,
                'algorithmName' => is_string($protection['algorithmName'] ?? null) ? $protection['algorithmName'] : null,
                'cryptProviderType' => is_string($protection['cryptProviderType'] ?? null) ? $protection['cryptProviderType'] : null,
                'cryptAlgorithmClass' => is_string($protection['cryptAlgorithmClass'] ?? null) ? $protection['cryptAlgorithmClass'] : null,
                'cryptAlgorithmType' => is_string($protection['cryptAlgorithmType'] ?? null) ? $protection['cryptAlgorithmType'] : null,
                'cryptAlgorithmSid' => is_int($protection['cryptAlgorithmSid'] ?? null) ? $protection['cryptAlgorithmSid'] : null,
                'spinCount' => is_int($protection['spinCount'] ?? null) ? $protection['spinCount'] : null,
                'cryptSpinCount' => is_int($protection['cryptSpinCount'] ?? null) ? $protection['cryptSpinCount'] : null,
                'reviewPolicy' => 'settings-protection-metadata-only',
                'rawValueExposurePolicy' => 'settings-protection-hash-and-salt-values-hashed',
                'cryptographicValidation' => false,
            ];

            foreach (['hashValue', 'saltValue'] as $valueKey) {
                $value = $protection[$valueKey] ?? null;
                $present = is_string($value) && $value !== '';
                $item[$valueKey . 'Present'] = $present;
                $item[$valueKey . 'Length'] = $present ? strlen($value) : 0;
                $item[$valueKey . 'Sha256'] = $present ? hash('sha256', $value) : null;
            }

            $item['cryptographicMetadataPresent'] = $item['algorithmName'] !== null
                || $item['hashValuePresent'] === true
                || $item['saltValuePresent'] === true
                || $item['spinCount'] !== null
                || $item['cryptProviderType'] !== null
                || $item['cryptAlgorithmClass'] !== null
                || $item['cryptAlgorithmType'] !== null
                || $item['cryptAlgorithmSid'] !== null
                || $item['cryptSpinCount'] !== null;

            $items[] = $item;
            $byKind[$kind] = $item;
        }

        if ($items === []) {
            return [];
        }

        $kinds = array_column($items, 'kind');
        sort($kinds, SORT_STRING);

        return [
            'count' => count($items),
            'kinds' => $kinds,
            'documentProtectionPresent' => isset($byKind['documentProtection']),
            'writeProtectionPresent' => isset($byKind['writeProtection']),
            'hashValueCount' => count(array_filter($items, static fn (array $item): bool => $item['hashValuePresent'] === true)),
            'saltValueCount' => count(array_filter($items, static fn (array $item): bool => $item['saltValuePresent'] === true)),
            'algorithmNameCount' => count(array_filter($items, static fn (array $item): bool => $item['algorithmName'] !== null)),
            'spinCountAttributeCount' => count(array_filter(
                $items,
                static fn (array $item): bool => $item['spinCount'] !== null || $item['cryptSpinCount'] !== null,
            )),
            'cryptographicMetadataCount' => count(array_filter($items, static fn (array $item): bool => $item['cryptographicMetadataPresent'] === true)),
            'reviewPolicy' => 'settings-protection-metadata-only',
            'rawValueExposurePolicy' => 'settings-protection-hash-and-salt-values-hashed',
            'cryptographicValidation' => false,
            'items' => $items,
            'byKind' => $byKind,
        ];
    }

    /**
     * @param array<string, mixed> $settings
     * @return array<string, mixed>
     */
    private function settingsViewStateDetails(array $settings): array
    {
        $details = [];
        $issueCodes = [];

        if (isset($settings['view']) && is_string($settings['view']) && $settings['view'] !== '') {
            $details['view'] = $settings['view'];
        }

        $zoom = $settings['zoom'] ?? null;
        if (is_array($zoom) && $zoom !== []) {
            $zoomDetails = [];
            if (isset($zoom['percent']) && is_int($zoom['percent'])) {
                $zoomDetails['percent'] = $zoom['percent'];
            }
            if (isset($zoom['value']) && is_string($zoom['value']) && $zoom['value'] !== '') {
                $zoomDetails['value'] = $zoom['value'];
            }
            if ($zoomDetails !== []) {
                $details['zoom'] = $zoomDetails;
            }
        }

        $revisionView = $settings['revisionView'] ?? null;
        if (is_array($revisionView) && $revisionView !== []) {
            $enabledAttributes = [];
            $disabledAttributes = [];
            foreach ($revisionView as $attribute => $enabled) {
                if ($enabled === true) {
                    $enabledAttributes[] = (string) $attribute;
                } elseif ($enabled === false) {
                    $disabledAttributes[] = (string) $attribute;
                }
            }

            $details['revisionView'] = $revisionView;
            $details['revisionViewAttributeCount'] = count($revisionView);
            $details['revisionViewEnabledCount'] = count($enabledAttributes);
            $details['revisionViewDisabledCount'] = count($disabledAttributes);
            $details['revisionViewEnabledAttributes'] = $enabledAttributes;
            $details['revisionViewDisabledAttributes'] = $disabledAttributes;
        }

        $proofing = $settings['proofing'] ?? null;
        if (is_array($proofing) && $proofing !== []) {
            $cleanAttributes = [];
            $dirtyAttributes = [];
            $otherAttributes = [];
            foreach ($proofing as $attribute => $state) {
                if ($state === 'clean') {
                    $cleanAttributes[] = (string) $attribute;
                } elseif ($state === 'dirty') {
                    $dirtyAttributes[] = (string) $attribute;
                } else {
                    $otherAttributes[] = (string) $attribute;
                }
            }

            if ($otherAttributes !== []) {
                $issueCodes[] = 'unknown-proof-state';
            }

            $details['proofing'] = $proofing;
            $details['proofingAttributeCount'] = count($proofing);
            $details['proofingCleanCount'] = count($cleanAttributes);
            $details['proofingDirtyCount'] = count($dirtyAttributes);
            $details['proofingOtherCount'] = count($otherAttributes);
            $details['proofingCleanAttributes'] = $cleanAttributes;
            $details['proofingDirtyAttributes'] = $dirtyAttributes;
            $details['proofingOtherAttributes'] = $otherAttributes;
        }

        if ($details === []) {
            return [];
        }

        $details['issueCount'] = count($issueCodes);
        $details['issueCodes'] = $issueCodes;

        return $details;
    }

    /**
     * @return array<string, mixed>
     */
    private function readSettingsCompatibility(\DOMXPath $xpath, \DOMDocument $dom): array
    {
        $items = [];
        $flatItems = [];
        $nameCounts = [];
        $uris = [];

        foreach ($this->elements($xpath, '/w:settings/w:compat/w:compatSetting', $dom) as $setting) {
            $name = $setting->getAttributeNS(self::NS_W, 'name');
            $uri = $setting->getAttributeNS(self::NS_W, 'uri');
            $value = $setting->getAttributeNS(self::NS_W, 'val');
            $item = [
                'index' => count($items),
                'name' => $name,
                'uri' => $uri,
                'value' => $value,
                'issues' => [],
            ];

            if ($name === '') {
                $item['issues'][] = 'missing-name';
            } else {
                $nameCounts[$name] = ($nameCounts[$name] ?? 0) + 1;
            }
            $this->appendUniqueString($uris, $uri);

            $items[] = $item;
            $flatItems[] = array_filter([
                'name' => $name ?: null,
                'uri' => $uri ?: null,
                'value' => $value ?: null,
            ], static fn (mixed $value): bool => $value !== null && $value !== '');
        }

        $duplicateNames = [];
        foreach ($nameCounts as $name => $count) {
            if ($count > 1) {
                $duplicateNames[] = $name;
            }
        }
        sort($duplicateNames, SORT_STRING);
        sort($uris, SORT_STRING);

        $duplicateLookup = array_fill_keys($duplicateNames, true);
        $issueCodes = [];
        $issueCount = 0;
        foreach ($items as &$item) {
            $name = $item['name'];
            $item['duplicateName'] = is_string($name) && isset($duplicateLookup[$name]);
            if ($item['duplicateName']) {
                $item['issues'][] = 'duplicate-name';
            }
            if ($item['issues'] !== []) {
                ++$issueCount;
                foreach ($item['issues'] as $issue) {
                    $issueCodes[$issue] = true;
                }
            }
        }
        unset($item);
        ksort($issueCodes, SORT_STRING);

        $byName = [];
        foreach ($items as $item) {
            if ($item['name'] !== '') {
                $byName[$item['name']] = $item;
            }
        }

        return [
            'count' => count($items),
            'namedCount' => count(array_filter($items, static fn (array $item): bool => $item['name'] !== '')),
            'emptyNameCount' => count(array_filter($items, static fn (array $item): bool => $item['name'] === '')),
            'uniqueNameCount' => count($nameCounts),
            'duplicateNameCount' => count($duplicateNames),
            'duplicateNames' => $duplicateNames,
            'uriCount' => count($uris),
            'uris' => $uris,
            'issueCount' => $issueCount,
            'issueCodes' => array_keys($issueCodes),
            'items' => $items,
            'byName' => $byName,
            'flatItems' => $flatItems,
        ];
    }

    /**
     * @return array<string, mixed>
     */
    private function readSettingsDocumentVariables(\DOMXPath $xpath, \DOMDocument $dom): array
    {
        $items = [];
        $byName = [];
        $nameCounts = [];

        foreach ($this->elements($xpath, '/w:settings/w:docVars/w:docVar', $dom) as $variable) {
            $name = $variable->getAttributeNS(self::NS_W, 'name');
            $value = $variable->getAttributeNS(self::NS_W, 'val');
            $item = [
                'index' => count($items),
                'name' => $name,
                'value' => $value,
                'valueLength' => strlen($value),
                'valueSha256' => hash('sha256', $value),
                'issues' => [],
            ];

            if ($name === '') {
                $item['issues'][] = 'missing-name';
            } else {
                $byName[$name] = $value;
                $nameCounts[$name] = ($nameCounts[$name] ?? 0) + 1;
            }

            $items[] = $item;
        }

        $duplicateNames = [];
        foreach ($nameCounts as $name => $count) {
            if ($count > 1) {
                $duplicateNames[] = $name;
            }
        }
        sort($duplicateNames, SORT_STRING);

        $duplicateLookup = array_fill_keys($duplicateNames, true);
        $issueCodes = [];
        $issueCount = 0;
        foreach ($items as &$item) {
            $name = $item['name'];
            $item['duplicateName'] = is_string($name) && isset($duplicateLookup[$name]);
            if ($item['duplicateName']) {
                $item['issues'][] = 'duplicate-name';
            }
            if ($item['issues'] !== []) {
                ++$issueCount;
                foreach ($item['issues'] as $issue) {
                    $issueCodes[$issue] = true;
                }
            }
        }
        unset($item);
        ksort($issueCodes, SORT_STRING);

        return [
            'count' => count($items),
            'namedCount' => count(array_filter($items, static fn (array $item): bool => $item['name'] !== '')),
            'emptyNameCount' => count(array_filter($items, static fn (array $item): bool => $item['name'] === '')),
            'duplicateNameCount' => count($duplicateNames),
            'duplicateNames' => $duplicateNames,
            'issueCount' => $issueCount,
            'issueCodes' => array_keys($issueCodes),
            'items' => $items,
            'byName' => $byName,
        ];
    }

    /**
     * @return array<string, mixed>
     */
    private function readSettingsRsids(\DOMXPath $xpath, \DOMDocument $dom): array
    {
        $root = $this->firstElement($xpath, '/w:settings/w:rsids/w:rsidRoot', $dom);
        $rootPresent = $root instanceof \DOMElement;
        $rootValue = $rootPresent ? $root->getAttributeNS(self::NS_W, 'val') : '';
        $rootIssues = [];
        if ($rootPresent && $rootValue === '') {
            $rootIssues[] = 'missing-root-value';
        } elseif ($rootPresent && !$this->isOpenXmlRsidValue($rootValue)) {
            $rootIssues[] = 'invalid-root-hex';
        }

        $items = [];
        $values = [];
        $nonEmptyValues = [];
        $valueCounts = [];
        $invalidValueCount = 0;
        foreach ($this->elements($xpath, '/w:settings/w:rsids/w:rsid', $dom) as $rsid) {
            $value = $rsid->getAttributeNS(self::NS_W, 'val');
            $validHex = $value !== '' && $this->isOpenXmlRsidValue($value);
            $issues = [];
            if ($value === '') {
                $issues[] = 'missing-value';
            } else {
                $nonEmptyValues[] = $value;
                $valueCounts[$value] = ($valueCounts[$value] ?? 0) + 1;
                if (!$validHex) {
                    $issues[] = 'invalid-hex';
                    ++$invalidValueCount;
                }
            }
            $values[] = $value;
            $items[] = [
                'index' => count($items),
                'value' => $value,
                'valueLength' => strlen($value),
                'validHex' => $validHex,
                'issues' => $issues,
            ];
        }

        $duplicateValues = [];
        foreach ($valueCounts as $value => $count) {
            if ($count > 1) {
                $duplicateValues[] = $value;
            }
        }
        sort($duplicateValues, SORT_STRING);

        $duplicateLookup = array_fill_keys($duplicateValues, true);
        $issueCodes = [];
        $issueCount = 0;
        foreach ($items as &$item) {
            $value = $item['value'];
            $item['duplicateValue'] = is_string($value) && $value !== '' && isset($duplicateLookup[$value]);
            if ($item['duplicateValue']) {
                $item['issues'][] = 'duplicate-value';
            }
            if ($item['issues'] !== []) {
                ++$issueCount;
                foreach ($item['issues'] as $issue) {
                    $issueCodes[$issue] = true;
                }
            }
        }
        unset($item);
        ksort($issueCodes, SORT_STRING);

        $rootIssueCodes = array_fill_keys($rootIssues, true);
        ksort($rootIssueCodes, SORT_STRING);

        return [
            'rootPresent' => $rootPresent,
            'rootValue' => $rootValue,
            'rootValueLength' => strlen($rootValue),
            'rootValidHex' => $rootPresent && $this->isOpenXmlRsidValue($rootValue),
            'rootIssueCount' => count($rootIssues),
            'rootIssueCodes' => array_keys($rootIssueCodes),
            'count' => count($items),
            'nonEmptyCount' => count($nonEmptyValues),
            'emptyValueCount' => count($items) - count($nonEmptyValues),
            'uniqueValueCount' => count($valueCounts),
            'duplicateValueCount' => count($duplicateValues),
            'duplicateValues' => $duplicateValues,
            'invalidValueCount' => $invalidValueCount,
            'issueCount' => $issueCount,
            'issueCodes' => array_keys($issueCodes),
            'values' => $values,
            'nonEmptyValues' => $nonEmptyValues,
            'items' => $items,
        ];
    }

    private function isOpenXmlRsidValue(string $value): bool
    {
        return preg_match('/\A[0-9A-Fa-f]{8}\z/', $value) === 1;
    }

    /**
     * @return array<string, mixed>
     */
    private function readSettingsMathProperties(\DOMXPath $xpath, \DOMDocument $dom): array
    {
        $mathProperties = $this->firstElement($xpath, '/w:settings/m:mathPr', $dom);
        if (!$mathProperties instanceof \DOMElement) {
            return [];
        }

        $items = [];
        $byName = [];
        $nameCounts = [];
        $names = [];
        $numericValueCount = 0;
        foreach ($mathProperties->childNodes as $child) {
            if (!$child instanceof \DOMElement || $child->namespaceURI !== self::NS_M) {
                continue;
            }

            $name = $child->localName;
            $value = $child->getAttributeNS(self::NS_M, 'val');
            if ($value === '') {
                $value = $child->getAttribute('val');
            }
            $hasValue = $value !== '';
            $issues = [];
            $item = [
                'index' => count($items),
                'name' => $name,
                'value' => $value,
                'hasValue' => $hasValue,
                'valueLength' => strlen($value),
                'issues' => [],
            ];
            if ($hasValue) {
                $byName[$name] = $value;
                if (preg_match('/^-?\d+$/', $value) === 1) {
                    $item['numericValue'] = (int) $value;
                    ++$numericValueCount;
                }
            } else {
                $issues[] = 'missing-value';
            }

            $nameCounts[$name] = ($nameCounts[$name] ?? 0) + 1;
            $this->appendUniqueString($names, $name);
            $item['issues'] = $issues;
            $items[] = $item;
        }

        $duplicateNames = [];
        foreach ($nameCounts as $name => $count) {
            if ($count > 1) {
                $duplicateNames[] = $name;
            }
        }
        sort($duplicateNames, SORT_STRING);

        $duplicateLookup = array_fill_keys($duplicateNames, true);
        $issueCodes = [];
        $issueCount = 0;
        foreach ($items as &$item) {
            $name = $item['name'];
            $item['duplicateName'] = is_string($name) && isset($duplicateLookup[$name]);
            if ($item['duplicateName']) {
                $item['issues'][] = 'duplicate-name';
            }
            if ($item['issues'] !== []) {
                ++$issueCount;
                foreach ($item['issues'] as $issue) {
                    $issueCodes[$issue] = true;
                }
            }
        }
        unset($item);
        sort($names, SORT_STRING);
        ksort($issueCodes, SORT_STRING);

        return [
            'count' => count($items),
            'valuedCount' => count(array_filter($items, static fn (array $item): bool => $item['hasValue'] === true)),
            'emptyValueCount' => count(array_filter($items, static fn (array $item): bool => $item['hasValue'] === false)),
            'uniqueNameCount' => count($names),
            'names' => $names,
            'numericValueCount' => $numericValueCount,
            'duplicateNameCount' => count($duplicateNames),
            'duplicateNames' => $duplicateNames,
            'issueCount' => $issueCount,
            'issueCodes' => array_keys($issueCodes),
            'items' => $items,
            'byName' => $byName,
        ];
    }

    /**
     * @param array<string, string> $parts
     * @param array<string, array{id:string, type:string, target:string, targetMode:string, resolvedTarget:string}> $relationships
     * @param array{defaults:array<string, string>, overrides:array<string, string>} $contentTypes
     * @return array<string, mixed>
     */
    private function readMailMergeSettings(
        \DOMDocument $dom,
        array $parts,
        string $settingsPart,
        string $relationshipsPart,
        array $relationships,
        array $contentTypes
    ): array {
        $xpath = $this->xpath($dom);
        $mailMerge = $this->firstElement($xpath, '/w:settings/w:mailMerge', $dom);
        if (!$mailMerge instanceof \DOMElement) {
            return [];
        }

        $metadata = [];
        foreach ([
            'mainDocumentType' => 'mainDocumentType',
            'destination' => 'destination',
            'dataType' => 'dataType',
            'query' => 'query',
            'mailSubject' => 'mailSubject',
        ] as $source => $target) {
            $value = $this->settingsStringChildValue($mailMerge, $source);
            if ($value !== null) {
                $metadata[$target] = $value;
            }
        }

        $connectString = $this->settingsStringChildValue($mailMerge, 'connectString');
        if ($connectString !== null) {
            $metadata['connectStringPresent'] = true;
            $metadata['connectStringLength'] = strlen($connectString);
            $metadata['connectStringSha256'] = hash('sha256', $connectString);
        }

        foreach ([
            'viewMergedData' => 'viewMergedData',
            'linkToQuery' => 'linkToQuery',
            'doNotSuppressBlankLines' => 'doNotSuppressBlankLines',
        ] as $source => $target) {
            $value = $this->settingsOnOffChildValue($mailMerge, $source);
            if ($value !== null) {
                $metadata[$target] = $value;
            }
        }

        foreach ([
            'activeRecord' => 'activeRecord',
            'checkErrors' => 'checkErrors',
        ] as $source => $target) {
            $value = $this->settingsIntChildValue($mailMerge, $source);
            if ($value !== null) {
                $metadata[$target] = $value;
            }
        }

        $relationshipCount = 0;
        $issueCount = 0;
        $issueCodes = [];
        $relationshipChildren = [
            [
                'parent' => $mailMerge,
                'key' => 'dataSource',
                'expectedRelationshipTypes' => [self::MAIL_MERGE_SOURCE_REL],
                'reviewPolicy' => 'mail-merge-source',
            ],
            [
                'parent' => $mailMerge,
                'key' => 'headerSource',
                'expectedRelationshipTypes' => [self::MAIL_MERGE_HEADER_SOURCE_REL],
                'reviewPolicy' => 'mail-merge-header-source',
            ],
        ];
        $odso = $this->childElement($mailMerge, 'odso');
        if ($odso instanceof \DOMElement) {
            $odsoMetadata = $this->readMailMergeOdsoSettings($odso);
            if ($odsoMetadata !== []) {
                $metadata['odso'] = $odsoMetadata;
            }
            $relationshipChildren[] = [
                'parent' => $odso,
                'key' => 'recipientData',
                'expectedRelationshipTypes' => [self::MAIL_MERGE_RECIPIENT_DATA_REL, self::MAIL_MERGE_RECIPIENT_DATA_COMPAT_REL],
                'reviewPolicy' => 'mail-merge-recipient-data',
            ];
        }

        foreach ($relationshipChildren as $relationshipChild) {
            $summary = $this->mailMergeRelationshipChildSummary(
                $relationshipChild['parent'],
                $relationshipChild['key'],
                $parts,
                $settingsPart,
                $relationshipsPart,
                $relationships,
                $contentTypes,
                $relationshipChild['expectedRelationshipTypes'],
                $relationshipChild['reviewPolicy'],
            );
            if ($summary === null) {
                continue;
            }

            if ($relationshipChild['key'] === 'recipientData') {
                $summary = $this->mailMergeRecipientDataPartSummary($summary, $parts);
            }

            $metadata[$relationshipChild['key']] = $summary;
            ++$relationshipCount;
            if ($summary['issues'] !== []) {
                ++$issueCount;
                foreach ($summary['issues'] as $issue) {
                    if (is_string($issue) && $issue !== '') {
                        $issueCodes[$issue] = true;
                    }
                }
            }
        }
        ksort($issueCodes, SORT_STRING);

        $metadata['relationshipCount'] = $relationshipCount;
        $metadata['issueCount'] = $issueCount;
        $metadata['issueCodes'] = array_keys($issueCodes);

        return $metadata;
    }

    private function readMailMergeOdsoSettings(\DOMElement $odso): array
    {
        $metadata = [
            'sourcePresentCount' => 0,
            'sourceKinds' => [],
            'fieldMapDataCount' => 0,
            'fieldMapDataNamedCount' => 0,
            'fieldMapDataMappedNameCount' => 0,
            'fieldMapDataDynamicAddressCount' => 0,
            'fieldMapDataIssueCount' => 0,
            'fieldMapDataIssueCodes' => [],
            'fieldMapDataColumnIndexes' => [],
            'fieldMapDataItems' => [],
            'reviewPolicy' => 'mail-merge-odso-metadata-only',
        ];

        foreach ([
            'type' => 'type',
            'lid' => 'languageId',
        ] as $source => $target) {
            $value = $this->settingsStringChildValue($odso, $source);
            if ($value !== null) {
                $metadata[$target] = $value;
            }
        }

        foreach ([
            'udl' => 'udl',
            'table' => 'table',
            'src' => 'source',
        ] as $source => $target) {
            $value = $this->settingsStringChildValue($odso, $source);
            if ($value === null) {
                continue;
            }

            $metadata[$target . 'Present'] = true;
            $metadata[$target . 'Length'] = strlen($value);
            $metadata[$target . 'Sha256'] = hash('sha256', $value);
            ++$metadata['sourcePresentCount'];
            $metadata['sourceKinds'][] = $target;
        }

        $firstHeaderRow = $this->settingsOnOffChildValue($odso, 'fHdr');
        if ($firstHeaderRow !== null) {
            $metadata['firstHeaderRow'] = $firstHeaderRow;
        }

        $columnDelimiter = $this->settingsIntChildValue($odso, 'colDelim');
        if ($columnDelimiter !== null) {
            $metadata['columnDelimiter'] = $columnDelimiter;
        }

        $fieldMapItems = [];
        $columnIndexes = [];
        $issueCodes = [];
        foreach ($this->childElementsByLocalName($odso, 'fieldMapData') as $index => $fieldMapData) {
            $name = $this->settingsStringChildValue($fieldMapData, 'name');
            $mappedName = $this->settingsStringChildValue($fieldMapData, 'mappedName');
            $columnIndex = $this->settingsIntChildValue($fieldMapData, 'column');
            $dynamicAddress = $this->settingsOnOffChildValue($fieldMapData, 'dynamicAddress');
            $issues = [];

            if ($name === null) {
                $issues[] = 'missing-field-map-name';
            }
            if ($columnIndex === null) {
                $issues[] = 'missing-field-map-column';
            } else {
                $columnIndexes[$columnIndex] = true;
            }

            foreach ($issues as $issue) {
                $issueCodes[$issue] = true;
            }
            sort($issues, SORT_STRING);

            $fieldMapItems[] = [
                'index' => $index,
                'type' => $this->settingsStringChildValue($fieldMapData, 'type'),
                'columnIndex' => $columnIndex,
                'languageId' => $this->settingsStringChildValue($fieldMapData, 'lid'),
                'dynamicAddress' => $dynamicAddress,
                'namePresent' => $name !== null,
                'nameLength' => $name === null ? null : strlen($name),
                'nameSha256' => $name === null ? null : hash('sha256', $name),
                'mappedNamePresent' => $mappedName !== null,
                'mappedNameLength' => $mappedName === null ? null : strlen($mappedName),
                'mappedNameSha256' => $mappedName === null ? null : hash('sha256', $mappedName),
                'issues' => $issues,
            ];
        }

        $columnIndexValues = array_keys($columnIndexes);
        sort($columnIndexValues, SORT_NUMERIC);
        ksort($issueCodes, SORT_STRING);

        $metadata['fieldMapDataCount'] = count($fieldMapItems);
        $metadata['fieldMapDataNamedCount'] = count(array_filter($fieldMapItems, static fn (array $item): bool => $item['namePresent'] === true));
        $metadata['fieldMapDataMappedNameCount'] = count(array_filter($fieldMapItems, static fn (array $item): bool => $item['mappedNamePresent'] === true));
        $metadata['fieldMapDataDynamicAddressCount'] = count(array_filter($fieldMapItems, static fn (array $item): bool => $item['dynamicAddress'] === true));
        $metadata['fieldMapDataIssueCount'] = count($issueCodes);
        $metadata['fieldMapDataIssueCodes'] = array_keys($issueCodes);
        $metadata['fieldMapDataColumnIndexes'] = $columnIndexValues;
        $metadata['fieldMapDataItems'] = $fieldMapItems;

        return $metadata;
    }

    private function settingsStringChildValue(\DOMElement $parent, string $localName): ?string
    {
        $child = $this->childElement($parent, $localName);
        if (!$child instanceof \DOMElement) {
            return null;
        }

        $value = trim($child->getAttributeNS(self::NS_W, 'val'));

        return $value === '' ? null : $value;
    }

    private function settingsOnOffChildValue(\DOMElement $parent, string $localName): ?bool
    {
        $child = $this->childElement($parent, $localName);
        if (!$child instanceof \DOMElement) {
            return null;
        }

        return $this->wordBoolean($child);
    }

    private function settingsIntChildValue(\DOMElement $parent, string $localName): ?int
    {
        $child = $this->childElement($parent, $localName);
        if (!$child instanceof \DOMElement) {
            return null;
        }

        $value = trim($child->getAttributeNS(self::NS_W, 'val'));

        return is_numeric($value) ? (int) $value : null;
    }

    /**
     * @param array<string, string> $parts
     * @param array<string, array{id:string, type:string, target:string, targetMode:string, resolvedTarget:string}> $relationships
     * @param array{defaults:array<string, string>, overrides:array<string, string>} $contentTypes
     * @param list<string> $expectedRelationshipTypes
     * @return array<string, mixed>|null
     */
    private function mailMergeRelationshipChildSummary(
        \DOMElement $mailMerge,
        string $localName,
        array $parts,
        string $settingsPart,
        string $relationshipsPart,
        array $relationships,
        array $contentTypes,
        array $expectedRelationshipTypes,
        string $reviewPolicy
    ): ?array {
        $child = $this->childElement($mailMerge, $localName);
        if (!$child instanceof \DOMElement) {
            return null;
        }

        $relationshipId = $child->getAttributeNS(self::NS_R, 'id');
        $item = [
            'id' => $relationshipId,
            'sourcePart' => $settingsPart,
            'relationshipsPart' => $relationshipsPart,
            'relationshipType' => null,
            'target' => null,
            'targetMode' => null,
            'resolvedTarget' => null,
            'targetPart' => null,
            'targetQuery' => null,
            'targetFragment' => null,
            'targetReferenceSuffix' => '',
            'contentType' => '',
            'contentTypeBase' => '',
            'contentTypeHasParameters' => false,
            'contentTypeParameterCount' => 0,
            'contentTypeParameters' => [],
            'contentTypeParameterMap' => [],
            'contentTypeSource' => 'missing',
            'defaultExtension' => null,
            'overridePartName' => null,
            'external' => null,
            'exists' => null,
            'byteLength' => null,
            'crc32' => null,
            'sha256' => null,
            'externalTargetKind' => null,
            'externalTargetScheme' => null,
            'externalTargetAllowed' => null,
            'byteExposurePolicy' => $reviewPolicy . '-bytes-blocked',
            'reviewPolicy' => $reviewPolicy . '-metadata-only',
            'relationship' => null,
            'issues' => [],
        ];

        if ($relationshipId === '') {
            $item['issues'][] = 'missing-relationship-id';

            return $item;
        }

        if (!isset($parts[$relationshipsPart])) {
            $item['issues'][] = 'missing-relationships';

            return $item;
        }

        $relationship = $relationships[$relationshipId] ?? null;
        if (!is_array($relationship)) {
            $item['issues'][] = 'unknown-relationship';

            return $item;
        }

        $summary = $this->relationshipInventorySummary($parts, $relationship, $settingsPart, $relationshipsPart, $contentTypes);
        $targetPart = is_string($summary['targetPart'] ?? null) ? $summary['targetPart'] : null;
        $external = (bool) ($summary['external'] ?? false);

        $item['relationshipType'] = $summary['type'];
        $item['target'] = $summary['target'];
        $item['targetMode'] = $summary['targetMode'];
        $item['resolvedTarget'] = $summary['resolvedTarget'];
        $item['targetPart'] = $targetPart;
        $item['targetQuery'] = $summary['targetQuery'];
        $item['targetFragment'] = $summary['targetFragment'];
        $item['targetReferenceSuffix'] = $summary['targetReferenceSuffix'];
        $item['contentType'] = $summary['contentType'];
        $item['contentTypeBase'] = $summary['contentTypeBase'];
        $item['contentTypeHasParameters'] = $summary['contentTypeHasParameters'];
        $item['contentTypeParameterCount'] = $summary['contentTypeParameterCount'];
        $item['contentTypeParameters'] = $summary['contentTypeParameters'];
        $item['contentTypeParameterMap'] = $summary['contentTypeParameterMap'];
        $item['contentTypeSource'] = $summary['contentTypeSource'];
        $item['defaultExtension'] = $summary['defaultExtension'];
        $item['overridePartName'] = $summary['overridePartName'];
        $item['external'] = $external;
        $item['exists'] = (bool) ($summary['exists'] ?? false);
        $item['byteLength'] = $targetPart !== null && $item['exists'] === true ? strlen($parts[$targetPart]) : null;
        $item['crc32'] = $targetPart !== null && $item['exists'] === true ? sprintf('%08x', crc32($parts[$targetPart])) : null;
        $item['sha256'] = $targetPart !== null && $item['exists'] === true ? hash('sha256', $parts[$targetPart]) : null;
        $item['relationship'] = $summary;

        if (!in_array($relationship['type'], $expectedRelationshipTypes, true)) {
            $item['issues'][] = 'unexpected-relationship-type';
        }

        if ($external) {
            $externalPolicy = $this->externalRelationshipTargetPolicy($relationship['target']);
            $item['externalTargetKind'] = $externalPolicy['kind'];
            $item['externalTargetScheme'] = $externalPolicy['scheme'];
            $item['externalTargetAllowed'] = $externalPolicy['allowed'];
            $item['issues'] = array_values(array_unique(array_merge($item['issues'], $externalPolicy['issues'])));
        } else {
            if ($item['exists'] !== true) {
                $item['issues'][] = 'missing-in-package';
            }
            if (($summary['contentTypeSource'] ?? '') === 'missing') {
                $item['issues'][] = 'missing-content-type';
            }
        }

        $item['issues'] = array_values(array_unique($item['issues']));
        sort($item['issues'], SORT_STRING);

        return $item;
    }

    /**
     * @param array<string, mixed> $item
     * @param array<string, string> $parts
     * @return array<string, mixed>
     */
    private function mailMergeRecipientDataPartSummary(array $item, array $parts): array
    {
        $expectedContentTypeBases = [
            self::CT_MAIL_MERGE_RECIPIENT_DATA,
            self::CT_MS_MAIL_MERGE_RECIPIENT_DATA,
        ];
        $item['expectedContentTypeBases'] = $expectedContentTypeBases;
        $item['contentTypeMatchesExpected'] = null;
        $item['validXml'] = null;
        $item['xmlParseError'] = null;
        $item['rootNamespace'] = null;
        $item['rootLocalName'] = null;
        $item['validRoot'] = null;
        $item['recordCount'] = 0;
        $item['includedRecordCount'] = 0;
        $item['explicitIncludedRecordCount'] = 0;
        $item['implicitIncludedRecordCount'] = 0;
        $item['excludedRecordCount'] = 0;
        $item['uniqueTagCount'] = 0;
        $item['duplicateUniqueTagCount'] = 0;
        $item['duplicateUniqueTagRecordCount'] = 0;
        $item['columnIndexes'] = [];
        $item['uniqueTagSha256s'] = [];
        $item['duplicateUniqueTagSha256s'] = [];
        $item['records'] = [];

        if (($item['external'] ?? null) === true) {
            $item['issues'][] = 'external-recipient-data';
        } else {
            $contentTypeBase = is_string($item['contentTypeBase'] ?? null) ? $item['contentTypeBase'] : '';
            if ($contentTypeBase !== '') {
                $item['contentTypeMatchesExpected'] = in_array($contentTypeBase, $expectedContentTypeBases, true);
                if ($item['contentTypeMatchesExpected'] !== true) {
                    $item['issues'][] = 'unexpected-content-type';
                }
            }
        }

        $targetPart = is_string($item['targetPart'] ?? null) ? $item['targetPart'] : null;
        if ($targetPart === null || ($item['exists'] ?? false) !== true || !isset($parts[$targetPart])) {
            return $this->finalizeMailMergeRecipientDataPartSummary($item);
        }

        $dom = $this->loadXmlForProvenance($parts[$targetPart], $targetPart);
        if (!$dom instanceof \DOMDocument) {
            $item['validXml'] = false;
            $item['xmlParseError'] = $this->lastXmlPreflightError($parts[$targetPart], $targetPart);
            $item['issues'][] = 'invalid-recipient-data-xml';

            return $this->finalizeMailMergeRecipientDataPartSummary($item);
        }

        $root = $dom->documentElement;
        $validRoot = $root instanceof \DOMElement
            && in_array($root->namespaceURI, [self::NS_W, self::NS_WNE], true)
            && $root->localName === 'recipients';
        $item['validXml'] = $root instanceof \DOMElement;
        $item['rootNamespace'] = $root instanceof \DOMElement ? $root->namespaceURI : null;
        $item['rootLocalName'] = $root instanceof \DOMElement ? $root->localName : null;
        $item['validRoot'] = $validRoot;
        if (!$validRoot) {
            $item['issues'][] = 'unexpected-recipient-data-root';

            return $this->finalizeMailMergeRecipientDataPartSummary($item);
        }

        $xpath = $this->xpath($dom);
        $records = [];
        $columnIndexes = [];
        $uniqueTagSha256s = [];
        $uniqueTagRecordIndexesBySha256 = [];
        foreach ($this->elements($xpath, '/*[local-name()="recipients"]/*[local-name()="recipientData"]') as $index => $recipientData) {
            $active = $this->mailMergeRecipientChildBoolean($recipientData, 'active');
            $columnIndex = $this->mailMergeRecipientChildInt($recipientData, 'column');
            $uniqueTag = $this->mailMergeRecipientChildValue($recipientData, 'uniqueTag');
            $uniqueTagKind = 'uniqueTag';
            if ($uniqueTag === null) {
                $uniqueTag = $this->mailMergeRecipientChildValue($recipientData, 'hash');
                $uniqueTagKind = $uniqueTag === null ? null : 'hash';
            }
            $uniqueTagLength = $uniqueTag === null ? null : strlen($uniqueTag);
            $uniqueTagSha256 = $uniqueTag === null ? null : hash('sha256', $uniqueTag);
            $recordIssues = [];
            if ($columnIndex === null) {
                $recordIssues[] = 'missing-recipient-column';
            } else {
                $columnIndexes[$columnIndex] = true;
            }
            if ($uniqueTag === null) {
                $recordIssues[] = 'missing-recipient-unique-tag';
            } elseif ($uniqueTagSha256 !== null) {
                $uniqueTagSha256s[$uniqueTagSha256] = true;
                $uniqueTagRecordIndexesBySha256[$uniqueTagSha256][] = count($records);
            }

            $records[] = [
                'index' => $index,
                'active' => $active,
                'included' => $active !== false,
                'columnIndex' => $columnIndex,
                'uniqueTagPresent' => $uniqueTag !== null,
                'uniqueTagKind' => $uniqueTagKind,
                'uniqueTagLength' => $uniqueTagLength,
                'uniqueTagSha256' => $uniqueTagSha256,
                'duplicateUniqueTag' => false,
                'issues' => $recordIssues,
            ];
            foreach ($recordIssues as $issue) {
                $item['issues'][] = $issue;
            }
        }

        $duplicateUniqueTagSha256s = [];
        $duplicateUniqueTagRecordCount = 0;
        foreach ($uniqueTagRecordIndexesBySha256 as $sha256 => $recordIndexes) {
            if (count($recordIndexes) < 2) {
                continue;
            }

            $duplicateUniqueTagSha256s[] = $sha256;
            $duplicateUniqueTagRecordCount += count($recordIndexes);
            $item['issues'][] = 'duplicate-recipient-unique-tag';
            foreach ($recordIndexes as $recordIndex) {
                if (!isset($records[$recordIndex])) {
                    continue;
                }
                $records[$recordIndex]['duplicateUniqueTag'] = true;
                $records[$recordIndex]['issues'][] = 'duplicate-recipient-unique-tag';
                $records[$recordIndex]['issues'] = array_values(array_unique($records[$recordIndex]['issues']));
                sort($records[$recordIndex]['issues'], SORT_STRING);
            }
        }

        $columnIndexValues = array_keys($columnIndexes);
        sort($columnIndexValues, SORT_NUMERIC);
        $uniqueTagSha256Values = array_keys($uniqueTagSha256s);
        sort($uniqueTagSha256Values, SORT_STRING);
        sort($duplicateUniqueTagSha256s, SORT_STRING);

        $item['recordCount'] = count($records);
        $item['includedRecordCount'] = count(array_filter($records, static fn (array $record): bool => $record['included'] === true));
        $item['explicitIncludedRecordCount'] = count(array_filter($records, static fn (array $record): bool => $record['active'] === true));
        $item['implicitIncludedRecordCount'] = count(array_filter($records, static fn (array $record): bool => $record['active'] === null));
        $item['excludedRecordCount'] = count(array_filter($records, static fn (array $record): bool => $record['active'] === false));
        $item['uniqueTagCount'] = count($uniqueTagSha256Values);
        $item['duplicateUniqueTagCount'] = count($duplicateUniqueTagSha256s);
        $item['duplicateUniqueTagRecordCount'] = $duplicateUniqueTagRecordCount;
        $item['columnIndexes'] = $columnIndexValues;
        $item['uniqueTagSha256s'] = $uniqueTagSha256Values;
        $item['duplicateUniqueTagSha256s'] = $duplicateUniqueTagSha256s;
        $item['records'] = $records;

        return $this->finalizeMailMergeRecipientDataPartSummary($item);
    }

    /**
     * @param array<string, mixed> $item
     * @return array<string, mixed>
     */
    private function finalizeMailMergeRecipientDataPartSummary(array $item): array
    {
        $item['issues'] = array_values(array_unique(array_map('strval', $item['issues'] ?? [])));
        sort($item['issues'], SORT_STRING);

        return $item;
    }

    private function mailMergeRecipientChildElement(\DOMElement $parent, string $localName): ?\DOMElement
    {
        foreach ($parent->childNodes as $child) {
            if (
                $child instanceof \DOMElement
                && in_array($child->namespaceURI, [self::NS_W, self::NS_WNE], true)
                && $child->localName === $localName
            ) {
                return $child;
            }
        }

        return null;
    }

    private function mailMergeRecipientChildValue(\DOMElement $parent, string $localName): ?string
    {
        $child = $this->mailMergeRecipientChildElement($parent, $localName);
        if (!$child instanceof \DOMElement) {
            return null;
        }

        foreach ([self::NS_W, self::NS_WNE] as $namespace) {
            $value = trim($child->getAttributeNS($namespace, 'val'));
            if ($value !== '') {
                return $value;
            }
        }

        $value = trim($child->textContent);

        return $value === '' ? null : $value;
    }

    private function mailMergeRecipientChildBoolean(\DOMElement $parent, string $localName): ?bool
    {
        $child = $this->mailMergeRecipientChildElement($parent, $localName);
        if (!$child instanceof \DOMElement) {
            return null;
        }

        $value = $this->mailMergeRecipientChildValue($parent, $localName);
        if ($value === null) {
            return true;
        }

        return $this->onOffStringValue($value);
    }

    private function mailMergeRecipientChildInt(\DOMElement $parent, string $localName): ?int
    {
        $value = $this->mailMergeRecipientChildValue($parent, $localName);
        if ($value === null || preg_match('/^-?\d+$/', $value) !== 1) {
            return null;
        }

        return (int) $value;
    }

    /**
     * @return array{kind:string, scheme:?string, allowed:bool, issues:list<string>}
     */
    private function externalRelationshipTargetPolicy(string $target): array
    {
        $scheme = null;
        $kind = 'relative-reference';
        if (preg_match('/^([A-Za-z][A-Za-z0-9+.-]*):/', $target, $match) === 1) {
            $scheme = strtolower($match[1]);
            $kind = 'absolute-uri';
        } elseif (str_starts_with($target, '//')) {
            $kind = 'network-path-reference';
        }

        $allowed = $scheme === null || in_array($scheme, ['http', 'https', 'mailto', 'urn'], true);
        $issues = $allowed ? [] : ['external-target-unsafe-scheme'];

        return [
            'kind' => $kind,
            'scheme' => $scheme,
            'allowed' => $allowed,
            'issues' => $issues,
        ];
    }

    /**
     * @param array<string, string> $parts
     * @param array<string, mixed> $webSettingsPart
     * @param array<string, array{id:string, type:string, target:string, targetMode:string, resolvedTarget:string}> $relationships
     * @param array{defaults:array<string, string>, overrides:array<string, string>} $contentTypes
     * @return array<string, mixed>
     */
    private function readWebSettingsPartProvenance(
        array $parts,
        array $webSettingsPart,
        string $documentPart,
        string $relationshipsPart,
        array $relationships,
        array $contentTypes
    ): array {
        $items = [];
        $byRelationshipId = [];
        $byPartName = [];
        $relationshipIds = [];
        $selectedPartNames = [];
        $selectedRelationship = is_array($webSettingsPart['relationship'] ?? null) ? $webSettingsPart['relationship'] : null;
        $selectedRelationshipId = is_array($selectedRelationship) ? (string) ($selectedRelationship['id'] ?? '') : null;

        foreach ($relationships as $relationship) {
            if ($relationship['type'] !== self::WEB_SETTINGS_REL) {
                continue;
            }

            $item = $this->webSettingsPartRelationshipItem(
                $parts,
                $relationship,
                $documentPart,
                $relationshipsPart,
                $contentTypes,
                count($items),
                $selectedRelationshipId !== null && $relationship['id'] === $selectedRelationshipId,
            );
            $items[] = $item;

            $this->appendUniqueString($relationshipIds, $relationship['id']);
            if ($relationship['id'] !== '' && !isset($byRelationshipId[$relationship['id']])) {
                $byRelationshipId[$relationship['id']] = $item;
            }

            $partName = is_string($item['partName'] ?? null) ? $item['partName'] : null;
            if ($partName !== null && !isset($byPartName[$partName])) {
                $byPartName[$partName] = $item;
            }
            if (($item['selected'] ?? false) === true) {
                $this->appendUniqueString($selectedPartNames, $partName);
            }
        }

        if ($selectedRelationship === null && ($webSettingsPart['exists'] ?? false) === true) {
            $item = $this->webSettingsPartPackageItem(
                $parts,
                (string) ($webSettingsPart['partName'] ?? ''),
                $contentTypes,
                count($items),
            );
            $items[] = $item;

            $partName = is_string($item['partName'] ?? null) ? $item['partName'] : null;
            if ($partName !== null && !isset($byPartName[$partName])) {
                $byPartName[$partName] = $item;
            }
            $this->appendUniqueString($selectedPartNames, $partName);
        }

        $partNames = [];
        $existingPartNames = [];
        $missingPartNames = [];
        $externalTargets = [];
        $unsafeExternalTargets = [];
        $externalTargetKindCounts = [];
        $externalTargetSchemeCounts = [];
        $externalTargetIssueCodes = [];
        $contentTypesSeen = [];
        $contentTypeBaseCounts = [];
        $issueCodes = [];
        foreach ($items as $item) {
            $partName = is_string($item['partName'] ?? null) ? $item['partName'] : null;
            $this->appendUniqueString($partNames, $partName);
            $this->appendUniqueString($contentTypesSeen, is_string($item['contentType'] ?? null) ? $item['contentType'] : null);
            $contentTypeBase = is_string($item['contentTypeBase'] ?? null) ? $item['contentTypeBase'] : '';
            if ($contentTypeBase !== '') {
                $contentTypeBaseCounts[$contentTypeBase] = ($contentTypeBaseCounts[$contentTypeBase] ?? 0) + 1;
            }

            if (($item['exists'] ?? false) === true) {
                $this->appendUniqueString($existingPartNames, $partName);
            } elseif (($item['external'] ?? false) !== true) {
                $this->appendUniqueString($missingPartNames, $partName);
            }

            if (($item['external'] ?? false) === true) {
                $this->appendUniqueString($externalTargets, is_string($item['target'] ?? null) ? $item['target'] : null);
                if (($item['externalTargetAllowed'] ?? null) !== true) {
                    $this->appendUniqueString($unsafeExternalTargets, is_string($item['target'] ?? null) ? $item['target'] : null);
                }

                $kind = is_string($item['externalTargetKind'] ?? null) ? $item['externalTargetKind'] : '(unknown)';
                $externalTargetKindCounts[$kind] = ($externalTargetKindCounts[$kind] ?? 0) + 1;
                $scheme = is_string($item['externalTargetScheme'] ?? null) ? $item['externalTargetScheme'] : '(none)';
                $externalTargetSchemeCounts[$scheme] = ($externalTargetSchemeCounts[$scheme] ?? 0) + 1;
                foreach (($item['externalTargetIssues'] ?? []) as $issue) {
                    if (is_string($issue) && $issue !== '') {
                        $externalTargetIssueCodes[$issue] = true;
                    }
                }
            }

            foreach (($item['issues'] ?? []) as $issue) {
                if (is_string($issue) && $issue !== '') {
                    $issueCodes[$issue] = true;
                }
            }
        }
        ksort($contentTypeBaseCounts, SORT_STRING);
        ksort($externalTargetKindCounts, SORT_STRING);
        ksort($externalTargetSchemeCounts, SORT_STRING);
        ksort($externalTargetIssueCodes, SORT_STRING);
        ksort($issueCodes, SORT_STRING);

        return [
            'count' => count($items),
            'relationshipCount' => count(array_filter($relationships, static fn (array $relationship): bool => $relationship['type'] === self::WEB_SETTINGS_REL)),
            'selectedCount' => count(array_filter($items, static fn (array $item): bool => ($item['selected'] ?? false) === true)),
            'internalCount' => count(array_filter($items, static fn (array $item): bool => ($item['external'] ?? false) !== true)),
            'externalCount' => count(array_filter($items, static fn (array $item): bool => ($item['external'] ?? false) === true)),
            'allowedExternalTargetCount' => count(array_filter($items, static fn (array $item): bool => ($item['external'] ?? false) === true && ($item['externalTargetAllowed'] ?? null) === true)),
            'unsafeExternalTargetCount' => count(array_filter($items, static fn (array $item): bool => ($item['external'] ?? false) === true && ($item['externalTargetAllowed'] ?? null) !== true)),
            'existingCount' => count(array_filter($items, static fn (array $item): bool => ($item['exists'] ?? false) === true)),
            'missingCount' => count(array_filter($items, static fn (array $item): bool => in_array('missing-web-settings-part', $item['issues'] ?? [], true))),
            'missingContentTypeCount' => count(array_filter($items, static fn (array $item): bool => in_array('missing-web-settings-content-type', $item['issues'] ?? [], true))),
            'unexpectedContentTypeCount' => count(array_filter($items, static fn (array $item): bool => in_array('unexpected-web-settings-content-type', $item['issues'] ?? [], true))),
            'validXmlCount' => count(array_filter($items, static fn (array $item): bool => ($item['validXml'] ?? null) === true)),
            'invalidXmlCount' => count(array_filter($items, static fn (array $item): bool => in_array('invalid-web-settings-xml', $item['issues'] ?? [], true))),
            'validRootCount' => count(array_filter($items, static fn (array $item): bool => ($item['validRoot'] ?? null) === true)),
            'unexpectedRootCount' => count(array_filter($items, static fn (array $item): bool => in_array('unexpected-web-settings-root', $item['issues'] ?? [], true))),
            'relationshipIds' => $relationshipIds,
            'selectedPartNames' => $selectedPartNames,
            'partNames' => $partNames,
            'existingPartNames' => $existingPartNames,
            'missingPartNames' => $missingPartNames,
            'externalTargets' => $externalTargets,
            'unsafeExternalTargets' => $unsafeExternalTargets,
            'externalTargetKindCounts' => $externalTargetKindCounts,
            'externalTargetSchemeCounts' => $externalTargetSchemeCounts,
            'externalTargetIssueCodes' => array_keys($externalTargetIssueCodes),
            'contentTypes' => $contentTypesSeen,
            'contentTypeBaseCounts' => $contentTypeBaseCounts,
            'expectedContentTypeBase' => self::CT_WORD_WEB_SETTINGS,
            'issueCount' => count(array_filter($items, static fn (array $item): bool => ($item['issues'] ?? []) !== [])),
            'issueCodes' => array_keys($issueCodes),
            'byRelationshipId' => $byRelationshipId,
            'byPartName' => $byPartName,
            'items' => $items,
            'byteExposurePolicy' => 'web-settings-bytes-blocked',
            'reviewPolicy' => 'web-settings-metadata-only',
        ];
    }

    /**
     * @param array<string, string> $parts
     * @param array{id:string, type:string, target:string, targetMode:string, resolvedTarget:string} $relationship
     * @param array{defaults:array<string, string>, overrides:array<string, string>} $contentTypes
     * @return array<string, mixed>
     */
    private function webSettingsPartRelationshipItem(
        array $parts,
        array $relationship,
        string $documentPart,
        string $relationshipsPart,
        array $contentTypes,
        int $index,
        bool $selected
    ): array {
        $item = $this->emptyWebSettingsPartItem($index);
        $summary = $this->relationshipInventorySummary($parts, $relationship, $documentPart, $relationshipsPart, $contentTypes);
        $targetPart = is_string($summary['targetPart'] ?? null) ? $summary['targetPart'] : null;
        $exists = (bool) ($summary['exists'] ?? false);

        $item['relationshipId'] = $summary['id'];
        $item['relationshipPresent'] = true;
        $item['selected'] = $selected;
        $item['selectionSource'] = $selected ? 'relationship' : 'unselected-relationship';
        $item['relationshipType'] = $summary['type'];
        $item['target'] = $summary['target'];
        $item['targetMode'] = $summary['targetMode'];
        $item['resolvedTarget'] = $summary['resolvedTarget'];
        $item['external'] = (bool) ($summary['external'] ?? false);
        $item['partName'] = $targetPart;
        $item['targetPart'] = $targetPart;
        $item['targetQuery'] = $summary['targetQuery'];
        $item['targetFragment'] = $summary['targetFragment'];
        $item['targetReferenceSuffix'] = $summary['targetReferenceSuffix'];
        $item['externalTargetKind'] = $summary['externalTargetKind'];
        $item['externalTargetScheme'] = $summary['externalTargetScheme'];
        $item['externalTargetAllowed'] = $summary['externalTargetAllowed'];
        $item['externalTargetIssues'] = $summary['externalTargetIssues'];
        $item['exists'] = $exists;
        $item['bytes'] = $exists && $targetPart !== null ? strlen($parts[$targetPart]) : 0;
        $item['byteLength'] = $item['bytes'];
        $item['crc32'] = $exists && $targetPart !== null ? sprintf('%08x', crc32($parts[$targetPart])) : null;
        $item['sha256'] = $exists && $targetPart !== null ? hash('sha256', $parts[$targetPart]) : null;
        $item['contentType'] = $summary['contentType'];
        $item['contentTypeBase'] = $summary['contentTypeBase'];
        $item['contentTypeHasParameters'] = $summary['contentTypeHasParameters'];
        $item['contentTypeParameterCount'] = $summary['contentTypeParameterCount'];
        $item['contentTypeParameters'] = $summary['contentTypeParameters'];
        $item['contentTypeParameterMap'] = $summary['contentTypeParameterMap'];
        $item['contentTypeSource'] = $summary['contentTypeSource'];
        $item['defaultExtension'] = $summary['defaultExtension'];
        $item['overridePartName'] = $summary['overridePartName'];
        $item['relationship'] = $summary;

        if ($item['external'] === true) {
            $item['issues'][] = 'external-web-settings-part';
            foreach ($item['externalTargetIssues'] as $issue) {
                if (is_string($issue) && $issue !== '') {
                    $this->appendUniqueString($item['issues'], $issue);
                }
            }
            $item['valid'] = false;

            return $item;
        }

        if (!$exists) {
            $item['issues'][] = 'missing-web-settings-part';
        }

        if (($summary['contentTypeSource'] ?? '') === 'missing') {
            $item['issues'][] = 'missing-web-settings-content-type';
        } elseif (($summary['contentTypeBase'] ?? '') !== self::CT_WORD_WEB_SETTINGS) {
            $item['issues'][] = 'unexpected-web-settings-content-type';
        }

        if ($exists && $targetPart !== null) {
            $this->applyWebSettingsPartXmlMetadata($item, $parts[$targetPart], $targetPart);
        }
        $item['valid'] = $item['issues'] === [];

        return $item;
    }

    /**
     * @param array<string, string> $parts
     * @param array{defaults:array<string, string>, overrides:array<string, string>} $contentTypes
     * @return array<string, mixed>
     */
    private function webSettingsPartPackageItem(array $parts, string $partName, array $contentTypes, int $index): array
    {
        $item = $this->emptyWebSettingsPartItem($index);
        $contentTypeResolution = $this->contentTypeResolutionForPart($partName, $contentTypes);
        $exists = isset($parts[$partName]);

        $item['selected'] = true;
        $item['selectionSource'] = 'conventional-part';
        $item['partName'] = $partName;
        $item['targetPart'] = $partName;
        $item['exists'] = $exists;
        $item['bytes'] = $exists ? strlen($parts[$partName]) : 0;
        $item['byteLength'] = $item['bytes'];
        $item['crc32'] = $exists ? sprintf('%08x', crc32($parts[$partName])) : null;
        $item['sha256'] = $exists ? hash('sha256', $parts[$partName]) : null;
        $item['contentType'] = $contentTypeResolution['contentType'];
        $item['contentTypeBase'] = $contentTypeResolution['contentTypeBase'];
        $item['contentTypeHasParameters'] = $contentTypeResolution['contentTypeHasParameters'];
        $item['contentTypeParameterCount'] = $contentTypeResolution['contentTypeParameterCount'];
        $item['contentTypeParameters'] = $contentTypeResolution['contentTypeParameters'];
        $item['contentTypeParameterMap'] = $contentTypeResolution['contentTypeParameterMap'];
        $item['contentTypeSource'] = $contentTypeResolution['contentTypeSource'];
        $item['defaultExtension'] = $contentTypeResolution['defaultExtension'];
        $item['overridePartName'] = $contentTypeResolution['overridePartName'];

        if (($contentTypeResolution['contentTypeSource'] ?? '') === 'missing') {
            $item['issues'][] = 'missing-web-settings-content-type';
        } elseif (($contentTypeResolution['contentTypeBase'] ?? '') !== self::CT_WORD_WEB_SETTINGS) {
            $item['issues'][] = 'unexpected-web-settings-content-type';
        }

        if ($exists) {
            $this->applyWebSettingsPartXmlMetadata($item, $parts[$partName], $partName);
        }
        $item['valid'] = $item['issues'] === [];

        return $item;
    }

    /**
     * @return array<string, mixed>
     */
    private function emptyWebSettingsPartItem(int $index): array
    {
        return [
            'index' => $index,
            'relationshipId' => null,
            'relationshipPresent' => false,
            'selected' => false,
            'selectionSource' => 'unselected',
            'relationshipType' => null,
            'target' => null,
            'targetMode' => null,
            'resolvedTarget' => null,
            'external' => false,
            'partName' => null,
            'targetPart' => null,
            'targetQuery' => null,
            'targetFragment' => null,
            'targetReferenceSuffix' => '',
            'externalTargetKind' => null,
            'externalTargetScheme' => null,
            'externalTargetAllowed' => null,
            'externalTargetIssues' => [],
            'exists' => false,
            'bytes' => 0,
            'byteLength' => 0,
            'crc32' => null,
            'sha256' => null,
            'contentType' => '',
            'contentTypeBase' => '',
            'contentTypeHasParameters' => false,
            'contentTypeParameterCount' => 0,
            'contentTypeParameters' => [],
            'contentTypeParameterMap' => [],
            'contentTypeSource' => 'missing',
            'defaultExtension' => null,
            'overridePartName' => null,
            'expectedContentTypeBase' => self::CT_WORD_WEB_SETTINGS,
            'validXml' => null,
            'xmlParseError' => null,
            'rootNamespace' => null,
            'rootLocalName' => null,
            'rootQualifiedName' => null,
            'rootPrefix' => null,
            'validRoot' => null,
            'byteExposurePolicy' => 'web-settings-bytes-blocked',
            'reviewPolicy' => 'web-settings-metadata-only',
            'valid' => false,
            'issues' => [],
            'relationship' => null,
        ];
    }

    /**
     * @param array<string, mixed> $item
     */
    private function applyWebSettingsPartXmlMetadata(array &$item, string $xml, string $partName): void
    {
        $root = $this->xmlRootProvenance($xml, $partName);
        $item['validXml'] = $root['validXml'];
        $item['xmlParseError'] = $root['xmlParseError'];
        $item['rootNamespace'] = $root['namespace'];
        $item['rootLocalName'] = $root['localName'];
        $item['rootQualifiedName'] = $root['qualifiedName'];
        $item['rootPrefix'] = $root['prefix'];
        $item['validRoot'] = $root['validXml'] === true
            && $root['namespace'] === self::NS_W
            && $root['localName'] === 'webSettings';

        if ($root['validXml'] === false) {
            $item['issues'][] = 'invalid-web-settings-xml';
        } elseif ($item['validRoot'] === false) {
            $item['issues'][] = 'unexpected-web-settings-root';
        }
    }

    /**
     * @return array<string, mixed>
     */
    private function readWebSettings(string $xml, string $partName): array
    {
        if ($xml === '') {
            return [];
        }

        $dom = $this->loadXmlForProvenance($xml, $partName);
        if (!$dom instanceof \DOMDocument) {
            return [
                'validXml' => false,
                'xmlParseError' => $this->lastXmlPreflightError($xml, $partName),
                'issueCount' => 1,
                'issueCodes' => ['invalid-web-settings-xml'],
            ];
        }

        $xpath = $this->xpath($dom);
        $webSettings = [
            'validXml' => true,
            'xmlParseError' => null,
            'issueCount' => 0,
            'issueCodes' => [],
        ];

        foreach ([
            'optimizeForBrowser' => 'optimizeForBrowser',
            'allowPNG' => 'allowPng',
            'relyOnVML' => 'relyOnVml',
            'doNotRelyOnCSS' => 'doNotRelyOnCss',
            'doNotSaveAsSingleFile' => 'doNotSaveAsSingleFile',
            'doNotOrganizeInFolder' => 'doNotOrganizeInFolder',
            'doNotUseLongFileNames' => 'doNotUseLongFileNames',
        ] as $source => $target) {
            $element = $this->firstElement($xpath, '/w:webSettings/w:' . $source, $dom);
            if ($element instanceof \DOMElement) {
                $webSettings[$target] = $this->wordBoolean($element);
            }
        }

        foreach ([
            'encoding' => 'encoding',
            'targetScreenSz' => 'targetScreenSize',
        ] as $source => $target) {
            $element = $this->firstElement($xpath, '/w:webSettings/w:' . $source, $dom);
            if ($element instanceof \DOMElement) {
                $value = $element->getAttributeNS(self::NS_W, 'val');
                if ($value !== '') {
                    $webSettings[$target] = $value;
                }
            }
        }

        $pixelsPerInch = $this->firstElement($xpath, '/w:webSettings/w:pixelsPerInch', $dom);
        if ($pixelsPerInch instanceof \DOMElement && is_numeric($pixelsPerInch->getAttributeNS(self::NS_W, 'val'))) {
            $webSettings['pixelsPerInch'] = (int) $pixelsPerInch->getAttributeNS(self::NS_W, 'val');
        }

        if ($webSettings !== []) {
            $webSettings['outputPolicy'] = $this->webSettingsOutputPolicy($webSettings);
        }

        return $webSettings;
    }

    /**
     * @param array<string, mixed> $webSettings
     * @return array<string, mixed>
     */
    private function webSettingsOutputPolicy(array $webSettings): array
    {
        $flags = [];
        foreach ([
            'optimizeForBrowser' => [
                'enabled' => 'browser-optimized',
                'disabled' => 'browser-optimization-disabled',
            ],
            'allowPng' => [
                'enabled' => 'png-allowed',
                'disabled' => 'png-disabled',
            ],
            'relyOnVml' => [
                'enabled' => 'vml-required',
                'disabled' => 'vml-not-required',
            ],
            'doNotRelyOnCss' => [
                'enabled' => 'css-output-disabled',
                'disabled' => 'css-output-allowed',
            ],
            'doNotSaveAsSingleFile' => [
                'enabled' => 'single-file-output-disabled',
                'disabled' => 'single-file-output-allowed',
            ],
            'doNotOrganizeInFolder' => [
                'enabled' => 'folder-organization-disabled',
                'disabled' => 'folder-organization-allowed',
            ],
            'doNotUseLongFileNames' => [
                'enabled' => 'long-file-names-disabled',
                'disabled' => 'long-file-names-allowed',
            ],
        ] as $key => $labels) {
            $value = $webSettings[$key] ?? null;
            if (is_bool($value)) {
                $flags[] = $value ? $labels['enabled'] : $labels['disabled'];
            }
        }

        return [
            'flagCount' => count($flags),
            'flags' => $flags,
            'browserOptimized' => $webSettings['optimizeForBrowser'] ?? null,
            'pngAllowed' => $webSettings['allowPng'] ?? null,
            'vmlRequired' => $webSettings['relyOnVml'] ?? null,
            'cssOutputDisabled' => $webSettings['doNotRelyOnCss'] ?? null,
            'singleFileOutputDisabled' => $webSettings['doNotSaveAsSingleFile'] ?? null,
            'folderOrganizationDisabled' => $webSettings['doNotOrganizeInFolder'] ?? null,
            'longFileNamesDisabled' => $webSettings['doNotUseLongFileNames'] ?? null,
            'encoding' => is_string($webSettings['encoding'] ?? null) ? $webSettings['encoding'] : null,
            'targetScreenSize' => is_string($webSettings['targetScreenSize'] ?? null) ? $webSettings['targetScreenSize'] : null,
            'pixelsPerInch' => is_int($webSettings['pixelsPerInch'] ?? null) ? $webSettings['pixelsPerInch'] : null,
        ];
    }

    /**
     * @return array<string, mixed>
     */
    private function readFontTable(string $xml, string $partName, array $parts, array $contentTypes): array
    {
        if ($xml === '') {
            return [];
        }

        $relationshipsPart = $this->relationshipsPartFor($partName);
        $relationships = $this->readRelationshipsPart($parts, $relationshipsPart);
        $dom = $this->loadXmlForProvenance($xml, $partName);
        if (!$dom instanceof \DOMDocument) {
            return [
                'relationshipsPart' => $relationshipsPart,
                'relationshipCount' => count($relationships),
                'validXml' => false,
                'xmlParseError' => $this->lastXmlPreflightError($xml, $partName),
                'invalidXmlCount' => 1,
                'issueCount' => 1,
                'issueCodes' => ['invalid-font-table-xml'],
                'fontCount' => 0,
                'embeddedFontRelationshipCount' => 0,
                'embeddedFontExistingCount' => 0,
                'embeddedFontMissingCount' => 0,
                'embeddedFontExternalCount' => 0,
                'embeddedFontAllowedExternalCount' => 0,
                'embeddedFontUnsafeExternalCount' => 0,
                'embeddedFontUnsafeExternalTargets' => [],
                'embeddedFontExternalTargetKindCounts' => [],
                'embeddedFontExternalTargetSchemeCounts' => [],
                'embeddedFontExternalTargetIssueCodes' => [],
                'embeddedFontIssueCount' => 0,
                'embeddedFontIssueCodes' => [],
                'embeddedFontKeyPresentCount' => 0,
                'embeddedFontInvalidKeyCount' => 0,
                'notTrueTypeCount' => 0,
                'signatureCount' => 0,
                'signatureUnicodeRangeCount' => 0,
                'signatureCodePageRangeCount' => 0,
                'declaredNames' => [],
                'fonts' => [],
                'byName' => [],
            ];
        }

        $xpath = $this->xpath($dom);
        $fonts = [];
        $byName = [];
        $embeddedFontRelationshipCount = 0;
        $embeddedFontExistingCount = 0;
        $embeddedFontMissingCount = 0;
        $embeddedFontExternalCount = 0;
        $embeddedFontAllowedExternalCount = 0;
        $embeddedFontUnsafeExternalCount = 0;
        $embeddedFontUnsafeExternalTargets = [];
        $embeddedFontExternalTargetKindCounts = [];
        $embeddedFontExternalTargetSchemeCounts = [];
        $embeddedFontExternalTargetIssueCodes = [];
        $embeddedFontIssueCount = 0;
        $embeddedFontIssueCodes = [];
        $embeddedFontKeyPresentCount = 0;
        $embeddedFontInvalidKeyCount = 0;
        foreach ($this->elements($xpath, '/w:fonts/w:font') as $font) {
            $name = $font->getAttributeNS(self::NS_W, 'name');
            if ($name === '') {
                continue;
            }

            $record = array_filter([
                'name' => $name,
                'alternateName' => $this->childAttr($font, 'altName', 'val') ?: null,
                'charset' => $this->childAttr($font, 'charset', 'val') ?: null,
                'family' => $this->childAttr($font, 'family', 'val') ?: null,
                'pitch' => $this->childAttr($font, 'pitch', 'val') ?: null,
                'panose1' => $this->childAttr($font, 'panose1', 'val') ?: null,
            ], static fn (mixed $value): bool => $value !== null && $value !== '');
            $notTrueType = $this->childElement($font, 'notTrueType');
            if ($notTrueType instanceof \DOMElement) {
                $record['notTrueType'] = $this->wordBoolean($notTrueType);
            }
            $signature = $this->fontTableSignature($font);
            if ($signature !== []) {
                $record['signature'] = $signature;
            }
            $embeddedFonts = $this->fontTableEmbeddedFonts($font, $parts, $relationships, $partName, $relationshipsPart, $contentTypes);
            $record['embeddedFontCount'] = count($embeddedFonts);
            $record['embeddedFonts'] = $embeddedFonts;
            $embeddedFontRelationshipCount += count($embeddedFonts);
            foreach ($embeddedFonts as $embeddedFont) {
                if (($embeddedFont['external'] ?? false) === true) {
                    ++$embeddedFontExternalCount;
                    if (($embeddedFont['externalTargetAllowed'] ?? null) === true) {
                        ++$embeddedFontAllowedExternalCount;
                    } else {
                        ++$embeddedFontUnsafeExternalCount;
                        $this->appendUniqueString($embeddedFontUnsafeExternalTargets, is_string($embeddedFont['target'] ?? null) ? $embeddedFont['target'] : null);
                    }
                    $kind = $embeddedFont['externalTargetKind'] ?? null;
                    if (is_string($kind) && $kind !== '') {
                        $embeddedFontExternalTargetKindCounts[$kind] = ($embeddedFontExternalTargetKindCounts[$kind] ?? 0) + 1;
                    }
                    $scheme = $embeddedFont['externalTargetScheme'] ?? null;
                    if (is_string($scheme) && $scheme !== '') {
                        $embeddedFontExternalTargetSchemeCounts[$scheme] = ($embeddedFontExternalTargetSchemeCounts[$scheme] ?? 0) + 1;
                    }
                    foreach (($embeddedFont['externalTargetIssues'] ?? []) as $issue) {
                        if (is_string($issue) && $issue !== '') {
                            $embeddedFontExternalTargetIssueCodes[$issue] = true;
                        }
                    }
                }
                if (($embeddedFont['external'] ?? false) === false && ($embeddedFont['exists'] ?? false) === true) {
                    ++$embeddedFontExistingCount;
                }
                if (in_array('missing-in-package', $embeddedFont['issues'], true)) {
                    ++$embeddedFontMissingCount;
                }
                if ($embeddedFont['issues'] !== []) {
                    ++$embeddedFontIssueCount;
                }
                if (($embeddedFont['fontKeyPresent'] ?? false) === true) {
                    ++$embeddedFontKeyPresentCount;
                }
                if (($embeddedFont['fontKeyValidGuid'] ?? null) === false) {
                    ++$embeddedFontInvalidKeyCount;
                }
                foreach ($embeddedFont['issues'] as $issue) {
                    if (is_string($issue) && $issue !== '') {
                        $embeddedFontIssueCodes[$issue] = true;
                    }
                }
            }

            $fonts[] = $record;
            $byName[$name] = $record;
        }
        ksort($embeddedFontIssueCodes, SORT_STRING);
        ksort($embeddedFontExternalTargetIssueCodes, SORT_STRING);
        ksort($embeddedFontExternalTargetKindCounts, SORT_STRING);
        ksort($embeddedFontExternalTargetSchemeCounts, SORT_STRING);

        return [
            'relationshipsPart' => $relationshipsPart,
            'relationshipCount' => count($relationships),
            'validXml' => true,
            'xmlParseError' => null,
            'invalidXmlCount' => 0,
            'issueCount' => 0,
            'issueCodes' => [],
            'fontCount' => count($fonts),
            'embeddedFontRelationshipCount' => $embeddedFontRelationshipCount,
            'embeddedFontExistingCount' => $embeddedFontExistingCount,
            'embeddedFontMissingCount' => $embeddedFontMissingCount,
            'embeddedFontExternalCount' => $embeddedFontExternalCount,
            'embeddedFontAllowedExternalCount' => $embeddedFontAllowedExternalCount,
            'embeddedFontUnsafeExternalCount' => $embeddedFontUnsafeExternalCount,
            'embeddedFontUnsafeExternalTargets' => $embeddedFontUnsafeExternalTargets,
            'embeddedFontExternalTargetKindCounts' => $embeddedFontExternalTargetKindCounts,
            'embeddedFontExternalTargetSchemeCounts' => $embeddedFontExternalTargetSchemeCounts,
            'embeddedFontExternalTargetIssueCodes' => array_keys($embeddedFontExternalTargetIssueCodes),
            'embeddedFontIssueCount' => $embeddedFontIssueCount,
            'embeddedFontIssueCodes' => array_keys($embeddedFontIssueCodes),
            'embeddedFontKeyPresentCount' => $embeddedFontKeyPresentCount,
            'embeddedFontInvalidKeyCount' => $embeddedFontInvalidKeyCount,
            'notTrueTypeCount' => count(array_filter($fonts, static fn (array $font): bool => ($font['notTrueType'] ?? false) === true)),
            'signatureCount' => count(array_filter($fonts, static fn (array $font): bool => isset($font['signature']))),
            'signatureUnicodeRangeCount' => array_sum(array_map(static fn (array $font): int => (int) ($font['signature']['unicodeRangeCount'] ?? 0), $fonts)),
            'signatureCodePageRangeCount' => array_sum(array_map(static fn (array $font): int => (int) ($font['signature']['codePageRangeCount'] ?? 0), $fonts)),
            'declaredNames' => array_column($fonts, 'name'),
            'fonts' => $fonts,
            'byName' => $byName,
        ];
    }

    /**
     * @return array<string, mixed>
     */
    private function fontTableSignature(\DOMElement $font): array
    {
        $signature = $this->childElement($font, 'sig');
        if (!$signature instanceof \DOMElement) {
            return [];
        }

        $unicodeRanges = [];
        foreach (['usb0', 'usb1', 'usb2', 'usb3'] as $attribute) {
            $value = trim($signature->getAttributeNS(self::NS_W, $attribute));
            if ($value !== '') {
                $unicodeRanges[$attribute] = $value;
            }
        }

        $codePageRanges = [];
        foreach (['csb0', 'csb1'] as $attribute) {
            $value = trim($signature->getAttributeNS(self::NS_W, $attribute));
            if ($value !== '') {
                $codePageRanges[$attribute] = $value;
            }
        }

        return [
            'unicodeRanges' => $unicodeRanges,
            'unicodeRangeCount' => count($unicodeRanges),
            'codePageRanges' => $codePageRanges,
            'codePageRangeCount' => count($codePageRanges),
            'rawAttributes' => [
                'usb0' => $unicodeRanges['usb0'] ?? null,
                'usb1' => $unicodeRanges['usb1'] ?? null,
                'usb2' => $unicodeRanges['usb2'] ?? null,
                'usb3' => $unicodeRanges['usb3'] ?? null,
                'csb0' => $codePageRanges['csb0'] ?? null,
                'csb1' => $codePageRanges['csb1'] ?? null,
            ],
        ];
    }

    /**
     * @param array<string, string> $parts
     * @param array<string, array{id:string, type:string, target:string, targetMode:string, resolvedTarget:string}> $relationships
     * @param array{defaults:array<string, string>, overrides:array<string, string>} $contentTypes
     * @return list<array<string, mixed>>
     */
    private function fontTableEmbeddedFonts(
        \DOMElement $font,
        array $parts,
        array $relationships,
        string $fontTablePart,
        string $relationshipsPart,
        array $contentTypes
    ): array {
        $embeddedFonts = [];
        foreach ([
            'embedRegular' => 'regular',
            'embedBold' => 'bold',
            'embedItalic' => 'italic',
            'embedBoldItalic' => 'bold-italic',
        ] as $localName => $style) {
            $embedded = $this->childElement($font, $localName);
            if (!$embedded instanceof \DOMElement) {
                continue;
            }

            $relationshipId = $this->fontTableEmbeddedFontRelationshipId($embedded);
            $embeddedFonts[] = $this->fontTableEmbeddedFontItem(
                $parts,
                $relationships[$relationshipId] ?? null,
                $fontTablePart,
                $relationshipsPart,
                $contentTypes,
                $relationshipId,
                $style,
                $this->fontTableEmbeddedFontKey($embedded),
            );
        }

        return $embeddedFonts;
    }

    private function fontTableEmbeddedFontRelationshipId(\DOMElement $embedded): string
    {
        $relationshipId = trim($embedded->getAttributeNS(self::NS_R, 'id'));
        if ($relationshipId !== '') {
            return $relationshipId;
        }

        return trim($embedded->getAttribute('id'));
    }

    private function fontTableEmbeddedFontKey(\DOMElement $embedded): string
    {
        $fontKey = trim($embedded->getAttributeNS(self::NS_W, 'fontKey'));
        if ($fontKey !== '') {
            return $fontKey;
        }

        return trim($embedded->getAttribute('fontKey'));
    }

    private function fontTableEmbeddedFontKeyIsValid(string $fontKey): bool
    {
        $guid = '[0-9A-Fa-f]{8}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{12}';

        return preg_match('/^(?:' . $guid . '|\{' . $guid . '\})$/', trim($fontKey)) === 1;
    }

    /**
     * @param array<string, string> $parts
     * @param array{id:string, type:string, target:string, targetMode:string, resolvedTarget:string}|null $relationship
     * @param array{defaults:array<string, string>, overrides:array<string, string>} $contentTypes
     * @return array<string, mixed>
     */
    private function fontTableEmbeddedFontItem(
        array $parts,
        ?array $relationship,
        string $fontTablePart,
        string $relationshipsPart,
        array $contentTypes,
        string $relationshipId,
        string $style,
        string $fontKey
    ): array {
        $item = [
            'style' => $style,
            'id' => $relationshipId,
            'sourcePart' => $fontTablePart,
            'relationshipsPart' => $relationshipsPart,
            'relationshipType' => null,
            'target' => null,
            'targetMode' => null,
            'resolvedTarget' => null,
            'targetPart' => null,
            'targetQuery' => null,
            'targetFragment' => null,
            'targetReferenceSuffix' => '',
            'contentType' => '',
            'contentTypeBase' => '',
            'contentTypeHasParameters' => false,
            'contentTypeParameterCount' => 0,
            'contentTypeParameters' => [],
            'contentTypeParameterMap' => [],
            'contentTypeSource' => 'missing',
            'defaultExtension' => null,
            'overridePartName' => null,
            'expectedContentTypeBase' => self::CT_OBFUSCATED_FONT,
            'external' => false,
            'externalTargetKind' => null,
            'externalTargetScheme' => null,
            'externalTargetAllowed' => null,
            'externalTargetIssues' => [],
            'exists' => false,
            'byteLength' => null,
            'crc32' => null,
            'sha256' => null,
            'fontKeyPresent' => $fontKey !== '',
            'fontKeyByteLength' => $fontKey !== '' ? strlen($fontKey) : 0,
            'fontKeyBraceWrapped' => $fontKey !== '' ? str_starts_with($fontKey, '{') && str_ends_with($fontKey, '}') : null,
            'fontKeyValidGuid' => $fontKey !== '' ? $this->fontTableEmbeddedFontKeyIsValid($fontKey) : null,
            'fontKeySha256' => $fontKey !== '' ? hash('sha256', $fontKey) : null,
            'byteExposurePolicy' => 'embedded-font-bytes-blocked',
            'reviewPolicy' => 'embedded-font-metadata-only',
            'valid' => false,
            'issues' => [],
            'relationship' => null,
        ];

        if ($relationshipId === '') {
            $item['issues'][] = 'missing-relationship-id';
            if ($item['fontKeyValidGuid'] === false) {
                $item['issues'][] = 'invalid-font-key';
            }

            return $item;
        }

        if (!is_array($relationship)) {
            $item['issues'][] = 'missing-relationship';
            if ($item['fontKeyValidGuid'] === false) {
                $item['issues'][] = 'invalid-font-key';
            }

            return $item;
        }

        $summary = $this->relationshipInventorySummary($parts, $relationship, $fontTablePart, $relationshipsPart, $contentTypes);
        $targetPart = is_string($summary['targetPart'] ?? null) ? $summary['targetPart'] : null;
        $external = (bool) ($summary['external'] ?? false);
        $exists = (bool) ($summary['exists'] ?? false);
        $contentTypeBase = is_string($summary['contentTypeBase'] ?? null) ? $summary['contentTypeBase'] : '';

        $item['relationshipType'] = $summary['type'];
        $item['target'] = $summary['target'];
        $item['targetMode'] = $summary['targetMode'];
        $item['resolvedTarget'] = $summary['resolvedTarget'];
        $item['targetPart'] = $targetPart;
        $item['targetQuery'] = $summary['targetQuery'];
        $item['targetFragment'] = $summary['targetFragment'];
        $item['targetReferenceSuffix'] = $summary['targetReferenceSuffix'];
        $item['contentType'] = $summary['contentType'];
        $item['contentTypeBase'] = $summary['contentTypeBase'];
        $item['contentTypeHasParameters'] = $summary['contentTypeHasParameters'];
        $item['contentTypeParameterCount'] = $summary['contentTypeParameterCount'];
        $item['contentTypeParameters'] = $summary['contentTypeParameters'];
        $item['contentTypeParameterMap'] = $summary['contentTypeParameterMap'];
        $item['contentTypeSource'] = $summary['contentTypeSource'];
        $item['defaultExtension'] = $summary['defaultExtension'];
        $item['overridePartName'] = $summary['overridePartName'];
        $item['external'] = $external;
        $item['externalTargetKind'] = $summary['externalTargetKind'];
        $item['externalTargetScheme'] = $summary['externalTargetScheme'];
        $item['externalTargetAllowed'] = $summary['externalTargetAllowed'];
        $item['externalTargetIssues'] = $summary['externalTargetIssues'];
        $item['exists'] = $exists;
        $item['byteLength'] = $targetPart !== null && $exists ? strlen($parts[$targetPart]) : null;
        $item['crc32'] = $targetPart !== null && $exists ? sprintf('%08x', crc32($parts[$targetPart])) : null;
        $item['sha256'] = $targetPart !== null && $exists ? hash('sha256', $parts[$targetPart]) : null;
        $item['relationship'] = $summary;

        if ($relationship['type'] !== self::FONT_REL) {
            $item['issues'][] = 'unexpected-relationship-type';
        }

        if ($external) {
            $item['issues'][] = 'external-embedded-font';
            foreach (($summary['externalTargetIssues'] ?? []) as $issue) {
                if (is_string($issue) && $issue !== '') {
                    $item['issues'][] = $issue;
                }
            }
        } else {
            if (!$exists) {
                $item['issues'][] = 'missing-in-package';
            }
            if (($summary['contentTypeSource'] ?? '') === 'missing') {
                $item['issues'][] = 'missing-content-type';
            } elseif ($contentTypeBase !== self::CT_OBFUSCATED_FONT) {
                $item['issues'][] = 'unexpected-embedded-font-content-type';
            }
        }
        if ($item['fontKeyValidGuid'] === false) {
            $item['issues'][] = 'invalid-font-key';
        }

        $item['issues'] = array_values(array_unique($item['issues']));
        $item['valid'] = $item['issues'] === [];

        return $item;
    }

    /**
     * @return array<string, mixed>
     */
    private function readTheme(string $xml, string $partName): array
    {
        if ($xml === '') {
            return [];
        }

        $dom = $this->loadXml($xml, $partName);
        $xpath = $this->xpath($dom);
        $root = $dom->documentElement;
        if (!$root instanceof \DOMElement || $root->namespaceURI !== self::NS_A || $root->localName !== 'theme') {
            return [];
        }

        $theme = [];
        $name = trim($root->getAttribute('name'));
        if ($name !== '') {
            $theme['name'] = $name;
        }

        $fonts = $this->themeFontScheme($xpath, $root);
        if ($fonts !== []) {
            $theme['fonts'] = $fonts;
        }

        $colors = $this->themeColorScheme($xpath, $root);
        if ($colors !== []) {
            $theme['colors'] = $colors;
        }

        return $theme;
    }

    /**
     * @return array<string, string>
     */
    private function themeFontScheme(\DOMXPath $xpath, \DOMElement $theme): array
    {
        $fontScheme = $this->firstElement($xpath, 'a:themeElements/a:fontScheme', $theme);
        if (!$fontScheme instanceof \DOMElement) {
            return [];
        }

        $fonts = [];
        $schemeName = trim($fontScheme->getAttribute('name'));
        if ($schemeName !== '') {
            $fonts['schemeName'] = $schemeName;
        }

        $supplementalFontCount = 0;
        $supplementalFontScripts = [];
        foreach ([
            'majorFont' => 'major',
            'minorFont' => 'minor',
        ] as $fontElementName => $prefix) {
            $fontElement = $this->firstElement($xpath, 'a:' . $fontElementName, $fontScheme);
            if (!$fontElement instanceof \DOMElement) {
                continue;
            }

            foreach ([
                'latin' => 'Latin',
                'ea' => 'EastAsia',
                'cs' => 'ComplexScript',
            ] as $source => $target) {
                $sourceElement = $this->firstElement($xpath, 'a:' . $source, $fontElement);
                if (!$sourceElement instanceof \DOMElement) {
                    continue;
                }

                $typeface = trim($sourceElement->getAttribute('typeface'));
                if ($typeface !== '') {
                    $fonts[$prefix . $target] = $typeface;
                }
            }

            $supplemental = $this->themeSupplementalFonts($fontElement);
            if ($supplemental['items'] !== []) {
                $fonts[$prefix . 'SupplementalFontCount'] = count($supplemental['items']);
                $fonts[$prefix . 'SupplementalFonts'] = $supplemental['items'];
                $fonts[$prefix . 'SupplementalFontsByScript'] = $supplemental['byScript'];
                $supplementalFontCount += count($supplemental['items']);
                foreach (array_keys($supplemental['byScript']) as $script) {
                    $supplementalFontScripts[$script] = true;
                }
            }
        }

        if ($supplementalFontCount > 0) {
            $fonts['supplementalFontCount'] = $supplementalFontCount;
            $scripts = array_keys($supplementalFontScripts);
            sort($scripts, SORT_STRING);
            $fonts['supplementalFontScripts'] = $scripts;
        }

        return $fonts;
    }

    /**
     * @return array{items:list<array{script:string, typeface:string}>, byScript:array<string, string>}
     */
    private function themeSupplementalFonts(\DOMElement $fontElement): array
    {
        $items = [];
        $byScript = [];
        foreach ($fontElement->childNodes as $child) {
            if (!$child instanceof \DOMElement || $child->namespaceURI !== self::NS_A || $child->localName !== 'font') {
                continue;
            }

            $script = trim($child->getAttribute('script'));
            $typeface = trim($child->getAttribute('typeface'));
            if ($script === '' || $typeface === '') {
                continue;
            }

            $items[] = [
                'script' => $script,
                'typeface' => $typeface,
            ];
            $byScript[$script] = $typeface;
        }

        return [
            'items' => $items,
            'byScript' => $byScript,
        ];
    }

    /**
     * @return array<string, mixed>
     */
    private function themeColorScheme(\DOMXPath $xpath, \DOMElement $theme): array
    {
        $colorScheme = $this->firstElement($xpath, 'a:themeElements/a:clrScheme', $theme);
        if (!$colorScheme instanceof \DOMElement) {
            return [];
        }

        $items = [];
        $byName = [];
        $transformCount = 0;
        $transformNames = [];
        foreach ($colorScheme->childNodes as $child) {
            if (!$child instanceof \DOMElement || $child->namespaceURI !== self::NS_A) {
                continue;
            }

            $name = $child->localName;
            if (!in_array($name, ['dk1', 'lt1', 'dk2', 'lt2', 'accent1', 'accent2', 'accent3', 'accent4', 'accent5', 'accent6', 'hlink', 'folHlink'], true)) {
                continue;
            }

            $color = $this->themeColorSchemeEntry($child);
            if ($color === null) {
                continue;
            }

            $item = ['name' => $name] + $color;
            if (isset($item['transformCount']) && is_int($item['transformCount'])) {
                $transformCount += $item['transformCount'];
                foreach (($item['transformNames'] ?? []) as $transformName) {
                    if (is_string($transformName)) {
                        $transformNames[$transformName] = true;
                    }
                }
            }
            $items[] = $item;
            if (is_string($item['rgb'] ?? null) && $item['rgb'] !== '') {
                $byName[$name] = $item['rgb'];
                foreach ($this->themeColorAliases($name) as $alias) {
                    $byName[$alias] = $item['rgb'];
                }
            }
        }

        if ($items === []) {
            return [];
        }

        $scheme = [
            'count' => count($items),
            'items' => $items,
            'byName' => $byName,
        ];
        if ($transformCount > 0) {
            $names = array_keys($transformNames);
            sort($names, SORT_STRING);
            $scheme['transformCount'] = $transformCount;
            $scheme['transformNames'] = $names;
        }
        $schemeName = trim($colorScheme->getAttribute('name'));
        if ($schemeName !== '') {
            $scheme = ['schemeName' => $schemeName] + $scheme;
        }

        return $scheme;
    }

    /**
     * @return array<string, mixed>|null
     */
    private function themeColorSchemeEntry(\DOMElement $container): ?array
    {
        foreach ($container->childNodes as $child) {
            if (!$child instanceof \DOMElement || $child->namespaceURI !== self::NS_A) {
                continue;
            }

            if ($child->localName === 'srgbClr') {
                $rgb = $this->normalizedRgb($child->getAttribute('val'));
                if ($rgb === null) {
                    continue;
                }

                return $this->themeColorEntryWithTransforms($child, [
                    'kind' => 'srgb',
                    'value' => $rgb,
                    'rgb' => $rgb,
                ]);
            }

            if ($child->localName === 'sysClr') {
                $value = trim($child->getAttribute('val'));

                return $this->themeColorEntryWithTransforms($child, [
                    'kind' => 'system',
                    'value' => $value !== '' ? $value : null,
                    'rgb' => $this->normalizedRgb($child->getAttribute('lastClr')),
                ]);
            }

            if ($child->localName === 'prstClr') {
                $value = trim($child->getAttribute('val'));
                if ($value === '') {
                    continue;
                }

                return $this->themeColorEntryWithTransforms($child, [
                    'kind' => 'preset',
                    'value' => $value,
                    'rgb' => null,
                ]);
            }

            if ($child->localName === 'schemeClr') {
                $value = trim($child->getAttribute('val'));
                if ($value === '') {
                    continue;
                }

                return $this->themeColorEntryWithTransforms($child, [
                    'kind' => 'scheme',
                    'value' => $value,
                    'rgb' => null,
                ]);
            }
        }

        return null;
    }

    /**
     * @param array<string, mixed> $entry
     * @return array<string, mixed>
     */
    private function themeColorEntryWithTransforms(\DOMElement $color, array $entry): array
    {
        $transforms = $this->themeColorTransforms($color);
        if ($transforms['items'] === []) {
            return $entry;
        }

        $entry['transformCount'] = count($transforms['items']);
        $entry['transforms'] = $transforms['items'];
        $entry['transformNames'] = $transforms['names'];
        $entry['transformValuesByName'] = $transforms['valuesByName'];

        return $entry;
    }

    /**
     * @return array{items:list<array{name:string, value:?string}>, names:list<string>, valuesByName:array<string, string>}
     */
    private function themeColorTransforms(\DOMElement $color): array
    {
        $transformNames = [
            'alpha' => true,
            'alphaMod' => true,
            'alphaOff' => true,
            'blue' => true,
            'blueMod' => true,
            'blueOff' => true,
            'comp' => true,
            'gamma' => true,
            'gray' => true,
            'green' => true,
            'greenMod' => true,
            'greenOff' => true,
            'hue' => true,
            'hueMod' => true,
            'hueOff' => true,
            'inv' => true,
            'invGamma' => true,
            'lum' => true,
            'lumMod' => true,
            'lumOff' => true,
            'red' => true,
            'redMod' => true,
            'redOff' => true,
            'sat' => true,
            'satMod' => true,
            'satOff' => true,
            'shade' => true,
            'tint' => true,
        ];
        $items = [];
        $names = [];
        $valuesByName = [];

        foreach ($color->childNodes as $child) {
            if (!$child instanceof \DOMElement || $child->namespaceURI !== self::NS_A || !isset($transformNames[$child->localName])) {
                continue;
            }

            $value = trim($child->getAttribute('val'));
            $items[] = [
                'name' => $child->localName,
                'value' => $value !== '' ? $value : null,
            ];
            $names[$child->localName] = true;
            if ($value !== '') {
                $valuesByName[$child->localName] = $value;
            }
        }

        $sortedNames = array_keys($names);
        sort($sortedNames, SORT_STRING);

        return [
            'items' => $items,
            'names' => $sortedNames,
            'valuesByName' => $valuesByName,
        ];
    }

    private function normalizedRgb(string $value): ?string
    {
        $value = strtoupper(trim($value));

        return preg_match('/^[0-9A-F]{6}$/D', $value) === 1 ? $value : null;
    }

    /**
     * @return list<string>
     */
    private function themeColorAliases(string $name): array
    {
        return match ($name) {
            'dk1' => ['dark1', 'text1'],
            'lt1' => ['light1', 'background1'],
            'dk2' => ['dark2', 'text2'],
            'lt2' => ['light2', 'background2'],
            'hlink' => ['hyperlink'],
            'folHlink' => ['followedHyperlink', 'followed-hyperlink'],
            default => [],
        };
    }

    /**
     * @param array<string, string> $parts
     * @param array<string, array{id:string, type:string, target:string, targetMode:string, resolvedTarget:string}> $relationships
     * @param array{defaults:array<string, string>, overrides:array<string, string>} $contentTypes
     * @param array<string, array{id:string, name:string, headingLevel:int|null}> $styles
     * @param array<string, array{abstractNumId:string, levels:array<int, array{format:string, text:string, start:int}>}> $numbering
     * @param array<string, array<string, AstNode>> $referencedNotes
     * @return array<string, mixed>
     */
    private function readGlossaryDocument(
        array $parts,
        string $xml,
        string $partName,
        bool $exists,
        string $relationshipsPart,
        array $relationships,
        array $contentTypes,
        array $styles,
        array $numbering,
        array $referencedNotes
    ): array {
        $relationshipDiagnostics = $this->relatedPartRelationshipDiagnostics(
            $parts,
            $relationships,
            $partName,
            $relationshipsPart,
            $contentTypes,
        );
        $relationshipReview = $this->glossaryDocumentRelationshipReview([], $relationshipDiagnostics);
        $summary = [
            'partName' => $partName,
            'exists' => $exists,
            'relationshipsPart' => $relationshipsPart,
            'validXml' => null,
            'xmlParseError' => null,
            'validRoot' => null,
            'rootNamespace' => null,
            'rootLocalName' => null,
            'invalidXmlCount' => 0,
            'invalidRootCount' => 0,
            'count' => 0,
            'bodyBlockCount' => 0,
            'names' => [],
            'galleries' => [],
            'categories' => [],
            'types' => [],
            'behaviors' => [],
            'relationshipIds' => [],
            'byName' => [],
            'items' => [],
            'issueCount' => 0,
            'issueCodes' => [],
            'reviewPolicy' => 'glossary-document-metadata-only',
        ];
        foreach ($relationshipReview as $key => $value) {
            if ($key !== 'items' && $key !== 'byName') {
                $summary[$key] = $value;
            }
        }

        if (!$exists || $xml === '') {
            return $summary;
        }

        $dom = $this->loadXmlForProvenance($xml, $partName);
        if (!$dom instanceof \DOMDocument) {
            $summary['validXml'] = false;
            $summary['validRoot'] = false;
            $summary['xmlParseError'] = $this->lastXmlPreflightError($xml, $partName);
            $summary['invalidXmlCount'] = 1;
            $summary['invalidRootCount'] = 1;
            $summary['issueCount'] = 1;
            $summary['issueCodes'] = ['invalid-xml'];

            return $summary;
        }

        $root = $dom->documentElement;
        $summary['validXml'] = $root instanceof \DOMElement;
        $summary['rootNamespace'] = $root instanceof \DOMElement ? $root->namespaceURI : null;
        $summary['rootLocalName'] = $root instanceof \DOMElement ? $root->localName : null;
        $summary['validRoot'] = $root instanceof \DOMElement
            && $root->namespaceURI === self::NS_W
            && $root->localName === 'glossaryDocument';

        if ($summary['validRoot'] !== true) {
            $summary['invalidRootCount'] = 1;
            $summary['issueCount'] = 1;
            $summary['issueCodes'] = ['unexpected-root'];

            return $summary;
        }

        $xpath = $this->xpath($dom);
        $issueCodes = [];
        foreach ($this->elements($xpath, '/w:glossaryDocument/w:docParts/w:docPart') as $docPart) {
            $item = $this->glossaryDocPartItem(
                $docPart,
                $xpath,
                $relationships,
                $contentTypes,
                $styles,
                $numbering,
                $referencedNotes,
                count($summary['items']),
            );
            $summary['items'][] = $item;
            $summary['bodyBlockCount'] += $item['bodyBlockCount'];

            $this->appendUniqueString($summary['names'], $item['name']);
            $this->appendUniqueString($summary['galleries'], $item['gallery']);
            $this->appendUniqueString($summary['categories'], $item['category']);
            foreach ($item['types'] as $type) {
                $this->appendUniqueString($summary['types'], $type);
            }
            foreach ($item['behaviors'] as $behavior) {
                $this->appendUniqueString($summary['behaviors'], $behavior);
            }
            foreach ($item['relationshipIds'] as $relationshipId) {
                $this->appendUniqueString($summary['relationshipIds'], $relationshipId);
            }
            foreach ($item['issues'] as $issue) {
                $issueCodes[$issue] = true;
            }
        }

        $relationshipReview = $this->glossaryDocumentRelationshipReview($summary['items'], $relationshipDiagnostics);
        $summary['items'] = $relationshipReview['items'];
        $summary['byName'] = $relationshipReview['byName'];
        foreach ($relationshipReview as $key => $value) {
            if ($key !== 'items' && $key !== 'byName') {
                $summary[$key] = $value;
            }
        }
        ksort($issueCodes, SORT_STRING);
        $summary['count'] = count($summary['items']);
        $summary['issueCount'] = count(array_filter($summary['items'], static fn (array $item): bool => $item['issues'] !== []));
        $summary['issueCodes'] = array_keys($issueCodes);

        return $summary;
    }

    /**
     * @param list<array<string, mixed>> $items
     * @param array<string, mixed> $relationshipDiagnostics
     * @return array<string, mixed>
     */
    private function glossaryDocumentRelationshipReview(array $items, array $relationshipDiagnostics): array
    {
        $relationships = is_array($relationshipDiagnostics['byId'] ?? null) ? $relationshipDiagnostics['byId'] : [];
        $allRelationshipIds = is_array($relationshipDiagnostics['relationshipIds'] ?? null)
            ? array_values(array_filter(
                array_map('strval', $relationshipDiagnostics['relationshipIds']),
                static fn (string $value): bool => $value !== '',
            ))
            : [];
        sort($allRelationshipIds, SORT_STRING);
        $relationshipRecords = is_array($relationshipDiagnostics['relationshipRecords'] ?? null)
            ? $relationshipDiagnostics['relationshipRecords']
            : [];
        $relationshipRecordsById = [];
        foreach ($relationshipRecords as $record) {
            if (!is_array($record)) {
                continue;
            }

            $recordId = is_string($record['id'] ?? null) ? $record['id'] : '';
            if ($recordId === '') {
                continue;
            }

            $relationshipRecordsById[$recordId][] = $record;
        }

        $duplicateRelationshipIds = is_array($relationshipDiagnostics['duplicateRelationshipIds'] ?? null)
            ? array_values(array_filter(
                array_map('strval', $relationshipDiagnostics['duplicateRelationshipIds']),
                static fn (string $value): bool => $value !== '',
            ))
            : [];
        $duplicateRelationshipIdSet = array_fill_keys($duplicateRelationshipIds, true);
        $relationshipBacklinks = [];
        $referencedRelationshipIds = [];
        $knownReferencedRelationshipIds = [];
        $missingReferencedRelationshipIds = [];
        $reconciledItems = [];
        $reconciledByName = [];

        foreach ($items as $itemIndex => $item) {
            $relationshipIds = is_array($item['relationshipIds'] ?? null) ? $item['relationshipIds'] : [];
            $knownRelationshipIds = [];
            $itemDuplicateRelationshipIds = [];
            $itemReferencedRelationships = [];
            $itemReferencedRelationshipItems = [];
            $itemReferencedRelationshipRecords = [];
            $itemRelationshipBacklinks = [];
            $itemRelationshipIssueCodes = [];

            foreach ($relationshipIds as $relationshipId) {
                if (!is_string($relationshipId) || $relationshipId === '') {
                    continue;
                }

                $itemName = is_string($item['name'] ?? null) ? $item['name'] : null;
                $backlink = [
                    'relationshipId' => $relationshipId,
                    'itemIndex' => $itemIndex,
                    'itemName' => $itemName,
                    'known' => isset($relationships[$relationshipId]),
                ];
                $this->appendUniqueString($referencedRelationshipIds, $relationshipId);
                if (isset($relationships[$relationshipId])) {
                    $this->appendUniqueString($knownRelationshipIds, $relationshipId);
                    $this->appendUniqueString($knownReferencedRelationshipIds, $relationshipId);
                    $itemReferencedRelationships[$relationshipId] = $relationships[$relationshipId];
                    $itemReferencedRelationshipItems[] = $relationships[$relationshipId];
                    foreach (($relationships[$relationshipId]['issues'] ?? []) as $issue) {
                        if (is_string($issue) && $issue !== '') {
                            $itemRelationshipIssueCodes[$issue] = true;
                        }
                    }
                } else {
                    $this->appendUniqueString($missingReferencedRelationshipIds, $relationshipId);
                    $itemRelationshipIssueCodes['missing-relationship'] = true;
                }
                if (isset($duplicateRelationshipIdSet[$relationshipId])) {
                    $this->appendUniqueString($itemDuplicateRelationshipIds, $relationshipId);
                }
                foreach ($relationshipRecordsById[$relationshipId] ?? [] as $record) {
                    $itemReferencedRelationshipRecords[] = $record;
                }

                $relationshipBacklinks[$relationshipId] ??= [];
                $relationshipBacklinks[$relationshipId][] = $backlink;
                $itemRelationshipBacklinks[] = $backlink;
            }

            ksort($itemRelationshipIssueCodes, SORT_STRING);
            $item['knownRelationshipIds'] = $knownRelationshipIds;
            $item['knownRelationshipCount'] = count($knownRelationshipIds);
            $item['referencedRelationshipIds'] = $knownRelationshipIds;
            $item['referencedRelationshipCount'] = count($knownRelationshipIds);
            $item['missingRelationshipIds'] = $this->missingRelationshipIds($relationshipIds, $relationships);
            $item['missingRelationshipCount'] = count($item['missingRelationshipIds']);
            $item['referencedDuplicateRelationshipIds'] = $itemDuplicateRelationshipIds;
            $item['duplicateRelationshipIds'] = $itemDuplicateRelationshipIds;
            $item['duplicateRelationshipCount'] = count($itemDuplicateRelationshipIds);
            $item['referencedRelationships'] = $itemReferencedRelationships;
            $item['referencedRelationshipItems'] = $itemReferencedRelationshipItems;
            $item['referencedRelationshipRecordCount'] = count($itemReferencedRelationshipRecords);
            $item['referencedRelationshipRecords'] = $itemReferencedRelationshipRecords;
            $item['relationshipIssueCount'] = count($itemRelationshipIssueCodes);
            $item['relationshipIssueCodes'] = array_keys($itemRelationshipIssueCodes);
            $item['relationshipBacklinks'] = $itemRelationshipBacklinks;

            $reconciledItems[] = $item;
            if (is_string($item['name'] ?? null) && $item['name'] !== '' && !isset($reconciledByName[$item['name']])) {
                $reconciledByName[$item['name']] = $item;
            }
        }

        $unreferencedRelationshipIds = [];
        foreach (($relationshipDiagnostics['relationshipIds'] ?? []) as $relationshipId) {
            if (!is_string($relationshipId) || $relationshipId === '') {
                continue;
            }

            $referenced = in_array($relationshipId, $referencedRelationshipIds, true);
            if (!$referenced) {
                $unreferencedRelationshipIds[] = $relationshipId;
            }

            if (isset($relationships[$relationshipId])) {
                $relationships[$relationshipId]['referenced'] = $referenced;
                $relationships[$relationshipId]['orphaned'] = !$referenced;
                $relationships[$relationshipId]['referencedItemNames'] = array_values(array_filter(array_unique(array_map(
                    static fn (array $backlink): string => is_string($backlink['itemName'] ?? null) ? $backlink['itemName'] : '',
                    $relationshipBacklinks[$relationshipId] ?? [],
                )), static fn (string $value): bool => $value !== ''));
                $relationships[$relationshipId]['referencedItemIndexes'] = array_values(array_unique(array_map(
                    static fn (array $backlink): int => (int) ($backlink['itemIndex'] ?? 0),
                    $relationshipBacklinks[$relationshipId] ?? [],
                )));
                $relationships[$relationshipId]['referencedItemCount'] = count($relationships[$relationshipId]['referencedItemNames']);
                $relationships[$relationshipId]['referenceBacklinks'] = $relationshipBacklinks[$relationshipId] ?? [];
            }
        }

        $relationshipDiagnostics['referencedRelationshipIds'] = $referencedRelationshipIds;
        $relationshipDiagnostics['knownReferencedRelationshipIds'] = $knownReferencedRelationshipIds;
        $relationshipDiagnostics['unreferencedRelationshipIds'] = $unreferencedRelationshipIds;
        $relationshipDiagnostics['orphanedRelationshipIds'] = $unreferencedRelationshipIds;
        $relationshipDiagnostics['missingReferencedRelationshipIds'] = $missingReferencedRelationshipIds;
        $relationshipDiagnostics['relationshipBacklinks'] = $relationshipBacklinks;
        $relationshipDiagnostics['byId'] = $relationships;
        $relationshipDiagnostics['items'] = array_values($relationships);

        return [
            'items' => $reconciledItems,
            'byName' => $reconciledByName,
            'relationshipsPart' => $relationshipDiagnostics['relationshipsPart'],
            'relationshipCount' => $relationshipDiagnostics['relationshipCount'],
            'relationshipRecordCount' => $relationshipDiagnostics['relationshipRecordCount'],
            'duplicateRelationshipIdCount' => $relationshipDiagnostics['duplicateRelationshipIdCount'],
            'duplicateRelationshipRecordCount' => $relationshipDiagnostics['duplicateRelationshipRecordCount'],
            'duplicateRelationshipIds' => $relationshipDiagnostics['duplicateRelationshipIds'],
            'duplicateRelationshipIdItems' => $relationshipDiagnostics['duplicateRelationshipIdItems'],
            'invalidRelationshipRecordCount' => $relationshipDiagnostics['invalidRelationshipRecordCount'],
            'relationshipRecordIssueCount' => $relationshipDiagnostics['relationshipRecordIssueCount'],
            'relationshipRecordIssueCodes' => $relationshipDiagnostics['relationshipRecordIssueCodes'],
            'invalidRelationshipRecords' => $relationshipDiagnostics['invalidRelationshipRecords'],
            'internalRelationshipCount' => $relationshipDiagnostics['internalRelationshipCount'],
            'externalRelationshipCount' => $relationshipDiagnostics['externalRelationshipCount'],
            'existingRelationshipTargetCount' => $relationshipDiagnostics['existingTargetCount'],
            'missingRelationshipTargetCount' => $relationshipDiagnostics['missingTargetCount'],
            'missingRelationshipContentTypeCount' => $relationshipDiagnostics['missingContentTypeCount'],
            'relationshipTargetReferenceSuffixCount' => $relationshipDiagnostics['targetReferenceSuffixCount'],
            'relationshipIds' => $allRelationshipIds,
            'referencedRelationshipIds' => $referencedRelationshipIds,
            'knownReferencedRelationshipIds' => $knownReferencedRelationshipIds,
            'unreferencedRelationshipIds' => $unreferencedRelationshipIds,
            'orphanedRelationshipIds' => $unreferencedRelationshipIds,
            'missingReferencedRelationshipIds' => $missingReferencedRelationshipIds,
            'referencedRelationshipCount' => count($referencedRelationshipIds),
            'knownReferencedRelationshipCount' => count($knownReferencedRelationshipIds),
            'unreferencedRelationshipCount' => count($unreferencedRelationshipIds),
            'orphanedRelationshipCount' => count($unreferencedRelationshipIds),
            'missingReferencedRelationshipCount' => count($missingReferencedRelationshipIds),
            'relationshipTargetParts' => $relationshipDiagnostics['targetParts'],
            'relationshipExternalTargets' => $relationshipDiagnostics['externalTargets'],
            'relationshipTargetReferenceSuffixes' => $relationshipDiagnostics['targetReferenceSuffixes'],
            'relationshipIssueCount' => $relationshipDiagnostics['issueCount'],
            'relationshipIssueCodes' => $relationshipDiagnostics['issueCodes'],
            'relationshipRecords' => $relationshipRecords,
            'relationshipBacklinks' => $relationshipBacklinks,
            'relationships' => $relationships,
            'relationshipDiagnostics' => $relationshipDiagnostics,
        ];
    }

    /**
     * @param array<string, array{id:string, type:string, target:string, targetMode:string, resolvedTarget:string}> $relationships
     * @param array{defaults:array<string, string>, overrides:array<string, string>} $contentTypes
     * @param array<string, array{id:string, name:string, headingLevel:int|null}> $styles
     * @param array<string, array{abstractNumId:string, levels:array<int, array{format:string, text:string, start:int}>}> $numbering
     * @param array<string, array<string, AstNode>> $referencedNotes
     * @return array<string, mixed>
     */
    private function glossaryDocPartItem(
        \DOMElement $docPart,
        \DOMXPath $xpath,
        array $relationships,
        array $contentTypes,
        array $styles,
        array $numbering,
        array $referencedNotes,
        int $index
    ): array {
        $properties = $this->childElement($docPart, 'docPartPr');
        $body = $this->childElement($docPart, 'docPartBody');
        $types = $this->glossaryDocPartValues($xpath, 'w:types/w:type', $properties);
        $behaviors = $this->glossaryDocPartValues($xpath, 'w:behaviors/w:behavior', $properties);
        $blocks = $body instanceof \DOMElement
            ? $this->readWordBlockChildren($body->childNodes, $xpath, $relationships, $contentTypes, $styles, $numbering, $referencedNotes)
            : [];
        $relationshipIds = $body instanceof \DOMElement ? $this->relationshipIdsInElement($body) : [];
        $issues = [];
        if (!$body instanceof \DOMElement) {
            $issues[] = 'missing-body';
        }

        return [
            'index' => $index,
            'sourceType' => 'glossaryDocument',
            'name' => $this->glossaryDocPartValue('name', $properties),
            'styleId' => $this->glossaryDocPartValue('style', $properties),
            'category' => $this->glossaryDocPartNestedValue('category', 'name', $properties),
            'gallery' => $this->glossaryDocPartNestedValue('category', 'gallery', $properties),
            'description' => $this->glossaryDocPartValue('description', $properties),
            'guid' => $this->glossaryDocPartValue('guid', $properties),
            'types' => $types,
            'behaviors' => $behaviors,
            'relationshipCount' => count($relationshipIds),
            'relationshipIds' => $relationshipIds,
            'bodyBlockCount' => count($blocks),
            'text' => $this->plainBlockText($blocks),
            'issues' => $issues,
        ];
    }

    private function glossaryDocPartValue(string $childLocalName, ?\DOMElement $properties): ?string
    {
        if (!$properties instanceof \DOMElement) {
            return null;
        }

        return $this->emptyStringToNull($this->childAttr($properties, $childLocalName, 'val'));
    }

    private function glossaryDocPartNestedValue(string $parentLocalName, string $childLocalName, ?\DOMElement $properties): ?string
    {
        $parent = $this->childElement($properties, $parentLocalName);
        if (!$parent instanceof \DOMElement) {
            return null;
        }

        return $this->glossaryDocPartValue($childLocalName, $parent);
    }

    /**
     * @return list<string>
     */
    private function glossaryDocPartValues(\DOMXPath $xpath, string $query, ?\DOMElement $properties): array
    {
        if (!$properties instanceof \DOMElement) {
            return [];
        }

        $values = [];
        foreach ($this->elements($xpath, $query, $properties) as $element) {
            $this->appendUniqueString($values, $this->emptyStringToNull($element->getAttributeNS(self::NS_W, 'val')));
        }

        return $values;
    }

    /**
     * @param array<string, array{id:string, type:string, target:string, targetMode:string, resolvedTarget:string}> $relationships
     * @param array{defaults:array<string, string>, overrides:array<string, string>} $contentTypes
     * @param array<string, array{id:string, name:string, headingLevel:int|null}> $styles
     * @param array<string, array{abstractNumId:string, levels:array<int, array{format:string, text:string, start:int}>}> $numbering
     * @return array{summary:array{count:int, ids:list<string>, byId:array<string, array{id:string, sourceType:string, type:string, blockCount:int, text:string}>, items:list<array{id:string, sourceType:string, type:string, blockCount:int, text:string}>}, nodes:array<string, AstNode>}
     */
    private function readNotes(
        array $parts,
        string $xml,
        string $partName,
        string $relationshipsPart,
        string $rootName,
        string $itemName,
        string $sourceType,
        array $relationships,
        array $contentTypes,
        array $styles,
        array $numbering
    ): array {
        $relationshipDiagnostics = $this->relatedPartRelationshipDiagnostics(
            $parts,
            $relationships,
            $partName,
            $relationshipsPart,
            $contentTypes,
        );
        $xmlProvenance = [
            'validXml' => null,
            'xmlParseError' => null,
            'validRoot' => null,
            'rootNamespace' => null,
            'rootLocalName' => null,
            'invalidXmlCount' => 0,
            'invalidRootCount' => 0,
            'issueCount' => 0,
            'issueCodes' => [],
        ];
        if ($xml === '') {
            return [
                'summary' => $this->noteCollectionSummary([], [], $relationshipDiagnostics, $xmlProvenance),
                'nodes' => [],
            ];
        }

        $dom = $this->loadXmlForProvenance($xml, $partName);
        if (!$dom instanceof \DOMDocument || !$dom->documentElement instanceof \DOMElement) {
            $xmlProvenance['validXml'] = false;
            $xmlProvenance['xmlParseError'] = $this->lastXmlPreflightError($xml, $partName);
            $xmlProvenance['validRoot'] = false;
            $xmlProvenance['invalidXmlCount'] = 1;
            $xmlProvenance['invalidRootCount'] = 1;
            $xmlProvenance['issueCount'] = 1;
            $xmlProvenance['issueCodes'] = ['invalid-' . $rootName . '-xml'];

            return [
                'summary' => $this->noteCollectionSummary([], [], $relationshipDiagnostics, $xmlProvenance),
                'nodes' => [],
            ];
        }

        $root = $dom->documentElement;
        $xmlProvenance['validXml'] = true;
        $xmlProvenance['rootNamespace'] = $root->namespaceURI;
        $xmlProvenance['rootLocalName'] = $root->localName;
        $xmlProvenance['validRoot'] = $root->namespaceURI === self::NS_W && $root->localName === $rootName;
        if ($xmlProvenance['validRoot'] !== true) {
            $xmlProvenance['invalidRootCount'] = 1;
            $xmlProvenance['issueCount'] = 1;
            $xmlProvenance['issueCodes'] = ['unexpected-' . $rootName . '-root'];

            return [
                'summary' => $this->noteCollectionSummary([], [], $relationshipDiagnostics, $xmlProvenance),
                'nodes' => [],
            ];
        }

        $xpath = $this->xpath($dom);
        $items = [];
        $byId = [];
        $nodes = [];
        foreach ($root->childNodes as $note) {
            if (!$note instanceof \DOMElement || $note->namespaceURI !== self::NS_W || $note->localName !== $itemName) {
                continue;
            }

            $id = $note->getAttributeNS(self::NS_W, 'id');
            $type = strtolower($note->getAttributeNS(self::NS_W, 'type'));
            if ($id === '' || str_starts_with($id, '-') || in_array($type, ['separator', 'continuationseparator', 'continuationnotice'], true)) {
                continue;
            }

            $blocks = $this->readNoteBlocks($note, $xpath, $relationships, $contentTypes, $styles, $numbering);
            $relationshipIds = $this->relationshipIdsInElement($note);
            $item = [
                'id' => $id,
                'sourceType' => $sourceType,
                'type' => $type === '' ? 'normal' : $type,
                'blockCount' => count($blocks),
                'text' => $this->plainBlockText($blocks),
                'relationshipCount' => count($relationshipIds),
                'relationshipIds' => $relationshipIds,
                'missingRelationshipIds' => $this->missingRelationshipIds($relationshipIds, $relationships),
            ];
            $items[] = $item;
            $byId[$id] = $item;
            $nodes[$id] = new AstNode('note', [
                'id' => $id,
                'sourceType' => $sourceType,
            ], $blocks);
        }

        return [
            'summary' => $this->noteCollectionSummary($items, $byId, $relationshipDiagnostics, $xmlProvenance),
            'nodes' => $nodes,
        ];
    }

    /**
     * @param array{id:string, type:string, target:string, targetMode:string, resolvedTarget:string}|null $relationship
     * @param array{defaults:array<string, string>, overrides:array<string, string>} $contentTypes
     * @return array<string, mixed>
     */
    private function readPeoplePart(
        string $xml,
        string $partName,
        bool $exists,
        ?array $relationship,
        array $contentTypes
    ): array {
        $contentTypeResolution = $this->contentTypeResolutionForPart($partName, $contentTypes);
        $items = [];
        $byAuthor = [];
        $authors = [];
        $providerIds = [];
        $userIds = [];
        $presenceInfoCount = 0;
        $issues = [];
        $validXml = null;
        $xmlParseError = null;
        $rootNamespace = null;
        $rootLocalName = null;
        $validRoot = null;

        if ($relationship !== null && !$exists) {
            $issues[] = 'missing-people-part';
        }
        if ($exists) {
            if (($contentTypeResolution['contentTypeSource'] ?? '') === 'missing') {
                $issues[] = 'missing-people-content-type';
            } elseif (($contentTypeResolution['contentTypeBase'] ?? '') !== self::CT_WORD_PEOPLE) {
                $issues[] = 'unexpected-people-content-type';
            }

            $dom = $this->loadXmlForProvenance($xml, $partName);
            if (!$dom instanceof \DOMDocument || !$dom->documentElement instanceof \DOMElement) {
                $validXml = false;
                $xmlParseError = $this->lastXmlPreflightError($xml, $partName);
                $validRoot = false;
                $issues[] = 'invalid-people-xml';
            } else {
                $root = $dom->documentElement;
                $validXml = true;
                $rootNamespace = $root->namespaceURI;
                $rootLocalName = $root->localName;
                $validRoot = $rootNamespace === self::NS_W15 && $rootLocalName === 'people';
                if (!$validRoot) {
                    $issues[] = 'unexpected-people-root';
                } else {
                    foreach ($root->childNodes as $person) {
                        if (!$person instanceof \DOMElement || $person->namespaceURI !== self::NS_W15 || $person->localName !== 'person') {
                            continue;
                        }

                        $author = $this->emptyStringToNull($person->getAttributeNS(self::NS_W15, 'author'));
                        if ($author !== null) {
                            $author = $this->boundedMetadataString($author);
                            $this->appendUniqueString($authors, $author);
                        }

                        $presenceInfo = [];
                        foreach ($person->childNodes as $presence) {
                            if (!$presence instanceof \DOMElement || $presence->namespaceURI !== self::NS_W15 || $presence->localName !== 'presenceInfo') {
                                continue;
                            }

                            ++$presenceInfoCount;
                            $providerId = $this->emptyStringToNull($presence->getAttributeNS(self::NS_W15, 'providerId'));
                            $userId = $this->emptyStringToNull($presence->getAttributeNS(self::NS_W15, 'userId'));
                            if ($providerId !== null) {
                                $providerId = $this->boundedMetadataString($providerId);
                                $this->appendUniqueString($providerIds, $providerId);
                            }
                            if ($userId !== null) {
                                $userId = $this->boundedMetadataString($userId);
                                $this->appendUniqueString($userIds, $userId);
                            }

                            $presenceInfo[] = [
                                'providerId' => $providerId,
                                'userId' => $userId,
                            ];
                        }

                        $item = [
                            'index' => count($items),
                            'author' => $author,
                            'presenceInfoCount' => count($presenceInfo),
                            'presenceInfo' => $presenceInfo,
                        ];
                        $items[] = $item;
                        if ($author !== null && !isset($byAuthor[$author])) {
                            $byAuthor[$author] = $item;
                        }
                    }
                }
            }
        }

        $issueCodes = array_values(array_unique($issues));
        sort($issueCodes, SORT_STRING);

        return [
            'partName' => $partName,
            'exists' => $exists,
            'relationshipId' => $relationship['id'] ?? null,
            'byteLength' => $exists ? strlen($xml) : null,
            'crc32' => $exists ? sprintf('%08x', crc32($xml)) : null,
            'sha256' => $exists ? hash('sha256', $xml) : null,
            'validXml' => $validXml,
            'xmlParseError' => $xmlParseError,
            'rootNamespace' => $rootNamespace,
            'rootLocalName' => $rootLocalName,
            'validRoot' => $validRoot,
            'contentType' => $contentTypeResolution['contentType'],
            'contentTypeBase' => $contentTypeResolution['contentTypeBase'],
            'contentTypeHasParameters' => $contentTypeResolution['contentTypeHasParameters'],
            'contentTypeParameterCount' => $contentTypeResolution['contentTypeParameterCount'],
            'contentTypeParameters' => $contentTypeResolution['contentTypeParameters'],
            'contentTypeParameterMap' => $contentTypeResolution['contentTypeParameterMap'],
            'contentTypeSource' => $contentTypeResolution['contentTypeSource'],
            'defaultExtension' => $contentTypeResolution['defaultExtension'],
            'overridePartName' => $contentTypeResolution['overridePartName'],
            'expectedContentTypeBase' => self::CT_WORD_PEOPLE,
            'contentTypeMatchesExpected' => ($contentTypeResolution['contentTypeBase'] ?? '') === self::CT_WORD_PEOPLE,
            'count' => count($items),
            'presenceInfoCount' => $presenceInfoCount,
            'authorCount' => count($authors),
            'authors' => $authors,
            'providerIdCount' => count($providerIds),
            'providerIds' => $providerIds,
            'userIdCount' => count($userIds),
            'userIds' => $userIds,
            'byAuthor' => $byAuthor,
            'items' => $items,
            'byteExposurePolicy' => 'people-part-bytes-blocked',
            'reviewPolicy' => 'people-part-metadata-only',
            'issueCount' => count($issueCodes),
            'issueCodes' => $issueCodes,
            'issues' => $issueCodes,
        ];
    }

    /**
     * @return array{summary:array<string, mixed>, byParaId:array<string, array{paraId:string, parentParaId:?string, resolved:?bool, partName:string}>}
     */
    private function readCommentsExtended(string $xml, string $partName): array
    {
        $empty = [
            'count' => 0,
            'resolvedCount' => 0,
            'threadedCount' => 0,
            'paraIds' => [],
            'byParaId' => [],
            'items' => [],
            'validXml' => null,
            'xmlParseError' => null,
            'rootNamespace' => null,
            'rootLocalName' => null,
            'validRoot' => null,
            'invalidXmlCount' => 0,
            'issueCount' => 0,
            'issueCodes' => [],
        ];
        if ($xml === '') {
            return [
                'summary' => $empty,
                'byParaId' => [],
            ];
        }

        $dom = $this->loadXmlForProvenance($xml, $partName);
        if (!$dom instanceof \DOMDocument) {
            return [
                'summary' => [
                    ...$empty,
                    'validXml' => false,
                    'xmlParseError' => $this->lastXmlPreflightError($xml, $partName),
                    'validRoot' => false,
                    'invalidXmlCount' => 1,
                    'issueCount' => 1,
                    'issueCodes' => ['invalid-comments-extended-xml'],
                ],
                'byParaId' => [],
            ];
        }

        $root = $dom->documentElement;
        if (!$root instanceof \DOMElement || $root->namespaceURI !== self::NS_W15 || $root->localName !== 'commentsEx') {
            return [
                'summary' => [
                    ...$empty,
                    'validXml' => $root instanceof \DOMElement,
                    'rootNamespace' => $root instanceof \DOMElement ? $root->namespaceURI : null,
                    'rootLocalName' => $root instanceof \DOMElement ? $root->localName : null,
                    'validRoot' => false,
                    'issueCount' => 1,
                    'issueCodes' => ['unexpected-comments-extended-root'],
                ],
                'byParaId' => [],
            ];
        }

        $items = [];
        $byParaId = [];
        foreach ($root->childNodes as $comment) {
            if (!$comment instanceof \DOMElement || $comment->namespaceURI !== self::NS_W15 || $comment->localName !== 'commentEx') {
                continue;
            }

            $paraId = $this->wordExtensionAttr($comment, 'paraId');
            if ($paraId === null || $paraId === '') {
                continue;
            }

            $parentParaId = $this->wordExtensionAttr($comment, 'paraIdParent');
            if ($parentParaId === '') {
                $parentParaId = null;
            }
            $resolved = $this->onOffStringValue($this->wordExtensionAttr($comment, 'done'));
            $item = [
                'paraId' => $paraId,
                'parentParaId' => $parentParaId,
                'resolved' => $resolved,
                'partName' => $partName,
            ];
            $items[] = $item;
            $byParaId[$paraId] = $item;
        }

        return [
            'summary' => [
                'count' => count($items),
                'resolvedCount' => count(array_filter($items, static fn (array $item): bool => $item['resolved'] === true)),
                'threadedCount' => count(array_filter($items, static fn (array $item): bool => is_string($item['parentParaId']) && $item['parentParaId'] !== '')),
                'paraIds' => array_column($items, 'paraId'),
                'byParaId' => $byParaId,
                'items' => $items,
                'validXml' => true,
                'xmlParseError' => null,
                'rootNamespace' => $root->namespaceURI,
                'rootLocalName' => $root->localName,
                'validRoot' => true,
                'invalidXmlCount' => 0,
                'issueCount' => 0,
                'issueCodes' => [],
            ],
            'byParaId' => $byParaId,
        ];
    }

    /**
     * @return array{summary:array<string, mixed>, byParaId:array<string, array<string, mixed>>}
     */
    private function readCommentsIds(string $xml, string $partName): array
    {
        $empty = [
            'count' => 0,
            'missingParaIdCount' => 0,
            'missingDurableIdCount' => 0,
            'duplicateParaIdCount' => 0,
            'duplicateParaIds' => [],
            'paraIds' => [],
            'durableIds' => [],
            'byParaId' => [],
            'items' => [],
            'validXml' => null,
            'xmlParseError' => null,
            'rootNamespace' => null,
            'rootLocalName' => null,
            'validRoot' => null,
            'invalidXmlCount' => 0,
            'issueCount' => 0,
            'issueCodes' => [],
        ];
        if ($xml === '') {
            return [
                'summary' => $empty,
                'byParaId' => [],
            ];
        }

        $dom = $this->loadXmlForProvenance($xml, $partName);
        if (!$dom instanceof \DOMDocument) {
            return [
                'summary' => [
                    ...$empty,
                    'validXml' => false,
                    'xmlParseError' => $this->lastXmlPreflightError($xml, $partName),
                    'validRoot' => false,
                    'invalidXmlCount' => 1,
                    'issueCount' => 1,
                    'issueCodes' => ['invalid-comments-ids-xml'],
                ],
                'byParaId' => [],
            ];
        }

        $root = $dom->documentElement;
        if (!$root instanceof \DOMElement || $root->namespaceURI !== self::NS_W16CID || $root->localName !== 'commentsIds') {
            return [
                'summary' => [
                    ...$empty,
                    'validXml' => $root instanceof \DOMElement,
                    'rootNamespace' => $root instanceof \DOMElement ? $root->namespaceURI : null,
                    'rootLocalName' => $root instanceof \DOMElement ? $root->localName : null,
                    'validRoot' => false,
                    'issueCount' => 1,
                    'issueCodes' => ['unexpected-comments-ids-root'],
                ],
                'byParaId' => [],
            ];
        }

        $items = [];
        $byParaId = [];
        $paraIds = [];
        $durableIds = [];
        $paraIdCounts = [];
        $duplicateParaIds = [];
        $missingParaIdCount = 0;
        $missingDurableIdCount = 0;
        $issueCount = 0;
        $issueCodes = [];

        foreach ($root->childNodes as $commentId) {
            if (!$commentId instanceof \DOMElement || $commentId->namespaceURI !== self::NS_W16CID || $commentId->localName !== 'commentId') {
                continue;
            }

            $paraId = $this->emptyStringToNull($commentId->getAttributeNS(self::NS_W16CID, 'paraId'));
            $durableId = $this->emptyStringToNull($commentId->getAttributeNS(self::NS_W16CID, 'durableId'));
            $issues = [];
            if ($paraId === null) {
                $issues[] = 'missing-para-id';
                $missingParaIdCount++;
            } else {
                $this->appendUniqueString($paraIds, $paraId);
                $paraIdCounts[$paraId] = ($paraIdCounts[$paraId] ?? 0) + 1;
                if ($paraIdCounts[$paraId] === 2) {
                    $duplicateParaIds[] = $paraId;
                }
            }
            if ($durableId === null) {
                $issues[] = 'missing-durable-id';
                $missingDurableIdCount++;
            } else {
                $this->appendUniqueString($durableIds, $durableId);
            }
            foreach ($issues as $issue) {
                $this->appendUniqueString($issueCodes, $issue);
            }
            $issueCount += count($issues);

            $item = [
                'paraId' => $paraId,
                'durableId' => $durableId,
                'partName' => $partName,
                'issues' => $issues,
            ];
            $items[] = $item;
            if ($paraId !== null) {
                $byParaId[$paraId] = $item;
            }
        }

        return [
            'summary' => [
                'count' => count($items),
                'missingParaIdCount' => $missingParaIdCount,
                'missingDurableIdCount' => $missingDurableIdCount,
                'duplicateParaIdCount' => count($duplicateParaIds),
                'duplicateParaIds' => $duplicateParaIds,
                'paraIds' => $paraIds,
                'durableIds' => $durableIds,
                'byParaId' => $byParaId,
                'items' => $items,
                'validXml' => true,
                'xmlParseError' => null,
                'rootNamespace' => $root->namespaceURI,
                'rootLocalName' => $root->localName,
                'validRoot' => true,
                'invalidXmlCount' => 0,
                'issueCount' => $issueCount,
                'issueCodes' => $issueCodes,
            ],
            'byParaId' => $byParaId,
        ];
    }

    /**
     * @param array<string, array{id:string, type:string, target:string, targetMode:string, resolvedTarget:string}> $relationships
     * @param array{defaults:array<string, string>, overrides:array<string, string>} $contentTypes
     * @param array<string, array{id:string, name:string, headingLevel:int|null}> $styles
     * @param array<string, array{abstractNumId:string, levels:array<int, array{format:string, text:string, start:int}>}> $numbering
     * @param array<string, array{paraId:string, parentParaId:?string, resolved:?bool, partName:string}> $commentsExtended
     * @param array<string, array<string, mixed>> $commentsIds
     * @param array<string, mixed> $people
     * @return array{summary:array<string, mixed>, nodes:array<string, AstNode>}
     */
    private function readComments(
        array $parts,
        string $xml,
        string $partName,
        string $relationshipsPart,
        array $relationships,
        array $contentTypes,
        array $styles,
        array $numbering,
        array $commentsExtended = [],
        array $commentsIds = [],
        array $people = []
    ): array {
        $relationshipDiagnostics = $this->relatedPartRelationshipDiagnostics(
            $parts,
            $relationships,
            $partName,
            $relationshipsPart,
            $contentTypes,
        );
        if ($xml === '') {
            $summary = $this->commentAuthorPeopleSummary(
                $this->noteCollectionSummary([], [], $relationshipDiagnostics),
                $people,
                0,
                0,
                [],
                [],
            );

            return [
                'summary' => $summary,
                'nodes' => [],
            ];
        }

        $dom = $this->loadXml($xml, $partName);
        $root = $dom->documentElement;
        if (!$root instanceof \DOMElement || $root->namespaceURI !== self::NS_W || $root->localName !== 'comments') {
            $summary = $this->commentAuthorPeopleSummary(
                $this->noteCollectionSummary([], [], $relationshipDiagnostics),
                $people,
                0,
                0,
                [],
                [],
            );

            return [
                'summary' => $summary,
                'nodes' => [],
            ];
        }

        $xpath = $this->xpath($dom);
        $items = [];
        $byId = [];
        $nodes = [];
        $authorPeopleMatchedCount = 0;
        $authorPeopleUnmatchedCount = 0;
        $authorPeopleMatchedAuthors = [];
        $authorPeopleUnmatchedAuthors = [];
        foreach ($root->childNodes as $comment) {
            if (!$comment instanceof \DOMElement || $comment->namespaceURI !== self::NS_W || $comment->localName !== 'comment') {
                continue;
            }

            $id = $comment->getAttributeNS(self::NS_W, 'id');
            if ($id === '') {
                continue;
            }

            $blocks = $this->readNoteBlocks($comment, $xpath, $relationships, $contentTypes, $styles, $numbering);
            $relationshipIds = $this->relationshipIdsInElement($comment);
            $attrs = [
                'id' => $id,
                'sourceType' => 'comment',
            ];
            $author = $this->emptyStringToNull($comment->getAttributeNS(self::NS_W, 'author'));
            $initials = $this->emptyStringToNull($comment->getAttributeNS(self::NS_W, 'initials'));
            $date = $this->emptyStringToNull($comment->getAttributeNS(self::NS_W, 'date'));
            if ($author !== null) {
                $attrs['author'] = $author;
            }
            if ($initials !== null) {
                $attrs['initials'] = $initials;
            }
            if ($date !== null) {
                $attrs['date'] = $date;
            }
            if ($author !== null) {
                foreach ($this->commentAuthorPeopleAttrs($author, $people) as $key => $value) {
                    $attrs[$key] = $value;
                }
                if (($attrs['commentAuthorPeopleMatched'] ?? false) === true) {
                    ++$authorPeopleMatchedCount;
                    $this->appendUniqueString($authorPeopleMatchedAuthors, $author);
                } else {
                    ++$authorPeopleUnmatchedCount;
                    $this->appendUniqueString($authorPeopleUnmatchedAuthors, $author);
                }
            }
            foreach ($this->commentPackageAttrs($comment, $commentsExtended, $commentsIds) as $key => $value) {
                $attrs[$key] = $value;
            }

            $item = [
                'id' => $id,
                'sourceType' => 'comment',
                'type' => 'normal',
                'blockCount' => count($blocks),
                'text' => $this->plainBlockText($blocks),
                'author' => $author,
                'initials' => $initials,
                'date' => $date,
                'commentParaId' => $attrs['commentParaId'] ?? null,
                'commentParentParaId' => $attrs['commentParentParaId'] ?? null,
                'commentResolved' => $attrs['commentResolved'] ?? null,
                'commentsExtendedPart' => $attrs['commentsExtendedPart'] ?? null,
                'commentDurableId' => $attrs['commentDurableId'] ?? null,
                'commentsIdsPart' => $attrs['commentsIdsPart'] ?? null,
                'commentIdIssues' => $attrs['commentIdIssues'] ?? [],
                'commentAuthorPeopleMatched' => $attrs['commentAuthorPeopleMatched'] ?? null,
                'commentAuthorPeoplePart' => $attrs['commentAuthorPeoplePart'] ?? null,
                'commentAuthorPersonIndex' => $attrs['commentAuthorPersonIndex'] ?? null,
                'commentAuthorPresenceInfoCount' => $attrs['commentAuthorPresenceInfoCount'] ?? null,
                'commentAuthorPresenceInfo' => $attrs['commentAuthorPresenceInfo'] ?? [],
                'commentAuthorProviderIds' => $attrs['commentAuthorProviderIds'] ?? [],
                'commentAuthorUserIds' => $attrs['commentAuthorUserIds'] ?? [],
                'commentAuthorPeopleReviewPolicy' => $attrs['commentAuthorPeopleReviewPolicy'] ?? null,
                'relationshipCount' => count($relationshipIds),
                'relationshipIds' => $relationshipIds,
                'missingRelationshipIds' => $this->missingRelationshipIds($relationshipIds, $relationships),
            ];
            $items[] = $item;
            $byId[$id] = $item;
            $nodes[$id] = new AstNode('note', $attrs, $blocks);
        }

        $summary = $this->commentAuthorPeopleSummary(
            $this->noteCollectionSummary($items, $byId, $relationshipDiagnostics),
            $people,
            $authorPeopleMatchedCount,
            $authorPeopleUnmatchedCount,
            $authorPeopleMatchedAuthors,
            $authorPeopleUnmatchedAuthors,
        );

        return [
            'summary' => $summary,
            'nodes' => $nodes,
        ];
    }

    /**
     * @param array<string, array{id:string, type:string, target:string, targetMode:string, resolvedTarget:string}> $relationships
     * @param array{defaults:array<string, string>, overrides:array<string, string>} $contentTypes
     * @param array<string, array{id:string, name:string, headingLevel:int|null}> $styles
     * @param array<string, array{abstractNumId:string, levels:array<int, array{format:string, text:string, start:int}>}> $numbering
     * @param array<string, array<string, AstNode>>|null $referencedNotes
     * @return list<AstNode>
     */
    private function readNoteBlocks(
        \DOMElement $note,
        \DOMXPath $xpath,
        array $relationships,
        array $contentTypes,
        array $styles,
        array $numbering,
        ?array $referencedNotes = null
    ): array {
        $blocks = [];
        $currentList = null;
        $referencedNotes ??= ['footnote' => [], 'endnote' => [], 'comment' => []];
        foreach ($note->childNodes as $child) {
            if (!$child instanceof \DOMElement || $child->namespaceURI !== self::NS_W) {
                continue;
            }

            if ($child->localName === 'p') {
                $paragraph = $this->readParagraph($child, $xpath, $relationships, $contentTypes, $styles, $referencedNotes);
                if ($paragraph === null) {
                    $this->flushCurrentList($currentList, $blocks);
                    continue;
                }

                $list = $this->paragraphListAttrs($child, $numbering);
                if ($list !== null && $paragraph->type === 'paragraph') {
                    $key = $list['type'] . ':' . $list['numId'] . ':' . $list['level'] . ':' . ($list['style'] ?? '') . ':' . ($list['delimiter'] ?? '') . ':' . $list['start'] . ':' . ($list['pictureBulletId'] ?? '');
                    if (!is_array($currentList) || $currentList['key'] !== $key) {
                        $this->flushCurrentList($currentList, $blocks);
                        $attrs = [
                            'docxNumId' => $list['numId'],
                            'docxLevel' => $list['level'],
                        ];
                        if ($list['type'] === 'ordered_list') {
                            $attrs['start'] = $list['start'];
                            $attrs['style'] = $list['style'];
                            $attrs['delimiter'] = $list['delimiter'];
                        } else {
                            $attrs['bulletChar'] = $list['text'];
                        }
                        if (is_string($list['pictureBulletId'] ?? null)) {
                            $attrs['pictureBulletId'] = $list['pictureBulletId'];
                        }
                        if (is_array($list['pictureBullet'] ?? null)) {
                            $attrs['pictureBullet'] = $list['pictureBullet'];
                        }
                        $currentList = [
                            'key' => $key,
                            'type' => $list['type'],
                            'attrs' => $attrs,
                            'items' => [],
                        ];
                    }

                    $currentList['items'][] = new AstNode('list_item', [], [$paragraph]);
                    continue;
                }

                $this->flushCurrentList($currentList, $blocks);
                $blocks[] = $paragraph;
                continue;
            }

            if ($child->localName === 'tbl') {
                $this->flushCurrentList($currentList, $blocks);
                $table = $this->readTable($child, $xpath, $relationships, $contentTypes, $styles, $referencedNotes);
                if ($table !== null) {
                    $blocks[] = $table;
                }
            }
        }
        $this->flushCurrentList($currentList, $blocks);

        return $blocks;
    }

    /**
     * @param array<string, array<string, AstNode>> $referencedNotes
     */
    private function referencedNoteNode(array $referencedNotes, string $sourceType, \DOMElement $reference): ?AstNode
    {
        $id = $reference->getAttributeNS(self::NS_W, 'id');
        if ($id === '') {
            return null;
        }

        $attrs = [
            'id' => $id,
            'sourceType' => $sourceType,
        ];
        $customMarkFollows = strtolower($reference->getAttributeNS(self::NS_W, 'customMarkFollows'));
        if ($customMarkFollows !== '' && !in_array($customMarkFollows, ['0', 'false', 'off'], true)) {
            $attrs['customMarkFollows'] = true;
        }

        $note = $referencedNotes[$sourceType][$id] ?? null;
        if ($note instanceof AstNode) {
            return new AstNode('note', array_replace($note->attrs, $attrs), $note->children);
        }

        return new AstNode('note', ['missing' => true] + $attrs);
    }

    /**
     * @param array<string, string> $parts
     * @param array{defaults:array<string, string>, overrides:array<string, string>} $contentTypes
     * @return array<string, array{path:string, contentType:string, size:int, sha1:string}>
     */
    private function mediaMetadata(array $parts, array $contentTypes): array
    {
        $media = [];
        foreach ($parts as $name => $contents) {
            if (!str_starts_with($name, 'word/media/')) {
                continue;
            }
            $media[$name] = [
                'path' => $name,
                'contentType' => $this->contentTypeFor($name, $contentTypes),
                'size' => strlen($contents),
                'sha1' => sha1($contents),
            ];
        }

        return $media;
    }

    /**
     * @param array<string, array{id:string, type:string, target:string, targetMode:string, resolvedTarget:string}> $relationships
     * @param array{defaults:array<string, string>, overrides:array<string, string>} $contentTypes
     * @param array<string, array{id:string, name:string, headingLevel:int|null}> $styles
     * @param array<string, array{abstractNumId:string, levels:array<int, array{format:string, text:string, start:int}>}> $numbering
     * @param array<string, array<string, AstNode>> $referencedNotes
     * @return list<AstNode>
     */
    private function readDocumentBlocks(string $xml, array $relationships, array $contentTypes, array $styles, array $numbering, array $referencedNotes): array
    {
        $dom = $this->loadXml($xml, 'word/document.xml');
        $xpath = $this->xpath($dom);
        $body = $this->firstElement($xpath, '/w:document/w:body', $dom);
        if (!$body instanceof \DOMElement) {
            return [];
        }

        return $this->readWordBlockChildren($body->childNodes, $xpath, $relationships, $contentTypes, $styles, $numbering, $referencedNotes);
    }

    /**
     * @return array<string, mixed>
     */
    private function readDocumentRevisionSummary(string $xml, string $partName): array
    {
        $dom = $this->loadXml($xml, $partName);
        $xpath = $this->xpath($dom);
        $items = [];
        $authors = [];
        $kindCounts = ['ins' => 0, 'del' => 0, 'moveFrom' => 0, 'moveTo' => 0];
        $visibleCount = 0;
        $reviewOnlyCount = 0;
        $datedCount = 0;
        $textRunCount = 0;
        $textBytes = 0;
        $emptyTextCount = 0;

        foreach ($this->elements($xpath, '/w:document/w:body//w:ins | /w:document/w:body//w:del | /w:document/w:body//w:moveFrom | /w:document/w:body//w:moveTo', $dom) as $revision) {
            $kind = $revision->localName;
            if (!array_key_exists($kind, $kindCounts)) {
                continue;
            }

            $text = $this->revisionElementText($revision);
            $author = $this->emptyStringToNull($revision->getAttributeNS(self::NS_W, 'author'));
            $date = $this->emptyStringToNull($revision->getAttributeNS(self::NS_W, 'date'));
            $visible = in_array($kind, ['ins', 'moveTo'], true);
            $textElementNames = $this->revisionTextElementNames($revision);
            $itemTextRunCount = count($textElementNames);
            $itemTextBytes = strlen($text);

            $kindCounts[$kind]++;
            $visible ? $visibleCount++ : $reviewOnlyCount++;
            $textRunCount += $itemTextRunCount;
            $textBytes += $itemTextBytes;
            if ($text === '') {
                $emptyTextCount++;
            }
            if ($author !== null) {
                $this->appendUniqueString($authors, $author);
            }
            if ($date !== null) {
                $datedCount++;
            }

            $items[] = [
                'index' => count($items),
                'kind' => $kind,
                'id' => $this->emptyStringToNull($revision->getAttributeNS(self::NS_W, 'id')),
                'author' => $author,
                'date' => $date,
                'visibleInBodyText' => $visible,
                'reviewPolicy' => $visible ? 'body-revision-visible' : 'body-revision-text-metadata-only',
                'textRunCount' => $itemTextRunCount,
                'textElementNames' => $textElementNames,
                'textBytes' => $itemTextBytes,
                'textSha256' => hash('sha256', $text),
            ];
        }

        return [
            'partName' => $partName,
            'count' => count($items),
            'visibleCount' => $visibleCount,
            'reviewOnlyCount' => $reviewOnlyCount,
            'kindCounts' => $kindCounts,
            'authorCount' => count($authors),
            'authors' => $authors,
            'datedCount' => $datedCount,
            'textRunCount' => $textRunCount,
            'textBytes' => $textBytes,
            'emptyTextCount' => $emptyTextCount,
            'items' => $items,
            'reviewPolicy' => 'body-revision-text-metadata-only',
        ];
    }

    /**
     * @return array<string, mixed>
     */
    private function readDocumentRangeMarkerSummary(string $xml, string $partName): array
    {
        $dom = $this->loadXml($xml, $partName);
        $xpath = $this->xpath($dom);
        $markerElementNames = [
            'bookmarkStart',
            'bookmarkEnd',
            'commentRangeStart',
            'commentRangeEnd',
            'proofErr',
            'permStart',
            'permEnd',
            'moveFromRangeStart',
            'moveFromRangeEnd',
            'moveToRangeStart',
            'moveToRangeEnd',
            'customXmlInsRangeStart',
            'customXmlInsRangeEnd',
            'customXmlDelRangeStart',
            'customXmlDelRangeEnd',
            'customXmlMoveFromRangeStart',
            'customXmlMoveFromRangeEnd',
            'customXmlMoveToRangeStart',
            'customXmlMoveToRangeEnd',
        ];
        $markerQueries = array_map(
            static fn (string $elementName): string => '/w:document/w:body//w:' . $elementName,
            $markerElementNames,
        );
        $kindCounts = [
            'bookmark' => 0,
            'comment' => 0,
            'proofError' => 0,
            'permission' => 0,
            'moveFrom' => 0,
            'moveTo' => 0,
            'customXmlInsert' => 0,
            'customXmlDelete' => 0,
            'customXmlMoveFrom' => 0,
            'customXmlMoveTo' => 0,
        ];
        $elementCounts = [];
        $positionCounts = ['start' => 0, 'end' => 0, 'point' => 0];
        $items = [];
        $emptyIdCount = 0;
        $namedBookmarkCount = 0;
        $nameHashCount = 0;
        $typedProofErrorCount = 0;
        $permissionEditorGroupCount = 0;
        $permissionColumnBoundCount = 0;

        foreach ($this->elements($xpath, implode(' | ', $markerQueries), $dom) as $marker) {
            $classification = $this->documentRangeMarkerClassification($marker->localName);
            if ($classification === null) {
                continue;
            }

            [$kind, $position] = $classification;
            $id = $this->emptyStringToNull($marker->getAttributeNS(self::NS_W, 'id'));
            $name = $this->emptyStringToNull($marker->getAttributeNS(self::NS_W, 'name'));
            $proofErrorType = $this->emptyStringToNull($marker->getAttributeNS(self::NS_W, 'type'));
            $editorGroup = $this->emptyStringToNull($marker->getAttributeNS(self::NS_W, 'edGrp'));
            $columnFirst = $this->wordOptionalIntAttr($marker, 'colFirst');
            $columnLast = $this->wordOptionalIntAttr($marker, 'colLast');
            $displacedByCustomXml = $this->emptyStringToNull($marker->getAttributeNS(self::NS_W, 'displacedByCustomXml'));
            $item = [
                'index' => count($items),
                'kind' => $kind,
                'element' => $marker->localName,
                'position' => $position,
                'id' => $id,
                'reviewPolicy' => 'body-range-marker-metadata-only',
            ];

            $kindCounts[$kind]++;
            $elementCounts[$marker->localName] = ($elementCounts[$marker->localName] ?? 0) + 1;
            $positionCounts[$position]++;
            if ($position !== 'point' && $id === null) {
                $emptyIdCount++;
            }
            if ($kind === 'bookmark' && $marker->localName === 'bookmarkStart' && $name !== null) {
                $namedBookmarkCount++;
            }
            if ($name !== null) {
                $nameHashCount++;
                $item['nameBytes'] = strlen($name);
                $item['nameSha256'] = hash('sha256', $name);
            }
            if ($proofErrorType !== null) {
                $typedProofErrorCount++;
                $item['proofErrorType'] = $proofErrorType;
            }
            if ($editorGroup !== null) {
                $permissionEditorGroupCount++;
                $item['editorGroup'] = $editorGroup;
            }
            if ($columnFirst !== null || $columnLast !== null) {
                $permissionColumnBoundCount++;
                $item['columnFirst'] = $columnFirst;
                $item['columnLast'] = $columnLast;
            }
            if ($displacedByCustomXml !== null) {
                $item['displacedByCustomXml'] = $displacedByCustomXml;
            }

            $items[] = $item;
        }

        return [
            'partName' => $partName,
            'count' => count($items),
            'kindCounts' => $kindCounts,
            'elementCounts' => $elementCounts,
            'positionCounts' => $positionCounts,
            'startCount' => $positionCounts['start'],
            'endCount' => $positionCounts['end'],
            'pointCount' => $positionCounts['point'],
            'emptyIdCount' => $emptyIdCount,
            'namedBookmarkCount' => $namedBookmarkCount,
            'nameHashCount' => $nameHashCount,
            'typedProofErrorCount' => $typedProofErrorCount,
            'permissionEditorGroupCount' => $permissionEditorGroupCount,
            'permissionColumnBoundCount' => $permissionColumnBoundCount,
            'items' => $items,
            'reviewPolicy' => 'body-range-marker-metadata-only',
        ];
    }

    /**
     * @return array{0:string, 1:string}|null
     */
    private function documentRangeMarkerClassification(string $elementName): ?array
    {
        return match ($elementName) {
            'bookmarkStart' => ['bookmark', 'start'],
            'bookmarkEnd' => ['bookmark', 'end'],
            'commentRangeStart' => ['comment', 'start'],
            'commentRangeEnd' => ['comment', 'end'],
            'proofErr' => ['proofError', 'point'],
            'permStart' => ['permission', 'start'],
            'permEnd' => ['permission', 'end'],
            'moveFromRangeStart' => ['moveFrom', 'start'],
            'moveFromRangeEnd' => ['moveFrom', 'end'],
            'moveToRangeStart' => ['moveTo', 'start'],
            'moveToRangeEnd' => ['moveTo', 'end'],
            'customXmlInsRangeStart' => ['customXmlInsert', 'start'],
            'customXmlInsRangeEnd' => ['customXmlInsert', 'end'],
            'customXmlDelRangeStart' => ['customXmlDelete', 'start'],
            'customXmlDelRangeEnd' => ['customXmlDelete', 'end'],
            'customXmlMoveFromRangeStart' => ['customXmlMoveFrom', 'start'],
            'customXmlMoveFromRangeEnd' => ['customXmlMoveFrom', 'end'],
            'customXmlMoveToRangeStart' => ['customXmlMoveTo', 'start'],
            'customXmlMoveToRangeEnd' => ['customXmlMoveTo', 'end'],
            default => null,
        };
    }

    private function revisionElementText(\DOMElement $revision): string
    {
        $text = '';
        foreach ($revision->getElementsByTagNameNS(self::NS_W, '*') as $element) {
            if (!$element instanceof \DOMElement) {
                continue;
            }

            $text .= match ($element->localName) {
                't', 'delText', 'instrText', 'delInstrText' => $element->textContent,
                'tab' => "\t",
                'br', 'cr' => "\n",
                'noBreakHyphen' => "\u{2011}",
                'softHyphen' => "\u{00AD}",
                'sym' => $this->symbolText($element),
                default => '',
            };
        }

        return $text;
    }

    /**
     * @return list<string>
     */
    private function revisionTextElementNames(\DOMElement $revision): array
    {
        $names = [];
        foreach ($revision->getElementsByTagNameNS(self::NS_W, '*') as $element) {
            if (!$element instanceof \DOMElement) {
                continue;
            }

            if (in_array($element->localName, ['t', 'delText', 'instrText', 'delInstrText', 'tab', 'br', 'cr', 'noBreakHyphen', 'softHyphen', 'sym'], true)) {
                $names[] = $element->localName;
            }
        }

        return $names;
    }

    private function symbolText(\DOMElement $element): string
    {
        $hex = $element->getAttributeNS(self::NS_W, 'char');
        if ($hex === '' || !ctype_xdigit($hex)) {
            return '';
        }

        return html_entity_decode('&#x' . $hex . ';', ENT_QUOTES | ENT_XML1, 'UTF-8');
    }

    /**
     * @param iterable<\DOMNode> $children
     * @param array<string, array{id:string, type:string, target:string, targetMode:string, resolvedTarget:string}> $relationships
     * @param array{defaults:array<string, string>, overrides:array<string, string>} $contentTypes
     * @param array<string, array{id:string, name:string, headingLevel:int|null}> $styles
     * @param array<string, array{abstractNumId:string, levels:array<int, array{format:string, text:string, start:int}>}> $numbering
     * @param array<string, array<string, AstNode>> $referencedNotes
     * @return list<AstNode>
     */
    private function readWordBlockChildren(iterable $children, \DOMXPath $xpath, array $relationships, array $contentTypes, array $styles, array $numbering, array $referencedNotes): array
    {
        $blocks = [];
        $currentList = null;

        foreach ($children as $bodyChild) {
            if (!$bodyChild instanceof \DOMElement) {
                continue;
            }

            if ($bodyChild->namespaceURI === self::NS_W && $bodyChild->localName === 'p') {
                $paragraph = $this->readParagraph($bodyChild, $xpath, $relationships, $contentTypes, $styles, $referencedNotes);
                if ($paragraph === null) {
                    $this->flushCurrentList($currentList, $blocks);
                    continue;
                }

                $list = $this->paragraphListAttrs($bodyChild, $numbering);
                if ($list !== null && $paragraph->type === 'paragraph') {
                    $key = $list['type'] . ':' . $list['numId'] . ':' . $list['level'] . ':' . ($list['style'] ?? '') . ':' . ($list['delimiter'] ?? '') . ':' . $list['start'] . ':' . ($list['pictureBulletId'] ?? '');
                    if (!is_array($currentList) || $currentList['key'] !== $key) {
                        $this->flushCurrentList($currentList, $blocks);
                        $attrs = [
                            'docxNumId' => $list['numId'],
                            'docxLevel' => $list['level'],
                        ];
                        if ($list['type'] === 'ordered_list') {
                            $attrs['start'] = $list['start'];
                            $attrs['style'] = $list['style'];
                            $attrs['delimiter'] = $list['delimiter'];
                        } else {
                            $attrs['bulletChar'] = $list['text'];
                        }
                        if (is_string($list['pictureBulletId'] ?? null)) {
                            $attrs['pictureBulletId'] = $list['pictureBulletId'];
                        }
                        if (is_array($list['pictureBullet'] ?? null)) {
                            $attrs['pictureBullet'] = $list['pictureBullet'];
                        }
                        $currentList = [
                            'key' => $key,
                            'type' => $list['type'],
                            'attrs' => $attrs,
                            'items' => [],
                        ];
                    }

                    $currentList['items'][] = new AstNode('list_item', [], [$paragraph]);
                    continue;
                }

                $this->flushCurrentList($currentList, $blocks);
                $blocks[] = $paragraph;
                continue;
            }

            if ($bodyChild->namespaceURI === self::NS_W && $bodyChild->localName === 'tbl') {
                $this->flushCurrentList($currentList, $blocks);
                $table = $this->readTable($bodyChild, $xpath, $relationships, $contentTypes, $styles, $referencedNotes);
                if ($table !== null) {
                    $blocks[] = $table;
                }
                continue;
            }

            if ($bodyChild->namespaceURI === self::NS_W && $bodyChild->localName === 'sdt') {
                $this->flushCurrentList($currentList, $blocks);
                $content = $this->childElement($bodyChild, 'sdtContent');
                if ($content instanceof \DOMElement) {
                    array_push(
                        $blocks,
                        ...$this->readWordBlockChildren($content->childNodes, $xpath, $relationships, $contentTypes, $styles, $numbering, $referencedNotes)
                    );
                }
            }
        }
        $this->flushCurrentList($currentList, $blocks);

        return $blocks;
    }

    /**
     * @return list<string>
     */
    private function relationshipIdsInElement(\DOMElement $element): array
    {
        $relationshipIds = [];
        $stack = [$element];
        while ($stack !== []) {
            $current = array_pop($stack);
            if (!$current instanceof \DOMElement) {
                continue;
            }

            foreach (['id', 'embed', 'link'] as $attribute) {
                $this->appendUniqueString($relationshipIds, $this->emptyStringToNull($current->getAttributeNS(self::NS_R, $attribute)));
            }

            foreach ($current->childNodes as $child) {
                if ($child instanceof \DOMElement) {
                    $stack[] = $child;
                }
            }
        }

        sort($relationshipIds, SORT_STRING);

        return $relationshipIds;
    }

    /**
     * @param array{key:string, type:string, attrs:array<string, mixed>, items:list<AstNode>}|null $currentList
     * @param list<AstNode> $blocks
     */
    private function flushCurrentList(?array &$currentList, array &$blocks): void
    {
        if (!is_array($currentList)) {
            return;
        }

        $blocks[] = new AstNode($currentList['type'], $currentList['attrs'], $currentList['items']);
        $currentList = null;
    }

    /**
     * @param array<string, array{id:string, type:string, target:string, targetMode:string, resolvedTarget:string}> $relationships
     * @param array{defaults:array<string, string>, overrides:array<string, string>} $contentTypes
     * @param array<string, array{id:string, name:string, headingLevel:int|null}> $styles
     * @param array<string, array<string, AstNode>> $referencedNotes
     */
    private function readParagraph(\DOMElement $paragraph, \DOMXPath $xpath, array $relationships, array $contentTypes, array $styles, array $referencedNotes): ?AstNode
    {
        $inlines = $this->readParagraphInlines($paragraph, $xpath, $relationships, $contentTypes, $referencedNotes);
        $text = $this->plainInlineText($inlines);
        if ($inlines === [] && $text === '') {
            return null;
        }

        $attrs = ['text' => $text];
        $styleId = $this->paragraphStyleId($paragraph);
        if ($styleId !== '') {
            $attrs['docxStyleId'] = $styleId;
            $style = $styles[$styleId] ?? null;
            if (is_array($style)) {
                $attrs['docxStyleName'] = $style['name'];
                if ($style['headingLevel'] !== null) {
                    $attrs['level'] = $style['headingLevel'];
                    $attrs['id'] = $this->identifierFromText($text);

                    return new AstNode('heading', $attrs, $inlines);
                }
            }
        }

        return new AstNode('paragraph', $attrs, $inlines);
    }

    /**
     * @param array<string, array{id:string, type:string, target:string, targetMode:string, resolvedTarget:string}> $relationships
     * @param array{defaults:array<string, string>, overrides:array<string, string>} $contentTypes
     * @param array<string, array<string, AstNode>> $referencedNotes
     * @return list<AstNode>
     */
    private function readParagraphInlines(\DOMElement $paragraph, \DOMXPath $xpath, array $relationships, array $contentTypes, array $referencedNotes): array
    {
        $inlines = [];
        foreach ($paragraph->childNodes as $child) {
            if (!$child instanceof \DOMElement) {
                continue;
            }

            if ($child->namespaceURI === self::NS_W && $child->localName === 'r') {
                array_push($inlines, ...$this->readRun($child, $xpath, $relationships, $contentTypes, $referencedNotes));
                continue;
            }

            if ($child->namespaceURI === self::NS_W && $child->localName === 'hyperlink') {
                $linkInlines = [];
                foreach ($this->elements($xpath, 'w:r', $child) as $run) {
                    array_push($linkInlines, ...$this->readRun($run, $xpath, $relationships, $contentTypes, $referencedNotes));
                }
                if ($linkInlines !== []) {
                    $inlines[] = new AstNode('link', $this->hyperlinkAttrs($child, $relationships), $linkInlines);
                }
                continue;
            }

            if (in_array($child->localName, ['ins', 'moveTo', 'smartTag', 'sdt'], true)) {
                foreach ($this->elements($xpath, './/w:r', $child) as $run) {
                    array_push($inlines, ...$this->readRun($run, $xpath, $relationships, $contentTypes, $referencedNotes));
                }
            }
        }

        return $this->mergeAdjacentText($inlines);
    }

    /**
     * @param array<string, array{id:string, type:string, target:string, targetMode:string, resolvedTarget:string}> $relationships
     * @return array<string, mixed>
     */
    private function hyperlinkAttrs(\DOMElement $hyperlink, array $relationships): array
    {
        $relationshipId = $hyperlink->getAttributeNS(self::NS_R, 'id');
        $anchor = $hyperlink->getAttributeNS(self::NS_W, 'anchor');
        $attrs = ['url' => ''];
        if ($relationshipId !== '' && isset($relationships[$relationshipId])) {
            $relationship = $relationships[$relationshipId];
            $attrs['url'] = $relationship['targetMode'] === 'External'
                ? $relationship['target']
                : $relationship['resolvedTarget'];
            $attrs['relationshipId'] = $relationshipId;
            $attrs['relationshipType'] = $relationship['type'];
            $attrs['targetMode'] = $relationship['targetMode'];
        } elseif ($anchor !== '') {
            $attrs['url'] = '#' . $anchor;
        }

        if ($anchor !== '' && $relationshipId !== '') {
            $attrs['url'] .= '#' . $anchor;
        }

        return $attrs;
    }

    /**
     * @param array<string, array{id:string, type:string, target:string, targetMode:string, resolvedTarget:string}> $relationships
     * @param array{defaults:array<string, string>, overrides:array<string, string>} $contentTypes
     * @param array<string, array<string, AstNode>> $referencedNotes
     * @return list<AstNode>
     */
    private function readRun(\DOMElement $run, \DOMXPath $xpath, array $relationships, array $contentTypes, array $referencedNotes): array
    {
        $inlines = [];
        foreach ($run->childNodes as $child) {
            if (!$child instanceof \DOMElement) {
                continue;
            }

            if ($child->namespaceURI === self::NS_W && $child->localName === 't') {
                $this->appendText($inlines, $child->textContent);
                continue;
            }
            if ($child->namespaceURI === self::NS_W && $child->localName === 'tab') {
                $this->appendText($inlines, "\t");
                continue;
            }
            if ($child->namespaceURI === self::NS_W && in_array($child->localName, ['br', 'cr'], true)) {
                $inlines[] = new AstNode('linebreak');
                continue;
            }
            if ($child->namespaceURI === self::NS_W && $child->localName === 'noBreakHyphen') {
                $this->appendText($inlines, "\u{2011}");
                continue;
            }
            if ($child->namespaceURI === self::NS_W && $child->localName === 'softHyphen') {
                $this->appendText($inlines, "\u{00AD}");
                continue;
            }
            if ($child->namespaceURI === self::NS_W && $child->localName === 'sym') {
                $hex = $child->getAttributeNS(self::NS_W, 'char');
                if ($hex !== '' && ctype_xdigit($hex)) {
                    $this->appendText($inlines, html_entity_decode('&#x' . $hex . ';', ENT_QUOTES | ENT_XML1, 'UTF-8'));
                }
                continue;
            }
            if ($child->namespaceURI === self::NS_W && $child->localName === 'drawing') {
                array_push($inlines, ...$this->readDrawingImages($child, $xpath, $relationships, $contentTypes));
                continue;
            }
            if ($child->namespaceURI === self::NS_W && $child->localName === 'pict') {
                array_push($inlines, ...$this->readPictImages($child, $xpath, $relationships, $contentTypes));
                continue;
            }
            if ($child->namespaceURI === self::NS_W && in_array($child->localName, ['footnoteRef', 'endnoteRef'], true)) {
                continue;
            }
            if ($child->namespaceURI === self::NS_W && $child->localName === 'footnoteReference') {
                $note = $this->referencedNoteNode($referencedNotes, 'footnote', $child);
                if ($note !== null) {
                    $inlines[] = $note;
                }
                continue;
            }
            if ($child->namespaceURI === self::NS_W && $child->localName === 'endnoteReference') {
                $note = $this->referencedNoteNode($referencedNotes, 'endnote', $child);
                if ($note !== null) {
                    $inlines[] = $note;
                }
                continue;
            }
            if ($child->namespaceURI === self::NS_W && $child->localName === 'commentReference') {
                $note = $this->referencedNoteNode($referencedNotes, 'comment', $child);
                if ($note !== null) {
                    $inlines[] = $note;
                }
            }
        }

        return $this->wrapRunInlines($run, $inlines);
    }

    /**
     * @param list<AstNode> $inlines
     * @return list<AstNode>
     */
    private function wrapRunInlines(\DOMElement $run, array $inlines): array
    {
        if ($inlines === []) {
            return [];
        }

        $rPr = $this->childElement($run, 'rPr');
        if (!$rPr instanceof \DOMElement) {
            return $inlines;
        }

        $wrappers = [];
        $vertical = $this->childAttr($rPr, 'vertAlign', 'val');
        if ($vertical === 'superscript') {
            $wrappers[] = 'superscript';
        } elseif ($vertical === 'subscript') {
            $wrappers[] = 'subscript';
        }
        if ($this->runPropertyEnabled($rPr, 'smallCaps')) {
            $wrappers[] = 'small_caps';
        }
        if ($this->runPropertyEnabled($rPr, 'u')) {
            $wrappers[] = 'underline';
        }
        if ($this->runPropertyEnabled($rPr, 'strike') || $this->runPropertyEnabled($rPr, 'dstrike')) {
            $wrappers[] = 'strikeout';
        }
        if ($this->runPropertyEnabled($rPr, 'i')) {
            $wrappers[] = 'emph';
        }
        if ($this->runPropertyEnabled($rPr, 'b')) {
            $wrappers[] = 'strong';
        }

        foreach ($wrappers as $type) {
            $inlines = [new AstNode($type, [], $inlines)];
        }

        return $inlines;
    }

    private function runPropertyEnabled(\DOMElement $rPr, string $name): bool
    {
        $property = $this->childElement($rPr, $name);
        if (!$property instanceof \DOMElement) {
            return false;
        }

        $value = strtolower($property->getAttributeNS(self::NS_W, 'val'));
        if ($name === 'u' && $value === 'none') {
            return false;
        }

        return !in_array($value, ['0', 'false', 'off'], true);
    }

    /**
     * @param array<string, array{id:string, type:string, target:string, targetMode:string, resolvedTarget:string}> $relationships
     * @param array{defaults:array<string, string>, overrides:array<string, string>} $contentTypes
     * @return list<AstNode>
     */
    private function readDrawingImages(\DOMElement $drawing, \DOMXPath $xpath, array $relationships, array $contentTypes): array
    {
        $images = [];
        $docPr = $this->firstElement($xpath, './/wp:docPr', $drawing);
        foreach ($this->elements($xpath, './/a:blip', $drawing) as $blip) {
            $relationshipId = $blip->getAttributeNS(self::NS_R, 'embed');
            if ($relationshipId === '') {
                $relationshipId = $blip->getAttributeNS(self::NS_R, 'link');
            }

            $relationship = $relationships[$relationshipId] ?? null;
            if (!is_array($relationship)) {
                continue;
            }

            $isExternal = $this->isExternalRelationshipTarget($relationship);
            $targetPart = $isExternal ? null : $this->stripQueryAndFragment($relationship['resolvedTarget']);
            $targetSuffix = $this->targetReferenceSuffix($relationship['resolvedTarget']);
            $url = $isExternal ? $relationship['target'] : (string) $targetPart;
            $alt = $docPr instanceof \DOMElement ? trim($docPr->getAttribute('descr')) : '';
            $title = $docPr instanceof \DOMElement ? trim($docPr->getAttribute('title') ?: $docPr->getAttribute('name')) : '';
            $attrs = [
                'url' => $url,
                'relationshipId' => $relationshipId,
                'relationshipType' => $relationship['type'],
                'targetMode' => $relationship['targetMode'],
                'target' => $relationship['target'],
                'resolvedTarget' => $relationship['resolvedTarget'],
                'targetPart' => $targetPart,
                'targetQuery' => $targetSuffix['query'],
                'targetFragment' => $targetSuffix['fragment'],
                'targetReferenceSuffix' => $targetSuffix['suffix'],
            ];
            if (!$isExternal && $targetPart !== null) {
                $attrs['mediaPath'] = $targetPart;
                $attrs['contentType'] = $this->contentTypeFor($targetPart, $contentTypes);
            }
            if ($alt !== '') {
                $attrs['alt'] = $alt;
            }
            if ($title !== '') {
                $attrs['title'] = $title;
            }

            $children = $alt === '' ? [] : [new AstNode('text', ['text' => $alt])];
            $images[] = new AstNode('image', $attrs, $children);
        }

        return $images;
    }

    /**
     * @param array<string, array{id:string, type:string, target:string, targetMode:string, resolvedTarget:string}> $relationships
     * @param array{defaults:array<string, string>, overrides:array<string, string>} $contentTypes
     * @return list<AstNode>
     */
    private function readPictImages(\DOMElement $pict, \DOMXPath $xpath, array $relationships, array $contentTypes): array
    {
        $images = [];
        foreach ($this->elements($xpath, './/v:imagedata', $pict) as $imageData) {
            $relationshipId = $this->vmlImageRelationshipId($imageData);
            $relationship = $relationships[$relationshipId] ?? null;
            if (!is_array($relationship)) {
                continue;
            }

            $isExternal = $relationship['targetMode'] === 'External';
            $url = $isExternal ? $relationship['target'] : $relationship['resolvedTarget'];
            $alt = $this->vmlImageAlt($imageData);
            $title = $this->vmlImageTitle($imageData);
            $attrs = [
                'url' => $url,
                'relationshipId' => $relationshipId,
                'relationshipType' => $relationship['type'],
                'targetMode' => $relationship['targetMode'],
                'imageSource' => 'vml-pict',
            ];
            if (!$isExternal) {
                $attrs['mediaPath'] = $relationship['resolvedTarget'];
                $attrs['contentType'] = $this->contentTypeFor($this->stripQueryAndFragment($relationship['resolvedTarget']), $contentTypes);
            }
            if ($alt !== '') {
                $attrs['alt'] = $alt;
            }
            if ($title !== '') {
                $attrs['title'] = $title;
            }

            $children = $alt === '' ? [] : [new AstNode('text', ['text' => $alt])];
            $images[] = new AstNode('image', $attrs, $children);
        }

        return $images;
    }

    private function vmlImageRelationshipId(\DOMElement $imageData): string
    {
        $relationshipId = $imageData->getAttributeNS(self::NS_R, 'id');
        if ($relationshipId === '') {
            $relationshipId = $imageData->getAttributeNS(self::NS_R, 'embed');
        }
        if ($relationshipId === '') {
            $relationshipId = $imageData->getAttributeNS(self::NS_R, 'link');
        }
        if ($relationshipId === '') {
            $relationshipId = $imageData->getAttributeNS(self::NS_O, 'relid');
        }

        return $relationshipId;
    }

    private function vmlImageAlt(\DOMElement $imageData): string
    {
        $node = $imageData->parentNode;
        while ($node instanceof \DOMElement) {
            if ($node->namespaceURI === self::NS_V && $node->localName === 'shape') {
                return trim($node->getAttribute('alt'));
            }
            $node = $node->parentNode;
        }

        return '';
    }

    private function vmlImageTitle(\DOMElement $imageData): string
    {
        $title = trim($imageData->getAttributeNS(self::NS_O, 'title'));
        if ($title === '') {
            $title = trim($imageData->getAttribute('title'));
        }

        return $title;
    }

    /**
     * @param array<string, array{abstractNumId:string, levels:array<int, array<string, mixed>>}> $numbering
     * @return array<string, mixed>|null
     */
    private function paragraphListAttrs(\DOMElement $paragraph, array $numbering): ?array
    {
        $pPr = $this->childElement($paragraph, 'pPr');
        $numPr = $pPr instanceof \DOMElement ? $this->childElement($pPr, 'numPr') : null;
        if (!$numPr instanceof \DOMElement) {
            return null;
        }

        $numId = $this->childAttr($numPr, 'numId', 'val');
        if ($numId === '' || !isset($numbering[$numId])) {
            return null;
        }

        $ilvl = (int) ($this->childAttr($numPr, 'ilvl', 'val') ?: '0');
        $level = $numbering[$numId]['levels'][$ilvl] ?? ['format' => 'decimal', 'text' => '%' . ($ilvl + 1) . '.', 'start' => 1];
        $format = $level['format'];
        $type = $format === 'bullet' ? 'bullet_list' : 'ordered_list';

        $attrs = [
            'type' => $type,
            'numId' => $numId,
            'level' => $ilvl,
            'start' => $level['start'],
            'style' => $this->listStyleForFormat($format),
            'delimiter' => $this->listDelimiterForText($level['text']),
            'text' => $level['text'],
        ];
        if (is_string($level['pictureBulletId'] ?? null)) {
            $attrs['pictureBulletId'] = $level['pictureBulletId'];
        }
        if (is_array($level['pictureBullet'] ?? null)) {
            $attrs['pictureBullet'] = $level['pictureBullet'];
        }

        return $attrs;
    }

    private function paragraphStyleId(\DOMElement $paragraph): string
    {
        $pPr = $this->childElement($paragraph, 'pPr');
        if (!$pPr instanceof \DOMElement) {
            return '';
        }

        return $this->childAttr($pPr, 'pStyle', 'val');
    }

    /**
     * @param array<string, array{id:string, type:string, target:string, targetMode:string, resolvedTarget:string}> $relationships
     * @param array{defaults:array<string, string>, overrides:array<string, string>} $contentTypes
     * @param array<string, array{id:string, name:string, headingLevel:int|null}> $styles
     * @param array<string, array<string, AstNode>> $referencedNotes
     */
    private function readTable(\DOMElement $table, \DOMXPath $xpath, array $relationships, array $contentTypes, array $styles, array $referencedNotes): ?AstNode
    {
        $headRows = [];
        $bodyRows = [];
        $gridBeforeRowCount = 0;
        $gridAfterRowCount = 0;
        $omittedBeforeColumnCount = 0;
        $omittedAfterColumnCount = 0;
        $headerRowCount = 0;
        $verticalMergeCellCount = 0;
        $verticalMergeRestartCount = 0;
        $verticalMergeContinueCount = 0;
        $maxGridColumnCount = 0;
        $promoteHeaderRows = true;
        foreach ($this->elements($xpath, 'w:tr', $table) as $row) {
            $rowProperties = $this->childElement($row, 'trPr');
            $gridBefore = $this->tableRowGridOmission($rowProperties, 'gridBefore');
            $gridAfter = $this->tableRowGridOmission($rowProperties, 'gridAfter');
            $isHeaderRow = $this->tableRowIsHeader($rowProperties);
            if ($gridBefore > 0) {
                ++$gridBeforeRowCount;
                $omittedBeforeColumnCount += $gridBefore;
            }
            if ($gridAfter > 0) {
                ++$gridAfterRowCount;
                $omittedAfterColumnCount += $gridAfter;
            }
            if ($isHeaderRow) {
                ++$headerRowCount;
            }

            $cells = [];
            $logicalColumn = $gridBefore + 1;
            foreach ($this->elements($xpath, 'w:tc', $row) as $cell) {
                $blocks = [];
                foreach ($this->elements($xpath, 'w:p', $cell) as $paragraph) {
                    $node = $this->readParagraph($paragraph, $xpath, $relationships, $contentTypes, $styles, $referencedNotes);
                    if ($node !== null) {
                        $blocks[] = $node;
                    }
                }
                $cellProperties = $this->childElement($cell, 'tcPr');
                $gridSpan = $this->tableCellGridSpan($cellProperties);
                $verticalMerge = $this->tableCellVerticalMerge($cellProperties);
                $attrs = [
                    'text' => $this->plainBlockText($blocks),
                    'docxGridColumn' => $logicalColumn,
                    'docxGridSpan' => $gridSpan,
                ];
                if ($isHeaderRow) {
                    $attrs['header'] = true;
                }
                if ($gridSpan > 1) {
                    $attrs['colspan'] = $gridSpan;
                }
                if ($verticalMerge !== null) {
                    ++$verticalMergeCellCount;
                    if ($verticalMerge === 'restart') {
                        ++$verticalMergeRestartCount;
                    } else {
                        ++$verticalMergeContinueCount;
                    }
                    $attrs['docxVerticalMerge'] = $verticalMerge;
                }
                $cells[] = new AstNode('table_cell', $attrs, $blocks);
                $logicalColumn += $gridSpan;
            }
            if ($cells !== []) {
                $rowAttrs = [
                    'docxGridBefore' => $gridBefore,
                    'docxGridAfter' => $gridAfter,
                    'docxGridColumnCount' => $logicalColumn - 1 + $gridAfter,
                    'docxTableHeader' => $isHeaderRow,
                ];
                if ($isHeaderRow) {
                    $rowAttrs['header'] = true;
                }
                $maxGridColumnCount = max($maxGridColumnCount, $rowAttrs['docxGridColumnCount']);
                $rowNode = new AstNode('table_row', $rowAttrs, $cells);
                if ($isHeaderRow && $promoteHeaderRows) {
                    $headRows[] = $rowNode;
                } else {
                    $bodyRows[] = $rowNode;
                }
                if (!$isHeaderRow) {
                    $promoteHeaderRows = false;
                }
            }
        }

        if ($headRows === [] && $bodyRows === []) {
            return null;
        }

        $sections = [];
        if ($headRows !== []) {
            $sections[] = new AstNode('table_head', [], $headRows);
        }
        $sections[] = new AstNode('table_body', [], $bodyRows);

        return new AstNode('table', [
            'caption' => '',
            'sourceFormat' => 'docx',
            'docxTableMetadataPolicy' => 'docx-table-grid-merge-metadata-only',
            'docxTableRowCount' => count($headRows) + count($bodyRows),
            'docxTableHeadRowCount' => count($headRows),
            'docxTableBodyRowCount' => count($bodyRows),
            'docxTableGridBeforeRowCount' => $gridBeforeRowCount,
            'docxTableGridAfterRowCount' => $gridAfterRowCount,
            'docxTableOmittedBeforeColumnCount' => $omittedBeforeColumnCount,
            'docxTableOmittedAfterColumnCount' => $omittedAfterColumnCount,
            'docxTableHeaderRowCount' => $headerRowCount,
            'docxTableVerticalMergeCellCount' => $verticalMergeCellCount,
            'docxTableVerticalMergeRestartCount' => $verticalMergeRestartCount,
            'docxTableVerticalMergeContinueCount' => $verticalMergeContinueCount,
            'docxTableMaxGridColumnCount' => $maxGridColumnCount,
        ], $sections);
    }

    private function tableRowGridOmission(?\DOMElement $rowProperties, string $localName): int
    {
        $element = $this->childElement($rowProperties, $localName);
        if (!$element instanceof \DOMElement) {
            return 0;
        }

        return max(0, $this->wordOptionalIntAttr($element, 'val') ?? 0);
    }

    private function tableRowIsHeader(?\DOMElement $rowProperties): bool
    {
        $header = $this->childElement($rowProperties, 'tblHeader');

        return $header instanceof \DOMElement && $this->wordBoolean($header);
    }

    private function tableCellGridSpan(?\DOMElement $cellProperties): int
    {
        $gridSpan = $this->childElement($cellProperties, 'gridSpan');
        if (!$gridSpan instanceof \DOMElement) {
            return 1;
        }

        return max(1, $this->wordOptionalIntAttr($gridSpan, 'val') ?? 1);
    }

    private function tableCellVerticalMerge(?\DOMElement $cellProperties): ?string
    {
        $verticalMerge = $this->childElement($cellProperties, 'vMerge');
        if (!$verticalMerge instanceof \DOMElement) {
            return null;
        }

        $value = trim($verticalMerge->getAttributeNS(self::NS_W, 'val'));
        if ($value === '') {
            return 'continue';
        }

        return strtolower($value) === 'restart' ? 'restart' : 'continue';
    }

    private function listStyleForFormat(string $format): string
    {
        return match ($format) {
            'lowerLetter' => 'lower_alpha',
            'upperLetter' => 'upper_alpha',
            'lowerRoman' => 'lower_roman',
            'upperRoman' => 'upper_roman',
            default => 'decimal',
        };
    }

    private function listDelimiterForText(string $text): string
    {
        $trimmed = trim($text);
        if (str_starts_with($trimmed, '(') && str_ends_with($trimmed, ')')) {
            return 'two_parens';
        }
        if (str_ends_with($trimmed, ')')) {
            return 'one_paren';
        }

        return 'period';
    }

    /**
     * @param list<AstNode> $nodes
     * @return list<AstNode>
     */
    private function mergeAdjacentText(array $nodes): array
    {
        $merged = [];
        foreach ($nodes as $node) {
            if ($node->type === 'text' && $merged !== [] && end($merged)->type === 'text') {
                $previous = array_pop($merged);
                $merged[] = new AstNode('text', ['text' => (string) $previous->attr('text', '') . (string) $node->attr('text', '')]);
                continue;
            }
            $merged[] = $node;
        }

        return $merged;
    }

    /**
     * @param list<AstNode> $nodes
     */
    private function appendText(array &$nodes, string $text): void
    {
        if ($text === '') {
            return;
        }

        if ($nodes !== [] && end($nodes)->type === 'text') {
            $previous = array_pop($nodes);
            $nodes[] = new AstNode('text', ['text' => (string) $previous->attr('text', '') . $text]);
            return;
        }

        $nodes[] = new AstNode('text', ['text' => $text]);
    }

    private function emptyStringToNull(string $value): ?string
    {
        $value = trim($value);

        return $value === '' ? null : $value;
    }

    /**
     * @param list<AstNode> $nodes
     */
    private function plainInlineText(array $nodes): string
    {
        $text = '';
        foreach ($nodes as $node) {
            $text .= match ($node->type) {
                'text', 'code' => (string) $node->attr('text', ''),
                'softbreak', 'linebreak' => ' ',
                'image' => (string) $node->attr('alt', ''),
                'note' => '',
                default => $this->plainInlineText($node->children),
            };
        }

        return trim(preg_replace('/\s+/u', ' ', $text) ?? $text);
    }

    /**
     * @param list<AstNode> $blocks
     */
    private function plainBlockText(array $blocks): string
    {
        $parts = [];
        foreach ($blocks as $block) {
            $parts[] = $block->attr('text', $this->plainInlineText($block->children));
        }

        return trim(implode(' ', array_map(static fn (mixed $part): string => (string) $part, $parts)));
    }

    private function identifierFromText(string $text): string
    {
        $id = strtolower(trim(preg_replace('/[^\pL\pN]+/u', '-', $text) ?? $text, '-'));

        return $id === '' ? 'section' : $id;
    }

    /**
     * @param array{defaults:array<string, string>, overrides:array<string, string>} $contentTypes
     */
    private function contentTypeFor(string $partName, array $contentTypes): string
    {
        $partName = $this->normalizePartName($partName);
        if (isset($contentTypes['overrides'][$partName])) {
            return $contentTypes['overrides'][$partName];
        }

        $extension = strtolower(pathinfo($partName, PATHINFO_EXTENSION));
        return $contentTypes['defaults'][$extension] ?? '';
    }

    private function relationshipsPartFor(string $partName): string
    {
        $partName = $this->normalizePartName($partName);
        $directory = dirname($partName);
        $baseName = basename($partName);

        return ($directory === '.' ? '' : $directory . '/') . '_rels/' . $baseName . '.rels';
    }

    private function documentSiblingPart(string $documentPart, string $fileName): string
    {
        $directory = dirname($this->normalizePartName($documentPart));

        return ($directory === '.' || $directory === '' ? '' : $directory . '/') . $fileName;
    }

    private function resolveRelationshipTarget(string $relsPartName, string $target, string $targetMode): string
    {
        if ($targetMode === 'External' || preg_match('/^[A-Za-z][A-Za-z0-9+.-]*:/', $target) === 1) {
            return $target;
        }

        $sourcePart = $this->sourcePartForRelationshipsPart($relsPartName);
        try {
            return $this->normalizePartName(OpcPackagePath::resolveInternalTarget(
                $sourcePart === '' ? '/' : '/' . $sourcePart,
                $target,
            ));
        } catch (\InvalidArgumentException) {
            return $this->resolveRelationshipTargetTolerantly($sourcePart, $target);
        }
    }

    private function resolveRelationshipTargetTolerantly(string $sourcePart, string $target): string
    {
        if (str_starts_with($target, '/')) {
            return $this->normalizePartName($target);
        }

        $base = $sourcePart === '' ? '' : dirname($sourcePart);
        $path = ($base === '' || $base === '.' ? '' : $base . '/') . $target;

        return $this->normalizePartName($path);
    }

    private function sourcePartForRelationshipsPart(string $relsPartName): string
    {
        if ($relsPartName === '_rels/.rels') {
            return '';
        }

        if (preg_match('~^_rels/([^/]+)\.rels$~', $relsPartName, $match) === 1) {
            return $match[1];
        }

        if (preg_match('~^(.*)/_rels/([^/]+)\.rels$~', $relsPartName, $match) === 1) {
            return ($match[1] === '' ? '' : $match[1] . '/') . $match[2];
        }

        return '';
    }

    private function normalizePartName(string $partName): string
    {
        $partName = str_replace('\\', '/', $partName);
        $partName = ltrim($partName, '/');
        $segments = [];
        foreach (explode('/', $partName) as $segment) {
            if ($segment === '' || $segment === '.') {
                continue;
            }
            if ($segment === '..') {
                array_pop($segments);
                continue;
            }
            $segments[] = $segment;
        }

        return implode('/', $segments);
    }

    private function stripQueryAndFragment(string $partName): string
    {
        $partName = preg_replace('/[#?].*$/', '', $partName) ?? $partName;

        return $this->normalizePartName($partName);
    }

    private function loadXml(string $xml, string $partName): \DOMDocument
    {
        $dom = new \DOMDocument();
        $previous = libxml_use_internal_errors(true);
        $ok = $dom->loadXML($xml, LIBXML_NONET | LIBXML_NOERROR | LIBXML_NOWARNING);
        if (!$ok) {
            $errors = libxml_get_errors();
            libxml_clear_errors();
            libxml_use_internal_errors($previous);
            $message = $errors === [] ? 'unknown XML parse error' : trim($errors[0]->message);
            throw new \RuntimeException("Invalid DOCX XML part {$partName}: {$message}");
        }
        libxml_clear_errors();
        libxml_use_internal_errors($previous);

        return $dom;
    }

    private function xpath(\DOMDocument $dom): \DOMXPath
    {
        $xpath = new \DOMXPath($dom);
        $xpath->registerNamespace('ct', self::NS_CT);
        $xpath->registerNamespace('rel', self::NS_REL);
        $xpath->registerNamespace('w', self::NS_W);
        $xpath->registerNamespace('w16cid', self::NS_W16CID);
        $xpath->registerNamespace('r', self::NS_R);
        $xpath->registerNamespace('dc', self::NS_DC);
        $xpath->registerNamespace('cp', self::NS_CP);
        $xpath->registerNamespace('dcterms', self::NS_DCTERMS);
        $xpath->registerNamespace('ep', self::NS_EP);
        $xpath->registerNamespace('cust', self::NS_CUSTOM_PROPS);
        $xpath->registerNamespace('vt', self::NS_VT);
        $xpath->registerNamespace('a', self::NS_A);
        $xpath->registerNamespace('wp', self::NS_WP);
        $xpath->registerNamespace('c', self::NS_C);
        $xpath->registerNamespace('b', self::NS_BIB);
        $xpath->registerNamespace('m', self::NS_M);
        $xpath->registerNamespace('v', self::NS_V);
        $xpath->registerNamespace('dgm', self::NS_DGM);
        $xpath->registerNamespace('o', self::NS_O);
        $xpath->registerNamespace('ds', self::NS_DS);

        return $xpath;
    }

    /**
     * @return list<\DOMElement>
     */
    private function elements(\DOMXPath $xpath, string $query, ?\DOMNode $context = null): array
    {
        $nodes = $context instanceof \DOMNode ? $xpath->query($query, $context) : $xpath->query($query);
        if (!$nodes instanceof \DOMNodeList) {
            return [];
        }

        $elements = [];
        foreach ($nodes as $node) {
            if ($node instanceof \DOMElement) {
                $elements[] = $node;
            }
        }

        return $elements;
    }

    private function firstElement(\DOMXPath $xpath, string $query, \DOMNode $context): ?\DOMElement
    {
        $elements = $this->elements($xpath, $query, $context);

        return $elements[0] ?? null;
    }

    /**
     * @param array<string, mixed> $summary
     * @param array<string, mixed> $people
     * @param list<string> $matchedAuthors
     * @param list<string> $unmatchedAuthors
     * @return array<string, mixed>
     */
    private function commentAuthorPeopleSummary(
        array $summary,
        array $people,
        int $matchedCount,
        int $unmatchedCount,
        array $matchedAuthors,
        array $unmatchedAuthors
    ): array {
        $summary['authorPeopleMatchedCount'] = $matchedCount;
        $summary['authorPeopleUnmatchedCount'] = $unmatchedCount;
        $summary['authorPeopleMatchedAuthors'] = $matchedAuthors;
        $summary['authorPeopleUnmatchedAuthors'] = $unmatchedAuthors;
        $summary['authorPeoplePart'] = is_string($people['partName'] ?? null) ? $people['partName'] : null;
        $summary['authorPeopleReviewPolicy'] = 'comment-author-people-metadata-only';

        return $summary;
    }

    /**
     * @param array<string, mixed> $people
     * @return array<string, mixed>
     */
    private function commentAuthorPeopleAttrs(string $author, array $people): array
    {
        $attrs = [
            'commentAuthorPeopleMatched' => false,
            'commentAuthorPresenceInfoCount' => 0,
            'commentAuthorPresenceInfo' => [],
            'commentAuthorProviderIds' => [],
            'commentAuthorUserIds' => [],
            'commentAuthorPeopleReviewPolicy' => 'comment-author-people-metadata-only',
        ];
        $byAuthor = is_array($people['byAuthor'] ?? null) ? $people['byAuthor'] : [];
        $person = $byAuthor[$author] ?? null;
        if (!is_array($person)) {
            return $attrs;
        }

        $presenceInfo = [];
        $providerIds = [];
        $userIds = [];
        foreach (($person['presenceInfo'] ?? []) as $presence) {
            if (!is_array($presence)) {
                continue;
            }

            $providerId = is_string($presence['providerId'] ?? null) ? $presence['providerId'] : null;
            $userId = is_string($presence['userId'] ?? null) ? $presence['userId'] : null;
            $presenceInfo[] = [
                'providerId' => $providerId,
                'userId' => $userId,
            ];
            $this->appendUniqueString($providerIds, $providerId);
            $this->appendUniqueString($userIds, $userId);
        }

        $attrs['commentAuthorPeopleMatched'] = true;
        $attrs['commentAuthorPeoplePart'] = is_string($people['partName'] ?? null) ? $people['partName'] : null;
        if (is_int($person['index'] ?? null)) {
            $attrs['commentAuthorPersonIndex'] = $person['index'];
        }
        $attrs['commentAuthorPresenceInfoCount'] = is_int($person['presenceInfoCount'] ?? null)
            ? $person['presenceInfoCount']
            : count($presenceInfo);
        $attrs['commentAuthorPresenceInfo'] = $presenceInfo;
        $attrs['commentAuthorProviderIds'] = $providerIds;
        $attrs['commentAuthorUserIds'] = $userIds;

        return $attrs;
    }

    /**
     * @param array<string, array{paraId:string, parentParaId:?string, resolved:?bool, partName:string}> $commentsExtended
     * @param array<string, array<string, mixed>> $commentsIds
     * @return array<string, mixed>
     */
    private function commentPackageAttrs(\DOMElement $comment, array $commentsExtended, array $commentsIds): array
    {
        $paraId = $this->commentParagraphId($comment);
        if ($paraId === null) {
            return [];
        }

        $attrs = [
            'commentParaId' => $paraId,
        ];
        $extended = $commentsExtended[$paraId] ?? null;
        if (is_array($extended)) {
            $attrs['commentsExtendedPart'] = $extended['partName'];
            if (is_string($extended['parentParaId']) && $extended['parentParaId'] !== '') {
                $attrs['commentParentParaId'] = $extended['parentParaId'];
            }
            if (is_bool($extended['resolved'])) {
                $attrs['commentResolved'] = $extended['resolved'];
            }
        }

        $commentId = $commentsIds[$paraId] ?? null;
        if (is_array($commentId)) {
            $attrs['commentsIdsPart'] = $commentId['partName'];
            if (is_string($commentId['durableId'] ?? null) && $commentId['durableId'] !== '') {
                $attrs['commentDurableId'] = $commentId['durableId'];
            }
            if (is_array($commentId['issues'] ?? null) && $commentId['issues'] !== []) {
                $attrs['commentIdIssues'] = $commentId['issues'];
            }
        }

        return $attrs;
    }

    private function commentParagraphId(\DOMElement $comment): ?string
    {
        foreach ($comment->childNodes as $child) {
            if (!$child instanceof \DOMElement || $child->namespaceURI !== self::NS_W || $child->localName !== 'p') {
                continue;
            }

            return $this->wordExtensionAttr($child, 'paraId');
        }

        return null;
    }

    private function wordExtensionAttr(\DOMElement $element, string $localName): ?string
    {
        foreach ([self::NS_W15, self::NS_W14] as $namespace) {
            $value = $element->getAttributeNS($namespace, $localName);
            if ($value !== '') {
                return $value;
            }
        }

        return null;
    }

    private function onOffStringValue(?string $value): ?bool
    {
        if ($value === null) {
            return null;
        }

        $value = strtolower(trim($value));
        if (in_array($value, ['1', 'true', 'on'], true)) {
            return true;
        }
        if (in_array($value, ['0', 'false', 'off'], true)) {
            return false;
        }

        return null;
    }

    private function childElement(?\DOMElement $parent, string $localName): ?\DOMElement
    {
        if (!$parent instanceof \DOMElement) {
            return null;
        }

        foreach ($parent->childNodes as $child) {
            if ($child instanceof \DOMElement && $child->namespaceURI === self::NS_W && $child->localName === $localName) {
                return $child;
            }
        }

        return null;
    }

    /**
     * @return list<\DOMElement>
     */
    private function childElementsByLocalName(?\DOMElement $parent, string $localName): array
    {
        if (!$parent instanceof \DOMElement) {
            return [];
        }

        $elements = [];
        foreach ($parent->childNodes as $child) {
            if ($child instanceof \DOMElement && $child->namespaceURI === self::NS_W && $child->localName === $localName) {
                $elements[] = $child;
            }
        }

        return $elements;
    }

    private function childAttr(\DOMElement $parent, string $childLocalName, string $attrLocalName): string
    {
        $child = $this->childElement($parent, $childLocalName);

        return $child instanceof \DOMElement ? $child->getAttributeNS(self::NS_W, $attrLocalName) : '';
    }

    private static function canonicalIdentityValue(mixed $value): mixed
    {
        if (!is_array($value)) {
            return $value;
        }

        if (array_is_list($value)) {
            return array_map(static fn (mixed $item): mixed => self::canonicalIdentityValue($item), $value);
        }

        $canonical = [];
        foreach ($value as $key => $item) {
            $canonical[(string) $key] = self::canonicalIdentityValue($item);
        }
        ksort($canonical, SORT_STRING);

        return $canonical;
    }

    private function wordBoolean(\DOMElement $element, string $attribute = 'val'): bool
    {
        $value = strtolower($element->getAttributeNS(self::NS_W, $attribute));

        return !in_array($value, ['0', 'false', 'off'], true);
    }

    private function wordOptionalIntAttr(\DOMElement $element, string $attribute): ?int
    {
        $value = trim($element->getAttributeNS(self::NS_W, $attribute));
        if ($value === '' || preg_match('/^-?\d+$/', $value) !== 1) {
            return null;
        }

        return (int) $value;
    }

    private function wordOptionalBooleanAttr(\DOMElement $element, string $attribute): ?bool
    {
        $value = $element->getAttributeNS(self::NS_W, $attribute);
        if ($value === '') {
            return null;
        }

        return $this->onOffStringValue($value);
    }

    /**
     * @param list<string> $names
     * @return array<string, string|int|bool>
     */
    private function wordAttributeMap(\DOMElement $element, array $names): array
    {
        $attributes = [];
        foreach ($names as $name) {
            $value = $element->getAttributeNS(self::NS_W, $name);
            if ($value !== '') {
                $attributes[$name] = $value;
            }
        }

        return $attributes;
    }
}
